bl-webapps/sellers/src/SellersPage/components/SellerDetailSidebar/components/SellerDetailsSection/SellerDetailsTab.tsx","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellerDetailSidebar/components/SellerDetailsSection/SellerDetailsSection.tsx","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellerDetailSidebar/components/MenuItems/SuspendSellerDialog.tsx","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellerDetailSidebar/components/MenuItems/SuspendSellerMenuItem.tsx","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellerDetailSidebar/components/MenuItems/EditSellerMenuItem.tsx","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellerDetailSidebar/components/SellerDetailsMenu.tsx","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellerDetailSidebar/getSellerDetails.hook.ts","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellerDetailSidebar/SellerDetailsSidebar.tsx","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellerDetailSidebar/ShowBuyerDetails.hook.ts","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellersTable/SellersStatusSelect.tsx","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellersTable/useColumns.tsx","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellersTable/usePagination.ts","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellersTable/useSearch.ts","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellersTable/SellersTable.hook.ts","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellersTable/SellersTable.tsx","../../../../libs/tbl-webapps/sellers/src/SellersPage/components/SellersPageNavigation.tsx","../../../../libs/tbl-webapps/sellers/src/SellersPage/SellersPage.tsx","../../src/routes/b2bPayments/RouterB2BPayments.tsx","../../../../libs/tbl-webapps/translations/src/lib/loadResources.ts","../../../../libs/tbl-webapps/translations/src/lib/initializeTranslations.ts","../../../../libs/tbl-webapps/developers/src/ApiKeys/components/GenerateApiKeyButton.tsx","../../../../libs/tbl-webapps/developers/src/ApiKeys/components/ReadOnlyField.tsx","../../../../libs/tbl-webapps/developers/src/ApiKeys/components/RevokeConfirmDialog.tsx","../../../../libs/tbl-webapps/developers/src/ApiKeys/components/ApiKeysTable.tsx","../../../../libs/tbl-webapps/developers/src/ApiKeys/components/ApiKeyRow.tsx","../../../../libs/tbl-webapps/developers/src/ApiKeys/components/BaseUrl.tsx","../../../../libs/tbl-webapps/developers/src/ApiKeys/components/KeysSafeBanner.tsx","../../../../libs/tbl-webapps/developers/src/ApiKeys/components/KeysSafeDialog.tsx","../../../../libs/tbl-webapps/developers/src/ApiKeys/ApiKeysPage.tsx","../../../../libs/tbl-webapps/developers/src/ApiKeys/CreateApiKeyPage.tsx","../../../../libs/tbl-webapps/developers/src/Webhooks/CreateWebhookPage/CreateWebhook.schema.ts","../../../../libs/tbl-webapps/developers/src/Webhooks/CreateWebhookPage/CreateWebhook.hook.ts","../../../../libs/tbl-webapps/developers/src/Webhooks/CreateWebhookPage/CreateWebhookPage.tsx","../../../../libs/tbl-webapps/developers/src/Webhooks/components/DeleteWebhookButton.tsx","../../../../libs/tbl-webapps/developers/src/Webhooks/components/WebhookStateSwitch.tsx","../../../../libs/tbl-webapps/developers/src/Webhooks/components/useColumns.tsx","../../../../libs/tbl-webapps/developers/src/Webhooks/components/WebhooksTable.tsx","../../../../libs/tbl-webapps/developers/src/Webhooks/WebhooksPage.tsx","../../../../libs/tbl-webapps/developers/src/DevelopersPage.tsx","../../../../libs/tbl-webapps/platform/src/InviteMember/useInviteMemberFormLabels.ts","../../../../libs/tbl-webapps/platform/src/InviteMember/InviteMember.errors.ts","../../../../libs/tbl-webapps/platform/src/InviteMember/InviteMember.schema.ts","../../../../libs/tbl-webapps/platform/src/InviteMember/InviteMember.hook.ts","../../../../libs/tbl-webapps/platform/src/InviteMember/InviteMemberButton.tsx","../../../../libs/tbl-webapps/platform/src/Members/components/MemberStatusTag.tsx","../../../../libs/tbl-webapps/platform/src/Members/components/RemoveMemberButton.tsx","../../../../libs/tbl-webapps/platform/src/Members/useColumns.tsx","../../../../libs/tbl-webapps/platform/src/Members/MembersTable.tsx","../../../../libs/tbl-webapps/platform/src/PlatformPage.tsx","../../../../libs/tbl-webapps/settings/src/components/CookieSettings.tsx","../../../../libs/tbl-webapps/settings/src/components/MfaSettings.tsx","../../../../libs/tbl-webapps/settings/src/components/PreviewFeatureSettings.tsx","../../../../libs/tbl-webapps/settings/src/SettingsPage.tsx","../../src/components/CapitalDistributorGuard.tsx","../../src/routes/ModulesRouter.tsx","../../src/App.tsx","../../src/index.tsx"],"sourcesContent":["import * as Sentry from '@sentry/react';\nimport { FunctionComponent, PropsWithChildren, useEffect } from 'react';\n\ninterface Props {\n  name: string;\n  value: string;\n}\n\nexport const SentryTagProvider: FunctionComponent<PropsWithChildren<Props>> = ({\n  children,\n  value,\n  name,\n}) => {\n  useEffect(() => {\n    Sentry.setTag(name, value);\n\n    return () => Sentry.setTag(name, undefined);\n  }, [value]);\n\n  return children;\n};\n","declare global {\n  interface Window {\n    _env_?: {\n      [env: string]: string;\n    };\n  }\n}\n\nconst ENV = window._env_?.['ENV'] ?? window._env_?.['APP_ENV'] ?? 'localhost';\n\ninterface Options {\n  required?: boolean;\n}\n\nexport function fromEnvironment(variable: string): string;\nexport function fromEnvironment(\n  variable: string,\n  options: { required: false },\n): string | undefined;\nexport function fromEnvironment(\n  variable: string,\n  options: Options = { required: true },\n): string | undefined {\n  const { required } = options;\n  const { _env_: environment } = window;\n\n  if (environment == null && !required) return undefined;\n\n  if (environment == null) {\n    if (ENV === 'localhost') alert(`Environment is not set`);\n\n    throw new Error('Environment is not set');\n  }\n\n  const result = environment[variable];\n  if ((result == null || result === '') && required) {\n    if (ENV === 'localhost')\n      alert(`Required variable '${variable}' is not set`);\n\n    throw new Error(`Required variable '${variable}' is not set`);\n  }\n\n  return result;\n}\n\ntype Environment = 'localhost' | 'test' | 'staging' | 'live';\n\nfunction defineEnvironment(): Environment {\n  if (ENV === 'live') return 'live';\n\n  if (ENV === 'staging') return 'staging';\n\n  if (ENV === 'test') return 'test';\n\n  return 'localhost';\n}\n\nexport const ENVIRONMENT = defineEnvironment();\n\n/**\n * Returns whether the app is running in debug mode. By default this is\n * true for localhost, staging and test environments. Does not include\n * sandbox mode for live.\n */\nexport const DEBUG_MODE =\n  ENVIRONMENT === 'localhost' ||\n  ENVIRONMENT === 'staging' ||\n  ENVIRONMENT === 'test';\n","import { ENVIRONMENT as ENV, fromEnvironment } from '@finmid/environment';\n\nexport const SENTRY_DSN = fromEnvironment('SENTRY_DSN', { required: false });\nexport const SENTRY_TRACE_RATE = (() => {\n  const envTrace = Number(fromEnvironment('SENTRY_RATE', { required: false }));\n\n  return Number.isNaN(envTrace) ? 1 : envTrace;\n})();\n\nexport const RELEASE =\n  ENV === 'localhost' ? 'DEVELOPMENT' : import.meta.env.VITE_SENTRY_RELEASE;\n\nconst testNavigator = navigator.userAgent.includes('Playwright');\nexport const ENVIRONMENT = testNavigator ? 'test' : ENV;\n\nexport const UNKNOWN_TRANSACTION = 'unknown transaction';\nexport const UNKNOWN_TICKET = '0000';\n","const REDACTED = '[Filtered]';\n\n// Matches a JWT: three base64url segments separated by dots. The header\n// segment always starts with `eyJ` (base64 of `{\"`). The signature segment\n// may be empty for unsigned tokens.\nconst JWT_REGEX = /eyJ[A-Za-z0-9_=-]+\\.[A-Za-z0-9_=-]+\\.[A-Za-z0-9_=-]*/g;\n\n// Query-string parameters whose values must never reach a third party, even\n// when the value is not JWT-shaped (e.g. OAuth authorization codes).\nconst SENSITIVE_QUERY_KEYS = [\n  'token',\n  'access_token',\n  'id_token',\n  'id_token_hint',\n  'refresh_token',\n  'code',\n  'jwt',\n  'session_state',\n];\n\nconst SENSITIVE_QUERY_REGEX = new RegExp(\n  `([?&]|^)((?:${SENSITIVE_QUERY_KEYS.join('|')})=)[^&#\\\\s]*`,\n  'gi',\n);\n\nfunction scrubString(value: string): string {\n  return value\n    .replace(JWT_REGEX, REDACTED)\n    .replace(SENSITIVE_QUERY_REGEX, `$1$2${REDACTED}`);\n}\n\nfunction deepScrub(input: unknown, seen: Map<object, unknown>): unknown {\n  if (typeof input === 'string') {\n    return scrubString(input);\n  }\n\n  if (Array.isArray(input)) {\n    const cached = seen.get(input);\n    if (cached !== undefined) {\n      return cached;\n    }\n    const copy: unknown[] = [];\n    seen.set(input, copy);\n    input.forEach((item) => copy.push(deepScrub(item, seen)));\n    return copy;\n  }\n\n  if (input !== null && typeof input === 'object') {\n    const cached = seen.get(input);\n    if (cached !== undefined) {\n      return cached;\n    }\n    const record = input as Record<string, unknown>;\n    const copy: Record<string, unknown> = {};\n    // Register the copy before recursing so circular references resolve to\n    // this (scrubbed) copy rather than the original object.\n    seen.set(input, copy);\n    for (const key of Object.keys(record)) {\n      copy[key] = deepScrub(record[key], seen);\n    }\n    return copy;\n  }\n\n  return input;\n}\n\n/**\n * Recursively redacts JWTs and sensitive query-string parameters from any\n * string field of a Sentry payload (event, transaction, or breadcrumb) so\n * tokens embedded in URLs, messages, or breadcrumbs never leak to Sentry.\n *\n * Returns a deep-scrubbed copy; the input payload is not mutated, so payloads\n * with readonly (frozen) fields are handled safely. Circular references are\n * preserved in the returned copy.\n */\nexport function scrubSensitiveData<T>(payload: T): T {\n  return deepScrub(payload, new Map()) as T;\n}\n","import * as Sentry from '@sentry/react';\nimport { useEffect } from 'react';\nimport {\n  createRoutesFromChildren,\n  matchRoutes,\n  useLocation,\n  useNavigationType,\n} from 'react-router-dom';\n\nimport {\n  ENVIRONMENT,\n  RELEASE,\n  SENTRY_DSN,\n  SENTRY_TRACE_RATE,\n} from './constants';\nimport { scrubSensitiveData } from './scrubSensitiveData';\n\nconst defaultOptions: Sentry.BrowserOptions = {\n  dsn: SENTRY_DSN,\n  integrations: [\n    Sentry.reactRouterV6BrowserTracingIntegration({\n      useEffect,\n      useLocation,\n      useNavigationType,\n      createRoutesFromChildren,\n      matchRoutes,\n    }),\n  ],\n  environment: ENVIRONMENT,\n  release: RELEASE,\n  tracesSampleRate: SENTRY_TRACE_RATE,\n};\n\nfunction isThenable<T>(value: unknown): value is PromiseLike<T> {\n  return (\n    value != null && typeof (value as { then?: unknown }).then === 'function'\n  );\n}\n\n/**\n * Wraps an app-provided event/transaction callback so that\n * {@link scrubSensitiveData} always runs last, on whatever payload the app\n * callback lets through. The app callback keeps its right to drop the payload\n * by returning `null`, and may be asynchronous.\n */\nfunction withScrubbing<Payload, Hint>(\n  callback:\n    | ((\n        payload: Payload,\n        hint: Hint,\n      ) => Payload | null | PromiseLike<Payload | null>)\n    | undefined,\n) {\n  return (payload: Payload, hint: Hint) => {\n    const result = callback ? callback(payload, hint) : payload;\n\n    if (isThenable<Payload | null>(result)) {\n      return result.then((resolved) =>\n        resolved == null ? resolved : scrubSensitiveData(resolved),\n      );\n    }\n\n    return result == null ? result : scrubSensitiveData(result);\n  };\n}\n\n/**\n * Synchronous variant of {@link withScrubbing} for `beforeBreadcrumb`, which\n * Sentry does not allow to return a promise.\n */\nfunction withScrubbingSync<Payload, Hint>(\n  callback: ((payload: Payload, hint?: Hint) => Payload | null) | undefined,\n) {\n  return (payload: Payload, hint?: Hint) => {\n    const result = callback ? callback(payload, hint) : payload;\n    return result == null ? result : scrubSensitiveData(result);\n  };\n}\n\nexport function initializeSentry(options: Sentry.BrowserOptions = {}) {\n  // Local dev servers often run with a staging env.js, so ENVIRONMENT alone\n  // would report HMR errors as staging.\n  if (\n    !import.meta.env.DEV &&\n    ENVIRONMENT !== 'localhost' &&\n    ENVIRONMENT !== 'test'\n  ) {\n    const merged = { ...defaultOptions, ...options };\n\n    Sentry.init({\n      ...merged,\n      beforeSend: withScrubbing(merged.beforeSend),\n      beforeSendTransaction: withScrubbing(merged.beforeSendTransaction),\n      beforeBreadcrumb: withScrubbingSync(merged.beforeBreadcrumb),\n    });\n  }\n}\n","import * as Sentry from '@sentry/react';\n\nimport { ENVIRONMENT, UNKNOWN_TICKET, UNKNOWN_TRANSACTION } from './constants';\n\ntype LoggerInfo = {\n  customContext?: Record<string, unknown>;\n  transactionName?: string;\n  ticket?: string;\n  fingerprint?: string[];\n};\n\ntype ErrorData = LoggerInfo & {\n  error: Error;\n};\n\ntype WarningData = LoggerInfo & {\n  message: string;\n};\n\nconst logToSentry = ENVIRONMENT !== 'localhost';\n\nconst applyLoggerInfo = (\n  scope: Sentry.Scope,\n  { transactionName, customContext = {}, ticket, fingerprint }: LoggerInfo,\n) => {\n  scope.setTransactionName(transactionName || UNKNOWN_TRANSACTION);\n  scope.setTag('ticket', ticket ?? UNKNOWN_TICKET);\n\n  if (fingerprint) {\n    scope.setFingerprint(fingerprint);\n  }\n\n  for (const key in customContext) {\n    scope.setExtra(key, customContext[key]);\n  }\n\n  return scope;\n};\n\nexport const logError = (errorData: ErrorData): void => {\n  const { error, ...loggerInfo } = errorData;\n  if (logToSentry) {\n    Sentry.captureException(error, (scope) => {\n      scope.setLevel('error');\n      return applyLoggerInfo(scope, loggerInfo);\n    });\n  } else {\n    console.error(error);\n  }\n};\n\nexport const logWarning = (warningData: WarningData): void => {\n  const { message, ...loggerInfo } = warningData;\n  if (logToSentry) {\n    Sentry.captureMessage(message, (scope) => {\n      scope.setLevel('warning');\n      return applyLoggerInfo(scope, loggerInfo);\n    });\n  } else {\n    console.warn(message);\n    console.dir(loggerInfo.customContext);\n  }\n};\n","import { ENVIRONMENT } from '@finmid/environment';\n\nexport const DEBUG_MODE = ENVIRONMENT !== 'live';\n\n/**\n * Custom override of console.log. Will be set to `console.log` if `DEBUG_MODE`\n * is `true`, otherwise it will be assigned a no op function. `DEBUG_MODE` is\n * currently being set inside `src/constants/constants.ts`, and will be `true`\n * on **every environment except live**.\n */\nexport const debugLog = DEBUG_MODE\n  ? window.console.log.bind(window.console)\n  : () => {\n      // noop\n    };\n","import type Keycloak from 'keycloak-js';\nimport { createContext } from 'react';\n\ntype KeycloakContextValue = {\n  keycloak?: Keycloak;\n};\n\n// eslint-disable-next-line @typescript-eslint/no-non-null-assertion\nexport const KeycloakContext = createContext<KeycloakContextValue>(null!);\n","import type Keycloak from 'keycloak-js';\nimport type { KeycloakInitOptions } from 'keycloak-js';\nimport { PropsWithChildren, useCallback, useEffect, useState } from 'react';\n\nimport { KeycloakContext } from './KeycloakContext';\nimport {\n  KeycloakError,\n  KeycloakErrorHandler,\n  KeycloakEvent,\n  Tokens,\n} from './types';\n\ntype Props = PropsWithChildren<{\n  keycloak: Keycloak;\n  initOptions: KeycloakInitOptions;\n  LoadingElement: React.ReactElement;\n  onDomainError?: KeycloakErrorHandler;\n  onJsError?: (error: unknown) => void;\n  onEvent?: (event: unknown, error?: unknown) => void;\n  onTokens?: (tokens: Tokens) => void;\n}>;\n\nexport const KeycloakProvider = ({\n  children,\n  keycloak,\n  initOptions,\n  LoadingElement,\n  onDomainError,\n  onJsError,\n  onEvent,\n  onTokens,\n}: Props) => {\n  const [initialized, setInitialized] = useState(false);\n\n  const onTokenExpired = useCallback(\n    (event: KeycloakEvent) => {\n      onEvent?.(event);\n      keycloak.updateToken(5);\n    },\n    [keycloak, onEvent],\n  );\n\n  const updateState = useCallback(\n    (event: KeycloakEvent) => {\n      onEvent?.(event);\n      setInitialized(true);\n\n      const { idToken, refreshToken, token } = keycloak;\n      onTokens?.({ idToken, refreshToken, token });\n    },\n    [keycloak, onEvent, onTokens],\n  );\n\n  const onDomainErrorEvent = useCallback(\n    (event: KeycloakEvent) => (error?: KeycloakError) => {\n      onEvent?.(event, error);\n      const { authenticated, clientId, idToken, refreshToken, token, realm } =\n        keycloak;\n      onDomainError?.({\n        error,\n        metadata: {\n          authenticated,\n          clientId,\n          idToken,\n          refreshToken,\n          token,\n          realm,\n        },\n      });\n    },\n    [keycloak, onEvent, onDomainError],\n  );\n\n  useEffect(() => {\n    if ('didInitialize' in keycloak && keycloak.didInitialize) {\n      return;\n    }\n\n    keycloak.onReady = () => {\n      updateState('onReady');\n    };\n    keycloak.onAuthSuccess = () => {\n      updateState('onAuthSuccess');\n    };\n    keycloak.onAuthError = (error) => {\n      onDomainErrorEvent('onAuthError')(error);\n    };\n    keycloak.onAuthRefreshSuccess = () => {\n      updateState('onAuthRefreshSuccess');\n    };\n    keycloak.onAuthRefreshError = () => {\n      onDomainErrorEvent('onAuthRefreshError')();\n    };\n    keycloak.onAuthLogout = () => {\n      updateState('onAuthLogout');\n    };\n    keycloak.onTokenExpired = () => {\n      onTokenExpired('onTokenExpired');\n    };\n    try {\n      void keycloak\n        .init(initOptions)\n        .catch((error) => onDomainErrorEvent('onInitError')(error));\n    } catch (error) {\n      onJsError?.(error);\n    }\n  }, [\n    keycloak,\n    initOptions,\n    onDomainErrorEvent,\n    onTokenExpired,\n    updateState,\n    onJsError,\n  ]);\n\n  if (!initialized) {\n    return LoadingElement;\n  }\n\n  return (\n    <KeycloakContext.Provider value={{ keycloak }}>\n      {children}\n    </KeycloakContext.Provider>\n  );\n};\n","import { useContext } from 'react';\n\nimport { KeycloakContext } from './KeycloakContext';\n\nexport const useKeycloak = () => {\n  const context = useContext(KeycloakContext);\n\n  if (context == null) {\n    throw new Error(\n      'useKeycloak hook must be used inside KeycloakContext.Provider',\n    );\n  }\n\n  const { keycloak } = context;\n\n  if (!keycloak) {\n    throw new Error('keycloak has not been assigned to Keycloak provider');\n  }\n\n  return {\n    keycloak,\n  };\n};\n","export default {}","import { ENVIRONMENT } from '@finmid/environment';\nimport { debugLog } from '@finmid/logging';\nimport Keycloak from 'keycloak-js';\nimport type { KeycloakInitOptions } from 'keycloak-js';\n\nconst keys = {\n  Token: {\n    key: 'token',\n    type: 'auth',\n  },\n  RefreshToken: {\n    key: 'refresh_token',\n    type: 'auth',\n  },\n};\n\n// Setup Keycloak instance as needed\n// Pass initialization options as required or leave blank to load from 'keycloak.json'\nconst createKeycloakInstance = (\n  authDomain: string,\n  clientId: string,\n  realm: string,\n) => {\n  debugLog('[KEYCLOAK]', 'createKeycloakInstance()');\n\n  function normalizeUrl(url: string) {\n    const withProtocol =\n      url.startsWith('http://') || url.startsWith('https://')\n        ? url\n        : `https://${url}/auth`;\n    const withEndingSlash = withProtocol.endsWith('/')\n      ? withProtocol\n      : `${withProtocol}/`;\n    return withEndingSlash;\n  }\n\n  return new Keycloak({ url: normalizeUrl(authDomain), realm, clientId });\n};\n\nconst enableLogging: boolean =\n  ENVIRONMENT === 'localhost' || ENVIRONMENT === 'test';\n\nexport const getKeycloakInitOptions = (redirectUri: string) => {\n  const token = localStorage.getItem(keys.Token.key);\n  const refreshToken = localStorage.getItem(keys.RefreshToken.key);\n\n  const options: KeycloakInitOptions = {\n    onLoad: 'check-sso',\n    enableLogging,\n    redirectUri,\n    pkceMethod: 'S256',\n  };\n\n  if (token) {\n    options.token = token;\n    options.checkLoginIframe = false;\n    debugLog('[KEYCLOAK]', 'getKeycloakInitOptions: initializing with token');\n  }\n\n  if (refreshToken) {\n    options.refreshToken = refreshToken;\n    options.checkLoginIframe = false;\n    debugLog(\n      '[KEYCLOAK]',\n      'getKeycloakInitOptions: initializing with refresh token',\n    );\n  }\n\n  if (!token && !refreshToken) {\n    debugLog(\n      '[KEYCLOAK]',\n      'getKeycloakInitOptions: initializing without token',\n    );\n  }\n\n  return options;\n};\n\nexport let globalKeycloakInstance: Keycloak | null = null;\n\n/**\n * This function creates and sets up a global keycloak instance. This keycloak\n * instance needs to be global so that we can access it outside of the React\n * component tree (i.e. in Axios and RTK Query).\n */\nexport function setupGlobalKeycloak(\n  url: string,\n  clientId: string,\n  realm: string,\n) {\n  debugLog('[KEYCLOAK]', 'setupGlobalKeycloak()');\n  if (!globalKeycloakInstance) {\n    debugLog(\n      '[KEYCLOAK]',\n      'setupGlobalKeycloak: global keycloak instance not found, creating',\n    );\n    globalKeycloakInstance = createKeycloakInstance(url, clientId, realm);\n  }\n  return globalKeycloakInstance;\n}\n","export const TOKEN_KEY = 'token';\nexport const REFRESH_TOKEN_KEY = 'refresh_token';\nexport const LOGIN_REDIRECT_KEY = 'login_redirect';\n","import { debugLog } from '@finmid/logging';\n\nimport { LOGIN_REDIRECT_KEY } from './localStorage';\n\nexport const saveRedirect = (redirectTo: string) => {\n  debugLog(`saveRedirect: saving redirect [${redirectTo}]`);\n  localStorage.setItem(LOGIN_REDIRECT_KEY, redirectTo);\n};\n","import { TOKEN_KEY, REFRESH_TOKEN_KEY } from './localStorage';\n\ninterface Options {\n  onSaveToken: (token: string) => void;\n}\n\nexport const useSaveTokens = ({ onSaveToken }: Options) => {\n  const saveToken = (token: string) => {\n    localStorage.removeItem(TOKEN_KEY);\n    localStorage.setItem(TOKEN_KEY, token);\n    onSaveToken(token);\n  };\n\n  const saveRefreshToken = (refreshToken: string) => {\n    localStorage.removeItem(REFRESH_TOKEN_KEY);\n    localStorage.setItem(REFRESH_TOKEN_KEY, refreshToken);\n  };\n\n  return {\n    saveToken,\n    saveRefreshToken,\n  };\n};\n","import { debugLog } from '@finmid/logging';\nimport * as Sentry from '@sentry/react';\nimport type Keycloak from 'keycloak-js';\nimport {\n  PropsWithChildren,\n  useCallback,\n  useEffect,\n  useMemo,\n  useState,\n} from 'react';\n\nimport {\n  KeycloakErrorHandler,\n  KeycloakProvider,\n  Tokens,\n} from './KeycloakProvider';\nimport { getKeycloakInitOptions, setupGlobalKeycloak } from './keycloak';\nimport { saveRedirect } from './saveRedirect';\nimport { useSaveTokens } from './useSaveTokens';\n\ntype Props = PropsWithChildren<{\n  url: string;\n  clientId: string;\n  realm: string;\n  /**\n   * Must be constant and not depend on any state.\n   */\n  redirectUri: string;\n  onSaveToken: (token: string) => void;\n  loadingElement: React.ReactElement;\n}>;\n\nexport const AuthenticationProvider = ({\n  url,\n  children,\n  clientId,\n  realm,\n  redirectUri,\n  onSaveToken,\n  loadingElement,\n}: Props) => {\n  const { saveToken } = useSaveTokens({ onSaveToken });\n  const location = [window.location.origin, window.location.pathname].join('');\n  const [keycloakInstance, setKeycloakInstance] = useState<Keycloak | null>(\n    null,\n  );\n\n  const keycloakInitOptions = useMemo(\n    () => getKeycloakInitOptions(redirectUri),\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [],\n  );\n\n  useEffect(() => {\n    debugLog('[KEYCLOAK]', 'AuthenticationProvider: location ' + location);\n    debugLog(\n      '[KEYCLOAK]',\n      'AuthenticationProvider: redirectUri ' + keycloakInitOptions.redirectUri,\n    );\n\n    if (location !== keycloakInitOptions.redirectUri) {\n      saveRedirect(window.location.pathname);\n    }\n\n    if (url && clientId && realm) {\n      setKeycloakInstance(setupGlobalKeycloak(url, clientId, realm));\n    }\n\n    return () => {\n      console.warn('[KEYCLOAK]', 'AuthenticationProvider unmounted');\n    };\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  debugLog('[KEYCLOAK]', 'AuthenticationProvider: rendering provider');\n\n  const tokenHandler = useCallback(\n    (tokens: Tokens) => {\n      const { token } = tokens;\n\n      debugLog(\n        '[KEYCLOAK]',\n        'AuthenticationProvider: onKeycloakTokens',\n        tokens,\n      );\n\n      if (token) {\n        saveToken(token);\n      }\n    },\n    [saveToken],\n  );\n\n  const eventHandler = useCallback((event: unknown, error: unknown) => {\n    debugLog('[KEYCLOAK]', 'onKeycloakEvent', event, error);\n  }, []);\n\n  const onDomainErrorHandler = useCallback<KeycloakErrorHandler>(\n    ({ error, metadata }) => {\n      if (error != null)\n        Sentry.captureException(error, (scope) =>\n          scope.setExtras({ ...metadata }),\n        );\n    },\n    [],\n  );\n\n  const onJsErrorHandler = useCallback((error: unknown) => {\n    Sentry.captureException(error ?? 'Keyclaok threw null. Madlads!');\n  }, []);\n\n  return keycloakInstance ? (\n    <KeycloakProvider\n      keycloak={keycloakInstance}\n      initOptions={keycloakInitOptions}\n      onDomainError={onDomainErrorHandler}\n      onJsError={onJsErrorHandler}\n      onEvent={eventHandler}\n      onTokens={tokenHandler}\n      LoadingElement={loadingElement}\n    >\n      {children}\n    </KeycloakProvider>\n  ) : (\n    loadingElement\n  );\n};\n","import type { ErrorEvent } from '@sentry/types';\n\n/*\ncheck for status_code values\n- 400: can not update expired token)\n- 0: HTTP request fails because of a network error (https://stackoverflow.com/questions/872206/what-does-it-mean-when-an-http-request-returns-status-code-0)\n*/\n\nexport const isTokenRefreshPromiseUndhandledRejection = (event: ErrorEvent) => {\n  if (\n    event.exception?.values?.[0].value ===\n    'Non-Error promise rejection captured with value: true'\n  ) {\n    const refreshTokenException = event.breadcrumbs?.findIndex((breadcrumb) => {\n      return (\n        breadcrumb.category === 'xhr' &&\n        breadcrumb?.data?.['method'] === 'POST' &&\n        breadcrumb?.data?.['url']?.endsWith('openid-connect/token') &&\n        [400, 0].includes(breadcrumb?.data?.['status_code'])\n      );\n    });\n    if (refreshTokenException && refreshTokenException > 0) {\n      return true;\n    }\n  }\n  return false;\n};\n","import { isTokenRefreshPromiseUndhandledRejection } from '@finmid/keycloak';\nimport type { BrowserOptions } from '@sentry/react';\n\nexport const options: BrowserOptions = {\n  normalizeDepth: 10,\n  ignoreErrors: ['ResizeObserver loop'],\n\n  // beforeBreadcrumb(breadcrumb, hint) {\n  beforeBreadcrumb(breadcrumb) {\n    const mutatedBreadcrumb = { ...breadcrumb };\n    // if (breadcrumb.category === 'console' && hint?.level === 'log') {\n    //   return null;\n    // }\n    return mutatedBreadcrumb;\n  },\n\n  beforeSend(event) {\n    if (isTokenRefreshPromiseUndhandledRejection(event)) {\n      return null;\n    }\n    return event;\n  },\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { createSlice } from '@reduxjs/toolkit';\n\nexport type DebugStoreState = {\n  featureFlagsDialogOpen: boolean;\n};\n\nconst initialState: DebugStoreState = {\n  featureFlagsDialogOpen: false,\n};\n\nconst debugSlice = createSlice({\n  name: 'debug',\n  initialState,\n  reducers: {\n    openFeatureFlagsDialog(state) {\n      if (ENVIRONMENT !== 'live') {\n        state.featureFlagsDialogOpen = true;\n      }\n    },\n\n    closeFeatureFlagsDialog(state) {\n      state.featureFlagsDialogOpen = false;\n    },\n  },\n});\n\nexport const { openFeatureFlagsDialog, closeFeatureFlagsDialog } =\n  debugSlice.actions;\n\nexport const debugReducer = debugSlice.reducer;\n","export const buyerStatus = [\n  'PENDING',\n  'PENDING_REACTIVATION',\n  'ACTIVE',\n  'INACTIVE',\n  'REJECTED',\n  'SUSPENDED',\n] as const;\n\nexport type BuyerStatus = (typeof buyerStatus)[number];\n","export const currencies = [\n  'EUR',\n  'USD',\n  'GBP',\n  'CAD',\n  'BRL',\n  'DKK',\n  'SEK',\n  'NOK',\n  'PLN',\n  'CZK',\n  'HUF',\n  'RON',\n] as const;\nexport const handledCurrencies = ['EUR', 'GBP', 'USD'] as const;\n\nexport type Currency = (typeof currencies)[number];\nexport type TBLCurrency = (typeof handledCurrencies)[number];\nexport type SupportedCurrencies = [TBLCurrency, ...TBLCurrency[]];\n\nexport function isTBLCurrency(key: Currency): key is TBLCurrency {\n  return key === 'EUR' || key === 'GBP' || key === 'USD';\n}\n\nexport type GetDistributorBalanceResponse = {\n  limit: number;\n  spent: number;\n};\n\nexport type GetDistributorCurrenciesResponse = {\n  defaultCurrency: TBLCurrency;\n  supportedCurrencies: SupportedCurrencies;\n};\n\nexport type GetDistributorAttributesResponse = {\n  actAsMOR: boolean;\n  recourseLimit: number;\n};\n","import { SerializedError } from '@reduxjs/toolkit';\nimport { FetchBaseQueryError } from '@reduxjs/toolkit/query';\n\n// https://redux-toolkit.js.org/rtk-query/usage-with-typescript\n// type FetchBaseQueryError => DefaultError | FetchError | ParsingError | TimeoutError | CustomError;\n\nexport function isPayloadAnRTKQueryError(\n  error: unknown,\n): error is FetchBaseQueryError | SerializedError {\n  return typeof error === 'object' && error !== null;\n}\n\nexport function isFetchBaseQueryError(\n  error: FetchBaseQueryError | SerializedError,\n): error is FetchBaseQueryError {\n  return 'status' in error;\n}\n\nexport function isSerializedError(\n  error: FetchBaseQueryError | SerializedError,\n): error is SerializedError {\n  return !('status' in error);\n}\n\n// --- DefaultError ---\n\nexport interface DefaultError {\n  status: number;\n  data: unknown;\n  ticketNumber?: string;\n}\n\nexport function isFetchBaseQueryDefaultError(\n  error: FetchBaseQueryError | SerializedError,\n): error is DefaultError {\n  return isFetchBaseQueryError(error) && typeof error.status === 'number';\n}\n\n// --- FetchError ---\n\ninterface FetchError {\n  status: 'FETCH_ERROR';\n  data: undefined;\n  error: string;\n}\n\nexport function isFetchError(\n  error: FetchBaseQueryError | SerializedError,\n): error is FetchError {\n  return isFetchBaseQueryError(error) && error.status === 'FETCH_ERROR';\n}\n\n// --- ParsingError ---\n\ninterface ParsingError {\n  status: 'PARSING_ERROR';\n  originalStatus: number;\n  data: string;\n  error: string;\n}\n\nexport function isParsingError(\n  error: FetchBaseQueryError | SerializedError,\n): error is ParsingError {\n  return isFetchBaseQueryError(error) && error.status === 'PARSING_ERROR';\n}\n\n// --- TimeoutError ---\n\ninterface TimeoutError {\n  status: 'TIMEOUT_ERROR';\n  data: undefined;\n  error: string;\n}\n\nexport function isTimeoutError(\n  error: FetchBaseQueryError | SerializedError,\n): error is TimeoutError {\n  return isFetchBaseQueryError(error) && error.status === 'TIMEOUT_ERROR';\n}\n\n// --- CustomError ---\n\ninterface CustomError {\n  status: 'CUSTOM_ERROR';\n  data?: unknown;\n  error: string;\n}\n\nexport function isCustomError(\n  error: FetchBaseQueryError | SerializedError,\n): error is CustomError {\n  return isFetchBaseQueryError(error) && error.status === 'CUSTOM_ERROR';\n}\n","import { SerializedError } from '@reduxjs/toolkit';\nimport { FetchBaseQueryError } from '@reduxjs/toolkit/query';\nimport { Request } from 'express';\n\nimport { DefaultError, isFetchBaseQueryDefaultError } from './baseRTKError';\n\nexport interface BE_ErrorData {\n  errorData: {\n    data: {\n      code: string;\n      description: string;\n    };\n    status: number;\n    statusText: string;\n  };\n  message: string;\n  requestContext: Partial<Request>;\n  success: false;\n}\n\nexport interface BE_Error extends DefaultError {\n  data: BE_ErrorData;\n}\n\nexport function dataIsBE_ErrorData(data: unknown): data is BE_ErrorData {\n  return (\n    typeof data === 'object' &&\n    data !== null &&\n    'errorData' in data &&\n    typeof data.errorData === 'object' &&\n    data.errorData !== null &&\n    'data' in data.errorData &&\n    typeof data.errorData.data === 'object' &&\n    data.errorData.data !== null &&\n    'code' in data.errorData.data &&\n    typeof data.errorData.data.code === 'string'\n  );\n}\n\nexport function isBE_Error(\n  error: FetchBaseQueryError | SerializedError,\n): error is BE_Error {\n  return (\n    isFetchBaseQueryDefaultError(error) &&\n    'data' in error &&\n    dataIsBE_ErrorData(error.data)\n  );\n}\n","export const zodValidationErrorCode = 'ZOD_VALIDATION_ERROR';\nexport const beValidationErrorCode = 'VALIDATION_ERROR';\nexport const validationErrorCodes = [\n  zodValidationErrorCode,\n  beValidationErrorCode,\n];\n\nexport const buyerConflictErrorCode = 'BUYER_CONFLICT';\nexport const sellerConflictErrorCode = 'SELLER_CONFLICT';\nexport const disposableEmailErrorCode = 'EMAIL_IS_DISPOSABLE';\n\nexport type ZodValidationErrorCode = typeof zodValidationErrorCode;\n","import { SerializedError } from '@reduxjs/toolkit';\nimport { FetchBaseQueryError } from '@reduxjs/toolkit/query';\n\nimport { isFetchBaseQueryError } from './baseRTKError';\n\ninterface NotFoundError {\n  status: 404;\n  data: unknown;\n  ticketNumber?: string;\n}\n\nexport function isNotFoundError(\n  error: FetchBaseQueryError | SerializedError,\n): error is NotFoundError {\n  return isFetchBaseQueryError(error) && error.status === 404;\n}\n","import { validationErrorCodes } from '../errorCodes';\n\nimport { BEValidationErrorData } from './beValidationError';\nimport { ZodValidationErrorData } from './zodValidationError';\n\ntype ValidationData = ZodValidationErrorData | BEValidationErrorData;\n\nexport function dataIsValidationData(data: unknown): data is ValidationData {\n  return (\n    typeof data === 'object' &&\n    data !== null &&\n    'errorData' in data &&\n    typeof data.errorData === 'object' &&\n    data.errorData !== null &&\n    'data' in data.errorData &&\n    typeof data.errorData.data === 'object' &&\n    data.errorData.data !== null &&\n    'code' in data.errorData.data &&\n    typeof data.errorData.data.code === 'string' &&\n    validationErrorCodes.includes(data.errorData.data.code)\n  );\n}\n","import { SerializedError } from '@reduxjs/toolkit';\nimport { FetchBaseQueryError } from '@reduxjs/toolkit/query';\nimport { Request } from 'express';\n\nimport { DefaultError, isFetchBaseQueryDefaultError } from '../baseRTKError';\nimport { beValidationErrorCode } from '../errorCodes';\n\nimport { dataIsValidationData } from './validationData';\n\nexport type BEValidationErrorData = {\n  errorData: {\n    data: {\n      code: typeof beValidationErrorCode;\n      description: string; // 'invalid input'\n    };\n    status: number;\n    statusText: string;\n  };\n  message: string;\n  requestContext: Partial<Request>;\n  success: false;\n};\n\nexport interface BEValidationError extends DefaultError {\n  data: BEValidationErrorData;\n}\n\nexport function dataIsBEValidationErrorData(\n  data: unknown,\n): data is BEValidationErrorData {\n  return (\n    dataIsValidationData(data) &&\n    data.errorData.data.code === beValidationErrorCode\n  );\n}\n\nexport function isBEValidationError(\n  error: FetchBaseQueryError | SerializedError,\n): error is BEValidationError {\n  return (\n    isFetchBaseQueryDefaultError(error) &&\n    'data' in error &&\n    dataIsBEValidationErrorData(error.data)\n  );\n}\n","import { SerializedError } from '@reduxjs/toolkit';\nimport { FetchBaseQueryError } from '@reduxjs/toolkit/query';\nimport { Request } from 'express';\n\nimport { DefaultError, isFetchBaseQueryDefaultError } from '../baseRTKError';\nimport { ZodValidationErrorCode, zodValidationErrorCode } from '../errorCodes';\n\nimport { dataIsValidationData } from './validationData';\n\nexport type ZodValidationErrorField = {\n  field: string;\n  message: string;\n};\n\nexport type ZodValidationErrorData = {\n  errorData: {\n    data: {\n      code: ZodValidationErrorCode;\n      description: string; // 'invalid input'\n      validationErrors: ZodValidationErrorField[];\n    };\n    status: 400;\n    statusText: string; // 'invalid input'\n  };\n  message: string;\n  requestContext: Partial<Request>;\n  success: false;\n};\n\nexport interface ZodValidationError extends DefaultError {\n  data: ZodValidationErrorData;\n}\n\nexport function dataIsZodErrorData(\n  data: unknown,\n): data is ZodValidationErrorData {\n  return (\n    dataIsValidationData(data) &&\n    data.errorData.data.code === zodValidationErrorCode\n  );\n}\n\nexport function isZodValidationError(\n  error: FetchBaseQueryError | SerializedError,\n): error is ZodValidationError {\n  return (\n    isFetchBaseQueryDefaultError(error) &&\n    'data' in error &&\n    dataIsZodErrorData(error.data)\n  );\n}\n","export enum PaymentRails {\n  SWIFT = 'SWIFT',\n  FPS = 'FPS',\n  SEPA = 'SEPA',\n}\n\nexport enum PaymentRailIds {\n  EUR_SWIFT = 'EUR_SWIFT',\n  EUR_SEPA = 'EUR_SEPA',\n  GBP_SWIFT = 'GBP_SWIFT',\n  GBP_SEPA = 'GBP_SEPA',\n  GBP_FPS = 'GBP_FPS',\n  USD_SWIFT = 'USD_SWIFT',\n}\n","export const paymentRequestStatuses = [\n  'PENDING',\n  'PROCESSING',\n  'PENDING_REPAYMENT',\n  'CANCELLED',\n  'CLOSED',\n  'DEFAULT',\n] as const;\n\nexport type PaymentRequestStatus = (typeof paymentRequestStatuses)[number];\n\n// payment request status shown in dashboard\nexport const DisplayedPaymentRequestStatusList = [\n  'PENDING',\n  'PROCESSING',\n  'PENDING_REPAYMENT',\n  'CANCELLED',\n  'CLOSED',\n] as const;\n\nexport type DisplayedPaymentRequestStatus =\n  (typeof DisplayedPaymentRequestStatusList)[number];\n","export const sellerStatus = [\n  'PENDING',\n  'ACTIVE',\n  'INACTIVE',\n  'REJECTED',\n  'SUSPENDED',\n] as const;\n\nexport type SellerStatus = (typeof sellerStatus)[number];\n","export function isObject(input: unknown): input is Record<string, unknown> {\n  return typeof input === 'object' && input !== null && !Array.isArray(input);\n}\n","export const generateTicketNumber = () => {\n  const characters =\n    '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz';\n  const length = 8;\n\n  let randomValue = '';\n  for (let i = 0; i < length; i++) {\n    const randomIndex = Math.floor(Math.random() * characters.length);\n    randomValue += characters[randomIndex];\n  }\n  return randomValue;\n};\n","import { isRejected } from '@reduxjs/toolkit';\n\nexport const getApiEndpointForRejectedAction = (\n  action: unknown,\n): [string, string, string] => {\n  if (!isRejected(action)) {\n    return ['<error>', '<unknown API>', '<non-rejected action>'];\n  }\n\n  const [api = '<unknown API>'] = action.type.split('/');\n\n  const queryArgs = action.meta.arg as Record<string, string | undefined>;\n\n  const endpoint = queryArgs['endpointName'] ?? '<unknown endpoint>';\n  const queryType = queryArgs['type'] ?? 'query';\n\n  return [queryType, api, endpoint];\n};\n","/* eslint-disable @typescript-eslint/no-explicit-any */\nexport const getGDPRPayload = ({\n  payload,\n  sensitiveInfo,\n  replacementValue,\n}: {\n  payload: any;\n  sensitiveInfo: string[];\n  replacementValue: string;\n}) => {\n  if (payload == null || typeof payload !== 'object') {\n    return payload;\n  }\n\n  const newPayload: Record<string, any> = {};\n\n  for (const key in payload) {\n    if (Array.isArray(payload[key])) {\n      newPayload[key] = payload[key].map((item: any) =>\n        getGDPRPayload({\n          payload: item,\n          sensitiveInfo,\n          replacementValue,\n        }),\n      );\n    } else if (typeof payload[key] === 'object' && payload[key] != null) {\n      newPayload[key] = getGDPRPayload({\n        payload: payload[key],\n        sensitiveInfo,\n        replacementValue,\n      });\n    } else {\n      newPayload[key] = sensitiveInfo.includes(key.toLowerCase())\n        ? replacementValue\n        : payload[key];\n    }\n  }\n\n  return newPayload;\n};\n","// keys to be scrubbed when sending to sentry - check is made against key.toLowerCase()\nexport const sensitiveInfo = ['email', 'phonenumber', 'phone'];\nexport const replacementValue = 'GDPR';\n","import {\n  isBE_Error,\n  isCustomError,\n  isFetchBaseQueryError,\n  isFetchError,\n  isObject,\n  isParsingError,\n  isPayloadAnRTKQueryError,\n  isTimeoutError,\n  isZodValidationError,\n} from '@finmid/distributor-types';\nimport { SentryLogger } from '@finmid/sentry/webapp';\nimport type { Middleware } from '@reduxjs/toolkit';\nimport { MiddlewareAPI, isFulfilled, isRejected } from '@reduxjs/toolkit';\n\nimport { generateTicketNumber } from './generateTicketNumber';\nimport { getApiEndpointForRejectedAction } from './getApiEndpointForRejectedAction';\nimport {\n  getGDPRPayload,\n  replacementValue,\n  sensitiveInfo,\n} from './getGDPRPayload';\n\nconst DEFAULT_MESSAGE = 'RTK errorMiddleware';\nconst DEFAULT_REQUEST_STATUS = 400;\nconst NETWORK_FAILURE_STATUS = 0;\n\nlet lastSuccessAt = Date.now();\n\n/**\n * The browser cancels in-flight fetches when the document goes away, and RTK\n * reports that as a FETCH_ERROR that looks identical to a real connectivity\n * failure — `meta.aborted` stays false because RTK did not do the aborting.\n * `pageshow` clears the flag again because bfcache can revive the document.\n */\nlet isUnloading = false;\nwindow.addEventListener('pagehide', () => {\n  isUnloading = true;\n});\nwindow.addEventListener('pageshow', () => {\n  isUnloading = false;\n});\n\nconst isExpectedDisconnect = () => isUnloading || navigator.onLine === false;\n\nexport const rtkQueryErrorMiddleware: Middleware =\n  (_: MiddlewareAPI) => (next) => (action) => {\n    if (isFulfilled(action)) {\n      lastSuccessAt = Date.now();\n      return next(action);\n    }\n\n    if (isRejected(action)) {\n      const { error, meta, payload } = action;\n      const isAborted = meta?.aborted;\n      const requestIsSkipped =\n        error?.message === 'Aborted due to condition callback returning false.';\n      if (isAborted || requestIsSkipped) {\n        return next(action);\n      }\n\n      const ticketNumber = generateTicketNumber();\n      const [queryType, api, endpoint] =\n        getApiEndpointForRejectedAction(action);\n\n      const gdprPayload = getGDPRPayload({\n        payload: action,\n        sensitiveInfo,\n        replacementValue,\n      });\n\n      const customContext = {\n        ...gdprPayload,\n        queryType,\n        api,\n        endpoint,\n        code: action.error.code,\n        msSinceLastSuccess: Date.now() - lastSuccessAt,\n      };\n\n      try {\n        let message = DEFAULT_MESSAGE;\n        let transactionName = `${queryType} ${api}/${endpoint}`;\n        let requestStatus = DEFAULT_REQUEST_STATUS;\n\n        if (\n          isPayloadAnRTKQueryError(payload) &&\n          isFetchBaseQueryError(payload)\n        ) {\n          if (isBE_Error(payload) || isZodValidationError(payload)) {\n            message = payload.data.message;\n            requestStatus = payload.status;\n            const { method, url } = payload.data.requestContext;\n            transactionName = `${method} ${url}`;\n          } else if (isFetchError(payload)) {\n            if (isExpectedDisconnect()) return next(action);\n            message = payload.error;\n            requestStatus = NETWORK_FAILURE_STATUS;\n          } else if (isCustomError(payload)) {\n            message = payload.error;\n          } else if (isTimeoutError(payload)) {\n            message = payload.error;\n            requestStatus = 408;\n          } else if (isParsingError(payload)) {\n            message = payload.data;\n            requestStatus = payload.originalStatus;\n          } else if (payload.status === 400) {\n            message = `Bad Request in ${queryType} ${api}/${endpoint}`;\n            requestStatus = payload.status;\n          } else if (payload.status === 404) {\n            message = `Not Found in ${queryType} ${api}/${endpoint}`;\n            requestStatus = payload.status;\n          } else {\n            message =\n              typeof payload.data === 'string' ? payload.data : DEFAULT_MESSAGE;\n            requestStatus =\n              typeof payload.status === 'number'\n                ? payload.status\n                : DEFAULT_REQUEST_STATUS;\n          }\n\n          const authorizationRejection = [401, 403].includes(requestStatus);\n          if (authorizationRejection) return next(action);\n\n          const report = {\n            transactionName,\n            customContext,\n            ticket: ticketNumber,\n            fingerprint: ['rtk', api, endpoint, String(requestStatus)],\n          };\n\n          if (requestStatus === NETWORK_FAILURE_STATUS) {\n            SentryLogger.logWarning({ ...report, message });\n          } else {\n            const exception = new Error(message);\n            exception.stack = action.error.stack ?? exception.stack;\n\n            SentryLogger.logError({ ...report, error: exception });\n          }\n\n          if (isObject(action.payload)) {\n            action.payload['ticketNumber'] = ticketNumber;\n          } else {\n            action.payload = { ticketNumber };\n          }\n        } else {\n          const exception = new Error(action.error.message);\n          exception.stack = action.error.stack ?? exception.stack;\n\n          SentryLogger.logError({\n            error: exception,\n            transactionName,\n            customContext,\n            ticket: ticketNumber,\n            fingerprint: ['rtk', api, endpoint, 'serialized-error'],\n          });\n        }\n      } catch (error) {\n        const sentryError =\n          error instanceof Error\n            ? error\n            : typeof error === 'string'\n            ? new Error(error)\n            : new Error(\n                ((error as Record<string, unknown>)['message'] as string) ??\n                  DEFAULT_MESSAGE,\n              );\n\n        SentryLogger.logError({\n          error: sentryError,\n          customContext,\n          ticket: ticketNumber,\n          fingerprint: ['rtk', 'errorMiddleware', 'unexpected'],\n        });\n      }\n    }\n\n    return next(action);\n  };\n","export const b2bPaymentRoutes = {\n  paymentRequests: '/invoices',\n  createPaymentRequest: '/invoices/new',\n  createPaymentRequestsBulk: '/invoices/new/bulk',\n  paymentRequestDocumentUpload: '/invoices/:invoiceId/upload',\n\n  sellers: '/sellers',\n  createSeller: '/sellers/new',\n  editSeller: '/sellers/:sellerId/edit',\n\n  analytics: '/analytics',\n\n  developers: '/developers',\n  // apiKeys: '/developers/api-tokens',\n  createApiKeys: '/developers/api-tokens/new',\n  // webhooks: '/developers/webhooks',\n  createWebhooks: '/developers/webhooks/new',\n} as const;\n","// shared by all (TBL-webapps & Capital)\nexport const sharedRoutes = {\n  debug: '/debug',\n  login: '/login',\n  loginVerification: '/login/auth',\n  logout: '/logout',\n  root: '/',\n\n  platform: '/platform',\n  settings: '/settings',\n\n  developers: '/developers',\n  createApiKeys: '/developers/api-tokens/new',\n  createWebhooks: '/developers/webhooks/new',\n} as const;\n","// shared TBL-B2B routes\nexport const sharedTblRoutes = {\n  buyers: '/buyers',\n  createBuyers: '/buyers/new',\n  editBuyer: '/buyers/:buyerId/edit',\n  buyerDocumentsUpload: '/buyers/:buyerId/upload',\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { FetchBaseQueryMeta } from '@reduxjs/toolkit/query';\n\nimport { BaseQueryType } from './BaseQuery.type';\n\nfunction isUnauthorized(meta?: FetchBaseQueryMeta) {\n  return meta && meta.response && meta.response.status === 401;\n}\n\nfunction isForbidden(meta?: FetchBaseQueryMeta) {\n  return meta && meta.response && meta.response.status === 403;\n}\n\nexport const createBaseQuery = (baseQuery: BaseQueryType) => {\n  const baseQueryWithReauth: BaseQueryType = async (\n    args,\n    api,\n    extraOptions,\n  ) => {\n    const result = await baseQuery(args, api, extraOptions);\n\n    if (isUnauthorized(result.meta) || isForbidden(result.meta)) {\n      if (ENVIRONMENT !== 'live') {\n        console.log('baseQuery.ts: user unauthorized, logging out');\n      }\n      window.location.replace(sharedRoutes.logout);\n    }\n\n    return result;\n  };\n  return baseQueryWithReauth;\n};\n","import { type fetchBaseQuery } from '@reduxjs/toolkit/query';\n\ntype PrepareHeaders = NonNullable<\n  Parameters<typeof fetchBaseQuery>[0]\n>['prepareHeaders'];\n\nexport const prepareHeaders: PrepareHeaders = (headers, api) => {\n  const token = localStorage.getItem('token');\n\n  if (token) {\n    headers.set('Authorization', `Bearer ${token}`);\n  }\n\n  return headers;\n};\n","import { ENVIRONMENT, fromEnvironment } from '@finmid/environment';\nimport { fetchBaseQuery } from '@reduxjs/toolkit/query';\n\nimport { BaseQueryType } from './BaseQuery.type';\nimport { createBaseQuery } from './createBaseQuery';\nimport { prepareHeaders } from './prepareHeaders';\n\nconst legacySandboxUrl = fromEnvironment('GATEWAY_SANDBOX_URL', {\n  required: false,\n});\nconst legacyLiveUrl = fromEnvironment('GATEWAY_LIVE_URL', {\n  required: false,\n});\n\nexport const GATEWAY_URL =\n  fromEnvironment('GATEWAY_URL', {\n    required: false,\n  }) ?? (ENVIRONMENT === 'live' ? legacyLiveUrl : legacySandboxUrl);\n\nif (GATEWAY_URL == null) {\n  // should throw -- remove this after nearest deployment, as well as GATEWAY_SANDBOX_URL and GATEWAY_LIVE_URL\n  fromEnvironment('GATEWAY_URL');\n}\n\nexport const baseQuery: BaseQueryType = async (args, api, extraOptions) => {\n  const baseQuery = fetchBaseQuery({\n    baseUrl: GATEWAY_URL,\n    prepareHeaders,\n  });\n\n  return createBaseQuery(baseQuery)(args, api, extraOptions);\n};\n","import { createApi } from '@reduxjs/toolkit/query/react';\n\nimport { baseQuery } from './helpers';\n\n// when adding new provided tagTypes, we need to also add them to the action\n// dispatched inside `src/components/Header/Header.tsx` so that they are\n// properly invalidated when switching environments.\nexport const cacheTags = [\n  'Analytics',\n  'ApiKeys',\n  'Buyers',\n  'BuyersStats',\n  'BuyersTasks',\n  'BuyersLimits',\n  'Capital.MerchantsOverview',\n  'Currencies',\n  'Documents',\n  'FinancingConditions',\n  'FinancingConfigurations',\n  'PaymentConfigs',\n  'PaymentRequests',\n  'BuyersPaymentRequests',\n  'SellersPaymentRequests',\n  'PaymentRequestStats',\n  'PaymentRequestLogs',\n  'PaymentRequestStatusLogs',\n  'PaymentRequestsTasks',\n  'Payouts',\n  'Sellers',\n  'SellersStats',\n  'Tasks',\n  'Webhooks',\n  'Members',\n] as const;\n\nexport const gatewayService = createApi({\n  reducerPath: 'gatewayService',\n  baseQuery,\n  tagTypes: cacheTags,\n  endpoints: () => ({}),\n});\n","import { TBLCurrency, GetIframeUrls } from '@finmid/distributor-types';\n\nimport { gatewayService } from './gatewayService';\n\nexport type AnalyticsRequest = {\n  target: 'dashboard' | 'question';\n  currency?: TBLCurrency;\n};\n\nexport type AnalyticsResponse = {\n  INVOICES: string;\n  BUYERS_AND_SELLERS: string;\n  FEES: string;\n  GENERAL: string;\n};\n\nconst extendedGatewayService = gatewayService.injectEndpoints({\n  endpoints: (builder) => ({\n    getIframeUrls: builder.query<\n      GetIframeUrls.GatewayResponse,\n      GetIframeUrls.GatewayRequest\n    >({\n      query: ({ currency }) => ({\n        url: 'api/analytics-dashboard',\n        params: {\n          currency,\n        },\n      }),\n      providesTags: ['Analytics'],\n    }),\n  }),\n});\n\nexport const { useGetIframeUrlsQuery } = extendedGatewayService;\n","import { ApiKey } from '@finmid/distributor-types';\n\nimport { gatewayService } from './gatewayService';\n\nexport type CreatedApiToken = ApiKey;\n\nconst extendedGatewayService = gatewayService.injectEndpoints({\n  endpoints: (builder) => ({\n    getApiTokens: builder.query<ApiKey[], void>({\n      query: () => ({ url: 'api/api-keys' }),\n      providesTags: ['ApiKeys'],\n    }),\n\n    createApiToken: builder.mutation<CreatedApiToken, string>({\n      query: (name) => ({\n        url: 'api/api-keys',\n        method: 'POST',\n        body: { name },\n      }),\n      invalidatesTags: ['ApiKeys'],\n    }),\n\n    deleteApiToken: builder.mutation<void, string>({\n      query: (apiTokenPrefix: string) => ({\n        url: `api/api-keys/${apiTokenPrefix}`,\n        method: 'DELETE',\n      }),\n      invalidatesTags: ['ApiKeys'],\n    }),\n  }),\n});\n\nexport const {\n  useGetApiTokensQuery,\n  useCreateApiTokenMutation,\n  useDeleteApiTokenMutation,\n} = extendedGatewayService;\n","export const b2bPaymentsChangelogLink =\n  'https://finmid.notion.site/B2B-Payments-Changelog-82c20b8184f547be957144b1e61cb9e1?pvs=4';\n","export const CSV_TEMPLATE_FILENAME =\n  'payment-requests-bulk-upload-template.csv';\n","export const digitsToWordsList = [\n  'zero',\n  'one',\n  'two',\n  'three',\n  'four',\n  'five',\n  'six',\n  'seven',\n  'eight',\n  'nine',\n  'ten',\n  'eleven',\n  'twelve',\n  'thirteen',\n  'fourteen',\n  'fifteen',\n  'sixteen',\n  'seventeen',\n  'eighteen',\n  'nineteen',\n  'twenty',\n];\n","// distributors used for manual testing\nexport const finmidDistributorId = '234a2630-5ddc-4d55-becd-61371fec3238';\nexport const NienowVonFeeneyDistributorId =\n  'e26d50b2-cf4d-4abf-80bd-4e4394cfc1ba';\nexport const LeuschkeIncId = '6e5aba71-0c8b-4264-9874-1a257c10409b';\n\nexport const ownDistributors