  '05528',\n  '96684-8247',\n  '00377-5762',\n  '29371',\n  '31902-6155',\n  '59278',\n  '13822-3579',\n  '04559-5264',\n  '19087-1796',\n  '98770',\n  '69354-2816',\n  '91073-7873',\n  '15625',\n  '82103',\n  '52559',\n  '48480',\n  '84336-3985',\n  '57525',\n  '12545',\n  '06706-9178',\n  '63910-9983',\n  '23277-6759',\n  '42772-5781',\n  '78731-5486',\n  '68875',\n  '40886',\n  '37311-9959',\n  '04529-0206',\n  '39116',\n  '66202-4313',\n  '35205',\n  '29270',\n  '33643-1142',\n  '61567',\n  '10750-7949',\n  '16410-9581',\n  '14116',\n  '69762-1457',\n  '91310',\n  '86098',\n];\n","import sample from 'lodash/sample';\n\nimport { Fakes } from './fakes/fakes.types';\n\nexport const getRandom = <T>(values: Fakes<T>) => {\n  return sample(values) ?? values[0];\n};\n","const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ';\nconst alphabetLength = alphabet.length;\n\nexport const replaceSymbols = (input: string): string => {\n  return input.replace(/[#?]/g, (match) => {\n    if (match === '#') {\n      return Math.floor(Math.random() * 10).toString();\n    } else if (match === '?') {\n      const randomLetterIndex = Math.floor(Math.random() * alphabetLength);\n      return alphabet[randomLetterIndex];\n    } else {\n      return '';\n    }\n  });\n};\n","import { CreateBuyer_GatewayRequest } from '@finmid/distributor-types';\nimport {\n  addressLine1Fakes,\n  cityFakes,\n  countryFakes,\n  emailFakes,\n  getRandom,\n  legalNameFakes,\n  replaceSymbols,\n  zipCodeFakes,\n} from '@finmid/tbl-webapps/sandbox';\nimport { v4 } from 'uuid';\n\nexport const createTestBuyerData = (): CreateBuyer_GatewayRequest => ({\n  externalId: `test-buyer-${v4()}`,\n  legalName: getRandom(legalNameFakes),\n  businessRegistrationNumber: replaceSymbols('HRB########?'),\n  email: getRandom(emailFakes),\n  legalAddress: {\n    addressLine1: getRandom(addressLine1Fakes),\n    postalCode: getRandom(zipCodeFakes),\n    city: getRandom(cityFakes),\n    country: getRandom(countryFakes),\n  },\n});\n","export const EXTERNAL_ID_REGEX = /^[a-zA-Z0-9_\\\\.\\\\-]+$/;\nexport const ISD_CODE_REGEX = /^\\+[0-9]{1,3}/gim;\nexport const ISD_RAW_REGEX = /^[0-9]{1,3}/g;\nexport const PHONE_REGEX = /^\\+[0-9]{5,}$/gim;\nexport const PHONE_RAW_REGEX = /^[0-9]{5,}$/g;\nexport const TWO_DECIMAL_REGEX = /^\\d+(\\.\\d{0,2})?$/;\nexport const IBAN_SHAPE_REGEX = /[A-Z]{2}[0-9]{2}[0-9 A-Z]*/;\n","import {\n  CreateSeller_GatewayRequest,\n  FpsBankAccountRequest,\n  IbanBankAccountRequest,\n  SwiftBankAccountRequest,\n  TBLCurrency,\n} from '@finmid/distributor-types';\nimport {\n  accountNumberFakes,\n  addressLine1Fakes,\n  bankAccountIdentifierFakes,\n  bicFakes,\n  cityFakes,\n  countryFakes,\n  emailFakes,\n  getRandom,\n  ibanFakes,\n  legalNameFakes,\n  replaceSymbols,\n  sortCodeFakes,\n  zipCodeFakes,\n} from '@finmid/tbl-webapps/sandbox';\nimport { v4 } from 'uuid';\n\nimport { IBAN_SHAPE_REGEX } from './regex';\n\nconst generateSellerBaseData = (): Omit<\n  CreateSeller_GatewayRequest,\n  'bankAccounts'\n> => ({\n  externalId: `test-seller-${v4()}`,\n  legalName: getRandom(legalNameFakes),\n  businessRegistrationNumber: replaceSymbols('HRB########?'),\n  email: getRandom(emailFakes),\n  legalAddress: {\n    addressLine1: getRandom(addressLine1Fakes),\n    postalCode: getRandom(zipCodeFakes),\n    city: getRandom(cityFakes),\n    country: getRandom(countryFakes),\n  },\n});\n\nconst generateIbanBankAccountData = (\n  currency: Extract<TBLCurrency, 'EUR' | 'GBP'>,\n): IbanBankAccountRequest => ({\n  iban: getRandom(ibanFakes),\n  bic: getRandom(bicFakes),\n  currency,\n});\n\nconst generateSwiftBankAccountData = (\n  currency: TBLCurrency,\n): SwiftBankAccountRequest => {\n  const accountNumber = getRandom(bankAccountIdentifierFakes);\n\n  return {\n    accountNumber,\n    accountNumberType: new RegExp(IBAN_SHAPE_REGEX).test(accountNumber)\n      ? 'IBAN'\n      : 'ACCOUNT_NUMBER',\n    bicSwift: getRandom(bicFakes),\n    address: {\n      addressLine: getRandom(addressLine1Fakes),\n      city: getRandom(cityFakes),\n      country: getRandom(countryFakes),\n    },\n    currency,\n  };\n};\n\nconst generateFpsBankAccountData = (): FpsBankAccountRequest => ({\n  sortCode: getRandom(sortCodeFakes),\n  accountNumber: getRandom(accountNumberFakes),\n  currency: 'GBP',\n});\n\ntype CreateTestData = (currency: TBLCurrency) => CreateSeller_GatewayRequest;\nexport const createTestSellerData: CreateTestData = (currency) => ({\n  ...generateSellerBaseData(),\n  bankAccounts: [\n    currency === 'GBP'\n      ? generateFpsBankAccountData()\n      : currency === 'USD'\n      ? generateSwiftBankAccountData('USD')\n      : generateIbanBankAccountData(currency),\n  ],\n});\n","import styled from '@emotion/styled';\nimport { HTMLAttributes } from 'react';\n\nexport type BadgeVariant =\n  | 'neutral'\n  | 'success'\n  | 'alert'\n  | 'danger'\n  | 'running'\n  | 'trivial';\n\ntype StyledBadgeProps = {\n  variant: BadgeVariant;\n};\n\nexport type BadgeProps = HTMLAttributes<HTMLSpanElement> &\n  StyledBadgeProps & {\n    label: string;\n  };\n\nconst StyledBadge = styled.span<StyledBadgeProps>(\n  ({ theme: { com }, variant }) => ({\n    display: 'inline-block',\n    paddingBlockStart: com.badge.padding.top,\n    paddingBlockEnd: com.badge.padding.bottom,\n    paddingInlineStart: com.badge.padding.left,\n    paddingInlineEnd: com.badge.padding.right,\n    backgroundColor: com.badge.color.bg[variant],\n    color:\n      variant === 'neutral'\n        ? com.badge.color.fg.dark\n        : com.badge.color.fg.bright,\n    borderRadius: com.badge.radius,\n    whiteSpace: 'nowrap',\n    ...com.badge.typo,\n  }),\n);\n\nexport const Badge = ({ label, variant, ...props }: BadgeProps) => {\n  return (\n    <StyledBadge variant={variant} {...props}>\n      {label}\n    </StyledBadge>\n  );\n};\n","import { Interpolation, Theme, css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { PositionsProps, SizingProps } from '@mui/system';\nimport { ForwardedRef, HTMLAttributes, forwardRef } from 'react';\n\nexport type IconProps = {\n  color?: string;\n  size?: 'small' | 'medium';\n  icon: React.ReactNode;\n  css?: Interpolation<Theme>;\n} & HTMLAttributes<HTMLDivElement>;\n\n// TODO tokenise\nconst IconContainer = styled.div<Omit<IconProps, 'icon'>>(\n  ({ theme: { com }, size, color }) => css`\n    width: ${size === 'medium' ? '24' : '16'}px;\n    height: ${size === 'medium' ? '24' : '16'}px;\n    color: ${color ?? com.textInput.color.fg.default};\n\n    & svg {\n      width: 100%;\n      height: 100%;\n    }\n  `,\n);\n\nexport const Icon = forwardRef(\n  (\n    {\n      color,\n      size = 'medium',\n      icon,\n      ...props\n    }: IconProps & SizingProps & PositionsProps,\n    ref: ForwardedRef<HTMLDivElement>,\n  ) => (\n    <IconContainer color={color} size={size} {...props} ref={ref}>\n      {icon}\n    </IconContainer>\n  ),\n);\n","import * as React from 'react';\nimport { SVGProps } from 'react';\nconst SvgComponent = (props: SVGProps<SVGSVGElement>) => (\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    width=\"100%\"\n    height=\"100%\"\n    viewBox=\"0 0 24 24\"\n    fill=\"none\"\n    {...props}\n  >\n    <path\n      fill=\"currentColor\"\n      d=\"M11.567 17.25a.5.5 0 0 0 .866 0l5.196-9a.5.5 0 0 0-.433-.75H6.804a.5.5 0 0 0-.433.75l5.196 9Z\"\n    />\n  </svg>\n);\nexport const ExpandIcon = React.memo(SvgComponent);\n","import styled from '@emotion/styled';\n\n// TODO: tokenise\nexport const Listbox = styled('ul')(({ theme: { com } }) => ({\n  minWidth: com.textInput.width.minWidth,\n  maxWidth: com.textInput.width.maxWidth,\n  width: com.textInput.width.width,\n  padding: 4,\n  margin: 0,\n  borderRadius: 12,\n  outline: 'none',\n  backgroundColor: '#FFF',\n  border: 'none',\n  color: com.list.color.fg.default,\n  boxShadow: '0px 0px 0px 4px rgba(40, 40, 41, 0.12)',\n\n  // same as MenuSection label styling\n  '& p.options_title': {\n    fontSize: 11,\n    marginLeft: 12,\n    marginBlock: