      GetFrequentSellers_GatewayRequest\n    >({\n      query: (params: GetFrequentSellers_GatewayRequest) => ({\n        url: `api/frequent-sellers`,\n        params,\n      }),\n    }),\n\n    getSellerById: builder.query<\n      GetSellerById_GatewayResponse,\n      GetSellerById_GatewayRequest\n    >({\n      query: ({ externalId }: GetSellerById_GatewayRequest) =>\n        `api/sellers/${externalId}`,\n      providesTags: (result, error, { externalId }) => [\n        { type: 'Sellers', id: externalId },\n      ],\n    }),\n\n    getSellerUseCase: builder.query<\n      GetSellerUseCase.GatewayResponse,\n      GetSellerUseCase.GatewayRequest\n    >({\n      query: ({ externalId }: GetSellerUseCase.GatewayRequest) =>\n        `api/sellers/${externalId}/use-case`,\n    }),\n\n    createSeller: builder.mutation<\n      CreateSeller_GatewayResponse,\n      CreateSeller_GatewayRequest\n    >({\n      query: (seller: CreateSeller_GatewayRequest) => ({\n        url: `api/sellers`,\n        method: 'POST',\n        body: seller,\n      }),\n      invalidatesTags: ['Sellers', 'SellersStats'],\n    }),\n\n    createTestSeller: builder.mutation<\n      CreateSeller_GatewayResponse,\n      CreateSeller_GatewayRequest\n    >({\n      query: (seller: CreateSeller_GatewayRequest) => ({\n        url: 'api/test-sellers',\n        method: 'POST',\n        body: seller,\n      }),\n      invalidatesTags: ['Sellers', 'SellersStats'],\n    }),\n\n    suspendSeller: builder.mutation<\n      SuspendSeller_GatewayResponse,\n      SuspendSeller_GatewayRequest\n    >({\n      query: ({ externalId, reason }) => ({\n        url: `api/sellers/${externalId}/suspend`,\n        method: 'PUT',\n        body: {\n          reason,\n        },\n      }),\n      invalidatesTags: ['Sellers', 'SellersStats'],\n    }),\n\n    editSeller: builder.mutation<\n      EditSeller_GatewayResponse,\n      EditSeller_GatewayRequest\n    >({\n      query: ({ externalId, ...request }) => ({\n        url: `api/sell