ateWebhook = {\n  status: WebhookStatus;\n  id: string;\n};\n\nconst extendedGatewayService = gatewayService.injectEndpoints({\n  endpoints: (builder) => ({\n    getWebhooks: builder.query<Webhook[], void>({\n      query: () => ({ url: 'api/webhooks' }),\n      providesTags: (result) =>\n        result\n          ? [\n              ...result.map(({ id }) => ({ type: 'Webhooks' as const, id })),\n              'Webhooks',\n            ]\n          : ['Webhooks'],\n    }),\n\n    createWebhook: builder.mutation<Webhook, CreateWebhook>({\n      query: (body) => ({\n        url: 'api/webhooks',\n        method: 'POST',\n        body,\n      }),\n      invalidatesTags: ['Webhooks'],\n    }),\n\n    // we don't have the requirements to update any other webhook field, so for\n    // now only status is allowed. same thing in gateway, only status is updated\n    updateWebhook: builder.mutation<Webhook, UpdateWebhook>({\n      query: ({ id, status }) => ({\n        url: `api/webhooks/${id}`,\n        method: 'PATCH',\n        body: { status },\n      }),\n\n      /**\n       * This is a cool logic to update the cached data, so we don't have to\n       * refresh or refetch anything. This endpoint already returns the\n       * full webhook data, so that makes it easy for us.\n       */\n      async onQueryStarted({ id, ...patch }, { dispatch, queryFulfilled }) {\n        const patchResult = dispatch(\n          extendedGatewayService.util.updateQueryData(\n            'getWebhooks',\n            undefined,\n            (draft) => {\n              const updatedWebhook = draft.find((webhook) => webhook.id === id);\n              if (updatedWebhook != null) {\n                Object.assign(updatedWebhook, patch);\n              }\n            },\n          ),\n        );\n        try {\n          await queryFulfilled;\n        } catch {\n          patchResult.undo();\n        }\n      },\n    }),\n\n    deleteWebhook: builder.mutation<void, string>({\n      query: (webhookId) => ({\n        url: `api/webhooks/${webhookId}`,\n        method: 'DELETE',\n      }),\n      async onQueryStarted(webhookId, { dispatch, queryFulfilled }) {\n        try {\n          await queryFulfilled;\n          dispatch(\n            extendedGatewayService.util.updateQueryData(\n              'getWebhooks',\n              undefined,\n              (draft) => {\n                const index = draft.findIndex(\n                  (webhook) => webhook.id === webhookId,\n                );\n                if (index !== -1) draft.splice(index, 1);\n              },\n            ),\n          );\n        } catch {\n          //\n        }\n      },\n    }),\n  }),\n});\n\nexport const {\n  useCreateWebhookMutation,\n  useGetWebhooksQuery,\n  useDeleteWebhookMutation,\n  useUpdateWebhookMutation,\n} = extendedGatewayService;\n","import { createSlice, PayloadAction } from '@reduxjs/toolkit';\n\nexport type ApiTokensPrefs = {\n  safeKeysAlert: boolean;\n};\n\nexport type LocalPrefsState = {\n  apiTokens: ApiTokensPrefs;\n};\n\nconst initialState: LocalPrefsState = {\n  apiTokens: {\n    safeKeysAlert: true,\n  },\n};\n\nconst localPrefsSlice = createSlice({\n  name: 'mode',\n  initialState,\n  reducers: {\n    setApiTokensPrefs(state, action: PayloadAction<ApiTokensPrefs>) {\n      state.apiTokens = { ...action.payload };\n    },\n  },\n});\n\nexport const { setApiTokensPrefs } = localPrefsSlice.actions;\n\nexport const localPrefsReducer = localPrefsSlice.reducer;\n","import {\n  gatewayService,\n  publicLiveGatewayService,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { StateFromReducersMapObject } from '@reduxjs/toolkit';\n\nimport { debugReducer } from './debugStore';\nimport { localPrefsReducer } from './localPrefsStore/localPrefsStore';\n\nexport const reducer = {\n  debug: debugReducer,\n  localPrefs: localPrefsReducer,\n\n  [gatewayService.reducerPath]: gatewayService.reducer,\n  [publicLiveGatewayService.reducerPath]: publicLiveGatewayService.reducer,\n};\n\nex