WithoutShades = {\n  50: color.foundations[10],\n  100: color.foundations[20],\n  200: color.foundations[30],\n  300: color.foundations[40],\n  400: color.foundations[50],\n  500: color.foundations[60],\n  600: color.foundations[70],\n  700: color.foundations[80],\n  800: color.foundations[90],\n  900: color.foundations[100],\n};\n\nconst green: ColorWithoutShades = {\n  50: color.roles.success[10],\n  100: color.roles.success[20],\n  200: color.roles.success[30],\n  300: color.roles.success[40],\n  400: color.roles.success[50],\n  500: color.roles.success[60],\n  600: color.roles.success[70],\n  700: color.roles.success[80],\n  800: color.roles.success[90],\n  900: color.roles.success[100],\n};\n\nconst violet: ColorWithoutShades = {\n  50: color.roles.accent[10],\n  100: color.roles.accent[20],\n  200: color.roles.accent[30],\n  300: color.roles.accent[40],\n  400: color.roles.accent[50],\n  500: color.roles.accent[60],\n  600: color.roles.accent[70],\n  700: color.roles.accent[80],\n  800: color.roles.accent[90],\n  900: color.roles.accent[100],\n};\n\nconst yellow: ColorWithoutShades = {\n  50: color.roles.alert[10],\n  100: color.roles.alert[20],\n  200: color.roles.alert[30],\n  300: color.roles.alert[40],\n  400: color.roles.alert[50],\n  500: color.roles.alert[60],\n  600: color.roles.alert[70],\n  700: color.roles.alert[80],\n  800: color.roles.alert[90],\n  900: color.roles.alert[100],\n};\n\nconst red: ColorWithoutShades = {\n  50: color.roles.danger[10],\n  100: color.roles.danger[20],\n  200: color.roles.danger[30],\n  300: color.roles.danger[40],\n  400: color.roles.danger[50],\n  500: color.roles.danger[60],\n  600: color.roles.danger[70],\n  700: color.roles.danger[80],\n  800: color.roles.danger[90],\n  900: color.roles.danger[100],\n};\n\nconst blue: ColorWithoutShades = {\n  50: color.roles.running[10],\n  100: color.roles.running[20],\n  200: color.roles.running[30],\n  300: color.roles.running[40],\n  400: color.roles.running[50],\n  500: color.roles.running[60],\n  600: color.roles.running[70],\n  700: color.roles.running[80],\n  800: color.roles.running[90],\n  900: color.roles.running[100],\n};\n\nexport const colors = {\n  gray,\n  grey: gray,\n  blue,\n  green,\n  red,\n  violet,\n  yellow,\n};\n\nexport const finmidBrandColors: PlatformData['brandColors'] = [\n  violet[50],\n  violet[100],\n  violet[200],\n  violet[300],\n  violet[400],\n  violet[500],\n  violet[600],\n  violet[700],\n  violet[800],\n  violet[900],\n];\n","import type { Theme } from '@mui/material/styles';\n\nimport { gray } from './colors';\n\ntype Borders = Theme['borders'];\n\nexport const borders: Borders = {\n  gray400: `1px solid ${gray[400]}`,\n  gray300: `1px solid ${gray[300]}`,\n  gray200: `1px solid ${gray[200]}`,\n  gray100: `1px solid ${gray[100]}`,\n  gray50: `1px solid ${gray[50]}`,\n};\n","import { Breakpoint } from '@mui/material';\n\nexport const breakPoints: Record<Breakpoint, number> = {\n  mobile: 0,\n  tablet: 576,\n  desktop: 992,\n\n  xl: 1200,\n};\n","import { Components } from '@mui/material';\n\nimport type { CustomThemeOptions } from './themeTemplate';\n\nexport const buttonStyles = (\n  theme: CustomThemeOptions,\n): Pick<Components<unknown>, 'MuiButton'> => ({\n  MuiButton: {\n    defaultProps: {\n      color: 'inherit',\n      variant: 'contained',\n    },\n    styleOverrides: {\n      root: {\n        borderRadius: 8,\n        textTransform: 'none',\n        fontSize: '14px',\n        lineHeight: '24px',\n        padding: '8px 32px',\n        position: 'relative',\n        color: theme.palette.gray[600],\n\n        '&.Mui-disabled': {\n          border: `1px solid ${theme.palette.gray[100]}`,\n          backgroundColor: theme.palette.gray[50],\n          color: theme.palette.gray[300],\n        },\n      },\n      contained: {\n        border: `1px solid ${theme.palette.gray[100]}`,\n        backgroundColor: 'white',\n        boxShadow: '0px 1px 2px rgba(203, 213, 224, 0.75)',\n        color: theme.palette.gray[600],\n\n        '&:hover': {\n          boxShadow: '0px 0px 0px 2px rgba(241, 245, 249, 1)',\n          border: `1px solid transparent`,\n          backgroundColor: 'white',\n        },\n      },\n      sizeLarge: {\n        padding: '16px 32px',\n        fontSize: '16px',\n      },\n      // containedSecondary: {\n      //   backgroundColor: theme.palette.secondary.main,\n      //   border: `1px solid ${theme.palette.secondary.main}`,\n      //   boxShadow: 'none',\n      //   color: 'white',\n      //   '&:hover': {\n      //     backgroundColor: theme.palette.secondary.light,\n      //     borderColor: theme.palette.secondary.light,\n      //     boxShadow: 'none',\n      //   },\n      // },\n      containedPrimary: {\n        backgroundColor: theme.palette.primary[700],\n        border: `1px solid ${theme.palette.primary[700]}`,\n        boxShadow: 'none',\n        color: 'white',\n\n        '&:hover': {\n          backgroundColor: theme.palette.primary[600],\n          borderColor: theme.palette.primary[600],\n          boxShadow: 'none',\n        },\n      },\n    },\n  },\n});\n","export const fontFamily = ['Inter', 'sans-serif'].join(', ');\n\nexport const monospaceFontFamily = ['Source Code Pro', 'monospace'].join(', ');\n","import { Shadows as MaterialShadows } from '@mui/material/styles';\n\nexport const shadows = {\n  buttonNormal: '0px 1px 2px 0px rgba(203, 213, 224, 0.5)',\n  buttonMedium: '0px 1px 2px 0px rgba(203, 213, 224, 0.75)',\n  objectNormal: '0px 24px 48px 0px rgba(71, 85, 104, 0.05)',\n  objectHard: '0px 24px 48px 0px rgba(71, 85, 104, 0.1)',\n} as const;\n\nexport type ShadowsType = keyof typeof shadows;\n\nexport const materialShadows: MaterialShadows = [\n  'none',\n\n  '0px 1px 2px rgba(203, 213, 224, 0.75)', // button normal\n  '0px 1px 2px rgba(203, 213, 224, 0.5)', // button medium\n\n  '0px 24px 48px 0px rgba(71, 85, 104, 0.05)', // object normal\n  '0px 24px 48px 0px rgba(71, 85, 104, 0.1)', // object hard,\n\n  // 'none'