ck<MuiDialogProps, 'fullWidth' | 'maxWidth' | 'sx' | 'PaperProps'>;\n\nexport const Dialog = ({\n  title,\n  open,\n  scroll,\n  onClose,\n  children,\n  actions,\n  actionsSx,\n  ...props\n}: DialogProps) => {\n  const scrollProps = scroll ? { scroll } : null;\n  const styleProps = actionsSx ? { style: actionsSx } : null;\n\n  return (\n    <MuiDialog\n      open={open}\n      onClose={onClose}\n      PaperProps={{ style: { maxWidth: '480px' }, elevation: 2 }}\n      {...props}\n      {...scrollProps}\n      PaperComponent={ElevatedPaper}\n    >\n      {title && (\n        <div>\n          <DialogTitle>{title}</DialogTitle>\n        </div>\n      )}\n      <DialogContent>{children}</DialogContent>\n      {actions && (\n        <DialogActions id=\"dialog-actions\" {...styleProps}>\n          {Children.toArray(actions).map((action) => action)}\n        </DialogActions>\n      )}\n    </MuiDialog>\n  );\n};\n","/* eslint-disable react/jsx-no-useless-fragment */\nimport { TextInput } from '@finmid/ui/ocarina';\nimport { Breakpoint } from '@mui/material';\nimport { Dispatch, SetStateAction, useState } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { Button } from '../Button';\nimport { Dialog } from '../Dialog';\nimport { Typography } from '../Typography';\n\nconst Confirm = ({ placeholder }: { placeholder: string }) => {\n  return (\n    <Typography variant=\"monospace\" sx={{ fontSize: '16px', mx: '4px' }}>\n      {placeholder}\n    </Typography>\n  );\n};\n\ntype DangerZoneDialogProps = {\n  fullWidth?: boolean;\n  maxWidth?: Breakpoint;\n  message: string;\n  open: boolean;\n  title: string;\n  cancelLabel?: string;\n  submitLabel?: string;\n  onSubmit: () => void;\n  setOpen: Dispatch<SetStateAction<boolean>>;\n};\n\nexport const DangerZoneDialog = ({\n  message,\n  open,\n  title,\n  cancelLabel,\n  submitLabel,\n  onSubmit,\n  setOpen,\n  ...props\n}: DangerZoneDialogProps) => {\n  const [value, setValue] = useState('');\n  const { t } = useTranslation('components', { keyPrefix: 'dangerZoneDialog' });\n\n  const confirm = t('confirm');\n\n  const canSubmit = value.toLowerCase() === t('confirm').toLowerCase();\n\n  const handleClose = () => {\n    setValue('');\n    setOpen(false);\n  };\n\n  const handleSubmit = () => {\n    if (canSubmit) {\n      onSubmit();\n      handleClose();\n    }\n  };\n\n  const actions = [\n    <Button\n      disabled={!canSubmit}\n      onClick={handleSubmit}\n      testId=\"dialog-submit-button\"\n      type=\"submit\"\n      key=\"submit-btn\"\n      variant=\"destructive\"\n    >\n      {submitLabel ?? t('submit')}\n    </Button>,\n    <Button\n      variant=\"invisible\"\n      onClick={handleClose}\n      testId=\"dialog-cancel-button\"\n      key=\"close-btn\"\n    >\n      {cancelLabel ?? t('cancel')}\n    </Button>,\n  ];\n\n  return (\n    <Dialog\n      open={open}\n      onClose={handleClose}\n      fullWidth\n      actions={actions}\n      title={title}\n      {...props}\n    >\n      <Typography\n        fontSize={15}\n        fontWeight={400}\n        lineHeight=\"20px\"\n        color=\"gray.500\"\n      >\n        {message}\n      </Typography>\n\n      <Typography mt={3} mb={1}>\n        <Trans\n          t={t}\n          i18nKey=\"instructions\"\n          components={[<></>, <Confirm placeholder={confirm} />]}\n        />\n      </Typography>\n      <TextInput\n        testId=\"confirm\"\n        fullWidth\n        placeholder={t('label')}\n        value={value}\n        onChange={(e) => setValue(e.target.value.toUpperCase())}\n        onKeyDown={(e) => {\n          if (e.key === 'Enter') {\n            handleSubmit();\n          }\n        }}\n      />\n    </Dialog>\n  );\n};\n","import styled from '@emotion/styled';\n\nimport { headerNavigationHeight } from '../constants';\n\nexport const HeaderContainer = styled('nav')(({ theme }) => ({\n  top: 0,\n  position: 'absolute',\n  zIndex: 10,\n  left: 0,\n  right: 0,\n  height: headerNavigationHe