seCallback(\n    (pathname: string, routes: readonly string[]) => {\n      let match: PathMatch<string> | null = null;\n      for (let i = 0; i < routes.length; i += 1) {\n        const pattern = routes[i];\n        const possibleMatch = matchPath(pattern, pathname);\n        if (possibleMatch !== null) {\n          match = possibleMatch;\n        }\n      }\n      return match;\n    },\n    [],\n  );\n\n  useEffect(() => {\n    const match = findMatch(pathname, routes);\n    setCurrentTab(match?.pathnameBase ?? '');\n  }, [findMatch, pathname, routes]);\n\n  return currentTab;\n};\n","import { Tab, Tabs, TabsList } from '@finmid/ui/ocarina';\nimport { prepareForSlot } from '@mui/base';\nimport { Link } from 'react-router-dom';\n\nimport { MenuItemTypeProps } from '../Sidebar';\n\nimport { useMatchTabToRoute } from './useMatchTabToRoute';\n\ntype HeaderTabsProps = {\n  menuItems: MenuItemTypeProps[];\n};\n\nconst LinkSlot = prepareForSlot(Link);\n\nexport const HeaderTabs = ({ menuItems }: HeaderTabsProps) => {\n  const routes = menuItems.map((item) =>\n    'route' in item ? `${item.route}/*` : '',\n  );\n  const currentTab = useMatchTabToRoute(routes);\n\n  return (\n    <Tabs variant=\"dark\" value={currentTab}>\n      <TabsList>\n        {menuItems.map(({ label, ...rest }) => (\n          <Tab\n            key={label}\n            value={'route' in rest ? rest.route : ''}\n            to={'route' in rest ? rest.route : ''}\n            slots={{ root: LinkSlot }}\n          >\n            {label}\n          </Tab>\n        ))}\n      </TabsList>\n    </Tabs>\n  );\n};\n","import { Loader } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { PropsWithChildren, Suspense } from 'react';\nimport { Outlet } from 'react-router-dom';\n\nimport { MenuItemTypeProps } from '../Sidebar';\n\nimport { HeaderContainer } from './HeaderContainer';\nimport { HeaderLogo } from './HeaderLogo';\nimport { HeaderTabs } from './HeaderTabs';\n\ntype DashboardLayout