lex',\n  alignItems: 'center',\n  paddingLeft: theme.spacing(0.5),\n  paddingRight: theme.spacing(0.5),\n\n  '& p': {\n    marginLeft: theme.spacing(2),\n    flex: 1,\n  },\n\n  '& hr': {\n    borderColor: theme.palette.grey[100],\n  },\n\n  '> div': {\n    display: 'flex',\n    alignItems: 'stretch',\n    gap: theme.spacing(1),\n  },\n}));\n","import styled from '@emotion/styled';\nimport Box from '@mui/material/Box';\nimport { PropsWithChildren, ReactNode } from 'react';\n\nimport { SectionHeader } from './SectionHeader';\n\nexport const SectionContainer = styled(Box)(({ theme }) => ({\n  display: 'flex',\n  flexDirection: 'column',\n  backgroundColor: theme.palette.gray[50],\n  paddingTop: theme.spacing(0.5),\n  paddingBottom: theme.spacing(0.5),\n  gap: theme.spacing(0.5),\n  border: '1px solid',\n  borderColor: theme.palette.gray[100],\n  borderRadius: 16,\n  width: '100%',\n}));\n\ntype SectionProps = PropsWithChildren<{\n  title: string;\n  actions?: ReactNode[];\n  testId?: string;\n  maxWidth?: number;\n}>;\n\nexport const Section = ({\n  children,\n  title,\n  actions,\n  testId,\n  maxWidth,\n}: SectionProps) => {\n  return (\n    <SectionContainer data-test-id={testId} maxWidth={maxWidth}>\n      <SectionHeader actions={actions}>{title}</SectionHeader>\n      {children}\n    </SectionContainer>\n  );\n};\n","import styled from '@emotion/styled';\nimport { HTMLAttributes } from 'react';\n\nimport { Typography } from '../Typography';\n\ntype SectionContentProps = {\n  title?: string;\n} & HTMLAttributes<HTMLDivElement>;\n\nexport const SectionContent = styled(\n  ({ children, title, ...props }: SectionContentProps) => (\n    <div {...props}>\n      {title && (\n        <Typography\n          fontSize={15}\n          lineHeight=\"20px\"\n          color=\"gray.700\"\n          fontWeight={700}\n        >\n          {title}\n        </Typography>\n      )}\n      {children}\n    </div>\n  ),\n  {\n    shouldForwardProp: (prop) => prop !== 'disablePadding',\n  },\n)<{ disablePadding?: boolean }>(({ theme, disablePadding = false }) => ({\n  backgroundColor: '#FFF',\n  borderRadius: 12,\n  border: '1px solid',\n  borderColor: theme.palette.gray[100],\n  marginBottom: theme.spacing(0.5),\n  marginLeft: theme.spacing(0.5),\n  marginRight: theme.spacing(0.5),\n\n  overflow: 'hidden',\n\n  display: 'flex',\n  flexDirection: 'column',\n  alignItems: 'stretch',\n\n  '&:last-of-type': {\n    marginBottom: 0,\n  },\n\n  ...(!disablePadding && {\n    padding: theme.spacing(2),\n    gap: theme.spacing(2),\n  }),\n}));\n","import styled from '@emotion/styled';\nimport { useDetectTruncated } from '@finmid/tbl-webapps/hooks';\nimport { Tooltip } from '@finmid/ui/ocarina';\nimport { Typography } from '@mui/material';\nimport { HTMLAttributes, ReactNode, useRef } from 'react';\n\ntype SectionDataRow = {\n  label: ReactNode;\n  testId?: string;\n  'data-date'?: string;\n  'data-currency'?: string;\n  'data-amount'?: string | number;\n} & HTMLAttributes<HTMLDivElement>;\n\nexport const SectionDataRow = styled(\n  ({\n    label,\n    children,\n    testId,\n    'data-date': dataDate,\n    'data-currency': dataCurrency,\n    'data-amount': dataAmount,\n    ...props\n  }: SectionDataRow) => {\n    const valueRef = useRef<HTMLParagraphElement>(null);\n    const isTruncated = useDetectTruncated(valueRef);\n\n    const tooltip = typeof children === 'string' ? children : '';\n\n    return (\n      <div {...props}>\n        <Typography\n          fontSize={13}\n          fontWeight={500}\n          lineHeight=\"16px\"\n          color=\"gray.500\"\n        >\n          {label}\n        </Typography>\n        <Tooltip title={tooltip} disableHoverListener={!isTruncated}>\n          <div\n            ref={valueRef}\n            className=\"section-row-value\"\n            data-test-id={testId ?? `property-${label}`}\n            data-currency={dataCurrency}\n            data-amount={dataAmount}\n            data-date={dataDate}\n          >\n            {children == null || children === '' ? '-' : children}\n          </div>\n        </Tooltip>\n      </div>\n    );\n  },\n)(({ theme }) => ({\n  display: 'flex',\n  alignItems: 'baseline',\n  gap: theme.spacing(3),\n  paddingTop: theme.spacing(1),\n  paddingBottom: theme.spacing(1),\n  paddingRight: theme.spacing(2),\n  paddingLeft: theme.spacing(2),\n\n  borderBottom: '1px solid',\n  borderColor: theme.palette.gray[100],\n\n  '&:last-of-type': {\n    borderBottom: 'none',\n  },\n\n  ' .section-row-value': {\n    flex: 1,\n    textAlign: 'right',\n    fontSize: 15,\n    lineHeight: '20px',\n    fontWeight: 400,\n    fontFeatureSettings: \"'ss01' on, 'ss02' on\",\n    fontVariantNumeric: 'lining-nums tabular-nums',\n    overflowX: 'hidden',\n    whiteSpace: 'nowrap',\n    overflow: 'hidden',\n    textOverflow: 'ellipsis',\n  },\n}));\n","import styled from '@emotion/styled';\n\nexport const SectionFooter = styled.div(({ theme }) => ({\n  backgroundColor: theme.palette.white,\n  width: '100%',\n  position: 'absolute',\n  bottom: 0,\n  left: 0,\n  borderBottomLeftRadius: 16,\n  borderBottomRightRadius: 16,\n  padding: '12px',\n  zIndex: 5,\n  borderTop: '1px solid',\n  borderColor: theme.palette.gray[100],\n  display: 'flex',\n  gap: theme.spacing(1),\n}));\n","import styled from '@emotion/styled';\nimport { SxProps } from '@mui/system';\nimport {\n  Fragment,\n  PropsWithChildren,\n  ReactNode,\n  forwardRef,\n  useImperativeHandle,\n  useRef,\n} from 'react';\n\nimport { SectionContainer, SectionFooter, SectionHeader } from '../Section';\nimport { formSectionMaxWidth } from '../constants';\n\ntype ScrollableFormSectionProps = PropsWithChildren<{\n  sectionTitle: string;\n  headerActions?: ReactNode[];\n  footerActions: ReactNode[];\n  sx?: SxProps;\n}>;\n\nexport type ScrollContainerHandle = {\n  scrollToBottom: () => void;\n};\n\nconst ScrollContainer = styled.div(({ theme }) => ({\n  height: '100%',\n  overflowY: 'scroll',\n  overflowX: 'hidden',\n  marginBottom: 53,\n  paddingBottom: theme.spacing(0.5),\n}));\n\nexport const ScrollableFormSection = forwardRef<\n  ScrollContainerHandle,\n  ScrollableFormSectionProps\n>(({ sectionTitle, headerActions, footerActions, children, sx }, ref) => {\n  const containerRef = useRef<HTMLDivElement>(null);\n\n  const scrollToBottom = () => {\n    if (containerRef.current == null) return;\n    containerRef.current.scrollTop = containerRef.current.scrollHeight;\n  };\n\n  useImperativeHandle(ref, () => ({\n    scrollToBottom,\n  }));\n\n  return (\n    <SectionContainer\n      maxWidth={formSectionMaxWidth}\n      sx={{\n        height: '100%',\n        position: 'relative',\n        ...sx,\n      }}\n    >\n      <SectionHeader actions={headerActions} data-test-id=\"section-header\">\n        {sectionTitle}\n      </SectionHeader>\n      <ScrollContainer ref={containerRef}>{children}</ScrollContainer>\n      <SectionFooter data-test-id=\"section-footer\">\n        {footerActions.map((action, index) => (\n          <Fragment key={`footer-action-${index}`}>{action}</Fragment>\n        ))}\n      </SectionFooter>\n    </SectionContainer>\n  );\n});\n","import styled from '@emotion/styled';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { Tooltip } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { MouseEvent } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useCopyToClipboard } from 'react-use';\n\ntype TruncatedContentProps = {\n  content: string;\n  maxWidth?: number;\n  testId?: string;\n};\n\nconst CopyIdCell = styled('div')(({ theme }) => ({\n  padding: `0 ${theme.spacing(0.5)}`,\n  borderRadius: 4,\n  whiteSpace: 'nowrap',\n  textOverflow: 'ellipsis',\n  overflow: 'hidden',\n  cursor: 'pointer',\n\n  '&:hover': {\n    backgroundColor: theme.palette.gray[100],\n  },\n}));\n\nexport const TruncatedContent = ({\n  content,\n  maxWidth = 200,\n  testId,\n}: TruncatedContentProps) => {\n  const { notifySuccess } = 