/File';\nimport { Typography } from '../../Typography';\n\ntype AddedFilesProps = {\n  files: File[];\n  onRemove: (index: number) => void;\n};\n\nexport const AddedFiles = ({ files, onRemove }: AddedFilesProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'documentUpload' });\n\n  return (\n    <Box display=\"flex\" flexDirection=\"column\" gap={1} p={2}>\n      <Typography\n        fontSize={13}\n        fontWeight={500}\n        lineHeight=\"16px\"\n        color=\"gray.500\"\n        mb={1}\n      >\n        {t('addedFiles.title', { count: files.length })}\n      </Typography>\n\n      {files.map((file, index) => (\n        <Fragment key={file.name + index}>\n          <File file={file} onRemove={() => onRemove(index)} />\n        </Fragment>\n      ))}\n    </Box>\n  );\n};\n","import styled from '@emotion/styled';\n\nexport const DropzoneArea = styled.div(({ theme: { glo } }) => ({\n  height: 250,\n  width: '100%',\n\n  backgroundColor: glo.color.foundations[10],\n\n  border: '1px dashed',\n  borderColor: glo.color.foundations[20],\n  borderRadius: 12,\n\n  cursor: 'pointer',\n\n  display: 'flex',\n  justifyContent: 'center',\n  alignItems: 'center',\n}));\n","import styled from '@emotion/styled';\nimport { DocumentIcon, Icon } from '@finmid/ui/ocarina';\n\nconst Container = styled.div(({ theme: { glo } }) => ({\n  width: 44,\n  height: 44,\n  borderRadius: 12,\n  backgroundColor: glo.color.foundations[0],\n\n  border: '1px solid',\n  borderColor: glo.color.foundations[20],\n\n  display: 'flex',\n  justifyContent: 'center',\n  alignItems: 'center',\n}));\n\nexport const DropzoneIcon = () => {\n  return (\n    <Container>\n      <Icon icon={<DocumentIcon />} />\n    </Container>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { Typography } from '../Typography';\n\nimport { DropzoneIcon } from './DropzoneIcon';\n\nconst typographyStyles = {\n  fontSize: 13,\n  lineHeight: '16px',\n  fontWeight: 500,\n};\n\nconst Underlined = styled.u(({ theme }) => ({\n  color: theme.palette.gray[400],\n}));\n\ntype DropzoneEmptyStateProps = {\n  title?: string;\n  withIcon?: boolean;\n};\n\nexport const DropzoneEmptyState = ({\n  title,\n  withIcon = true,\n}: DropzoneEmptyStateProps) => {\n  const { t } = useTranslation('components', { keyPrefix: 'dropzone' });\n\n  return (\n    <>\n      {withIcon && (\n        <>\n          <DropzoneIcon />\n          <Spacer height={2} />\n        </>\n      )}\n      <Typography {...typographyStyles}>{title || t('title')}</Typography>\n      <Spacer height={0.5} />\n\n      <Typography {...typographyStyles} color=\"gray.300\">\n        <Trans\n          t={t}\n          i18nKey=\"subtitle\"\n          components={{\n            u: <Underlined />,\n          }}\n        />\n      </Typography>\n    </>\n  );\n};\n","export const MAX_FILE_SIZE = 15728640; // 15 MB\nexport const MAX_FILES = 20;\n","import styled from '@emotion/styled';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { Typography } from '../../../Typography';\n\nconst Underlined = styled.u(({ theme }) => ({\n  color: theme.palette.gray[400],\n}));\n\nexport const UploadMore = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'documentUpload' });\n\n  return (\n    <>\n      <Typography fontSize={15} fontWeight={700} lineHeight=\"16px\">\n        {t('dropzone.uploadMoreTitle')}\n      </Typography>\n      <Spacer height={0.5} />\n      <Typography\n        fontSize={13}\n        fontWeight={500}\n        lineHeight=\"16px\"\n        color=\"gray.300\"\n      >\n        <Trans\n          t={t}\n          i18nKey=\"dropzone.uploadMoreSubtitle\"\n          components={{\n            u: <Underlined />,\n          }}\n        />\n      </Typography>\n    </>\n  );\n};\n","import Box from '@mui/material/Box';\nimport Dropzone, { FileRejection } from 'react-dropzone';\nimport { useTranslation } from 'react-i18next';\n\nimport { DropzoneArea, DropzoneEmptyState } from '../../../Dropzone';\nimport { MAX_FILES, MAX_FILE_SIZE } from '../../utils/constants';\n\nimport { UploadMore } from './UploadMore';\n\ntype FilesUploadProps = {\n  files: File[];\n  onDrop: (acceptedFiles: File[], rejectedFiles: FileRejection[]) => void;\n};\n\nexport const FilesUpload = ({ files, onDrop }: FilesUploadProps) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'documentUpload',\n  });\n  const hasAddedFiles = files.length > 0;\n\n  return (\n    <Dropzone\n      useFsAccessApi={false} // https://github.com/react-dropzone/react-dropzone/discussions/1339\n      onDrop={onDrop}\n      accept={{\n        'image/jpg': ['.jpg', '.jpeg'],\n        'image/png': ['.png'],\n        'application/pdf': ['.pdf'],\n      }}\n      maxFiles={MAX_FILES}\n      maxSize={MAX_FILE_SIZE}\n    >\n      {({ getRootProps, getInputProps }) => (\n        <DropzoneArea\n          {...getRootProps()}\n          css={{\n            transition: 'height 250ms ease-out',\n            height: hasAddedFiles ? 100 : undefined,\n          }}\n        >\n          <input {...getInputProps()} data-test-id=\"drop-files-input\" />\n          <Box\n            display=\"flex\"\n            flexDirection=\"column\"\n            alignItems=\"center\"\n            textAlign=\"center\"\n            data-test-id=\"drop-files-box\"\n          >\n            {hasAddedFiles ? (\n              <UploadMore />\n            ) : (\n              <DropzoneEmptyState title={t('dropzone.title')} />\n            )}\n          </Box>\n        </DropzoneArea>\n      )}\n    </Dropzone>\n  );\n};\n","import { humanReadableFileSize } from '@finmid/tbl-webapps/utils';\nimport { useCallback } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { MAX_FILES, MAX_FILE_SIZE } from '../utils/constants';\n\nexport const useCustomDropzoneErrors = () => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'validation',\n  });\n\n  const getCustomDropzoneErrors = useCallback(\n    (errorCode: string, fileNames?: string[]) => {\n      let message: string | undefined;\n      switch (errorCode) {\n        case 'file-invalid-type':\n          message = t('file.invalidType');\n          break;\n        case 'too-many-files':\n          message = t('file.tooMany', { maxFiles: MAX_FILES });\n          break;\n        case 'file-too-large':\n          message = t('file.tooLarge', {\n            maxSize: humanReadableFileSize(MAX_FILE_SIZE),\n          });\n          break;\n        default:\n          break;\n      }\n\n      return message;\n    },\n    [t],\n  );\n\n  return { getCustomDropzoneErrors };\n};\n","import { useMemo } from 'react';\nimport { FileRejection } from 'react-dropzone';\n\nimport { useCustomDropzoneErrors } from './customDropzoneErrors.hook';\n\nexport const useUniqueDropzoneErrors = (fileErrors: FileRejection[]) => {\n  const { getCustomDropzoneErrors } = useCustomDropzoneErrors();\n\n  const errorMessages = useMemo(() => {\n    const messages: string[] = [];\n    const uniqueErrorCodes = [\n      ...new Set(\n        fileErrors.flatMap(({ errors }) => {\n          return errors.map(({ code }) => code);\n        }),\n      ),\n    ];\n\n    uniqueErrorCodes.forEach((errorCode) => {\n      const message = getCustomDropzoneErrors(errorCode);\n      if (message) messages.push(message);\n    });\n\n    return messages;\n  }, [fileErrors, getCustomDropzoneErrors]);\n\n  return { errorMessages };\n};\n","import { useEffect, useState } from 'react';\nimport { FileRejection } from 'react-dropzone';\n\nimport { MAX_FILES } from '../utils/constants';\n\nexport type FileErrors = {\n  rejectedFiles: string[];\n  errorCodes: string[];\n};\n\nexport const usePageDocumentsUpload = () => {\n  const [files, setFiles] = useState<File[]>([]);\n  const [fileErrors, setFileErrors] = useState<FileRejection[]>([]);\n  const [tooManyFiles, setTooManyFiles] = useState(false);\n\n  const addFiles = (newFiles: File[], rejectedFiles: FileRejection[]) => {\n    setFiles((f) => [...f, ...newFiles]);\n    setFileErrors(rejectedFiles);\n  };\n\n  useEffect(() => {\n    setTooManyFiles(files.length > MAX_FILES);\n    if (files.length === 0) setFileErrors([]);\n  }, [files.length]);\n\n  const removeFile = (index: number) => {\n    setFiles(files.filter((_, i) => i !== index));\n  };\n\n  return { addFiles, removeFile, files, fileErrors, tooManyFiles };\n};\n","import { FileRejection } from 'react-dropzone';\nimport { useTranslation } from 'react-i18next';\n\nimport { Alert } from '../../Alert';\nimport { Typography } from '../../Typography';\nimport { useUniqueDropzoneErrors } from '../hooks';\n\ntype InvalidFilesAlertsProps = {\n  fileErrors: FileRejection[];\n};\n\nexport const InvalidFilesAlerts = ({ fileErrors }: InvalidFilesAlertsProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'documentUpload' });\n  const rejectedFilesNames = fileErrors.map(({ file }) => file.name).join(', ');\n  const { errorMessages } = useUniqueDropzoneErrors(fileErrors);\n\n  const hasMultipleErrors = errorMessages.length > 1;\n\n  return (\n    <Alert severity=\"warning\" data-test-id=\"invalid-files\">\n      <Typography>\n        {fileErrors.length === 1\n          ? t('error.unableToAddFile')\n          : t('error.unableToAddFiles')}\n        {rejectedFilesNames}.\n      </Typography>\n\n      {hasMultipleErrors ? (\n        <ul>\n          {errorMessages.map((message, index) => (\n            <li key={index}>{message}</li>\n          ))}\n        </ul>\n      ) : (\n        <Typography mt={1}>{errorMessages[0]}</Typography>\n      )}\n    </Alert>\n  );\n};\n","import { Alert } from '../../Alert';\nimport { Typography } from '../../Typography';\nimport { useCustomDropzoneErrors } from '../hooks';\n\nexport const TooManyFilesAlert = () => {\n  const { getCustomDropzoneErrors } = useCustomDropzoneErrors();\n\n  return (\n    <Alert severity=\"warning\">\n      <Typography>{getCustomDropzoneErrors('too-many-files')}</Typography>\n    </Alert>\n  );\n};\n","import { Breadcrumb, useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { Button, Loader } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { SerializedError } from '@reduxjs/toolkit';\nimport { FetchBaseQueryError } from '@reduxjs/toolkit/query';\nimport { ReactElement } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { Divider } from '../Divider';\nimport { Page } from '../Page';\nimport { PageNavigation } from '../PageNavigation';\nimport { ScrollableFormSection } from '../ScrollableFormSection';\nimport { SectionContent } from '../Section';\n\nimport {\n  AddedFiles,\n  FilesUpload,\n  InvalidFilesAlerts,\n  TooManyFilesAlert,\n} from './components';\nimport { usePageDocumentsUpload } from './hooks';\n\ntype InnerDocumentsUploadProps = {\n  backHomeRoute: string;\n  breadcrumbs: Breadcrumb;\n  isLoading: boolean;\n  DocumentsUploadDescription: ReactElement;\n  uploadDocuments: (files: File[]) => Promise<\n    | {\n        data: void;\n        error?: undefined;\n      }\n    | {\n        data?: undefined;\n        error: FetchBaseQueryError | SerializedError;\n      }\n  >;\n};\n\nexport const InnerDocumentsUpload = ({\n  backHomeRoute,\n  breadcrumbs,\n  isLoading,\n  DocumentsUploadDescription,\n  uploadDocuments,\n}: InnerDocumentsUploadProps) => {\n  const { t, ready: componentsReady } = useTranslation('components', {\n    keyPrefix: 'documentUpload',\n  });\n  const { ready: formatsReady } = useTranslation('formats');\n\n  const { notifyError, notifySuccess } = useNotifications();\n  const navigate = useNavigate();\n\n  const isLoadingTranslations = !componentsReady || !formatsReady;\n\n  const { addFiles, removeFile, files, fileErrors, tooManyFiles } =\n    usePageDocumentsUpload();\n\n  const hasAddedFiles = files.length > 0;\n  const hasRejectedFiles = fileErrors.length > 0;\n\n  const handleUpload = async () => {\n    const { error } = await uploadDocuments(files);\n    if (error) {\n      notifyError(t('errorUploadingFiles'));\n    } else {\n      notifySuccess(t('successUploadingFiles'));\n      navigate(backHomeRoute);\n    }\n  };\n\n  return (\n    <>\n      <PageNavigation breadcrumbs={breadcrumbs} />\n      <Page>\n        {isLoadingTranslations ? (\n          <Loader />\n        ) : (\n          <ScrollableFormSection\n            sectionTitle={t('sectionTitle')}\n            footerActions={[\n              <Button\n                disabled={!hasAddedFiles || tooManyFiles || isLoading}\n                onClick={handleUpload}\n                data-test-id=\"upload-submit-btn\"\n              >\n                {t('submitButton.label')}\n              </Button>,\n            ]}\n          >\n            <SectionContent disablePadding>\n              <Box display=\"flex\" flexDirection=\"column\" gap={2} p={2}>\n                {DocumentsUploadDescription}\n                <FilesUpload files={files} onDrop={addFiles} />\n\n                {hasRejectedFiles && (\n                  <InvalidFilesAlerts fileErrors={fileErrors} />\n                )}\n\n                {tooManyFiles && <TooManyFilesAlert />}\n              </Box>\n\n              {hasAddedFiles && (\n                <>\n                  <Divider />\n                  <AddedFiles files={files} onRemove={removeFile} />\n                </>\n              )}\n            </SectionContent>\n          </ScrollableFormSection>\n        )}\n      </Page>\n    </>\n  );\n};\n","import styled from '@emotion/styled';\nimport { backdropClasses } from '@mui/material/Backdrop';\nimport MuiDrawer from '@mui/material/Drawer';\nimport { paperClasses } from '@mui/material/Paper';\n\nexport const Drawer = styled(MuiDrawer)(({ theme: { glo } }) => ({\n  [`& .${paperClasses.root}`]: {\n    boxShadow: '0px 0px 0px 8px rgba(40, 40, 41, 0.24)',\n    width: 440,\n  },\n  [`& .${backdropClasses.root}`]: {\n    backgroundColor: `${glo.color.foundations[100]}30`,\n  },\n}));\n","import styled from '@emotion/styled';\nimport { Box } from '@mui/material';\n\nimport { headerNavigationHeight } from '../constants';\n\nexport const DrawerContent = styled(Box)(({ theme: { glo, spacing } }) => ({\n  display: 'flex',\n  flexDirection: 'column',\n  justifyContent: 'flex-start',\n  paddingInline: spacing(2),\n  paddingBlockStart: spacing(3),\n  paddingBlockEnd: spacing(2),\n  minHeight: `calc(100vh - ${headerNavigationHeight}px)`,\n  position: 'relative',\n  overflowY: 'auto',\n\n  '&:before': {\n    content: `\"\"`,\n    backgroundColor: glo.color.foundations[20],\n    display: 'block',\n    width: '1px',\n    height: '100%',\n    position: 'absolute',\n    left: 0,\n    top: 0,\n  },\n}));\n","import styled from '@emotion/styled';\nimport { CloseXIcon, IconButton } from '@finmid/ui/ocarina';\nimport Box, { BoxProps } from '@mui/material/Box';\n\nimport { Typography } from '../Typography';\nimport { headerNavigationHeight } from '../constants';\n\ntype DrawerHeaderProps = {\n  title: string;\n  onClose: () => void;\n} & BoxProps;\n\nexport const DrawerHeader = styled(\n  ({ title, onClose, ...props }: DrawerHeaderProps) => {\n    return (\n      <Box {...props}>\n        <Typography fontSize={15} lineHeight=\"20px\">\n          {title}\n        </Typography>\n        <IconButton\n          icon={<CloseXIcon />}\n          size=\"s\"\n          onClick={onClose}\n          data-test-id=\"close-icon\"\n        />\n      </Box>\n    );\n  },\n)(({ theme: { glo, spacing } }) => ({\n  backgroundColor: glo.color.foundations[90],\n  color: glo.color.foundations[40],\n\n  display: 'flex',\n  alignItems: 'center',\n  justifyContent: 'space-between',\n\n  height: headerNavigationHeight,\n  paddingInline: spacing(3),\n  flexShrink: 0,\n}));\n","import type { DrawerProps as MuiDrawerProps } from '@mui/material/Drawer';\n\nimport { Drawer as StyledDrawer } from './Drawer.styled';\nimport { DrawerContent } from './DrawerContent';\nimport { DrawerHeader } from './DrawerHeader';\n\ntype DrawerProps = {\n  title: string;\n  onClose: () => void;\n  testId?: string;\n} & MuiDrawerProps;\n\nexport const Drawer = ({\n  anchor = 'right',\n  transitionDuration = 500,\n  title,\n  onClose,\n  children,\n  testId,\n  ...props\n}: DrawerProps) => {\n  return (\n    <StyledDrawer\n      anchor={anchor}\n      transitionDuration={transitionDuration}\n      onClose={onClose}\n      data-test-id={testId}\n      {...props}\n    >\n      <DrawerHeader title={title} onClose={onClose} />\n      <DrawerContent>{children}</DrawerContent>\n    </StyledDrawer>\n  );\n};\n","import styled from '@emotion/styled';\nimport Box from '@mui/material/Box';\nimport { PropsWithChildren } from 'react';\n\nimport { Typography } from '../Typography';\n\nexport type AlertLevel = 'warning' | 'error' | 'info' | 'trivial';\n\ntype DrawerAlertProps = PropsWithChildren<{\n  level?: AlertLevel;\n  testId?: string;\n}>;\n\nexport const DrawerAlert = styled(\n  ({ children, testId, ...props }: DrawerAlertProps) => (\n    <Box {...props} data-test-id={testId}>\n      <Typography>{children}</Typography>\n    </Box>\n  ),\n)<DrawerAlertProps>(({ theme: { glo, spacing }, level = 'info' }) => ({\n  display: 'flex',\n  justifyContent: 'center',\n  alignItems: 'center',\n  padding: spacing(1.5),\n  minHeight: 48,\n  borderRadius: 12,\n  border: '1px solid',\n\n  flexShrink: 0,\n\n  p: {\n    fontSize: 15,\n    lineHeight: '20px',\n    color: 'inherit',\n  },\n\n  ...(level === 'error'\n    ? {\n        backgroundColor: glo.color.roles.danger[20],\n        borderColor: glo.color.roles.danger[30],\n        color: glo.color.roles.danger[70],\n      }\n    : {}),\n\n  ...(level === 'warning'\n    ? {\n        backgroundColor: glo.color.roles.alert[20],\n        borderColor: glo.color.roles.alert[30],\n        color: glo.color.roles.alert[70],\n      }\n    : {}),\n\n  ...(level === 'trivial'\n    ? {\n        backgroundColor: glo.color.roles.trivial[20],\n        borderColor: glo.color.roles.trivial[30],\n        color: glo.color.roles.trivial[70],\n      }\n    : {}),\n\n  ...(level === 'info'\n    ? {\n        backgroundColor: glo.color.foundations[10],\n        borderColor: glo.color.foundations[20],\n        color: glo.color.foundations[100],\n      }\n    : {}),\n}));\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { SentryLogger } from '@finmid/sentry/webapp';\nimport { Component, ErrorInfo, PropsWithChildren, ReactNode } from 'react';\n\ntype ErrorBoundaryProps = PropsWithChildren<{ fallback: ReactNode }>;\ntype ErrorBoundaryState = {\n  hasError: boolean;\n};\n\nexport class ErrorBoundary extends Component<\n  ErrorBoundaryProps,\n  ErrorBoundaryState\n> {\n  override state = {\n    hasError: false,\n  };\n\n  static getDerivedStateFromError() {\n    return { hasError: true };\n  }\n\n  override componentDidCatch(error: Error, errorInfo: ErrorInfo): void {\n    if (ENVIRONMENT === 'localhost') {\n      console.log({ error, errorInfo });\n    } else if (ENVIRONMENT !== 'test') {\n      SentryLogger.logWarning(error);\n    }\n  }\n\n  override render() {\n    if (this.state.hasError) {\n      return this.props.fallback;\n    }\n\n    return this.props.children;\n  }\n}\n","import { digitsToWordsList } from '@finmid/tbl-webapps/utils';\nimport { Typography } from '@mui/material';\nimport { TFunction } from 'i18next';\nimport { useTranslation } from 'react-i18next';\n\nimport { Alert } from '../Alert';\n\nexport const formatReviewMessage = (\n  invalidFieldsList: string[],\n  t: TFunction<'components', 'errorNotification'>,\n) => {\n  if (invalidFieldsList.length === 0) {\n    return;\n  }\n\n  if (invalidFieldsList.length === 1) {\n    return invalidFieldsList[0];\n  }\n\n  const lastWord = invalidFieldsList.at(-1);\n  const firstPart = invalidFieldsList.slice(0, -1).join(', ');\n  return t('reviewMessage', { firstPart, lastWord });\n};\n\nexport const ErrorInfo = ({ invalidFields }: { invalidFields: string[] }) => {\n  const { t } = useTranslation('components', {\n    keyPrefix: 'errorNotification',\n  });\n\n  if (invalidFields.length === 0) {\n    return null;\n  }\n\n  const baseMessage =\n    invalidFields.length === 1\n      ? t('openErrorSingle')\n      : t('openErrorsMultiple', {\n          number: digitsToWordsList[invalidFields.length],\n        });\n\n  const reviewMessage = formatReviewMessage(invalidFields, t);\n\n  return (\n    <Alert severity=\"warning\">\n      <Typography>\n        {`${baseMessage} `}\n        <span\n          style={{\n            textDecoration: 'underline',\n            fontWeight: 'bold',\n          }}\n        >\n          {reviewMessage}\n        </span>\n      </Typography>\n    </Alert>\n  );\n};\n","import { digitsToWordsList } from '@finmid/tbl-webapps/utils';\nimport { Typography } from '@mui/material';\nimport { ForwardedRef, forwardRef, useEffect, useRef } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { Alert } from '../Alert';\n\nimport { formatReviewMessage } from './ErrorInfo';\n\nconst ErrorInfoInvalidFields = forwardRef(\n  (\n    { invalidFields }: { invalidFields: string[] },\n    ref: ForwardedRef<HTMLDivElement>,\n  ) => {\n    const { t } = useTranslation('components', {\n      keyPrefix: 'errorNotification',\n    });\n\n    if (invalidFields.length === 0) {\n      return null;\n    }\n\n    const baseMessage =\n      invalidFields.length === 1\n        ? t('openErrorSingle')\n        : t('openErrorsMultiple', {\n            number: digitsToWordsList[invalidFields.length],\n          });\n\n    const reviewMessage = formatReviewMessage(invalidFields, t);\n\n    return (\n      <Alert severity=\"warning\" ref={ref}>\n        <Typography>\n          {`${baseMessage} `}\n          <span\n            style={{\n              textDecoration: 'underline',\n              fontWeight: 'bold',\n            }}\n          >\n            {reviewMessage}\n          </span>\n        </Typography>\n      </Alert>\n    );\n  },\n);\n\ntype InvalidFieldsErrorProps = {\n  invalidFields: string[];\n};\n\nexport const InvalidFieldsError = ({\n  invalidFields,\n}: InvalidFieldsErrorProps) => {\n  const ref = useRef<HTMLDivElement>(null);\n  useEffect(() => {\n    ref.current?.scrollIntoView({ behavior: 'smooth' });\n  }, []);\n\n  return <ErrorInfoInvalidFields ref={ref} invalidFields={invalidFields} />;\n};\n","import { useTheme } from '@emotion/react';\nimport { TranslationKey } from '@finmid/tbl-webapps/translations';\nimport { Typography } from '@mui/material';\nimport { ForwardedRef, forwardRef, useEffect, useRef } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { Alert } from '../Alert';\n\n// The gateway decides which of these messages to raise, so the key arrives as a\n// plain string and cannot be checked against the JSON at compile time.\ntype ErrorNotificationKey = TranslationKey<'components', 'errorNotification'>;\n\nconst ErrorInfoInvalidMessages = forwardRef(\n  (\n    { invalidMessages }: { invalidMessages: string[] },\n    ref: ForwardedRef<HTMLDivElement>,\n  ) => {\n    const { t } = useTranslation('components', {\n      keyPrefix: 'errorNotification',\n    });\n    const theme = useTheme();\n\n    if (invalidMessages.length === 0) {\n      return null;\n    }\n\n    return (\n      <div ref={ref} style={{ backgroundColor: theme.palette.gray[50] }}>\n        {invalidMessages.map((message, index) => (\n          <Alert key={index} severity=\"warning\" sx={{ mb: 0.5 }}>\n            <Typography>{t(message as ErrorNotificationKey)}</Typography>\n          </Alert>\n        ))}\n      </div>\n    );\n  },\n);\n\ntype InvalidMessagesErrorProps = {\n  invalidMessages: string[];\n};\n\nexport const InvalidMessagesError = ({\n  invalidMessages,\n}: InvalidMessagesErrorProps) => {\n  const ref = useRef<HTMLDivElement>(null);\n  useEffect(() => {\n    ref.current?.scrollIntoView({ behavior: 'smooth' });\n  }, []);\n\n  return (\n    <ErrorInfoInvalidMessages ref={ref} invalidMessages={invalidMessages} />\n  );\n};\n","import { InvalidMessages } from '@finmid/distributor-types';\n\nimport { InvalidFieldsError } from './InvalidFieldsError';\nimport { InvalidMessagesError } from './InvalidMessagesError';\n\ntype FormErrorInfoProps = {\n  invalidFieldsErrors: {\n    messages?: InvalidMessages;\n    labels?: string[];\n  };\n};\n\nexport const FormErrorInfo = ({ invalidFieldsErrors }: FormErrorInfoProps) => {\n  const { messages, labels } = invalidFieldsErrors ?? {};\n  if (messages?.translationKeys.length) {\n    return <InvalidMessagesError invalidMessages={messages.translationKeys} />;\n  }\n\n  if (messages?.customMessages.length) {\n    return <InvalidMessagesError invalidMessages={messages.customMessages} />;\n  }\n\n  if (labels?.length) {\n    return <InvalidFieldsError invalidFields={labels} />;\n  }\n\n  return null;\n};\n","import { useTheme } from '@emotion/react';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { CloseXIcon } from '@finmid/ui/icons';\nimport { Box } from '@mui/material';\nimport { SnackbarKey } from 'notistack';\nimport { useTranslation } from 'react-i18next';\n\nimport { Button } from '../../Button';\nimport { Typography } from '../../Typography';\n\nexport const ToastAction = (snackbarId: SnackbarKey) => {\n  const { closeSnackbar } = useNotifications();\n  const theme = useTheme();\n  const textColor = theme.palette.yellow[700];\n  const { t } = useTranslation('components', {\n    keyPrefix: 'errorNotification',\n  });\n\n  return (\n    <Box display=\"flex\" alignItems=\"baseline\">\n      <Button\n        variant=\"invisible\"\n        onClick={() => {\n          closeSnackbar(snackbarId);\n        }}\n      >\n        <Typography color={textColor} fontWeight={700}>\n          {t('dismiss')}\n        </Typography>\n        <CloseXIcon\n          style={{\n            fontSize: '0.75rem',\n            marginInlineStart: '1rem',\n            color: textColor,\n          }}\n        />\n      </Button>\n    </Box>\n  );\n};\n","import { useTranslation } from 'react-i18next';\n\nexport const ToastMessage = ({\n  errorMessage,\n  ticket,\n}: {\n  errorMessage: string;\n  ticket?: string;\n}) => {\n  const { t } = useTranslation('components', {\n    keyPrefix: 'errorNotification',\n  });\n  return (\n    <span>\n      {errorMessage}\n      {ticket != null ? (\n        <>\n          <br />\n          {`${t('personalReferenceId')}: ${ticket}`}\n        </>\n      ) : null}\n    </span>\n  );\n};\n","import { ToastAction, ToastMessage } from '../components';\n\ninterface WithCustomErrorProps extends Partial<Error> {\n  message: string;\n  ticketNumber?: string;\n}\n\nexport const withCustomErrorProps = ({\n  message,\n  ticketNumber,\n}: WithCustomErrorProps) => ({\n  action: ToastAction,\n  toastComponent: <ToastMessage errorMessage={message} ticket={ticketNumber} />,\n});\n","import { useTranslation } from 'react-i18next';\n\nimport { ToastAction, ToastMessage } from '../components';\n\ninterface WithUnknownErrorProps extends Partial<Error> {\n  ticketNumber?: string;\n}\n\nconst UnknownErrorToastMessage = ({ ticket }: { ticket?: string }) => {\n  const { t } = useTranslation('components', {\n    keyPrefix: 'errorNotification',\n  });\n  return <ToastMessage errorMessage={t('messageUnknown')} ticket={ticket} />;\n};\n\nexport const withUnknownErrorProps = ({\n  ticketNumber,\n}: WithUnknownErrorProps) => ({\n  action: ToastAction,\n  toastComponent: <UnknownErrorToastMessage ticket={ticketNumber} />,\n});\n","import { withCustomErrorProps } from './withCustomErrorProps';\nimport { withUnknownErrorProps } from './withUnknownErrorProps';\n\ninterface WithErrorProps extends Partial<Error> {\n  message?: string;\n  ticketNumber?: string;\n}\n\nexport const withErrorProps = ({ message, ticketNumber }: WithErrorProps) => {\n  if (message != null) {\n    return withCustomErrorProps({ message, ticketNumber });\n  }\n  return withUnknownErrorProps({ ticketNumber });\n};\n","import { useTranslation } from 'react-i18next';\n\nimport { ToastAction, ToastMessage } from '../components';\n\nconst FetchErrorToastMessage = () => {\n  const { t } = useTranslation('components', {\n    keyPrefix: 'errorNotification',\n  });\n  return <ToastMessage errorMessage={t('messageFetchError')} />;\n};\n\nexport const fetchErrorProps = {\n  action: ToastAction,\n  toastComponent: <FetchErrorToastMessage />,\n  ticketNumber: 'static',\n};\n","import {\n  FeatureKey,\n  defaultFeatures,\n  FeatureScope,\n} from '@finmid/tbl-webapps/utils';\nimport { Indicator, IndicatorVariant } from '@finmid/ui/ocarina';\n\nconst variantMap: Record<FeatureScope, IndicatorVariant> = {\n  live: 'success',\n  staging: 'alert',\n  localhost: 'neutral',\n};\n\nexport const ScopeIndicator = ({ featureKey }: { featureKey: string }) => {\n  if (featureKey in defaultFeatures) {\n    const scope = defaultFeatures[featureKey as FeatureKey].scope;\n    const tooltip =\n      scope !== 'localhost' ? 'Released on ' + scope : 'Unreleased';\n\n    return (\n      <Indicator\n        tooltip={tooltip}\n        tooltipPlacement=\"left\"\n        variant={variantMap[scope]}\n      />\n    );\n  }\n\n  return null;\n};\n","import { Feature, FeatureKey, setFeature } from '@finmid/tbl-webapps/utils';\nimport { Box } from '@mui/material';\n\nimport { SectionContent, Switch, Typography } from '../index';\n\nimport { ScopeIndicator } from './ScopeIndicator';\n\ntype FeatureRowProps = {\n  feature: Feature;\n  featureKey: string;\n  onChange: () => void;\n};\n\nexport const FeatureFlagRow = (props: FeatureRowProps) => {\n  const { feature, featureKey, onChange } = props;\n\n  const handleChange = (checked: boolean) => {\n    setFeature(featureKey as FeatureKey, checked ? 'staging' : 'localhost');\n    onChange();\n  };\n\n  return (\n    <SectionContent disablePadding css={{ marginBottom: 0 }}>\n      <Box\n        display=\"flex\"\n        alignItems=\"flex-start\"\n        justifyContent=\"space-between\"\n        px={2}\n        py={1}\n      >\n        <Box mt={0.5} display=\"flex\" alignItems=\"center\" gap={2}>\n          <ScopeIndicator featureKey={featureKey} />\n          <Typography fontSize={15} fontWeight={500}>\n            {feature.name}\n          </Typography>\n        </Box>\n\n        <Switch\n          size=\"small\"\n          checked={feature.scope !== 'localhost'}\n          onChange={(_, checked) => handleChange(checked)}\n        />\n      </Box>\n    </SectionContent>\n  );\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport {\n  closeFeatureFlagsDialog,\n  useAppDispatch,\n  useFeatureFlagsDialogOpen,\n} from '@finmid/tbl-webapps/store';\nimport { Features, getFeatures } from '@finmid/tbl-webapps/utils';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport { useEffect, useState } from 'react';\n\nimport { Button, Dialog, SectionContainer, Typography } from '../index';\n\nimport { FeatureFlagRow } from './FeatureFlagRow';\n\nexport type FeatureFlagsControlProps = {\n  open: boolean;\n  onClose: () => void;\n};\n\nexport const FeatureFlagsControl = (props: FeatureFlagsControlProps) => {\n  const { open, onClose } = props;\n  const [features, setFeatures] = useState<Features | null>();\n\n  useEffect(() => {\n    setFeatures(getFeatures());\n  }, []);\n\n  const refresh = () => setFeatures(getFeatures());\n\n  if (ENVIRONMENT === 'live') {\n    return null;\n  }\n\n  return (\n    <Dialog\n      onClose={onClose}\n      open={open}\n      actions={<Button onClick={onClose}>Close</Button>}\n      title=\"Feature flags control\"\n    >\n      <Typography color=\"inherit\">\n        Please note: A full page refresh is needed for the feature flags to\n        update.\n      </Typography>\n      <Spacer height={2} />\n\n      <SectionContainer>\n        {features &&\n          Object.entries(features)\n            .filter(([key]) => key !== 'exampleToggle')\n            .map(([key, feature]) => (\n              <FeatureFlagRow\n                feature={feature}\n                featureKey={key}\n                onChange={refresh}\n                key={key}\n              />\n            ))}\n      </SectionContainer>\n    </Dialog>\n  );\n};\n\nexport const GlobalFeatureFlagsControl = () => {\n  const isOpen = useFeatureFlagsDialogOpen();\n  const dispatch = useAppDispatch();\n\n  const onClose = () => dispatch(closeFeatureFlagsDialog());\n\n  return <FeatureFlagsControl open={isOpen} onClose={onClose} />;\n};\n","import { TBLCurrency } from '@finmid/distributor-types';\nimport { currencyIcons } from '@finmid/tbl-webapps/utils';\nimport { Icon } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { Controller, useFormContext } from 'react-hook-form';\n\nimport { FormAutocompleteField, FormTextField } from '../TextField';\nimport { Typography } from '../Typography';\n\nconst OptionDisplayed = ({ option }: { option: TBLCurrency }) => (\n  <Box display=\"flex\" gap={1}>\n    <Icon\n      icon={currencyIcons[option]}\n      style={{ width: '18px', height: '18px' }}\n    />\n    <Typography>{option}</Typography>\n  </Box>\n);\n\nconst StartAdornment = ({ currency }: { currency: TBLCurrency }) => (\n  <Box>\n    <Icon icon={currencyIcons[currency]} size=\"small\" />\n  </Box>\n);\n\ntype FormCurrencySelectorProps = {\n  currencies: TBLCurrency[];\n  name?: string;\n  fullWidth?: boolean;\n};\n\nexport const FormCurrencySelector = ({\n  currencies,\n  name = 'currency',\n  fullWidth = false,\n}: FormCurrencySelectorProps) => {\n  const { control } = useFormContext();\n\n  if (currencies.length > 1) {\n    return (\n      <FormAutocompleteField\n        control={control}\n        name={name}\n        options={currencies}\n        getKey={(option) => option}\n        getValue={(option) => option}\n        getLabel={(option) => option}\n        getStartAdornment={(option) => {\n          if (option != null) {\n            return <StartAdornment currency={option} />;\n          }\n        }}\n        renderOption={(option) => <OptionDisplayed option={option} />}\n        testId=\"multiple-currencies\"\n        fullWidth={fullWidth}\n      />\n    );\n  }\n\n  return (\n    <Controller\n      name={name}\n      control={control}\n      render={({ field: { value } }) => (\n        <FormTextField\n          control={control}\n          name={name}\n          disabled\n          value={value}\n          fullWidth={fullWidth}\n          testId=\"single-currency\"\n          startAdornment={currencyIcons[currencies[0]] ?? ''}\n        />\n      )}\n    />\n  );\n};\n","import styled from '@emotion/styled';\nimport Box from '@mui/material/Box';\n\nexport const FormGrid = styled(Box)(({ theme }) => ({\n  display: 'grid',\n  gridTemplateColumns: '286px auto',\n  gap: theme.spacing(2),\n}));\n","import { useState } from 'react';\n\nimport type { SendFeedbackFormValues } from './sendFeedbackSchema';\n\nexport const feedbackTopics = ['PROBLEM', 'IDEA', 'OTHER'] as const;\n\nexport type FeedbackTopic = (typeof feedbackTopics)[number];\n\n/** What the backend will receive once the endpoint exists. */\nexport type SendFeedbackRequest = SendFeedbackFormValues & {\n  /** The page the user sent it from, for triage. */\n  page: string;\n};\n\n// There is no endpoint yet, so sending only waits as a request would. At the\n// swap, this body calls the gateway mutation and keeps the same signature.\nconst SIMULATED_LATENCY_MS = 600;\n\nexport const useSendFeedback = () => {\n  const [isSending, setIsSending] = useState(false);\n\n  const sendFeedback = async (_request: SendFeedbackRequest) => {\n    setIsSending(true);\n    try {\n      await new Promise((resolve) => setTimeout(resolve, SIMULATED_LATENCY_MS));\n    } finally {\n      setIsSending(false);\n    }\n  };\n\n  return { sendFeedback, isSending };\n};\n","import { zodResolver } from '@hookform/resolvers/zod';\nimport { TFunction } from 'i18next';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { z } from 'zod';\n\nimport { feedbackTopics } from './useSendFeedback';\n\nconst MAX_MESSAGE_LENGTH = 2000;\n\nconst sendFeedbackSchema = (\n  t: TFunction<'components', 'sendFeedback.validation'>,\n) =>\n  z.object({\n    topic: z.enum(feedbackTopics, { error: t('topicRequired') }),\n    message: z\n      .string()\n      .trim()\n      .min(1, t('messageRequired'))\n      .max(\n        MAX_MESSAGE_LENGTH,\n        t('messageTooLong', { max: MAX_MESSAGE_LENGTH }),\n      ),\n  });\n\nexport type SendFeedbackFormValues = z.infer<\n  ReturnType<typeof sendFeedbackSchema>\n>;\n\nexport const useSendFeedbackResolver = () => {\n  const { t } = useTranslation('components', {\n    keyPrefix: 'sendFeedback.validation',\n  });\n\n  return useMemo(() => zodResolver(sendFeedbackSchema(t)), [t]);\n};\n","import styled from '@emotion/styled';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { ElevatedPaper, HelperText, RadioGroup } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport Dialog from '@mui/material/Dialog';\nimport { Controller, useForm } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\nimport { useLocation } from 'react-router-dom';\n\nimport { Button } from '../Button';\nimport { DialogActions, DialogContent, DialogTitle } from '../Dialog';\nimport { FormTextField } from '../TextField';\nimport { Typography } from '../Typography';\n\nimport {\n  SendFeedbackFormValues,\n  useSendFeedbackResolver,\n} from './sendFeedbackSchema';\nimport {\n  FeedbackTopic,\n  feedbackTopics,\n  useSendFeedback,\n} from './useSendFeedback';\n\nconst TopicFieldset = styled.fieldset({\n  border: 0,\n  margin: 0,\n  padding: 0,\n  minWidth: 0,\n});\n\ntype Props = {\n  open: boolean;\n  onClose: () => void;\n};\n\nexport const SendFeedbackDialog = ({ open, onClose }: Props) => {\n  const { t } = useTranslation('components', { keyPrefix: 'sendFeedback' });\n  const { pathname } = useLocation();\n  const { notifySuccess } = useNotifications();\n  const { sendFeedback, isSending } = useSendFeedback();\n\n  const { control, handleSubmit, reset } = useForm<SendFeedbackFormValues>({\n    resolver: useSendFeedbackResolver(),\n    defaultValues: { message: '' },\n  });\n\n  const close = () => {\n    reset();\n    onClose();\n  };\n\n  const submit = handleSubmit(async ({ topic, message }) => {\n    await sendFeedback({ topic, message, page: pathname });\n    notifySuccess(t('success'));\n    close();\n  });\n\n  return (\n    <Dialog\n      open={open}\n      onClose={isSending ? undefined : close}\n      fullWidth\n      PaperProps={{ style: { maxWidth: '480px' }, elevation: 2 }}\n      PaperComponent={ElevatedPaper}\n    >\n      <DialogTitle>{t('title')}</DialogTitle>\n      <form onSubmit={submit} noValidate data-test-id=\"send-feedback-form\">\n        <DialogContent>\n          <Typography\n            fontSize={15}\n            fontWeight={400}\n            lineHeight=\"20px\"\n            color=\"gray.500\"\n          >\n            {t('subtitle')}\n          </Typography>\n\n          <Box mt={4} display=\"flex\" flexDirection=\"column\" gap={3}>\n            <Controller\n              control={control}\n              name=\"topic\"\n              render={({ field, fieldState }) => (\n                <TopicFieldset>\n                  <Typography component=\"legend\" fontWeight={500} mb={1} p={0}>\n                    {t('topic.label')}\n                  </Typography>\n                  <RadioGroup<FeedbackTopic>\n                    name={field.name}\n                    defaultValue={field.value}\n                    onChange={field.onChange}\n                    options={feedbackTopics.map((topic) => ({\n                      value: topic,\n                      label: t(`topic.${topic}`),\n                      testId: `feedback-topic-${topic}`,\n                    }))}\n                  />\n                  {fieldState.error !== undefined && (\n                    <HelperText>{fieldState.error.message}</HelperText>\n                  )}\n                </TopicFieldset>\n              )}\n            />\n            <FormTextField\n              control={control}\n              name=\"message\"\n              label={t('message.label')}\n              placeholder={t('message.placeholder')}\n              rows={5}\n              fullWidth\n              testId=\"feedback-message\"\n            />\n          </Box>\n        </DialogContent>\n        <DialogActions>\n          <Button\n            variant=\"primary\"\n            type=\"submit\"\n            disabled={isSending}\n            testId=\"send-feedback-submit\"\n          >\n            {t('submit')}\n          </Button>\n          <Button onClick={close} disabled={isSending} variant=\"invisible\">\n            {t('cancel')}\n          </Button>\n        </DialogActions>\n      </form>\n    </Dialog>\n  );\n};\n","import { SVGProps } from 'react';\nexport const FeedbackIcon = (props: SVGProps<SVGSVGElement>) => (\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    width=\"100%\"\n    height=\"100%\"\n    viewBox=\"0 0 16 16\"\n    fill=\"none\"\n    {...props}\n  >\n    <path\n      stroke=\"currentColor\"\n      strokeWidth={1.1}\n      strokeLinejoin=\"round\"\n      d=\"M3.5 2.75h9a1.75 1.75 0 0 1 1.75 1.75V10a1.75 1.75 0 0 1-1.75 1.75H7.6l-2.85 2.3a.4.4 0 0 1-.65-.31v-1.99H3.5A1.75 1.75 0 0 1 1.75 10V4.5A1.75 1.75 0 0 1 3.5 2.75Z\"\n    />\n    <path\n      stroke=\"currentColor\"\n      strokeWidth={1.1}\n      strokeLinecap=\"round\"\n      d=\"M5 6h6M5 8.5h3.5\"\n    />\n  </svg>\n);\n","import { SVGProps } from 'react';\nexport const LogoutIcon = (props: SVGProps<SVGSVGElement>) => (\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    width=\"100%\"\n    height=\"100%\"\n    viewBox=\"0 0 16 16\"\n    fill=\"none\"\n    {...props}\n  >\n    <path\n      fill=\"currentColor\"\n      d=\"M3.333 3.867h4.334a.533.533 0 0 0 0-1.067H3.333a1.2 1.2 0 0 0-1.2 1.2v8a1.2 1.2 0 0 0 1.2 1.2h4.334a.533.533 0 1 0 0-1.067H3.333A.133.133 0 0 1 3.2 12V4c0-.074.06-.133.133-.133Z\"\n    />\n    <path\n      fill=\"currentColor\"\n      d=\"M5.467 7.333a.533.533 0 0 1 1.066 0v.134h5.513L9.623 5.044a.533.533 0 0 1 .754-.754L14.087 8l-3.71 3.71a.533.533 0 1 1-.754-.754l2.423-2.423H6.533v.134a.533.533 0 0 1-1.066 0V7.333Z\"\n    />\n  </svg>\n);\n","import { Drawer, DrawerProps } from '@mui/material';\nimport { styled } from '@mui/material/styles';\n\nconst drawerWidth = '268px';\n\nconst StyledSidebarContainer = styled(Drawer)`\n  width: ${drawerWidth};\n  flex-shrink: 0;\n  white-space: nowrap;\n  box-sizing: border-box;\n\n  & .MuiPaper-root {\n    padding-bottom: ${({ theme }) => theme.spacing(3)};\n    padding-left: 2px;\n    display: flex;\n    flex-direction: column;\n    justify-content: space-between;\n  }\n\n  & .MuiDrawer-paper {\n    width: ${drawerWidth};\n    overflow-x: hidden;\n  }\n`;\n\nexport const SidebarContainer = ({\n  variant = 'permanent',\n  ...props\n}: DrawerProps) => <StyledSidebarContainer variant={variant} {...props} />;\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport ListItemButton, {\n  ListItemButtonProps,\n} from '@mui/material/ListItemButton';\nimport ListItemText from '@mui/material/ListItemText';\n\nconst shouldForwardProp = (prop: string) => {\n  const innerProps = ['isToggler', 'isActive', 'isSubroute'];\n  return !innerProps.includes(prop);\n};\n\ntype StyledListItemButtonProps = ListItemButtonProps & {\n  isToggler?: boolean;\n  isActive?: boolean;\n  isSubroute?: boolean;\n};\n\nexport const StyledListItemButton = styled(ListItemButton, {\n  shouldForwardProp,\n})<StyledListItemButtonProps>`\n  ${({ theme, isToggler, isActive, isSubroute }) => css`\n    margin-block: ${isSubroute ? 0 : theme.spacing(1)};\n    padding-block: ${theme.spacing(1)};\n    margin-inline: ${theme.spacing(2)};\n    padding-inline: ${theme.spacing(1)};\n    margin-bottom: ${isToggler || isSubroute ? 0 : theme.spacing(1)};\n    line-height: 24px;\n    color: inherit;\n\n    display: grid;\n    grid-template-columns: 24px 1fr auto;\n    border-radius: 8px;\n\n    align-content: center;\n    transition: opacity 0.5s;\n\n    &:hover {\n      background-color: ${theme.palette.gray[50]};\n      & .arrow-icon {\n        opacity: 1;\n        color: ${isActive ? theme.palette.gray[900] : theme.palette.gray[400]};\n      }\n    }\n\n    & .arrow-icon {\n      opacity: ${isActive ? 1 : 0};\n      color: ${theme.palette.gray[900]};\n    }\n\n    &.Mui-disabled {\n      opacity: 1;\n      & .MuiListItemIcon-root,\n      & .MuiListItemText-root {\n        color: ${theme.palette.gray[400]};\n      }\n    }\n  `}\n`;\n\nexport const StyledListItemText = styled(ListItemText)`\n  ${({ theme }) => css`\n    margin-left: ${theme.spacing(1)};\n    line-height: 16px;\n    &.MuiListItemText-inset {\n      padding-left: ${theme.spacing(0)};\n    }\n  `}\n`;\n","type MenuItemCommonProps = {\n  label: string;\n  disabled?: boolean;\n  Icon?: JSX.Element;\n  comingSoon?: boolean;\n  isSubroute?: boolean;\n  noDivider?: boolean;\n  testId?: string;\n  IndicatorRight?: JSX.Element | null;\n};\n\nexport type MenuItemActionProps = MenuItemCommonProps & {\n  handleClick: () => void;\n};\n\nexport type MenuItemInternalNavProps = MenuItemCommonProps & {\n  route: string;\n};\n\nexport type MenuItemExternalNavProps = MenuItemCommonProps & {\n  to: string;\n};\n\nexport type MenuItemToggleProps = MenuItemCommonProps & {\n  routes: (\n    | MenuItemInternalNavProps\n    | MenuItemExternalNavProps\n    | MenuItemActionProps\n  )[];\n};\n\nexport type MenuItemTypeProps =\n  | MenuItemInternalNavProps\n  | MenuItemExternalNavProps\n  | MenuItemActionProps\n  | MenuItemToggleProps;\n\n// Type Guards\nexport function isMenuItemToggle(\n  menuItemProps: MenuItemTypeProps,\n): menuItemProps is MenuItemToggleProps {\n  return 'routes' in menuItemProps && Array.isArray(menuItemProps.routes);\n}\n\nexport function isMenuItemExternalNav(\n  menuItemProps: MenuItemTypeProps,\n): menuItemProps is MenuItemExternalNavProps {\n  return 'to' in menuItemProps;\n}\n\nexport function isMenuItemInternalNav(\n  menuItemProps: MenuItemTypeProps,\n): menuItemProps is MenuItemInternalNavProps {\n  return 'route' in menuItemProps;\n}\n\nexport function isMenuItemAction(\n  menuItemProps: MenuItemTypeProps,\n): menuItemProps is MenuItemActionProps {\n  return 'handleClick' in menuItemProps;\n}\n","import styled from '@emotion/styled';\nimport { MenuItem, MenuSection } from '@finmid/ui/ocarina';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useMatchTabToRoute } from '../DashboardLayout/useMatchTabToRoute';\nimport {\n  MenuItemTypeProps,\n  isMenuItemAction,\n  isMenuItemExternalNav,\n  isMenuItemInternalNav,\n  isMenuItemToggle,\n} from '../Sidebar';\n\nconst NavigationItem = styled(MenuItem)({\n  '&[aria-current=\"page\"] > div': { fontWeight: 600 },\n});\n\ntype Props = {\n  menuItems: MenuItemTypeProps[];\n};\n\n/** The header tabs as a menu section, for screens too narrow to show them. */\nexport const NavigationSection = ({ menuItems }: Props) => {\n  const navigate = useNavigate();\n\n  const clickHandlerFor = (item: MenuItemTypeProps) => {\n    if (isMenuItemInternalNav(item)) return () => navigate(item.route);\n    if (isMenuItemAction(item)) return item.handleClick;\n    return undefined;\n  };\n\n  const items = menuItems.flatMap((item) =>\n    isMenuItemToggle(item) ? item.routes : [item],\n  );\n  const currentRoute = useMatchTabToRoute(\n    items.filter(isMenuItemInternalNav).map(({ route }) => `${route}/*`),\n  );\n\n  return (\n    <MenuSection>\n      {items.map((item) => (\n        <NavigationItem\n          key={item.label}\n          disabled={item.disabled}\n          aria-current={\n            isMenuItemInternalNav(item) && item.route === currentRoute\n              ? 'page'\n              : undefined\n          }\n          href={isMenuItemExternalNav(item) ? item.to : undefined}\n          onClick={clickHandlerFor(item)}\n          data-test-id={item.testId}\n        >\n          {item.label}\n        </NavigationItem>\n      ))}\n    </MenuSection>\n  );\n};\n","import { SVGProps } from 'react';\nexport const TeamIcon = (props: SVGProps<SVGSVGElement>) => (\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    width=\"100%\"\n    height=\"100%\"\n    viewBox=\"0 0 16 16\"\n    fill=\"none\"\n    {...props}\n  >\n    <path\n      fill=\"currentColor\"\n      fillRule=\"evenodd\"\n      d=\"M12.333 4.333a3 3 0 1 1-6 0 3 3 0 0 1 6 0Zm-1.066 0a1.933 1.933 0 1 1-3.867 0 1.933 1.933 0 0 1 3.867 0ZM4 4.667c.525 0 1.002.202 1.359.532.116.535.337 1.03.641 1.465v.003a2 2 0 1 1-2-2ZM4 7.6a.933.933 0 1 0 0-1.867A.933.933 0 0 0 4 7.6ZM5.6 9.2a1.087 1.087 0 0 0-.933 1.077c0 1.45.864 2.76 2.197 3.331l.631.27a4.667 4.667 0 0 0 3.677 0l.631-.27A3.625 3.625 0 0 0 14 10.276c0-.54-.398-1-.934-1.076l-2.978-.426a5.333 5.333 0 0 0-1.509 0L5.6 9.2Zm5.151 3.698.632-.27a2.558 2.558 0 0 0 1.55-2.359.021.021 0 0 0-.005-.006.026.026 0 0 0-.006-.005.02.02 0 0 0-.007-.002L9.938 9.83a4.267 4.267 0 0 0-1.207 0l-2.979.426a.02.02 0 0 0-.007.002.025.025 0 0 0-.01.011 2.558 2.558 0 0 0 1.55 2.358l.631.271a3.6 3.6 0 0 0 2.836 0Z\"\n      clipRule=\"evenodd\"\n    />\n    <path\n      fill=\"currentColor\"\n      d=\"m2.835 9.802.248-.037c.282-.041.517.227.517.511a.554.554 0 0 1-.457.559l-.075.011c.026.76.443 1.447 1.095 1.824a.66.66 0 0 1 .221.203c.098.147.203.288.317.423.264.314.05.815-.326.649l-.439-.196A3.26 3.26 0 0 1 2 10.77c0-.484.355-.896.835-.967Z\"\n    />\n  </svg>\n);\n","import { KebabMenuItem } from '@finmid/distributor-types';\nimport { useFeatureFlags } from '@finmid/tbl-webapps/hooks';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { BurgerIcon } from '@finmid/ui/icons';\nimport {\n  Dropdown,\n  Icon,\n  Menu,\n  MenuIconButton,\n  MenuItem,\n  MenuSection,\n  MoreVerticalIcon,\n  SettingsIcon,\n} from '@finmid/ui/ocarina';\nimport { Theme, useMediaQuery } from '@mui/material';\nimport posthog from 'posthog-js';\nimport { FunctionComponent, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { SendFeedbackDialog } from '../SendFeedback';\nimport { MenuItemTypeProps } from '../Sidebar';\n\nimport { FeedbackIcon } from './FeedbackIcon';\nimport { LogoutIcon } from './LogoutIcon';\nimport { NavigationSection } from './NavigationSection';\nimport { TeamIcon } from './TeamIcon';\n\ninterface Props {\n  kebabMenuSections: KebabMenuItem[][];\n  /** The header tabs, listed at the top of the menu on phones, which hide them. */\n  menuItems?: MenuItemTypeProps[];\n}\n\nexport const HeaderMenu: FunctionComponent<Props> = ({\n  kebabMenuSections,\n  menuItems = [],\n}) => {\n  const navigate = useNavigate();\n  const { capitalFeedbackAndUploads } = useFeatureFlags();\n  const { t } = useTranslation('sidebar');\n  const { t: navigationLabel } = useTranslation('navigation', {\n    keyPrefix: 'header',\n  });\n  const isPhone = useMediaQuery((theme: Theme) =>\n    theme.breakpoints.down('tablet'),\n  );\n  const showsNavigation = isPhone && menuItems.length > 0;\n  const [isFeedbackOpen, setIsFeedbackOpen] = useState(false);\n\n  const logout = () => navigate(sharedRoutes.logout);\n  const goToMembers = () => navigate(sharedRoutes.platform);\n  const goToSettings = () => navigate(sharedRoutes.settings);\n\n  const [firstSection, secondSection, thirdSection] = kebabMenuSections;\n\n  return (\n    <>\n      <Dropdown>\n        <MenuIconButton\n          icon={\n            showsNavigation ? (\n              <BurgerIcon sx={{ fontSize: 16 }} />\n            ) : (\n              <MoreVerticalIcon />\n            )\n          }\n          aria-label={showsNavigation ? navigationLabel('openMenu') : undefined}\n          data-test-id=\"header-menu-button\"\n        />\n        <Menu placement=\"bottom-end\">\n          {showsNavigation && <NavigationSection menuItems={menuItems} />}\n          <MenuSection>\n            <MenuItem onClick={goToMembers}>\n              <Icon size=\"small\" icon={<TeamIcon />} />\n              {t('members')}\n            </MenuItem>\n            {capitalFeedbackAndUploads && (\n              <MenuItem\n                onClick={() => setIsFeedbackOpen(true)}\n                data-test-id=\"send-feedback-button\"\n              >\n                <Icon size=\"small\" icon={<FeedbackIcon />} />\n                {t('sendFeedback')}\n              </MenuItem>\n            )}\n            {firstSection.map(({ icon, label, ...menuItemProps }, index) => (\n              <MenuItem key={index} {...menuItemProps}>\n                <Icon size=\"small\" icon={icon} />\n                {label}\n              </MenuItem>\n            ))}\n          </MenuSection>\n          {secondSection.length > 0 && (\n            <MenuSection>\n              {secondSection.map(({ icon, label, ...menuItemProps }, index) => (\n                <MenuItem key={index} {...menuItemProps}>\n                  <Icon size=\"small\" icon={icon} />\n                  {label}\n                </MenuItem>\n              ))}\n            </MenuSection>\n          )}\n          <MenuSection>\n            {thirdSection.map(({ icon, label, ...menuItemProps }, index) => (\n              <MenuItem key={index} {...menuItemProps}>\n                <Icon size=\"small\" icon={icon} />\n                {label}\n              </MenuItem>\n            ))}\n\n            <MenuItem\n              onClick={() => {\n                goToSettings();\n                posthog.capture('clicked_menu_item_settings');\n              }}\n              data-test-id=\"settings-button\"\n            >\n              <Icon size=\"small\" icon={<SettingsIcon />} />\n              Settings\n            </MenuItem>\n\n            <MenuItem onClick={logout} data-test-id=\"logout-button\">\n              <Icon size=\"small\" icon={<LogoutIcon />} />\n              {t('logout')}\n            </MenuItem>\n          </MenuSection>\n        </Menu>\n      </Dropdown>\n      {capitalFeedbackAndUploads && (\n        <SendFeedbackDialog\n          open={isFeedbackOpen}\n          onClose={() => setIsFeedbackOpen(false)}\n        />\n      )}\n    </>\n  );\n};\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\n\nimport { Typography } from '../Typography';\n\nexport const DetailLabel = styled(Typography)`\n  ${({ theme }) => css`\n    color: ${theme.palette.gray[500]};\n    font-size: 14px;\n  `}\n`;\n","import styled from '@emotion/styled';\nimport Box from '@mui/material/Box';\n\nexport const LabelBox = styled(Box)`\n  min-width: 260px;\n  display: flex;\n  flex-direction: column;\n  align-items: flex-start;\n  justify-content: flex-start;\n  gap: 16px;\n`;\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { CSSProperties, PropsWithChildren } from 'react';\n\nimport { Typography } from '../Typography';\n\nconst StyledSectionLabel = styled(Typography)`\n  ${({ theme }) => css`\n    font-weight: 600;\n    font-size: 16px;\n    line-height: 24px;\n    border-bottom: 1px solid ${theme.palette.gray[100]};\n    padding-bottom: ${theme.spacing(1)};\n    margin-bottom: ${theme.spacing(2)};\n    margin-top: ${theme.spacing(6)};\n  `}\n`;\n\ntype SectionLabelProps = PropsWithChildren<{\n  testId?: string;\n  style?: CSSProperties;\n}>;\n\nexport const SectionLabel = ({ children, testId }: SectionLabelProps) => {\n  return (\n    <StyledSectionLabel data-test-id={testId}>{children}</StyledSectionLabel>\n  );\n};\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { EditIcon } from '@finmid/ui/icons';\nimport Box from '@mui/material/Box';\nimport { SxProps } from '@mui/material/styles';\n\nimport { Button } from '../Button';\nimport { Typography } from '../Typography';\n\nconst StyledBox = styled(Box)`\n  ${({ theme }) => css`\n    font-weight: 600;\n    font-size: 16px;\n    line-height: 24px;\n    border-bottom: 1px solid ${theme.palette.gray[100]};\n    margin-bottom: ${theme.spacing(2)};\n    margin-top: ${theme.spacing(6)};\n  `}\n`;\n\ntype SectionLabelWithButtonProps = {\n  btnLabel: string;\n  label: string;\n  sx?: SxProps;\n  handleClick?: () => void;\n};\n\nexport const SectionLabelWithButton = ({\n  btnLabel,\n  label,\n  sx,\n  handleClick,\n}: SectionLabelWithButtonProps) => {\n  return (\n    <StyledBox\n      display=\"flex\"\n      justifyContent=\"space-between\"\n      alignItems=\"center\"\n      sx={sx}\n    >\n      <Typography fontSize={16} fontWeight={600} lineHeight=\"24px\">\n        {label}\n      </Typography>\n      <Button\n        variant=\"invisible\"\n        prefixIcon={<EditIcon style={{ fill: 'white' }} />}\n        onClick={() => handleClick?.()}\n      >\n        {btnLabel}\n      </Button>\n    </StyledBox>\n  );\n};\n","import { Loader, Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\n\nimport { Button } from '../Button';\nimport { Typography } from '../Typography';\n\nexport const LazyLoadFallback = () => {\n  const { t, ready } = useTranslation('components', {\n    keyPrefix: 'errorBoundary',\n  });\n\n  const handleReload = () => {\n    window.location.reload();\n  };\n\n  return (\n    <Box\n      display=\"flex\"\n      flexDirection=\"column\"\n      alignItems=\"center\"\n      justifyContent=\"center\"\n      textAlign=\"center\"\n      my={8}\n    >\n      {!ready && <Loader />}\n\n      {ready && (\n        <>\n          <Typography>{t('reloadTitle')}</Typography>\n          <Typography color=\"gray.300\">{t('reloadSubtitle')}</Typography>\n          <Spacer height={2} />\n          <Button onClick={handleReload} variant=\"accent\">\n            {t('reloadBtn')}\n          </Button>\n        </>\n      )}\n    </Box>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Link, LinkProps } from 'react-router-dom';\n\nexport const UnstyledLink = styled(Link)<LinkProps>`\n  text-decoration: none;\n  color: inherit;\n\n  &:hover,\n  &:active,\n  &:visited,\n  &:focus,\n  &:link {\n    text-decoration: none;\n    color: inherit;\n  }\n`;\n","import styled from '@emotion/styled';\nimport { NavLinkProps, NavLink } from 'react-router-dom';\n\nexport const StyledNavLink = styled(NavLink)<NavLinkProps>`\n  text-decoration: none;\n  color: inherit;\n\n  &:hover,\n  &:active,\n  &:visited,\n  &:focus,\n  &:link {\n    text-decoration: none;\n    color: inherit;\n  }\n`;\n","import {\n  BuyerStatus,\n  GetBuyerStats_GatewayResponse,\n} from '@finmid/distributor-types';\nimport { SelectOutlinedOpenIcon } from '@finmid/ui/icons';\nimport { Dropdown, Menu, MenuButton, MenuItem } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\n\nimport { Typography } from '../Typography';\n\ntype Status = BuyerStatus | 'ALL';\n\nconst statuses: Record<Status, Lowercase<Status>> = {\n  ALL: 'all',\n  ACTIVE: 'active',\n  PENDING: 'pending',\n  PENDING_REACTIVATION: 'pending_reactivation',\n  REJECTED: 'rejected',\n  SUSPENDED: 'suspended',\n  INACTIVE: 'inactive',\n};\n\nexport type BuyerStatusUpdatedFilters = {\n  firstPosition: 1;\n  'server.cursor': undefined;\n  'server.status'?: BuyerStatus;\n};\n\ntype BuyerStatusSelectorProps = {\n  selectedStatus: BuyerStatus | 'ALL';\n  onChange: (updatedFilters: BuyerStatusUpdatedFilters) => void;\n  stats?: GetBuyerStats_GatewayResponse;\n};\n\nexport const BuyerStatusSelector = ({\n  selectedStatus,\n  onChange,\n  stats,\n}: BuyerStatusSelectorProps) => {\n  const { t } = useTranslation('components', {\n    keyPrefix: 'smeStatus',\n  });\n\n  const handleChange = async (status: Status) => {\n    const updatedStatus = status === 'ALL' ? undefined : status;\n    const updatedFilters = {\n      firstPosition: 1,\n      'server.cursor': undefined,\n      'server.status': updatedStatus,\n    };\n    onChange(updatedFilters as BuyerStatusUpdatedFilters);\n  };\n\n  return (\n    <Dropdown>\n      <MenuButton\n        variant=\"invisible\"\n        suffixIcon={\n          <SelectOutlinedOpenIcon\n            sx={{ fontSize: '1rem', transform: 'rotate(180deg)' }}\n          />\n        }\n      >\n        {selectedStatus === 'ALL'\n          ? t('viewAllStatuses')\n          : t('viewButton', {\n              selectedStatus: t(statuses[selectedStatus]).toLowerCase(),\n            })}\n      </MenuButton>\n      <Menu placement=\"bottom-end\">\n        {Object.entries(statuses).map(([value, statusKey]) => (\n          <MenuItem key={value} onClick={() => handleChange(value as Status)}>\n            <Box display=\"flex\" width=\"100%\" justifyContent=\"space-between\">\n              <Typography>{t(statusKey)}</Typography>\n              <Typography>{stats?.[value as Status] ?? '-'}</Typography>\n            </Box>\n          </MenuItem>\n        ))}\n      </Menu>\n    </Dropdown>\n  );\n};\n","import { SearchIcon } from '@finmid/ui/icons';\nimport InputAdornment from '@mui/material/InputAdornment';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { FormContainer, TextField } from '../index';\n\ntype SearchInputUpdatedFilters = {\n  firstPosition: 1;\n  'server.cursor': undefined;\n  'server.search': string;\n};\n\ntype SearchInputProps = {\n  searchValue?: string;\n  handleUpdateFilters: (filters: SearchInputUpdatedFilters) => void;\n};\n\nexport const useSearchInputFilter = ({\n  handleUpdateFilters,\n  searchValue,\n}: SearchInputProps) => {\n  const [value, setValue] = useState(searchValue);\n\n  const handleChange = (searchTerm: string) => {\n    setValue(searchTerm);\n    const updatedFilters: SearchInputUpdatedFilters = {\n      firstPosition: 1,\n      'server.cursor': undefined,\n      'server.search': searchTerm,\n    };\n    handleUpdateFilters(updatedFilters);\n  };\n\n  return {\n    handleChange,\n    value,\n  };\n};\n\nexport const SearchInputFilter = ({\n  searchValue,\n  handleUpdateFilters,\n}: SearchInputProps) => {\n  const { t } = useTranslation('components');\n\n  const { handleChange, value } = useSearchInputFilter({\n    searchValue,\n    handleUpdateFilters,\n  });\n\n  return (\n    <FormContainer>\n      <TextField\n        value={value}\n        label={t('textField.search')}\n        onChange={(e) => handleChange(e.target.value)}\n        fullWidth\n        InputProps={{\n          endAdornment: (\n            <InputAdornment position=\"end\">\n              <SearchIcon />\n            </InputAdornment>\n          ),\n        }}\n      />\n    </FormContainer>\n  );\n};\n","import {\n  GetSellerStats_GatewayResponse,\n  SellerStatus,\n} from '@finmid/distributor-types';\nimport { SelectOutlinedOpenIcon } from '@finmid/ui/icons';\nimport { Dropdown, Menu, MenuButton, MenuItem } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\n\nimport { Typography } from '../Typography';\n\ntype Status = SellerStatus | 'ALL';\n\nconst statuses: Record<Status, Lowercase<Status>> = {\n  ALL: 'all',\n  ACTIVE: 'active',\n  PENDING: 'pending',\n  REJECTED: 'rejected',\n  SUSPENDED: 'suspended',\n  INACTIVE: 'inactive',\n};\n\nexport type SellerStatusUpdatedFilters = {\n  firstPosition: 1;\n  'server.cursor': undefined;\n  'server.status'?: SellerStatus;\n};\n\ntype SellerStatusSelectorProps = {\n  selectedStatus: SellerStatus | 'ALL';\n  onChange: (updatedFilters: SellerStatusUpdatedFilters) => void;\n  stats?: GetSellerStats_GatewayResponse;\n};\n\nexport const SellerStatusSelector = ({\n  selectedStatus,\n  onChange,\n  stats,\n}: SellerStatusSelectorProps) => {\n  const { t } = useTranslation('components', {\n    keyPrefix: 'smeStatus',\n  });\n\n  const handleChange = async (status: Status) => {\n    const updatedStatus = status === 'ALL' ? undefined : status;\n    const updatedFilters = {\n      firstPosition: 1,\n      'server.cursor': undefined,\n      'server.status': updatedStatus,\n    };\n    onChange(updatedFilters as SellerStatusUpdatedFilters);\n  };\n\n  return (\n    <Dropdown>\n      <MenuButton\n        variant=\"invisible\"\n        suffixIcon={\n          <SelectOutlinedOpenIcon\n            sx={{ fontSize: '1rem', transform: 'rotate(180deg)' }}\n          />\n        }\n      >\n        {selectedStatus === 'ALL'\n          ? t('viewAllStatuses')\n          : t('viewButton', {\n              selectedStatus: t(statuses[selectedStatus]).toLowerCase(),\n            })}\n      </MenuButton>\n      <Menu placement=\"bottom-end\">\n        {Object.entries(statuses).map(([value, statusKey]) => (\n          <MenuItem key={value} onClick={() => handleChange(value as Status)}>\n            <Box display=\"flex\" width=\"100%\" justifyContent=\"space-between\">\n              <Typography>{t(statusKey)}</Typography>\n              <Typography>{stats?.[value as Status] ?? '-'}</Typography>\n            </Box>\n          </MenuItem>\n        ))}\n      </Menu>\n    </Dropdown>\n  );\n};\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { Box, Typography } from '@mui/material';\n\n// TODO extract (shared)\nconst StyledListItem = styled.li`\n  ${({ theme }) => css`\n    &.MuiAutocomplete-option,\n    &.MuiAutocomplete-option[aria-selected='true'],\n    &.MuiAutocomplete-option:hover {\n      background-color: white !important;\n      padding-inline: 8px;\n    }\n\n    &.MuiAutocomplete-option:hover,\n    &.Mui-focused,\n    &.Mui-focusVisible {\n      & div {\n        background-color: ${theme.palette.primary[50]} !important;\n        border-radius: 8px;\n      }\n    }\n  `}\n`;\n\ntype PaymentRequestCurrencyOptionProps = {\n  option: string;\n};\n\nexport const MultipleCurrenciesOption = ({\n  option,\n  ...props\n}: PaymentRequestCurrencyOptionProps) => (\n  <StyledListItem data-value={option} {...props}>\n    <Box\n      display=\"flex\"\n      justifyContent=\"space-between\"\n      alignItems=\"center\"\n      width=\"100%\"\n      px={2}\n      py={1}\n    >\n      <Box color=\"gray.500\">\n        <Typography>{option}</Typography>\n      </Box>\n    </Box>\n  </StyledListItem>\n);\n","import styled from '@emotion/styled';\n\nconst HiddenInput = styled.input`\n  display: none;\n`;\n\nexport const NoFormAutofill = () => {\n  return (\n    <>\n      <HiddenInput name=\"name\" />\n      <HiddenInput name=\"password\" />\n      <HiddenInput name=\"address\" />\n    </>\n  );\n};\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport Box from '@mui/material/Box';\n\nexport const PageHeader = styled(Box)`\n  ${({ theme }) => css`\n    display: grid;\n    grid-template-columns: auto auto;\n    grid-template-rows: auto;\n    grid-template-areas:\n      'breadcrumbs breadcrumbs'\n      'title actions';\n    padding-bottom: ${theme.spacing(3)};\n    margin-bottom: ${theme.spacing(3)};\n    border-bottom: 1px solid ${theme.palette.gray[100]};\n  `}\n`;\n\nexport const PageHeaderTitle = styled(Box)`\n  grid-area: title;\n  justify-content: start;\n  align-items: center;\n`;\n\nexport const PageHeaderActions = styled(Box)`\n  ${({ theme }) => css`\n    display: flex;\n    flex-direction: row;\n    justify-content: flex-end;\n    gap: ${theme.spacing(2)};\n    align-items: center;\n    grid-area: actions;\n  `}\n`;\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport MuiPaper from '@mui/material/Paper';\n\nimport { innerPagePaddingY } from '../constants';\n\nexport const Paper = styled(MuiPaper)`\n  ${({ theme }) => css`\n    background-color: white;\n    box-shadow: ${theme.customShadows.buttonNormal};\n    border-radius: ${theme.spacing(1)};\n    padding: ${theme.spacing(4)};\n\n    &.MuiPaper-rounded {\n      border-radius: ${theme.spacing(1)};\n    }\n  `}\n`;\n\nexport const PaperOutlined = styled(Paper)`\n  ${({ theme }) => css`\n    background-color: ${theme.palette.gray[50]};\n    box-shadow: none;\n    border: 1px solid ${theme.palette.gray[100]};\n  `}\n`;\n\nexport const PaperPage = styled(Paper)`\n  display: flex;\n  flex-direction: column;\n  height: ${`calc(100vh - ${innerPagePaddingY}px)`};\n`;\n","import {\n  Box,\n  Divider,\n  Menu,\n  MenuItem,\n  MenuProps,\n  PopoverOrigin,\n  styled,\n} from '@mui/material';\nimport React from 'react';\n\nimport { Typography } from '../Typography';\n\nexport type PopupMenuItem = {\n  title: string;\n  subtitle?: string;\n  itemTestId?: string;\n  onClick?: React.MouseEventHandler<HTMLElement>;\n  icon?: JSX.Element;\n  href?: string;\n  isActive?: boolean;\n};\n\ntype PopupMenuProps = {\n  anchorElement: HTMLButtonElement | null;\n  onClose: (\n    event: unknown,\n    reason: 'backdropClick' | 'escapeKeyDown',\n  ) => void | undefined;\n  menuItems: PopupMenuItem[];\n  testId?: string;\n  anchorOrigin?: PopoverOrigin;\n  transformOrigin?: PopoverOrigin;\n};\n\nconst StyledMenu = styled((props: MenuProps) => <Menu {...props} />)(\n  ({ theme }) => ({\n    '& .MuiPaper-root': {\n      borderRadius: 8,\n      borderWidth: 1,\n      borderColor: theme.palette.grey[200],\n      borderStyle: 'solid',\n      marginTop: theme.spacing(1),\n      minWidth: 224,\n      maxWidth: 280,\n      boxShadow: theme.customShadows.objectHard,\n      '& .MuiMenu-list': {\n        padding: theme.spacing(1),\n      },\n      '& .MuiMenuItem-root': {\n        '& .MuiSvgIcon-root': {\n          fontSize: 16,\n          color: theme.palette.grey[500],\n        },\n        padding: `${theme.spacing(1.5)} ${theme.spacing(2)}`,\n        justifyContent: 'space-between',\n        alignItems: 'flex-start',\n        borderRadius: 6,\n        '& p, span': {\n          fontSize: 12,\n        },\n        '& span': {\n          color: theme.palette.gray[500],\n          display: 'block',\n        },\n      },\n      '& .MuiMenuItem-root.MuiButtonBase-root:hover, .MuiMenuItem-root.Mui-focusVisible':\n        {\n          backgroundColor: theme.palette.primary[50],\n          '& p, span': {\n            color: theme.palette.primary[700],\n          },\n          '& .MuiSvgIcon-root': {\n            color: theme.palette.primary[700],\n          },\n        },\n    },\n  }),\n);\n\nexport const PopupMenu = ({\n  anchorElement,\n  onClose,\n  menuItems,\n  testId,\n  anchorOrigin = {\n    vertical: 'bottom',\n    horizontal: 'right',\n  },\n  transformOrigin = {\n    vertical: 'top',\n    horizontal: 'right',\n  },\n}: PopupMenuProps) => {\n  return (\n    <StyledMenu\n      anchorEl={anchorElement}\n      keepMounted\n      open={anchorElement != null}\n      onClose={onClose}\n      anchorOrigin={anchorOrigin}\n      transformOrigin={transformOrigin}\n      data-test-id={testId}\n    >\n      {menuItems.map(\n        (\n          {\n            title,\n            subtitle,\n            itemTestId,\n            onClick,\n            icon,\n            href,\n            isActive,\n          }: PopupMenuItem,\n          index,\n        ) => [\n          <MenuItem\n            key={title}\n            data-test-id={itemTestId}\n            onClick={onClick}\n            component={href ? 'a' : 'li'}\n            href={href}\n            target={href ? '_blank' : undefined}\n            rel={href ? 'noopener' : undefined}\n            selected={isActive}\n          >\n            <Box mr={4}>\n              <Typography fontWeight={600}>{title}</Typography>\n              {subtitle ? (\n                <>\n                  <Box mb={1} />\n                  <Typography component=\"span\">{subtitle}</Typography>\n                </>\n              ) : null}\n            </Box>\n            {icon ? icon : null}\n          </MenuItem>,\n          index !== menuItems.length - 1 ? (\n            <Divider key={`divider-${index}`} />\n          ) : null,\n        ],\n      )}\n    </StyledMenu>\n  );\n};\n","import { SentryTagProvider } from '@finmid/sentry/webapp';\nimport { FunctionComponent } from 'react';\nimport { Outlet } from 'react-router-dom';\n\ninterface Props {\n  value: string;\n}\n\nexport const ProductSentryTag: FunctionComponent<Props> = ({ value }) => {\n  return (\n    <SentryTagProvider name=\"product\" value={value}>\n      <Outlet />\n    </SentryTagProvider>\n  );\n};\n","import { Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { Button } from '../Button';\nimport { Typography } from '../Typography';\n\nexport const RouteErrorFallback = () => {\n  const { t } = useTranslation('errors', { keyPrefix: 'routeErrorFallback' });\n\n  return (\n    <Box\n      height=\"100vh\"\n      width=\"100vw\"\n      display=\"flex\"\n      justifyContent=\"center\"\n      alignItems=\"center\"\n      bgcolor=\"gray.50\"\n    >\n      <Box\n        maxWidth={360}\n        display=\"flex\"\n        justifyContent=\"center\"\n        alignItems=\"center\"\n        flexDirection=\"column\"\n        textAlign=\"center\"\n      >\n        <Typography fontSize={24} lineHeight=\"32px\" fontWeight={700}>\n          {t('title')}\n        </Typography>\n        <Spacer height={2} />\n        <Typography fontSize={15} lineHeight=\"20px\">\n          <Trans\n            t={t}\n            i18nKey=\"message\"\n            defaults=\"We have been notified of the issue and are looking into it. For immediate support please reach out to us at <a>support@finmid.com</a>.\"\n            components={{\n              a: <a href=\"mailto:support@finmid.com\">support@finmid.com</a>,\n            }}\n          />\n        </Typography>\n        <Spacer height={3} />\n        <Button variant=\"primary\" onClick={() => window.location.reload()}>\n          {t('action')}\n        </Button>\n      </Box>\n    </Box>\n  );\n};\n","import * as Sentry from '@sentry/react';\nimport { useEffect } from 'react';\nimport { useRouteError } from 'react-router-dom';\n\nimport { RouteErrorFallback } from './RouteErrorFallback';\n\nexport const SentryRouteErrorFallback = () => {\n  const routeError = useRouteError();\n\n  useEffect(() => {\n    Sentry.captureException(routeError);\n  }, [routeError]);\n\n  return <RouteErrorFallback />;\n};\n","import { Typography } from '@mui/material';\nimport Box from '@mui/material/Box';\nimport { v4 } from 'uuid';\n\nimport { DataRowValueWithDetail, SectionContent, SectionDataRow } from '..';\n\nfunction isSectionItemWithDetail(\n  object: SectionItem | SectionItemWithDetail,\n): object is SectionItemWithDetail {\n  return 'detail' in object;\n}\n\ninterface SectionItem {\n  label: string;\n  value?: string | number | null;\n  'data-amount'?: number;\n}\ninterface SectionItemWithDetail {\n  label: string;\n  value: string;\n  detail: string;\n  'data-amount'?: number;\n}\n\nexport type ItemsList = (SectionItem | SectionItemWithDetail)[];\n\ninterface List {\n  items: ItemsList;\n  testId?: string;\n}\n\nexport interface SectionDetails {\n  title?: string;\n  lists: List[];\n  testId?: string;\n}\n\ninterface Props {\n  sections: SectionDetails[];\n}\n\nexport const ProfileDetails = ({ sections }: Props) => {\n  return (\n    <Box\n      gap={0.5}\n      display={'flex'}\n      flexDirection={'column'}\n      data-test-id=\"profile-details\"\n    >\n      {sections.map((section) => (\n        <Box key={v4()} data-test-id={section.testId}>\n          {section.title && (\n            <Box height={32} display=\"flex\" alignItems=\"center\" mb={0.5}>\n              <Typography\n                fontSize={15}\n                lineHeight=\"16px\"\n                fontWeight={700}\n                ml={2}\n              >\n                {section.title}\n              </Typography>\n            </Box>\n          )}\n          {section.lists.map((list) => (\n            <SectionContent\n              disablePadding\n              key={v4()}\n              data-test-id={list.testId}\n            >\n              {list.items.map((item) => (\n                <SectionDataRow\n                  label={item.label}\n                  css={{ padding: 16 }}\n                  key={item.label}\n                  data-amount={item['data-amount']}\n                >\n                  {isSectionItemWithDetail(item) ? (\n                    <DataRowValueWithDetail\n                      value={item.value ?? ''}\n                      detail={item.detail}\n                    />\n                  ) : (\n                    item.value\n                  )}\n                </SectionDataRow>\n              ))}\n            </SectionContent>\n          ))}\n        </Box>\n      ))}\n    </Box>\n  );\n};\n","import { BuyerStatus, SellerStatus } from '@finmid/distributor-types';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { ReactNode } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { SmeStatusIndicator, Typography, smeStatusMap } from '..';\n\ninterface Props {\n  status: BuyerStatus | SellerStatus;\n  name: string;\n  menu: ReactNode;\n}\n\nexport const ProfileStatusSection = ({ status, name, menu }: Props) => {\n  const { t } = useTranslation('components', {\n    keyPrefix: 'smeStatus',\n  });\n\n  return (\n    <Box data-test-id=\"buyer-status\">\n      <Typography\n        fontSize={13}\n        lineHeight=\"16px\"\n        data-test-id=\"sme-status-label\"\n      >\n        {t(smeStatusMap[status].label).toUpperCase()}\n      </Typography>\n      <Spacer height={1} />\n      <Box\n        display=\"flex\"\n        alignItems=\"center\"\n        justifyContent=\"space-between\"\n        gap={1}\n      >\n        <Box\n          display=\"flex\"\n          alignItems=\"center\"\n          justifyContent=\"flex-start\"\n          gap={1}\n          overflow=\"hidden\"\n        >\n          <SmeStatusIndicator status={status} />\n          <Typography\n            fontSize={19}\n            fontWeight={700}\n            lineHeight=\"24px\"\n            style={{\n              textOverflow: 'ellipsis',\n              overflow: 'hidden',\n              textWrap: 'nowrap',\n            }}\n          >\n            {name}\n          </Typography>\n        </Box>\n        <Box>{menu}</Box>\n      </Box>\n      <Spacer height={2} />\n    </Box>\n  );\n};\n","import {\n  Buyer,\n  BuyerStatus,\n  Seller,\n  SellerStatus,\n} from '@finmid/distributor-types';\nimport { useReactivateBuyerMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { BannerVariant } from '@finmid/ui/ocarina';\nimport { useCallback, useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nconst alertVariants: Record<SellerStatus | BuyerStatus, BannerVariant> = {\n  REJECTED: 'critical',\n  SUSPENDED: 'neutral',\n  INACTIVE: 'neutral',\n  PENDING: 'success',\n  PENDING_REACTIVATION: 'success',\n  ACTIVE: 'success',\n};\n\ntype Alert = {\n  label: string;\n  variant: BannerVariant;\n  action?: {\n    label: string;\n    onClick: () => void;\n  };\n};\n\nexport const useBuyerStatusAlerts = (buyer?: Buyer): Alert | null => {\n  const { t } = useTranslation('sidebar', {\n    keyPrefix: 'alerts.buyer',\n  });\n  const { notifyError } = useNotifications();\n\n  const [reactivateBuyer] = useReactivateBuyerMutation();\n\n  const handleReactivation = useCallback(\n    async ({\n      externalId,\n      buyerLegalName,\n    }: {\n      externalId: string;\n      buyerLegalName: string;\n    }) => {\n      try {\n        await reactivateBuyer({ externalId }).unwrap();\n      } catch {\n        notifyError(t('reactivation.errorMessage', { buyerLegalName }));\n      }\n    },\n    [notifyError, reactivateBuyer, t],\n  );\n\n  return useMemo(() => {\n    if (buyer == null) return null;\n\n    const variant = alertVariants[buyer.status];\n\n    switch (buyer.status) {\n      case 'REJECTED':\n        return { label: t('rejected'), variant };\n\n      case 'SUSPENDED':\n        return { label: t('suspended'), variant };\n\n      case 'INACTIVE':\n        return {\n          label: t('inactive'),\n          variant,\n          action: {\n            label: t('reactivateBtn'),\n            onClick: () =>\n              handleReactivation({\n                externalId: buyer.externalId,\n                buyerLegalName: buyer.legalName,\n              }),\n          },\n        };\n\n      case 'PENDING_REACTIVATION':\n        return { label: t('pending_reactivation'), variant };\n\n      default:\n        return null;\n    }\n  }, [buyer, handleReactivation, t]);\n};\n\nexport const useSellerStatusAlerts = (seller?: Seller): Alert | null => {\n  const { t } = useTranslation('sidebar', {\n    keyPrefix: 'alerts.seller',\n  });\n\n  return useMemo(() => {\n    if (seller == null) return null;\n\n    const variant = alertVariants[seller.status];\n\n    switch (seller.status) {\n      case 'REJECTED':\n        return { label: t('rejected'), variant };\n\n      case 'SUSPENDED':\n        return { label: t('suspended'), variant };\n\n      default:\n        return null;\n    }\n  }, [seller, t]);\n};\n","import { Buyer, Seller } from '@finmid/distributor-types';\nimport { Banner, Spacer } from '@finmid/ui/ocarina';\n\nimport {\n  useBuyerStatusAlerts,\n  useSellerStatusAlerts,\n} from './SmeStatusDrawerAlert.hook';\n\nexport type SmeStatusDrawerAlertProps =\n  | {\n      buyer: Buyer;\n      seller?: never;\n    }\n  | {\n      buyer?: never;\n      seller: Seller;\n    };\n\nexport const SmeStatusDrawerAlert = ({\n  buyer,\n  seller,\n}: SmeStatusDrawerAlertProps) => {\n  const buyerAlert = useBuyerStatusAlerts(buyer);\n  const sellerAlert = useSellerStatusAlerts(seller);\n\n  const alert = buyerAlert || sellerAlert;\n\n  if (alert) {\n    return (\n      <>\n        <Banner\n          variant={alert.variant}\n          data-test-id=\"sme-status-drawer-alert\"\n          action={\n            alert.action != null ? (\n              <Banner.Button onClick={alert.action.onClick}>\n                {alert.action.label}\n              </Banner.Button>\n            ) : undefined\n          }\n        >\n          {alert.label}\n        </Banner>\n        <Spacer height={2} />\n      </>\n    );\n  }\n\n  return null;\n};\n","import { BuyerStatus, SellerStatus } from '@finmid/distributor-types';\nimport { BadgeProps, Indicator } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\ntype SmeStatusIndicatorProps = {\n  status: BuyerStatus | SellerStatus;\n};\n\nconst smeStatusMap = {\n  ACTIVE: { label: 'active', variant: 'success' },\n  PENDING: { label: 'pending', variant: 'alert' },\n  PENDING_REACTIVATION: { label: 'pendingReactivation', variant: 'alert' },\n  INACTIVE: { label: 'inactive', variant: 'neutral' },\n  SUSPENDED: { label: 'suspended', variant: 'trivial' },\n  REJECTED: { label: 'rejected', variant: 'danger' },\n} as const satisfies Record<BuyerStatus | SellerStatus, BadgeProps>;\n\nexport const SmeStatusIndicator = ({ status }: SmeStatusIndicatorProps) => {\n  const { t, ready } = useTranslation('components', {\n    keyPrefix: 'smeStatus',\n  });\n  const { label, variant } = smeStatusMap[status];\n\n  if (ready) {\n    return (\n      <Indicator\n        tooltip={t(label)}\n        variant={variant}\n        data-test-id=\"sme-status-indicator\"\n      />\n    );\n  }\n\n  return null;\n};\n","import { BuyerStatus, SellerStatus } from '@finmid/distributor-types';\nimport { Badge, BadgeProps } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\ntype SmeStatusTagProps = {\n  status: BuyerStatus | SellerStatus;\n};\n\nexport const smeStatusMap = {\n  ACTIVE: { label: 'active', variant: 'success' },\n  PENDING: { label: 'pending', variant: 'alert' },\n  PENDING_REACTIVATION: { label: 'pendingReactivation', variant: 'alert' },\n  INACTIVE: { label: 'inactive', variant: 'running' },\n  SUSPENDED: { label: 'suspended', variant: 'trivial' },\n  REJECTED: { label: 'rejected', variant: 'danger' },\n} as const satisfies Record<BuyerStatus | SellerStatus, BadgeProps>;\n\nexport const SmeStatusTag = ({ status }: SmeStatusTagProps) => {\n  const { t, ready } = useTranslation('components', {\n    keyPrefix: 'smeStatus',\n  });\n  const { label, variant } = smeStatusMap[status];\n\n  if (ready) {\n    return (\n      <Badge label={t(label)} variant={variant} data-test-id=\"sme-status-tag\" />\n    );\n  }\n\n  return null;\n};\n","import { FormEvent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { Button } from '../Button';\n\ntype ActionsProps = {\n  disabled?: boolean;\n  handleCancel: () => void;\n  handleSubmit: (e?: FormEvent<HTMLFormElement> | undefined) => void;\n};\n\nexport const Actions = ({\n  disabled,\n  handleCancel,\n  handleSubmit,\n}: ActionsProps) => {\n  const { t } = useTranslation('components', { keyPrefix: 'suspendSme' });\n\n  return (\n    <>\n      <Button\n        disabled={disabled}\n        variant=\"destructive\"\n        type=\"submit\"\n        onClick={() => handleSubmit()}\n      >\n        {t('btnSubmit')}\n      </Button>\n      <Button variant=\"invisible\" onClick={handleCancel}>\n        {t('btnCancel')}\n      </Button>\n    </>\n  );\n};\n","/* eslint-disable react/jsx-no-useless-fragment */\nimport { ChangeEvent, FormEvent } from 'react';\nimport { Control } from 'react-hook-form';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { FormTextField, Typography } from '../index';\n\nimport { SuspendFormValues } from './SuspendSmeFormDialog';\n\nconst Confirm = ({ placeholder }: { placeholder: string }) => {\n  return (\n    <Typography variant=\"monospace\" sx={{ fontSize: '16px', mx: '4px' }}>\n      {placeholder}\n    </Typography>\n  );\n};\n\ntype ConfirmInputProps = {\n  control: Control<SuspendFormValues>;\n  onSubmit: (e?: FormEvent<HTMLFormElement> | undefined) => void;\n};\n\nexport const ConfirmInput = ({ control, onSubmit }: ConfirmInputProps) => {\n  const { t } = useTranslation('components');\n\n  return (\n    <>\n      <Typography mt={3} mb={1}>\n        <Trans\n          t={t}\n          i18nKey=\"dangerZoneDialog.instructions\"\n          components={[\n            <></>,\n            <Confirm placeholder={t('dangerZoneDialog.confirm')} />,\n          ]}\n        />\n      </Typography>\n      <FormTextField\n        transform={{\n          input: (value: string) => value,\n          output: (e: ChangeEvent<HTMLInputElement | HTMLTextAreaElement>) =>\n            e.target.value.toUpperCase(),\n        }}\n        control={control}\n        name=\"confirm\"\n        fullWidth\n        placeholder={t('suspendSme.placeholderConfirm')}\n        onKeyDown={(e) => {\n          if (e.key === 'Enter') {\n            onSubmit();\n          }\n        }}\n      />\n    </>\n  );\n};\n","import { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport * as yup from 'yup';\n\nexport const useSuspendSmeValidationSchema = () => {\n  const { ready, i18n, t } = useTranslation('components', {\n    keyPrefix: 'suspendSme',\n  });\n\n  const validationSchema = useMemo(\n    () =>\n      yup.object().shape({\n        reason: yup.string().required(t('reasonRequired')),\n        confirm: yup\n          .string()\n          .required()\n          .matches(/confirm/i),\n      }),\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [ready, i18n.language],\n  );\n\n  return {\n    validationSchema,\n  };\n};\n","import { useTheme } from '@emotion/react';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { yupResolver } from '@hookform/resolvers/yup';\nimport { Box } from '@mui/material';\nimport { Dispatch, SetStateAction, useRef } from 'react';\nimport { useForm } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { Dialog } from '../Dialog';\nimport { FormTextField } from '../TextField';\nimport { Typography } from '../Typography';\n\nimport { Actions } from './Actions';\nimport { ConfirmInput } from './ConfirmInput';\nimport { useSuspendSmeValidationSchema } from './SuspendSmeValidationSchema';\n\ntype SuspendSmeFormDialogProps = {\n  isProcessing: boolean;\n  message: string;\n  open: boolean;\n  title: string;\n  handleSuspend: (reason: string) => Promise<void>;\n  setOpen: Dispatch<SetStateAction<boolean>>;\n};\n\nexport type SuspendFormValues = {\n  reason: string;\n  confirm: string;\n};\n\nexport const SuspendSmeFormDialog = ({\n  isProcessing,\n  message,\n  open,\n  title,\n  handleSuspend,\n  setOpen,\n}: SuspendSmeFormDialogProps) => {\n  const formRef = useRef<HTMLFormElement>(null);\n  const { validationSchema } = useSuspendSmeValidationSchema();\n  const { t, ready } = useTranslation('components', {\n    keyPrefix: 'suspendSme',\n  });\n  const theme = useTheme();\n\n  const methods = useForm<SuspendFormValues>({\n    resolver: yupResolver(validationSchema),\n    defaultValues: { reason: '', confirm: '' },\n    mode: 'onBlur',\n  });\n\n  const {\n    control,\n    formState: { isValid },\n    handleSubmit,\n    reset,\n  } = methods;\n\n  const handleSubmitForm = async ({ reason }: SuspendFormValues) => {\n    await handleSuspend(reason);\n    handleClose();\n  };\n\n  const handleClose = () => {\n    reset();\n    setOpen(false);\n  };\n\n  const onSubmit = handleSubmit(handleSubmitForm);\n\n  return (\n    <form ref={formRef}>\n      <Dialog\n        actions={\n          <Actions\n            handleCancel={handleClose}\n            handleSubmit={onSubmit}\n            disabled={!isValid || isProcessing}\n          />\n        }\n        open={open}\n        title={title}\n        onClose={handleClose}\n        data-test-id=\"suspend-sme-dialog\"\n      >\n        {ready ? (\n          <>\n            <Typography\n              fontSize={15}\n              fontWeight={400}\n              lineHeight=\"20px\"\n              color=\"gray.500\"\n              mb={3}\n            >\n              {message}\n            </Typography>\n            <Box>\n              <FormTextField\n                control={control}\n                name=\"reason\"\n                placeholder={t('placeholderReason')}\n                fullWidth\n              />\n            </Box>\n\n            <ConfirmInput control={control} onSubmit={onSubmit} />\n          </>\n        ) : (\n          <Box width={theme.breakpoints.values.tablet}>\n            <Box display=\"flex\" height=\"100%\" width=\"100%\" position=\"relative\">\n              <Loader />\n            </Box>\n          </Box>\n        )}\n      </Dialog>\n    </form>\n  );\n};\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport {\n  Switch as MaterialSwitch,\n  SwitchProps as MaterialSwitchProps,\n} from '@mui/material';\n\n/**\n * This is different from the one we have in sme-frontend; This one has\n * additional styles in the case of size=\"small\" (MuiSwitch-sizeSmall)\n */\nconst StyledSwitch = styled(MaterialSwitch)`\n  ${({ theme }) => css`\n    &.MuiSwitch-root.MuiSwitch-sizeSmall {\n      width: 32px;\n      height: 16px;\n\n      .MuiSwitch-thumb {\n        width: 12px;\n        height: 12px;\n      }\n\n      .MuiSwitch-switchBase {\n        top: 1px;\n        left: 1px;\n      }\n    }\n\n    &.MuiSwitch-root {\n      width: 48px;\n      height: 32px;\n      padding: 0;\n      margin: ${theme.spacing(1)};\n\n      .MuiSwitch-thumb {\n        width: 24px;\n        height: 24px;\n      }\n\n      .MuiSwitch-switchBase {\n        top: 3px;\n        left: 3px;\n        padding: 1px;\n\n        &.Mui-checked {\n          transform: translateX(16px);\n          color: ${theme.palette.common.white};\n        }\n        &.Mui-checked + .MuiSwitch-track {\n          background-color: ${theme.palette.green[400]};\n          opacity: 1;\n          border: none;\n        }\n        &.Mui-focusVisible .MuiSwitch-thumb {\n          color: ${theme.palette.primary.main};\n          border: 6px solid #fff;\n        }\n      }\n\n      .MuiSwitch-track {\n        border-radius: 16px;\n        background-color: ${theme.palette.gray[200]};\n        opacity: 1;\n        transition: ${theme.transitions.create(['background-color', 'border'])};\n      }\n\n      .Mui-disabled {\n        color: ${theme.palette.gray[400]};\n        opacity: 1;\n      }\n\n      .Mui-disabled + .MuiSwitch-track {\n        background-color: ${theme.palette.gray[200]} !important;\n        opacity: 1;\n      }\n\n      .Mui-disabled .MuiSwitch-thumb {\n        background-color: ${theme.palette.gray[400]};\n      }\n    }\n  `}\n`;\n\nexport const Switch = ({\n  disableRipple = true,\n  ...props\n}: MaterialSwitchProps) => (\n  <StyledSwitch disableRipple={disableRipple} {...props} />\n);\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { SwitchProps } from '@mui/material';\n\nimport { Switch } from './Switch';\n\nconst StyledTestModeSwitch = styled(Switch)`\n  ${({ theme }) => css`\n    &.MuiSwitch-root {\n      margin-left: 0;\n      .MuiSwitch-switchBase {\n        &.Mui-checked + .MuiSwitch-track {\n          background-color: ${theme.palette.violet[500]};\n          opacity: 1;\n          border: none;\n        }\n      }\n\n      .MuiSwitch-track {\n        background-color: ${theme.palette.green[400]};\n      }\n    }\n  `}\n`;\n\nexport const TestModeSwitch = ({ size = 'small', ...props }: SwitchProps) => (\n  <StyledTestModeSwitch size={size} {...props} />\n);\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport MuiTableCell from '@mui/material/TableCell';\n\nexport const TableCell = styled(MuiTableCell)`\n  ${({ theme }) => css`\n    color: ${theme.palette.gray[600]};\n    padding-left: 10px;\n    padding-right: 20px;\n\n    &:first-of-type {\n      padding-left: 0;\n    }\n  `}\n`;\n","import styled from '@emotion/styled';\nimport MuiTableHead from '@mui/material/TableHead';\n\nexport const TableHead = styled(MuiTableHead)`\n  & .MuiTableRow-root:hover {\n    background-color: white;\n  }\n`;\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport TableCell from '@mui/material/TableCell';\n\nexport const TableHeader = styled(TableCell)`\n  ${({ theme }) => css`\n    text-transform: none;\n    color: ${theme.palette.gray[500]};\n    font-size: 14px;\n    font-weight: 400;\n    user-select: none;\n    padding-left: 10px;\n    padding-right: 20px;\n    border-bottom-width: 1px;\n    border-bottom-style: solid;\n    border-bottom-color: ${theme.palette.gray[400]};\n    white-space: nowrap;\n\n    &:first-of-type {\n      padding-left: 0;\n    }\n  `}\n`;\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { ArrowRightIcon } from '@finmid/ui/icons';\n\nexport const TableNavigationIcon = styled(ArrowRightIcon)`\n  ${({ theme }) => css`\n    color: ${theme.palette.gray[400]};\n    cursor: pointer;\n  `}\n`;\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport MaterialTableRow, {\n  TableRowProps as MuiTableRowProps,\n} from '@mui/material/TableRow';\nimport { ReactNode } from 'react';\n\ntype TableRowProps = {\n  clickable?: boolean;\n} & MuiTableRowProps;\n\nconst shouldForwardProp = (prop: string) => prop !== 'clickable';\n\nexport const TableRow = styled(MaterialTableRow, {\n  shouldForwardProp,\n})<TableRowProps>`\n  ${({ theme, clickable }) => css`\n    transition: background-color 200ms cubic-bezier(0.4, 0, 0.2, 1) 0ms;\n    cursor: ${clickable ? 'pointer' : 'default'};\n\n    &:last-of-type td {\n      border-bottom: 0;\n    }\n\n    &:hover {\n      background-color: ${theme.palette.gray[50]};\n      & svg {\n        color: #000;\n      }\n    }\n  `}\n`;\n\ntype ClickableTableRowProps = {\n  children: ReactNode;\n  handleClick: () => void;\n};\n\nexport const ClickableTableRow = ({\n  children,\n  handleClick,\n}: ClickableTableRowProps) => (\n  <TableRow onClick={handleClick} clickable>\n    {children}\n  </TableRow>\n);\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport MuiTab, { TabProps } from '@mui/material/Tab';\n\nexport const Tab = styled(MuiTab)`\n  ${({ theme }) => css`\n    text-transform: none;\n    color: ${theme.palette.gray[400]};\n    font-size: 14px;\n    min-width: auto;\n    padding-inline: 0;\n    padding-bottom: ${theme.spacing(3)};\n    margin-inline: ${theme.spacing(2)};\n\n    &:first-of-type {\n      margin-left: 0;\n    }\n\n    &.Mui-selected {\n      color: ${theme.palette.gray[900]};\n      font-weight: 500;\n    }\n  `}\n`;\n\nexport type { TabProps };\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\n\nimport { Tab, TabProps } from './Tab';\n\ntype CounterProps = {\n  selected?: boolean;\n};\n\nconst shouldForwardProp = (prop: string) => {\n  return prop !== 'selected';\n};\n\nconst Counter = styled('span', { shouldForwardProp })<CounterProps>`\n  ${({ theme, selected }) => css`\n    padding: 0 8px;\n    color: ${selected ? theme.palette.gray[900] : theme.palette.gray[400]};\n    box-shadow: ${theme.customShadows.buttonMedium};\n    border-radius: 4px;\n    border: 1px solid ${theme.palette.gray[100]};\n    margin-left: ${theme.spacing(1)};\n    min-height: 24px;\n    display: inline-flex;\n    justify-content: center;\n    align-items: center;\n  `}\n`;\n\ntype TabCounterProps = {\n  count: number;\n  selected?: boolean;\n} & TabProps;\n\nexport const TabCounter = ({ label, count, ...props }: TabCounterProps) => {\n  const { selected } = props;\n\n  return (\n    <Tab\n      label={\n        <span className=\"counter\">\n          {label} <Counter selected={selected}>{count}</Counter>\n        </span>\n      }\n      {...props}\n    />\n  );\n};\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport MuiTabs from '@mui/material/Tabs';\n\nexport const Tabs = styled(MuiTabs)`\n  ${({ theme }) => css`\n    .MuiTabs-indicator {\n      background-color: ${theme.palette.gray[900]};\n      margin-left: 0;\n    }\n  `}\n`;\n","import { useDetectTruncated } from '@finmid/tbl-webapps/hooks';\nimport { useFormat } from '@finmid/translations';\nimport { ArrowLeftIcon, Button, Tooltip } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { HTMLAttributes, PropsWithChildren, ReactNode, useRef } from 'react';\n\nimport { SectionContent } from '../Section';\nimport { Typography } from '../Typography';\n\ntype TaskProps = {\n  id: string;\n  creationTime: string;\n  icon: ReactNode;\n  onClick: () => void;\n  actionLabel: string | ReactNode;\n} & HTMLAttributes<HTMLDivElement>;\n\nexport const Task = ({\n  children,\n  id,\n  creationTime,\n  icon,\n  onClick,\n  actionLabel,\n  ...props\n}: PropsWithChildren<TaskProps>) => {\n  const { ago } = useFormat();\n  const creationTimeRef = useRef(null);\n  const creationTimeIsTruncated = useDetectTruncated(creationTimeRef);\n\n  const timeAgo = ago(new Date(creationTime));\n\n  return (\n    <SectionContent\n      disablePadding\n      data-test-id={`pending-task-${id}`}\n      {...props}\n      css={{\n        marginBottom: 0,\n      }}\n    >\n      <Box height={32} display=\"flex\" alignItems=\"center\" gap={1} mx={2} my={1}>\n        <Box height={20} width={20} flexShrink={0}>\n          {icon}\n        </Box>\n        <Typography\n          lineHeight=\"20px\"\n          fontSize={15}\n          fontWeight={400}\n          whiteSpace=\"nowrap\"\n        >\n          {children}\n        </Typography>\n        <Tooltip\n          title={timeAgo}\n          disableHoverListener={!creationTimeIsTruncated}\n        >\n          <Typography\n            lineHeight=\"20px\"\n            fontSize={15}\n            fontWeight={400}\n            color=\"gray.500\"\n            whiteSpace=\"nowrap\"\n            textOverflow=\"ellipsis\"\n            overflow=\"hidden\"\n            ref={creationTimeRef}\n          >\n            {timeAgo}\n          </Typography>\n        </Tooltip>\n        <Box flex=\"1 0\" display=\"flex\" justifyContent=\"flex-end\">\n          <Button\n            size=\"s\"\n            variant=\"invisible\"\n            onClick={onClick}\n            suffixIcon={\n              <ArrowLeftIcon width={16} css={{ transform: 'scaleX(-1)' }} />\n            }\n            data-test-id=\"btn-doc-upload\"\n          >\n            {actionLabel}\n          </Button>\n        </Box>\n      </Box>\n    </SectionContent>\n  );\n};\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport MuiTooltip from '@mui/material/Tooltip';\n\nexport const Tooltip = styled(MuiTooltip)`\n  ${({ theme }) => css`\n    .Mui-arrow {\n      color: ${theme.palette.gray[900]};\n    }\n\n    .Mui-tooltip {\n      background-color: ${theme.palette.gray[900]};\n      padding: 16px;\n      color: white;\n      font-size: 12px;\n      line-height: 24px;\n      box-shadow: 0px 8px 16px rgba(15, 24, 41, 0.15);\n    }\n\n    .MuiTooltip-tooltipPlacementRight {\n      border-top-left-radius: 0;\n    }\n  `}\n`;\n","import Box from '@mui/material/Box';\nimport { PropsWithChildren } from 'react';\n\nimport { CircleIcon } from '../CircleIcon';\nimport { Typography } from '../Typography';\n\ntype ZeroStateProps = PropsWithChildren<{\n  title: string;\n  description?: string;\n  icon?: React.ReactNode;\n}>;\n\n/**\n * Zero state component. Used when we need to display the fact that we don't\n * have data to show.\n *\n * @param {string} props.title - string\n * @param {string} props.description - string\n * @param {React.ReactNode} props.icon - React node element\n * @param {React.ReactNode} props.children - React node element\n * @returns JSX.Element\n * @example\n    <ZeroState\n      title=\"No API key created yet\"\n      description=\"API keys will be shown here once you create them.\"\n      icon={<KeyIcon />}\n    >\n      <Button variant=\"primary\" onClick={onCreate} disabled={loading}>\n        Generate API key\n      </Button>\n    </ZeroState>\n */\nexport const ZeroState = ({\n  title,\n  description,\n  icon,\n  children,\n  ...props\n}: ZeroStateProps) => (\n  <Box\n    sx={{\n      paddingTop: 7,\n      paddingBottom: 7,\n      flexDirection: 'column',\n      justifyContent: 'center',\n      alignItems: 'center',\n      display: 'flex',\n      ...props,\n    }}\n  >\n    {icon && <CircleIcon icon={icon} outerCircle />}\n    <Box sx={{ mt: 3 }}>\n      <Typography\n        sx={{ fontWeight: 600, color: 'gray.900', fontSize: '14px' }}\n        variant=\"body1\"\n      >\n        {title}\n      </Typography>\n    </Box>\n    {description && (\n      <Box sx={{ mt: 3, w: 0.45, color: 'gray.900' }}>\n        <Typography sx={{ fontSize: '14px' }} color=\"gray.500\" align=\"center\">\n          {description}\n        </Typography>\n      </Box>\n    )}\n    {children && <Box sx={{ mt: 3 }}>{children}</Box>}\n  </Box>\n);\n","import { ENVIRONMENT } from '@finmid/environment';\n\ndeclare global {\n  interface Window {\n    _env_?: {\n      [env: string]: string;\n    };\n  }\n}\n\nconst IS_EPHEMERAL_DEPLOYMENT = window.location.host.endsWith(\n  '.ed.finmid-neutral.com',\n);\n\nexport const KEYCLOAK_URL = window._env_?.KEYCLOAK_URL || '';\nexport const KEYCLOAK_REALM = window._env_?.KEYCLOAK_REALM || '';\nexport const KEYCLOAK_CLIENT_ID = IS_EPHEMERAL_DEPLOYMENT\n  ? 'platform-ui-ed'\n  : window._env_?.KEYCLOAK_CLIENT_ID || '';\n\nexport const RELEASE =\n  ENVIRONMENT === 'localhost'\n    ? 'DEVELOPMENT'\n    : import.meta.env.VITE_SENTRY_RELEASE;\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { AuthenticationProvider } from '@finmid/keycloak';\nimport { GlobalFeatureFlagsControl } from '@finmid/tbl-webapps/components';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { supportedLanguages } from '@finmid/tbl-webapps/utils';\nimport { LocalizationProvider } from '@finmid/translations';\nimport { FullPageLoader } from '@finmid/ui/ocarina';\nimport { StrictMode } from 'react';\nimport { Outlet } from 'react-router-dom';\n\nimport {\n  KEYCLOAK_CLIENT_ID,\n  KEYCLOAK_REALM,\n  KEYCLOAK_URL,\n} from '../environment';\n\nconst buildRedirectUri = () => {\n  const { protocol, host } = window.location;\n  return `${protocol}//${host}${sharedRoutes.loginVerification}`;\n};\n\nconst redirectUri = buildRedirectUri();\n\nexport const AuthenticationRoutesLayout = () => {\n  return (\n    <AuthenticationProvider\n      url={KEYCLOAK_URL}\n      clientId={KEYCLOAK_CLIENT_ID}\n      realm={KEYCLOAK_REALM}\n      redirectUri={redirectUri}\n      onSaveToken={(token) => {\n        localStorage.setItem('token', token);\n      }}\n      loadingElement={<FullPageLoader />}\n    >\n      <StrictMode>\n        <LocalizationProvider supportedLocales={supportedLanguages}>\n          <Outlet />\n        </LocalizationProvider>\n        {ENVIRONMENT !== 'live' && <GlobalFeatureFlagsControl />}\n      </StrictMode>\n    </AuthenticationProvider>\n  );\n};\n","import { Platform } from '@finmid/distributor-types';\nimport {\n  b2bPaymentRoutes,\n  sharedRoutes,\n  sharedTblRoutes,\n} from '@finmid/tbl-webapps/routes';\nimport { useTranslation } from 'react-i18next';\n\nconst b2bPaymentsMenuItemsCategories = [\n  'paymentRequests',\n  'buyers',\n  'sellers',\n  'analytics',\n  'developer',\n] as const;\n\nexport const useTblMenuItems = () => {\n  const { t } = useTranslation('navigation', { keyPrefix: 'header' });\n\n  const menuItems = {\n    paymentRequests: {\n      label: t('paymentRequests'),\n      route: b2bPaymentRoutes.paymentRequests,\n    },\n    buyers: {\n      label: t('buyers'),\n      route: sharedTblRoutes.buyers,\n    },\n    sellers: {\n      label: t('sellers'),\n      route: b2bPaymentRoutes.sellers,\n    },\n    analytics: {\n      label: t('analytics'),\n      route: b2bPaymentRoutes.analytics,\n    },\n    developer: {\n      label: t('developers'),\n      route: sharedRoutes.developers,\n    },\n  };\n\n  const getMenuItems = (distributor?: Platform) => {\n    const isCapitalDistributor = distributor?.products?.includes('PAYABLES');\n\n    const categories = isCapitalDistributor\n      ? b2bPaymentsMenuItemsCategories.filter((cat) => cat !== 'developer')\n      : b2bPaymentsMenuItemsCategories;\n\n    return categories.map((category) => menuItems[category]);\n  };\n\n  return {\n    getMenuItems,\n  };\n};\n","import { CountryIso3Code } from '@finmid/countries';\nimport {\n  createContext,\n  FunctionComponent,\n  PropsWithChildren,\n  useContext,\n} from 'react';\nimport { useLocalStorage } from 'react-use';\n\ninterface CountryContextValue {\n  country: CountryIso3Code | null;\n  setCountry: (country: CountryIso3Code | null) => void;\n}\n\n// eslint-disable-next-line @typescript-eslint/no-non-null-assertion\nconst CountryContext = createContext<CountryContextValue>(null!);\n\nexport const CountryProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => {\n  const [localStorageCountry, setCountry] = useLocalStorage<\n    CountryIso3Code | ''\n  >('country', undefined, {\n    raw: true,\n  });\n\n  const country =\n    localStorageCountry === '' ? null : localStorageCountry ?? null;\n\n  return (\n    <CountryContext.Provider\n      value={{\n        country,\n        setCountry: (c) => setCountry(c ?? ''),\n      }}\n    >\n      {children}\n    </CountryContext.Provider>\n  );\n};\n\nexport const useCountryContext = (): CountryContextValue => {\n  const context = useContext(CountryContext);\n  if (context == null)\n    throw new Error('useCountryContext must be used within a CountryProvider');\n\n  return context;\n};\n","import { getCountry } from '@finmid/countries';\nimport { useGetCountriesQuery } from '@finmid/tbl-webapps/gateway-api';\nimport {\n  ExpandIcon,\n  Dropdown,\n  Menu,\n  MenuButton,\n  MenuItem,\n} from '@finmid/ui/ocarina';\nimport sortBy from 'lodash/sortBy';\nimport { FunctionComponent, useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useCountryContext } from '../Providers';\n\nexport const CountryGlobalSelector: FunctionComponent = () => {\n  const { t } = useTranslation('capital', { keyPrefix: 'merchantOverview' });\n\n  const { data: countries } = useGetCountriesQuery();\n\n  const sortedCountries = useMemo(\n    () =>\n      countries == null ? null : sortBy(countries, (c) => getCountry(c)?.name),\n    [countries],\n  );\n\n  const { country: countryCode, setCountry } = useCountryContext();\n\n  const country = getCountry(countryCode);\n\n  return (\n    <Dropdown>\n      <MenuButton suffixIcon={<ExpandIcon />}>\n        {country == null\n          ? t('countrySelector.allCountries')\n          : `${country.flag} ${country.name}`}\n      </MenuButton>\n      <Menu>\n        <MenuItem onClick={() => setCountry(null)}>\n          {t('countrySelector.allCountries')}\n        </MenuItem>\n        {sortedCountries == null ? (\n          <MenuItem>Loading...</MenuItem>\n        ) : (\n          sortedCountries.map((code) => (\n            <MenuItem key={code} onClick={() => setCountry(code)}>\n              {`${getCountry(code)?.flag} ${getCountry(code)?.name}`}\n            </MenuItem>\n          ))\n        )}\n      </Menu>\n    </Dropdown>\n  );\n};\n","import {\n  ErrorBoundary,\n  LazyLoadFallback,\n  Page,\n} from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { PropsWithChildren, Suspense } from 'react';\n\nexport const LazyLoadedRoute = ({ children }: PropsWithChildren) => {\n  const fallback = (\n    <Page>\n      <LazyLoadFallback />\n    </Page>\n  );\n\n  return (\n    <ErrorBoundary fallback={fallback}>\n      <Suspense fallback={<Loader />}>{children}</Suspense>\n    </ErrorBoundary>\n  );\n};\n","export const routes = {\n  home: '/',\n  summary: '/capital/summary',\n  merchantOverview: '/capital/merchant-overview',\n  merchantDetail: '/capital/merchant-overview/:internalBusinessId',\n  conversion: '/capital/conversion',\n  nps: '/capital/nps',\n} as const;\n\n/**\n * The entry the merchant detail page opens: an application's ID, or its\n * offer group's, which is all the merchant list knows.\n */\nexport const APPLICATION_PARAM = 'applicationId';\n","import { lazy } from 'react';\nimport { Navigate, Route } from 'react-router-dom';\n\nimport { LazyLoadedRoute } from './LazyLoadedRoute';\nimport { routes } from './routes';\n\nconst Summary = lazy(() => import('./Summary/Summary'));\nconst MerchantOverview = lazy(\n  () => import('./MerchantOverview/MerchantOverview'),\n);\nconst MerchantDetailPage = lazy(\n  () => import('./MerchantDetail/MerchantDetailPage'),\n);\nconst NpsOverview = lazy(() => import('./NpsOverview/NpsOverview'));\nconst ConversionPage = lazy(() => import('./ConversionPage/ConversionPage'));\n\nexport const router = (\n  <>\n    <Route\n      path={routes.home}\n      element={<Navigate to={routes.summary} replace />}\n    />\n    <Route\n      path={routes.summary}\n      element={\n        <LazyLoadedRoute>\n          <Summary />\n        </LazyLoadedRoute>\n      }\n    />\n    <Route\n      path={routes.merchantOverview}\n      element={\n        <LazyLoadedRoute>\n          <MerchantOverview />\n        </LazyLoadedRoute>\n      }\n    />\n    <Route\n      path={`${routes.merchantDetail}/*`}\n      element={\n        <LazyLoadedRoute>\n          <MerchantDetailPage />\n        </LazyLoadedRoute>\n      }\n    />\n    <Route\n      path={routes.nps}\n      element={\n        <LazyLoadedRoute>\n          <NpsOverview />\n        </LazyLoadedRoute>\n      }\n    />\n    <Route\n      path={routes.conversion}\n      element={\n        <LazyLoadedRoute>\n          <ConversionPage />\n        </LazyLoadedRoute>\n      }\n    />\n  </>\n);\n","import { MenuItemTypeProps } from '@finmid/tbl-webapps/components';\nimport { useGetDistributorQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { useTranslation } from 'react-i18next';\n\nimport { routes } from '../routes';\n\nexport const useMenuItems: () => MenuItemTypeProps[] = () => {\n  const { t } = useTranslation('sidebar');\n  const { data: distributor } = useGetDistributorQuery();\n\n  const isCapitalDistributor = distributor?.products?.includes('PAYABLES');\n\n  const menuItems: MenuItemTypeProps[] = [\n    { label: t('capital.summary'), route: routes.summary },\n    {\n      label: t('capital.merchantOverview'),\n      route: routes.merchantOverview,\n    },\n    {\n      label: t('capital.nps'),\n      route: routes.nps,\n    },\n    {\n      label: t('capital.conversion'),\n      route: routes.conversion,\n    },\n  ];\n\n  // Only add developers menu if not a Capital distributor\n  if (!isCapitalDistributor) {\n    menuItems.push({\n      label: t('developers'),\n      route: sharedRoutes.developers,\n    });\n  }\n\n  return menuItems;\n};\n","import { ProductModule } from '@finmid/distributor-types';\nimport {\n  CommandBarCapitalProvider,\n  MenuItemTypeProps,\n} from '@finmid/tbl-webapps/components';\n\nimport { CountryProvider } from '../Providers';\nimport { CountryGlobalSelector } from '../components/CountryGlobalSelector';\nimport { router } from '../router';\n\nimport { useMenuItems } from './useMenuItems';\n\nexport const useCapitalModule = (): ProductModule & {\n  menuItems: MenuItemTypeProps[];\n} => {\n  const menuItems = useMenuItems();\n\n  return {\n    id: 'PAYABLES',\n    name: 'Capital',\n    router,\n    menuItems,\n\n    header: {\n      topRightBar: <CountryGlobalSelector />,\n    },\n\n    globalProviders: [CountryProvider, CommandBarCapitalProvider],\n  };\n};\n","import { SVGProps } from 'react';\nexport const LifeRingIcon = (props: SVGProps<SVGSVGElement>) => (\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    width=\"100%\"\n    height=\"100%\"\n    viewBox=\"0 0 16 16\"\n    fill=\"none\"\n    {...props}\n  >\n    <path\n      fill=\"currentColor\"\n      fillRule=\"evenodd\"\n      d=\"M3.152 12.863a6.867 6.867 0 1 0 0-9.727l-.007.008-.009.009A6.845 6.845 0 0 0 1.133 8a6.845 6.845 0 0 0 2.02 4.863ZM2.2 8c0-1.41.503-2.702 1.339-3.707l.9.9A4.514 4.514 0 0 0 3.467 8c0 1.06.363 2.034.972 2.806l-.9.9A5.776 5.776 0 0 1 2.2 8Zm2.093 4.461.9-.9c.773.609 1.747.972 2.807.972 1.06 0 2.034-.363 2.806-.973l.9.901A5.777 5.777 0 0 1 8 13.8a5.777 5.777 0 0 1-3.707-1.339Zm8.168-.754A5.776 5.776 0 0 0 13.801 8c0-1.41-.504-2.702-1.34-3.707l-.9.9c.609.773.972 1.747.972 2.807 0 1.06-.363 2.034-.972 2.806l.9.9ZM8.001 2.2c1.409 0 2.7.503 3.706 1.339l-.9.9A4.514 4.514 0 0 0 8 3.467c-1.06 0-2.034.363-2.806.972l-.9-.9A5.776 5.776 0 0 1 8 2.2ZM4.532 8a3.467 3.467 0 1 1 6.934 0 3.467 3.467 0 0 1-6.934 0Z\"\n      clipRule=\"evenodd\"\n    />\n  </svg>\n);\n","import { SVGProps } from 'react';\nexport const RocketIcon = (props: SVGProps<SVGSVGElement>) => (\n  <svg\n    xmlns=\"http://www.w3.org/2000/svg\"\n    width=\"100%\"\n    height=\"100%\"\n    viewBox=\"0 0 16 16\"\n    fill=\"none\"\n    {...props}\n  >\n    <path\n      fill=\"currentColor\"\n      d=\"M9.385 6.865a1 1 0 1 0 1.414-1.414 1 1 0 0 0-1.414 1.414Z\"\n    />\n    <path\n      fill=\"currentColor\"\n      fillRule=\"evenodd\"\n      d=\"m13.647 2.603.128 1.413a7.2 7.2 0 0 1-3.53 6.864l-2.74 1.606a1.2 1.2 0 0 1-1.454-.187l-2.1-2.1a1.2 1.2 0 0 1-.187-1.455l1.606-2.74a7.2 7.2 0 0 1 6.863-3.53l1.414.129Zm-.982.982-.528-.048A6.133 6.133 0 0 0 6.29 6.543l-1.606 2.74a.133.133 0 0 0 .02.162l2.1 2.1c.044.043.11.051.162.02l2.74-1.605a6.133 6.133 0 0 0 3.007-5.847l-.048-.528Z\"\n      clipRule=\"evenodd\"\n    />\n    <path\n      fill=\"currentColor\"\n      d=\"M4.576 11.674a.533.533 0 0 1 0 .754l-1.885 1.885a.533.533 0 0 1-.755-.754l1.886-1.885a.533.533 0 0 1 .754 0ZM3.162 11.014a.533.533 0 1 0-.754-.755l-.943.943a.533.533 0 1 0 .754.754l.943-.942ZM5.99 13.088a.533.533 0 0 1 0 .754l-.942.943a.533.533 0 0 1-.755-.755l.943-.942a.533.533 0 0 1 .754 0Z\"\n    />\n  </svg>\n);\n","import { useTblMenuItems } from '@distributor-webapp/pages/useTblMenuItems';\nimport { ProductModule } from '@finmid/distributor-types';\nimport { useCapitalModule } from '@finmid/tbl-webapps/capital';\nimport {\n  CommandBarTblProvider,\n  MenuItemTypeProps,\n} from '@finmid/tbl-webapps/components';\nimport { LifeRingIcon } from '@finmid/tbl-webapps/components/HeaderMenu/LifeRingIcon';\nimport { RocketIcon } from '@finmid/tbl-webapps/components/HeaderMenu/RocketIcon';\nimport { useGetDistributorQuery } from '@finmid/tbl-webapps/gateway-api';\nimport {\n  b2bPaymentsChangelogLink,\n  b2bPaymentsFaqPageLink,\n} from '@finmid/tbl-webapps/utils';\nimport posthog from 'posthog-js';\nimport { useTranslation } from 'react-i18next';\n\nimport { B2bPaymentsRouter } from '../routes';\n\ntype Module = ProductModule & {\n  menuItems: MenuItemTypeProps[];\n};\n\nexport const useModules = (): Module[] | null => {\n  const b2bModule = useB2bPaymentsModule();\n  const capitalModule = useCapitalModule();\n\n  const modules = [b2bModule, capitalModule];\n\n  if (modules.includes(null)) return null;\n\n  return [b2bModule, capitalModule] as Module[];\n};\n\nconst useB2bPaymentsModule = (): Module | null => {\n  const { t } = useTranslation('sidebar');\n\n  const { data: distributor } = useGetDistributorQuery();\n\n  const { getMenuItems } = useTblMenuItems();\n\n  const menuItems = getMenuItems(distributor);\n\n  return {\n    id: 'TBL',\n    name: 'B2B Payments',\n    router: B2bPaymentsRouter,\n    menuItems,\n\n    globalProviders: [CommandBarTblProvider],\n\n    header: {\n      kebabMenuSections: [\n        [\n          {\n            label: t('changelog'),\n            icon: <RocketIcon />,\n            href: b2bPaymentsChangelogLink,\n            onClick: () => posthog.capture('clicked_menu_item_changelog'),\n          },\n        ],\n        [\n          {\n            label: t('faq'),\n            icon: <LifeRingIcon />,\n            href: b2bPaymentsFaqPageLink,\n            onClick: () => posthog.capture('clicked_menu_item_faq'),\n          },\n        ],\n        [],\n      ],\n    },\n  };\n};\n","import { useGetDistributorQuery } from '@finmid/tbl-webapps/gateway-api';\n\nimport { useModules } from './useModules';\n\nexport const useEnabledModules = () => {\n  const modules = useModules();\n  const { data: distributor, isLoading, error } = useGetDistributorQuery();\n\n  const distributorProducts = distributor?.products || [];\n  const enabledModules =\n    modules?.filter((m) => distributorProducts.includes(m.id)) ?? [];\n\n  return {\n    enabledModules,\n    isLoading: isLoading || modules == null,\n    error,\n  };\n};\n","import { useEnabledModules } from '@distributor-webapp/hooks/useEnabledModules';\nimport { KebabMenuItem } from '@finmid/distributor-types';\nimport { DashboardLayout, HeaderMenu } from '@finmid/tbl-webapps/components';\nimport { Fragment } from 'react';\n\nexport const DashboardPage = () => {\n  const { enabledModules } = useEnabledModules();\n\n  const menuItems = enabledModules.flatMap(({ menuItems }) => menuItems);\n  const kebabMenuSections = enabledModules\n    .map<[KebabMenuItem[], KebabMenuItem[], KebabMenuItem[]]>(\n      (em) => em.header?.kebabMenuSections ?? [[], [], []],\n    )\n    .reduce(\n      (mergedSections, moduleSections) => [\n        mergedSections[0].concat(moduleSections[0]),\n        mergedSections[1].concat(moduleSections[1]),\n        mergedSections[2].concat(moduleSections[2]),\n      ],\n      [[], [], []],\n    );\n\n  return (\n    <DashboardLayout menuItems={menuItems}>\n      {enabledModules.map(({ id, header }) =>\n        header?.topRightBar != null ? (\n          <Fragment key={`header-${id}`}>{header.topRightBar}</Fragment>\n        ) : null,\n      )}\n      <HeaderMenu kebabMenuSections={kebabMenuSections} menuItems={menuItems} />\n    </DashboardLayout>\n  );\n};\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { ENVIRONMENT } from '@finmid/environment';\nimport { useKeycloak } from '@finmid/keycloak';\nimport { CopyButton, Page } from '@finmid/tbl-webapps/components';\nimport { usePlatformId } from '@finmid/tbl-webapps/hooks';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { Typography } from '@mui/material';\nimport { Navigate } from 'react-router-dom';\n\nconst WrapperPage = styled(Page)(({ theme }) => ({\n  paddingTop: 0,\n}));\n\nconst Content = styled.div`\n  ${({ theme }) => css`\n    padding: ${theme.spacing(4)};\n  `}\n`;\n\nconst Title = styled(Typography)`\n  font-weight: 600;\n`;\n\nexport const Debug = () => {\n  const {\n    keycloak: { token, tokenParsed },\n  } = useKeycloak();\n  const platformId = usePlatformId();\n\n  if (ENVIRONMENT === 'live') {\n    return <Navigate to={sharedRoutes.root} />;\n  }\n\n  const tokenParsedJson = JSON.stringify(tokenParsed, null, 2);\n\n  return (\n    <WrapperPage>\n      <Title>Your Platform ID:</Title>\n      <Content>\n        <pre>{platformId || 'no platform id'}</pre>\n        {platformId && <CopyButton text={platformId} notify />}\n      </Content>\n\n      <Title>Parsed Token:</Title>\n      <Content>\n        <pre>{tokenParsedJson || 'no parsed token'}</pre>\n        {tokenParsedJson && <CopyButton text={tokenParsedJson} notify />}\n      </Content>\n\n      <Title>Your Full Keycloak Token:</Title>\n      <Content>\n        <Typography sx={{ maxWidth: '100%', wordBreak: 'break-all', mb: 2 }}>\n          <code>{token || 'no token'}</code>\n        </Typography>\n        {token && <CopyButton text={token} notify />}\n      </Content>\n    </WrapperPage>\n  );\n};\n","import { LOGIN_REDIRECT_KEY, useKeycloak } from '@finmid/keycloak';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { FullPageLoader } from '@finmid/ui/ocarina';\nimport { useEffect } from 'react';\nimport { Navigate, useLocation } from 'react-router-dom';\n\nconst saveRedirectUri = (redirectTo: string) => {\n  localStorage.setItem(LOGIN_REDIRECT_KEY, redirectTo);\n};\n\nconst getRedirectUri = () => localStorage.getItem(LOGIN_REDIRECT_KEY) ?? '';\n\nexport const LoginPage = () => {\n  const location = useLocation();\n  const state = location.state as { redirectTo?: string };\n  const { redirectTo = sharedRoutes.root } = state ?? {\n    redirectTo: sharedRoutes.root,\n  };\n\n  const { keycloak } = useKeycloak();\n\n  useEffect(() => {\n    if (!keycloak.authenticated) {\n      saveRedirectUri(redirectTo);\n      void keycloak.login();\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  if (keycloak?.authenticated && !keycloak.isTokenExpired()) {\n    const savedRedirect = getRedirectUri();\n    return <Navigate replace to={savedRedirect} />;\n  }\n\n  return <FullPageLoader />;\n};\n","import { LOGIN_REDIRECT_KEY } from '@finmid/keycloak';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { useEffect } from 'react';\nimport { Navigate } from 'react-router-dom';\n\nconst getRedirect = (): string | null =>\n  localStorage.getItem(LOGIN_REDIRECT_KEY);\n\nconst clearRedirect = () => localStorage.removeItem(LOGIN_REDIRECT_KEY);\n\nexport const LoginRedirect = () => {\n  const redirectLocation = getRedirect();\n  useEffect(clearRedirect, []);\n\n  return <Navigate replace to={redirectLocation ?? sharedRoutes.root} />;\n};\n","import { useSaveTokens } from '@finmid/keycloak';\nimport { useKeycloak } from '@finmid/keycloak';\n\nimport { LoginRedirect } from './LoginRedirect';\n\nexport const LoginVerification = () => {\n  const { keycloak } = useKeycloak();\n  const onSaveToken = () => {};\n\n  const { saveToken, saveRefreshToken } = useSaveTokens({ onSaveToken });\n\n  if (keycloak.authenticated && keycloak.token && keycloak.refreshToken) {\n    saveToken(keycloak.token);\n    saveRefreshToken(keycloak.refreshToken);\n  }\n\n  return <LoginRedirect />;\n};\n","export const isTestEnvironment = navigator.userAgent.startsWith('Playwright');\n","import {\n  FunctionComponent,\n  PropsWithChildren,\n  createContext,\n  useCallback,\n  useContext,\n} from 'react';\nimport { useLocalStorage } from 'react-use';\n\nimport { isTestEnvironment } from '../isTestEnvironment';\n\nimport { ConsentBanner } from './ConsentBanner';\n\nexport type ConsentState = 'ACTIVE' | 'MISSING' | 'REJECTED';\n\ninterface Value {\n  consentState: ConsentState | undefined;\n  changeConsent: (state: ConsentState) => void;\n}\n\nexport const ConsentContext = createContext<Value>({\n  consentState: 'REJECTED',\n  changeConsent: () => {},\n});\n\nexport const ConsentContextProvider: FunctionComponent<PropsWithChildren> = ({\n  children,\n}) => {\n  const [consentState, setConsentState] = useLocalStorage<ConsentState>(\n    'cookieConsent',\n    'MISSING',\n  );\n\n  const onConsentChange = useCallback(\n    async (state: ConsentState) => {\n      if (state === 'MISSING') {\n        setConsentState('MISSING');\n        return;\n      }\n\n      setConsentState(state);\n    },\n    [setConsentState],\n  );\n\n  return (\n    <ConsentContext.Provider\n      value={{\n        consentState,\n        changeConsent: onConsentChange,\n      }}\n    >\n      {children}\n      {isTestEnvironment ? null : <ConsentBanner />}\n    </ConsentContext.Provider>\n  );\n};\n\nexport const useConsentContext = () => useContext(ConsentContext);\n","import styled from '@emotion/styled';\nimport { Button, ElevatedPaper } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/system';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { useConsentContext } from './ConsentContext';\n\nexport const ConsentBanner = () => {\n  const { t } = useTranslation('consentBanner');\n  const { consentState, changeConsent } = useConsentContext();\n\n  const open = consentState === 'MISSING';\n\n  if (!open) return null;\n\n  return (\n    <DialogPaper data-test-id=\"consent-banner\">\n      <Box>\n        <Trans\n          t={t}\n          i18nKey=\"text\"\n          components={{\n            pdfLink: (\n              // eslint-disable-next-line jsx-a11y/anchor-has-content\n              <a\n                href=\"/Cookie Policy.pdf\"\n                target=\"_blank\"\n                rel=\"noreferrer\"\n                style={{ color: 'black' }}\n              />\n            ),\n          }}\n        >\n          To optimize our website, we use cookies (PostHog), for analysis and\n          statistical purposes. By selecting \"Accept\", you consent to the use of\n          cookies as described in our {'<'}pdfLink{'>'}\n          Privacy Policy\n          {'</'}pdfLink{'>'}. You can withdraw your consent at any time.\n        </Trans>\n      </Box>\n      <Box display=\"flex\" gap={1} flexDirection=\"row\">\n        <Button\n          variant=\"secondary\"\n          onClick={() => changeConsent('REJECTED')}\n          data-test-id=\"reject-button\"\n          translate=\"no\"\n        >\n          {t('declineButton')}\n        </Button>\n        <Button\n          variant=\"secondary\"\n          onClick={() => changeConsent('ACTIVE')}\n          data-test-id=\"accept-button\"\n          translate=\"no\"\n        >\n          {t('acceptButton')}\n        </Button>\n      </Box>\n    </DialogPaper>\n  );\n};\n\nconst DialogPaper = styled(ElevatedPaper)(({ theme }) => ({\n  position: 'fixed',\n  bottom: 32,\n  left: 0,\n  right: 0,\n  marginLeft: 'auto',\n  marginRight: 'auto',\n  width: 'calc(100vw - 160px)',\n  maxWidth: 780,\n  padding: 16,\n  display: 'flex',\n  flexDirection: 'column',\n  gap: 16,\n  justifyContent: 'center',\n  alignItems: 'center',\n  zIndex: 1000,\n\n  [theme.breakpoints.up('desktop')]: {\n    flexDirection: 'row',\n  },\n}));\n","import { ENVIRONMENT, fromEnvironment } from '@finmid/environment';\nimport { sanitizePostHogEvent } from '@finmid/utils';\nimport { PostHogConfig } from 'posthog-js';\nimport {\n  PostHogProvider as BasePostHogProvider,\n  usePostHog,\n} from 'posthog-js/react';\nimport { FunctionComponent, PropsWithChildren, useEffect } from 'react';\n\nimport { useConsentContext } from './ConsentBanner';\nimport { isTestEnvironment } from './isTestEnvironment';\n\ninterface Props {\n  options?: Partial<PostHogConfig>;\n}\n\nexport const PostHogProvider: FunctionComponent<PropsWithChildren<Props>> = ({\n  options,\n  children,\n}) => {\n  const { consentState } = useConsentContext();\n  const apiKey = fromEnvironment('POSTHOG_KEY', { required: false });\n\n  if (apiKey == null) return children;\n\n  const isDisabled =\n    consentState !== 'ACTIVE' ||\n    isTestEnvironment ||\n    (ENVIRONMENT !== 'live' && ENVIRONMENT !== 'staging');\n\n  return (\n    <BasePostHogProvider\n      apiKey={apiKey}\n      options={{\n        api_host: 'https://eu.posthog.com',\n        persistence: 'cookie',\n        opt_out_capturing_by_default: isDisabled,\n        opt_out_persistence_by_default: isDisabled,\n        before_send: sanitizePostHogEvent,\n\n        ...options,\n      }}\n    >\n      <OptInManager />\n      {children}\n    </BasePostHogProvider>\n  );\n};\n\nconst OptInManager = () => {\n  const { consentState } = useConsentContext();\n  const posthog = usePostHog();\n\n  useEffect(() => {\n    if (consentState === 'ACTIVE') {\n      posthog.opt_in_capturing();\n    } else {\n      posthog.opt_out_capturing();\n      posthog.persistence?.clear();\n    }\n  }, [consentState, posthog]);\n\n  return null;\n};\n","import { useKeycloak } from '@finmid/keycloak';\nimport { useGetDistributorQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { jwtDecode } from '@finmid/utils';\nimport posthog from 'posthog-js';\nimport { useEffect } from 'react';\nimport { useLocation } from 'react-router-dom';\n\nexport const useInitPostHog = () => {\n  const { data: distributor } = useGetDistributorQuery();\n  const {\n    keycloak: { token, subject },\n  } = useKeycloak();\n  const { pathname } = useLocation();\n\n  useEffect(() => {\n    if (distributor == null) return;\n\n    posthog.group('platform', distributor.id, {\n      name: distributor.name,\n      products: distributor.products,\n    });\n  }, [distributor]);\n\n  useEffect(() => {\n    if (subject != null) {\n      const decodedToken = token != null ? jwtDecode(token) : null;\n\n      posthog.identify(subject, {\n        email: decodedToken?.email ?? undefined,\n        internalUserId: decodedToken?.preferred_username ?? undefined,\n        keycloakSubject: subject,\n      });\n    }\n  }, [subject, token]);\n\n  useEffect(() => {\n    posthog.capture('$pageview');\n  }, [pathname]);\n};\n","import { useKeycloak } from '@finmid/keycloak';\nimport { useFirstVisits } from '@finmid/tbl-webapps/hooks';\nimport { useConsentContext } from '@finmid/tbl-webapps/posthog';\nimport { FullPageLoader } from '@finmid/ui/ocarina';\nimport { useEffect } from 'react';\n\nexport const LogoutPage = () => {\n  const { keycloak } = useKeycloak();\n  const { changeConsent, consentState = 'MISSING' } = useConsentContext();\n  const { firstVisits, setFirstVisits } = useFirstVisits();\n\n  useEffect(() => {\n    localStorage.clear();\n    sessionStorage.clear();\n    setFirstVisits(firstVisits); // Preserve firsVisits state\n    changeConsent(consentState); // Preserve consent state\n    void keycloak.logout();\n    // eslint-disable-next-line react-hooks/exhaustive-deps -- run once on mount; re-running would clear storage and log out again\n  }, []);\n\n  return <FullPageLoader />;\n};\n","import styled from '@emotion/styled';\n\nconst CenteredContainer = styled.div`\n  display: flex;\n  align-items: center;\n  justify-content: center;\n  min-height: 100vh;\n  background-color: white;\n`;\n\nconst MaintenanceContent = styled.div`\n  max-width: 600px;\n  padding: 24px;\n`;\n\nexport const TechnicalMaintenancePage = () => {\n  return (\n    <CenteredContainer>\n      <MaintenanceContent>\n        <h2>Technical maintenance</h2>\n        <p>\n          The application is currently undergoing technical maintenance.\n          <br />\n          We'll be back shortly. Thank you for your patience.\n        </p>\n      </MaintenanceContent>\n    </CenteredContainer>\n  );\n};\n","import { BEValidationError } from '@finmid/distributor-types';\n\nexport const getBEInvalidFields = (\n  error: BEValidationError,\n  fieldsMap: Record<string, string>,\n) => {\n  const { description } = error.data.errorData.data;\n\n  // Escape special characters in the fields and join them into a single regular expression\n  const escapedFields = Object.keys(fieldsMap)\n    .map((field) => field.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&'))\n    .join('|');\n  const regexPattern = `(${escapedFields})`;\n\n  const regex = new RegExp(regexPattern, 'gi');\n\n  const matches = description.match(regex);\n\n  const uniqueMatches = matches ? [...new Set(matches)] : [];\n\n  const invalidFields = uniqueMatches\n    .map((match) => fieldsMap[match])\n    .filter((fieldName) => fieldName != null);\n\n  if (invalidFields.length === 0) {\n    throw new Error('Could not identify invalid fields');\n  }\n  return invalidFields;\n};\n","import { ZodValidationError } from '@finmid/distributor-types';\n\nexport const getZodInvalidFields = (\n  error: ZodValidationError,\n  fieldsMap: Record<string, string>,\n) => {\n  const invalidFields = Array.from(\n    new Set(\n      error.data.errorData.data.validationErrors\n        .map((validationError) => validationError.field)\n        .filter((fieldName) => Object.values(fieldsMap).includes(fieldName)),\n    ),\n  );\n  if (invalidFields.length === 0) {\n    throw new Error('Could not identify invalid fields');\n  }\n  return invalidFields;\n};\n","import {\n  isBEValidationError,\n  isZodValidationError,\n} from '@finmid/distributor-types';\nimport { SerializedError } from '@reduxjs/toolkit';\nimport { FetchBaseQueryError } from '@reduxjs/toolkit/query';\n\nimport { getBEInvalidFields } from './BEValidationError/getBEInvalidFields';\nimport { getZodInvalidFields } from './ZodValidationError/getZodInvalidFields';\n\ntype GetFormValidationErrorsProps = {\n  error: FetchBaseQueryError | SerializedError;\n  fieldsMap: Record<string, string>;\n};\ntype GetFormValidationErrors = (props: GetFormValidationErrorsProps) => {\n  validation: string[] | null;\n};\n\nexport const getFormValidationErrors: GetFormValidationErrors = ({\n  error,\n  fieldsMap,\n}) => {\n  try {\n    let invalidFields: string[] | null = null;\n    if (isZodValidationError(error)) {\n      invalidFields = getZodInvalidFields(error, fieldsMap);\n    } else if (isBEValidationError(error)) {\n      invalidFields = getBEInvalidFields(error, fieldsMap);\n    }\n    return { validation: invalidFields };\n  } catch {\n    // isZodValidationError || isBeValidationError but error is not recognized\n    return { validation: [] };\n  }\n};\n","import {\n  isBE_Error,\n  isBEValidationError,\n  isPayloadAnRTKQueryError,\n  isZodValidationError,\n} from '@finmid/distributor-types';\nimport { SerializedError } from '@reduxjs/toolkit';\nimport { FetchBaseQueryError } from '@reduxjs/toolkit/query';\nimport { useCallback } from 'react';\n\nimport { GetCustomDomainErrors } from '../types';\nimport { getFormValidationErrors } from '../utils';\n\ntype UseHandleFormError = (props: {\n  labels: Record<string, string>;\n  fieldsMap: Record<string, string>;\n  getCustomDomainErrors?: GetCustomDomainErrors;\n}) => {\n  handleFormError: (error: unknown) => {\n    customError?: string;\n    invalidFields: string[] | null;\n    validationErrors: string[] | null;\n  };\n};\n\nexport const useHandleFormError: UseHandleFormError = ({\n  labels,\n  fieldsMap,\n  getCustomDomainErrors,\n}) => {\n  const handleRTKError = useCallback(\n    (error: FetchBaseQueryError | SerializedError) => {\n      let invalidFields: string[] | null = null;\n      let validationErrors: string[] | null = null;\n      let customError: string | undefined;\n\n      if (isZodValidationError(error) || isBEValidationError(error)) {\n        const formValidationErrors = getFormValidationErrors({\n          error,\n          fieldsMap,\n        });\n\n        if (formValidationErrors.validation != null) {\n          const recognizedErrors = formValidationErrors.validation.length > 0;\n          if (recognizedErrors) {\n            invalidFields = formValidationErrors.validation;\n            validationErrors = formValidationErrors.validation.map(\n              (invalidField) => labels[invalidField],\n            );\n          }\n        }\n      } else if (isBE_Error(error)) {\n        const domainError = getCustomDomainErrors?.(error);\n        customError = domainError?.message;\n      }\n      return { customError, invalidFields, validationErrors };\n    },\n    [fieldsMap, labels, getCustomDomainErrors],\n  );\n\n  const handleFormError = useCallback(\n    (error: unknown) => {\n      if (isPayloadAnRTKQueryError(error)) {\n        return handleRTKError(error);\n      } else {\n        return {\n          customError: undefined,\n          invalidFields: null,\n          validationErrors: null,\n        };\n      }\n    },\n    [handleRTKError],\n  );\n\n  return {\n    handleFormError,\n  };\n};\n","import { BE_Error } from '@finmid/distributor-types';\n\nimport { GetDomainErrorType } from '../../types';\n\nexport const getDomainErrors: GetDomainErrorType = (error: BE_Error) =>\n  error.data.errorData.data.description;\n","import { InvalidMessages } from '@finmid/distributor-types';\n\nexport const defaultInvalidFields = [];\n\nexport const defaultInvalidMessages: InvalidMessages = {\n  translationKeys: [],\n  customMessages: [],\n};\n","import { ZodValidationError } from '@finmid/distributor-types';\nimport {\n  TRANSLATION_KEY_PREFIX,\n  CUSTOM_MESSAGE_PREFIX,\n} from '@finmid/tbl-webapps/utils';\n\nconst getReadableMessages = ({\n  error,\n  prefix,\n}: {\n  error: ZodValidationError;\n  prefix: string;\n}) => {\n  const messages = error.data.errorData.data.validationErrors\n    .filter((validationError) => validationError.message.startsWith(prefix))\n    .map((prefixedValidationError) => {\n      const [, message] = prefixedValidationError.message.split(prefix);\n      return message;\n    });\n  return messages;\n};\n\nconst getReadableTranslationKeys = (error: ZodValidationError) =>\n  getReadableMessages({ error, prefix: TRANSLATION_KEY_PREFIX });\n\nconst getReadableMessagesCustom = (error: ZodValidationError) =>\n  getReadableMessages({ error, prefix: CUSTOM_MESSAGE_PREFIX });\n\nexport const getZodReadableMessages = (error: ZodValidationError) => {\n  const translationKeys = getReadableTranslationKeys(error);\n  const customMessages = getReadableMessagesCustom(error);\n\n  return {\n    translationKeys,\n    customMessages,\n  };\n};\n","import { ZodValidationError } from '@finmid/distributor-types';\n\nexport const getZodInvalidFieldsV2 = (error: ZodValidationError) => {\n  try {\n    const invalidFields = Array.from(\n      new Set(\n        error.data.errorData.data.validationErrors.map(\n          (validationError) => validationError.field,\n        ),\n      ),\n    );\n    return invalidFields;\n  } catch {\n    return [];\n  }\n};\n","import { InvalidMessages } from '@finmid/distributor-types';\nimport { ZodValidationError } from '@finmid/distributor-types';\n\nimport { defaultInvalidFields, defaultInvalidMessages } from '../constants';\n\nimport { getZodReadableMessages } from './getZodCustomMessages';\nimport { getZodInvalidFieldsV2 } from './getZodInvalidFieldsV2';\n\nexport const getZodErrors = (error: ZodValidationError) => {\n  let invalidFieldsZod: string[] = defaultInvalidFields;\n  let invalidMessagesZod: InvalidMessages = defaultInvalidMessages;\n\n  try {\n    invalidMessagesZod = getZodReadableMessages(error);\n    invalidFieldsZod = getZodInvalidFieldsV2(error);\n\n    return { invalidFieldsZod, invalidMessagesZod };\n  } catch {\n    return { invalidFieldsZod, invalidMessagesZod };\n  }\n};\n","import {\n  InvalidMessages,\n  isBE_Error,\n  isPayloadAnRTKQueryError,\n  isZodValidationError,\n} from '@finmid/distributor-types';\nimport { SerializedError } from '@reduxjs/toolkit';\nimport { FetchBaseQueryError } from '@reduxjs/toolkit/query';\nimport { useCallback } from 'react';\n\nimport { GetDomainErrorType } from '../types';\nimport { getDomainErrors } from '../utils/BEDomainError/getDomainError';\nimport { getZodErrors } from '../utils/ZodValidationError';\n\ntype UseHandleFormErrorV2 = (getCustomDomainErrors?: GetDomainErrorType) => (\n  error: unknown,\n) => {\n  customError?: string;\n  invalidFieldsZod?: string[];\n  invalidMessagesZod?: InvalidMessages;\n};\n\nexport const useIdentifyFormErrors: UseHandleFormErrorV2 = (\n  getCustomDomainErrors,\n) => {\n  const identifyRTKError = useCallback(\n    (error: FetchBaseQueryError | SerializedError) => {\n      if (isZodValidationError(error)) {\n        const { invalidFieldsZod, invalidMessagesZod } = getZodErrors(error);\n        return {\n          invalidFieldsZod,\n          invalidMessagesZod,\n        };\n      } else if (isBE_Error(error)) {\n        const customError = getCustomDomainErrors\n          ? getCustomDomainErrors(error)\n          : getDomainErrors(error);\n        return {\n          customError,\n        };\n      } else {\n        return {};\n      }\n    },\n    [getCustomDomainErrors],\n  );\n\n  const identifyErrors = useCallback(\n    (error: unknown) => {\n      if (isPayloadAnRTKQueryError(error)) {\n        return identifyRTKError(error);\n      } else {\n        return {};\n      }\n    },\n    [identifyRTKError],\n  );\n\n  return identifyErrors;\n};\n","import { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { SnackbarKey } from 'notistack';\n\ntype DisplayErrorToast = (props: {\n  ticketNumber?: string;\n  toastComponent: JSX.Element;\n  action: (snackbarId: SnackbarKey) => JSX.Element;\n}) => void;\n\ntype UseDisplayErrorToast = () => {\n  displayErrorToast: DisplayErrorToast;\n};\n\nexport const useDisplayErrorToast: UseDisplayErrorToast = () => {\n  const { enqueueSnackbar } = useNotifications();\n\n  const displayErrorToast: DisplayErrorToast = ({\n    action,\n    ticketNumber,\n    toastComponent,\n  }) => {\n    enqueueSnackbar(toastComponent, {\n      action,\n      key: ticketNumber,\n      persist: true,\n      preventDuplicate: true,\n      variant: 'warning',\n      style: { whiteSpace: 'pre-line' },\n    });\n  };\n\n  return {\n    displayErrorToast,\n  };\n};\n","const getInvalidFieldsLabels = (\n  appFields: string[],\n  appFieldsToFieldsLabels: Record<string, string>,\n) => {\n  return appFields.reduce((acc, invalidField) => {\n    acc.push(appFieldsToFieldsLabels[invalidField] ?? invalidField);\n    return acc;\n  }, [] as string[]);\n};\n\nexport const getFieldsLabels =\n  ({\n    bffFieldsToAppFields,\n    appFieldsToLabels,\n  }: {\n    bffFieldsToAppFields: Record<string, string>;\n    appFieldsToLabels: Record<string, string>;\n  }) =>\n  (bffInvalidFields: string[]) => {\n    const invalidFields = bffInvalidFields.map(\n      (field) => bffFieldsToAppFields[field] ?? field,\n    );\n    const labels = getInvalidFieldsLabels(invalidFields, appFieldsToLabels);\n    return labels;\n  };\n","import { InvalidMessages } from '@finmid/distributor-types';\nimport { withErrorProps } from '@finmid/tbl-webapps/components';\nimport { useState } from 'react';\n\nimport { GetDomainErrorType } from '../types';\n\nimport { useDisplayErrorToast } from './useDisplayErrorToast';\nimport { getFieldsLabels } from './useGetWebappLabels';\nimport { useIdentifyFormErrors } from './useIdentifyFormErrors';\n\ntype UseDisplayErrorToUserProps = {\n  appFieldsToLabels?: Record<string, string>;\n  bffFieldsToAppFields?: Record<string, string>;\n  getCustomDomainErrors?: GetDomainErrorType;\n};\n\nexport const useDisplayErrorToUser = ({\n  appFieldsToLabels = {},\n  bffFieldsToAppFields = {},\n  getCustomDomainErrors,\n}: UseDisplayErrorToUserProps) => {\n  const [invalidFieldsErrors, setInvalidFieldsErrors] = useState<{\n    labels?: string[];\n    messages?: InvalidMessages;\n  }>({});\n\n  const getLabels = getFieldsLabels({\n    bffFieldsToAppFields,\n    appFieldsToLabels,\n  });\n\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const identifyErrors = useIdentifyFormErrors(getCustomDomainErrors);\n\n  const displayErrorToUser = (error: unknown) => {\n    const { customError, invalidFieldsZod, invalidMessagesZod } =\n      identifyErrors(error);\n\n    // Checking if we have custom messages from failed validation on BFF\n    if (\n      invalidMessagesZod?.customMessages.length ||\n      invalidMessagesZod?.translationKeys.length\n    ) {\n      setInvalidFieldsErrors({\n        messages: invalidMessagesZod,\n      });\n    }\n\n    // else if anything at all from validation on BFF\n    else if (invalidFieldsZod) {\n      setInvalidFieldsErrors({\n        labels: getLabels(invalidFieldsZod),\n      });\n    }\n\n    // else -> error passed from BE\n    else {\n      setInvalidFieldsErrors({});\n      displayErrorToast(\n        withErrorProps({ ...(error as Error), message: customError }),\n      );\n    }\n  };\n\n  return {\n    invalidFieldsErrors,\n    displayErrorToUser,\n  };\n};\n","import { TechnicalMaintenancePage } from '@distributor-webapp/pages';\nimport { ENVIRONMENT } from '@finmid/environment';\nimport { useKeycloak } from '@finmid/keycloak';\nimport { fetchErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useGetLiveDistributorLockQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useLoadDistributorCurrencies } from '@finmid/tbl-webapps/hooks';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { useEffect } from 'react';\nimport { Navigate, Outlet, RouteProps, useLocation } from 'react-router-dom';\n\ntype Props = RouteProps & {\n  component?: React.ComponentType<RouteProps> | React.ComponentType<any>;\n};\n\nexport const PrivateRoute = ({ component: Component, ...props }: Props) => {\n  const { keycloak } = useKeycloak();\n  const location = useLocation();\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const { isError: isErrorCurrencies, isLoading: loadingCurrencies } =\n    useLoadDistributorCurrencies();\n\n  const { data } = useGetLiveDistributorLockQuery(undefined, {\n    skip: ENVIRONMENT !== 'live' || !keycloak.authenticated,\n  });\n\n  const loadingLock = ENVIRONMENT === 'live' && data == null;\n  const locked = ENVIRONMENT === 'live' && data?.bnplSandboxOnlyMode === true;\n\n  useEffect(() => {\n    if (isErrorCurrencies) {\n      displayErrorToast(fetchErrorProps);\n    }\n  }, [isErrorCurrencies, displayErrorToast]);\n\n  if (!keycloak.authenticated) {\n    return (\n      <Navigate\n        replace\n        to={sharedRoutes.login}\n        state={{ redirectTo: location.pathname }}\n      />\n    );\n  }\n\n  if (loadingCurrencies || loadingLock) return null;\n\n  if (locked) return <TechnicalMaintenancePage />;\n\n  return Component == null ? <Outlet /> : <Component {...props} />;\n};\n","import { useGetIframeUrlsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useDistributorCurrencies } from '@finmid/tbl-webapps/hooks';\nimport { jwtDecode } from '@finmid/utils';\nimport { differenceInMilliseconds } from 'date-fns';\nimport { useEffect } from 'react';\n\nconst getTokenFromUrl = (url: string): string => {\n  const jwtTokenStart = url.indexOf('/ey') + 1;\n  return url.slice(jwtTokenStart);\n};\n\nexport const useAnalyticsPage = () => {\n  const { defaultCurrency } = useDistributorCurrencies();\n  const {\n    data: iframeUrl,\n    isLoading: isLoadingAnalytics,\n    isFetching: isFetchingAnalytics,\n    refetch,\n  } = useGetIframeUrlsQuery({ currency: defaultCurrency });\n\n  useEffect(() => {\n    if (iframeUrl == null) return;\n\n    const token = getTokenFromUrl(iframeUrl);\n    const decodedToken = jwtDecode(token);\n\n    if (decodedToken == null) return;\n\n    const expirationDate = new Date(decodedToken.exp * 1000);\n    const timeToTokenExpiry = differenceInMilliseconds(\n      expirationDate,\n      new Date(),\n    );\n\n    const refetchAfterTimeout = setTimeout(() => refetch(), timeToTokenExpiry);\n\n    return () => clearTimeout(refetchAfterTimeout);\n  }, [iframeUrl, refetch]);\n\n  const isLoading = isLoadingAnalytics || isFetchingAnalytics;\n\n  return {\n    iframeUrl,\n    isLoading,\n  };\n};\n","import { PageNavigation, Typography } from '@finmid/tbl-webapps/components';\nimport {\n  useBreadcrumbs,\n  useDistributorCurrencies,\n} from '@finmid/tbl-webapps/hooks';\nimport {\n  currencyIcons,\n  currencyLabels,\n  currencySymbols,\n} from '@finmid/tbl-webapps/utils';\nimport { Icon } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { useTranslation } from 'react-i18next';\n\nexport const AnalyticsPageNavigation = () => {\n  const { defaultCurrency } = useDistributorCurrencies();\n  const { t } = useTranslation('analyticsPage');\n\n  const breadcrumbs = useBreadcrumbs();\n\n  return (\n    <PageNavigation breadcrumbs={breadcrumbs.analytics}>\n      <Box display=\"flex\" alignItems=\"center\">\n        <Typography fontSize={15}>{t('metricsDisplayed')}&nbsp;</Typography>\n        <Typography\n          fontWeight={700}\n          mr={1}\n          fontSize={15}\n        >{`${currencyLabels[defaultCurrency]} ${currencySymbols[defaultCurrency]}`}</Typography>\n        <Icon\n          icon={currencyIcons[defaultCurrency]}\n          style={{ width: '19px', height: '19px' }}\n        />\n      </Box>\n    </PageNavigation>\n  );\n};\n","import { Page } from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { useTranslation } from 'react-i18next';\n\nimport { useAnalyticsPage } from './AnalyticsPage.hook';\nimport { AnalyticsPageNavigation } from './AnalyticsPageNavigation';\n\nexport const AnalyticsPage = () => {\n  const { ready } = useTranslation('analyticsPage');\n\n  const { iframeUrl, isLoading } = useAnalyticsPage();\n\n  return (\n    <>\n      <AnalyticsPageNavigation />\n      <Page\n        data-test-id=\"analytics-page\"\n        css={{ paddingTop: 0, paddingBottom: 0, overflowY: 'hidden' }}\n      >\n        {!ready && <Loader />}\n\n        {ready && (\n          <Box height=\"100%\">\n            {isLoading && <Loader />}\n\n            {!isLoading && iframeUrl !== undefined && (\n              <Box height=\"100%\">\n                <iframe\n                  title=\"Analytics Dashboard\"\n                  src={`${iframeUrl}#bordered=false&titled=false`}\n                  style={{\n                    border: 'none',\n                    width: '100%',\n                    height: '100%',\n                  }}\n                />\n              </Box>\n            )}\n          </Box>\n        )}\n      </Page>\n    </>\n  );\n};\n","import styled from '@emotion/styled';\nimport {\n  MAX_FILE_SIZE,\n  Typography,\n  UnstyledLink,\n} from '@finmid/tbl-webapps/components';\nimport { humanReadableFileSize } from '@finmid/tbl-webapps/utils';\nimport { Trans, useTranslation } from 'react-i18next';\n\nconst typographyStyles = {\n  fontSize: 15,\n  fontWeight: 400,\n  lineHeight: '20px',\n};\n\nconst List = styled.ul(({ theme }) => ({\n  ...typographyStyles,\n  color: theme.glo.color.foundations[60],\n  paddingInlineStart: theme.spacing(3),\n  marginBlock: 0,\n}));\n\ntype BuyerDocumentUploadDescriptionProps = {\n  docsExpected: boolean;\n  buyerId: string;\n  buyerLegalName: string;\n};\n\nexport const BuyerDocumentsUploadDescription = ({\n  buyerId,\n  buyerLegalName,\n  docsExpected,\n}: BuyerDocumentUploadDescriptionProps) => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'documentUpload' });\n\n  return (\n    <>\n      <Typography {...typographyStyles} color=\"gray.500\">\n        <Trans\n          t={t}\n          i18nKey={\n            docsExpected\n              ? 'documentsRequiredDescription'\n              : 'documentsNotRequiredDescription'\n          }\n          components={{\n            u: (\n              <UnstyledLink\n                to={`/buyers/${buyerId}`}\n                style={{ textDecoration: 'underline' }}\n              />\n            ),\n            br: <br />,\n          }}\n          values={{\n            buyerLegalName,\n          }}\n        />\n      </Typography>\n      <List>\n        <li>{t('docTypes.latestFinancials')}</li>\n        <li>{t('docTypes.tradeDetails')}</li>\n        <li>{t('docTypes.other')}</li>\n      </List>\n      <Typography {...typographyStyles} color=\"gray.500\">\n        {t('restrictions', {\n          maxFileSize: humanReadableFileSize(MAX_FILE_SIZE),\n        })}\n      </Typography>\n    </>\n  );\n};\n","import { InnerDocumentsUpload } from '@finmid/tbl-webapps/components';\nimport {\n  useGetBuyerByIdQuery,\n  useGetBuyerTasksQuery,\n  useUploadBuyerDocumentsMutation,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { sharedTblRoutes } from '@finmid/tbl-webapps/routes';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { Navigate, useParams } from 'react-router-dom';\n\nimport { BuyerDocumentsUploadDescription } from './BuyerDocumentsUploadDescription';\n\nexport const BuyerDocumentsUploadPage = () => {\n  const { buyerId = '' } = useParams();\n\n  const {\n    data: buyer,\n    isFetching: isFetchingBuyer,\n    error: errorBuyer,\n  } = useGetBuyerByIdQuery({ externalId: buyerId ?? '' }, { skip: !buyerId });\n\n  const { buyerDocumentsUpload: breadcrumbs } = useBreadcrumbs(\n    buyerId,\n    buyer?.legalName,\n  );\n\n  const {\n    data: buyerTasks,\n    error: errorBuyerTasks,\n    isFetching: isFetchingBuyerTasks,\n  } = useGetBuyerTasksQuery({ externalId: buyerId }, { skip: !buyerId });\n\n  const [upload, { isLoading }] = useUploadBuyerDocumentsMutation();\n  const uploadBuyerDocuments = async (files: File[]) => {\n    return upload({ files, externalId: buyerId });\n  };\n\n  if (isFetchingBuyerTasks || isFetchingBuyer) {\n    return <Loader />;\n  }\n\n  if (errorBuyer || errorBuyerTasks) {\n    // TODO\n  }\n\n  const pendingTasks =\n    buyerTasks?.filter((task) => task.status === 'PENDING') ?? [];\n  const hasPendingTasks = pendingTasks.length > 0;\n\n  const backHomeRoute = `${sharedTblRoutes.buyers}?view=${buyerId}`;\n\n  if (buyerId && buyer) {\n    return (\n      <InnerDocumentsUpload\n        backHomeRoute={backHomeRoute}\n        breadcrumbs={breadcrumbs}\n        isLoading={isLoading}\n        uploadDocuments={uploadBuyerDocuments}\n        DocumentsUploadDescription={\n          <BuyerDocumentsUploadDescription\n            buyerId={buyerId}\n            buyerLegalName={buyer.legalName}\n            docsExpected={hasPendingTasks}\n          />\n        }\n      />\n    );\n  }\n\n  return <Navigate to={backHomeRoute} replace />;\n};\n","import { BuyersFilters } from './BuyersFilters.types';\n\nexport const useDefaultFilters = () => {\n  const defaultBuyersFilters: BuyersFilters = {\n    server: {\n      limit: 10,\n      scope: 'AGGREGATED',\n      search: '',\n    },\n    firstPosition: 1,\n  };\n\n  return {\n    defaultBuyersFilters,\n  };\n};\n","export const buyersFiltersKey = 'buyersFiltersKey';\n\nexport const removeStoredBuyersFilters = () => {\n  sessionStorage.removeItem(buyersFiltersKey);\n};\n","import cloneDeep from 'lodash/cloneDeep';\nimport set from 'lodash/set';\nimport {\n  createContext,\n  PropsWithChildren,\n  useContext,\n  useEffect,\n  useState,\n} from 'react';\nimport { useSessionStorage } from 'react-use';\n\nimport { buyersFiltersKey, useDefaultFilters } from '../BuyersFilters';\nimport {\n  BuyersFilters,\n  Scope,\n  UpdateBuyersFilters,\n} from '../BuyersFilters/BuyersFilters.types';\n\ntype ListContext = {\n  filters: BuyersFilters;\n  resetFilters: () => void;\n  updateFilters: (filters: UpdateBuyersFilters) => void;\n};\n\nconst initialContext = null;\n\nexport const BuyersListContext = createContext<ListContext | null>(\n  initialContext,\n);\n\ntype BuyersListContextProps = PropsWithChildren;\n\nexport const BuyersListContextProvider = ({\n  children,\n}: BuyersListContextProps) => {\n  const { defaultBuyersFilters } = useDefaultFilters();\n\n  const [storedFilters, setStoredFilters] =\n    useSessionStorage<BuyersFilters>(buyersFiltersKey);\n\n  const [filters, setFilters] = useState<BuyersFilters>(() => {\n    return storedFilters ?? defaultBuyersFilters;\n  });\n\n  const updateFilters = (updatedFilters: UpdateBuyersFilters) => {\n    const _filters = cloneDeep(filters);\n    Object.entries(updatedFilters).forEach(([key, value]) => {\n      set(_filters, key, value);\n    });\n    setStoredFilters(_filters);\n    setFilters(_filters);\n  };\n\n  const resetFilters = () => {\n    setStoredFilters(defaultBuyersFilters);\n    setFilters(defaultBuyersFilters);\n  };\n\n  useEffect(() => {\n    const scope: Scope = 'AGGREGATED';\n    const updatedFilters = {\n      'server.scope': scope,\n    };\n    updateFilters(updatedFilters);\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const value = {\n    filters,\n    resetFilters,\n    updateFilters,\n  };\n\n  return (\n    <BuyersListContext.Provider value={value}>\n      {children}\n    </BuyersListContext.Provider>\n  );\n};\n\nexport const useBuyersListContext = () => {\n  const context = useContext(BuyersListContext);\n\n  if (context == null) {\n    throw new Error(\n      'useBuyersListContext can only be used inside BuyersListContext Provider',\n    );\n  }\n\n  return context;\n};\n","import styled from '@emotion/styled';\nimport { Badge } from '@finmid/ui/ocarina';\n\n// TODO add variant to Ocarina?\nconst StyledAccentBadge = styled(Badge)(({ theme: { glo } }) => ({\n  backgroundColor: glo.color.roles.accent[60],\n}));\n\nexport const AccentBadge = ({\n  label,\n  testId,\n}: {\n  label: string;\n  testId?: string;\n}) => (\n  <StyledAccentBadge variant=\"running\" label={label} data-test-id={testId} />\n);\n","import styled from '@emotion/styled';\nimport { Button, ButtonProps } from '@finmid/ui/ocarina';\n\ntype Props = {\n  selected: boolean;\n};\n\nexport const ButtonsTabButton = styled(\n  (props: ButtonProps) => <Button variant=\"invisible\" {...props} />,\n  {\n    shouldForwardProp: (prop) => prop !== 'selected',\n  },\n)<Props>(({ theme: { com, glo }, selected }) => ({\n  borderStyle: 'solid',\n  borderWidth: '1px',\n  borderColor: selected ? glo.color.foundations[20] : 'transparent',\n  color: selected ? glo.color.foundations[100] : glo.color.foundations[50],\n  backgroundColor: selected ? 'white' : 'transparent',\n  whiteSpace: 'nowrap',\n  fontWeight: selected ? 700 : 400,\n  zIndex: selected ? 1 : undefined,\n\n  '&:hover': {\n    borderColor: glo.color.foundations[20],\n    backgroundColor: glo.color.foundations[20],\n  },\n\n  '&:focus-visible': {\n    boxShadow: com.button.shadow.focus,\n    borderColor: selected ? glo.color.foundations[100] : 'transparent',\n    outline: 'none',\n  },\n}));\n","import styled from '@emotion/styled';\nimport ButtonGroupBase from '@mui/material/ButtonGroup';\nimport { FunctionComponent, useState } from 'react';\n\nimport { ButtonsTabButton } from './ButtonsTabButton';\n\ninterface Button {\n  label: string;\n  onClick: () => void;\n  testId?: string;\n}\n\ninterface ManagedButton extends Button {\n  /**\n   * Can be used to control the selected state of the button\n   */\n  selected: boolean;\n}\n\ninterface UnmanagedButton extends Button {\n  selected?: never;\n}\n\ninterface Props {\n  buttons: UnmanagedButton[] | ManagedButton[];\n  fullWidth?: boolean;\n}\n\nconst StyledButtonGroup = styled(ButtonGroupBase)(({ theme }) => ({\n  borderRadius: theme.com.button.radius.m,\n  display: 'flex',\n  flexDirection: 'row',\n  gap: 5,\n}));\n\nexport const ButtonsTabs: FunctionComponent<Props> = ({\n  buttons,\n  fullWidth = false,\n}) => {\n  const [selected, setSelected] = useState(0);\n\n  const managed = 'selected' in buttons[0];\n  const managedButtons = buttons as ManagedButton[];\n\n  return (\n    <StyledButtonGroup fullWidth={fullWidth}>\n      {buttons.map((button, index) => (\n        <ButtonsTabButton\n          key={index}\n          fullWidth={fullWidth}\n          selected={\n            managed ? managedButtons[index].selected : selected === index\n          }\n          onClick={() => {\n            if (!managed) {\n              setSelected(index);\n            }\n            button.onClick();\n          }}\n          data-test-id={button.testId}\n        >\n          {button.label}\n        </ButtonsTabButton>\n      ))}\n    </StyledButtonGroup>\n  );\n};\n","import { Buyer, Seller } from '@finmid/distributor-types';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { MenuItem, Tooltip } from '@finmid/ui/ocarina';\nimport posthog from 'posthog-js';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\ninterface Props {\n  seller?: Seller;\n  buyer?: Buyer;\n}\n\nexport const CreatePaymentRequestMenuItem = ({ seller, buyer }: Props) => {\n  const navigate = useNavigate();\n  const { t } = useTranslation('sidebar', {\n    keyPrefix: 'actions.createPaymentRequest',\n  });\n\n  const status = seller?.status || buyer?.status;\n  const canCreatePaymentRequests = status === 'ACTIVE';\n\n  const createPaymentRequest = () => {\n    posthog.capture('clicked-sidebar-create-payment-request');\n\n    navigate(b2bPaymentRoutes.createPaymentRequest, {\n      state: { seller, buyer },\n    });\n  };\n\n  return (\n    <Tooltip\n      title={\n        !canCreatePaymentRequests\n          ? seller != null\n            ? t('tooltipSeller')\n            : t('tooltipBuyer')\n          : ''\n      }\n      placement=\"left\"\n    >\n      <MenuItem\n        onClick={createPaymentRequest}\n        data-test-id=\"create-payment-request-menu-item\"\n        disabled={!canCreatePaymentRequests}\n      >\n        {t('btnLabel')}\n      </MenuItem>\n    </Tooltip>\n  );\n};\n","import { Theme } from '@emotion/react';\nimport styled from '@emotion/styled';\n\ntype variant = 'neutral' | 'success' | 'alert' | 'running' | 'trivial';\n\nconst variantColorMap: (\n  theme: Theme,\n) => Record<variant, { main: string; subdued?: string }> = ({ glo }) => ({\n  neutral: {\n    main: glo.color.foundations[80],\n  },\n  success: {\n    main: glo.color.roles.success[40],\n  },\n  alert: {\n    main: glo.color.roles.alert[40],\n    subdued: glo.color.roles.alert[50],\n  },\n  running: {\n    main: glo.color.roles.running[40],\n    subdued: glo.color.roles.running[50],\n  },\n  trivial: {\n    main: glo.color.roles.trivial[50],\n  },\n});\n\nexport const FormulaBlock = styled('span', {\n  shouldForwardProp: (prop) => !['variant', 'suffix'].includes(prop),\n})<{ variant: variant; suffix?: string }>(({ theme, variant, suffix }) => ({\n  fontSize: 15,\n  lineHeight: '20px',\n  fontWeight: 400,\n\n  display: 'inline-block',\n  padding: `0 ${theme.spacing(0.5)}`,\n  color: theme.palette.white,\n  borderRadius: 4,\n\n  backgroundColor: variantColorMap(theme)[variant].main,\n\n  '::after': {\n    borderTopRightRadius: 'inherit',\n    borderBottomRightRadius: 'inherit',\n    content: suffix ? `'${suffix}'` : undefined,\n    backgroundColor: variantColorMap(theme)[variant].subdued,\n    display: 'inline-block',\n    marginRight: `-${theme.spacing(0.5)}`,\n    marginLeft: theme.spacing(0.5),\n    padding: 'inherit',\n  },\n}));\n","import { Typography } from '@finmid/tbl-webapps/components';\nimport { Fragment } from 'react';\n\ntype FormulaRowProps = {\n  items: React.ReactNode[];\n};\n\nexport const FormulaRow = ({ items }: FormulaRowProps) => (\n  <Typography fontSize={15} fontWeight={400} lineHeight=\"20px\">\n    {items.map((item, index) => (\n      <Fragment key={index}>\n        {typeof item === 'string' ? ` ${item} ` : item}\n      </Fragment>\n    ))}\n  </Typography>\n);\n","import { useFormat } from '@finmid/translations';\nimport Box from '@mui/material/Box';\nimport Collapse from '@mui/material/Collapse';\nimport { useTranslation } from 'react-i18next';\n\nimport { FormulaBlock } from './FormulaBlock';\nimport { FormulaRow } from './FormulaRow';\n\nexport const ExampleSummary = ({ open }: { open: boolean }) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice.feeFormulaDialog',\n  });\n  const { money } = useFormat();\n\n  return (\n    <Collapse in={open}>\n      <Box\n        display=\"flex\"\n        flexDirection=\"column\"\n        gap={1}\n        p={2}\n        borderTop=\"1px solid\"\n        borderColor=\"gray.100\"\n      >\n        <FormulaRow\n          items={[\n            <FormulaBlock variant=\"neutral\">{t('totalAmount')}</FormulaBlock>,\n            '=',\n            <FormulaBlock variant=\"neutral\">{money(100, 'EUR')}</FormulaBlock>,\n          ]}\n        />\n\n        <FormulaRow\n          items={[\n            <FormulaBlock variant=\"alert\" suffix=\"%\">\n              {t('totalFee')}\n            </FormulaBlock>,\n            '=',\n            <FormulaBlock variant=\"alert\" suffix=\"%\">\n              3.0\n            </FormulaBlock>,\n          ]}\n        />\n\n        <FormulaRow\n          items={[\n            <FormulaBlock variant=\"running\" suffix=\"%\">\n              {t('serviceFee')}\n            </FormulaBlock>,\n            '=',\n            <FormulaBlock variant=\"running\" suffix=\"%\">\n              2.0\n            </FormulaBlock>,\n          ]}\n        />\n      </Box>\n    </Collapse>\n  );\n};\n","import { useFormat } from '@finmid/translations';\nimport Box from '@mui/material/Box';\n\nimport { FormulaBlock } from './FormulaBlock';\nimport { FormulaRow } from './FormulaRow';\n\nexport const ExampleView = () => {\n  const { money } = useFormat();\n\n  return (\n    <Box display=\"flex\" flexDirection=\"column\" gap={1} p={2}>\n      <FormulaRow\n        items={[\n          <FormulaBlock variant=\"neutral\">{money(100, 'EUR')}</FormulaBlock>,\n          '-',\n          <FormulaBlock variant=\"alert\">{money(3, 'EUR')}</FormulaBlock>,\n          '=',\n          <FormulaBlock variant=\"trivial\">{money(97, 'EUR')}</FormulaBlock>,\n        ]}\n      />\n\n      <FormulaRow\n        items={[\n          <FormulaBlock variant=\"trivial\">{money(97, 'EUR')}</FormulaBlock>,\n          '×',\n          <FormulaBlock variant=\"running\" suffix=\"%\">\n            2.0\n          </FormulaBlock>,\n          '=',\n          <FormulaBlock variant=\"running\">{money(1.94, 'EUR')}</FormulaBlock>,\n        ]}\n      />\n\n      <FormulaRow\n        items={[\n          <FormulaBlock variant=\"alert\">{money(3, 'EUR')}</FormulaBlock>,\n          '-',\n          <FormulaBlock variant=\"running\">{money(1.94, 'EUR')}</FormulaBlock>,\n          '=',\n          <FormulaBlock variant=\"success\">{money(1.06, 'EUR')}</FormulaBlock>,\n        ]}\n      />\n    </Box>\n  );\n};\n","import { Typography } from '@finmid/tbl-webapps/components';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\n\nimport { FormulaBlock } from './FormulaBlock';\n\nexport const FormulaView = () => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice.feeFormulaDialog',\n  });\n\n  return (\n    <Box display=\"flex\" flexDirection=\"column\" gap={1} p={2}>\n      <Typography fontSize={15} fontWeight={400} lineHeight=\"20px\">\n        <FormulaBlock variant=\"neutral\">{t('totalAmount')}</FormulaBlock>\n        {' - '}\n        <FormulaBlock variant=\"alert\">{t('totalFee')}</FormulaBlock>\n        {' = '}\n        <FormulaBlock variant=\"trivial\">{t('totalPayout')}</FormulaBlock>\n      </Typography>\n\n      <Typography fontSize={15} fontWeight={400} lineHeight=\"20px\">\n        <FormulaBlock variant=\"trivial\">{t('totalPayout')}</FormulaBlock>\n        {' × '}\n        <FormulaBlock variant=\"running\" suffix=\"%\">\n          {t('serviceFee')}\n        </FormulaBlock>\n        {' = '}\n        <FormulaBlock variant=\"running\">{t('serviceFee')}</FormulaBlock>\n      </Typography>\n\n      <Typography fontSize={15} fontWeight={400} lineHeight=\"20px\">\n        <FormulaBlock variant=\"alert\">{t('totalFee')}</FormulaBlock>\n        {' - '}\n        <FormulaBlock variant=\"running\">{t('serviceFee')}</FormulaBlock>\n        {' = '}\n        <FormulaBlock variant=\"success\">{t('platformMarkup')}</FormulaBlock>\n      </Typography>\n    </Box>\n  );\n};\n","import {\n  ButtonGroup,\n  DialogContent,\n  DialogTitle,\n  Typography,\n} from '@finmid/tbl-webapps/components';\nimport { CloseXIcon, ElevatedPaper, IconButton } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport Dialog from '@mui/material/Dialog';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { ExampleSummary, ExampleView, FormulaView } from './components';\n\ntype FeeFormulaDialogProps = {\n  open: boolean;\n  onClose: () => void;\n};\n\nexport const FeeFormulaDialog = ({ open, onClose }: FeeFormulaDialogProps) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice.feeFormulaDialog',\n  });\n  const [currentView, setCurrentView] = useState<'formulas' | 'example'>(\n    'formulas',\n  );\n\n  const handleClose = () => {\n    onClose();\n    setTimeout(() => setCurrentView('formulas'), 300);\n  };\n\n  return (\n    <Dialog\n      open={open}\n      onClose={handleClose}\n      fullWidth\n      PaperProps={{\n        style: { maxWidth: '432px', position: 'relative' },\n        elevation: 2,\n      }}\n      PaperComponent={ElevatedPaper}\n    >\n      <Box\n        width=\"100%\"\n        position=\"absolute\"\n        left={0}\n        display=\"flex\"\n        justifyContent=\"flex-end\"\n        pr={0.5}\n      >\n        <IconButton\n          variant=\"invisible\"\n          icon={<CloseXIcon />}\n          onClick={handleClose}\n        />\n      </Box>\n      <DialogTitle>{t('title')}</DialogTitle>\n      <DialogContent>\n        <Typography\n          fontSize={15}\n          fontWeight={400}\n          lineHeight=\"20px\"\n          color=\"gray.500\"\n        >\n          {t('description')}\n        </Typography>\n\n        <Box mt={4}>\n          <ButtonGroup\n            buttons={[\n              {\n                label: t('formulasButtonLabel'),\n                onClick: () => setCurrentView('formulas'),\n              },\n              {\n                label: t('exampleButtonLabel'),\n                onClick: () => setCurrentView('example'),\n                testId: 'example-view-button',\n              },\n            ]}\n          />\n        </Box>\n      </DialogContent>\n\n      <Box\n        bgcolor=\"gray.50\"\n        border=\"1px solid\"\n        borderColor=\"gray.100\"\n        borderRadius={2}\n      >\n        {currentView === 'formulas' ? <FormulaView /> : <ExampleView />}\n        <ExampleSummary open={currentView === 'example'} />\n      </Box>\n    </Dialog>\n  );\n};\n","import { DatePickerOcarinaLike } from '@finmid/tbl-webapps/components';\nimport { TextInputLabel } from '@finmid/ui/ocarina';\nimport { PopperPlacementType } from '@mui/base';\nimport {\n  Controller,\n  ControllerFieldState,\n  FieldPath,\n  FieldValues,\n  UseControllerProps,\n} from 'react-hook-form';\n\ntype FormDatePickerProps<\n  TFieldValues extends FieldValues,\n  TName extends FieldPath<TFieldValues>,\n> = UseControllerProps<TFieldValues, TName> & {\n  label: string;\n  disabled?: boolean;\n  disableFuture?: boolean;\n  maxDate?: Date;\n  minDate?: Date;\n  handleChange?: (data: Date | null) => Promise<void> | void;\n  fullWidth?: boolean;\n  required?: boolean;\n  testId?: string;\n  placement?: PopperPlacementType;\n};\n\nexport function InvoiceDueDatePickerOcarinaLike<\n  TFieldValues extends FieldValues,\n  TName extends FieldPath<TFieldValues>,\n>({\n  defaultValue,\n  label,\n  disabled = false,\n  disableFuture = false,\n  handleChange,\n  maxDate,\n  minDate,\n  fullWidth,\n  placement,\n  required = true,\n  testId,\n  ...props\n}: FormDatePickerProps<TFieldValues, TName>) {\n  const showError = (field: ControllerFieldState) =>\n    field.isDirty && !!field.error?.message;\n\n  return (\n    <div>\n      <TextInputLabel required={required}>{label}</TextInputLabel>\n      <Controller\n        {...props}\n        render={({ field: { ref, value, ...field }, fieldState }) => (\n          <DatePickerOcarinaLike\n            testId={testId}\n            disablePast\n            disabled={disabled}\n            value={(defaultValue ?? value) || null}\n            maxDate={maxDate}\n            minDate={minDate || new Date()}\n            onChange={(value) => {\n              field.onChange(value);\n              handleChange?.(value);\n            }}\n            placement={placement}\n            slotProps={{\n              textField: {\n                error: showError(fieldState),\n                helperText: showError(fieldState) && fieldState.error?.message,\n                onBlur: () => field.onBlur(),\n              },\n              popper: { disablePortal: true },\n            }}\n          />\n        )}\n      />\n    </div>\n  );\n}\n","import styled from '@emotion/styled';\nimport Box from '@mui/material/Box';\n\nexport const PaymentRequestDataRowContainer = styled(Box)(({ theme }) => ({\n  cursor: 'pointer',\n  padding: theme.spacing(2),\n\n  transition: 'background-color 300ms',\n\n  '&:hover': {\n    backgroundColor: theme.glo.color.foundations[10],\n  },\n}));\n","import { PaymentRequestStatus } from '@finmid/distributor-types';\nimport {\n  ArrowCirclepathIcon,\n  EllipsisCircleIcon,\n  MultiplyCircleIcon,\n  CheckmarkCircleIcon,\n  RepeatCircleIcon,\n} from '@finmid/ui/icons';\nimport { BadgeVariant } from '@finmid/ui/ocarina';\n\ntype StatusMapItemTypeNew = {\n  color: string;\n  translationKey: string;\n  variant: BadgeVariant;\n  // eslint-disable-next-line @typescript-eslint/no-explicit-any\n  icon: (props: any) => JSX.Element;\n};\n\nexport const paymentRequestStatusMapNew = {\n  PENDING: {\n    color: '#4d4f52', // temporary - default color too light to be seen\n    translationKey: 'created',\n    variant: 'neutral',\n    icon: EllipsisCircleIcon,\n  },\n\n  PROCESSING: {\n    color: '#1d91ff',\n    translationKey: 'financingStarted',\n    variant: 'running',\n    icon: ArrowCirclepathIcon,\n  },\n\n  PENDING_REPAYMENT: {\n    color: '#f29d2a',\n    translationKey: 'pendingRepayment',\n    variant: 'alert',\n    icon: RepeatCircleIcon,\n  },\n\n  CLOSED: {\n    color: '#2fb782',\n    translationKey: 'closed',\n    variant: 'success',\n    icon: CheckmarkCircleIcon,\n  },\n\n  CANCELLED: {\n    color: '#65758a',\n    translationKey: 'paymentCancelled',\n    variant: 'trivial',\n    icon: MultiplyCircleIcon,\n  },\n\n  DEFAULT: {\n    color: '#f1f5f9',\n    translationKey: 'default',\n    variant: 'danger',\n    icon: MultiplyCircleIcon,\n  },\n} as const satisfies Record<PaymentRequestStatus, StatusMapItemTypeNew>;\n\nexport const INACTIVE_STATUS_COLOR = 'gray.400';\nexport const INACTIVE_STATUS_COLOR_KEY = 'gray';\n","import { PaymentRequestStatus } from '@finmid/distributor-types';\nimport { Badge } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport { paymentRequestStatusMapNew } from './PaymentRequestStatusMap';\n\nexport type StatusTagProps = {\n  status: PaymentRequestStatus;\n};\n\nexport const PaymentRequestStatusTag = ({ status }: StatusTagProps) => {\n  const { t, ready } = useTranslation('invoicesPage', {\n    keyPrefix: 'status',\n  });\n\n  const { translationKey, variant } = paymentRequestStatusMapNew[status];\n\n  if (!ready) {\n    return null;\n  }\n\n  return <Badge label={t(translationKey)} variant={variant} />;\n};\n","import { Indicator } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport { paymentRequestStatusMapNew } from './PaymentRequestStatusMap';\nimport { StatusTagProps } from './PaymentRequestStatusTag';\n\nexport const PaymentRequestStatusIndicator = ({ status }: StatusTagProps) => {\n  const { t, ready } = useTranslation('invoicesPage', {\n    keyPrefix: 'status',\n  });\n\n  const { translationKey, variant } = paymentRequestStatusMapNew[status];\n\n  return (\n    <Indicator\n      tooltip={ready ? t(translationKey) : ''}\n      variant={variant}\n      data-test-id=\"payment-request-status-indicator\"\n    />\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport type { PaymentRequest } from '@finmid/distributor-types';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { useDetectTruncated } from '@finmid/tbl-webapps/hooks';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { useFormat } from '@finmid/translations';\nimport { Tooltip } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useRef } from 'react';\nimport { useNavigate } from 'react-router-dom';\n\nimport { PaymentRequestDataRowContainer } from './PaymentRequestDataRow.styled';\nimport { PaymentRequestStatusIndicator } from './PaymentRequestStatus';\n\nexport const PaymentRequestDataRow = ({\n  paymentRequest,\n}: {\n  paymentRequest: PaymentRequest;\n}) => {\n  const { dateDots, money } = useFormat();\n  const theme = useTheme();\n  const idRef = useRef<HTMLParagraphElement>(null);\n  const isTruncated = useDetectTruncated(idRef);\n  const navigate = useNavigate();\n\n  const goToPaymentRequestDetails = () =>\n    navigate(`${b2bPaymentRoutes.paymentRequests}?view=${paymentRequest.id}`);\n\n  return (\n    <PaymentRequestDataRowContainer onClick={goToPaymentRequestDetails}>\n      <Typography\n        color={theme.glo.color.foundations[60]}\n        fontSize={13}\n        fontWeight={500}\n        lineHeight=\"16px\"\n        numeric\n      >\n        {dateDots(new Date(paymentRequest.creationTime))}\n      </Typography>\n      <Box\n        display={'flex'}\n        justifyContent={'space-between'}\n        alignItems={'center'}\n        marginTop=\"4px\"\n      >\n        <Box>\n          <PaymentRequestStatusIndicator status={paymentRequest.status} />\n        </Box>\n\n        <Tooltip title={paymentRequest.id} disableHoverListener={!isTruncated}>\n          <Typography\n            ref={idRef}\n            fontSize={15}\n            lineHeight=\"20px\"\n            fontWeight={400}\n            whiteSpace=\"nowrap\"\n            overflow=\"hidden\"\n            textOverflow=\"ellipsis\"\n            marginLeft={1}\n            numeric\n            maxWidth={215}\n            onClick={(e) => e.stopPropagation()}\n          >\n            {paymentRequest.id}\n          </Typography>\n        </Tooltip>\n\n        <Typography\n          marginLeft={'auto'}\n          numeric\n          onClick={(e) => e.stopPropagation()}\n        >\n          {money(paymentRequest.totalAmount, paymentRequest.currency)}\n        </Typography>\n      </Box>\n    </PaymentRequestDataRowContainer>\n  );\n};\n","import { Alert, Typography } from '@finmid/tbl-webapps/components';\nimport { useCallback } from 'react';\nimport { FileRejection } from 'react-dropzone';\nimport { useTranslation } from 'react-i18next';\n\ntype FileErrorsProps = {\n  fileErrors: FileRejection[];\n};\n\nconst useCustomDropzoneErrors = () => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'validation',\n  });\n\n  const getCustomDropzoneErrors = useCallback(\n    (errorCode: string) => {\n      let message: string;\n      switch (errorCode) {\n        case 'file-invalid-type':\n          message = t('file.invalidTypeCsv');\n          break;\n        case 'too-many-files':\n          message = t('file.tooMany', { maxFiles: 1 });\n          break;\n        default:\n          message = t('file.fallbackMessage');\n          break;\n      }\n\n      return message;\n    },\n    [t],\n  );\n\n  return { getCustomDropzoneErrors };\n};\n\nexport const CsvDropzoneFileErrors = ({ fileErrors }: FileErrorsProps) => {\n  const { getCustomDropzoneErrors } = useCustomDropzoneErrors();\n\n  return (\n    <Alert severity=\"warning\" data-test-id=\"invalid-files\">\n      {fileErrors[0].errors.map(({ code }, index) => (\n        <Typography key={code + index}>\n          {getCustomDropzoneErrors(code)}\n        </Typography>\n      ))}\n    </Alert>\n  );\n};\n","export const formatNumberWithDecimals = (amount?: number) => {\n  if (amount) {\n    return amount.toString().includes('.')\n      ? amount.toFixed(2)\n      : amount.toString();\n  }\n  return '';\n};\n","import { PayoutStatus } from '@finmid/distributor-types';\nimport { IndicatorProps } from '@finmid/ui/ocarina';\n\nexport const payoutStatusIndicatorColor: Record<\n  PayoutStatus,\n  IndicatorProps['variant']\n> = {\n  PAID_OUT: 'success',\n  PENDING: {\n    backgroundColor: '#31A5FF',\n    borderColor: '#0D68BD',\n  },\n  REJECTED: 'danger',\n};\n","import { PayoutStatus } from '@finmid/distributor-types';\nimport { Indicator, TooltipProps } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport { payoutStatusIndicatorColor } from './payoutStatusIndicatorColor';\n\ntype PayoutStatusIndicatorProps = {\n  status: PayoutStatus | null;\n  tooltipPlacement?: TooltipProps['placement'];\n};\n\nconst payoutStatusLabelMap = {\n  PAID_OUT: 'booked',\n  PENDING: 'underReview',\n  REJECTED: 'rejected',\n} as const satisfies Record<PayoutStatus, string>;\n\nexport const PayoutStatusIndicator = ({\n  status,\n  tooltipPlacement,\n}: PayoutStatusIndicatorProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'payoutStatus' });\n\n  if (status == null) return null;\n\n  return (\n    <Indicator\n      variant={payoutStatusIndicatorColor[status]}\n      tooltip={t(payoutStatusLabelMap[status])}\n      tooltipPlacement={tooltipPlacement}\n    />\n  );\n};\n","import { useGetPaymentRequestsCsvTemplateQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { CSV_TEMPLATE_FILENAME } from '@finmid/tbl-webapps/utils';\nimport { useEffect, useState } from 'react';\n\nexport const useCsvTemplateDownloadUrl = () => {\n  const { data } = useGetPaymentRequestsCsvTemplateQuery();\n  const [url, setUrl] = useState<string>();\n\n  useEffect(() => {\n    if (data == null) return;\n\n    const csvData = new Blob([data], { type: 'text/csv' });\n    const csvUrl = URL.createObjectURL(csvData);\n\n    setUrl(csvUrl);\n  }, [data]);\n\n  return { url, fileName: CSV_TEMPLATE_FILENAME };\n};\n","import { TranslationKey } from '@finmid/tbl-webapps/translations';\nimport { useTranslation } from 'react-i18next';\n\n/**\n * Use-case ids come from the platform-configuration API, so the key space is\n * server-driven and cannot be enumerated from the JSON.\n */\ntype UseCaseKey = TranslationKey<'useCases', 'option'>;\n\nconst optionKey = (useCase: string, field: 'title' | 'description') =>\n  `${useCase}.${field}` as UseCaseKey;\n\nexport const useUseCaseCopy = () => {\n  const { t, i18n } = useTranslation('useCases', { keyPrefix: 'option' });\n\n  const title = (useCase: string) => t(optionKey(useCase, 'title'));\n\n  // A use case with no description yet must render nothing rather than a raw key.\n  const describe = (useCase: string) =>\n    i18n.exists(`option.${useCase}.description`, { ns: 'useCases' })\n      ? t(optionKey(useCase, 'description'))\n      : undefined;\n\n  return { title, describe };\n};\n","import { withErrorProps } from '@finmid/tbl-webapps/components';\nimport {\n  useDisplayErrorToast,\n  useDisplayErrorToUser,\n} from '@finmid/tbl-webapps/errors-handling';\nimport {\n  useCheckPaymentRequestsCsvFileMutation,\n  useCreatePaymentRequestsBulkMutation,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport posthog from 'posthog-js';\nimport { useEffect } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nexport const useCreateMultiplePaymentRequestsPage = (file: File | null) => {\n  const navigate = useNavigate();\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createBulk' });\n  const { notifySuccess, notifyError } = useNotifications();\n  const { displayErrorToUser } = useDisplayErrorToUser({});\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const [checkCsvFile, { isLoading: checkLoading, error, data, reset }] =\n    useCheckPaymentRequestsCsvFileMutation();\n  const [createBulk, { isLoading: submitLoading }] =\n    useCreatePaymentRequestsBulkMutation();\n\n  useEffect(() => {\n    if (file != null) {\n      checkCsvFile({ file });\n    }\n  }, [checkCsvFile, file]);\n\n  useEffect(() => {\n    if (error != null) {\n      displayErrorToast(\n        withErrorProps({\n          ...(error as Error),\n          message: t('notification.checkFailure'),\n        }),\n      );\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, [error]);\n\n  const submitBulk = async () => {\n    if (data == null) return;\n\n    posthog.capture('bulk_upload_submit');\n\n    try {\n      const { created, failed } = await createBulk(data.data).unwrap();\n      navigate(b2bPaymentRoutes.paymentRequests);\n\n      if (created.length > 0) {\n        notifySuccess(\n          t('notification.createdSuccess', { amount: created.length }),\n        );\n      }\n\n      if (failed.length > 0) {\n        notifyError(\n          t('notification.createdFailure', {\n            IDs: failed.flatMap(({ id }) => id).join(', '),\n          }),\n        );\n      }\n    } catch (error) {\n      displayErrorToUser(error);\n    }\n  };\n\n  return {\n    submitBulk,\n    submitLoading,\n    checkLoading,\n    checkResponse: data,\n    resetCheck: reset,\n  };\n};\n","import {\n  createContext,\n  Dispatch,\n  PropsWithChildren,\n  SetStateAction,\n  useContext,\n  useEffect,\n  useState,\n} from 'react';\nimport { useLocation, useNavigate } from 'react-router-dom';\n\ntype Context = {\n  file: File | null;\n  setFile: Dispatch<SetStateAction<File | null>>;\n};\n\nexport const FileContext = createContext<Context | null>(null);\n\nexport const FileContextProvider = ({ children }: PropsWithChildren) => {\n  const location = useLocation();\n  const navigate = useNavigate();\n\n  // store file from location state to context\n  const [file, setFile] = useState<File | null>(location.state?.file ?? null);\n\n  // remove file from location state & history\n  useEffect(() => {\n    navigate('.', { replace: true });\n  }, [navigate]);\n\n  return (\n    <FileContext.Provider value={{ file, setFile }}>\n      {children}\n    </FileContext.Provider>\n  );\n};\n\nexport const useFileContext = () => {\n  const context = useContext(FileContext);\n\n  if (context == null) {\n    throw new Error(\n      'useFileContext can only be used inside FileContextProvider',\n    );\n  }\n\n  return context;\n};\n","export const BOTTOM_ACTION_BAR_HEIGHT = '88px';\n","import styled from '@emotion/styled';\nimport { Button, Typography } from '@finmid/tbl-webapps/components';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\n\nimport { BOTTOM_ACTION_BAR_HEIGHT } from '../constants';\n\nconst BottomActionBarContainer = styled(Box)(({ theme }) => ({\n  width: '100%',\n  height: BOTTOM_ACTION_BAR_HEIGHT,\n  borderTop: '1px solid',\n  borderColor: theme.glo.color.foundations[20],\n  backgroundColor: theme.glo.color.foundations[10],\n  position: 'fixed',\n  bottom: 0,\n  left: 0,\n  display: 'flex',\n  flexDirection: 'column',\n  alignItems: 'center',\n  gap: theme.spacing(1),\n  padding: theme.spacing(2),\n}));\n\ntype BottomActionBarProps = {\n  disabled: boolean;\n  onClick: () => void;\n  isLoading: boolean;\n};\n\nexport const BottomActionBar = ({\n  disabled,\n  onClick,\n  isLoading,\n}: BottomActionBarProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createBulk' });\n\n  return (\n    <BottomActionBarContainer>\n      <Button\n        disabled={disabled}\n        onClick={onClick}\n        loading={isLoading}\n        variant=\"primary\"\n        testId=\"create-bulk\"\n      >\n        {t('submit.btnLabel')}\n      </Button>\n      <Typography\n        fontSize={13}\n        lineHeight=\"16px\"\n        fontWeight={500}\n        color=\"gray.500\"\n      >\n        {t('submit.disclaimer')}\n      </Typography>\n    </BottomActionBarContainer>\n  );\n};\n","import { CheckCsvFile } from '@finmid/distributor-types';\n\nexport type FileStatus = 'loading' | 'idle' | 'error' | 'empty' | 'success';\n\nexport const useDataStatus = ({\n  data,\n  isLoading,\n}: {\n  data: CheckCsvFile.GatewayResponse | undefined;\n  isLoading: boolean;\n}): FileStatus => {\n  if (isLoading) return 'loading';\n  if (data == null) return 'idle';\n  if (data.isValid === false) return 'error';\n  if (data.data.length === 0) return 'empty';\n\n  return 'success';\n};\n","import { BadgeVariant } from '@finmid/ui/ocarina';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { FileStatus } from './useDataStatus';\n\nexport const useFileStatus = () => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createBulk.fileStatus',\n  });\n\n  const variants: Record<FileStatus, BadgeVariant> = {\n    success: 'success',\n    empty: 'alert',\n    error: 'danger',\n    idle: 'neutral',\n    loading: 'running',\n  };\n\n  const labels: Record<FileStatus, string> = useMemo(\n    () => ({\n      success: t('success'),\n      empty: t('empty'),\n      error: t('invalid'),\n      idle: t('pendingCheck'),\n      loading: t('processing'),\n    }),\n    [t],\n  );\n\n  return { labels, variants };\n};\n","import { useDistributorCurrencies } from '@finmid/tbl-webapps/hooks';\nimport { minInvoiceDueDateThreshold } from '@finmid/tbl-webapps/utils';\nimport { useCallback } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nexport const useDataErrorMessages = () => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'validation.csvData',\n  });\n  const { supportedCurrencies } = useDistributorCurrencies();\n\n  const getDataErrorMessage = useCallback(\n    ({\n      code,\n      message: beFallbackMessage,\n    }: {\n      code: string;\n      message: string;\n    }) => {\n      let message: string;\n      switch (code) {\n        // payment request ID\n        case 'EMPTY_ID':\n          message = t('paymentRequestId.empty');\n          break;\n        case 'DUPLICATE_ID':\n          message = t('paymentRequestId.exists');\n          break;\n        case 'DUPLICATE_ID_IN_CSV':\n          message = t('paymentRequestId.notUnique');\n          break;\n\n        // invoice due date\n        case 'EMPTY_INVOICE_DUE_DATE':\n          message = t('invoiceDueDate.empty');\n          break;\n        case 'INVOICE_DUE_DATE_IS_NOT_A_DATE':\n          message = t('invoiceDueDate.invalidDate');\n          break;\n        case 'INVOICE_DUE_DATE_IS_TOO_SHORT':\n          message = t('invoiceDueDate.tooEarly', {\n            threshold: minInvoiceDueDateThreshold,\n          });\n          break;\n        case 'INVOICE_DUE_DATE_OUT_OF_TERMS':\n          message = t('invoiceDueDate.exceedsTerm');\n          break;\n\n        // invoice number\n        case 'EMPTY_INVOICE_NUMBER':\n          message = t('invoiceNumber.empty');\n          break;\n        case 'DUPLICATE_INVOICE_NUMBER':\n          message = t('invoiceNumber.exists');\n          break;\n        case 'DUPLICATE_INVOICE_NUMBER_IN_CSV':\n          message = t('invoiceNumber.notUnique');\n          break;\n\n        // buyer\n        case 'EMPTY_BUYER_ID':\n          message = t('buyerId.empty');\n          break;\n        case 'BUYER_NOT_FOUND_OR_INACTIVE':\n          message = t('buyerId.notFoundOrInactive');\n          break;\n        case 'BUYER_EXPENSE_LIMIT_EXCEEDED':\n          message = t('buyerId.limitExceeded');\n          break;\n        case 'BUYER_COMBINED_EXPENSE_LIMIT_EXCEEDED':\n          message = t('buyerId.combinedLimitExceeded');\n          break;\n\n        // seller\n        case 'EMPTY_SELLER_ID':\n          message = t('sellerId.empty');\n          break;\n        case 'SELLER_NOT_FOUND_OR_INACTIVE':\n          message = t('sellerId.notFoundOrInactive');\n          break;\n\n        // currency\n        case 'EMPTY_CURRENCY':\n          message = t('currency.empty');\n          break;\n        case 'CURRENCY_NOT_SUPPORTED_BY_SELLER':\n          message = t('currency.notSupportedBySeller');\n          break;\n        case 'NOT_SUPPORTED_CURRENCY':\n          message = t('currency.notSupported', {\n            supportedCurrencies: supportedCurrencies.join(', '),\n          });\n          break;\n\n        // total amount\n        case 'EMPTY_TOTAL_AMOUNT':\n          message = t('totalAmount.empty');\n          break;\n        case 'TOTAL_AMOUNT_IS_LESS_THAN_ZERO':\n          message = t('totalAmount.negative');\n          break;\n        case 'TOTAL_AMOUNT_IS_NOT_A_NUMBER':\n          message = t('totalAmount.notANumber');\n          break;\n        case 'FEES_TOO_LOW':\n          message = t('totalAmount.feesTooLow');\n          break;\n        case 'FEES_EXCEED_TOTAL_AMOUNT':\n          message = t('totalAmount.feesExceedTotalAmount');\n          break;\n        default:\n          message = beFallbackMessage;\n          break;\n      }\n\n      return message;\n    },\n    [supportedCurrencies, t],\n  );\n\n  return getDataErrorMessage;\n};\n","import { CheckCsvFile } from '@finmid/distributor-types';\nimport { GridColDef } from '@mui/x-data-grid';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useDataErrorMessages } from '../hooks';\n\nexport const useColumns = (): {\n  columns: GridColDef[];\n  numberColumn: Pick<GridColDef, 'field' | 'headerName' | 'width'>;\n} => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'table' });\n  const getDataErrorMessage = useDataErrorMessages();\n\n  const columns = useMemo(\n    () =>\n      [\n        {\n          field: 'field',\n          headerName: t('headerPaymentRequestErrorField'),\n          sortable: false,\n          filterable: false,\n          flex: 0.4,\n          maxWidth: 400,\n          minWidth: 100,\n          renderCell: ({ row: { field } }) => (\n            <div>\n              <code\n                css={({ glo }) => ({\n                  backgroundColor: glo.color.foundations[10],\n                  padding: '0 4px',\n                  borderRadius: 4,\n                })}\n              >\n                {field}\n              </code>\n            </div>\n          ),\n        },\n        {\n          field: 'message',\n          headerName: t('headerPaymentRequestErrorMessage'),\n          sortable: false,\n          filterable: false,\n          flex: 1,\n          minWidth: 100,\n          renderCell: ({ row: { message, code } }) => (\n            <div\n              style={{\n                overflow: 'hidden',\n                textOverflow: 'ellipsis',\n              }}\n            >\n              {getDataErrorMessage({ code, message })}\n            </div>\n          ),\n        },\n        {\n          field: 'value',\n          headerName: t('headerPaymentRequestErrorValue'),\n          sortable: false,\n          filterable: false,\n          flex: 0.6,\n          minWidth: 100,\n          renderCell: ({ row: { value } }) => (\n            <div\n              style={{\n                overflow: 'hidden',\n                textOverflow: 'ellipsis',\n              }}\n            >\n              {value}\n            </div>\n          ),\n        },\n      ] as GridColDef<CheckCsvFile.ExtendedFieldError>[],\n    [getDataErrorMessage, t],\n  );\n\n  const numberColumn = useMemo(\n    () => ({\n      field: 'line',\n      headerName: t('headerPaymentRequestErrorRow'),\n      width: 60,\n    }),\n    [t],\n  );\n\n  return { columns, numberColumn };\n};\n","import { CheckCsvFile } from '@finmid/distributor-types';\nimport {\n  ErrorBoundary,\n  LazyLoadFallback,\n} from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { lazy, Suspense } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useColumns } from './DataErrorsTable.hook';\n\nconst DataGrid = lazy(() => import('@finmid/tbl-webapps/components/DataGrid'));\n\ntype DataErrorsTableProps = {\n  data: CheckCsvFile.GatewayResponse;\n};\n\nexport const DataErrorsTable = ({ data }: DataErrorsTableProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createBulk' });\n  const { columns, numberColumn } = useColumns();\n\n  if (data.isValid) return null;\n\n  return (\n    <ErrorBoundary fallback={<LazyLoadFallback />}>\n      <Suspense fallback={<Loader />}>\n        <DataGrid\n          testId=\"csv-payment-requests-errors\"\n          disableColumnMenu\n          rows={data.errors}\n          columns={columns}\n          numberColumn={numberColumn}\n          getRowId={(row) => row.id}\n          toolbar={{\n            title: t('errorsTable.title'),\n          }}\n        />\n      </Suspense>\n    </ErrorBoundary>\n  );\n};\n","import styled from '@emotion/styled';\nimport Box from '@mui/material/Box';\nimport Collapse from '@mui/material/Collapse';\n\nexport const CollapsibleDropzoneArea = styled(Collapse)(\n  ({ theme: { glo } }) => ({\n    width: '100%',\n\n    backgroundColor: glo.color.foundations[10],\n\n    border: '1px dashed',\n    borderColor: glo.color.foundations[20],\n    borderRadius: 12,\n\n    cursor: 'pointer',\n  }),\n);\n\nexport const InnerDropzoneArea = styled(Box)({\n  display: 'flex',\n  justifyContent: 'center',\n  alignItems: 'center',\n});\n","import { DropzoneEmptyState } from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport Dropzone, { FileRejection } from 'react-dropzone';\n\nimport { FileStatus } from '../../hooks';\n\nimport {\n  CollapsibleDropzoneArea,\n  InnerDropzoneArea,\n} from './PaymentRequestCsvDropzone.styled';\n\ntype PaymentRequestCsvDropzoneProps = {\n  onDrop: (acceptedFiles: File[], fileRejections: FileRejection[]) => void;\n  dropzoneTitle: string;\n  hideDropzoneIcon: boolean;\n  status: FileStatus;\n  collapse?: boolean;\n};\n\nexport const PaymentRequestCsvDropzone = ({\n  onDrop,\n  dropzoneTitle,\n  hideDropzoneIcon,\n  status,\n  collapse = false,\n}: PaymentRequestCsvDropzoneProps) => {\n  return (\n    <Dropzone\n      useFsAccessApi={false} // https://github.com/react-dropzone/react-dropzone/discussions/1339\n      onDrop={onDrop}\n      accept={{ 'text/csv': ['.csv'] }}\n      multiple={false}\n      disabled={status === 'loading'}\n    >\n      {({ getRootProps, getInputProps }) => (\n        <CollapsibleDropzoneArea\n          {...getRootProps()}\n          in={!collapse}\n          unmountOnExit\n        >\n          <InnerDropzoneArea\n            sx={{\n              height:\n                status === 'loading' || status === 'error' || status === 'empty'\n                  ? 164\n                  : 250,\n              transition: 'height 100ms ease-out',\n            }}\n          >\n            <input {...getInputProps()} data-test-id=\"drop-files-input\" />\n            <Box\n              display=\"flex\"\n              flexDirection=\"column\"\n              alignItems=\"center\"\n              textAlign=\"center\"\n              data-test-id=\"drop-files-box\"\n            >\n              {status !== 'loading' ? (\n                <DropzoneEmptyState\n                  title={dropzoneTitle}\n                  withIcon={!hideDropzoneIcon}\n                />\n              ) : (\n                <Box width={36} height={36} position=\"relative\">\n                  <Loader size={36} />\n                </Box>\n              )}\n            </Box>\n          </InnerDropzoneArea>\n        </CollapsibleDropzoneArea>\n      )}\n    </Dropzone>\n  );\n};\n","import { CheckCsvFile, TBLCurrency } from '@finmid/distributor-types';\nimport { useDistributorCurrencies } from '@finmid/tbl-webapps/hooks';\nimport { useFormat } from '@finmid/translations';\nimport { GridColDef } from '@mui/x-data-grid';\nimport currencyJs from 'currency.js';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\ntype TableData = CheckCsvFile.GatewayResponse['data'][number];\n\nexport const useColumns = (): GridColDef[] => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'table' });\n  const { money, date } = useFormat();\n  const { defaultCurrency, supportedCurrencies } = useDistributorCurrencies();\n\n  return useMemo(\n    () =>\n      [\n        {\n          field: 'id',\n          headerName: t('headerPaymentRequestId'),\n          sortable: false,\n          filterable: false,\n          flex: 1,\n          minWidth: 100,\n          renderCell: ({ row: { id } }) => (\n            <div\n              style={{\n                overflow: 'hidden',\n                textOverflow: 'ellipsis',\n              }}\n            >\n              {id}\n            </div>\n          ),\n        },\n        {\n          field: 'buyerId',\n          headerName: t('headerBuyerId'),\n          sortable: false,\n          filterable: false,\n          flex: 1,\n          minWidth: 100,\n          renderCell: ({ row: { buyerId } }) => (\n            <div\n              style={{\n                overflow: 'hidden',\n                textOverflow: 'ellipsis',\n              }}\n            >\n              {buyerId}\n            </div>\n          ),\n        },\n        {\n          field: 'buyerName',\n          headerName: t('headerBuyerName'),\n          sortable: false,\n          filterable: false,\n          flex: 1,\n          minWidth: 100,\n          renderCell: ({ row: { buyerName } }) => (\n            <div\n              style={{\n                overflow: 'hidden',\n                textOverflow: 'ellipsis',\n              }}\n            >\n              {buyerName}\n            </div>\n          ),\n        },\n        {\n          field: 'sellerId',\n          headerName: t('headerSellerId'),\n          sortable: false,\n          filterable: false,\n          flex: 1,\n          minWidth: 100,\n          renderCell: ({ row: { sellerId } }) => (\n            <div\n              style={{\n                overflow: 'hidden',\n                textOverflow: 'ellipsis',\n              }}\n            >\n              {sellerId}\n            </div>\n          ),\n        },\n        {\n          field: 'totalAmount',\n          headerName: t('headerAmount'),\n          sortable: false,\n          filterable: false,\n          align: 'right',\n          headerAlign: 'right',\n          flex: 1,\n          minWidth: 130,\n          renderCell: ({ row: { totalAmount, currency } }) => {\n            const currencyIndex = supportedCurrencies.indexOf(\n              currency as TBLCurrency,\n            );\n            const renderCurrency =\n              currencyIndex !== -1\n                ? supportedCurrencies[currencyIndex]\n                : defaultCurrency;\n\n            return money(currencyJs(totalAmount), renderCurrency);\n          },\n        },\n        {\n          field: 'currency',\n          headerName: t('headerCurrency'),\n          sortable: false,\n          filterable: false,\n          align: 'right',\n          headerAlign: 'right',\n        },\n        {\n          field: 'invoiceDueDate',\n          headerName: t('headerInvoiceDueDate'),\n          sortable: false,\n          filterable: false,\n          align: 'right',\n          headerAlign: 'right',\n          minWidth: 140,\n          renderCell: ({ row: { invoiceDueDate } }) =>\n            date(new Date(invoiceDueDate)),\n        },\n        {\n          field: 'invoiceNumber',\n          headerName: t('headerInvoiceNumber'),\n          sortable: false,\n          filterable: false,\n          align: 'right',\n          headerAlign: 'right',\n          flex: 0.8,\n          minWidth: 100,\n          renderCell: ({ row: { invoiceNumber } }) => (\n            <div\n              style={{\n                overflow: 'hidden',\n                textOverflow: 'ellipsis',\n              }}\n            >\n              {invoiceNumber}\n            </div>\n          ),\n        },\n      ] as GridColDef<TableData>[],\n    [date, defaultCurrency, money, supportedCurrencies, t],\n  );\n};\n","import { CheckCsvFile } from '@finmid/distributor-types';\nimport {\n  ErrorBoundary,\n  LazyLoadFallback,\n} from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { lazy, Suspense } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useColumns } from './PaymentRequestsDataTable.hook';\n\nconst DataGrid = lazy(() => import('@finmid/tbl-webapps/components/DataGrid'));\n\ntype PaymentRequestsDataTableProps = {\n  paymentRequestsData: CheckCsvFile.GatewayResponse['data'];\n};\n\nexport const PaymentRequestsDataTable = ({\n  paymentRequestsData,\n}: PaymentRequestsDataTableProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createBulk' });\n  const columns = useColumns();\n\n  return (\n    <ErrorBoundary fallback={<LazyLoadFallback />}>\n      <Suspense fallback={<Loader />}>\n        <DataGrid\n          testId=\"csv-payment-requests-data\"\n          disableColumnMenu\n          rows={paymentRequestsData}\n          columns={columns}\n          toolbar={{\n            title: t('dataTable.title'),\n          }}\n        />\n      </Suspense>\n    </ErrorBoundary>\n  );\n};\n","import { Button, Banner } from '@finmid/tbl-webapps/components';\nimport {\n  BadgeVariant,\n  CheckmarkCircleIcon,\n  DownloadIcon,\n  InfoIcon,\n  Loader,\n  WarningIcon,\n} from '@finmid/ui/ocarina';\nimport posthog from 'posthog-js';\nimport { useCallback } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { useCsvTemplateDownloadUrl } from '../../../shared';\nimport { FileStatus } from '../../hooks';\n\ntype StatusBannerProps = {\n  status: FileStatus;\n  amountValid: number;\n  hasInvalidTemplate: boolean;\n};\n\nconst statusMessageKeyMap = {\n  idle: 'instructions',\n  empty: 'emptyFile',\n  error: 'invalidData',\n  loading: 'processingData',\n  success: 'validData',\n} as const satisfies Record<FileStatus, string>;\n\nconst statusBadgeVariantMap: Record<FileStatus, BadgeVariant> = {\n  idle: 'neutral',\n  empty: 'alert',\n  error: 'danger',\n  loading: 'running',\n  success: 'success',\n};\n\nconst statusIconMap: Record<FileStatus, JSX.Element> = {\n  idle: <InfoIcon />,\n  empty: <InfoIcon />,\n  error: <WarningIcon />,\n  loading: <Loader size={17} color=\"inherit\" />,\n  success: <CheckmarkCircleIcon />,\n};\n\nexport const StatusBanner = ({\n  status,\n  amountValid,\n  hasInvalidTemplate,\n}: StatusBannerProps) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createBulk.statusNotification',\n  });\n\n  const { url, fileName } = useCsvTemplateDownloadUrl();\n\n  const handleDownload = useCallback(() => {\n    if (url == null) return;\n\n    posthog.capture('bulk_upload_download_template');\n    const anchor = document.createElement('a');\n    anchor.href = url;\n    anchor.download = fileName;\n    document.body.appendChild(anchor);\n    anchor.click();\n  }, [url, fileName]);\n\n  return (\n    <Banner\n      variant={statusBadgeVariantMap[status]}\n      icon={statusIconMap[status]}\n      action={\n        status === 'idle' || hasInvalidTemplate ? (\n          <Button\n            size=\"s\"\n            variant=\"invisible\"\n            suffixIcon={<DownloadIcon />}\n            onClick={handleDownload}\n            disabled={!url}\n            testId=\"download-csv-template-btn\"\n          >\n            {t('downloadTemplate')}\n          </Button>\n        ) : undefined\n      }\n    >\n      <Trans\n        t={t}\n        i18nKey={\n          hasInvalidTemplate ? 'invalidTemplate' : statusMessageKeyMap[status]\n        }\n        values={{\n          amountValid,\n        }}\n        components={{\n          b: <strong />,\n        }}\n      />\n    </Banner>\n  );\n};\n","import { File, Typography } from '@finmid/tbl-webapps/components';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { FileRejection } from 'react-dropzone';\nimport { useTranslation } from 'react-i18next';\n\nimport { CsvDropzoneFileErrors } from '../shared';\n\nimport { useCreateMultiplePaymentRequestsPage } from './CreateMultiplePaymentRequestsPage.hook';\nimport { useFileContext } from './FileContext';\nimport {\n  BottomActionBar,\n  DataErrorsTable,\n  PaymentRequestCsvDropzone,\n  PaymentRequestsDataTable,\n  StatusBanner,\n} from './components';\nimport { useDataStatus, useFileStatus } from './hooks';\n\nexport const CreateMultiplePaymentRequestsPageInner = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createBulk' });\n\n  const { file, setFile } = useFileContext();\n  const [fileErrors, setFileErrors] = useState<FileRejection[]>([]);\n\n  const { checkResponse, checkLoading, submitBulk, submitLoading, resetCheck } =\n    useCreateMultiplePaymentRequestsPage(file);\n\n  const status = useDataStatus({\n    data: checkResponse,\n    isLoading: checkLoading,\n  });\n  const { labels, variants } = useFileStatus();\n\n  const addFile = (newFiles: File[], rejectedFiles: FileRejection[]) => {\n    posthog.capture('bulk_upload_add_file');\n\n    setFile(newFiles[0]);\n    setFileErrors(rejectedFiles);\n  };\n\n  const isError = checkResponse != null && status === 'error';\n  const hasInvalidTemplate = checkResponse?.reason === 'INVALID_HEADERS';\n\n  return (\n    <>\n      <Typography fontSize={24} lineHeight=\"32px\" fontWeight={700}>\n        {t('pageTitle')}\n      </Typography>\n\n      <Spacer height={4} />\n\n      <Box display=\"flex\" flexDirection=\"column\" gap={2}>\n        <PaymentRequestCsvDropzone\n          status={status}\n          dropzoneTitle={\n            file == null\n              ? t('dropzone.emptyState.initial')\n              : t('dropzone.emptyState.reUpload')\n          }\n          hideDropzoneIcon={file != null}\n          onDrop={addFile}\n          collapse={status === 'success'}\n        />\n\n        {file != null && (\n          <File\n            testId=\"csv-file\"\n            file={file}\n            statusVariant={variants[status]}\n            statusLabel={labels[status]}\n            onRemove={() => {\n              posthog.capture('bulk_upload_remove_file');\n\n              setFile(null);\n              resetCheck();\n            }}\n          />\n        )}\n\n        {fileErrors.length > 0 ? (\n          <CsvDropzoneFileErrors fileErrors={fileErrors} />\n        ) : null}\n\n        <StatusBanner\n          status={status}\n          hasInvalidTemplate={hasInvalidTemplate}\n          amountValid={checkResponse?.data.length ?? 0}\n        />\n\n        {checkResponse != null && status === 'success' && (\n          <PaymentRequestsDataTable paymentRequestsData={checkResponse.data} />\n        )}\n\n        {isError && !hasInvalidTemplate && (\n          <DataErrorsTable data={checkResponse} />\n        )}\n      </Box>\n\n      <BottomActionBar\n        disabled={!checkResponse?.isValid || checkResponse.data.length < 1}\n        onClick={submitBulk}\n        isLoading={submitLoading}\n      />\n    </>\n  );\n};\n","import { Button, Page, PageNavigation } from '@finmid/tbl-webapps/components';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { Loader } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { CreateMultiplePaymentRequestsPageInner } from './CreateMultiplePaymentRequestsPageInner';\nimport { FileContextProvider } from './FileContext';\nimport { BOTTOM_ACTION_BAR_HEIGHT } from './constants';\n\nexport const CreateMultiplePaymentRequestsPage = () => {\n  const { t, ready } = useTranslation('invoicesPage');\n  const { ready: componentsReady } = useTranslation('components');\n  const navigate = useNavigate();\n  const breadcrumbs = useBreadcrumbs();\n\n  const translationsReady = ready && componentsReady;\n\n  return (\n    <FileContextProvider>\n      <PageNavigation breadcrumbs={breadcrumbs.createMultiplePaymentRequests}>\n        {ready && (\n          <Button\n            variant=\"invisible\"\n            onClick={() => navigate(b2bPaymentRoutes.paymentRequests)}\n          >\n            {t('createBulk.cancelBtn')}\n          </Button>\n        )}\n      </PageNavigation>\n      <Page>\n        <Box maxWidth={1440} mx=\"auto\" mb={BOTTOM_ACTION_BAR_HEIGHT}>\n          {!translationsReady && <Loader />}\n\n          {translationsReady && <CreateMultiplePaymentRequestsPageInner />}\n        </Box>\n      </Page>\n    </FileContextProvider>\n  );\n};\n","/**\n * Today as the backend dates a capture: the current UTC calendar day, as a local date for the date pickers.\n * Counting from the browser's own day puts the due date bounds a day ahead of the backend's between local\n * midnight and UTC midnight, and the payment request is then rejected on capture.\n */\nexport const getBusinessToday = (now = new Date()) =>\n  new Date(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate());\n","import { CheckPaymentRequest } from '@finmid/distributor-types';\nimport { differenceInDays } from 'date-fns';\n\ntype GetClosestRepaymentTerm = {\n  repaymentMethods: CheckPaymentRequest.GatewayResponse['repaymentMethods'];\n  date?: Date;\n};\n\nexport const getClosestRepaymentTerm = ({\n  repaymentMethods,\n  date,\n}: GetClosestRepaymentTerm) => {\n  const targetDate = date ?? new Date();\n  const daysDifference = differenceInDays(targetDate, new Date());\n\n  const validTerms = repaymentMethods.filter(\n    ({ period }) => period >= daysDifference,\n  );\n\n  if (validTerms.length === 0) return null;\n\n  return validTerms.reduce((closest, term) =>\n    term.period < closest.period ? term : closest,\n  );\n};\n","import { addDays, endOfDay } from 'date-fns';\n\nimport { getBusinessToday } from './getBusinessToday';\n\nexport const getMaxInvoiceDueDate = (period: number, date?: Date) =>\n  endOfDay(addDays(date ?? getBusinessToday(), period));\n","import { minInvoiceDueDateThreshold } from '@finmid/tbl-webapps/utils';\nimport { addDays, endOfDay } from 'date-fns';\n\nimport { getBusinessToday } from './getBusinessToday';\n\nexport const getMinInvoiceDueDate = (threshold = minInvoiceDueDateThreshold) =>\n  endOfDay(addDays(getBusinessToday(), threshold));\n","import { CreatePaymentRequest } from '@finmid/distributor-types';\nimport { setValueOrUndefined } from '@finmid/tbl-webapps/utils';\nimport { formatISO } from 'date-fns';\n\nimport { CreatePaymentRequestOnePageFormType } from '../CreatePaymentRequestOnePage.types';\n\nexport const createPaymentRequestPayload = (\n  values: CreatePaymentRequestOnePageFormType,\n) => {\n  const invoiceDueDate = values.invoiceDueDate\n    ? formatISO(values.invoiceDueDate, {\n        representation: 'complete',\n      }).split('T')[0]\n    : undefined;\n\n  // TODO: check fee override\n  const feeOverridePercentageForTerm =\n    values.feeOverridePercentagePerTerm?.[values.repaymentOption.period];\n  const totalFeePercentageOverride =\n    feeOverridePercentageForTerm != null\n      ? {\n          totalFeePercentageOverride:\n            feeOverridePercentageForTerm.overridePercentage.toString(),\n        }\n      : null;\n\n  const payload: CreatePaymentRequest.GatewayRequest = {\n    buyerId: values.buyer?.externalId ?? '',\n    captureInstantly: values.instantPayout,\n    currency: values.currency,\n    financingPortion: values.repaymentOption.payoutRatio,\n    id: values.paymentRequestId,\n    invoiceDueDate,\n    invoiceNumber: setValueOrUndefined(values.invoiceId),\n    repaymentTermDays: values.repaymentOption.period,\n    sellerId: values.seller.externalId,\n    totalAmount: parseFloat(values.amount),\n    useCase: values.useCase,\n    ...totalFeePercentageOverride,\n  };\n\n  return payload;\n};\n","import { CheckPaymentRequest } from '@finmid/distributor-types';\n\nexport const getLongestRepaymentMethod = (\n  repaymentMethods: CheckPaymentRequest.GatewayResponse['repaymentMethods'],\n) => {\n  return repaymentMethods.reduce(\n    (max, term) => (term.period > max.period ? term : max),\n    repaymentMethods[0],\n  );\n};\n\nexport const getShortestRepaymentMethod = (\n  repaymentMethods: CheckPaymentRequest.GatewayResponse['repaymentMethods'],\n) => {\n  return repaymentMethods.reduce(\n    (min, term) => (term.period < min.period ? term : min),\n    repaymentMethods[0],\n  );\n};\n","import { CheckPaymentRequest } from '@finmid/distributor-types';\n\nimport { getMaxInvoiceDueDate } from '../../PaymentRequests.utils';\n\nimport { getLongestRepaymentMethod } from './getMinOrMaxRepaymentMethod';\n\nexport const getAvailableMaxInvoiceDueDate = (\n  repaymentOptions: CheckPaymentRequest.GatewayResponse['repaymentMethods'],\n) => {\n  const longestRepaymentOptionAvailable =\n    getLongestRepaymentMethod(repaymentOptions);\n  const maxInvoiceDueDate = getMaxInvoiceDueDate(\n    longestRepaymentOptionAvailable.period,\n  );\n  return maxInvoiceDueDate;\n};\n","export const validateDate = (date: unknown) => {\n  return date instanceof Date && isFinite(+date);\n};\n","import {\n  CheckPaymentRequest,\n  Seller,\n  TBLCurrency,\n} from '@finmid/distributor-types';\nimport {\n  createContext,\n  Dispatch,\n  PropsWithChildren,\n  SetStateAction,\n  useContext,\n  useMemo,\n  useState,\n} from 'react';\n\nimport { getMinInvoiceDueDate } from '../PaymentRequests.utils';\n\nimport { getAvailableMaxInvoiceDueDate } from './utils';\n\ntype Context = {\n  defaultCurrency: TBLCurrency;\n  maxInvoiceDueDate: Date;\n  minInvoiceDueDate: Date;\n  repaymentTerms: CheckPaymentRequest.GatewayResponse['repaymentMethods'];\n  setRepaymentTerms: Dispatch<\n    SetStateAction<CheckPaymentRequest.GatewayResponse['repaymentMethods']>\n  >;\n  uniqueSeller?: Seller;\n  isLoading: boolean;\n  setIsLoading: Dispatch<SetStateAction<boolean>>;\n  allowPayoutWithoutDueDate: boolean;\n  setAllowPayoutWithoutDueDate: Dispatch<SetStateAction<boolean>>;\n};\n\nconst initialContext = null;\n\nconst CreatePaymentRequestFormContext = createContext<Context | null>(\n  initialContext,\n);\n\ntype CreatePaymentRequestFormContextProviderProps = {\n  defaultCurrency: TBLCurrency;\n  repaymentTerms: CheckPaymentRequest.GatewayResponse['repaymentMethods'];\n  uniqueSeller?: Seller;\n  allowPayoutWithoutDueDate: boolean;\n};\n\nexport const CreatePaymentRequestFormContextProvider = ({\n  defaultCurrency,\n  children,\n  repaymentTerms: initialRepaymentTerms,\n  uniqueSeller,\n  allowPayoutWithoutDueDate: initialAllowPayoutWithoutDueDate,\n}: PropsWithChildren<CreatePaymentRequestFormContextProviderProps>) => {\n  const [isLoading, setIsLoading] = useState<boolean>(false);\n  const [repaymentTerms, setRepaymentTerms] = useState(initialRepaymentTerms);\n  const [allowPayoutWithoutDueDate, setAllowPayoutWithoutDueDate] = useState(\n    initialAllowPayoutWithoutDueDate,\n  );\n\n  const minInvoiceDueDate = getMinInvoiceDueDate();\n  const maxInvoiceDueDate = useMemo(\n    () => getAvailableMaxInvoiceDueDate(repaymentTerms),\n    [repaymentTerms],\n  );\n\n  const value: Context = {\n    defaultCurrency,\n    maxInvoiceDueDate,\n    minInvoiceDueDate,\n    repaymentTerms,\n    setRepaymentTerms,\n    uniqueSeller,\n    isLoading,\n    setIsLoading,\n    allowPayoutWithoutDueDate,\n    setAllowPayoutWithoutDueDate,\n  };\n\n  return (\n    <CreatePaymentRequestFormContext.Provider value={value}>\n      {children}\n    </CreatePaymentRequestFormContext.Provider>\n  );\n};\n\nexport const useCreatePaymentRequestFormPayload = () => {\n  const context = useContext(CreatePaymentRequestFormContext);\n\n  if (context == null) {\n    throw new Error(\n      'useCreatePaymentRequestFormPayload can only be used inside CreatePaymentRequestFormContextProvider Provider',\n    );\n  }\n\n  return context;\n};\n","import { CheckPaymentRequest } from '@finmid/distributor-types';\nimport { useCheckPaymentRequestMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useDistributorCurrencies } from '@finmid/tbl-webapps/hooks';\nimport { formatISO, isAfter, isBefore } from 'date-fns';\nimport debounce from 'lodash/debounce';\nimport {\n  createContext,\n  PropsWithChildren,\n  useContext,\n  useEffect,\n  useMemo,\n  useState,\n} from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport { getClosestRepaymentTerm } from '../PaymentRequests.utils';\n\nimport { useCreatePaymentRequestFormPayload } from './CreatePaymentRequestForm.context';\nimport { CreatePaymentRequestOnePageFormType } from './CreatePaymentRequestOnePage.types';\nimport { validateDate } from './utils';\n\nexport type CheckPaymentRequestContext =\n  | (CheckPaymentRequest.GatewayResponse & {\n      selectedTerm:\n        | CheckPaymentRequest.GatewayResponse['repaymentMethods'][number]\n        | null;\n    })\n  | null;\n\nconst initialContext = null;\n\nconst CheckPaymentRequestContext =\n  createContext<CheckPaymentRequestContext | null>(initialContext);\n\nexport const CheckPaymentRequestContextProvider = ({\n  children,\n}: PropsWithChildren) => {\n  const { defaultCurrency } = useDistributorCurrencies();\n  const [checkAndCalculate, { data }] = useCheckPaymentRequestMutation();\n  const {\n    watch,\n    setValue: setFormValue,\n    getValues,\n    trigger,\n  } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const {\n    setRepaymentTerms,\n    setIsLoading,\n    maxInvoiceDueDate,\n    minInvoiceDueDate,\n    setAllowPayoutWithoutDueDate,\n  } = useCreatePaymentRequestFormPayload();\n\n  const [value, setValue] = useState<CheckPaymentRequestContext>({\n    eligible: false,\n    declineReason: null,\n    code: null,\n    currency: defaultCurrency,\n    repaymentMethods: [],\n    selectedTerm: null,\n    useCaseLevel: 'PLATFORM',\n    allowPayoutWithoutDueDate: false,\n  });\n\n  const amount = watch('amount');\n  const currency = watch('currency');\n  const buyer = watch('buyer');\n  const seller = watch('seller');\n  const invoiceDueDate = watch('invoiceDueDate');\n  const repaymentOption = watch('repaymentOption');\n  const useCase = watch('useCase');\n  const feeOverridePercentage =\n    repaymentOption?.period != null\n      ? watch('feeOverridePercentagePerTerm')?.[repaymentOption?.period]\n      : undefined;\n  const captureInstantly = watch('instantPayout');\n\n  const debouncedCheckAndCalculate = useMemo(\n    () =>\n      debounce((props: CheckPaymentRequest.GatewayRequest) => {\n        checkAndCalculate(props);\n      }, 300),\n    [checkAndCalculate],\n  );\n\n  useEffect(() => {\n    setIsLoading(true);\n    debouncedCheckAndCalculate({\n      totalAmount: Number(amount) || undefined,\n      currency,\n      buyerId: buyer?.externalId,\n      sellerId: seller?.externalId,\n      useCase,\n      totalFeePercentageOverride:\n        feeOverridePercentage?.overrideHumanPercentage != null\n          ? feeOverridePercentage.overrideHumanPercentage\n          : undefined,\n      invoiceDueDate:\n        invoiceDueDate && validateDate(invoiceDueDate)\n          ? formatISO(invoiceDueDate, {\n              representation: 'complete',\n            }).split('T')[0]\n          : undefined,\n      captureInstantly,\n    });\n  }, [\n    amount,\n    currency,\n    buyer,\n    seller,\n    invoiceDueDate,\n    feeOverridePercentage,\n    debouncedCheckAndCalculate,\n    useCase,\n    captureInstantly,\n    setIsLoading,\n  ]);\n\n  useEffect(() => {\n    if (data == null) return;\n    setIsLoading(false);\n\n    const selectedTerm =\n      data.repaymentMethods.find(\n        ({ period, payoutRatio }) =>\n          period === repaymentOption?.period &&\n          payoutRatio === repaymentOption?.payoutRatio,\n      ) ?? null;\n\n    setRepaymentTerms(data.repaymentMethods);\n\n    setAllowPayoutWithoutDueDate(data.allowPayoutWithoutDueDate);\n    trigger('invoiceDueDate');\n\n    setValue({ ...data, selectedTerm: selectedTerm });\n\n    const date = getValues('invoiceDueDate');\n\n    if (\n      date &&\n      validateDate(date) &&\n      !isBefore(maxInvoiceDueDate, date) &&\n      !isAfter(minInvoiceDueDate, date)\n    ) {\n      const closestTerm = getClosestRepaymentTerm({\n        repaymentMethods: data.repaymentMethods,\n        date,\n      });\n      if (\n        closestTerm &&\n        (closestTerm.period !== repaymentOption?.period ||\n          closestTerm.payoutRatio !== repaymentOption?.payoutRatio)\n      ) {\n        setFormValue(\n          'repaymentOption',\n          {\n            period: closestTerm.period,\n            payoutRatio: closestTerm.payoutRatio,\n          },\n          { shouldValidate: true, shouldTouch: true },\n        );\n      }\n    }\n\n    if (\n      (selectedTerm?.period ?? 0) !== repaymentOption?.period ||\n      (selectedTerm?.payoutRatio ?? 0) !== repaymentOption?.payoutRatio\n    ) {\n      setFormValue(\n        'repaymentOption',\n        {\n          period: selectedTerm?.period ?? 0,\n          payoutRatio: selectedTerm?.payoutRatio ?? 0,\n        },\n        { shouldValidate: true, shouldTouch: true },\n      );\n    }\n  }, [\n    data,\n    setFormValue,\n    setIsLoading,\n    setRepaymentTerms,\n    setAllowPayoutWithoutDueDate,\n    repaymentOption,\n    getValues,\n    maxInvoiceDueDate,\n    minInvoiceDueDate,\n    trigger,\n  ]);\n\n  useEffect(() => {\n    // Reset invoice due date when use case changes, as\n    // use case might return different terms\n    setFormValue('invoiceDueDate', undefined, { shouldValidate: true });\n  }, [useCase, setFormValue]);\n\n  return (\n    <CheckPaymentRequestContext.Provider value={value}>\n      {children}\n    </CheckPaymentRequestContext.Provider>\n  );\n};\n\nexport const useCheckPaymentRequestContext = () => {\n  const context = useContext(CheckPaymentRequestContext);\n\n  if (context == null) {\n    throw new Error(\n      'useCheckPaymentRequestContext can only be used inside CheckPaymentRequestContextProvider Provider',\n    );\n  }\n\n  return context;\n};\n","import { formatISO, sub } from 'date-fns';\n\nimport { PaymentRequestsFilters } from './PaymentRequestsFilters.types';\n\nexport const useDefaultFilters = () => {\n  const fromDate = sub(new Date(), { months: 3 });\n\n  const defaultPaymentRequestsFilters: PaymentRequestsFilters = {\n    server: {\n      limit: 10,\n      from: formatISO(fromDate, { representation: 'date' }),\n      search: '',\n    },\n    firstPosition: 1,\n  };\n\n  return {\n    defaultPaymentRequestsFilters,\n  };\n};\n","export const invoicesFiltersKey = 'invoicesFiltersKey';\n\nexport const removeStoredPaymentRequestsFilters = () => {\n  sessionStorage.removeItem(invoicesFiltersKey);\n};\n","import styled from '@emotion/styled';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { useTranslation } from 'react-i18next';\n\nconst UnstyledButton = styled.span`\n  cursor: pointer;\n  text-decoration: underline;\n  color: #fff;\n  margin-left: -14px;\n`;\n\nexport const useNotifyCreatePaymentRequest = () => {\n  const { t: tInvoicesPage } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice',\n  });\n  const { t: tComponents } = useTranslation('components');\n  const { notifySuccess, notifySuccessWithAction } = useNotifications();\n\n  const notifyCreated = (paymentRequestId: string) =>\n    notifySuccess(tInvoicesPage('success', { paymentRequestId }));\n\n  // TODO when BE ready\n  const handleUndoCreatePaymentRequest = (paymentRequestId: string) => {\n    console.log('Undo payment request', paymentRequestId);\n  };\n  const notifySuccessWithUndo = (paymentRequestId: string) =>\n    notifySuccessWithAction({\n      message: tInvoicesPage('paymentRequestCreated', { paymentRequestId }),\n      action: () => (\n        <UnstyledButton\n          onClick={() => handleUndoCreatePaymentRequest(paymentRequestId)}\n        >\n          {tComponents('undo')}\n        </UnstyledButton>\n      ),\n    });\n\n  // TODO when BE ready\n  const handleUndoCreatePaymentRequestWithPayout = (\n    paymentRequestId: string,\n  ) => {\n    console.log('Undo payment request with payout', paymentRequestId);\n  };\n  const notifySuccessWithUndoPayout = (paymentRequestId: string) =>\n    notifySuccessWithAction({\n      message: tInvoicesPage('paymentRequestWithPayoutCreated', {\n        paymentRequestId,\n      }),\n      action: () => (\n        <UnstyledButton\n          onClick={() =>\n            handleUndoCreatePaymentRequestWithPayout(paymentRequestId)\n          }\n        >\n          {tComponents('undo')}\n        </UnstyledButton>\n      ),\n    });\n\n  return {\n    notifyCreated,\n    notifySuccessWithUndo,\n    notifySuccessWithUndoPayout,\n  };\n};\n","import { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nexport const useCreatePaymentRequestFormLabels = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n\n  // form field name: label\n  const labels: Record<string, string> = useMemo(\n    () => ({\n      amount: t('amount'),\n      buyer: t('paymentIntentCheck.buyerLabel'),\n      invoiceId: t('invoiceNumber.label'),\n      invoiceDueDate: t('invoiceDuDate.label'),\n      paymentRequestId: t('paymentRequestId.label'),\n      seller: t('paymentIntentCheck.sellerLabel'),\n      id: 'id',\n      useCase: t('useCase.label'),\n    }),\n    [t],\n  );\n\n  const placeholders: Record<string, string> = useMemo(\n    () => ({\n      amount: t('amountPlaceholder'),\n      invoiceId: t('invoiceIdPlaceholder'),\n      invoiceDueDate: t('invoiceDueDatePlaceholder'),\n      paymentRequestId: t('paymentRequestIdPlaceholder'),\n      useCase: t('useCase.placeholder'),\n    }),\n    [t],\n  );\n\n  const sections: Record<string, string> = useMemo(\n    () => ({\n      amountAndParties: t('amountAndParties'),\n      paymentDetails: t('paymentAndPayoutDetails'),\n    }),\n    [t],\n  );\n\n  const sidebar: Record<string, string> = useMemo(\n    () => ({\n      amountAndParties: t('involvedParties.title'),\n      paymentDetails: t('paymentRequestBreakdown.title'),\n    }),\n    [t],\n  );\n\n  const actions: Record<string, string> = useMemo(\n    () => ({\n      createRequestAndPayout: t('btnLabelWithPayout'),\n      createRequest: t('btnLabel'),\n    }),\n    [t],\n  );\n\n  return { actions, labels, placeholders, sections, sidebar };\n};\n","import { useDisplayErrorToUser } from '@finmid/tbl-webapps/errors-handling';\n\nimport { useCreatePaymentRequestFormLabels } from './createPaymentRequestForm.labels';\n\nconst zodNameToYupName = {\n  id: 'paymentRequestId',\n  invoiceNumber: 'invoiceId',\n};\n\nexport const useCreatePaymentRequestFormError = () => {\n  const { labels } = useCreatePaymentRequestFormLabels();\n  return useDisplayErrorToUser({\n    bffFieldsToAppFields: zodNameToYupName,\n    appFieldsToLabels: labels,\n  });\n};\n","import {\n  createContext,\n  Dispatch,\n  PropsWithChildren,\n  SetStateAction,\n  useContext,\n  useState,\n} from 'react';\n\ntype Context = {\n  isRecourseDialogOpen: boolean;\n  setIsRecourseDialogOpen: Dispatch<SetStateAction<boolean>>;\n  isRecourse: boolean;\n  setIsRecourse: Dispatch<SetStateAction<boolean>>;\n};\n\nconst initialContext = null;\n\nexport const RecourseContext = createContext<Context | null>(initialContext);\n\nexport const RecourseContextProvider = ({ children }: PropsWithChildren) => {\n  const [isRecourseDialogOpen, setIsRecourseDialogOpen] = useState(false);\n  const [isRecourse, setIsRecourse] = useState(false);\n\n  return (\n    <RecourseContext.Provider\n      value={{\n        isRecourseDialogOpen,\n        setIsRecourseDialogOpen,\n        isRecourse,\n        setIsRecourse,\n      }}\n    >\n      {children}\n    </RecourseContext.Provider>\n  );\n};\n\nexport const useRecourseContext = () => {\n  const context = useContext(RecourseContext);\n\n  if (context == null) {\n    throw new Error(\n      'useRecourseContext can only be used inside RecourseContextProvider Provider',\n    );\n  }\n\n  return context;\n};\n","import { displayPercentage, useDisplayAmount } from '@finmid/tbl-webapps/utils';\nimport { useFormContext } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { useCheckPaymentRequestContext } from '../../../CheckPaymentRequest.context';\nimport { CreatePaymentRequestOnePageFormType } from '../../../CreatePaymentRequestOnePage.types';\nimport { getShortestRepaymentMethod } from '../../../utils';\n\ninterface RecourseTableProps {\n  variant: 'default' | 'custom';\n}\nexport const useGetRecourseTableData = ({ variant }: RecourseTableProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'recourse' });\n  const { getValues } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const currency = getValues('currency');\n  const displayAmount = useDisplayAmount();\n\n  const availableBase = displayAmount({\n    amount: getValues('buyer.availableBaseLimit'),\n    currency,\n  });\n  const availableRecourse = displayAmount({\n    amount: getValues('buyer.availableRecourseLimit'),\n    currency,\n  });\n\n  const { repaymentMethods, selectedTerm } = useCheckPaymentRequestContext();\n  const minRepaymentTerm = getShortestRepaymentMethod(repaymentMethods);\n\n  const customBaseFee = displayPercentage(\n    selectedTerm?.amountsBreakdown.financingAmountSplit.baseFeePercentage,\n  );\n  const customRecourseFee = displayPercentage(\n    selectedTerm?.amountsBreakdown.financingAmountSplit.recourseFeePercentage,\n  );\n  const customBaseAmount = displayAmount({\n    amount: getValues('customBaseAmount'),\n    currency,\n  });\n  const customRecourseAmount = displayAmount({\n    amount: getValues('customRecourseAmount'),\n    currency,\n  });\n\n  const minTermDays = minRepaymentTerm?.period;\n  const minTermBaseFee = displayPercentage(\n    minRepaymentTerm?.amountsBreakdown.financingAmountSplit.baseFeePercentage,\n  );\n  const minTermRecourseFee = displayPercentage(\n    minRepaymentTerm?.amountsBreakdown.financingAmountSplit\n      .recourseFeePercentage,\n  );\n\n  const defaultHeaders = [\n    t('limitType'),\n    t('availableLimit'),\n    t('minDayPricing', { minTermDays }),\n  ];\n\n  const customHeaders = [t('amountUsed'), t('limitType'), t('pricing')];\n  const headers = variant === 'default' ? defaultHeaders : customHeaders;\n  let rows;\n  if (variant === 'default') {\n    rows = [\n      [t('baseLimit'), availableBase, minTermBaseFee],\n      [t('recourseLimit'), availableRecourse, minTermRecourseFee],\n    ];\n  } else {\n    rows = [\n      [customBaseAmount, t('baseLimit'), customBaseFee],\n      [customRecourseAmount, t('recourseLimit'), customRecourseFee],\n    ];\n  }\n  return { rows, headers };\n};\n","import { TableRow, TableCell } from '@finmid/tbl-webapps/components';\nimport Table from '@mui/material/Table';\nimport { tableCellClasses } from '@mui/material/TableCell';\nimport { styled } from '@mui/material/styles';\n\ninterface RecourseTableProps {\n  tone: 'light' | 'dark';\n}\n\nexport const StyledTableHeaderCell = styled(TableCell)<RecourseTableProps>(\n  ({ theme, tone }) => {\n    const bgColor =\n      tone === 'light'\n        ? theme.glo.color.foundations[10]\n        : theme.glo.color.foundations[20];\n    const color =\n      tone === 'light'\n        ? theme.glo.color.foundations[60]\n        : theme.glo.color.foundations[60];\n    return {\n      [`&.${tableCellClasses.head}`]: {\n        backgroundColor: bgColor,\n        color: color,\n        padding: '8px 16px',\n      },\n      fontSize: 12,\n    };\n  },\n);\n\nexport const StyledTableCell = styled(TableCell)<RecourseTableProps>(\n  ({ theme, tone }) => {\n    const bgColor =\n      tone === 'light'\n        ? theme.glo.color.foundations[0]\n        : theme.glo.color.foundations[10];\n    const color =\n      tone === 'light'\n        ? theme.glo.color.foundations[100]\n        : theme.glo.color.foundations[60];\n    return {\n      [`&.${tableCellClasses.head}`]: {\n        padding: '10px 16px',\n      },\n      [`&.${tableCellClasses.body}`]: {\n        fontSize: 13,\n        backgroundColor: bgColor,\n        color: color,\n      },\n      '&.:first-of-type': {\n        paddingLeft: 'unset',\n      },\n    };\n  },\n);\n\nexport const StyledTable = styled(Table)<RecourseTableProps>(\n  ({ theme, tone }) => ({\n    border:\n      tone === 'light'\n        ? `1px solid ${theme.glo.color.foundations[20]}`\n        : 'none',\n    borderCollapse: 'collapse',\n    borderRadius: 4,\n    overflow: tone === 'light' ? 'visible' : 'hidden',\n    '& .MuiTableCell-root': {\n      textAlign: 'left',\n      padding: '6px 16px !important',\n    },\n  }),\n);\n\nexport const StyledTableRow = styled(TableRow)(({ theme }) => ({\n  '&:hover': {\n    backgroundColor: 'unset',\n  },\n}));\n","import { TableHead, TableRow } from '@finmid/tbl-webapps/components';\nimport { TableBody } from '@mui/material';\n\nimport { useGetRecourseTableData } from '../hooks/useGetRecourseTableData';\n\nimport {\n  StyledTable,\n  StyledTableCell,\n  StyledTableHeaderCell,\n  StyledTableRow,\n} from './RecourseTable.styled';\ninterface RecourseTableProps {\n  variant: 'default' | 'custom';\n}\n\nexport const RecourseTable = ({ variant }: RecourseTableProps) => {\n  const { headers, rows } = useGetRecourseTableData({ variant });\n  const tone = variant === 'default' ? 'light' : 'dark';\n\n  return (\n    <StyledTable data-test-id=\"recourse-table\" tone={tone}>\n      <TableHead>\n        <TableRow>\n          {headers.map((header, index) => (\n            <StyledTableHeaderCell key={index} tone={tone}>\n              {header}\n            </StyledTableHeaderCell>\n          ))}\n        </TableRow>\n      </TableHead>\n      <TableBody>\n        {rows.map((row, rowIndex) => (\n          <StyledTableRow key={rowIndex}>\n            {row.map((cell, cellIndex) => (\n              <StyledTableCell key={cellIndex} tone={tone}>\n                {cell}\n              </StyledTableCell>\n            ))}\n          </StyledTableRow>\n        ))}\n      </TableBody>\n    </StyledTable>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { displayPercentage, useDisplayAmount } from '@finmid/tbl-webapps/utils';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { useFormContext } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { useCheckPaymentRequestContext } from '../../../CheckPaymentRequest.context';\nimport { CreatePaymentRequestOnePageFormType } from '../../../CreatePaymentRequestOnePage.types';\nimport { getShortestRepaymentMethod } from '../../../utils';\n\nimport { RecourseTable } from './RecourseTable';\n\nexport const RecourseModalContent = () => {\n  const theme = useTheme();\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'recourseModal',\n  });\n  const { getValues } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const buyerName = getValues('buyer.legalName');\n\n  const { repaymentMethods } = useCheckPaymentRequestContext();\n  const minRepaymentMethod = getShortestRepaymentMethod(repaymentMethods);\n\n  const displayAmount = useDisplayAmount();\n  const totalLimit = displayAmount({\n    amount: getValues('buyer.availableLimit'),\n    currency: getValues('currency'),\n  });\n  const baseLimitValue = getValues('buyer.availableBaseLimit');\n  const baseLimit = displayAmount({\n    amount: baseLimitValue,\n    currency: getValues('currency'),\n  });\n\n  const minTermBaseFee = displayPercentage(\n    minRepaymentMethod?.amountsBreakdown.financingAmountSplit.baseFeePercentage,\n  );\n  const minTermRecourseFee = displayPercentage(\n    minRepaymentMethod?.amountsBreakdown.financingAmountSplit\n      .recourseFeePercentage,\n  );\n\n  const feeDetailText =\n    baseLimitValue === 0\n      ? t('feeDetailsWithZeroBase', { baseLimit, minTermRecourseFee })\n      : t('feeDetails', { baseLimit, minTermBaseFee, minTermRecourseFee });\n\n  return (\n    <Box>\n      <Typography fontSize={19} fontWeight={700} lineHeight=\"24px\">\n        {t('title', { buyerName })}\n      </Typography>\n      <Spacer height={1} />\n\n      <Typography\n        fontSize={15}\n        fontWeight={400}\n        lineHeight=\"20px\"\n        color={theme.glo.color.foundations[60]}\n      >\n        {t('description')}\n      </Typography>\n      <Spacer height={3} />\n      <Typography\n        fontSize={15}\n        fontWeight={400}\n        lineHeight=\"20px\"\n        color={theme.glo.color.foundations[60]}\n      >\n        {t('limitDetails', {\n          buyerName,\n          totalLimit,\n          minRepaymentTerm: minRepaymentMethod?.period,\n        })}\n      </Typography>\n      <Spacer height={3} />\n      <RecourseTable variant=\"default\" />\n      <Spacer height={3} />\n      <Typography\n        fontSize={15}\n        fontWeight={400}\n        lineHeight=\"20px\"\n        color={theme.glo.color.foundations[60]}\n      >\n        {feeDetailText}\n      </Typography>\n      <Spacer height={3} />\n      <Typography\n        fontSize={13}\n        fontWeight={400}\n        lineHeight=\"14px\"\n        color={theme.glo.color.foundations[60]}\n      >\n        {t('financingProvider')}\n      </Typography>\n    </Box>\n  );\n};\n","import { TBLCurrency } from '@finmid/distributor-types';\nimport {\n  EXTERNAL_ID_REGEX,\n  TWO_DECIMAL_REGEX,\n} from '@finmid/tbl-webapps/utils';\nimport { useFormat } from '@finmid/translations';\nimport { endOfDay } from 'date-fns';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport * as Yup from 'yup';\n\nimport { useRecourseContext } from '../components/CreatePaymentRequestPageRecourseModal/components';\n\ntype UseCreatePaymentRequestFormSchemaProps = {\n  minInvoiceDueDate: Date;\n  maxInvoiceDueDate: Date;\n  allowPayoutWithoutDueDate: boolean;\n};\n\nexport const useCreatePaymentRequestFormSchema = ({\n  minInvoiceDueDate,\n  maxInvoiceDueDate,\n  allowPayoutWithoutDueDate,\n}: UseCreatePaymentRequestFormSchemaProps) => {\n  const { date } = useFormat();\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'validation',\n  });\n  const { isRecourse } = useRecourseContext();\n\n  const isPositiveTest: [\n    string,\n    string,\n    (value: string | number | undefined) => boolean,\n  ] = useMemo(\n    () => [\n      'positive',\n      t('amountPositive'),\n      (value: string | number | undefined) => {\n        if (Number(value) > 0) {\n          return true;\n        } else {\n          return false;\n        }\n      },\n    ],\n    [t],\n  );\n\n  const schema = useMemo(\n    () =>\n      Yup.object().shape({\n        amount: Yup.string()\n          .test(\n            'thousands-separator-comma',\n            t('thousandsSeparatorComma'),\n            (value: string | undefined) => {\n              if (value != null) {\n                return !value.includes(',');\n              }\n              return true;\n            },\n          )\n          .test(...isPositiveTest)\n          .test(\n            'max-two-decimal',\n            t('maxTwoDigits'),\n            (value: string | undefined) => {\n              if (value != null) {\n                return TWO_DECIMAL_REGEX.test(value);\n              }\n              return true;\n            },\n          )\n          .test(\n            'platform-recourse-limit',\n            'PLATFORM_RECOURSE_LIMIT_EXCEEDED',\n            (value, ctx) => {\n              if (!value || !isRecourse || !ctx.parent.buyer) {\n                return true;\n              }\n              const { availablePlatformRecourseLimit, availableBaseLimit } =\n                ctx.parent.buyer;\n              return !(\n                +value - availableBaseLimit >\n                availablePlatformRecourseLimit\n              );\n            },\n          )\n          .test('buyer-limit', 'BUYER_EXPENSE_LIMIT_EXCEEDED', (val, ctx) => {\n            return !(\n              ctx.parent.eligibilityError === 'BUYER_EXPENSE_LIMIT_EXCEEDED' ||\n              ctx.parent.buyer?.availableLimit +\n                ctx.parent.buyer?.availableRecourseLimit <\n                Number(val)\n            );\n          })\n          .test(\n            'platform-limit',\n            'PLATFORM_CREDIT_LIMIT_EXCEEDED',\n            (_, ctx) => {\n              return !(\n                ctx.parent.eligibilityError === 'PLATFORM_CREDIT_LIMIT_EXCEEDED'\n              );\n            },\n          )\n          .required(t('totalAmountRequired')),\n\n        buyer: Yup.object()\n          .shape({\n            availableLimit: Yup.number().required(),\n            currency: Yup.string<TBLCurrency>().required(),\n            externalId: Yup.string()\n              .matches(EXTERNAL_ID_REGEX)\n              .required(t('buyerRequired')),\n            id: Yup.string().required(),\n            legalName: Yup.string().required(),\n            availableBaseLimit: Yup.number().required(),\n            availableRecourseLimit: Yup.number().nullable(),\n            availablePlatformRecourseLimit: Yup.number().required(),\n            useCase: Yup.string().required().nullable(),\n          })\n          .nullable()\n          .test('has-buyer', t('buyerRequired'), (value) => value != null),\n\n        currency: Yup.string<TBLCurrency>().required(t('currencyRequired')),\n\n        repaymentOption: Yup.object().shape({\n          period: Yup.number()\n            .required()\n            .test(...isPositiveTest),\n          payoutRatio: Yup.number()\n            .required()\n            .test(...isPositiveTest),\n        }),\n\n        instantPayout: Yup.boolean().required(),\n\n        invoiceDueDate: Yup.date().when(\n          ['instantPayout', 'useCase'],\n          (val, schema) => {\n            const [instantPayout] = val;\n            if (instantPayout && !allowPayoutWithoutDueDate) {\n              return schema\n                .typeError(t('dateValid'))\n                .required()\n                .test(\n                  'is-within-range',\n                  t('dateWithinRange', {\n                    minInvoiceDueDate: date(minInvoiceDueDate),\n                    maxInvoiceDueDate: date(maxInvoiceDueDate),\n                  }),\n                  (value) =>\n                    endOfDay(value) >= minInvoiceDueDate &&\n                    endOfDay(value) <= maxInvoiceDueDate,\n                );\n            }\n            return Yup.date()\n              .nullable()\n              .optional()\n              .typeError(t('dateValid'))\n              .test(\n                'is-within-range',\n                t('dateWithinRange', {\n                  minInvoiceDueDate: date(minInvoiceDueDate),\n                  maxInvoiceDueDate: date(maxInvoiceDueDate),\n                }),\n                (value) =>\n                  value == null ||\n                  (endOfDay(value) >= minInvoiceDueDate &&\n                    endOfDay(value) <= maxInvoiceDueDate),\n              );\n          },\n        ),\n\n        invoiceId: Yup.string().when(['instantPayout', 'useCase'], (val) => {\n          const [instantPayout] = val;\n          if (instantPayout) {\n            return Yup.string()\n              .matches(EXTERNAL_ID_REGEX, t('invoiceIdRegex'))\n              .required();\n          }\n          return Yup.string()\n            .optional()\n            .test('is-valid', t('invoiceIdRegex'), (value) => {\n              if (value != null && value !== '') {\n                return EXTERNAL_ID_REGEX.test(value);\n              }\n              return true;\n            });\n        }),\n\n        paymentRequestId: Yup.string()\n          .required(t('paymentRequestIdRequired'))\n          .matches(EXTERNAL_ID_REGEX, t('paymentRequestIdRegex')),\n\n        seller: Yup.object()\n          .shape({\n            externalId: Yup.string()\n              .matches(EXTERNAL_ID_REGEX)\n              .required(t('sellerRequired')),\n            legalName: Yup.string().required(),\n          })\n          .required(),\n\n        feeOverridePercentagePerTerm: Yup.object().shape({}),\n\n        useCase: Yup.string().required(),\n      }),\n\n    [\n      t,\n      isRecourse,\n      date,\n      minInvoiceDueDate,\n      maxInvoiceDueDate,\n      allowPayoutWithoutDueDate,\n      isPositiveTest,\n    ],\n  );\n\n  return {\n    validationSchema: schema,\n  };\n};\n","import { useCreatePaymentRequestMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { yupResolver } from '@hookform/resolvers/yup';\nimport posthog from 'posthog-js';\nimport { useForm } from 'react-hook-form';\nimport { useNavigate } from 'react-router-dom';\n\nimport { removeStoredPaymentRequestsFilters } from '../../PaymentRequestsFilters';\nimport { useCreatePaymentRequestFormPayload } from '../CreatePaymentRequestForm.context';\nimport { CreatePaymentRequestOnePageFormType } from '../CreatePaymentRequestOnePage.types';\nimport { createPaymentRequestPayload } from '../utils';\n\nimport { useNotifyCreatePaymentRequest } from './createPaymentRequest.notify';\nimport { useCreatePaymentRequestFormError } from './createPaymentRequestForm.error';\nimport { useCreatePaymentRequestFormSchema } from './createPaymentRequestForm.schema';\n\nexport const useCreatePaymentRequestForm = () => {\n  const {\n    defaultCurrency,\n    minInvoiceDueDate,\n    maxInvoiceDueDate,\n    uniqueSeller,\n    allowPayoutWithoutDueDate,\n  } = useCreatePaymentRequestFormPayload();\n  const { validationSchema } = useCreatePaymentRequestFormSchema({\n    minInvoiceDueDate,\n    maxInvoiceDueDate,\n    allowPayoutWithoutDueDate,\n  });\n\n  const { notifyCreated } = useNotifyCreatePaymentRequest();\n  const [createPaymentRequest] = useCreatePaymentRequestMutation();\n  const { invalidFieldsErrors, displayErrorToUser } =\n    useCreatePaymentRequestFormError();\n  const navigate = useNavigate();\n\n  const methods = useForm<CreatePaymentRequestOnePageFormType>({\n    resolver: yupResolver(validationSchema),\n    defaultValues: {\n      amount: '',\n      currency: defaultCurrency,\n      instantPayout: true,\n      invoiceId: '',\n      paymentRequestId: '',\n      seller: uniqueSeller,\n      feeOverridePercentagePerTerm: {},\n    },\n    mode: 'onChange',\n  });\n\n  const onSubmit = async (values: CreatePaymentRequestOnePageFormType) => {\n    try {\n      posthog.capture('clicked_create_paymentRequest_confirm');\n      const payload = createPaymentRequestPayload(values);\n      const response = await createPaymentRequest(payload).unwrap();\n      if (response) {\n        removeStoredPaymentRequestsFilters();\n        navigate(`${b2bPaymentRoutes.paymentRequests}/${response.id}`);\n        notifyCreated(response.id);\n      }\n    } catch (error) {\n      displayErrorToUser(error);\n    }\n  };\n\n  return {\n    invalidFieldsErrors,\n    methods,\n    handleSubmitForm: methods.handleSubmit(onSubmit),\n  };\n};\n","import {\n  useCheckPaymentRequestMutation,\n  useGetDefaultFinancingConfigurationQuery,\n  useGetSellersQuery,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { useDistributorCurrencies } from '@finmid/tbl-webapps/hooks';\nimport { useEffect } from 'react';\n\nexport const useCheckUniqueSeller = () => {\n  const { data, isFetching, error } = useGetSellersQuery({ status: 'ACTIVE' });\n\n  const uniqueSeller = data?.data.length === 1 ? data.data[0] : undefined;\n\n  return {\n    isFetching,\n    error,\n    uniqueSeller,\n  };\n};\n\nconst useGetDefaultRepaymentTerms = (useCase?: string) => {\n  const [getRepaymentTerms, { data, isLoading, error }] =\n    useCheckPaymentRequestMutation();\n  const { defaultCurrency } = useDistributorCurrencies();\n\n  useEffect(() => {\n    if (useCase == null) return;\n\n    getRepaymentTerms({\n      currency: defaultCurrency,\n      useCase,\n    });\n  }, [defaultCurrency, useCase, getRepaymentTerms]);\n\n  return {\n    isLoading,\n    error,\n    defaultRepaymentTerms: data?.repaymentMethods,\n  };\n};\n\nconst useGetDefaultFinancingConfiguration = () => {\n  const {\n    data: financingConfiguration,\n    isFetching,\n    error,\n  } = useGetDefaultFinancingConfigurationQuery();\n\n  return {\n    isFetching,\n    error,\n    financingConfiguration,\n  };\n};\n\nexport const useCreatePaymentRequestPage = () => {\n  const {\n    isFetching: isFetchingUniqueSeller,\n    error: errorUniqueSeller,\n    uniqueSeller,\n  } = useCheckUniqueSeller();\n\n  const {\n    isFetching: isFetchingFinancingConfig,\n    error: errorFinancingConfig,\n    financingConfiguration,\n  } = useGetDefaultFinancingConfiguration();\n\n  const {\n    isLoading: isLoadingRepaymentTerms,\n    error: errorRepaymentTerms,\n    defaultRepaymentTerms,\n  } = useGetDefaultRepaymentTerms(financingConfiguration?.useCase);\n\n  const { defaultCurrency } = useDistributorCurrencies();\n\n  return {\n    defaultCurrency,\n    error: errorUniqueSeller || errorFinancingConfig || errorRepaymentTerms,\n    isFetching:\n      isFetchingUniqueSeller ||\n      isFetchingFinancingConfig ||\n      isLoadingRepaymentTerms,\n    defaultRepaymentTerms,\n    uniqueSeller,\n    allowPayoutWithoutDueDate:\n      financingConfiguration?.allowPayoutWithoutDueDate ?? false,\n  };\n};\n","import { UnstyledLink } from '@finmid/tbl-webapps/components';\nimport { useFormat } from '@finmid/translations';\nimport toCurrency from 'currency.js';\nimport { useFormContext } from 'react-hook-form';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../CreatePaymentRequestOnePage.types';\n\nexport const BuyerLimitExceededMessage = () => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice',\n  });\n  const { money } = useFormat();\n\n  const { getValues } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const buyer = getValues('buyer');\n\n  const currentLimit =\n    buyer != null\n      ? money(toCurrency(buyer.availableLimit), buyer.currency)\n      : money(0, 'EUR');\n\n  return (\n    <Trans\n      t={t}\n      i18nKey=\"paymentRequestCheck.buyerLimitExceeded\"\n      // i18nKey=\"paymentRequestCheck.buyerLimitExceededWithRequest\" // uncomment when increase request enabled\n      components={{\n        u: (\n          <UnstyledLink\n            to={`/invoices`}\n            style={{ textDecoration: 'underline' }}\n          />\n        ),\n      }}\n      values={{\n        buyerName: buyer?.legalName || t('limit.buyerPlaceholder'),\n        currentLimit,\n        requestIncrease: t('paymentRequestCheck.requestIncrease'),\n      }}\n    />\n  );\n};\n","import { useFormat } from '@finmid/translations';\nimport toCurrency from 'currency.js';\nimport { useRef } from 'react';\nimport { useFormContext } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../CreatePaymentRequestOnePage.types';\n\nexport const PlatformLimitExceededMessage = () => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice',\n  });\n  const { money } = useFormat();\n\n  const { getValues } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const [totalAmount, buyer] = getValues(['amount', 'buyer']);\n\n  const amountRef = useRef(totalAmount);\n  const amount = money(toCurrency(amountRef.current), buyer?.currency ?? 'EUR');\n\n  return t('paymentIntentCheck.distributorLimitExceeded', {\n    amount,\n  });\n};\n","import { useFormat } from '@finmid/translations';\nimport toCurrency from 'currency.js';\nimport { useFormContext } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../CreatePaymentRequestOnePage.types';\n\nexport const PlatformRecourseLimitExceededMessage = () => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice',\n  });\n  const { money } = useFormat();\n\n  const { getValues } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const buyer = getValues('buyer');\n\n  const availablePlatformRecourseLimit = money(\n    toCurrency(buyer?.availablePlatformRecourseLimit ?? 0),\n    buyer?.currency ?? 'EUR',\n  );\n\n  return t('paymentIntentCheck.platformRecourseLimitExceeded', {\n    availablePlatformRecourseLimit,\n  });\n};\n","import { currencySymbols } from '@finmid/tbl-webapps/utils';\nimport { TextInput } from '@finmid/ui/ocarina';\nimport { Control, Controller, FieldError, useWatch } from 'react-hook-form';\nimport { NumericFormat } from 'react-number-format';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../CreatePaymentRequestOnePage.types';\nimport { useCreatePaymentRequestFormLabels } from '../../../../../hooks';\n\nimport { BuyerLimitExceededMessage } from './BuyerLimitExceededMessage';\nimport { PlatformLimitExceededMessage } from './PlatformLimitExceededMessage';\nimport { PlatformRecourseLimitExceededMessage } from './PlatformRecourseLimitExceededMessage';\n\ntype AmountProps = {\n  control: Control<CreatePaymentRequestOnePageFormType>;\n};\n\nexport const AmountInput = ({ control }: AmountProps) => {\n  const { placeholders } = useCreatePaymentRequestFormLabels();\n\n  const currency = useWatch({\n    control,\n    name: 'currency',\n  });\n\n  const name = 'amount';\n\n  const renderError = (error: FieldError) => {\n    if (error.message === 'BUYER_EXPENSE_LIMIT_EXCEEDED') {\n      return <BuyerLimitExceededMessage />;\n    } else if (error.message === 'PLATFORM_CREDIT_LIMIT_EXCEEDED') {\n      return <PlatformLimitExceededMessage />;\n    } else if (error.message === 'PLATFORM_RECOURSE_LIMIT_EXCEEDED') {\n      return <PlatformRecourseLimitExceededMessage />;\n    }\n  };\n\n  return (\n    <Controller\n      control={control}\n      name={name}\n      render={({ field, fieldState }) => {\n        const { onChange, ref, ...rest } = field;\n        return (\n          <NumericFormat\n            decimalScale={2}\n            thousandSeparator\n            fixedDecimalScale\n            testId={`${name}Field`}\n            customInput={TextInput}\n            error={fieldState.error != null}\n            helperText={\n              fieldState.error != null\n                ? renderError?.(fieldState.error) || fieldState.error.message\n                : undefined\n            }\n            onValueChange={(v) => {\n              onChange(v.floatValue?.toString(10));\n            }}\n            startAdornment={currencySymbols[currency]}\n            placeholder={placeholders.amount}\n            fullWidth\n            {...rest}\n          />\n        );\n      }}\n    />\n  );\n};\n","import { FormCurrencySelector } from '@finmid/tbl-webapps/components';\nimport { useDistributorCurrencies } from '@finmid/tbl-webapps/hooks';\nimport { TextInputLabel } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { Control } from 'react-hook-form';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../CreatePaymentRequestOnePage.types';\nimport { useCreatePaymentRequestFormLabels } from '../../../../../hooks';\n\nimport { AmountInput } from './AmountInput';\n\ntype AmountAndCurrencyProps = {\n  control: Control<CreatePaymentRequestOnePageFormType>;\n};\n\nexport const AmountAndCurrencyInput = ({ control }: AmountAndCurrencyProps) => {\n  const { labels } = useCreatePaymentRequestFormLabels();\n  const { supportedCurrencies } = useDistributorCurrencies();\n\n  return (\n    <Box>\n      <TextInputLabel>{labels.amount}</TextInputLabel>\n      <Box display=\"grid\" gridTemplateColumns=\"auto 180px\" gap={2}>\n        <AmountInput control={control} />\n        <FormCurrencySelector currencies={supportedCurrencies} fullWidth />\n      </Box>\n    </Box>\n  );\n};\n","import {\n  AggregatedBuyer,\n  FrequentBuyer,\n  TBLCurrency,\n} from '@finmid/distributor-types';\nimport { useFormat } from '@finmid/translations';\nimport { Box, Typography } from '@mui/material';\nimport toCurrency from 'currency.js';\nimport { useTranslation } from 'react-i18next';\n\nexport function RenderBuyerWithRecourse({\n  buyer,\n  currency,\n}: {\n  buyer: AggregatedBuyer | FrequentBuyer;\n  currency: TBLCurrency;\n}) {\n  const { money } = useFormat();\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  return (\n    <Box\n      display=\"flex\"\n      justifyContent=\"space-between\"\n      alignItems=\"center\"\n      width=\"100%\"\n    >\n      <Box maxWidth=\"50%\">\n        <Typography fontSize=\"15px\" fontWeight={400}>\n          {buyer.legalName}\n        </Typography>\n      </Box>\n      <Box display=\"flex\" flexDirection=\"column\" alignItems=\"flex-end\">\n        <Typography fontSize=\"13px\" fontWeight={500}>\n          {t('totalLimit', {\n            totalLimit: money(toCurrency(buyer.availableLimit), currency),\n          })}\n        </Typography>\n        <Typography\n          fontSize=\"12px\"\n          fontWeight={400}\n          data-test-id=\"available-recourse\"\n        >\n          {t('limitSplit', {\n            base: money(toCurrency(buyer.availableBaseLimit), currency),\n            recourse: money(toCurrency(buyer.availableRecourseLimit), currency),\n          })}\n        </Typography>\n      </Box>\n    </Box>\n  );\n}\n","import { useGetFinancingConfigurationsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useMemo } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport { CheckPaymentRequestContext } from '../../../../../CheckPaymentRequest.context';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../CreatePaymentRequestOnePage.types';\n\nexport const useUseCaseHint = (useCase: CheckPaymentRequestContext) => {\n  const { data } = useGetFinancingConfigurationsQuery();\n  const { watch } = useFormContext<CreatePaymentRequestOnePageFormType>();\n\n  const selectedUseCaseName = watch('useCase');\n  const selectedUseCase = data?.find(\n    ({ useCase }) => useCase === selectedUseCaseName,\n  );\n\n  const defaultPayoutRatio = selectedUseCase?.payoutRatio;\n  // payoutRatio is the same for all terms,\n  // so we can use whatever term to access it\n  const payoutRatio = useCase?.repaymentMethods[0].payoutRatio;\n\n  const defaultTerm = selectedUseCase?.terms.find(\n    ({ period }) => period === useCase?.selectedTerm?.period,\n  );\n  const defaultTotalFee = defaultTerm?.serviceFee;\n  const totalFee =\n    useCase?.selectedTerm?.amountsBreakdown.financingAmountSplit\n      .baseFeePercentage;\n\n  const label = useMemo(() => {\n    if (useCase?.selectedTerm == null) {\n      return {\n        key: 'buyerSellerUseCaseHint.pending' as const,\n      };\n    }\n\n    const hasCustomPayoutRatio = payoutRatio !== defaultPayoutRatio;\n    const hasCustomTotalFee = totalFee != null && totalFee !== defaultTotalFee;\n\n    if (hasCustomPayoutRatio && hasCustomTotalFee) {\n      return {\n        key: 'buyerSellerUseCaseHint.payoutRatioAndFee' as const,\n        values: { payoutRatio, fee: totalFee },\n      };\n    }\n\n    if (hasCustomPayoutRatio) {\n      return {\n        key: 'buyerSellerUseCaseHint.payoutRatio' as const,\n        values: { payoutRatio },\n      };\n    }\n\n    if (hasCustomTotalFee) {\n      return {\n        key: 'buyerSellerUseCaseHint.fee' as const,\n        values: { fee: totalFee },\n      };\n    }\n  }, [\n    defaultPayoutRatio,\n    defaultTotalFee,\n    payoutRatio,\n    totalFee,\n    useCase?.selectedTerm,\n  ]);\n\n  return label;\n};\n","import { HelperText } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { CheckPaymentRequestContext } from '../../../../../CheckPaymentRequest.context';\n\nimport { useUseCaseHint } from './UseCaseHint.hook';\n\nexport const UseCaseHint = ({\n  useCase,\n}: {\n  useCase: CheckPaymentRequestContext;\n}) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice',\n  });\n\n  const useCaseHint = useUseCaseHint(useCase);\n\n  if (useCaseHint == null) return null;\n\n  return (\n    <Box data-test-id=\"use-case-hint\">\n      <HelperText level=\"info\">\n        <p>\n          <Trans\n            t={t}\n            i18nKey={useCaseHint.key}\n            values={useCaseHint.values}\n            components={{\n              strong: <strong />,\n            }}\n          />\n        </p>\n      </HelperText>\n    </Box>\n  );\n};\n","import { AggregatedBuyer, FrequentBuyer } from '@finmid/distributor-types';\nimport {\n  useGetFrequentBuyersQuery,\n  useLazyGetBuyersQuery,\n  useGetDistributorAttributesQuery,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { useDistributorCurrencies } from '@finmid/tbl-webapps/hooks';\nimport { useFormat } from '@finmid/translations';\nimport { Autocomplete, HelperText } from '@finmid/ui/ocarina';\nimport toCurrency from 'currency.js';\nimport debounce from 'lodash/debounce';\nimport { useCallback, useEffect, useMemo, useState } from 'react';\nimport {\n  Controller,\n  ControllerFieldState,\n  useFormContext,\n} from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { useCheckPaymentRequestContext } from '../../../../../CheckPaymentRequest.context';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../CreatePaymentRequestOnePage.types';\nimport { RecourseInfo } from '../../../../../components';\nimport { useRecourseContext } from '../../../../CreatePaymentRequestPageRecourseModal/components';\n\nimport { RenderBuyerWithRecourse } from './RenderBuyerWithRecourse';\nimport { UseCaseHint } from './UseCaseHint';\ntype BuyerSelectAsyncProps = {\n  disabled?: boolean;\n  fullWidth?: boolean;\n};\n\nexport const BuyerSelectAsync = ({\n  disabled = false,\n  fullWidth,\n}: BuyerSelectAsyncProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const { money } = useFormat();\n  const { control, watch, setValue, getFieldState } =\n    useFormContext<CreatePaymentRequestOnePageFormType>();\n  const { data } = useGetDistributorAttributesQuery();\n  const isRecourseEnabled = Number(data?.recourseLimit) > 0;\n  const [options, setOptions] = useState<AggregatedBuyer[]>([]);\n  const useCase = useCheckPaymentRequestContext();\n  const [emptyMessage, setEmptyMessage] = useState<string>();\n  const { defaultCurrency } = useDistributorCurrencies();\n  const { isRecourse, setIsRecourse } = useRecourseContext();\n  const currency = watch('currency');\n  const buyer = watch('buyer');\n  const amount = watch('amount');\n  const recourseText = t('recourseWarningWithLimits', {\n    baseLimit: money(buyer?.availableBaseLimit ?? 0, currency),\n    recourseLimit: money(buyer?.availableRecourseLimit ?? 0, currency),\n  });\n  const startMessage = t('paymentIntentCheck.buyerStartMessage');\n  const noOptionsMessage = t('paymentIntentCheck.buyerNoOptionsMessage');\n  const noOptionsText = emptyMessage ?? startMessage;\n  const errorMessage = t('paymentIntentCheck.buyerErrorMessage');\n  const loadingMessage = t('paymentIntentCheck.buyerSearchLoadingMessage');\n  const { data: frequentBuyers = [], refetch } = useGetFrequentBuyersQuery({\n    currency: currency || defaultCurrency,\n  });\n  const [showFrequentOptions, setShowFrequentOptions] = useState(false);\n\n  useEffect(() => {\n    if (frequentBuyers.length > 0) setShowFrequentOptions(true);\n  }, [frequentBuyers.length]);\n\n  useEffect(() => {\n    const isRecourse =\n      buyer &&\n      amount &&\n      +amount > buyer.availableBaseLimit &&\n      +amount <= buyer.availableLimit;\n    if (isRecourse && isRecourseEnabled) {\n      setIsRecourse(true);\n      setValue('customBaseAmount', buyer.availableBaseLimit);\n      setValue('customRecourseAmount', +amount - buyer.availableBaseLimit);\n    } else setIsRecourse(false);\n  }, [amount, buyer, setIsRecourse, setValue, isRecourseEnabled]);\n\n  const [fetchBuyers] = useLazyGetBuyersQuery();\n\n  const searchBuyers = useCallback(\n    async (value: string) => {\n      const inputValue = value;\n      const { data } = await fetchBuyers({\n        search: inputValue,\n        status: 'ACTIVE',\n        scope: 'AGGREGATED',\n      });\n\n      setOptions(data?.data ?? []);\n      if (data?.data && data.data.length === 0) {\n        setEmptyMessage(noOptionsMessage);\n      }\n    },\n    [fetchBuyers, noOptionsMessage],\n  );\n\n  const debouncedSearchBuyers = useMemo(\n    () => debounce(searchBuyers, 500),\n    [searchBuyers],\n  );\n\n  const handleClearInput = useCallback(() => {\n    if (frequentBuyers.length > 0) {\n      setShowFrequentOptions(true);\n    } else {\n      setOptions([]);\n      setEmptyMessage(startMessage);\n    }\n  }, [frequentBuyers.length, startMessage]);\n\n  const handleInputChange = useCallback(\n    (value: string) => {\n      if (value === '') {\n        handleClearInput();\n        return;\n      }\n      // loading state\n      setShowFrequentOptions(false);\n      setOptions([]);\n      setEmptyMessage(loadingMessage);\n\n      const selectedFromFrequent = frequentBuyers.some(\n        ({ legalName }) => legalName === value,\n      );\n      if (!selectedFromFrequent) debouncedSearchBuyers(value);\n    },\n    [debouncedSearchBuyers, frequentBuyers, handleClearInput, loadingMessage],\n  );\n\n  useEffect(() => {\n    setValue('buyer', null, {\n      shouldValidate: getFieldState('buyer').isTouched,\n    });\n    setOptions([]);\n    refetch();\n  }, [currency, refetch, setValue, getFieldState]);\n\n  const showError = (field: ControllerFieldState) =>\n    field.isTouched && !!field.error?.message;\n\n  return (\n    <Controller\n      defaultValue={null}\n      render={({ field, fieldState }) => (\n        <Autocomplete<FrequentBuyer | AggregatedBuyer>\n          {...field}\n          disabled={disabled}\n          data-test-id=\"buyers-autocomplete-async\"\n          noOptionsText={noOptionsText}\n          options={showFrequentOptions ? frequentBuyers : options}\n          optionsTitle={\n            showFrequentOptions\n              ? t('paymentIntentCheck.buyerFrequentlyUsed')\n              : undefined\n          }\n          filterOptions={(x) => x}\n          isOptionEqualToValue={(option, value) =>\n            option.legalName === value.legalName\n          }\n          label={t('paymentIntentCheck.buyerLabel')}\n          onInputChange={(_, data) => handleInputChange(data)}\n          onInputBlur={() => field.onBlur()}\n          error={showError(fieldState)}\n          helperText={\n            showError(fieldState) ? (\n              errorMessage\n            ) : (\n              <>\n                {isRecourse && (\n                  <HelperText level=\"warning\">\n                    <RecourseInfo infoText={recourseText} />\n                  </HelperText>\n                )}\n                {useCase.useCaseLevel === 'BUYER' && (\n                  <UseCaseHint useCase={useCase} />\n                )}\n              </>\n            )\n          }\n          helperLevel={\n            showError(fieldState) ? 'error' : isRecourse ? 'warning' : 'info'\n          }\n          testId=\"buyers-async-input\"\n          getOptionLabel={(option) => option.legalName}\n          onChange={async (_, data) => {\n            if (data == null) return field.onChange(data);\n            field.onChange({\n              currency: data.currency,\n              externalId: data.externalId,\n              availableLimit: data.availableLimit,\n              id: data.id,\n              legalName: data.legalName,\n              availableRecourseLimit: data.availableRecourseLimit,\n              availableBaseLimit: data.availableBaseLimit,\n              availablePlatformRecourseLimit:\n                data.availablePlatformRecourseLimit,\n              useCase: data.useCase,\n            });\n            const isFrequentBuyer = !('legalAddress' in data);\n            setShowFrequentOptions(isFrequentBuyer);\n          }}\n          renderOption={\n            isRecourseEnabled\n              ? (option) => (\n                  <RenderBuyerWithRecourse buyer={option} currency={currency} />\n                )\n              : undefined\n          }\n          fullWidth={fullWidth}\n          placeholder={showFrequentOptions ? startMessage : undefined}\n          badge={\n            field.value?.availableLimit != null\n              ? t('buyerLimitBadge', {\n                  limit: money(\n                    toCurrency(field.value.availableLimit),\n                    currency,\n                  ),\n                })\n              : undefined\n          }\n        />\n      )}\n      name=\"buyer\"\n      control={control}\n    />\n  );\n};\n","import {\n  handledCurrencies,\n  Seller,\n  TBLCurrency,\n} from '@finmid/distributor-types';\nimport {\n  useGetFrequentSellersQuery,\n  useLazyGetSellersQuery,\n} from '@finmid/tbl-webapps/gateway-api';\nimport debounce from 'lodash/debounce';\nimport { useCallback, useEffect, useMemo, useState } from 'react';\nimport { ControllerFieldState, useFormContext } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\ntype UseSellerSelectAsyncArgs = {\n  currency: TBLCurrency;\n};\n\nexport const useSellerSelectAsync = ({\n  currency,\n}: UseSellerSelectAsyncArgs) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const { control, setValue, getFieldState } = useFormContext();\n  const [options, setOptions] = useState<Seller[]>([]);\n  const [emptyMessage, setEmptyMessage] = useState<string>();\n\n  const startMessage = t('paymentIntentCheck.sellerStartMessage');\n  const noOptionsMessage = t('paymentIntentCheck.sellerNoOptionsMessage');\n  const noOptionsText = emptyMessage ?? startMessage;\n  const errorMessage = t('paymentIntentCheck.sellerErrorMessage');\n  const loadingMessage = t('paymentIntentCheck.sellerSearchLoadingMessage');\n\n  const { data: frequentSellers = [], refetch } = useGetFrequentSellersQuery(\n    {\n      currency,\n    },\n    { skip: !handledCurrencies.includes(currency) },\n  );\n  const [showFrequentOptions, setShowFrequentOptions] = useState(false);\n\n  useEffect(() => {\n    if (frequentSellers.length > 0) setShowFrequentOptions(true);\n  }, [frequentSellers.length]);\n\n  const [fetchSellers] = useLazyGetSellersQuery();\n\n  const isSelectedFromFrequent = useCallback(\n    (legalName: string) =>\n      frequentSellers.some((seller) => seller.legalName === legalName),\n    [frequentSellers],\n  );\n\n  const searchSellers = useCallback(\n    async (value: string) => {\n      const inputValue = value.trim();\n      const { data } = await fetchSellers({\n        search: inputValue,\n        status: 'ACTIVE',\n      });\n\n      const sellers = data?.data ?? [];\n      const filteredSellers = sellers.filter((seller) =>\n        seller.bankAccounts.some((account) => account.currency === currency),\n      );\n\n      setOptions(filteredSellers);\n      if (filteredSellers.length === 0) {\n        setEmptyMessage(noOptionsMessage);\n      }\n    },\n    [currency, fetchSellers, noOptionsMessage],\n  );\n\n  const debouncedSearchSellers = useMemo(\n    () => debounce(searchSellers, 500),\n    [searchSellers],\n  );\n\n  const handleClearInput = useCallback(() => {\n    if (frequentSellers.length > 0) {\n      setShowFrequentOptions(true);\n    } else {\n      setOptions([]);\n      setEmptyMessage(startMessage);\n    }\n  }, [frequentSellers.length, startMessage]);\n\n  const handleInputChange = useCallback(\n    (value: string) => {\n      if (value === '') {\n        handleClearInput();\n        return;\n      }\n\n      // loading state\n      setShowFrequentOptions(false);\n      setOptions([]);\n      setEmptyMessage(loadingMessage);\n\n      if (!isSelectedFromFrequent(value)) {\n        debouncedSearchSellers(value);\n      }\n    },\n    [\n      debouncedSearchSellers,\n      handleClearInput,\n      isSelectedFromFrequent,\n      loadingMessage,\n    ],\n  );\n\n  useEffect(() => {\n    setValue('seller', null, {\n      shouldValidate: getFieldState('seller').isTouched,\n    });\n    setOptions([]);\n    refetch();\n  }, [currency, refetch, setValue, getFieldState]);\n\n  const showError = (field: ControllerFieldState) =>\n    field.isTouched && !!field.error?.message;\n\n  return {\n    t,\n    control,\n    startMessage,\n    noOptionsText,\n    errorMessage,\n    showFrequentOptions,\n    setShowFrequentOptions,\n    isSelectedFromFrequent,\n    frequentSellers,\n    options,\n    handleInputChange,\n    showError,\n  };\n};\n","import { FrequentSeller, Seller, TBLCurrency } from '@finmid/distributor-types';\nimport { Autocomplete } from '@finmid/ui/ocarina';\nimport { Controller } from 'react-hook-form';\n\nimport { useCheckPaymentRequestContext } from '../../../../../../CheckPaymentRequest.context';\nimport { UseCaseHint } from '../UseCaseHint';\n\nimport { useSellerSelectAsync } from './SellerSelectAsync.hook';\n\ntype SelectedSeller = Pick<Seller, 'externalId' | 'legalName'>;\n\ntype SellerSelectAsyncProps = {\n  disabled?: boolean;\n  fullWidth?: boolean;\n  label: string;\n  handleChange?: (data: SelectedSeller | null) => void;\n  currency: TBLCurrency;\n};\n\nexport const SellerSelectAsync = ({\n  disabled,\n  fullWidth,\n  label,\n  handleChange,\n  currency,\n}: SellerSelectAsyncProps) => {\n  const {\n    t,\n    control,\n    startMessage,\n    noOptionsText,\n    errorMessage,\n    showFrequentOptions,\n    setShowFrequentOptions,\n    isSelectedFromFrequent,\n    frequentSellers,\n    options,\n    handleInputChange,\n    showError,\n  } = useSellerSelectAsync({ currency });\n  const useCase = useCheckPaymentRequestContext();\n\n  return (\n    <Controller\n      defaultValue={null}\n      render={({ field, fieldState }) => (\n        <Autocomplete<Seller | FrequentSeller>\n          {...field}\n          disabled={disabled}\n          data-test-id=\"seller-autocomplete-async\"\n          noOptionsText={noOptionsText}\n          options={showFrequentOptions ? frequentSellers : options}\n          optionsTitle={\n            showFrequentOptions\n              ? t('paymentIntentCheck.sellerFrequentlyUsed')\n              : undefined\n          }\n          filterOptions={(x) => x}\n          isOptionEqualToValue={(option, value) =>\n            option.legalName === value.legalName\n          }\n          label={label}\n          onInputChange={(_, data) => handleInputChange(data)}\n          onInputBlur={() => field.onBlur()}\n          testId=\"seller-async-input\"\n          error={showError(fieldState)}\n          helperText={\n            showError(fieldState) ? (\n              errorMessage\n            ) : useCase.useCaseLevel === 'SELLER' ? (\n              <UseCaseHint useCase={useCase} />\n            ) : undefined\n          }\n          getOptionLabel={(option) => option.legalName}\n          onChange={async (_, data) => {\n            const selectedSeller =\n              data == null\n                ? null\n                : {\n                    externalId: data.externalId,\n                    legalName: data.legalName,\n                  };\n            handleChange?.(selectedSeller);\n            field.onChange(selectedSeller);\n\n            if (isSelectedFromFrequent(selectedSeller?.legalName ?? '')) {\n              setShowFrequentOptions(true);\n            }\n          }}\n          fullWidth={fullWidth}\n          placeholder={showFrequentOptions ? startMessage : undefined}\n        />\n      )}\n      name=\"seller\"\n      control={control}\n    />\n  );\n};\n","import { useGetSellerUseCaseQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { TextInput } from '@finmid/ui/ocarina';\nimport { useFormContext } from 'react-hook-form';\n\nimport { useCheckPaymentRequestContext } from '../../../../../CheckPaymentRequest.context';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../CreatePaymentRequestOnePage.types';\nimport {\n  useCheckUniqueSeller,\n  useCreatePaymentRequestFormLabels,\n} from '../../../../../hooks';\n\nimport { SellerSelectAsync } from './SellerSelectAsync';\nimport { UseCaseHint } from './UseCaseHint';\n\nexport const SellerInput = () => {\n  const { uniqueSeller } = useCheckUniqueSeller();\n\n  const { labels } = useCreatePaymentRequestFormLabels();\n  const label = labels.seller;\n\n  const { watch } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const watchCurrency = watch('currency');\n  const useCase = useCheckPaymentRequestContext();\n\n  const { data: useCaseResponse } = useGetSellerUseCaseQuery(\n    { externalId: uniqueSeller?.externalId ?? '' },\n    { skip: uniqueSeller == null },\n  );\n\n  if (uniqueSeller != null) {\n    return (\n      <TextInput\n        value={uniqueSeller.legalName}\n        disabled\n        label={label}\n        testId=\"seller-unique-input\"\n        fullWidth\n        hint={useCaseResponse?.useCase && <UseCaseHint useCase={useCase} />}\n      />\n    );\n  }\n\n  return <SellerSelectAsync currency={watchCurrency} label={label} fullWidth />;\n};\n","import { GetFinancingConfigurations } from '@finmid/distributor-types';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { useGetFinancingConfigurationsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { Autocomplete } from '@finmid/ui/ocarina';\nimport { Stack } from '@mui/material';\nimport { useEffect, useMemo } from 'react';\nimport { Controller, useFormContext } from 'react-hook-form';\n\nimport { useUseCaseCopy } from '../../../../../../shared';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../CreatePaymentRequestOnePage.types';\nimport { useCreatePaymentRequestFormLabels } from '../../../../../hooks';\n\ntype PlatformConfigOptionProps = {\n  option: GetFinancingConfigurations.ApiResponse[number];\n};\n\nconst PlatformConfigOption = ({ option }: PlatformConfigOptionProps) => {\n  const { title, describe } = useUseCaseCopy();\n\n  return (\n    <Stack\n      direction=\"row\"\n      justifyContent=\"space-between\"\n      alignItems=\"center\"\n      gap={1}\n      flex={1}\n      overflow=\"hidden\"\n    >\n      <span>{title(option.useCase)}</span>\n      <Typography fontSize={13} fontStyle={'italic'}>\n        {describe(option.useCase) ?? '-'}\n      </Typography>\n    </Stack>\n  );\n};\n\nexport const TransactionTypeSelect = () => {\n  const methods = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const { control, setValue } = methods;\n  const { title, describe } = useUseCaseCopy();\n\n  const { data: financingConfigurations } =\n    useGetFinancingConfigurationsQuery();\n  const { labels, placeholders } = useCreatePaymentRequestFormLabels();\n\n  const platformFinancingConfigurations = useMemo(\n    () => financingConfigurations?.filter(({ level }) => level === 'PLATFORM'),\n    [financingConfigurations],\n  );\n\n  useEffect(() => {\n    if (platformFinancingConfigurations?.length) {\n      const defaultConfig =\n        platformFinancingConfigurations.find(\n          ({ default: isDefault }) => isDefault,\n        ) ?? platformFinancingConfigurations[0];\n      if (defaultConfig) {\n        setValue('useCase', defaultConfig.useCase, {\n          shouldTouch: true,\n          shouldValidate: true,\n        });\n      }\n    }\n  }, [platformFinancingConfigurations, setValue]);\n\n  if (\n    platformFinancingConfigurations == null ||\n    platformFinancingConfigurations?.length <= 1\n  ) {\n    return null;\n  }\n\n  return (\n    <Controller\n      name=\"useCase\"\n      control={control}\n      render={({ field }) => (\n        <Autocomplete<GetFinancingConfigurations.ApiResponse[number]>\n          {...field}\n          value={\n            platformFinancingConfigurations.find(\n              (config) => config.useCase === field.value,\n            ) || null\n          }\n          disabled={platformFinancingConfigurations.length <= 1}\n          label={labels.useCase}\n          placeholder={placeholders.useCase}\n          optionsTitle={placeholders.useCase}\n          fullWidth\n          options={platformFinancingConfigurations}\n          getOptionLabel={(option) => title(option.useCase)}\n          renderOption={(option) => <PlatformConfigOption option={option} />}\n          helperText={field.value && describe(field.value)}\n          helperLevel={field.value ? 'info' : undefined}\n          isOptionEqualToValue={(option, value) =>\n            option.useCase === value.useCase\n          }\n          onChange={(_, data) => {\n            field.onChange(data?.useCase);\n          }}\n          onInputBlur={() => field.onBlur()}\n          testId=\"transaction-type-select\"\n        />\n      )}\n    />\n  );\n};\n","import {\n  useLazyCheckInvoiceNumberExistsQuery,\n  useLazyCheckPaymentRequestExistsQuery,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { useUniqueId } from '@finmid/tbl-webapps/hooks';\nimport { FieldValues, UseFormReturn } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../CreatePaymentRequestOnePage.types';\n\nexport const useCheckPaymentRequestUniqueId = (\n  methods: UseFormReturn<\n    CreatePaymentRequestOnePageFormType,\n    FieldValues,\n    undefined\n  >,\n) => {\n  const { t } = useTranslation('invoicesPage');\n\n  const [getPaymentRequestById] = useLazyCheckPaymentRequestExistsQuery();\n\n  const checkUniqueId = useUniqueId({\n    field: 'paymentRequestId',\n    methods: methods,\n    message: t('validation.paymenRequestIdUnique'),\n    lazyQuery: getPaymentRequestById,\n  });\n\n  return checkUniqueId;\n};\n\nexport const useCheckInvoiceUniqueId = (\n  methods: UseFormReturn<\n    CreatePaymentRequestOnePageFormType,\n    FieldValues,\n    undefined\n  >,\n) => {\n  const { t } = useTranslation('invoicesPage');\n\n  const [checkInvoiceNumberExists] = useLazyCheckInvoiceNumberExistsQuery();\n\n  const checkUniqueId = useUniqueId({\n    field: 'invoiceId',\n    methods: methods,\n    message: t('validation.invoiceIdUnique'),\n    lazyQuery: checkInvoiceNumberExists,\n  });\n\n  return checkUniqueId;\n};\n","import {\n  FormTextField,\n  SectionContainer,\n  SectionContent,\n  SectionHeader,\n} from '@finmid/tbl-webapps/components';\nimport debounce from 'lodash/debounce';\nimport { useFormContext } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\nimport { useLocation } from 'react-router-dom';\nimport { useMount } from 'react-use';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../CreatePaymentRequestOnePage.types';\nimport { useCreatePaymentRequestFormLabels } from '../../../../hooks';\n\nimport { useCheckPaymentRequestUniqueId } from './FormAmountAndParties.hooks';\nimport {\n  AmountAndCurrencyInput,\n  BuyerSelectAsync,\n  SellerInput,\n  TransactionTypeSelect,\n} from './components';\n\nconst ALPHA_NUMERIC_DASH_REGEX = /^[a-zA-Z0-9-._]+$/;\n\nexport const FormAmountAndParties = () => {\n  const { labels, placeholders, sections } =\n    useCreatePaymentRequestFormLabels();\n  const methods = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const { control, setValue } = methods;\n  const location = useLocation();\n  const { t } = useTranslation('invoicesPage');\n\n  useMount(() => {\n    const seller = location.state?.seller;\n    const buyer = location.state?.buyer;\n\n    if (seller) {\n      setValue('seller', seller);\n    }\n    if (buyer) {\n      setValue('buyer', buyer);\n    }\n  });\n\n  const checkUniqueId = useCheckPaymentRequestUniqueId(methods);\n\n  return (\n    <SectionContainer>\n      <SectionHeader>{sections.amountAndParties}</SectionHeader>\n      <SectionContent style={{ gap: 24 }}>\n        <TransactionTypeSelect />\n\n        <FormTextField\n          control={control}\n          name=\"paymentRequestId\"\n          label={labels.paymentRequestId}\n          placeholder={placeholders.paymentRequestId}\n          tooltip={t('validation.paymentRequestIdRegex')}\n          autoFocus\n          handleChange={debounce(checkUniqueId, 300)}\n          fullWidth\n          onKeyDown={(e) => {\n            if (!ALPHA_NUMERIC_DASH_REGEX.test(e.key)) {\n              e.preventDefault();\n            }\n          }}\n        />\n\n        <AmountAndCurrencyInput control={control} />\n\n        <BuyerSelectAsync fullWidth />\n\n        <SellerInput />\n      </SectionContent>\n    </SectionContainer>\n  );\n};\n","import styled from '@emotion/styled';\n\nconst transitionTimingFunction = 'cubic-bezier(0.4, 0, 0.2, 1)';\nconst transitionDuration = '200ms';\n\nexport const Root = styled.span(({ theme }) => ({\n  width: 40,\n  height: 20,\n  cursor: 'pointer',\n  position: 'relative',\n  display: 'block',\n\n  '&.base--checked': {\n    '.base-Switch-thumb': {\n      left: 20,\n    },\n\n    '.base-Switch-track': {\n      backgroundColor: theme.palette.violet[500],\n    },\n  },\n\n  '&.base--focusVisible': {\n    '.base-Switch-thumb': {\n      outline: '1px solid white',\n    },\n  },\n}));\n\nexport const Track = styled.span(({ theme }) => ({\n  backgroundColor: theme.glo.color.foundations[20],\n  borderRadius: 8,\n  display: 'block',\n  width: '100%',\n  height: '100%',\n  position: 'absolute',\n  transitionProperty: 'background-color',\n  transitionTimingFunction,\n  transitionDuration,\n}));\n\nexport const Thumb = styled.span(({ theme }) => ({\n  backgroundColor: theme.palette.white,\n  borderRadius: 8,\n  borderColor: theme.glo.color.foundations[40],\n  borderWidth: 1,\n  borderStyle: 'solid',\n  display: 'flex',\n  width: 20,\n  height: 20,\n  left: 0,\n  position: 'relative',\n  alignItems: 'center',\n  justifyContent: 'center',\n  transitionProperty: 'left',\n  transitionTimingFunction,\n  transitionDuration,\n}));\n\nexport const Input = styled.input({\n  opacity: 0,\n  top: 0,\n  left: 0,\n  width: '100%',\n  height: '100%',\n  position: 'absolute',\n  cursor: 'inherit',\n  margin: 0,\n  zIndex: 1,\n});\n","import { Switch as MuiSwitch } from '@mui/base';\n\nimport { Input, Root, Thumb, Track } from './InstantPayoutSwitch.styled';\n\ntype InstantSwitchProps = {\n  checked: boolean;\n  testId?: string;\n  handleChange: (checked: boolean) => void;\n};\n\nexport const InstantPayoutSwitch = ({\n  checked,\n  testId,\n  handleChange,\n}: InstantSwitchProps) => {\n  return (\n    <MuiSwitch\n      checked={checked}\n      onChange={(e) => {\n        handleChange(e.target.checked);\n      }}\n      data-test-id={testId}\n      slots={{\n        root: Root,\n        track: Track,\n        thumb: Thumb,\n        input: Input,\n      }}\n      slotProps={{ input: { role: 'switch' } }}\n    />\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { Box } from '@mui/material';\nimport { Controller, useFormContext } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { InstantPayoutSwitch } from '../../../../../../../components/InstantPayoutSwitch';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../CreatePaymentRequestOnePage.types';\n\nexport const InstantPayout = () => {\n  const theme = useTheme();\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const { control } = useFormContext<CreatePaymentRequestOnePageFormType>();\n\n  return (\n    <Box p={2} bgcolor={theme.glo.color.foundations[10]} borderRadius={2}>\n      <Box display=\"flex\" justifyContent=\"space-between\">\n        <Typography fontSize={13} fontWeight={600}>\n          {t('instantPayoutTitle')}\n        </Typography>\n\n        <Controller\n          name=\"instantPayout\"\n          control={control}\n          render={({ field: { onChange, value } }) => (\n            <InstantPayoutSwitch\n              checked={value}\n              testId=\"instant-payout-toggle\"\n              handleChange={onChange}\n            />\n          )}\n        />\n      </Box>\n\n      <Typography\n        fontSize={13}\n        mt={0.5}\n        color={theme.glo.color.foundations[60]}\n      >\n        {t('instantPayoutInfo')}\n      </Typography>\n    </Box>\n  );\n};\n","import { Dispatch, SetStateAction } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../CreatePaymentRequestOnePage.types';\n\ntype UseTriggerValidationOnInputChangeProps = {\n  setIsTouched: Dispatch<SetStateAction<boolean>>;\n  triggerInvoiceDueDateValidation: () => Promise<void>;\n};\n\nexport const useTriggerValidationOnInputChange = ({\n  setIsTouched,\n  triggerInvoiceDueDateValidation,\n}: UseTriggerValidationOnInputChangeProps) => {\n  const { setValue } = useFormContext<CreatePaymentRequestOnePageFormType>();\n\n  const handleChange = async (value: Date | null) => {\n    setIsTouched(true);\n    setValue('invoiceDueDate', value ?? undefined);\n    await triggerInvoiceDueDateValidation();\n  };\n\n  return {\n    handleChange,\n  };\n};\n","import { useEffect, useRef } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../CreatePaymentRequestOnePage.types';\n\ntype UseTriggerValidationOnInstantPayoutChangeProps = {\n  triggerInvoiceDueDateValidation: () => Promise<void>;\n};\n\nexport const useTriggerValidationOnInstantPayoutChange = ({\n  triggerInvoiceDueDateValidation,\n}: UseTriggerValidationOnInstantPayoutChangeProps) => {\n  const instantPayoutHasChanged = useRef<boolean>(false);\n  const { getFieldState, watch } =\n    useFormContext<CreatePaymentRequestOnePageFormType>();\n  const watchInstantPayout = watch('instantPayout');\n\n  // mark user action on instantPayout field\n  useEffect(() => {\n    const instantPayoutIsDirty = getFieldState('instantPayout').isDirty;\n    if (instantPayoutIsDirty) {\n      instantPayoutHasChanged.current = true;\n    }\n  }, [watchInstantPayout, getFieldState]);\n\n  useEffect(() => {\n    if (instantPayoutHasChanged.current) {\n      void triggerInvoiceDueDateValidation();\n    }\n  }, [watchInstantPayout, triggerInvoiceDueDateValidation]);\n\n  return {\n    instantPayoutHasChanged,\n  };\n};\n","import { useEffect } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../CreatePaymentRequestOnePage.types';\n\ntype UseTriggerValidationOnInvoiceDueDateChangeProps = {\n  triggerInvoiceDueDateValidation: () => Promise<void>;\n};\n\nexport const useTriggerValidationOnInvoiceDueDateChange = ({\n  triggerInvoiceDueDateValidation,\n}: UseTriggerValidationOnInvoiceDueDateChangeProps) => {\n  const { watch } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const watchInvoiceDueDate = watch('invoiceDueDate');\n\n  useEffect(() => {\n    void triggerInvoiceDueDateValidation();\n  }, [watchInvoiceDueDate, triggerInvoiceDueDateValidation]);\n};\n","import { useCallback, useState } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../CreatePaymentRequestOnePage.types';\n\ntype UseValidateInvoiceDueDateProps = {\n  isTouched: boolean;\n};\n\nexport const useValidateInvoiceDueDate = ({\n  isTouched,\n}: UseValidateInvoiceDueDateProps) => {\n  const [showError, setShowError] = useState(false);\n  const [errorMessage, setErrorMessage] = useState<string | undefined>();\n\n  const { getFieldState, trigger } =\n    useFormContext<CreatePaymentRequestOnePageFormType>();\n\n  const triggerInvoiceDueDateValidation = useCallback(async () => {\n    const isFieldValid = await trigger('invoiceDueDate');\n\n    if (isFieldValid) {\n      setShowError(false);\n      setErrorMessage(undefined);\n    } else {\n      const currentState = getFieldState('invoiceDueDate');\n      setShowError(isTouched);\n      setErrorMessage(currentState.error?.message);\n    }\n  }, [isTouched, getFieldState, trigger]);\n\n  return {\n    errorMessage,\n    showError,\n    triggerInvoiceDueDateValidation,\n  };\n};\n","import { useState } from 'react';\n\nexport const useWatchInputIsTouched = () => {\n  const [isTouched, setIsTouched] = useState(false);\n  return {\n    isTouched,\n    setIsTouched,\n  };\n};\n","import { useFormContext } from 'react-hook-form';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../CreatePaymentRequestOnePage.types';\nimport { useCreatePaymentRequestFormLabels } from '../../../../../../../hooks';\n\nimport { useTriggerValidationOnInputChange } from './triggerValidationOnInputChange.hook';\nimport { useTriggerValidationOnInstantPayoutChange } from './triggerValidationOnInstantPayoutChange.hook';\nimport { useTriggerValidationOnInvoiceDueDateChange } from './triggerValidationOnInvoiceDueDateChange.hook';\nimport { useValidateInvoiceDueDate } from './validateInvoiceDueDate.hook';\nimport { useWatchInputIsTouched } from './watchInputIsTouched.hook';\n\nexport const useInvoiceDueDate = () => {\n  const { labels, placeholders } = useCreatePaymentRequestFormLabels();\n  const { watch } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const watchInstantPayout = watch('instantPayout');\n  const watchInvoiceDueDate = watch('invoiceDueDate');\n\n  const { isTouched, setIsTouched } = useWatchInputIsTouched();\n\n  const { errorMessage, showError, triggerInvoiceDueDateValidation } =\n    useValidateInvoiceDueDate({ isTouched });\n\n  const { handleChange } = useTriggerValidationOnInputChange({\n    setIsTouched,\n    triggerInvoiceDueDateValidation,\n  });\n  useTriggerValidationOnInstantPayoutChange({\n    triggerInvoiceDueDateValidation,\n  });\n  useTriggerValidationOnInvoiceDueDateChange({\n    triggerInvoiceDueDateValidation,\n  });\n\n  return {\n    labels,\n    placeholders,\n    watchInstantPayout,\n    watchInvoiceDueDate,\n    errorMessage,\n    showError,\n    handleChange,\n  };\n};\n","import { DatePickerOcarinaLike } from '@finmid/tbl-webapps/components';\nimport { TextInputLabel } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\n\nimport { useCheckPaymentRequestContext } from '../../../../../../CheckPaymentRequest.context';\nimport { useCreatePaymentRequestFormPayload } from '../../../../../../CreatePaymentRequestForm.context';\n\nimport { useInvoiceDueDate } from './hooks';\n\nexport const InvoiceDueDate = () => {\n  const {\n    labels,\n    placeholders,\n    watchInstantPayout,\n    watchInvoiceDueDate,\n    errorMessage,\n    showError,\n    handleChange,\n  } = useInvoiceDueDate();\n\n  const { minInvoiceDueDate, maxInvoiceDueDate } =\n    useCreatePaymentRequestFormPayload();\n\n  const { allowPayoutWithoutDueDate } = useCheckPaymentRequestContext();\n\n  return (\n    <Box flexGrow={1}>\n      <div>\n        <TextInputLabel\n          required={watchInstantPayout && !allowPayoutWithoutDueDate}\n        >\n          {labels.invoiceDueDate}\n        </TextInputLabel>\n        <DatePickerOcarinaLike\n          testId=\"invoiceDueDate\"\n          placeholder={placeholders.invoiceDueDate}\n          disablePast\n          disabled={false}\n          value={watchInvoiceDueDate}\n          maxDate={maxInvoiceDueDate}\n          minDate={minInvoiceDueDate}\n          onChange={handleChange}\n          placement=\"right-end\"\n          slotProps={{\n            textField: {\n              error: showError,\n              helperText: showError && errorMessage,\n            },\n            popper: { disablePortal: true },\n          }}\n        />\n      </div>\n    </Box>\n  );\n};\n","import { FormTextField } from '@finmid/tbl-webapps/components';\nimport { TextInputLabel } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport debounce from 'lodash/debounce';\nimport { useFormContext } from 'react-hook-form';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../CreatePaymentRequestOnePage.types';\nimport { useCreatePaymentRequestFormLabels } from '../../../../../../hooks';\nimport { useCheckInvoiceUniqueId } from '../../../FormAmountAndParties/FormAmountAndParties.hooks';\n\nexport const InvoiceId = () => {\n  const methods = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const { labels, placeholders } = useCreatePaymentRequestFormLabels();\n  const instantPayout = methods.watch('instantPayout');\n\n  const checkUniqueId = useCheckInvoiceUniqueId(methods);\n\n  return (\n    <Box flexGrow={1}>\n      <TextInputLabel required={instantPayout}>\n        {labels.invoiceId}\n      </TextInputLabel>\n      <FormTextField\n        control={methods.control}\n        name=\"invoiceId\"\n        placeholder={placeholders.invoiceId}\n        handleChange={debounce(checkUniqueId, 300)}\n        fullWidth\n      />\n    </Box>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { InfoIcon } from '@finmid/ui/ocarina';\nimport { Typography } from '@mui/material';\nimport Box from '@mui/material/Box';\n\nimport { useRecourseContext } from './CreatePaymentRequestPageRecourseModal/components/RecourseModal.context';\ninterface Props {\n  infoText: string;\n}\nexport const RecourseInfo = ({ infoText }: Props) => {\n  const { setIsRecourseDialogOpen } = useRecourseContext();\n  const { com } = useTheme();\n\n  return (\n    <Box\n      sx={{ margin: 0 }}\n      data-test-id=\"recourse-warning\"\n      color={com.textInput.color.fg.message}\n    >\n      <Typography fontSize={13} fontWeight={400} lineHeight=\"16px\">\n        {infoText}\n        <span\n          style={{\n            display: 'inline-block',\n            width: '16px',\n            height: '16px',\n            marginLeft: '4px',\n            verticalAlign: 'bottom',\n            cursor: 'pointer',\n          }}\n        >\n          <InfoIcon\n            width={16}\n            height={16}\n            onClick={() => setIsRecourseDialogOpen(true)}\n          />\n        </span>\n      </Typography>\n    </Box>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Box } from '@mui/system';\n\nconst borderRadius = 12;\n\nexport const ButtonWrapper = styled('label', {\n  shouldForwardProp: (p) => !['disabled', 'selected'].includes(p),\n})<{ disabled: boolean; selected: boolean }>(\n  ({ theme: { com, glo }, disabled, selected }) => ({\n    flexBasis: 170,\n    flexGrow: 1,\n    flexShrink: 1,\n\n    display: 'grid',\n    gridTemplateAreas: `\"radio term fee\"`,\n    gridTemplateColumns: 'auto 1fr auto',\n    cursor: 'pointer',\n    padding: 8,\n    border: '1px solid',\n    borderRadius,\n    borderColor: selected\n      ? glo.color.roles.accent[60]\n      : glo.color.foundations[20],\n\n    ...(disabled && {\n      cursor: 'not-allowed',\n    }),\n\n    backgroundColor: glo.color.foundations[0],\n    position: 'relative',\n    zIndex: 1,\n\n    '> p': {\n      alignSelf: 'center',\n      whiteSpace: 'nowrap',\n    },\n  }),\n);\n\nexport const LabelWrapper = styled(Box)(({ theme: { com } }) => ({\n  width: '100%',\n  display: 'flex',\n  justifyContent: 'space-between',\n}));\n\nexport const RadioInput = styled.input(({ theme: { com } }) => ({\n  appearance: 'none',\n\n  width: 16,\n  height: 16,\n  padding: 0,\n  margin: 0,\n  marginRight: 8,\n\n  position: 'relative',\n  cursor: 'pointer',\n  boxSizing: 'border-box',\n\n  fill: com.radioButton.color.bg.default,\n  borderStyle: 'solid',\n  borderWidth: com.radioButton.borderWidth,\n  borderColor: com.radioButton.color.border.default,\n  borderRadius: com.radioButton.radius,\n\n  display: 'flex',\n  justifyContent: 'center',\n  alignItems: 'center',\n  flexShrink: 0,\n\n  '&[data-focus=\"true\"],&:focus-visible': {\n    outline: 'none',\n    boxShadow: com.button.shadow.focus,\n  },\n\n  '&:checked': {\n    borderColor: com.radioButton.color.border.defaultSelected,\n    backgroundColor: com.radioButton.color.bg.defaultSelected,\n\n    '&:after': {\n      display: 'block',\n      backgroundColor: com.radioButton.color.border.defaultSelected,\n    },\n\n    '&[data-focus=\"true\"],&:focus-visible': {\n      boxShadow: com.button.shadow.focus,\n    },\n  },\n\n  '&:after': {\n    content: '\"\"',\n    display: 'none',\n\n    width: 6,\n    height: 6,\n    borderRadius: '50%',\n  },\n\n  '&:disabled': {\n    borderColor: com.radioButton.color.border.disabled,\n    color: com.radioButton.content.color.fg.disabled,\n    fill: com.radioButton.content.color.fg.disabled,\n    backgroundColor: com.radioButton.color.bg.disabled,\n    cursor: 'not-allowed',\n\n    '&:checked': {\n      borderColor: com.radioButton.color.border.disabledSelected,\n      backgroundColor: com.radioButton.color.bg.disabledSelected,\n\n      '&:after': {\n        display: 'block',\n        backgroundColor: com.radioButton.color.fg.disabledSelected,\n      },\n    },\n  },\n}));\n\nexport const BottomLabel = styled.div(({ theme: { com } }) => ({\n  backgroundColor: com.radioButton.color.border.focusSelected,\n  paddingTop: 12,\n  paddingBottom: 3,\n  display: 'flex',\n  justifyContent: 'center',\n  borderBottomRightRadius: borderRadius,\n  borderBottomLeftRadius: borderRadius,\n}));\n","export const getOptionDetails = (value: string) => {\n  const values = value.split('_');\n  return values.map((value) => Number(value));\n};\n","import styled, { CSSObject } from '@emotion/styled';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { currencyIcons } from '@finmid/tbl-webapps/utils';\nimport { Icon } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { shouldForwardProp } from '@mui/system';\nimport { HTMLProps, PropsWithChildren } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../../../../../../CreatePaymentRequestOnePage.types';\n\nconst transitionTimingFunction = 'cubic-bezier(0.4, 0, 0.2, 1)';\nconst transitionDuration = '200ms';\n\nexport const Input = styled.input({\n  opacity: 0,\n  top: 0,\n  left: 0,\n  width: '100%',\n  height: '100%',\n  position: 'absolute',\n  cursor: 'inherit',\n  margin: 0,\n  zIndex: 1,\n});\n\nexport const Thumb = styled(\n  (props: HTMLProps<HTMLSpanElement>) => {\n    if (props.content === 'PERCENTAGE') {\n      return (\n        <span {...props}>\n          <Typography color=\"black\">%</Typography>\n        </span>\n      );\n    }\n    const { watch } = useFormContext<CreatePaymentRequestOnePageFormType>();\n    const watchCurrency = watch('currency');\n\n    return (\n      <span {...props}>\n        <Icon\n          size=\"small\"\n          icon={currencyIcons[watchCurrency]}\n          style={{ display: 'flex' }}\n        />\n      </span>\n    );\n  },\n  { shouldForwardProp },\n)(\n  () =>\n    ({\n      backgroundColor: 'white',\n      borderRadius: 12,\n      border: '1px solid',\n      lineHeight: '24px',\n      display: 'flex',\n      width: 32,\n      height: 32,\n      position: 'relative',\n      alignItems: 'center',\n      justifyContent: 'center',\n      transitionProperty: 'left',\n      transitionTimingFunction,\n      transitionDuration,\n    } as CSSObject),\n);\n\nconst StyledTrack = styled.div(({ theme }) => ({\n  backgroundColor: theme.glo.color.foundations[20],\n  borderRadius: 12,\n  display: 'flex',\n  justifyContent: 'space-between',\n  alignItems: 'center',\n  width: '100%',\n  height: '100%',\n  position: 'absolute',\n  transitionProperty: 'background-color',\n  transitionTimingFunction,\n  transitionDuration,\n}));\n\nconst HalfTrack = ({ children }: PropsWithChildren) => (\n  <Box display=\"flex\" justifyContent=\"center\" width=\"50%\">\n    {children}\n  </Box>\n);\n\nexport const Track = () => {\n  const { watch } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const watchCurrency = watch('currency');\n\n  return (\n    <StyledTrack id=\"track-div\">\n      <HalfTrack>%</HalfTrack>\n      <HalfTrack>\n        <Icon\n          size=\"small\"\n          icon={currencyIcons[watchCurrency]}\n          style={{ display: 'flex' }}\n        />\n      </HalfTrack>\n    </StyledTrack>\n  );\n};\n\nexport const Root = styled.span(({ theme }) => ({\n  width: 64,\n  height: 32,\n  cursor: 'pointer',\n  position: 'relative',\n  flexShrink: 0,\n\n  '&.base--checked': {\n    '.base-Switch-thumb': {\n      left: 33,\n    },\n\n    '.base-Switch-track': {\n      backgroundColor: theme.glo.color.foundations[20],\n    },\n  },\n\n  '&.base--focusVisible': {\n    '.base-Switch-thumb': {\n      outline: '1px solid white',\n    },\n  },\n}));\n","import { Switch } from '@mui/base/Switch';\nimport { ChangeEvent } from 'react';\n\nimport { Input, Root, Thumb, Track } from './FeesTypeSwitch.styled';\n\ntype FeesTypeSwitchProps = {\n  feeInputType: 'PERCENTAGE' | 'AMOUNT';\n  toggleFeeInputType: (e: ChangeEvent<HTMLInputElement>) => void;\n};\n\nexport const FeesTypeSwitch = ({\n  feeInputType,\n  toggleFeeInputType,\n}: FeesTypeSwitchProps) => (\n  <Switch\n    checked={feeInputType === 'AMOUNT'}\n    onChange={toggleFeeInputType}\n    data-test-id=\"fee-type-toggle\"\n    slots={{\n      root: Root,\n      track: Track,\n      thumb: Thumb,\n      input: Input,\n    }}\n    slotProps={{\n      input: { role: 'switch' },\n      thumb: {\n        content: feeInputType,\n      },\n    }}\n  />\n);\n","/* eslint-disable @typescript-eslint/no-explicit-any */\nimport { TWO_DECIMAL_REGEX } from '@finmid/tbl-webapps/utils';\nimport { useMemo } from 'react';\nimport { useFormContext } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\nimport * as yup from 'yup';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../../../../../CreatePaymentRequestOnePage.types';\n\nexport const useValidationSchema = () => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'validation',\n  });\n  const { watch } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const watchAmount = watch('amount');\n\n  const percentageSchema = useMemo(\n    () =>\n      yup\n        .string()\n        .test('can not be empty', 'Must provide a value', (value) => {\n          return value !== '' && value !== undefined;\n        })\n        .test(\n          'smaller-than-total',\n          t('sellerFeeLowerThanTotalAmount'),\n          (value) => {\n            if (value !== undefined && value !== '') {\n              return parseFloat(value) < 100;\n            }\n            return true;\n          },\n        )\n        .test('positive-number', t('pricePositive'), (value) => {\n          if (value !== undefined && value !== '') {\n            return parseFloat(value) > 0;\n          }\n          return true;\n        })\n        .test('max-two-decimal', t('maxTwoDigits'), (value) => {\n          if (value !== undefined && value !== '') {\n            return TWO_DECIMAL_REGEX.test(value);\n          }\n          return true;\n        }),\n    [t],\n  );\n\n  const amountSchema = useMemo(\n    () =>\n      yup\n        .string()\n        .test('can not be empty', 'Must provide a value', (value) => {\n          return value !== '' && value !== undefined;\n        })\n        .test(\n          'smaller-than-total',\n          t('sellerFeeLowerThanTotalAmount'),\n          (value) => {\n            if (value !== undefined && value !== '') {\n              return parseFloat(value) < parseFloat(watchAmount);\n            }\n            return true;\n          },\n        )\n        .test('max-two-decimal', t('maxTwoDigits'), (value) => {\n          if (value !== undefined && value !== '') {\n            return TWO_DECIMAL_REGEX.test(value);\n          }\n          return true;\n        })\n        .test('positive-number', t('pricePositive'), (value) => {\n          if (value !== undefined && value !== '') {\n            return parseFloat(value) > 0;\n          }\n          return true;\n        }),\n    [t, watchAmount],\n  );\n\n  return {\n    amountSchema,\n    percentageSchema,\n  };\n};\n\nexport type ValidationErrors = Partial<{\n  fixed: string;\n  percentage: string;\n}>;\n\nexport const getValidationErrors = (errors: any) => {\n  const validationErrors = {};\n  errors.inner.forEach((error: any) => {\n    if (error.path) {\n      (validationErrors as any)[error.path] = error.message;\n    }\n  });\n  return validationErrors;\n};\n","import { CalculateFeeOverride } from '@finmid/distributor-types';\nimport { useCalculateFeeOverrideMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport currencyjs from 'currency.js';\nimport {\n  ChangeEvent,\n  Dispatch,\n  KeyboardEvent,\n  SetStateAction,\n  useState,\n} from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport { formatNumberWithDecimals } from '../../../../../../../../../../../../shared';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../../../../../CreatePaymentRequestOnePage.types';\nimport { getOptionDetails } from '../../../../../utils';\n\nimport { useValidationSchema } from './OverrideFeesPopper.schema';\n\nfunction isCalculatePercentageSuccess(\n  response: CalculateFeeOverride.ApiResponse,\n): response is CalculateFeeOverride.SuccessResponse {\n  return 'overridePercentage' in response;\n}\n\ntype UseOverrideFeesPopperProps = {\n  defaultFees: number;\n  setOpen: Dispatch<SetStateAction<boolean>>;\n};\n\nexport const useOverrideFeesPopper = ({\n  defaultFees,\n  setOpen,\n}: UseOverrideFeesPopperProps) => {\n  const { notifyError } = useNotifications();\n  const { getValues, setValue } =\n    useFormContext<CreatePaymentRequestOnePageFormType>();\n  const validation = useValidationSchema();\n\n  const [feeInputType, setFeeInputType] = useState<'PERCENTAGE' | 'AMOUNT'>(\n    'PERCENTAGE',\n  );\n  const [feeOverrideInput, setFeeOverrideInput] = useState<string | undefined>(\n    formatNumberWithDecimals(defaultFees),\n  );\n  const [feeOverrideValid, setFeeOverrideValid] = useState(false);\n\n  const [getFeeOverrideAsPercentage] = useCalculateFeeOverrideMutation();\n\n  const toggleFeeInputType = (e: ChangeEvent<HTMLInputElement>) => {\n    if (e.target.checked) {\n      setFeeInputType('AMOUNT');\n    } else {\n      setFeeInputType('PERCENTAGE');\n    }\n  };\n\n  const handleKeyDown = (\n    e: KeyboardEvent<HTMLInputElement>,\n    optionValue: string,\n  ) => {\n    if (e.key === 'Enter') {\n      void saveOverrideFees(optionValue);\n    }\n  };\n\n  const handleOverrideFeeChange = (e: ChangeEvent<HTMLInputElement>) => {\n    const validationSchema =\n      feeInputType === 'PERCENTAGE'\n        ? validation.percentageSchema\n        : validation.amountSchema;\n\n    const inputValidation = validationSchema.cast(e.target.value);\n    try {\n      let inputValue = e.target.value;\n      if (isNaN(parseFloat(inputValue))) {\n        inputValue = '';\n      }\n      setFeeOverrideInput(inputValue);\n      setFeeOverrideValid(true);\n      validationSchema.validateSync(inputValidation);\n    } catch {\n      setFeeOverrideValid(false);\n    }\n  };\n\n  const saveOverrideFees = async (optionValue: string) => {\n    try {\n      const [period] = getOptionDetails(optionValue);\n\n      if (feeOverrideInput != null) {\n        const feeOverrideAsPercentage = await getFeeOverrideAsPercentage({\n          intentTotalAmount: currencyjs(getValues('amount')).value,\n          calculationType: feeInputType,\n          overrideAmount: feeOverrideInput,\n        }).unwrap();\n        if (isCalculatePercentageSuccess(feeOverrideAsPercentage)) {\n          setValue('feeOverridePercentagePerTerm', {\n            ...getValues('feeOverridePercentagePerTerm'),\n            [period]: feeOverrideAsPercentage,\n          });\n        } else {\n          notifyError(feeOverrideAsPercentage.error);\n        }\n      }\n\n      setOpen(false);\n    } catch {\n      //\n    }\n  };\n\n  return {\n    canSubmit: feeOverrideValid,\n    feeInputType,\n    feeOverride: feeOverrideInput,\n    handleKeyDown,\n    handleOverrideFeeChange,\n    saveOverrideFees,\n    toggleFeeInputType,\n  };\n};\n","import { Button, Typography } from '@finmid/tbl-webapps/components';\nimport { currencySymbols } from '@finmid/tbl-webapps/utils';\nimport {\n  CloseXIcon,\n  ElevatedPaper,\n  IconButton,\n  Popper,\n  Spacer,\n  TextInput,\n} from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport Fade from '@mui/material/Fade';\nimport { Dispatch, SetStateAction } from 'react';\nimport { useFormContext } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../../../../../CreatePaymentRequestOnePage.types';\n\nimport { FeesTypeSwitch } from './FeesTypeSwitch';\nimport { useOverrideFeesPopper } from './OverrideFeesPopper.hook';\n\ntype OverrideFeesProps = {\n  anchorEl?: HTMLElement | null;\n  defaultFees: number;\n  open: boolean;\n  repaymentMethod: string;\n  setOpen: Dispatch<SetStateAction<boolean>>;\n};\n\nexport const OverrideFeesPopper = ({\n  anchorEl,\n  defaultFees,\n  open,\n  repaymentMethod,\n  setOpen,\n}: OverrideFeesProps) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice.overrideFees',\n  });\n  const canBeOpened = open && anchorEl != null;\n  const id = canBeOpened ? 'transition-popper' : undefined;\n\n  const { watch } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const watchCurrency = watch('currency');\n\n  const {\n    canSubmit,\n    feeInputType,\n    feeOverride,\n    handleKeyDown,\n    handleOverrideFeeChange,\n    saveOverrideFees,\n    toggleFeeInputType,\n  } = useOverrideFeesPopper({\n    defaultFees,\n    setOpen,\n  });\n\n  if (anchorEl == null) {\n    return null;\n  }\n\n  return (\n    <Popper\n      id={id}\n      open={open}\n      anchorEl={anchorEl}\n      placement=\"right-start\"\n      transition\n    >\n      {({ TransitionProps }) => (\n        <Fade {...TransitionProps} timeout={350}>\n          <ElevatedPaper\n            id=\"elevated-paper\"\n            css={{\n              padding: 0,\n              overflow: 'hidden',\n              marginLeft: 8,\n            }}\n            data-test-id=\"override-fees-popper\"\n          >\n            <Box\n              height={40}\n              display=\"flex\"\n              justifyContent=\"space-between\"\n              alignItems=\"center\"\n              borderBottom=\"1px solid\"\n              borderColor=\"gray.100\"\n              id=\"popper-title\"\n              px={2}\n            >\n              <Typography fontSize={15} lineHeight=\"16px\">\n                {t('title')}\n              </Typography>\n              <Box display=\"flex\" alignItems=\"center\" gap={1}>\n                <Button\n                  variant=\"primary\"\n                  size=\"s\"\n                  disabled={!canSubmit}\n                  onClick={() => saveOverrideFees(repaymentMethod)}\n                  testId=\"save-override-fees\"\n                >\n                  {t('saveButton')}\n                </Button>\n                <IconButton\n                  variant=\"invisible\"\n                  size=\"s\"\n                  icon={<CloseXIcon />}\n                  onClick={() => {\n                    setOpen(false);\n                  }}\n                />\n              </Box>\n            </Box>\n\n            <Box bgcolor=\"gray.50\" id=\"bottom-box\" p={2}>\n              <Typography color=\"gray.600\" fontSize={13} lineHeight=\"16px\">\n                {feeInputType === 'PERCENTAGE'\n                  ? t('percentage.label')\n                  : t('amount.label')}\n              </Typography>\n              <Spacer height={1} />\n              <Box display=\"flex\" justifyContent=\"space-between\" gap={1}>\n                <FeesTypeSwitch\n                  feeInputType={feeInputType}\n                  toggleFeeInputType={toggleFeeInputType}\n                />\n                <TextInput\n                  startAdornment={\n                    feeInputType === 'AMOUNT'\n                      ? currencySymbols[watchCurrency]\n                      : undefined\n                  }\n                  endAdornment={feeInputType === 'PERCENTAGE' ? '%' : undefined}\n                  style={{ flexGrow: 1 }}\n                  value={feeOverride}\n                  onChange={handleOverrideFeeChange}\n                  onKeyDown={(e) => handleKeyDown(e, repaymentMethod)}\n                  testId=\"custom-fee-input\"\n                />\n              </Box>\n            </Box>\n          </ElevatedPaper>\n        </Fade>\n      )}\n    </Popper>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { EditIconOutlined } from '@finmid/ui/icons';\nimport { Button, Icon } from '@finmid/ui/ocarina';\nimport ClickAwayListener from '@mui/material/ClickAwayListener';\nimport Collapse from '@mui/material/Collapse';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport { formatNumberWithDecimals } from '../../../../../../../../../../../../shared';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../../../../../CreatePaymentRequestOnePage.types';\nimport { OverrideFeesPopper } from '../OverrideFeesPopper';\n\ntype DefaultFeesButtonProps = {\n  selected: boolean;\n  defaultFees: number;\n  anchor: HTMLElement | null;\n  repaymentMethod: string;\n};\n\nexport const DefaultFeesButton = ({\n  selected,\n  defaultFees,\n  anchor,\n  repaymentMethod,\n}: DefaultFeesButtonProps) => {\n  const feeText = defaultFees\n    ? `${formatNumberWithDecimals(defaultFees)}%`\n    : '-';\n  const { com } = useTheme();\n\n  const [openOverrideFeesPopper, setOpenOverrideFeesPopper] = useState(false);\n  const { watch } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const watchAmount = watch('amount');\n  const canOpenPopper = watchAmount !== '';\n\n  return (\n    <>\n      <Typography\n        // we use display instead of conditional rendering to\n        // allow the smooth collapse transition of the edit icon\n        display={!selected ? 'block' : 'none'}\n        fontSize={com.button.m.typo.fontSize}\n        fontWeight={com.button.m.typo.fontWeight}\n        lineHeight={com.button.m.typo.lineHeight}\n        py={com.button.m.padding.button.top}\n        px={com.button.m.padding.button.right}\n        numeric\n        gridArea=\"fee\"\n        color={!canOpenPopper ? 'gray.500' : 'gray.900'}\n      >\n        {feeText}\n      </Typography>\n\n      <ClickAwayListener\n        onClickAway={() => {\n          setOpenOverrideFeesPopper(false);\n        }}\n      >\n        <div>\n          <Button\n            variant=\"invisible\"\n            onClick={() => {\n              setOpenOverrideFeesPopper(true);\n              posthog.capture('clicked_open_override_fees');\n            }}\n            disabled={!selected || !canOpenPopper}\n            css={{\n              display: selected ? 'flex' : 'none',\n              fontVariantNumeric: 'lining-nums tabular-nums',\n              fontFeatureSettings: \"'ss02' on, 'ss01' on\",\n              gridArea: 'fee',\n            }}\n            data-test-id=\"override-fees-button\"\n            style={{\n              paddingInline: 4,\n              gap: 4,\n            }}\n          >\n            {feeText}\n            {canOpenPopper && (\n              <Collapse in={selected} orientation=\"horizontal\" timeout={300}>\n                <Icon size=\"small\" icon={<EditIconOutlined id=\"edit-icon\" />} />\n              </Collapse>\n            )}\n          </Button>\n          {openOverrideFeesPopper ? (\n            <OverrideFeesPopper\n              anchorEl={anchor}\n              defaultFees={defaultFees}\n              open\n              repaymentMethod={repaymentMethod}\n              setOpen={setOpenOverrideFeesPopper}\n            />\n          ) : null}\n        </div>\n      </ClickAwayListener>\n    </>\n  );\n};\n","import { Button, CloseXIcon } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { useFormContext } from 'react-hook-form';\n\nimport { formatNumberWithDecimals } from '../../../../../../../../../../../../shared';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../../../../../CreatePaymentRequestOnePage.types';\nimport { getOptionDetails } from '../../../../../utils';\n\ntype OverridenFeesButtonProps = {\n  feeOverride?: number;\n  repaymentMethod: string;\n};\n\nexport const OverridenFeesButton = ({\n  feeOverride,\n  repaymentMethod,\n}: OverridenFeesButtonProps) => {\n  const [repaymentTerm] = getOptionDetails(repaymentMethod);\n  const { getValues, setValue } =\n    useFormContext<CreatePaymentRequestOnePageFormType>();\n\n  const removeOverrideFees = async () => {\n    setValue('feeOverridePercentagePerTerm', {\n      ...getValues('feeOverridePercentagePerTerm'),\n      [repaymentTerm]: null,\n    });\n  };\n\n  return (\n    <Box\n      display=\"flex\"\n      justifyContent=\"flex-end\"\n      alignItems=\"center\"\n      gap={2}\n      gridArea=\"fee\"\n    >\n      <Button\n        suffixIcon={<CloseXIcon id=\"close-icon\" style={{ width: 16 }} />}\n        variant=\"accent\"\n        onClick={removeOverrideFees}\n        css={{\n          fontVariantNumeric: 'lining-nums tabular-nums',\n          fontFeatureSettings: \"'ss02' on, 'ss01' on\",\n        }}\n        data-test-id=\"reset-fees-button\"\n        style={{\n          paddingInline: 4,\n          gap: 4,\n        }}\n      >\n        {`${formatNumberWithDecimals(feeOverride)}%`}\n      </Button>\n    </Box>\n  );\n};\n","import { useFormContext } from 'react-hook-form';\n\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../../../../../CreatePaymentRequestOnePage.types';\nimport { getOptionDetails } from '../../../../../utils';\n\nimport { DefaultFeesButton } from './DefaultFeesButton';\nimport { OverridenFeesButton } from './OverridenFeesButton';\n\ntype FeesButtonProps = {\n  defaultFees: number;\n  anchor: HTMLLabelElement | null;\n  selected: boolean;\n  repaymentMethod: string;\n};\n\nexport const DisplayedFeesButton = ({\n  anchor,\n  defaultFees,\n  selected,\n  repaymentMethod,\n}: FeesButtonProps) => {\n  const [repaymentTerm] = getOptionDetails(repaymentMethod);\n\n  const { getValues } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const totalFeeOverridePercentage = getValues('feeOverridePercentagePerTerm');\n  const feeIsOverridenForTerm = totalFeeOverridePercentage?.[repaymentTerm];\n\n  const overrideIsSameAsDefault =\n    defaultFees ===\n    totalFeeOverridePercentage?.[repaymentTerm]?.overridePercentage;\n\n  if (\n    !overrideIsSameAsDefault &&\n    feeIsOverridenForTerm &&\n    totalFeeOverridePercentage?.[repaymentTerm]\n  ) {\n    return (\n      <OverridenFeesButton\n        feeOverride={\n          totalFeeOverridePercentage[repaymentTerm].overrideHumanPercentage\n        }\n        repaymentMethod={repaymentMethod}\n      />\n    );\n  }\n\n  return (\n    <DefaultFeesButton\n      selected={selected}\n      defaultFees={defaultFees}\n      anchor={anchor}\n      repaymentMethod={repaymentMethod}\n    />\n  );\n};\n","import { Typography } from '@finmid/tbl-webapps/components';\nimport Collapse from '@mui/material/Collapse';\nimport { useEffect, useRef, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { BottomLabel, ButtonWrapper, RadioInput } from './RadioButton.styled';\nimport { DisplayedFeesButton } from './components';\n\ninterface RadioButtonProps {\n  defaultFees: number;\n  disabled: boolean;\n  selected: boolean;\n  repaymentMethod: string;\n  period: number;\n  bottomLabel?: string;\n  testId?: string;\n  onChange: (repaymentMethod: string) => void;\n  style: React.CSSProperties;\n}\n\nexport const RadioButton = ({\n  defaultFees,\n  selected,\n  period,\n  repaymentMethod,\n  disabled,\n  testId,\n  onChange,\n  bottomLabel,\n  style,\n}: RadioButtonProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const buttonWrapperRef = useRef<HTMLLabelElement | null>(null);\n  const [, setAnchor] = useState(false);\n\n  const selectOption = (repaymentMethod: string) => {\n    onChange(repaymentMethod);\n  };\n\n  useEffect(() => {\n    setAnchor(true);\n  }, []);\n\n  return (\n    <div>\n      <ButtonWrapper\n        ref={buttonWrapperRef}\n        key={repaymentMethod}\n        disabled={disabled}\n        selected={selected}\n        data-test-id={testId}\n        data-term={period}\n        style={style}\n      >\n        <RadioInput\n          type=\"radio\"\n          value={repaymentMethod}\n          onChange={() => selectOption(repaymentMethod)}\n          disabled={disabled}\n          checked={selected}\n          css={{ gridArea: 'radio', alignSelf: 'center' }}\n        />\n\n        <Typography fontSize={15} lineHeight=\"20px\" numeric gridArea=\"term\">\n          {t('repaymentTermDays.label', { repaymentTermDays: period })}\n        </Typography>\n\n        <DisplayedFeesButton\n          anchor={buttonWrapperRef.current}\n          defaultFees={defaultFees}\n          selected={selected}\n          repaymentMethod={repaymentMethod}\n        />\n      </ButtonWrapper>\n\n      {bottomLabel ? (\n        <Collapse in={selected} timeout={300} sx={{ marginTop: '-11px' }}>\n          <BottomLabel>\n            <Typography\n              color=\"white\"\n              fontSize={12}\n              fontWeight={500}\n              lineHeight=\"16px\"\n            >\n              {bottomLabel}\n            </Typography>\n          </BottomLabel>\n        </Collapse>\n      ) : null}\n    </div>\n  );\n};\n","import { CheckPaymentRequest } from '@finmid/distributor-types';\nimport { useTranslation } from 'react-i18next';\n\nimport { RadioButton } from './RadioButton';\n\ntype RepaymentTermOptionProps = {\n  repaymentMethod: CheckPaymentRequest.GatewayResponse['repaymentMethods'][number];\n  handleOptionChange: (repaymentMethod: string) => void;\n  isLoading: boolean;\n  selectedOption: string;\n};\n\nexport const RepaymentTermOption = ({\n  repaymentMethod,\n  handleOptionChange,\n  selectedOption,\n  isLoading,\n}: RepaymentTermOptionProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const { period, payoutRatio, amountsBreakdown } = repaymentMethod;\n\n  return (\n    <RadioButton\n      selected={selectedOption === `${period}_${payoutRatio}`}\n      disabled={false}\n      defaultFees={amountsBreakdown.fees.totalFeePercentage}\n      onChange={handleOptionChange}\n      repaymentMethod={`${period}_${payoutRatio}`}\n      period={period}\n      testId=\"repayment-term-option\"\n      style={{ cursor: isLoading ? 'wait' : 'pointer' }}\n      bottomLabel={\n        payoutRatio !== 100\n          ? t('financingPortion.label', {\n              financingPortion: payoutRatio,\n            })\n          : undefined\n      }\n    />\n  );\n};\n","import { useFormContext } from 'react-hook-form';\n\nimport { getMaxInvoiceDueDate } from '../../../../../../../../PaymentRequests.utils';\nimport { useCheckPaymentRequestContext } from '../../../../../../../CheckPaymentRequest.context';\nimport { useCreatePaymentRequestFormPayload } from '../../../../../../../CreatePaymentRequestForm.context';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../../CreatePaymentRequestOnePage.types';\nimport { validateDate } from '../../../../../../../utils';\nimport { getOptionDetails } from '../utils';\n\nconst checkIfDateMustBeUpdated = ({\n  currentInvoiceDueDate,\n  maxDueDateForSelectedRepaymentTerm,\n  previousPeriod,\n  period,\n  minInvoiceDueDate,\n  allowPayoutWithoutDueDate,\n}: {\n  currentInvoiceDueDate?: Date | null;\n  maxDueDateForSelectedRepaymentTerm: Date;\n  previousPeriod: number | null;\n  period: number;\n  minInvoiceDueDate: Date;\n  maxInvoiceDueDate: Date;\n  allowPayoutWithoutDueDate: boolean;\n}) => {\n  if (currentInvoiceDueDate == null && allowPayoutWithoutDueDate) {\n    return false;\n  }\n\n  if (currentInvoiceDueDate == null || !validateDate(currentInvoiceDueDate)) {\n    return true;\n  }\n\n  const currentDateIsAfterMaxDate =\n    currentInvoiceDueDate > maxDueDateForSelectedRepaymentTerm;\n  const currentDateIsBeforeMaxDate =\n    currentInvoiceDueDate < maxDueDateForSelectedRepaymentTerm;\n  const currentDateIsBeforeMinDate = currentInvoiceDueDate < minInvoiceDueDate;\n\n  if (currentDateIsAfterMaxDate) return true;\n  if (\n    currentDateIsBeforeMaxDate &&\n    previousPeriod != null &&\n    previousPeriod < period\n  ) {\n    return true;\n  }\n\n  if (currentDateIsBeforeMinDate) {\n    return true;\n  }\n\n  return false;\n};\n\ntype UseHandleSelectRepaymentTermOptionProps = {\n  previousPeriod: number | null;\n};\n\nexport const useHandleSelectRepaymentTermOption = ({\n  previousPeriod,\n}: UseHandleSelectRepaymentTermOptionProps) => {\n  const { maxInvoiceDueDate, minInvoiceDueDate } =\n    useCreatePaymentRequestFormPayload();\n  const { getValues, setValue } =\n    useFormContext<CreatePaymentRequestOnePageFormType>();\n  const { allowPayoutWithoutDueDate } = useCheckPaymentRequestContext();\n\n  const handleSelectOption = (value: string) => {\n    const [period, payoutRatio] = getOptionDetails(value);\n\n    const maxDueDateForSelectedRepaymentTerm = getMaxInvoiceDueDate(period);\n    const currentInvoiceDueDate = getValues('invoiceDueDate');\n\n    const mustUpdateInvoiceDueDate = checkIfDateMustBeUpdated({\n      currentInvoiceDueDate,\n      maxDueDateForSelectedRepaymentTerm,\n      previousPeriod,\n      period,\n      minInvoiceDueDate,\n      maxInvoiceDueDate,\n      allowPayoutWithoutDueDate,\n    });\n\n    if (mustUpdateInvoiceDueDate) {\n      setValue('invoiceDueDate', maxDueDateForSelectedRepaymentTerm, {\n        shouldValidate: true,\n      });\n    }\n\n    setValue(\n      'repaymentOption',\n      { period, payoutRatio },\n      { shouldValidate: true, shouldTouch: true },\n    );\n  };\n\n  return handleSelectOption;\n};\n","import { displayPercentage } from '@finmid/tbl-webapps/utils';\nimport { Spacer, TextInputLabel } from '@finmid/ui/ocarina';\nimport { Box, FormControl } from '@mui/material';\nimport { memo } from 'react';\nimport { useFormContext } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { useCheckPaymentRequestContext } from '../../../../../../CheckPaymentRequest.context';\nimport { useCreatePaymentRequestFormPayload } from '../../../../../../CreatePaymentRequestForm.context';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../../CreatePaymentRequestOnePage.types';\nimport { getShortestRepaymentMethod } from '../../../../../../utils';\nimport { useRecourseContext } from '../../../../../CreatePaymentRequestPageRecourseModal/components/RecourseModal.context';\nimport { RecourseInfo } from '../../../../../RecourseInfo';\n\nimport { RepaymentTermOption } from './components';\nimport { useHandleSelectRepaymentTermOption } from './hooks';\n\nconst RepaymentTermAndFeesComp = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const { repaymentMethods, selectedTerm } = useCheckPaymentRequestContext();\n  const previousPeriod = selectedTerm?.period ?? null;\n\n  const { isLoading } = useCreatePaymentRequestFormPayload();\n\n  const { watch } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const repaymentOption = watch('repaymentOption');\n\n  const customRecourseFee =\n    selectedTerm?.amountsBreakdown.financingAmountSplit.recourseFeePercentage;\n  const minRepaymentTerm = getShortestRepaymentMethod(repaymentMethods);\n  const minTermRecourseFee =\n    minRepaymentTerm?.amountsBreakdown.financingAmountSplit\n      .recourseFeePercentage;\n  const minTermRecourseFeeLabel = t('recourseWarningWithMinFee', {\n    minFee: displayPercentage(minTermRecourseFee),\n  });\n  const customRecourseFeeLabel = t('recourseWarningWithFee', {\n    recourseFee: displayPercentage(customRecourseFee),\n  });\n  const recourseFeeLabel = customRecourseFee\n    ? customRecourseFeeLabel\n    : minTermRecourseFeeLabel;\n  const { isRecourse } = useRecourseContext();\n\n  const handleSelectOption = useHandleSelectRepaymentTermOption({\n    previousPeriod,\n  });\n\n  if (repaymentMethods == null) {\n    return null;\n  }\n\n  return (\n    <Box data-test-id=\"repayment-methods\">\n      <TextInputLabel>{t('repaymentTermsAndFees')}</TextInputLabel>\n      {isRecourse && (\n        <>\n          <RecourseInfo infoText={recourseFeeLabel} />\n          <Spacer height={2} />\n        </>\n      )}\n      <FormControl\n        sx={{\n          mb: 2,\n          width: '100%',\n          display: 'grid',\n          gridTemplateColumns: '1fr 1fr 1fr',\n          gap: 2,\n        }}\n      >\n        {repaymentMethods.map((repaymentMethod, index) => {\n          return (\n            <RepaymentTermOption\n              key={index}\n              selectedOption={`${repaymentOption?.period}_${repaymentOption?.payoutRatio}`}\n              repaymentMethod={repaymentMethod}\n              handleOptionChange={handleSelectOption}\n              isLoading={isLoading}\n            />\n          );\n        })}\n      </FormControl>\n    </Box>\n  );\n};\n\nexport const RepaymentTermAndFees = memo(RepaymentTermAndFeesComp);\n","import {\n  SectionContainer,\n  SectionContent,\n  SectionHeader,\n} from '@finmid/tbl-webapps/components';\nimport { Box } from '@mui/material';\n\nimport { useCreatePaymentRequestFormLabels } from '../../../../hooks';\n\nimport {\n  InstantPayout,\n  InvoiceDueDate,\n  InvoiceId,\n  RepaymentTermAndFees,\n} from './components';\n\nexport const FormPaymentDetails = () => {\n  const { sections } = useCreatePaymentRequestFormLabels();\n\n  return (\n    <SectionContainer>\n      <SectionHeader>{sections.paymentDetails}</SectionHeader>\n      <SectionContent style={{ gap: 24 }}>\n        <InstantPayout />\n        <Box display=\"grid\" gridTemplateColumns=\"1fr 1fr\" gap={2}>\n          <InvoiceId />\n          <InvoiceDueDate />\n        </Box>\n        <RepaymentTermAndFees />\n      </SectionContent>\n    </SectionContainer>\n  );\n};\n","import { Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\n\nimport { FormAmountAndParties, FormPaymentDetails } from './components';\n\nexport const CreatePaymentRequestOnePageForm = () => (\n  <Box>\n    <FormAmountAndParties />\n    <Spacer height={2} />\n    <FormPaymentDetails />\n  </Box>\n);\n","import { useTheme } from '@emotion/react';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { Icon } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { PropsWithChildren } from 'react';\n\ntype DetailsWrapperProps = PropsWithChildren<{\n  title: string;\n  IconFlag?: React.ReactElement;\n  testId?: string;\n}>;\n\nexport const DetailsWrapper = ({\n  children,\n  title,\n  IconFlag,\n  testId,\n}: DetailsWrapperProps) => {\n  const theme = useTheme();\n\n  return (\n    <Box\n      borderRadius={3}\n      overflow=\"hidden\"\n      data-test-id={testId}\n      border={`1px solid ${theme.glo.color.foundations[20]}`}\n    >\n      <Box\n        borderBottom={`1px solid ${theme.glo.color.foundations[20]}`}\n        bgcolor={theme.glo.color.foundations[10]}\n        display=\"flex\"\n        justifyContent=\"space-between\"\n        alignItems=\"center\"\n        py={1}\n        px={2}\n      >\n        <Box\n          width=\"100%\"\n          display=\"flex\"\n          alignItems=\"center\"\n          justifyContent=\"space-between\"\n          gap={1}\n          height={32}\n          py={0.5}\n        >\n          <Typography\n            fontWeight={500}\n            fontSize={13}\n            lineHeight=\"16px\"\n            color={theme.glo.color.foundations[60]}\n          >\n            {title}\n          </Typography>\n          {IconFlag != null ? (\n            <Icon icon={IconFlag} style={{ width: '22px', height: '22px' }} />\n          ) : null}\n        </Box>\n      </Box>\n      {children}\n    </Box>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { PropsWithChildren } from 'react';\n\ntype DetailsRowLabelProps = PropsWithChildren<{\n  label: string;\n}>;\n\nexport const DetailsRowLabel = ({ children, label }: DetailsRowLabelProps) => {\n  const theme = useTheme();\n  return (\n    <Typography\n      fontWeight={500}\n      fontSize={13}\n      lineHeight=\"16px\"\n      color={theme.glo.color.foundations[60]}\n    >\n      {label}\n      {children}\n    </Typography>\n  );\n};\n","import { Box } from '@mui/material';\nimport { CSSProperties, PropsWithChildren } from 'react';\n\ntype DetailsRowContainerProps = PropsWithChildren<{\n  style?: CSSProperties;\n}>;\n\nexport const DetailsRowContainer = ({\n  children,\n  style = {},\n}: DetailsRowContainerProps) => (\n  <Box\n    display=\"flex\"\n    alignItems=\"center\"\n    gap={1}\n    justifyContent=\"space-between\"\n    style={style}\n    width=\"100%\"\n  >\n    {children}\n  </Box>\n);\n","import { useTheme } from '@emotion/react';\nimport { Divider, Typography } from '@finmid/tbl-webapps/components';\nimport { Box } from '@mui/material';\nimport { useFormContext } from 'react-hook-form';\n\nimport { DetailsWrapper } from '../../../../components/DetailsWrapper';\nimport { CreatePaymentRequestOnePageFormType } from '../../../CreatePaymentRequestOnePage.types';\nimport { useCreatePaymentRequestFormLabels } from '../../../hooks';\n\nimport { DetailsRowLabel } from './DetailsRow';\nimport { DetailsRowContainer } from './DetailsRowContainer';\n\ntype InvolvedPartyDetailsProps = {\n  entity?: { legalName: string; externalId: string } | null;\n  label: string;\n  testId: string;\n};\n\nconst InvolvedPartyDetails = ({\n  entity,\n  label,\n  testId,\n}: InvolvedPartyDetailsProps) => {\n  const theme = useTheme();\n\n  return (\n    <DetailsRowContainer style={{ padding: '16px' }}>\n      <DetailsRowLabel label={label} />\n      <Box\n        sx={{\n          textAlign: 'end',\n        }}\n        maxWidth=\"240px\"\n      >\n        <Typography fontSize={15}>{entity?.legalName || '-'}</Typography>\n        <Typography\n          fontSize={13}\n          color={theme.glo.color.foundations[60]}\n          style={{\n            textOverflow: 'ellipsis',\n            overflow: 'hidden',\n            textWrap: 'nowrap',\n          }}\n          data-test-id={testId}\n        >\n          {entity?.externalId || '-'}\n        </Typography>\n      </Box>\n    </DetailsRowContainer>\n  );\n};\n\nexport const SidebarInvolvedParties = () => {\n  const { labels, sidebar } = useCreatePaymentRequestFormLabels();\n  const { watch } = useFormContext<CreatePaymentRequestOnePageFormType>();\n\n  const buyer = watch('buyer');\n  const seller = watch('seller');\n\n  return (\n    <DetailsWrapper title={sidebar.amountAndParties} testId=\"involved-parties\">\n      <Box>\n        <InvolvedPartyDetails\n          label={labels.buyer}\n          entity={buyer}\n          testId=\"sidebar-buyer-externalid\"\n        />\n        <Divider />\n        <InvolvedPartyDetails\n          label={labels.seller}\n          entity={seller}\n          testId=\"sidebar-seller-externalid\"\n        />\n      </Box>\n    </DetailsWrapper>\n  );\n};\n","import { Badge } from '@finmid/ui/ocarina';\nimport { useFormContext } from 'react-hook-form';\n\nimport { AccentBadge } from '../../../../../../components';\nimport { formatNumberWithDecimals } from '../../../../../../shared';\nimport { useCheckPaymentRequestContext } from '../../../../../CheckPaymentRequest.context';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../../CreatePaymentRequestOnePage.types';\n\nexport const TotalFeeOverrideBadge = () => {\n  const { getValues } = useFormContext<CreatePaymentRequestOnePageFormType>();\n  const { selectedTerm } = useCheckPaymentRequestContext();\n\n  if (!selectedTerm) {\n    return null;\n  }\n\n  const totalFeeOverridePercentage = getValues(\n    'feeOverridePercentagePerTerm',\n  )?.[selectedTerm?.period];\n  const feeIsOverridenForTerm = totalFeeOverridePercentage != null;\n\n  const { totalFeePercentage } = selectedTerm.amountsBreakdown.fees;\n\n  if (\n    feeIsOverridenForTerm &&\n    totalFeeOverridePercentage != null &&\n    totalFeeOverridePercentage.overrideHumanPercentage > 0\n  ) {\n    return (\n      <AccentBadge\n        label={`${formatNumberWithDecimals(\n          totalFeeOverridePercentage.overrideHumanPercentage,\n        )}%`}\n        testId=\"total-fee-badge\"\n      />\n    );\n  }\n\n  if (totalFeePercentage != null && totalFeePercentage > 0) {\n    return (\n      <Badge\n        variant=\"neutral\"\n        label={`${formatNumberWithDecimals(totalFeePercentage)}%`}\n        data-test-id=\"total-fee-badge\"\n      />\n    );\n  }\n\n  return null;\n};\n","import { useTheme } from '@emotion/react';\nimport { TBLCurrency } from '@finmid/distributor-types';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { useGetDistributorAttributesQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useDisplayAmount } from '@finmid/tbl-webapps/utils';\nimport { IconButton, InfoIcon } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { FeeFormulaDialog } from '../../../../../../components';\nimport { useCheckPaymentRequestContext } from '../../../../../CheckPaymentRequest.context';\nimport { DetailsRowLabel } from '../../DetailsRow';\n\nimport { TotalFeeOverrideBadge } from './TotalFeeOverrideBadge';\n\ntype SidebarFeesBreakdownProps = {\n  currency: TBLCurrency;\n};\n\nexport const SidebarFeesBreakdown = ({\n  currency,\n}: SidebarFeesBreakdownProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const theme = useTheme();\n  const [feeFormulaDialogOpen, setFeeFormulaDialogOpen] = useState(false);\n  const handleOpenFeeFormulaDialog = () => setFeeFormulaDialogOpen(true);\n\n  const { selectedTerm } = useCheckPaymentRequestContext();\n  const displayAmount = useDisplayAmount();\n  const { data } = useGetDistributorAttributesQuery();\n  const isMORDistributor = data?.actAsMOR ?? false;\n\n  const { totalFeeAmount, platformMarkup, serviceFee } =\n    selectedTerm?.amountsBreakdown?.fees ?? {};\n\n  return (\n    <>\n      <Box bgcolor=\"#FFF\" py={2}>\n        <Box\n          display=\"flex\"\n          justifyContent=\"space-between\"\n          alignItems=\"center\"\n          py={0.5}\n          px={2}\n        >\n          <Box display=\"flex\" alignItems=\"center\" gap={1}>\n            <DetailsRowLabel label={t('totalFee.label')} />\n            <TotalFeeOverrideBadge />\n          </Box>\n          <Typography\n            fontWeight={400}\n            fontSize={15}\n            lineHeight=\"20px\"\n            color=\"gray.900\"\n            sx={{\n              fontVariantNumeric: 'lining-nums tabular-nums',\n              fontFeatureSettings: \"'ss02' on, 'ss01' on\",\n            }}\n            data-amount={totalFeeAmount}\n            data-test-id=\"sidebar-total-fees\"\n          >\n            {displayAmount({ amount: totalFeeAmount, currency })}\n          </Typography>\n        </Box>\n\n        {!isMORDistributor && (\n          <Box\n            p={1}\n            mx={2}\n            borderRadius={1}\n            bgcolor={theme.glo.color.foundations[10]}\n            color={theme.glo.color.foundations[60]}\n          >\n            <Box\n              display=\"flex\"\n              gap={1}\n              justifyContent=\"space-between\"\n              alignItems=\"center\"\n            >\n              <Typography>{t('serviceFee.label')}</Typography>\n              <IconButton\n                icon={<InfoIcon />}\n                size=\"s\"\n                variant=\"invisible\"\n                onClick={handleOpenFeeFormulaDialog}\n              />\n\n              <Typography\n                textAlign=\"right\"\n                sx={{ flex: 1 }}\n                numeric\n                data-amount={serviceFee}\n                data-test-id=\"sidebar-service-fee\"\n              >\n                {displayAmount({ amount: serviceFee, currency })}\n              </Typography>\n            </Box>\n            <Box mt={0.5} display=\"flex\" justifyContent=\"space-between\">\n              <Typography>{t('platformMarkup.label')}</Typography>\n              <Typography\n                numeric\n                data-test-id=\"sidebar-platform-markup\"\n                data-amount={platformMarkup}\n              >\n                {displayAmount({ amount: platformMarkup, currency })}\n              </Typography>\n            </Box>\n          </Box>\n        )}\n      </Box>\n      <FeeFormulaDialog\n        open={feeFormulaDialogOpen}\n        onClose={() => setFeeFormulaDialogOpen(false)}\n      />\n    </>\n  );\n};\n","import { TBLCurrency } from '@finmid/distributor-types';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { useDisplayAmount } from '@finmid/tbl-webapps/utils';\nimport { Box } from '@mui/material';\nimport { useTranslation } from 'react-i18next';\n\nimport { useCheckPaymentRequestContext } from '../../../../../CheckPaymentRequest.context';\nimport { useRecourseContext } from '../../../../CreatePaymentRequestPageRecourseModal/components/RecourseModal.context';\nimport { RecourseInfo } from '../../../../RecourseInfo';\n\ntype SidebarPayoutAmountProps = {\n  currency: TBLCurrency;\n};\n\nexport const SidebarPayoutAmount = ({ currency }: SidebarPayoutAmountProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const { selectedTerm } = useCheckPaymentRequestContext();\n\n  const displayAmount = useDisplayAmount();\n  const { isRecourse } = useRecourseContext();\n\n  const netFinancingAmount = selectedTerm?.amountsBreakdown.netFinancingAmount;\n\n  return (\n    <Box\n      bgcolor=\"#FFF\"\n      display=\"flex\"\n      gap={1}\n      px={2}\n      py={1.5}\n      justifyContent=\"space-between\"\n      flexWrap=\"wrap\"\n    >\n      <Typography fontWeight={700} fontSize={15} lineHeight=\"20px\">\n        {t('payoutAmount.label')}\n      </Typography>\n      <Typography\n        fontWeight={700}\n        fontSize={15}\n        lineHeight=\"20px\"\n        sx={{ flex: 1 }}\n        textAlign=\"right\"\n        numeric\n        data-amount={netFinancingAmount}\n        data-test-id=\"sidebar-payout-amount\"\n      >\n        {displayAmount({ amount: netFinancingAmount, currency })}\n      </Typography>\n      {isRecourse && <RecourseInfo infoText={t('recourseWarning')} />}\n    </Box>\n  );\n};\n","import { TBLCurrency } from '@finmid/distributor-types';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { useDisplayAmount } from '@finmid/tbl-webapps/utils';\n\nexport const AmountDisplayTypography = ({\n  currency,\n  value,\n  testId,\n  ...props\n}: {\n  currency: TBLCurrency;\n  value?: number | string;\n  testId: string;\n}) => {\n  const displayAmount = useDisplayAmount();\n\n  return (\n    <Typography\n      fontWeight={400}\n      fontSize={15}\n      lineHeight=\"20px\"\n      color=\"#101219\"\n      numeric\n      data-test-id={testId}\n      {...props}\n    >\n      {displayAmount({ amount: value, currency })}\n    </Typography>\n  );\n};\n","import { TBLCurrency } from '@finmid/distributor-types';\nimport { Badge } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\n\nimport { DetailsRowLabel } from '../../DetailsRow';\nimport { DetailsRowContainer } from '../../DetailsRowContainer';\n\nimport { AmountDisplayTypography } from './AmountDisplayTypography';\n\nexport const PartialAmountLabel = ({\n  payoutRatio,\n  grossFinancingAmount,\n  currency,\n}: {\n  payoutRatio: number;\n  grossFinancingAmount?: number;\n  currency: TBLCurrency;\n}) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n\n  return (\n    <DetailsRowContainer>\n      <Box display=\"flex\" alignItems=\"center\" gap={1}>\n        <DetailsRowLabel label={t('grossFinancingAmount')} />\n        <Badge variant=\"neutral\" label={`${payoutRatio}%`} />\n      </Box>\n\n      <AmountDisplayTypography\n        currency={currency}\n        value={grossFinancingAmount}\n        data-amount={grossFinancingAmount}\n        testId=\"sidebar-gross-financing\"\n      />\n    </DetailsRowContainer>\n  );\n};\n","import { useTranslation } from 'react-i18next';\n\nimport { useCheckPaymentRequestContext } from '../../../../../CheckPaymentRequest.context';\nimport { DetailsRowLabel } from '../../DetailsRow';\nimport { DetailsRowContainer } from '../../DetailsRowContainer';\n\nimport { AmountDisplayTypography } from './AmountDisplayTypography';\n\nexport const TotalAmountLabel = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const { repaymentMethods, currency } = useCheckPaymentRequestContext();\n\n  return (\n    <DetailsRowContainer>\n      <DetailsRowLabel label={t('totalAmount.label')} />\n      <AmountDisplayTypography\n        value={repaymentMethods?.[0]?.amount}\n        currency={currency}\n        data-amount={repaymentMethods?.[0]?.amount}\n        testId=\"sidebar-total-amount\"\n      />\n    </DetailsRowContainer>\n  );\n};\n","import { TBLCurrency } from '@finmid/distributor-types';\nimport { ChevronDownIcon, Icon } from '@finmid/ui/ocarina';\nimport ExpandMoreIcon from '@mui/icons-material/ExpandMore';\nimport { AccordionDetails, AccordionSummary, Box } from '@mui/material';\nimport Accordion from '@mui/material/Accordion';\n\nimport { useCheckPaymentRequestContext } from '../../../../../CheckPaymentRequest.context';\nimport { useRecourseContext } from '../../../../CreatePaymentRequestPageRecourseModal/components/RecourseModal.context';\nimport { RecourseTable } from '../../../../CreatePaymentRequestPageRecourseModal/components/RecourseTable';\n\nimport { PartialAmountLabel } from './PartialAmountLabel';\nimport { TotalAmountLabel } from './TotalAmountLabel';\n\ntype SidebarTotalAmountProps = {\n  currency: TBLCurrency;\n};\n\nexport const SidebarTotalAmount = ({ currency }: SidebarTotalAmountProps) => {\n  const { isRecourse } = useRecourseContext();\n\n  const { selectedTerm } = useCheckPaymentRequestContext();\n  const payoutRatio = selectedTerm?.payoutRatio;\n  const grossFinancingAmount =\n    selectedTerm?.amountsBreakdown.grossFinancingAmount;\n\n  const isPartialFinancing = payoutRatio != null && payoutRatio !== 100;\n\n  return (\n    <Box\n      bgcolor=\"#FFF\"\n      display=\"flex\"\n      flexDirection=\"column\"\n      gap={1}\n      py={2}\n      px={2}\n    >\n      {!isRecourse && !isPartialFinancing && <TotalAmountLabel />}\n      {isRecourse && !isPartialFinancing && (\n        <Accordion>\n          <AccordionSummary\n            expandIcon={\n              <Icon\n                icon={<ChevronDownIcon data-test-id=\"expand-more-icon\" />}\n                size=\"small\"\n              />\n            }\n            aria-controls=\"panel1-content\"\n            id=\"panel1-header\"\n            sx={{ gap: 1 }}\n          >\n            <TotalAmountLabel />\n          </AccordionSummary>\n          <AccordionDetails>\n            <RecourseTable variant=\"custom\" />\n          </AccordionDetails>\n        </Accordion>\n      )}\n\n      {!isRecourse && isPartialFinancing && (\n        <>\n          <TotalAmountLabel />\n          <PartialAmountLabel\n            grossFinancingAmount={grossFinancingAmount}\n            payoutRatio={payoutRatio}\n            currency={currency}\n          />\n        </>\n      )}\n      {isRecourse && isPartialFinancing && (\n        <>\n          <TotalAmountLabel />\n          <Accordion>\n            <AccordionSummary\n              expandIcon={<ExpandMoreIcon />}\n              aria-controls=\"panel2-content\"\n              id=\"panel2-header\"\n            >\n              <PartialAmountLabel\n                grossFinancingAmount={grossFinancingAmount}\n                payoutRatio={payoutRatio}\n                currency={currency}\n              />\n            </AccordionSummary>\n            <AccordionDetails>\n              <RecourseTable variant=\"custom\" />\n            </AccordionDetails>\n          </Accordion>\n        </>\n      )}\n    </Box>\n  );\n};\n","import { Divider } from '@finmid/tbl-webapps/components';\nimport { currencyIcons } from '@finmid/tbl-webapps/utils';\n\nimport { DetailsWrapper } from '../../../../../components/DetailsWrapper';\nimport { useCheckPaymentRequestContext } from '../../../../CheckPaymentRequest.context';\nimport { useCreatePaymentRequestFormLabels } from '../../../../hooks';\n\nimport {\n  SidebarFeesBreakdown,\n  SidebarPayoutAmount,\n  SidebarTotalAmount,\n} from './components';\n\nexport const SidebarPaymentRequestBreakdown = () => {\n  const { sidebar } = useCreatePaymentRequestFormLabels();\n  const { currency } = useCheckPaymentRequestContext();\n\n  return (\n    <DetailsWrapper\n      title={sidebar.paymentDetails}\n      IconFlag={currencyIcons[currency]}\n      testId=\"payment-request-breakdown\"\n    >\n      <SidebarTotalAmount currency={currency} />\n      <Divider />\n      <SidebarFeesBreakdown currency={currency} />\n      <Divider />\n      <SidebarPayoutAmount currency={currency} />\n    </DetailsWrapper>\n  );\n};\n","import { Button } from '@finmid/tbl-webapps/components';\nimport { Tooltip } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport { useCheckPaymentRequestContext } from '../../../../CheckPaymentRequest.context';\n\nconst useButtonWithHint = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n\n  const { code, selectedTerm } = useCheckPaymentRequestContext();\n  const { netFinancingAmount } = selectedTerm?.amountsBreakdown ?? {};\n\n  let message = t('submitDisabledDefault');\n  if (\n    code === 'FEES_EXCEED_TOTAL_AMOUNT' ||\n    (netFinancingAmount != null && netFinancingAmount <= 0)\n  ) {\n    message = t('amountTooLow');\n  }\n\n  return message;\n};\n\nexport const ButtonWithHint = ({\n  disabled,\n  label,\n  loading,\n}: {\n  disabled: boolean;\n  label: string;\n  loading: boolean;\n}) => {\n  const message = useButtonWithHint();\n\n  return (\n    <Tooltip title={message}>\n      <span>\n        <Button\n          variant=\"primary\"\n          disabled={disabled}\n          loading={loading}\n          size=\"m\"\n          type=\"submit\"\n          fullWidth\n          data-test-id=\"submit-btn\"\n        >\n          {label}\n        </Button>\n      </span>\n    </Tooltip>\n  );\n};\n","import { Button } from '@finmid/tbl-webapps/components';\nimport { useFormContext } from 'react-hook-form';\n\nimport { useCheckPaymentRequestContext } from '../../../../CheckPaymentRequest.context';\nimport { CreatePaymentRequestOnePageFormType } from '../../../../CreatePaymentRequestOnePage.types';\nimport { useCreatePaymentRequestFormLabels } from '../../../../hooks';\n\nimport { ButtonWithHint } from './ButtonWithHint';\n\nexport const SubmitButton = () => {\n  const { formState, watch } =\n    useFormContext<CreatePaymentRequestOnePageFormType>();\n  const { eligible } = useCheckPaymentRequestContext();\n\n  const disabled =\n    !eligible || !formState.isValid || Object.keys(formState.errors).length > 0;\n\n  const { actions } = useCreatePaymentRequestFormLabels();\n  const instantPayout = watch('instantPayout');\n  const label = instantPayout\n    ? actions.createRequestAndPayout\n    : actions.createRequest;\n\n  if (disabled) {\n    return (\n      <ButtonWithHint\n        disabled={disabled}\n        label={label}\n        loading={formState.isLoading}\n      />\n    );\n  }\n\n  return (\n    <Button\n      variant=\"primary\"\n      size=\"m\"\n      type=\"submit\"\n      fullWidth\n      data-test-id=\"submit-btn\"\n      loading={formState.isLoading}\n    >\n      {label}\n    </Button>\n  );\n};\n","import { InvalidMessages } from '@finmid/distributor-types';\nimport { FormErrorInfo } from '@finmid/tbl-webapps/components';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\n\nimport {\n  SidebarInvolvedParties,\n  SidebarPaymentRequestBreakdown,\n} from './components';\nimport { SubmitButton } from './components/SubmitButton/SubmitButton';\n\ntype CreatePaymentRequestOnePageSidebarProps = {\n  invalidFieldsErrors: {\n    labels?: string[];\n    messages?: InvalidMessages;\n  };\n};\n\nexport const CreatePaymentRequestOnePageSidebar = ({\n  invalidFieldsErrors,\n}: CreatePaymentRequestOnePageSidebarProps) => (\n  <Box position=\"sticky\" alignSelf=\"start\" top={52}>\n    <SidebarPaymentRequestBreakdown />\n    <Spacer height={1} />\n    <SidebarInvolvedParties />\n    <Spacer height={3} />\n    <SubmitButton />\n    <Box mt={2}>\n      <FormErrorInfo invalidFieldsErrors={invalidFieldsErrors} />\n    </Box>\n  </Box>\n);\n","import { Button, PageNavigation } from '@finmid/tbl-webapps/components';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nexport const CreatePaymentRequestPageNavigation = () => {\n  const { t, ready } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice',\n  });\n  const breadcrumbs = useBreadcrumbs();\n  const navigate = useNavigate();\n\n  return (\n    <PageNavigation breadcrumbs={breadcrumbs.createPaymentRequest}>\n      {ready && (\n        <Button\n          variant=\"invisible\"\n          onClick={() => navigate(b2bPaymentRoutes.paymentRequests)}\n        >\n          {t('cancelButton')}\n        </Button>\n      )}\n    </PageNavigation>\n  );\n};\n","import { Dialog, Button } from '@finmid/tbl-webapps/components';\nimport { useTranslation } from 'react-i18next';\n\nimport { useRecourseContext, RecourseModalContent } from './components';\n\nexport const CreatePaymentRequestPageRecourseModal = () => {\n  const { isRecourseDialogOpen, setIsRecourseDialogOpen } =\n    useRecourseContext();\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'recourseModal',\n  });\n  return (\n    <Dialog\n      open={isRecourseDialogOpen}\n      onClose={() => setIsRecourseDialogOpen(false)}\n      actions={\n        <Button\n          variant=\"primary\"\n          size=\"m\"\n          type=\"submit\"\n          onClick={() => setIsRecourseDialogOpen(false)}\n        >\n          {t('btnLabel')}\n        </Button>\n      }\n      PaperProps={{ sx: { maxWidth: '640px' } }}\n    >\n      <RecourseModalContent />\n    </Dialog>\n  );\n};\n","import { Page, Typography } from '@finmid/tbl-webapps/components';\nimport Box from '@mui/material/Box';\nimport { FormProvider } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { CheckPaymentRequestContextProvider } from './CheckPaymentRequest.context';\nimport { useCreatePaymentRequestFormPayload } from './CreatePaymentRequestForm.context';\nimport {\n  CreatePaymentRequestOnePageForm,\n  CreatePaymentRequestOnePageSidebar,\n} from './components';\nimport { CreatePaymentRequestPageRecourseModal } from './components/CreatePaymentRequestPageRecourseModal';\nimport { useCreatePaymentRequestForm } from './hooks';\n\nexport const CreatePaymentRequestFormWrapper = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const { isLoading } = useCreatePaymentRequestFormPayload();\n  const { invalidFieldsErrors, methods, handleSubmitForm } =\n    useCreatePaymentRequestForm();\n\n  return (\n    <Page>\n      <form\n        onSubmit={handleSubmitForm}\n        style={{ cursor: isLoading ? 'wait' : 'unset' }}\n      >\n        <FormProvider {...methods}>\n          <Box display=\"flex\" width=\"100%\" justifyContent=\"center\">\n            <Box\n              display=\"grid\"\n              rowGap={2}\n              columnGap={5}\n              gridTemplateColumns=\"minmax(0, 632px) minmax(0, 400px)\"\n              gridTemplateAreas={`\n                \"title title\"\n                \"area1 area2\"\n                `}\n            >\n              <Typography\n                fontSize={24}\n                fontWeight={700}\n                style={{ gridArea: 'title' }}\n              >\n                {t('formTitle')}\n              </Typography>\n              <CheckPaymentRequestContextProvider>\n                <CreatePaymentRequestOnePageForm />\n                <CreatePaymentRequestOnePageSidebar\n                  invalidFieldsErrors={invalidFieldsErrors}\n                />\n                <CreatePaymentRequestPageRecourseModal />\n              </CheckPaymentRequestContextProvider>\n            </Box>\n          </Box>\n        </FormProvider>\n      </form>\n    </Page>\n  );\n};\n","import { Loader } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport { CreatePaymentRequestFormContextProvider } from './CreatePaymentRequestForm.context';\nimport { CreatePaymentRequestFormWrapper } from './CreatePaymentRequestFormWrapper';\nimport { CreatePaymentRequestPageNavigation } from './components';\nimport { RecourseContextProvider } from './components/CreatePaymentRequestPageRecourseModal/components';\nimport { useCreatePaymentRequestPage } from './hooks';\n\nexport const CreatePaymentRequestOnePage = () => {\n  const { ready: translationsReady } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice',\n  });\n  const { ready: componentsReady } = useTranslation('components');\n  const { ready: formatsReady } = useTranslation('formats');\n\n  const {\n    defaultCurrency,\n    defaultRepaymentTerms,\n    uniqueSeller,\n    isFetching,\n    error,\n    allowPayoutWithoutDueDate,\n  } = useCreatePaymentRequestPage();\n\n  const ready =\n    translationsReady &&\n    componentsReady &&\n    formatsReady &&\n    !isFetching &&\n    defaultRepaymentTerms != null; // TODO: check for DAILY\n\n  if (!ready || error) {\n    return <Loader />;\n  }\n\n  return (\n    <>\n      <CreatePaymentRequestPageNavigation />\n      <CreatePaymentRequestFormContextProvider\n        repaymentTerms={defaultRepaymentTerms}\n        defaultCurrency={defaultCurrency}\n        uniqueSeller={uniqueSeller}\n        allowPayoutWithoutDueDate={allowPayoutWithoutDueDate}\n      >\n        <RecourseContextProvider>\n          <CreatePaymentRequestFormWrapper />\n        </RecourseContextProvider>\n      </CreatePaymentRequestFormContextProvider>\n    </>\n  );\n};\n","export const MAX_FILE_SIZE = 15728640; // 15 MB\nexport const MAX_FILES = 20;\n","import { useEffect, useState } from 'react';\nimport { FileRejection } from 'react-dropzone';\n\nimport { MAX_FILES } from './constants';\n\nexport type FileErrors = {\n  rejectedFiles: string[];\n  errorCodes: string[];\n};\n\nexport const usePaymentRequestDocumentUpload = () => {\n  const [files, setFiles] = useState<File[]>([]);\n  const [fileErrors, setFileErrors] = useState<FileRejection[]>([]);\n  const [tooManyFiles, setTooManyFiles] = useState(false);\n\n  const addFiles = (newFiles: File[], rejectedFiles: FileRejection[]) => {\n    setFiles((f) => [...f, ...newFiles]);\n    setFileErrors(rejectedFiles);\n  };\n\n  useEffect(() => {\n    setTooManyFiles(files.length > MAX_FILES);\n    if (files.length === 0) setFileErrors([]);\n  }, [files.length]);\n\n  const removeFile = (index: number) => {\n    setFiles(files.filter((_, i) => i !== index));\n  };\n\n  return { addFiles, removeFile, files, fileErrors, tooManyFiles };\n};\n","import { File, Typography } from '@finmid/tbl-webapps/components';\nimport Box from '@mui/material/Box';\nimport { Fragment } from 'react';\nimport { useTranslation } from 'react-i18next';\n\ntype AddedFilesProps = {\n  files: File[];\n  onRemove: (index: number) => void;\n};\n\nexport const AddedFiles = ({ files, onRemove }: AddedFilesProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'documentUpload' });\n\n  return (\n    <Box display=\"flex\" flexDirection=\"column\" gap={1} p={2}>\n      <Typography\n        fontSize={13}\n        fontWeight={500}\n        lineHeight=\"16px\"\n        color=\"gray.500\"\n        mb={1}\n      >\n        {t('addedFiles.title', { count: files.length })}\n      </Typography>\n\n      {files.map((file, index) => (\n        <Fragment key={file.name + index}>\n          <File file={file} onRemove={() => onRemove(index)} />\n        </Fragment>\n      ))}\n    </Box>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Typography, UnstyledLink } from '@finmid/tbl-webapps/components';\nimport { humanReadableFileSize } from '@finmid/tbl-webapps/utils';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { MAX_FILE_SIZE } from '../constants';\n\nconst typographyStyles = {\n  fontSize: 15,\n  fontWeight: 400,\n  lineHeight: '20px',\n};\n\nconst List = styled.ul(({ theme }) => ({\n  ...typographyStyles,\n  color: theme.glo.color.foundations[60],\n  paddingInlineStart: theme.spacing(3),\n  marginBlock: 0,\n}));\n\ntype DocumentUploadDescriptionProps = {\n  docsExpected: boolean;\n  paymentRequestId: string;\n};\n\nexport const DocumentUploadDescription = ({\n  docsExpected,\n  paymentRequestId,\n}: DocumentUploadDescriptionProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'documentUpload' });\n\n  return (\n    <>\n      <Typography {...typographyStyles} color=\"gray.500\">\n        <Trans\n          t={t}\n          i18nKey={\n            docsExpected ? 'description' : 'documentsNotRequiredDescription'\n          }\n          components={{\n            u: (\n              <UnstyledLink\n                to={`/invoices?view=${paymentRequestId}`}\n                style={{ textDecoration: 'underline' }}\n              />\n            ),\n            br: <br />,\n          }}\n          values={{\n            paymentRequestId,\n          }}\n        />\n      </Typography>\n      <List>\n        <li>{t('docTypes.invoice')}</li>\n        <li>{t('docTypes.orderConfirmation')}</li>\n        <li>{t('docTypes.billOfLading')}</li>\n        <li>{t('docTypes.other')}</li>\n      </List>\n      <Typography {...typographyStyles} color=\"gray.500\">\n        {t('restrictions', {\n          maxFileSize: humanReadableFileSize(MAX_FILE_SIZE),\n        })}\n      </Typography>\n    </>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport { Trans, useTranslation } from 'react-i18next';\n\nconst Underlined = styled.u(({ theme }) => ({\n  color: theme.palette.gray[400],\n}));\n\nexport const UploadMore = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'documentUpload' });\n\n  return (\n    <>\n      <Typography fontSize={15} fontWeight={700} lineHeight=\"16px\">\n        {t('dropzone.uploadMoreTitle')}\n      </Typography>\n      <Spacer height={0.5} />\n      <Typography\n        fontSize={13}\n        fontWeight={500}\n        lineHeight=\"16px\"\n        color=\"gray.300\"\n      >\n        <Trans\n          t={t}\n          i18nKey=\"dropzone.uploadMoreSubtitle\"\n          components={{\n            u: <Underlined />,\n          }}\n        />\n      </Typography>\n    </>\n  );\n};\n","import {\n  DropzoneArea,\n  DropzoneEmptyState,\n} from '@finmid/tbl-webapps/components';\nimport Box from '@mui/material/Box';\nimport Dropzone, { FileRejection } from 'react-dropzone';\nimport { useTranslation } from 'react-i18next';\n\nimport { MAX_FILE_SIZE, MAX_FILES } from '../../constants';\n\nimport { UploadMore } from './UploadMore';\n\ntype FilesUploadProps = {\n  files: File[];\n  onDrop: (acceptedFiles: File[], rejectedFiles: FileRejection[]) => void;\n};\n\nexport const FilesUpload = ({ files, onDrop }: FilesUploadProps) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'documentUpload',\n  });\n  const hasAddedFiles = files.length > 0;\n\n  return (\n    <Dropzone\n      useFsAccessApi={false} // https://github.com/react-dropzone/react-dropzone/discussions/1339\n      onDrop={onDrop}\n      accept={{\n        'image/jpg': ['.jpg', '.jpeg'],\n        'image/png': ['.png'],\n        'application/pdf': ['.pdf'],\n      }}\n      maxFiles={MAX_FILES}\n      maxSize={MAX_FILE_SIZE}\n    >\n      {({ getRootProps, getInputProps }) => (\n        <DropzoneArea\n          {...getRootProps()}\n          css={{\n            transition: 'height 250ms ease-out',\n            height: hasAddedFiles ? 100 : undefined,\n          }}\n        >\n          <input {...getInputProps()} data-test-id=\"drop-files-input\" />\n          <Box\n            display=\"flex\"\n            flexDirection=\"column\"\n            alignItems=\"center\"\n            textAlign=\"center\"\n            data-test-id=\"drop-files-box\"\n          >\n            {hasAddedFiles ? (\n              <UploadMore />\n            ) : (\n              <DropzoneEmptyState title={t('dropzone.title')} />\n            )}\n          </Box>\n        </DropzoneArea>\n      )}\n    </Dropzone>\n  );\n};\n","import { humanReadableFileSize } from '@finmid/tbl-webapps/utils';\nimport { useCallback, useMemo } from 'react';\nimport { FileRejection } from 'react-dropzone';\nimport { useTranslation } from 'react-i18next';\n\nimport { MAX_FILE_SIZE, MAX_FILES } from './constants';\n\nexport const useCustomDropzoneErrors = () => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'validation',\n  });\n\n  const getCustomDropzoneErrors = useCallback(\n    (errorCode: string) => {\n      let message: string | undefined;\n      switch (errorCode) {\n        case 'file-invalid-type':\n          message = t('file.invalidType');\n          break;\n        case 'too-many-files':\n          message = t('file.tooMany', { maxFiles: MAX_FILES });\n          break;\n        case 'file-too-large':\n          message = t('file.tooLarge', {\n            maxSize: humanReadableFileSize(MAX_FILE_SIZE),\n          });\n          break;\n        default:\n          break;\n      }\n\n      return message;\n    },\n    [t],\n  );\n\n  return { getCustomDropzoneErrors };\n};\n\nexport const useUnqiueDropzoneErrors = (fileErrors: FileRejection[]) => {\n  const { getCustomDropzoneErrors } = useCustomDropzoneErrors();\n\n  const errorMessages = useMemo(() => {\n    const messages: string[] = [];\n    const uniqueErrorCodes = [\n      ...new Set(\n        fileErrors.flatMap(({ errors }) => {\n          return errors.map(({ code }) => code);\n        }),\n      ),\n    ];\n\n    uniqueErrorCodes.forEach((errorCode) => {\n      const message = getCustomDropzoneErrors(errorCode);\n      if (message) messages.push(message);\n    });\n\n    return messages;\n  }, [fileErrors, getCustomDropzoneErrors]);\n\n  return { errorMessages };\n};\n","import { Alert, Typography } from '@finmid/tbl-webapps/components';\nimport { FileRejection } from 'react-dropzone';\nimport { useTranslation } from 'react-i18next';\n\nimport { useUnqiueDropzoneErrors } from '../PaymentRequestDocumentUploadPage.errors';\n\ntype InvalidFilesAlertsProps = {\n  fileErrors: FileRejection[];\n};\n\nexport const InvalidFilesAlerts = ({ fileErrors }: InvalidFilesAlertsProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'documentUpload' });\n  const rejectedFilesNames = fileErrors.map(({ file }) => file.name).join(', ');\n  const { errorMessages } = useUnqiueDropzoneErrors(fileErrors);\n\n  const hasMultipleErrors = errorMessages.length > 1;\n\n  return (\n    <Alert severity=\"warning\" data-test-id=\"invalid-files\">\n      <Typography>\n        {fileErrors.length === 1\n          ? t('error.unableToAddFile')\n          : t('error.unableToAddFiles')}\n        {rejectedFilesNames}.\n      </Typography>\n\n      {hasMultipleErrors ? (\n        <ul>\n          {errorMessages.map((message, index) => (\n            <li key={index}>{message}</li>\n          ))}\n        </ul>\n      ) : (\n        <Typography mt={1}>{errorMessages[0]}</Typography>\n      )}\n    </Alert>\n  );\n};\n","import { Alert, Typography } from '@finmid/tbl-webapps/components';\n\nimport { useCustomDropzoneErrors } from '../PaymentRequestDocumentUploadPage.errors';\n\nexport const TooManyFilesAlert = () => {\n  const { getCustomDropzoneErrors } = useCustomDropzoneErrors();\n\n  return (\n    <Alert severity=\"warning\">\n      <Typography>{getCustomDropzoneErrors('too-many-files')}</Typography>\n    </Alert>\n  );\n};\n","import {\n  Divider,\n  Page,\n  PageNavigation,\n  ScrollableFormSection,\n  SectionContent,\n} from '@finmid/tbl-webapps/components';\nimport { useUploadPaymentRequestDocumentsMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useBreadcrumbs, useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { Button, Loader } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { usePaymentRequestDocumentUpload } from './PaymentRequestDocumentUploadPage.hook';\nimport {\n  AddedFiles,\n  DocumentUploadDescription,\n  FilesUpload,\n  InvalidFilesAlerts,\n  TooManyFilesAlert,\n} from './components';\n\ntype InnerPaymentRequestDocumentUploadPageProps = {\n  docsExpected: boolean;\n  paymentRequestId: string;\n};\n\nexport const InnerPaymentRequestDocumentUploadPage = ({\n  docsExpected,\n  paymentRequestId,\n}: InnerPaymentRequestDocumentUploadPageProps) => {\n  const { t, ready: paymentRequestsPageReady } = useTranslation(\n    'invoicesPage',\n    { keyPrefix: 'documentUpload' },\n  );\n  const { ready: componentsReady } = useTranslation('components');\n  const { ready: formatsReady } = useTranslation('formats');\n  const { paymentRequestDocumentUploadWithSidebar } =\n    useBreadcrumbs(paymentRequestId);\n  const breadcrumbs = paymentRequestDocumentUploadWithSidebar;\n\n  const { notifyError, notifySuccess } = useNotifications();\n  const navigate = useNavigate();\n\n  const isLoadingTranslations =\n    !paymentRequestsPageReady || !componentsReady || !formatsReady;\n\n  const { addFiles, removeFile, files, fileErrors, tooManyFiles } =\n    usePaymentRequestDocumentUpload();\n\n  const hasAddedFiles = files.length > 0;\n  const hasRejectedFiles = fileErrors.length > 0;\n\n  const [upload, { isLoading }] = useUploadPaymentRequestDocumentsMutation();\n\n  const handleUpload = async () => {\n    const { error } = await upload({ files, paymentRequestId });\n\n    if (error) {\n      notifyError(t('errorUploadingFiles'));\n    } else {\n      notifySuccess(t('successUploadingFiles'));\n      navigate(b2bPaymentRoutes.paymentRequests);\n    }\n  };\n\n  return (\n    <>\n      <PageNavigation breadcrumbs={breadcrumbs} />\n      <Page>\n        {isLoadingTranslations ? (\n          <Loader />\n        ) : (\n          <ScrollableFormSection\n            sectionTitle={t('sectionTitle')}\n            footerActions={[\n              <Button\n                disabled={!hasAddedFiles || tooManyFiles || isLoading}\n                onClick={handleUpload}\n                data-test-id=\"upload-submit-btn\"\n              >\n                {t('submitButton.label')}\n              </Button>,\n            ]}\n          >\n            <SectionContent disablePadding>\n              <Box display=\"flex\" flexDirection=\"column\" gap={2} p={2}>\n                <DocumentUploadDescription\n                  docsExpected={docsExpected}\n                  paymentRequestId={paymentRequestId}\n                />\n\n                <FilesUpload files={files} onDrop={addFiles} />\n\n                {hasRejectedFiles && (\n                  <InvalidFilesAlerts fileErrors={fileErrors} />\n                )}\n\n                {tooManyFiles && <TooManyFilesAlert />}\n              </Box>\n\n              {hasAddedFiles && (\n                <>\n                  <Divider />\n                  <AddedFiles files={files} onRemove={removeFile} />\n                </>\n              )}\n            </SectionContent>\n          </ScrollableFormSection>\n        )}\n      </Page>\n    </>\n  );\n};\n","import { useGetPaymentRequestTasksQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { Navigate, useParams } from 'react-router-dom';\n\nimport { InnerPaymentRequestDocumentUploadPage } from './InnerPaymentRequestDocumentUploadPage';\n\nexport const PaymentRequestDocumentUploadPage = () => {\n  const { invoiceId = '' } = useParams();\n  const { data, isLoading } = useGetPaymentRequestTasksQuery(invoiceId);\n\n  if (isLoading) return <Loader />;\n\n  const pendingTasks = data?.filter(({ status }) => status === 'PENDING') ?? [];\n  const hasPendingTasks = pendingTasks.length > 0;\n  const mustUploadDocs =\n    hasPendingTasks &&\n    pendingTasks.some(({ paymentIntentId }) => {\n      return paymentIntentId === invoiceId;\n    });\n\n  if (invoiceId) {\n    return (\n      <InnerPaymentRequestDocumentUploadPage\n        paymentRequestId={invoiceId}\n        docsExpected={mustUploadDocs}\n      />\n    );\n  }\n\n  return (\n    <Navigate to={`${b2bPaymentRoutes.paymentRequests}/${invoiceId}`} replace />\n  );\n};\n","import cloneDeep from 'lodash/cloneDeep';\nimport set from 'lodash/set';\nimport { createContext, PropsWithChildren, useContext, useState } from 'react';\nimport { useSearchParams } from 'react-router-dom';\nimport { useMount, useSessionStorage } from 'react-use';\n\nimport {\n  invoicesFiltersKey,\n  PaymentRequestsFilters,\n  UpdateFilters,\n  useDefaultFilters,\n} from '../PaymentRequestsFilters';\n\ntype ListContext = {\n  filters: PaymentRequestsFilters;\n  resetFilters: () => void;\n  updateFilters: (filters: UpdateFilters) => void;\n};\n\nconst initialContext = null;\n\nexport const PaymentRequestsListContext = createContext<ListContext | null>(\n  initialContext,\n);\n\nexport const PaymentRequestsListContextProvider = ({\n  children,\n}: PropsWithChildren) => {\n  const { defaultPaymentRequestsFilters } = useDefaultFilters();\n\n  const [storedFilters, setStoredFilters] =\n    useSessionStorage<PaymentRequestsFilters>(invoicesFiltersKey);\n  const [searchParams] = useSearchParams();\n\n  const [filters, setFilters] = useState<PaymentRequestsFilters>(() => {\n    return storedFilters ?? defaultPaymentRequestsFilters;\n  });\n\n  const updateFilters = (updatedFilters: UpdateFilters) => {\n    const _filters = cloneDeep(filters);\n    Object.entries(updatedFilters).forEach(([key, value]) => {\n      set(_filters, key, value);\n    });\n    setStoredFilters(_filters);\n    setFilters(_filters);\n  };\n\n  const resetFilters = () => {\n    setStoredFilters(defaultPaymentRequestsFilters);\n    setFilters(defaultPaymentRequestsFilters);\n  };\n\n  useMount(() => {\n    const buyer = searchParams.get('buyer');\n    const seller = searchParams.get('seller');\n\n    updateFilters({\n      ...(buyer ? { 'server.externalBuyerIds': [buyer] } : {}),\n      ...(seller ? { 'server.externalSellerIds': [seller] } : {}),\n    });\n  });\n\n  const value = {\n    filters,\n    resetFilters,\n    updateFilters,\n  };\n\n  return (\n    <PaymentRequestsListContext.Provider value={value}>\n      {children}\n    </PaymentRequestsListContext.Provider>\n  );\n};\n\nexport const usePaymentRequestsListContext = () => {\n  const context = useContext(PaymentRequestsListContext);\n\n  if (context == null) {\n    throw new Error(\n      'usePaymentRequestsListContext can only be used inside PaymentRequestsListContext Provider',\n    );\n  }\n\n  return context;\n};\n","import {\n  DropzoneArea,\n  DropzoneEmptyState,\n} from '@finmid/tbl-webapps/components';\nimport { LoaderCircle } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport Dropzone, { FileRejection } from 'react-dropzone';\nimport { useTranslation } from 'react-i18next';\n\ntype BulkCreationDropzoneProps = {\n  onDrop: (acceptedFiles: File[], fileRejections: FileRejection[]) => void;\n  isLoading?: boolean;\n};\n\nexport const BulkCreationDropzone = ({\n  onDrop,\n  isLoading = false,\n}: BulkCreationDropzoneProps) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice.bulkCreationDialog',\n  });\n\n  return (\n    <Dropzone\n      useFsAccessApi={false}\n      onDrop={onDrop}\n      accept={{ 'text/csv': ['.csv'] }}\n      multiple={false}\n    >\n      {({ getRootProps, getInputProps }) => (\n        <DropzoneArea {...getRootProps()}>\n          <input {...getInputProps()} data-test-id=\"drop-files-input\" />\n          <Box\n            display=\"flex\"\n            flexDirection=\"column\"\n            alignItems=\"center\"\n            textAlign=\"center\"\n            data-test-id=\"drop-files-box\"\n          >\n            {isLoading ? (\n              <LoaderCircle />\n            ) : (\n              <DropzoneEmptyState title={t('dropzoneTitle')} />\n            )}\n          </Box>\n        </DropzoneArea>\n      )}\n    </Dropzone>\n  );\n};\n","import { Dialog, Typography } from '@finmid/tbl-webapps/components';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { Button, Spacer } from '@finmid/ui/ocarina';\nimport posthog from 'posthog-js';\nimport { useEffect, useState } from 'react';\nimport { FileRejection } from 'react-dropzone';\nimport { Trans, useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport {\n  CsvDropzoneFileErrors,\n  useCsvTemplateDownloadUrl,\n} from '../../../shared';\n\nimport { BulkCreationDropzone } from './BulkCreationDropzone';\n\nconst typographyProps = {\n  fontSize: 15,\n  lineHeight: '20px',\n  fontWeight: 400,\n  color: 'gray.500',\n};\n\ntype BulkCreationDialogProps = {\n  open: boolean;\n  onClose: () => void;\n};\n\nexport const BulkCreationDialog = ({\n  open,\n  onClose,\n}: BulkCreationDialogProps) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice.bulkCreationDialog',\n  });\n  const navigate = useNavigate();\n  const { url, fileName } = useCsvTemplateDownloadUrl();\n\n  const [file, setFile] = useState<File>();\n  const [fileErrors, setFileErrors] = useState<FileRejection[]>([]);\n\n  const addFile = (newFiles: File[], rejectedFiles: FileRejection[]) => {\n    posthog.capture('bulk_upload_dialog_add_file');\n\n    setFile(newFiles[0]);\n    setFileErrors(rejectedFiles);\n  };\n\n  useEffect(() => {\n    if (file != null) {\n      const timeoutBeforeRedirect = setTimeout(() => {\n        navigate(b2bPaymentRoutes.createPaymentRequestsBulk, {\n          state: { file },\n        });\n      }, 500);\n\n      return () => clearTimeout(timeoutBeforeRedirect);\n    }\n  }, [file, navigate]);\n\n  return (\n    <Dialog\n      open={open}\n      onClose={onClose}\n      title={t('title')}\n      fullWidth\n      PaperProps={{\n        style: { maxWidth: '640px' },\n      }}\n      actions={[\n        <Button variant=\"secondary\" onClick={onClose}>\n          {t('cancelBtn')}\n        </Button>,\n      ]}\n      data-test-id=\"bulk-creation-dialog\"\n    >\n      <Typography {...typographyProps}>\n        <Trans\n          t={t}\n          i18nKey=\"instruction\"\n          components={{\n            a: (\n              <a\n                href={url}\n                download={fileName}\n                onClick={() =>\n                  posthog.capture('bulk_upload_dialog_download_template')\n                }\n                css={{ color: 'inherit' }}\n              >\n                link\n              </a>\n            ),\n          }}\n        />\n      </Typography>\n      <Spacer height={1} />\n      <Typography {...typographyProps}>{t('info.title')}</Typography>\n      <ul\n        css={{\n          marginBlockStart: 4,\n          marginBlockEnd: 0,\n          paddingInlineStart: 22,\n        }}\n      >\n        <Trans\n          t={t}\n          i18nKey=\"info.list\"\n          components={{\n            li: <Typography {...typographyProps} component=\"li\" />,\n          }}\n        />\n      </ul>\n\n      <Spacer height={3} />\n      <BulkCreationDropzone onDrop={addFile} isLoading={file != null} />\n\n      {fileErrors.length > 0 ? (\n        <>\n          <Spacer height={1} />\n          <CsvDropzoneFileErrors fileErrors={fileErrors} />\n        </>\n      ) : null}\n    </Dialog>\n  );\n};\n","import { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { SelectOutlinedOpenIcon } from '@finmid/ui/icons';\nimport {\n  DocumentIcon,\n  DocumentsIcon,\n  Dropdown,\n  Icon,\n  Menu,\n  MenuButton,\n  MenuItem,\n  MenuSection,\n} from '@finmid/ui/ocarina';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { BulkCreationDialog } from './BulkCreationDialog';\n\ntype PaymentRequestCreationMenuProps = {\n  disabled?: boolean;\n};\n\nexport const PaymentRequestCreationMenu = ({\n  disabled,\n}: PaymentRequestCreationMenuProps) => {\n  const navigate = useNavigate();\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const [openBulkCreationDialog, setOpenBulkCreationDialog] = useState(false);\n\n  return (\n    <>\n      <Dropdown>\n        <MenuButton\n          disabled={disabled}\n          suffixIcon={\n            <SelectOutlinedOpenIcon\n              sx={{\n                fontSize: '1rem',\n                transform: 'rotate(180deg)',\n              }}\n            />\n          }\n          data-test-id=\"create-payment-request-menu-button\"\n        >\n          {t('btnLabel')}\n        </MenuButton>\n        <Menu placement=\"bottom-end\">\n          <MenuSection>\n            <MenuItem\n              onClick={() => navigate(b2bPaymentRoutes.createPaymentRequest)}\n              data-test-id=\"create-single\"\n            >\n              <Icon size=\"small\" icon={<DocumentIcon />} />\n              {t('createSingle.btnLabel')}\n            </MenuItem>\n          </MenuSection>\n          <MenuSection>\n            <MenuItem\n              onClick={() => {\n                posthog.capture('clicked_open_bulk_creation_dialog');\n                setOpenBulkCreationDialog(true);\n              }}\n              data-test-id=\"create-multiple\"\n            >\n              <Icon size=\"small\" icon={<DocumentsIcon />} />\n              {t('createMultiple.btnLabel')}\n            </MenuItem>\n          </MenuSection>\n        </Menu>\n      </Dropdown>\n\n      <BulkCreationDialog\n        open={openBulkCreationDialog}\n        onClose={() => setOpenBulkCreationDialog(false)}\n      />\n    </>\n  );\n};\n","import { Tooltip, fetchErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport {\n  useGetBuyersQuery,\n  useGetSellersQuery,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { useEffect } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { PaymentRequestCreationMenu } from './PaymentRequestCreationMenu';\n\nexport const CreatePaymentRequestButton = () => {\n  const { displayErrorToast } = useDisplayErrorToast();\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n  const {\n    data: buyersResponse,\n    isLoading: isLoadingBuyers,\n    isError: isErrorBuyers,\n    error: errorBuyers,\n  } = useGetBuyersQuery({ status: 'ACTIVE' });\n  const {\n    data: sellersResponse,\n    isLoading: isLoadingSellers,\n    isError: isErrorSellers,\n    error: errorSellers,\n  } = useGetSellersQuery({ status: 'ACTIVE' });\n\n  const isLoading = isLoadingBuyers || isLoadingSellers;\n  const isError = errorBuyers != null || errorSellers != null;\n  const missingEntities =\n    buyersResponse?.data &&\n    buyersResponse.data.length === 0 &&\n    sellersResponse?.data &&\n    sellersResponse.data.length === 0;\n  const tooltipMessage = isError\n    ? t('live.errorEntities')\n    : missingEntities\n    ? t('live.missingEntities')\n    : '';\n\n  useEffect(() => {\n    if (isErrorBuyers || isErrorSellers) {\n      displayErrorToast(fetchErrorProps);\n    }\n  }, [isErrorBuyers, isErrorSellers, displayErrorToast]);\n\n  return (\n    <Tooltip title={tooltipMessage} placement=\"top-end\">\n      <div>\n        <PaymentRequestCreationMenu\n          disabled={isLoading || isError || missingEntities}\n        />\n      </div>\n    </Tooltip>\n  );\n};\n","import { PageNavigation } from '@finmid/tbl-webapps/components';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { useTranslation } from 'react-i18next';\n\nimport { CreatePaymentRequestButton } from './CreatePaymentRequestButton';\n\nexport const PaymentRequestsPageNavigation = () => {\n  const { ready } = useTranslation('invoicesPage', {\n    keyPrefix: 'createInvoice',\n  });\n\n  const breadcrumbs = useBreadcrumbs();\n\n  return (\n    <PageNavigation breadcrumbs={breadcrumbs.paymentRequests}>\n      {ready && <CreatePaymentRequestButton />}\n    </PageNavigation>\n  );\n};\n","import { PaymentRequest } from '@finmid/distributor-types';\nimport { GridRowParams } from '@mui/x-data-grid';\nimport { useEffect, useState } from 'react';\nimport { useSearchParams } from 'react-router-dom';\n\nexport const useShowPaymentDetails = () => {\n  const [searchParams, setSearchParams] = useSearchParams();\n  const [openSidebar, setOpenSidebar] = useState(false);\n  const [visiblePaymentRequestId, setVisiblePaymentRequestId] =\n    useState<string>('');\n\n  useEffect(() => {\n    const view = searchParams.get('view');\n    if (view) {\n      setVisiblePaymentRequestId(view);\n      setOpenSidebar(true);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const closeSidebar = () => {\n    setSearchParams((params) => {\n      params.delete('view');\n      return params;\n    });\n    setOpenSidebar(false);\n  };\n  const showSidebar = () => setOpenSidebar(true);\n\n  const triggerOpenSidebar = (id: string) => {\n    showSidebar();\n    setVisiblePaymentRequestId(id);\n  };\n\n  const onRowClick = ({ row: { id } }: GridRowParams<PaymentRequest>) => {\n    const params = { view: id };\n    setSearchParams(params);\n    triggerOpenSidebar(id);\n  };\n\n  return {\n    openSidebar,\n    visiblePaymentRequestId,\n    closeSidebar,\n    onRowClick,\n  };\n};\n","import { GetPaymentRequests } from '@finmid/distributor-types';\nimport { fetchErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useGetPaymentRequestsStatsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useCallback, useEffect } from 'react';\n\nimport { usePaymentRequestsListContext } from '../../../PaymentRequestsPage.context';\n\nexport const usePagination = ({\n  nextCursor,\n  previousCursor,\n}: GetPaymentRequests.GatewayResponse['metadata']) => {\n  const {\n    filters: { firstPosition, server },\n    updateFilters,\n  } = usePaymentRequestsListContext();\n\n  const { limit, search, status, from, to } = server;\n\n  const paginationState = {\n    page: Math.floor(firstPosition / limit),\n    pageSize: limit,\n  };\n\n  const {\n    data: paymentRequestsStats,\n    isError: isErrorStats,\n    isFetching: isFetchingStats,\n  } = useGetPaymentRequestsStatsQuery({ search, from, to });\n\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  useEffect(() => {\n    if (isErrorStats) {\n      displayErrorToast(fetchErrorProps);\n    }\n  }, [isErrorStats, displayErrorToast]);\n\n  const onPaginationBack = useCallback(async () => {\n    if (previousCursor != null) {\n      const updatedFilters = {\n        firstPosition: Math.max(firstPosition - limit, 1),\n        'server.cursor': firstPosition < limit ? undefined : previousCursor,\n      };\n      updateFilters(updatedFilters);\n    }\n  }, [firstPosition, limit, previousCursor, updateFilters]);\n\n  const onPaginationNext = useCallback(async () => {\n    if (nextCursor != null) {\n      const updatedFilters = {\n        firstPosition: firstPosition + limit,\n        'server.cursor': nextCursor,\n      };\n      updateFilters(updatedFilters);\n    }\n  }, [firstPosition, limit, nextCursor, updateFilters]);\n\n  const currentStatus = status ?? 'ALL';\n\n  const rowsCount = paymentRequestsStats?.[currentStatus] ?? 0;\n\n  const onPageSizeChange = useCallback(\n    async (pageSize: number) => {\n      const updatedFilters = {\n        'server.limit': pageSize,\n        // reset cursor and firstPosition\n        firstPosition: 1,\n        'server.cursor': undefined,\n      };\n      updateFilters(updatedFilters);\n    },\n    [updateFilters],\n  );\n\n  return {\n    rowsCount,\n    onPaginationBack,\n    onPaginationNext,\n    paginationState,\n    onPageSizeChange,\n\n    loading: isFetchingStats,\n  };\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { useTranslation } from 'react-i18next';\n\nimport { usePaymentRequestsListContext } from '../../../PaymentRequestsPage.context';\n\nexport const usePaymentRequestsTableWithSidebar = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'table' });\n  const { filters } = usePaymentRequestsListContext();\n\n  const { server } = filters;\n\n  const zeroStateDescriptionNoFilter =\n    ENVIRONMENT === 'live'\n      ? t('noPaymentRequestsMessageLive')\n      : t('noPaymentRequestsMessageTest');\n  const zeroStateDescription =\n    server.status || server.search\n      ? t('zeroStateDescriptionWithFilters')\n      : zeroStateDescriptionNoFilter;\n\n  return {\n    zeroStateDescription,\n  };\n};\n","import {\n  useGetBuyerByIdQuery,\n  useGetSellerByIdQuery,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { useCallback, useEffect, useState } from 'react';\nimport { useSearchParams } from 'react-router-dom';\n\nimport { usePaymentRequestsListContext } from '../../../PaymentRequestsPage.context';\n\ntype ToolbarFilters = {\n  label: string;\n  id: string;\n  onRemove: () => void;\n}[];\n\nexport const useBuyersSellersFilter = () => {\n  const {\n    filters: { server },\n    updateFilters,\n  } = usePaymentRequestsListContext();\n  const [, setSearchParams] = useSearchParams();\n  const [filters, setFilters] = useState<ToolbarFilters>([]);\n\n  const buyerId = server.externalBuyerIds?.[0] ?? '';\n  const { data: buyer } = useGetBuyerByIdQuery(\n    { externalId: buyerId },\n    { skip: buyerId === '' },\n  );\n\n  const sellerId = server.externalSellerIds?.[0] ?? '';\n  const { data: seller } = useGetSellerByIdQuery(\n    { externalId: sellerId },\n    { skip: sellerId === '' },\n  );\n\n  const clearFilters = useCallback(\n    (filter: 'buyer' | 'seller') => {\n      setSearchParams((params) => {\n        params.delete(filter);\n        return params;\n      });\n      updateFilters({\n        [filter === 'buyer'\n          ? 'server.externalBuyerIds'\n          : 'server.externalSellerIds']: undefined,\n      });\n    },\n    [setSearchParams, updateFilters],\n  );\n\n  useEffect(() => {\n    const newFilters: ToolbarFilters = [];\n\n    if (server.externalBuyerIds && buyer) {\n      newFilters.push({\n        id: buyer.externalId,\n        label: buyer.legalName,\n        onRemove: () => clearFilters('buyer'),\n      });\n    }\n\n    if (server.externalSellerIds && seller) {\n      newFilters.push({\n        id: seller.externalId,\n        label: seller.legalName,\n        onRemove: () => clearFilters('seller'),\n      });\n    }\n\n    setFilters(newFilters);\n  }, [\n    buyer,\n    seller,\n    server.externalBuyerIds,\n    server.externalSellerIds,\n    clearFilters,\n  ]);\n\n  return filters;\n};\n","import { Button, CloseXIcon } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\n\nimport { useBuyersSellersFilter } from './hooks';\n\nexport const BuyersSellersFilter = () => {\n  const filters = useBuyersSellersFilter();\n\n  if (filters.length > 0)\n    return (\n      <Box mr={1} display=\"flex\" gap=\"inherit\">\n        {filters.map(({ id, label, onRemove }) => (\n          <Button\n            prefixIcon={<CloseXIcon width={16} />}\n            onClick={onRemove}\n            key={id}\n          >\n            {label}\n          </Button>\n        ))}\n      </Box>\n    );\n\n  return null;\n};\n","import { DatePickerOcarinaLike } from '@finmid/tbl-webapps/components';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { formatISO } from 'date-fns';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { usePaymentRequestsListContext } from '../../PaymentRequestsPage.context';\n\nconst earliestPossibleDate = new Date('01-01-2022');\nconst latestPossibleDate = new Date();\n\nconst parseDate = (date: Date) =>\n  formatISO(new Date(date), { representation: 'date' });\n\nconst areDatesMeaningful = (fromDate: Date | null, toDate: Date | null) => {\n  if (fromDate == null || toDate == null) {\n    return false;\n  }\n\n  const fromTime = fromDate.getTime();\n  const toTime = toDate.getTime();\n\n  if (isNaN(fromTime) || isNaN(toTime)) {\n    return false;\n  }\n\n  return fromTime > 0 && toTime > 0 && toTime > fromTime;\n};\n\nexport const PaymentRequestsDatesFilter = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'table' });\n  const { filters, updateFilters } = usePaymentRequestsListContext();\n\n  const { server } = filters;\n\n  const toFilter = server.to ? new Date(server.to) : new Date();\n\n  const [fromDate, setFromDate] = useState<Date | null>(\n    () => new Date(server.from),\n  );\n  const [toDate, setToDate] = useState<Date | null>(() =>\n    server.to ? new Date(server.to) : new Date(),\n  );\n  const lazyQueryDatesFilter = async (fromDate: Date, toDate: Date) => {\n    const from = parseDate(fromDate);\n    const to = parseDate(toDate);\n    const updatedFilters = {\n      firstPosition: 1,\n      'server.from': from,\n      'server.to': to,\n      'server.cursor': undefined,\n    };\n    updateFilters(updatedFilters);\n  };\n\n  const handleChangeFrom = async (from: Date | null) => {\n    setFromDate(from);\n    if (from != null && toDate != null && areDatesMeaningful(from, toDate)) {\n      await lazyQueryDatesFilter(from, toDate);\n    }\n  };\n\n  const handleChangeTo = async (to: Date | null) => {\n    setToDate(to);\n    if (fromDate != null && to != null && areDatesMeaningful(fromDate, to)) {\n      await lazyQueryDatesFilter(fromDate, to);\n    }\n  };\n\n  return (\n    <Box display=\"flex\">\n      <DatePickerOcarinaLike\n        label={t('from')}\n        value={fromDate}\n        onChange={(e) => handleChangeFrom(e)}\n        disableFuture\n        minDate={earliestPossibleDate}\n        maxDate={toDate ?? toFilter}\n      />\n      <Spacer width={2} />\n      <DatePickerOcarinaLike\n        label={t('to')}\n        value={toDate}\n        onChange={(e) => handleChangeTo(e)}\n        disableFuture\n        minDate={fromDate ?? new Date(server.from)}\n        maxDate={latestPossibleDate}\n      />\n    </Box>\n  );\n};\n","import { DisplayedPaymentRequestStatus } from '@finmid/distributor-types';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { useGetPaymentRequestsStatsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { SelectOutlinedOpenIcon } from '@finmid/ui/icons';\nimport { Dropdown, Menu, MenuButton, MenuItem } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { FunctionComponent } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { UpdateFilters } from '../../../PaymentRequestsFilters';\nimport { paymentRequestStatusMapNew } from '../../../components';\nimport { usePaymentRequestsListContext } from '../../PaymentRequestsPage.context';\n\ntype Status = DisplayedPaymentRequestStatus | 'ALL';\n\nconst statuses = {\n  ALL: 'all',\n  PENDING: paymentRequestStatusMapNew.PENDING.translationKey,\n  PROCESSING: paymentRequestStatusMapNew.PROCESSING.translationKey,\n  PENDING_REPAYMENT:\n    paymentRequestStatusMapNew.PENDING_REPAYMENT.translationKey,\n  CANCELLED: paymentRequestStatusMapNew.CANCELLED.translationKey,\n  CLOSED: paymentRequestStatusMapNew.CLOSED.translationKey,\n} as const satisfies Record<Status, string>;\n\nexport const StatusSelector: FunctionComponent = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'status' });\n\n  const { filters, updateFilters } = usePaymentRequestsListContext();\n  const { data: stats } = useGetPaymentRequestsStatsQuery({\n    ...filters.server,\n  });\n\n  const selectedStatus = filters.server.status ?? 'ALL';\n\n  const handleChange = async (status: Status) => {\n    const updatedStatus = status === 'ALL' ? undefined : status;\n    const updatedFilters: UpdateFilters = {\n      firstPosition: 1,\n      'server.cursor': undefined,\n      'server.status': updatedStatus,\n    };\n    updateFilters(updatedFilters);\n  };\n\n  return (\n    <Dropdown>\n      <MenuButton\n        variant=\"invisible\"\n        suffixIcon={\n          <SelectOutlinedOpenIcon\n            sx={{ fontSize: '1rem', transform: 'rotate(180deg)' }}\n          />\n        }\n      >\n        {selectedStatus === 'ALL'\n          ? t('viewAllStatuses')\n          : t('viewButton', {\n              selectedStatus: t(statuses[selectedStatus]).toLowerCase(),\n            })}\n      </MenuButton>\n\n      <Menu placement=\"bottom-end\">\n        {(\n          Object.entries(statuses) as [Status, (typeof statuses)[Status]][]\n        ).map(([value, statusKey]) => (\n          <MenuItem key={value} onClick={() => handleChange(value)}>\n            <Box display=\"flex\" width=\"100%\" justifyContent=\"space-between\">\n              <Typography>{t(statusKey)}</Typography>\n              <Typography>{stats?.[value] ?? '-'}</Typography>\n            </Box>\n          </MenuItem>\n        ))}\n      </Menu>\n    </Dropdown>\n  );\n};\n","import {\n  GetPaymentRequest,\n  GetPaymentRequestDocuments,\n  GetPaymentRequestPayouts,\n  GetPaymentRequestStatusLogsList,\n  GetSellerById_GatewayResponse,\n} from '@finmid/distributor-types';\nimport {\n  createContext,\n  Dispatch,\n  PropsWithChildren,\n  SetStateAction,\n  useContext,\n  useState,\n} from 'react';\n\ntype Context = {\n  isMaxPayout: boolean;\n  paymentRequest: GetPaymentRequest.GatewayResponse;\n  payouts: GetPaymentRequestPayouts.GatewayResponse;\n  seller: GetSellerById_GatewayResponse;\n  logEntries: GetPaymentRequestStatusLogsList.GatewayResponse['logEntries'];\n  uploadedDocuments: GetPaymentRequestDocuments.GatewayResponse['documents'];\n  isPayoutDialogOpen: boolean;\n  setIsPayoutDialogOpen: Dispatch<SetStateAction<boolean>>;\n};\n\nconst initialContext = null;\n\nexport const PaymentRequestActivityContext = createContext<Context | null>(\n  initialContext,\n);\n\ntype PaymentRequestSidebarDetailsContextProviderProps = PropsWithChildren<{\n  paymentRequest: GetPaymentRequest.GatewayResponse;\n  payouts: GetPaymentRequestPayouts.GatewayResponse;\n  seller: GetSellerById_GatewayResponse;\n  logEntries: GetPaymentRequestStatusLogsList.GatewayResponse['logEntries'];\n  uploadedDocuments: GetPaymentRequestDocuments.GatewayResponse['documents'];\n}>;\n\nexport const PaymentRequestSidebarDetailsContextProvider = ({\n  children,\n  logEntries,\n  paymentRequest,\n  payouts,\n  seller,\n  uploadedDocuments,\n}: PaymentRequestSidebarDetailsContextProviderProps) => {\n  const [isPayoutDialogOpen, setIsPayoutDialogOpen] = useState(false);\n\n  const value: Context = {\n    isMaxPayout: payouts.length === 1 && payouts[0].percentageGross === 100,\n    logEntries,\n    paymentRequest,\n    payouts,\n    seller,\n    isPayoutDialogOpen,\n    setIsPayoutDialogOpen,\n    uploadedDocuments,\n  };\n\n  return (\n    <PaymentRequestActivityContext.Provider value={value}>\n      {children}\n    </PaymentRequestActivityContext.Provider>\n  );\n};\n\nexport const usePaymentRequestSidebarPayload = () => {\n  const context = useContext(PaymentRequestActivityContext);\n\n  if (context == null) {\n    throw new Error(\n      'usePaymentRequestSidebarPayload can only be used inside PaymentRequestSidebarDetailsContextProvider Provider',\n    );\n  }\n\n  return context;\n};\n","import styled from '@emotion/styled';\nimport Box from '@mui/material/Box';\n\nexport const labelProps = {\n  fontSize: 13,\n  lineHeight: '16px',\n  fontWeight: 500,\n  color: 'grey.500',\n};\n\nexport const valueProps = {\n  fontSize: 15,\n  lineHeight: '20px',\n  fontWeight: 400,\n  numeric: true,\n};\n\nexport const Row = styled(Box)({\n  display: 'flex',\n  alignItems: 'baseline',\n  '> :last-child': {\n    flex: 1,\n    textAlign: 'right',\n  },\n});\n","import { Divider, Typography } from '@finmid/tbl-webapps/components';\nimport { useGetDistributorAttributesQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useFormat } from '@finmid/translations';\nimport { Badge, ElevatedPaper, Popper, Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport Fade from '@mui/material/Fade';\nimport { useTranslation } from 'react-i18next';\n\nimport { usePaymentRequestSidebarPayload } from '../../../../../../../PaymentRequestDetailsSidebar.context';\n\nimport { labelProps, Row, valueProps } from './FeeBreakdownPopper.styled';\n\ntype FeeBreakdownPopperProps = {\n  anchorEl: HTMLDivElement | null;\n  open: boolean;\n};\n\nexport const FeeBreakdownPopper = ({\n  anchorEl,\n  open,\n}: FeeBreakdownPopperProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'details' });\n  const { money } = useFormat();\n  const {\n    paymentRequest: { currency, amountsBreakdown, totalAmount },\n  } = usePaymentRequestSidebarPayload();\n  const { data } = useGetDistributorAttributesQuery();\n  const isMORDistributor = data?.actAsMOR ?? false;\n  return (\n    <Popper\n      open={open}\n      anchorEl={anchorEl}\n      transition\n      placement=\"bottom-end\"\n      css={{ zIndex: 1201 }}\n    >\n      {({ TransitionProps }) => (\n        <Fade {...TransitionProps} timeout={350}>\n          <ElevatedPaper css={{ padding: 16, width: 336 }}>\n            <Row>\n              <Typography {...labelProps}>{t('amount')}</Typography>\n              <Typography {...valueProps} color=\"gray.500\">\n                {money(totalAmount, currency)}\n              </Typography>\n            </Row>\n            <Spacer height={1} />\n            <Row>\n              <Box display=\"flex\" alignItems=\"inherit\" gap={1}>\n                <Typography {...labelProps}>{t('totalFee')}</Typography>\n                <Badge\n                  label={amountsBreakdown.fees.totalFeePercentage + '%'}\n                  variant=\"neutral\"\n                />\n              </Box>\n              <Typography {...valueProps}>\n                {'-' + money(amountsBreakdown.fees.totalFeeAmount, currency)}\n              </Typography>\n            </Row>\n            <Spacer height={1} />\n            {!isMORDistributor && (\n              <Box\n                display=\"flex\"\n                flexDirection=\"column\"\n                gap=\"inherit\"\n                bgcolor=\"gray.50\"\n                borderRadius={1}\n                padding={1}\n              >\n                <Row>\n                  <Typography {...labelProps}>{t('serviceFee')}</Typography>\n                  <Typography {...valueProps}>\n                    {money(amountsBreakdown.fees.details.serviceFee, currency)}\n                  </Typography>\n                </Row>\n                <Spacer height={1} />\n                <Row>\n                  <Typography {...labelProps}>{t('platformMarkup')}</Typography>\n                  <Typography {...valueProps}>\n                    {money(\n                      amountsBreakdown.fees.details.platformMarkup,\n                      currency,\n                    )}\n                  </Typography>\n                </Row>\n              </Box>\n            )}\n            <Spacer height={2} />\n            <Divider />\n            <Spacer height={2} />\n            <Row>\n              <Typography {...labelProps} fontWeight={700}>\n                {t('payoutAmount')}\n              </Typography>\n              <Typography {...valueProps} fontWeight={700}>\n                {money(amountsBreakdown.payoutAmount, currency)}\n              </Typography>\n            </Row>\n          </ElevatedPaper>\n        </Fade>\n      )}\n    </Popper>\n  );\n};\n","import { IconButton, InfoIcon } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { FocusEvent, MouseEvent, useState } from 'react';\n\nimport { FeeBreakdownPopper } from './FeeBreakdownPopper';\n\nexport const FeeBreakdownIconButton = () => {\n  const [anchorEl, setAnchorEl] = useState<null | HTMLDivElement>(null);\n  const [openFeeBreakdown, setOpenFeeBreakdown] = useState(false);\n\n  const openPopper = (\n    e: MouseEvent<HTMLDivElement> | FocusEvent<HTMLDivElement>,\n  ) => {\n    if (anchorEl == null) setAnchorEl(e.currentTarget);\n    setOpenFeeBreakdown(true);\n  };\n\n  return (\n    <Box\n      onMouseEnter={openPopper}\n      onMouseLeave={() => setOpenFeeBreakdown(false)}\n      onFocusCapture={openPopper}\n    >\n      <IconButton icon={<InfoIcon />} size=\"s\" variant=\"invisible\" />\n      <FeeBreakdownPopper anchorEl={anchorEl} open={openFeeBreakdown} />\n    </Box>\n  );\n};\n","import {\n  SectionContent,\n  SectionDataRow,\n  DataRowValueWithDetail,\n} from '@finmid/tbl-webapps/components';\nimport { useFormat } from '@finmid/translations';\nimport { Badge } from '@finmid/ui/ocarina';\nimport { Stack } from '@mui/material';\nimport Box from '@mui/material/Box';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { FeeFormulaDialog } from '../../../../../../../../../components';\nimport { useUseCaseCopy } from '../../../../../../../../../shared';\nimport { usePaymentRequestSidebarPayload } from '../../../../PaymentRequestDetailsSidebar.context';\n\nimport { FeeBreakdownIconButton } from './components';\n\nexport const DetailsTab = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'details' });\n  const { title: useCaseTitle } = useUseCaseCopy();\n  const { money, dateDots } = useFormat();\n  const { paymentRequest, seller } = usePaymentRequestSidebarPayload();\n\n  const [feeFormulaDialogOpen, setFeeFormulaDialogOpen] = useState(false);\n\n  return (\n    <Box>\n      <SectionContent disablePadding>\n        <SectionDataRow\n          label={t('useCase')}\n          css={{ padding: 16 }}\n          testId=\"details-use-case\"\n        >\n          {useCaseTitle(paymentRequest.useCase)}\n        </SectionDataRow>\n        <SectionDataRow\n          label={t('amount')}\n          css={{ padding: 16 }}\n          testId=\"details-total-amount\"\n        >\n          <Box display=\"flex\" justifyContent=\"flex-end\" gap={0.5}>\n            {money(paymentRequest.totalAmount, paymentRequest.currency)}\n            <FeeBreakdownIconButton />\n          </Box>\n        </SectionDataRow>\n        <SectionDataRow\n          label={t('amountPaidOut')}\n          css={{ padding: 16 }}\n          testId=\"details-paidout-amout\"\n        >\n          {money(paymentRequest.amountPaidOut, paymentRequest.currency)}\n        </SectionDataRow>\n        <SectionDataRow\n          label={\n            <Stack alignItems=\"center\" direction=\"row\" gap={1}>\n              <span>{t('financeableToday')}</span>\n              <Badge\n                label={`${paymentRequest.financingPortion}%`}\n                variant=\"neutral\"\n              />\n            </Stack>\n          }\n          css={{ padding: 16 }}\n          testId=\"details-financeable-today\"\n        >\n          {money(paymentRequest.maxFinancingAmount, paymentRequest.currency)}\n        </SectionDataRow>\n        <SectionDataRow\n          label={\n            <Stack alignItems=\"center\" direction=\"row\" gap={1}>\n              <span>{t('totalFee')}</span>\n              <Badge\n                label={`${paymentRequest.amountsBreakdown.fees.totalFeePercentage}%`}\n                variant=\"neutral\"\n              />\n            </Stack>\n          }\n          css={{ padding: 16 }}\n          testId=\"details-total-fee\"\n        >\n          {paymentRequest.amountsBreakdown.fees.totalFeeAmount ? (\n            money(\n              paymentRequest.amountsBreakdown.fees.totalFeeAmount,\n              paymentRequest.currency,\n            )\n          ) : (\n            <Badge label={t('pending')} variant=\"neutral\" />\n          )}\n        </SectionDataRow>\n        <SectionDataRow\n          label={t('invoiceNumber')}\n          css={{ padding: 16 }}\n          testId=\"details-invoice-number\"\n        >\n          {paymentRequest.invoiceNumber ?? (\n            <Badge label={t('pending')} variant=\"neutral\" />\n          )}\n        </SectionDataRow>\n        <SectionDataRow\n          label={t('date')}\n          css={{ padding: 16 }}\n          testId=\"details-creation-time\"\n          data-date={paymentRequest.creationTime.split('T')[0].toString()}\n        >\n          {dateDots(new Date(paymentRequest.creationTime))}\n        </SectionDataRow>\n        <SectionDataRow\n          label={t('invoiceDueDate')}\n          css={{ padding: 16 }}\n          testId=\"details-invoice-due-date\"\n          data-date={paymentRequest.invoiceDueDate?.toString()}\n        >\n          {paymentRequest.invoiceDueDate ? (\n            dateDots(new Date(paymentRequest.invoiceDueDate))\n          ) : (\n            <Badge label={t('pending')} variant=\"neutral\" />\n          )}\n        </SectionDataRow>\n        <SectionDataRow\n          label={t('buyer')}\n          css={{ padding: 16 }}\n          testId=\"details-buyer\"\n        >\n          <DataRowValueWithDetail\n            value={paymentRequest.buyerName}\n            detail={paymentRequest.buyerId}\n          />\n        </SectionDataRow>\n        <SectionDataRow\n          label={t('seller')}\n          css={{ padding: 16 }}\n          testId=\"details-seller\"\n        >\n          <DataRowValueWithDetail\n            value={seller?.legalName ?? '-'}\n            detail={seller?.externalId ?? '-'}\n          />\n        </SectionDataRow>\n      </SectionContent>\n\n      <FeeFormulaDialog\n        open={feeFormulaDialogOpen}\n        onClose={() => setFeeFormulaDialogOpen(false)}\n      />\n    </Box>\n  );\n};\n","import { Typography } from '@finmid/tbl-webapps/components';\nimport { useTranslation } from 'react-i18next';\n\nexport const DocumentsSectionTitle = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'details' });\n  return (\n    <Typography fontSize={15} lineHeight=\"20px\" fontWeight={700}>\n      {t('documentsSection')}\n    </Typography>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport {\n  ErrorBoundary,\n  LazyLoadFallback,\n  Typography,\n} from '@finmid/tbl-webapps/components';\nimport { DocumentIcon } from '@finmid/ui/icons';\nimport { Button, Icon, Loader, PlusIcon, Spacer } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { Suspense } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { usePaymentRequestSidebarPayload } from '../../../../../../PaymentRequestDetailsSidebar.context';\nimport { DocumentsSectionTitle } from '../DocumentsSectionTitle';\n\ntype AddDocumentsSectionProps = {\n  navigateToUploadPage: () => void;\n};\n\nexport const AddDocumentsSection = ({\n  navigateToUploadPage,\n}: AddDocumentsSectionProps) => {\n  const {\n    logEntries,\n    paymentRequest: { status },\n  } = usePaymentRequestSidebarPayload();\n  const theme = useTheme();\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'documentUpload' });\n  const latestLog = logEntries[0];\n  const isPendingDocuments =\n    latestLog.statusCategory === 'TASK' && latestLog.status === 'PENDING';\n\n  if (status === 'PENDING' || status === 'PROCESSING') {\n    return (\n      <ErrorBoundary fallback={<LazyLoadFallback />}>\n        <Suspense fallback={<Loader />}>\n          <Box mx={2} mt={1} mb={0.5}>\n            <DocumentsSectionTitle />\n          </Box>\n\n          <Box\n            padding={4}\n            mx={0.5}\n            display=\"flex\"\n            flexDirection=\"column\"\n            alignItems=\"center\"\n            bgcolor=\"white\"\n            borderRadius={3}\n            border={`1px solid ${theme.glo.color.foundations[20]}`}\n          >\n            <Box\n              border={`1px solid ${theme.glo.color.foundations[20]}`}\n              borderRadius={1}\n              position=\"relative\"\n            >\n              <Icon\n                icon={<DocumentIcon />}\n                style={{ width: '36px', height: '36px' }}\n              />\n              <Box\n                data-test-id=\"badge-doc\"\n                position=\"absolute\"\n                top={0}\n                right={0}\n                sx={{\n                  transform: `translate3d(50%, -50%, 0)`,\n                }}\n                bgcolor={theme.glo.color.roles.danger[60]}\n                width=\"8px\"\n                height=\"8px\"\n                borderRadius={8}\n              />\n            </Box>\n            <Spacer height={1} />\n            <Typography fontSize={13} fontWeight={700} lineHeight=\"16px\">\n              {isPendingDocuments\n                ? t('documentsRequired')\n                : t('documentsNotRequired')}\n            </Typography>\n            <Spacer height={0.5} />\n            <Typography\n              fontSize={13}\n              fontWeight={500}\n              lineHeight=\"16px\"\n              maxWidth=\"305px\"\n              display=\"inline-block\"\n              textAlign=\"center\"\n            >\n              {isPendingDocuments\n                ? t('documentsRequiredDesc')\n                : t('documentsNotRequiredDesc')}\n            </Typography>\n            <Spacer height={2} />\n            <Button\n              prefixIcon={<PlusIcon />}\n              variant=\"invisible\"\n              onClick={navigateToUploadPage}\n              size=\"s\"\n            >\n              {t('navigateToUploadPage')}\n            </Button>\n          </Box>\n        </Suspense>\n      </ErrorBoundary>\n    );\n  }\n\n  return null;\n};\n","import { useTheme } from '@emotion/react';\nimport { GetPaymentRequestDocuments } from '@finmid/distributor-types';\nimport { humanReadableFileSize } from '@finmid/tbl-webapps/utils';\nimport { DocumentIcon, Icon } from '@finmid/ui/ocarina';\nimport { Box, Typography } from '@mui/material';\nimport { GridColDef, GridRenderCellParams } from '@mui/x-data-grid';\nimport { useMemo } from 'react';\n\nconst getFileType = (documentName: string) => {\n  const [, fileType] = documentName.split('.');\n  return (fileType ?? '').toUpperCase();\n};\n\nexport const useUploadedDocumentsColumns = (): GridColDef[] => {\n  const theme = useTheme();\n\n  return useMemo(\n    () => [\n      {\n        field: 'document',\n        headerName: 'Document',\n        sortable: false,\n        flex: 1,\n        renderCell: ({\n          row: { documentName, documentSize },\n        }: GridRenderCellParams<\n          GetPaymentRequestDocuments.GatewayResponse['documents'][number]\n        >) => {\n          return (\n            <Box\n              display=\"grid\"\n              alignItems=\"center\"\n              gap={1}\n              gridTemplateColumns=\"20px 1fr 120px\"\n              width=\"100%\"\n            >\n              <Icon\n                icon={<DocumentIcon />}\n                style={{ width: '20px', height: '20px' }}\n              />\n              <Typography\n                fontSize={15}\n                fontWeight={700}\n                lineHeight=\"20px\"\n                textOverflow=\"ellipsis\"\n                whiteSpace=\"nowrap\"\n                overflow=\"hidden\"\n              >\n                {documentName}\n              </Typography>\n              <Typography\n                fontSize={15}\n                lineHeight=\"20px\"\n                color={theme.glo.color.foundations[60]}\n              >\n                {getFileType(documentName)}\n                &ensp;•&ensp;\n                {humanReadableFileSize(documentSize)}\n              </Typography>\n            </Box>\n          );\n        },\n      },\n    ],\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [],\n  );\n};\n","import { GetPaymentRequestDocuments } from '@finmid/distributor-types';\nimport {\n  ErrorBoundary,\n  LazyLoadFallback,\n} from '@finmid/tbl-webapps/components';\nimport { IconButton, Loader, PlusIcon } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { lazy, Suspense } from 'react';\n\nimport { usePaymentRequestSidebarPayload } from '../../../../../../PaymentRequestDetailsSidebar.context';\nimport { DocumentsSectionTitle } from '../DocumentsSectionTitle';\n\nimport { useUploadedDocumentsColumns } from './useUploadedDocumentsColumns';\n\nconst DataGrid = lazy(() => import('@finmid/tbl-webapps/components/DataGrid'));\nconst ROW_HEIGHT = 56;\n\ntype UploadedDocumentsSectionProps = {\n  uploadedDocuments: GetPaymentRequestDocuments.GatewayResponse['documents'];\n  navigateToUploadPage: () => void;\n};\n\nexport const UploadedDocumentsSection = ({\n  uploadedDocuments,\n  navigateToUploadPage,\n}: UploadedDocumentsSectionProps) => {\n  const columns = useUploadedDocumentsColumns();\n  const {\n    paymentRequest: { status },\n  } = usePaymentRequestSidebarPayload();\n\n  const canAddDocuments = status === 'PENDING' || status === 'PROCESSING';\n\n  return (\n    <ErrorBoundary fallback={<LazyLoadFallback />}>\n      <Suspense fallback={<Loader />}>\n        <Box\n          display=\"flex\"\n          justifyContent=\"space-between\"\n          alignItems=\"center\"\n          mx={2}\n          mt={1}\n          mb={0.5}\n        >\n          <DocumentsSectionTitle />\n          {canAddDocuments ? (\n            <IconButton\n              size=\"s\"\n              variant=\"invisible\"\n              icon={<PlusIcon />}\n              onClick={navigateToUploadPage}\n            />\n          ) : null}\n        </Box>\n        <Box\n          display=\"flex\"\n          flexDirection=\"column\"\n          alignItems=\"flex-start\"\n          justifyContent=\"flex-start\"\n          data-test-id=\"uploaded-documents\"\n          mx={0.5}\n        >\n          <DataGrid\n            rowHeight={ROW_HEIGHT}\n            columns={columns}\n            rows={uploadedDocuments}\n            getRowId={(row) => row.documentId}\n            disableColumnMenu\n            disableColumnSorting\n            hideFooter\n            autoHeight\n            sx={{\n              '--DataGrid-overlayHeight': `${ROW_HEIGHT}px`,\n            }}\n          />\n        </Box>\n      </Suspense>\n    </ErrorBoundary>\n  );\n};\n","import { useNavigate } from 'react-router-dom';\n\nimport { usePaymentRequestSidebarPayload } from '../../../../PaymentRequestDetailsSidebar.context';\n\nimport { AddDocumentsSection, UploadedDocumentsSection } from './components';\n\nexport const DocumentsSection = () => {\n  const { paymentRequest, uploadedDocuments } =\n    usePaymentRequestSidebarPayload();\n  const navigate = useNavigate();\n\n  const navigateToUploadPage = () => {\n    navigate(`/invoices/${paymentRequest.id}/upload`);\n  };\n\n  if (uploadedDocuments.length > 0) {\n    return (\n      <UploadedDocumentsSection\n        uploadedDocuments={uploadedDocuments}\n        navigateToUploadPage={navigateToUploadPage}\n      />\n    );\n  }\n  return <AddDocumentsSection navigateToUploadPage={navigateToUploadPage} />;\n};\n","import {\n  GetPaymentRequest,\n  GetPaymentRequestPayouts,\n} from '@finmid/distributor-types';\nimport { differenceInCalendarDays } from 'date-fns';\n\nconst checkIfFullyPaidOut = (\n  payouts: GetPaymentRequestPayouts.GatewayResponse,\n) => {\n  if (payouts.length === 0) return false;\n  const sumOfPayouts = payouts.reduce((acc, current) => {\n    acc += current.percentageGross;\n    return acc;\n  }, 0);\n  return sumOfPayouts === 100;\n};\n\ntype CanCreatePayoutProps = {\n  paymentRequest: GetPaymentRequest.GatewayResponse;\n  payouts: GetPaymentRequestPayouts.GatewayResponse;\n};\n\nexport const checkCanCreatePayout = ({\n  paymentRequest,\n  payouts,\n}: CanCreatePayoutProps) => {\n  const { invoiceDueDate, status } = paymentRequest;\n  const paymentRequestIsOpen = status === 'PENDING' || status === 'PROCESSING';\n  const isFullyPaidOut = checkIfFullyPaidOut(payouts);\n  const payoutInProcess =\n    payouts.length > 0 && payouts[0].status !== 'PAID_OUT';\n  const isWithinInvoiceDueDateLimit =\n    invoiceDueDate != null &&\n    differenceInCalendarDays(new Date(invoiceDueDate), new Date()) >= 3; // min threshold time to create payout\n\n  const canCreatePayout =\n    paymentRequestIsOpen &&\n    !isFullyPaidOut &&\n    !payoutInProcess &&\n    (isWithinInvoiceDueDateLimit || invoiceDueDate == null);\n\n  return canCreatePayout;\n};\n","import { useTheme } from '@emotion/react';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { Button, MoneyIcon, Icon, PlusIcon, Spacer } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { useTranslation } from 'react-i18next';\n\nimport { usePaymentRequestSidebarPayload } from '../../../../PaymentRequestDetailsSidebar.context';\nimport { checkCanCreatePayout } from '../../../../utils';\n\nconst CreatePayoutContent = () => {\n  const { t } = useTranslation('invoicesPage');\n  const { setIsPayoutDialogOpen } = usePaymentRequestSidebarPayload();\n\n  const handleOpenCreatePayoutModal = () => {\n    setIsPayoutDialogOpen(true);\n  };\n\n  return (\n    <>\n      <Spacer height={0.5} />\n      <Typography\n        fontSize={13}\n        fontWeight={500}\n        lineHeight=\"16px\"\n        display=\"inline-block\"\n        textAlign=\"center\"\n      >\n        {t('details.noPayoutsDescription')}\n      </Typography>\n      <Spacer height={2} />\n      <Button\n        prefixIcon={<PlusIcon />}\n        variant=\"invisible\"\n        onClick={handleOpenCreatePayoutModal}\n        size=\"s\"\n      >\n        {t('payoutsTable.toolbar.createPayoutButton')}\n      </Button>\n    </>\n  );\n};\n\nexport const EmptyPayouts = () => {\n  const theme = useTheme();\n  const { t } = useTranslation('invoicesPage');\n  const { paymentRequest, payouts } = usePaymentRequestSidebarPayload();\n  const canCreatePayout = checkCanCreatePayout({ paymentRequest, payouts });\n\n  return (\n    <Box\n      padding={4}\n      display=\"flex\"\n      flexDirection=\"column\"\n      alignItems=\"center\"\n      bgcolor=\"white\"\n      borderRadius={3}\n      mx={0.5}\n      border={`1px solid ${theme.glo.color.foundations[20]}`}\n    >\n      <Box\n        border={`1px solid ${theme.glo.color.foundations[20]}`}\n        borderRadius={1}\n        position=\"relative\"\n        width={36}\n        height={36}\n        display=\"flex\"\n        justifyContent=\"center\"\n        alignItems=\"center\"\n      >\n        <Icon icon={<MoneyIcon />} style={{ width: '22px', height: '22px' }} />\n        <Box\n          data-test-id=\"badge-doc\"\n          position=\"absolute\"\n          top={0}\n          right={0}\n          sx={{\n            transform: `translate3d(50%, -50%, 0)`,\n          }}\n          bgcolor={theme.glo.color.roles.danger[60]}\n          width=\"8px\"\n          height=\"8px\"\n          borderRadius={8}\n        />\n      </Box>\n      <Spacer height={1} />\n      <Typography fontSize={13} fontWeight={700} lineHeight=\"16px\">\n        {t('details.noPayoutsTitle')}\n      </Typography>\n      {canCreatePayout ? <CreatePayoutContent /> : null}\n    </Box>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport {\n  GetPaymentRequestPayouts,\n  TBLCurrency,\n} from '@finmid/distributor-types';\nimport { Divider, Typography } from '@finmid/tbl-webapps/components';\nimport { useFormat } from '@finmid/translations';\nimport { ElevatedPaper, Popper, Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport Fade from '@mui/material/Fade';\nimport currencyjs from 'currency.js';\nimport { useTranslation } from 'react-i18next';\n\nconst labelProps = {\n  fontSize: 13,\n  lineHeight: '16px',\n  fontWeight: 500,\n};\n\nconst valueProps = {\n  fontSize: 15,\n  lineHeight: '20px',\n  fontWeight: 400,\n  numeric: true,\n};\n\nconst Row = styled(Box)({\n  display: 'flex',\n  alignItems: 'baseline',\n  '> :last-child': {\n    flex: 1,\n    textAlign: 'right',\n  },\n});\n\ntype FeeBreakdownPopperProps = {\n  anchorEl: HTMLDivElement | null;\n  currency: TBLCurrency;\n  open: boolean;\n  row: GetPaymentRequestPayouts.SinglePayout;\n};\n\nexport const PayoutBreakdownPopper = ({\n  anchorEl,\n  currency,\n  open,\n  row,\n}: FeeBreakdownPopperProps) => {\n  const theme = useTheme();\n  const { money } = useFormat();\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createPayout' });\n  const { grossAmount, percentageGross, netAmount } = row;\n  const fee = currencyjs(grossAmount).subtract(currencyjs(netAmount));\n\n  return (\n    <Popper\n      open={open}\n      anchorEl={anchorEl}\n      transition\n      placement=\"top\"\n      css={{ zIndex: 1201 }}\n    >\n      {({ TransitionProps }) => (\n        <Fade {...TransitionProps} timeout={350}>\n          <ElevatedPaper css={{ padding: 16, width: 336 }}>\n            <Row>\n              <Typography\n                color={theme.glo.color.foundations[60]}\n                {...labelProps}\n              >\n                {t('grossAmount')}\n              </Typography>\n              <Typography {...valueProps}>\n                {`${money(grossAmount, currency)} (${percentageGross}%)`}\n              </Typography>\n            </Row>\n            <Spacer height={1} />\n            <Row>\n              <Typography\n                color={theme.glo.color.foundations[60]}\n                {...labelProps}\n              >\n                {t('fee')}\n              </Typography>\n              <Typography {...valueProps}>\n                {`-${money(Number(fee), currency)}`}\n              </Typography>\n            </Row>\n            <Spacer height={2} />\n            <Divider />\n            <Spacer height={2} />\n            <Row>\n              <Typography {...labelProps} fontWeight={700}>\n                {t('netAmount')}\n              </Typography>\n              <Typography {...valueProps} fontWeight={700}>\n                {money(netAmount, currency)}\n              </Typography>\n            </Row>\n          </ElevatedPaper>\n        </Fade>\n      )}\n    </Popper>\n  );\n};\n","import {\n  GetPaymentRequestPayouts,\n  TBLCurrency,\n} from '@finmid/distributor-types';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { useFormat } from '@finmid/translations';\nimport { IconButton, InfoIcon } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport currencyjs from 'currency.js';\nimport { FocusEvent, MouseEvent, useState } from 'react';\n\nimport { PayoutBreakdownPopper } from './PayoutBreakdownPopper';\n\ntype PayoutAmountCellProps = {\n  currency: TBLCurrency;\n  row: GetPaymentRequestPayouts.SinglePayout;\n};\n\nexport const PayoutAmountCell = ({ currency, row }: PayoutAmountCellProps) => {\n  const { money } = useFormat();\n  const [anchorEl, setAnchorEl] = useState<null | HTMLDivElement>(null);\n  const [open, setOpen] = useState(false);\n  const { netAmount } = row;\n\n  const openPopper = (\n    e: MouseEvent<HTMLDivElement> | FocusEvent<HTMLDivElement>,\n  ) => {\n    if (anchorEl == null) setAnchorEl(e.currentTarget);\n    setOpen(true);\n  };\n\n  return (\n    <Box display=\"flex\" alignItems=\"center\" gap={0.5}>\n      <Typography fontSize={15}>\n        {money(currencyjs(netAmount ?? '').value, currency)}\n      </Typography>\n      <Box\n        onMouseEnter={openPopper}\n        onMouseLeave={() => setOpen(false)}\n        onFocusCapture={openPopper}\n      >\n        <IconButton icon={<InfoIcon />} size=\"s\" variant=\"invisible\" />\n        <PayoutBreakdownPopper\n          anchorEl={anchorEl}\n          currency={currency}\n          open={open}\n          row={row}\n        />\n      </Box>\n    </Box>\n  );\n};\n","import {\n  GetPaymentRequestPayouts,\n  TBLCurrency,\n} from '@finmid/distributor-types';\nimport { useFormat } from '@finmid/translations';\nimport { GridColDef, GridRenderCellParams } from '@mui/x-data-grid';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { PayoutStatusIndicator } from '../../../../../../../../../shared';\n\nimport { PayoutAmountCell } from './PayoutAmountCell';\n\ntype UsePayoutsColumnsArgs = {\n  currency: TBLCurrency;\n};\n\nexport const usePayoutsColumn = ({\n  currency,\n}: UsePayoutsColumnsArgs): GridColDef[] => {\n  const { date } = useFormat();\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createPayout' });\n\n  return useMemo(\n    () => [\n      {\n        field: 'netAmount',\n        headerName: t('netAmount'),\n        sortable: false,\n        flex: 1,\n        editable: true,\n        renderCell: ({\n          row,\n        }: GridRenderCellParams<GetPaymentRequestPayouts.SinglePayout>) => (\n          <PayoutAmountCell row={row} currency={currency} />\n        ),\n      },\n      {\n        field: 'creationTime',\n        headerName: t('date'),\n        sortable: false,\n        minWidth: 120,\n        renderCell: ({\n          row: { creationTime },\n        }: GridRenderCellParams<GetPaymentRequestPayouts.SinglePayout>) =>\n          date(new Date(creationTime)),\n      },\n      {\n        field: 'status',\n        headerName: t('status'),\n        width: 100,\n        sortable: false,\n        headerAlign: 'center',\n        align: 'center',\n        renderCell: ({\n          row: { status },\n        }: GridRenderCellParams<GetPaymentRequestPayouts.SinglePayout>) => (\n          <PayoutStatusIndicator status={status} tooltipPlacement=\"left\" />\n        ),\n      },\n    ],\n    [currency, t, date],\n  );\n};\n","import { Button, PlusIcon } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport posthog from 'posthog-js';\nimport { lazy } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { usePaymentRequestSidebarPayload } from '../../../../PaymentRequestDetailsSidebar.context';\nimport { checkCanCreatePayout } from '../../../../utils';\n\nimport { usePayoutsColumn } from './usePayoutsColumns';\n\nconst DataGrid = lazy(() => import('@finmid/tbl-webapps/components/DataGrid'));\n\nconst ROW_HEIGHT = 56;\n\nconst PayoutsTableFooter = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createPayout' });\n  const { setIsPayoutDialogOpen } = usePaymentRequestSidebarPayload();\n\n  return (\n    <Box\n      sx={({ spacing }) => ({\n        borderTop: '1px solid #E0E0E0',\n        background: '#FFF',\n        borderRadius: '0 0 12px 12px',\n        padding: spacing(1),\n        backgroundColor: 'white',\n      })}\n    >\n      <Button\n        variant=\"invisible\"\n        prefixIcon={<PlusIcon />}\n        onClick={() => {\n          posthog.capture('clicked-sidebar-add-payout');\n          setIsPayoutDialogOpen(true);\n        }}\n        size=\"s\"\n      >\n        {t('add')}\n      </Button>\n    </Box>\n  );\n};\n\nexport const PayoutsTable = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'payoutsTable' });\n  const { paymentRequest, payouts } = usePaymentRequestSidebarPayload();\n  const columns = usePayoutsColumn({ currency: paymentRequest.currency });\n  const canCreatePayout = checkCanCreatePayout({ paymentRequest, payouts });\n  const footerSlot = canCreatePayout ? { footer: PayoutsTableFooter } : null;\n\n  return (\n    <Box\n      display=\"flex\"\n      flexDirection=\"column\"\n      alignItems=\"flex-start\"\n      justifyContent=\"flex-start\"\n      px={0.5}\n      data-test-id=\"tabs-payout-table\"\n    >\n      <DataGrid\n        rowHeight={ROW_HEIGHT}\n        editMode=\"row\"\n        columns={columns}\n        rows={payouts ?? []}\n        getRowId={(row) => row.internalId}\n        initialState={{\n          sorting: {\n            sortModel: [{ field: 'creationTime', sort: 'desc' }],\n          },\n        }}\n        localeText={{ noRowsLabel: t('emptyState') }}\n        disableColumnMenu\n        disableColumnSorting\n        hideNumberColumn\n        autoHeight\n        hideFooter={!canCreatePayout}\n        sx={{\n          '--DataGrid-overlayHeight': `${ROW_HEIGHT}px`,\n        }}\n        style={{ borderRadius: 12 }}\n        slots={{\n          ...footerSlot,\n        }}\n      />\n    </Box>\n  );\n};\n","import {\n  ErrorBoundary,\n  LazyLoadFallback,\n} from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { Suspense } from 'react';\n\nimport { usePaymentRequestSidebarPayload } from '../../../../PaymentRequestDetailsSidebar.context';\n\nimport { EmptyPayouts } from './EmptyPayouts';\nimport { PayoutsTable } from './PayoutsTable';\n\nexport const PayoutsTab = () => {\n  const { payouts } = usePaymentRequestSidebarPayload();\n\n  const hasPayouts = payouts.length > 0;\n\n  return (\n    <ErrorBoundary fallback={<LazyLoadFallback />}>\n      <Suspense fallback={<Loader />}>\n        {hasPayouts ? <PayoutsTable /> : <EmptyPayouts />}\n      </Suspense>\n    </ErrorBoundary>\n  );\n};\n","import { SectionContainer } from '@finmid/tbl-webapps/components';\nimport Box from '@mui/material/Box';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { ButtonsTabs } from '../../../../../../../components';\n\nimport { DetailsTab, DocumentsSection, PayoutsTab } from './components';\n\ntype Tab = 'DETAILS' | 'PAYOUTS';\n\nexport const DetailsAndDocuments = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'details' });\n  const [tab, setTab] = useState<Tab>('DETAILS');\n\n  const buttons = [\n    {\n      label: t('detailsSection'),\n      onClick: () => setTab('DETAILS'),\n      testId: 'tab-details',\n    },\n    {\n      label: t('payoutsSection'),\n      onClick: () => setTab('PAYOUTS'),\n      testId: 'tab-payouts',\n    },\n  ];\n\n  if (tab === 'DETAILS') {\n    return (\n      <SectionContainer className=\"section-container\">\n        <Box mx={0.5}>\n          <ButtonsTabs fullWidth buttons={buttons} />\n        </Box>\n        <DetailsTab />\n        <DocumentsSection />\n      </SectionContainer>\n    );\n  }\n\n  if (tab === 'PAYOUTS') {\n    return (\n      <SectionContainer className=\"section-container\">\n        <Box mx={0.5}>\n          <ButtonsTabs fullWidth buttons={buttons} />\n        </Box>\n        <PayoutsTab />\n      </SectionContainer>\n    );\n  }\n\n  return null;\n};\n","import { ActivityLog } from '@finmid/distributor-types';\nimport { BadgeVariant } from '@finmid/ui/ocarina';\nimport { endOfDay, isAfter, isSameDay } from 'date-fns';\nimport { useTranslation } from 'react-i18next';\n\nimport { ActivityLogKey } from '../../../../../../../../shared';\nimport { usePaymentRequestSidebarPayload } from '../../../PaymentRequestDetailsSidebar.context';\n\nconst compareDatesWithToday = (eventDate: string) => {\n  const today = endOfDay(new Date());\n  const eventDay = endOfDay(new Date(eventDate));\n  const isToday = isSameDay(eventDay, today);\n  const isInTheFuture = isAfter(eventDay, today);\n\n  return {\n    isInTheFuture,\n    isToday,\n  };\n};\n\nexport const useActivityLogVariant = (log: ActivityLog) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'activity' });\n  const { isMaxPayout } = usePaymentRequestSidebarPayload();\n\n  let i18nKey: ActivityLogKey | '' = '';\n  let badgeProps: { label: string; variant: BadgeVariant } = {\n    label: '',\n    variant: 'neutral',\n  };\n  let action: 'CREATE_PAYOUT' | 'ADD_DOCUMENTS' | null = null;\n\n  if (log.statusCategory === 'PAYMENT_REQUEST') {\n    switch (log.status) {\n      case 'PENDING':\n        action = 'CREATE_PAYOUT';\n        i18nKey = 'paymentRequestPending';\n        badgeProps = {\n          label: t('badgePaymentRequestPending'),\n          variant: 'neutral',\n        };\n        break;\n\n      case 'PROCESSING':\n        i18nKey = 'paymentRequestProcessing'; // should not happen - keeping just in case\n        badgeProps = {\n          label: t('badgePaymentRequestProcessing'),\n          variant: 'running',\n        };\n        break;\n\n      case 'PENDING_REPAYMENT':\n        i18nKey = 'paymentRequestPendingRepayment';\n        badgeProps = {\n          label: t('badgePaymentRequestPendingRepayment'),\n          variant: 'alert',\n        };\n        break;\n\n      case 'CANCELLED':\n        i18nKey = 'paymentRequestCancelled';\n        badgeProps = {\n          label: t('badgePaymentRequestCancelled'),\n          variant: 'trivial',\n        };\n        break;\n\n      case 'CLOSED':\n        i18nKey = 'paymentRequestClosed';\n        badgeProps = {\n          label: t('badgePaymentRequestClosed'),\n          variant: 'success',\n        };\n        break;\n\n      case 'DEFAULT':\n        i18nKey = 'paymentRequestDefaulted';\n        badgeProps = {\n          label: t('badgePaymentRequestDefaulted'),\n          variant: 'danger',\n        };\n        break;\n    }\n  }\n\n  if (log.statusCategory === 'PAYOUT_DETAILS') {\n    switch (log.status) {\n      case 'CREATED':\n        i18nKey = isMaxPayout ? 'maxPayoutCreated' : 'partialPayoutCreated';\n        badgeProps = { label: t('badgePayoutCreated'), variant: 'running' };\n        break;\n      case 'REJECTED':\n        i18nKey = 'payoutRejected';\n        badgeProps = { label: t('badgePayoutRejected'), variant: 'danger' };\n        break;\n      case 'AUTHORIZED':\n        i18nKey = 'payoutAuthorized';\n        badgeProps = { label: t('badgePayoutPaidout'), variant: 'success' };\n        break;\n      case 'IN_TRANSIT':\n        i18nKey = 'payoutInTransit';\n        badgeProps = { label: t('badgePayoutPaidout'), variant: 'success' };\n        break;\n      case 'PAYOUT':\n        i18nKey = 'payoutPayout';\n        badgeProps = { label: t('badgePayoutPaidout'), variant: 'success' };\n        break;\n      case 'PAYOUT_ARRIVAL': {\n        const { isInTheFuture, isToday } = compareDatesWithToday(log.timestamp);\n        if (isInTheFuture || isToday) {\n          i18nKey = 'payoutArrivalSoon';\n        } else {\n          i18nKey = 'payoutArrivalPast';\n        }\n        badgeProps = { label: t('badgePayoutPaidout'), variant: 'success' };\n        break;\n      }\n      // case 'TRACKING':\n      // unhandled for now\n    }\n  }\n\n  if (log.statusCategory === 'TASK') {\n    switch (log.status) {\n      case 'PENDING':\n        action = 'ADD_DOCUMENTS';\n        i18nKey = 'taskAddDocuments';\n        badgeProps = {\n          label: t('badgeTaskMissingDocuments'),\n          variant: 'alert',\n        };\n        break;\n      case 'COMPLETED':\n        i18nKey = 'taskReceivedDocuments';\n        badgeProps = { label: t('badgePayoutCreated'), variant: 'running' };\n        break;\n    }\n  }\n\n  return {\n    action,\n    badgeProps,\n    i18nKey,\n  };\n};\n","import { Button, Spacer } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { usePaymentRequestSidebarPayload } from '../../../../../../PaymentRequestDetailsSidebar.context';\n\nexport const AddDocumentsButton = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'activity' });\n\n  const navigate = useNavigate();\n  const { paymentRequest, logEntries } = usePaymentRequestSidebarPayload();\n\n  const [latestLog] = logEntries;\n\n  const expectingDocument =\n    latestLog.statusCategory === 'TASK' &&\n    latestLog.taskType === 'DOCUMENTS_REQUIRED' &&\n    latestLog.status === 'PENDING';\n\n  const handleClick = () => navigate(`/invoices/${paymentRequest.id}/upload`);\n\n  if (!expectingDocument) {\n    return null;\n  }\n\n  return (\n    <>\n      <Spacer height={3} />\n      <Button onClick={handleClick} data-test-id=\"add-docs-btn\">\n        {t('addDocuments')}\n      </Button>\n    </>\n  );\n};\n","import { Button, Spacer } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport { usePaymentRequestSidebarPayload } from '../../../../../../PaymentRequestDetailsSidebar.context';\nimport { checkCanCreatePayout } from '../../../../../../utils';\n\nexport const CreatePayoutButton = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'activity' });\n\n  const { paymentRequest, payouts, setIsPayoutDialogOpen } =\n    usePaymentRequestSidebarPayload();\n\n  const canCreatePayout = checkCanCreatePayout({ paymentRequest, payouts });\n  if (!canCreatePayout) {\n    return null;\n  }\n\n  return (\n    <>\n      <Spacer height={3} />\n      <Button\n        onClick={() => setIsPayoutDialogOpen(true)}\n        data-test-id=\"create-payout-btn\"\n      >\n        {t('createPayout')}\n      </Button>\n    </>\n  );\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { Dialog, withErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useSimulateClosePaymentRequestMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { Button, Spacer } from '@finmid/ui/ocarina';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { PaymentRequestStatusTag } from '../../../../../../../../../../../components';\nimport { usePaymentRequestSidebarPayload } from '../../../../../../PaymentRequestDetailsSidebar.context';\n\nexport const SimulateRepaymentButton = () => {\n  const [open, setOpen] = useState(false);\n  const { notifySuccess } = useNotifications();\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'captureInvoice' });\n  const { t: tComponents } = useTranslation('components', {\n    keyPrefix: 'dangerZoneDialog',\n  });\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const [simulateRepayment, { isLoading }] =\n    useSimulateClosePaymentRequestMutation();\n\n  const {\n    paymentRequest: { id, status },\n    payouts,\n  } = usePaymentRequestSidebarPayload();\n\n  const canSimulateRepayment =\n    ENVIRONMENT !== 'live' &&\n    status === 'PENDING_REPAYMENT' &&\n    payouts.every((payout) => payout.status === 'PAID_OUT');\n\n  if (!canSimulateRepayment) {\n    return null;\n  }\n\n  const handleSimulateRepayment = async () => {\n    try {\n      await simulateRepayment(id).unwrap();\n      posthog.capture('clicked_simulate_repayment');\n      notifySuccess(t('simulateRepaymentSuccess', { paymentRequestId: id }));\n    } catch (error) {\n      displayErrorToast(withErrorProps({ ...(error as Error) }));\n    }\n  };\n\n  const actions = [\n    <Button\n      disabled={isLoading}\n      onClick={handleSimulateRepayment}\n      data-test-id=\"dialog-submit-button\"\n      type=\"submit\"\n      key=\"submit-btn\"\n    >\n      {t('simulateRepaymentBtn')}\n    </Button>,\n    <Button\n      variant=\"invisible\"\n      onClick={() => setOpen(false)}\n      data-test-id=\"dialog-cancel-button\"\n      key=\"close-btn\"\n    >\n      {tComponents('cancel')}\n    </Button>,\n  ];\n\n  return (\n    <>\n      <Spacer height={3} />\n      <Button\n        onClick={() => setOpen(true)}\n        data-test-id=\"open-simulate-repayment-dialog-btn\"\n      >\n        {t('simulateRepayment')}\n      </Button>\n      <Dialog\n        open={open}\n        onClose={() => setOpen(false)}\n        fullWidth\n        actions={actions}\n        title={t('simulateRepayment')}\n      >\n        <Trans\n          t={t}\n          i18nKey=\"toClosed\"\n          components={[<PaymentRequestStatusTag status=\"CLOSED\" />]}\n        />\n      </Dialog>\n    </>\n  );\n};\n","import { AddDocumentsButton } from './AddDocumentsButton';\nimport { CreatePayoutButton } from './CreatePayoutButton';\nimport { SimulateRepaymentButton } from './SimulateRepaymentButton';\n\nexport const ActionButton = () => {\n  return (\n    <>\n      <AddDocumentsButton />\n      <CreatePayoutButton />\n      <SimulateRepaymentButton />\n    </>\n  );\n};\n","import { ActivityLog, GetPaymentRequest } from '@finmid/distributor-types';\nimport { currencySymbols } from '@finmid/tbl-webapps/utils';\n\nexport const getAmount = ({\n  log,\n  paymentRequest,\n}: {\n  log: ActivityLog;\n  paymentRequest: GetPaymentRequest.GatewayResponse;\n}) => {\n  if (log.statusCategory === 'PAYOUT_DETAILS') {\n    return `${currencySymbols[log.currency]} ${log.grossAmount.toFixed(2)}`;\n  }\n  if (log.statusCategory === 'PAYMENT_REQUEST') {\n    return `${\n      currencySymbols[paymentRequest.currency]\n    } ${paymentRequest.amountsBreakdown.grossFinancingAmount.toFixed(2)}`;\n  }\n};\n","type OrdinalPluralRule = 'one' | 'two' | 'few' | 'other';\n\nexport const formatOrdinalWithPluralRules = (number: number) => {\n  const pr = new Intl.PluralRules('en', { type: 'ordinal' });\n  const suffixes: Record<OrdinalPluralRule, string> = {\n    one: 'st',\n    two: 'nd',\n    few: 'rd',\n    other: 'th',\n  };\n  return number + suffixes[pr.select(number) as OrdinalPluralRule];\n};\n","import {\n  ActivityLog,\n  GetPaymentRequestPayouts,\n} from '@finmid/distributor-types';\n\nimport { formatOrdinalWithPluralRules } from './formatOrdinalWithPluralRules';\n\nexport const getPayoutNumber = (\n  payouts: GetPaymentRequestPayouts.GatewayResponse,\n  log: ActivityLog,\n) => {\n  try {\n    if (log.statusCategory === 'PAYOUT_DETAILS') {\n      const rank =\n        payouts.findIndex((payout) => payout.id === log.payoutId) + 1;\n      if (rank === 1) return 'first';\n      if (rank === 2) return 'second';\n      if (rank === 3) return 'third';\n      return formatOrdinalWithPluralRules(rank);\n    }\n  } catch {\n    //\n  }\n};\n","import { ActivityLog } from '@finmid/distributor-types';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { ActivityLogKey } from '../../../../../../../../../shared';\nimport { usePaymentRequestSidebarPayload } from '../../../../PaymentRequestDetailsSidebar.context';\n\nimport { getAmount, getPayoutNumber } from './utils';\n\ntype LogProps = {\n  i18nKey: ActivityLogKey;\n  log: ActivityLog;\n};\n\nexport const Log = ({ i18nKey, log }: LogProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'activity' });\n  const { paymentRequest, payouts, seller } = usePaymentRequestSidebarPayload();\n\n  const payoutNumber = getPayoutNumber(payouts, log);\n\n  return (\n    <Trans\n      t={t}\n      i18nKey={i18nKey}\n      components={{\n        span: <span style={{ fontWeight: 700 }} />,\n        a: <a href=\"mailto:support@finmid.com\">support@finmid.com</a>,\n      }}\n      values={{\n        amount: getAmount({ log, paymentRequest }),\n        payoutNumber,\n        seller: seller.legalName,\n      }}\n    />\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { ActivityLog } from '@finmid/distributor-types';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { useFormat } from '@finmid/translations';\nimport { Spacer } from '@finmid/ui/ocarina';\n\nimport { ActivityLogKey } from '../../../../../../../../../../../shared';\nimport { Log } from '../../../Log';\n\ntype LatestStatusInfoProps = {\n  latestLog: ActivityLog;\n  i18nKey: ActivityLogKey;\n};\n\nexport const LatestStatusInfo = ({\n  latestLog,\n  i18nKey,\n}: LatestStatusInfoProps) => {\n  const theme = useTheme();\n  const { dateAtTime } = useFormat();\n\n  return (\n    <>\n      <Typography fontSize={15} lineHeight=\"20px\">\n        <Log i18nKey={i18nKey} log={latestLog} />\n      </Typography>\n      <Spacer height={1} />\n      <Typography\n        fontSize={13}\n        lineHeight=\"16px\"\n        color={theme.glo.color.foundations[60]}\n      >\n        {dateAtTime(new Date(latestLog.timestamp))}\n      </Typography>\n    </>\n  );\n};\n","import { ActivityLog } from '@finmid/distributor-types';\nimport { Badge, Spacer } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\n\nimport { useActivityLogVariant } from '../../hooks';\n\nimport { ActionButton, LatestStatusInfo } from './components';\n\ntype LatestStatusProps = {\n  latestLog: ActivityLog;\n};\n\nexport const LatestStatus = ({ latestLog }: LatestStatusProps) => {\n  const { i18nKey, badgeProps } = useActivityLogVariant(latestLog);\n  return (\n    <Box padding={2}>\n      <Badge {...badgeProps} data-test-id=\"payment-request-status-badge\" />\n      <Spacer height={2} />\n      {i18nKey !== '' && (\n        <LatestStatusInfo latestLog={latestLog} i18nKey={i18nKey} />\n      )}\n      <ActionButton />\n    </Box>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { ActivityLog } from '@finmid/distributor-types';\nimport { Divider, Typography } from '@finmid/tbl-webapps/components';\nimport { useFormat } from '@finmid/translations';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\n\nimport { useActivityLogVariant } from '../../../hooks';\nimport { Log } from '../../Log';\n\ntype ActivityLogBlockProps = {\n  log: ActivityLog;\n  isLast: boolean;\n};\n\nexport const ActivityLogBlock = ({ log, isLast }: ActivityLogBlockProps) => {\n  const theme = useTheme();\n  const { dateAtTime } = useFormat();\n  const { i18nKey } = useActivityLogVariant(log);\n\n  if (i18nKey === '' || i18nKey == null) return null;\n\n  return (\n    <Box>\n      <Box px={2}>\n        <Spacer height={4} />\n        <Typography\n          fontSize={15}\n          lineHeight=\"20px\"\n          color={theme.glo.color.foundations[100]}\n        >\n          <Log i18nKey={i18nKey} log={log} />\n        </Typography>\n        <Spacer height={1} />\n        <Typography\n          fontSize={13}\n          lineHeight=\"16px\"\n          color={theme.glo.color.foundations[60]}\n        >\n          {dateAtTime(new Date(log.timestamp))}\n        </Typography>\n        <Spacer height={4} />\n      </Box>\n      {isLast ? null : <Divider />}\n    </Box>\n  );\n};\n","import styled from '@emotion/styled';\nimport { Divider } from '@finmid/tbl-webapps/components';\nimport { Badge } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\n\nconst StyledWhiteBadge = styled(Badge)(({ theme: { palette } }) => ({\n  border: `1px solid ${palette.gray[100]}`,\n  backgroundColor: '#FFF',\n  zIndex: 1,\n}));\n\ntype DayDividerProps = {\n  label: string;\n};\n\nexport const DayDivider = ({ label }: DayDividerProps) => (\n  <Box\n    position=\"relative\"\n    display=\"flex\"\n    alignItems=\"center\"\n    justifyContent=\"center\"\n  >\n    <Divider\n      style={{\n        height: '1px',\n        position: 'absolute',\n        top: '50%',\n        transform: 'translateY(-50%)',\n        left: 0,\n        right: 0,\n      }}\n    />\n    <StyledWhiteBadge label={label} variant=\"neutral\" />\n  </Box>\n);\n","import { ActivityLog } from '@finmid/distributor-types';\nimport { useFormat } from '@finmid/translations';\nimport { Box } from '@mui/material';\nimport {\n  differenceInCalendarDays,\n  endOfDay,\n  formatDistanceToNow,\n} from 'date-fns';\nimport { useTranslation } from 'react-i18next';\n\nimport { ActivityLogBlock } from './ActivityLogBlock';\nimport { DayDivider } from './DayDivider';\n\nconst getDaysDifference = (date: string) =>\n  differenceInCalendarDays(endOfDay(new Date()), endOfDay(new Date(date)));\n\nconst usePaymentRequestLogsByDay = (date: string) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'activity' });\n  const { dateDots } = useFormat();\n  let label = dateDots(new Date(date));\n  const daysDifference = getDaysDifference(date);\n  if (daysDifference < 1) {\n    label = t('today');\n  } else if (daysDifference <= 3) {\n    label = formatDistanceToNow(date, { addSuffix: true });\n  }\n  return label;\n};\n\ntype PaymentRequestLogsByDayProps = {\n  date: string;\n  logs: ActivityLog[];\n};\n\nexport const PaymentRequestLogsByDay = ({\n  date,\n  logs,\n}: PaymentRequestLogsByDayProps) => {\n  const label = usePaymentRequestLogsByDay(date);\n  return (\n    <Box data-test-id=\"activity-log-block\">\n      <DayDivider label={label} />\n      {logs.map((log, index) => (\n        <ActivityLogBlock\n          key={index}\n          log={log}\n          isLast={index === logs.length - 1}\n        />\n      ))}\n    </Box>\n  );\n};\n","import { HistoryLogsType } from '@finmid/distributor-types';\nimport { Box, Collapse } from '@mui/material';\n\nimport { PaymentRequestLogsByDay } from './components';\n\ntype PaymentRequestHistoryProps = {\n  activityLogs: HistoryLogsType;\n  open: boolean;\n};\n\nexport const PaymentRequestHistory = ({\n  activityLogs,\n  open,\n}: PaymentRequestHistoryProps) => {\n  return (\n    <Collapse in={open}>\n      <Box>\n        <Box>\n          {activityLogs.map(([date, logs], index) => (\n            <PaymentRequestLogsByDay key={index} date={date} logs={logs} />\n          ))}\n        </Box>\n      </Box>\n    </Collapse>\n  );\n};\n","import { ActivityLog } from '@finmid/distributor-types';\n\ntype FilterOutLogsEntriesType = (\n  logs: ActivityLog[],\n  filteredOutStatuses: string[],\n) => ActivityLog[];\n\nexport const filterOutLogsEntries: FilterOutLogsEntriesType = (\n  logs,\n  filteredOutStatuses,\n) => logs.filter((log) => !filteredOutStatuses.includes(log.status));\n","import { ActivityLog } from '@finmid/distributor-types';\n\ntype GroupLogsPerDayType = (\n  logs: ActivityLog[],\n) => Record<string, ActivityLog[]>;\n\nexport const groupLogsPerDay: GroupLogsPerDayType = (logs) =>\n  logs.reduce((acc, currentLog) => {\n    const [currentLogDate] = currentLog.timestamp.split('T');\n    if (acc[currentLogDate] == null) {\n      acc[currentLogDate] = [currentLog];\n    } else {\n      acc[currentLogDate].push(currentLog);\n    }\n    return acc;\n  }, {} as Record<string, ActivityLog[]>);\n","import { ActivityLog } from '@finmid/distributor-types';\n\ntype SortGroupedLogsPerDayType = (\n  groupedLogsPerDay: Record<string, ActivityLog[]>,\n) => [string, ActivityLog[]][];\n\nexport const sortGroupedLogsPerDay: SortGroupedLogsPerDayType = (\n  groupedLogsPerDay,\n) => {\n  const result = Object.entries(groupedLogsPerDay).sort(\n    ([dateA], [dateB]) => new Date(dateB).getTime() - new Date(dateA).getTime(),\n  );\n  return result;\n};\n","import {\n  SectionContainer,\n  SectionContent,\n} from '@finmid/tbl-webapps/components';\nimport { Button, ChevronDownIcon } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { usePaymentRequestSidebarPayload } from '../../PaymentRequestDetailsSidebar.context';\n\nimport { LatestStatus, PaymentRequestHistory } from './components';\nimport {\n  filterOutLogsEntries,\n  groupLogsPerDay,\n  sortGroupedLogsPerDay,\n} from './utils';\n\nexport const PaymentRequestActivity = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'activity' });\n  const { isMaxPayout, logEntries } = usePaymentRequestSidebarPayload();\n  const [seeMore, setSeeMore] = useState(false);\n\n  const toggleActivityDetails = () => {\n    if (seeMore) {\n      posthog.capture('clicked_payment_visibility_collapse');\n    } else {\n      posthog.capture('clicked_payment_visibility_expand');\n    }\n    setSeeMore((prev) => !prev);\n  };\n\n  const [latestLog, ...previousLogs] = filterOutLogsEntries(logEntries, [\n    'TRACKING',\n    ...(isMaxPayout ? ['PROCESSING'] : []),\n  ]);\n  const groupedPreviousLogs = groupLogsPerDay(previousLogs);\n  const historyLogs = sortGroupedLogsPerDay(groupedPreviousLogs);\n\n  return (\n    <SectionContainer>\n      <SectionContent disablePadding css={{ marginBottom: 0 }}>\n        <LatestStatus latestLog={latestLog} />\n        <PaymentRequestHistory open={seeMore} activityLogs={historyLogs} />\n      </SectionContent>\n      {historyLogs.length > 0 ? (\n        <Box display=\"flex\" justifyContent=\"center\">\n          <Button\n            variant=\"invisible\"\n            size=\"s\"\n            onClick={toggleActivityDetails}\n            prefixIcon={\n              <ChevronDownIcon\n                style={{\n                  transform: seeMore ? 'rotate(180deg)' : 'rotate(0deg)',\n                  transition: 'all 300ms cubic-bezier(0.4, 0, 0.2, 1) 0ms',\n                }}\n              />\n            }\n          >\n            {seeMore ? t('seeLess') : t('seeMore')}\n          </Button>\n        </Box>\n      ) : null}\n    </SectionContainer>\n  );\n};\n","import { BE_Error } from '@finmid/distributor-types';\nimport { useDisplayErrorToUser } from '@finmid/tbl-webapps/errors-handling';\nimport { useCallback } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nconst useGetCustomDomainErrors = () => {\n  const { t } = useTranslation('errors', { keyPrefix: 'createPartialPayout' });\n\n  const getCustomDomainErrors = useCallback(\n    (error: BE_Error) => {\n      let message: string | undefined;\n      const { description: errorDescription } = error.data.errorData.data;\n\n      if (\n        errorDescription ===\n        'Payout request amount exceeds total intent amount.'\n      ) {\n        message = t('payoutRequestAmount.exceedsTotalIntentAmount');\n      } else if (\n        errorDescription === 'intentTotalAmount must be larger than zero.'\n      ) {\n        message = t('intentTotalAmount.largerThanZero');\n      } else if (\n        errorDescription === 'intentAmountPaidOut cannot be negative.'\n      ) {\n        message = t('intentAmountPaidOut.negative');\n      } else if (\n        errorDescription.startsWith('Payout request amount is too small.')\n      ) {\n        message = t('paymentRequestAmount.tooSmall');\n      } else if (\n        errorDescription.startsWith(\n          'Remaining amount after payout is too small.',\n        )\n      ) {\n        message = t('remainingAmount.tooSmall');\n      }\n\n      return message ?? error.data.errorData.data.description;\n    },\n    [t],\n  );\n\n  return { getCustomDomainErrors };\n};\n\nexport const useCreatePayoutErrors = () => {\n  const { getCustomDomainErrors } = useGetCustomDomainErrors();\n  return useDisplayErrorToUser({\n    getCustomDomainErrors,\n  });\n};\n","import { useFormat } from '@finmid/translations';\nimport { endOfDay } from 'date-fns';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport * as Yup from 'yup';\n\ntype UseUpdateInvoiceDueDateFormSchemaArgs = {\n  minInvoiceDueDate: Date;\n  maxInvoiceDueDate: Date;\n};\n\nexport const useUpdateInvoiceDueDateFormSchema = ({\n  minInvoiceDueDate,\n  maxInvoiceDueDate,\n}: UseUpdateInvoiceDueDateFormSchemaArgs) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'validation',\n  });\n  const { date } = useFormat();\n\n  const schema = useMemo(\n    () =>\n      Yup.object().shape({\n        invoiceDueDate: Yup.date()\n          .typeError(t('dateValid'))\n          .required()\n          .test(\n            'is-within-range',\n            t('dateWithinRange', {\n              minInvoiceDueDate: date(minInvoiceDueDate),\n              maxInvoiceDueDate: date(maxInvoiceDueDate),\n            }),\n            (value) =>\n              endOfDay(value) >= minInvoiceDueDate &&\n              endOfDay(value) <= maxInvoiceDueDate,\n          ),\n      }),\n    [date, maxInvoiceDueDate, minInvoiceDueDate, t],\n  );\n\n  return {\n    validationSchema: schema,\n  };\n};\n","import { yupResolver } from '@hookform/resolvers/yup';\nimport { addDays } from 'date-fns';\nimport { useForm } from 'react-hook-form';\n\nimport { getBusinessToday } from '../../../../../../../PaymentRequests.utils';\nimport { usePaymentRequestSidebarPayload } from '../../PaymentRequestDetailsSidebar.context';\n\nimport { useUpdateInvoiceDueDateFormSchema } from './UpdateInvoiceDueDateForm.schema';\n\nexport const useUpdateInvoiceDueDateDialog = () => {\n  const { paymentRequest } = usePaymentRequestSidebarPayload();\n  const today = getBusinessToday();\n  const maxInvoiceDueDate = addDays(today, paymentRequest.repaymentTermDays);\n\n  const { validationSchema } = useUpdateInvoiceDueDateFormSchema({\n    maxInvoiceDueDate,\n    minInvoiceDueDate: today,\n  });\n  const methods = useForm<{ invoiceDueDate: Date }>({\n    resolver: yupResolver(validationSchema),\n  });\n\n  return {\n    methods,\n    maxInvoiceDueDate,\n    paymentRequestId: paymentRequest.id,\n  };\n};\n","import { useCallback, useState } from 'react';\nimport { UseFormReturn } from 'react-hook-form';\n\nexport const useValidateInvoiceDueDate = (\n  methods: UseFormReturn<{ invoiceDueDate: Date }>,\n) => {\n  const [showError, setShowError] = useState(false);\n  const [errorMessage, setErrorMessage] = useState<string | undefined>();\n\n  const { getFieldState, trigger } = methods;\n\n  const triggerInvoiceDueDateValidation = useCallback(async () => {\n    const isFieldValid = await trigger('invoiceDueDate');\n\n    if (isFieldValid) {\n      setShowError(false);\n      setErrorMessage(undefined);\n    } else {\n      const currentState = getFieldState('invoiceDueDate');\n      setShowError(true);\n      setErrorMessage(currentState.error?.message);\n    }\n  }, [getFieldState, trigger]);\n\n  return {\n    errorMessage,\n    showError,\n    triggerInvoiceDueDateValidation,\n  };\n};\n","import { DatePickerOcarinaLike, Dialog } from '@finmid/tbl-webapps/components';\nimport { useUpdatePaymentRequestOptionalMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { Button } from '@finmid/ui/ocarina/Button';\nimport { TextInputLabel } from '@finmid/ui/ocarina/TextInput/TextInputLabel';\nimport { formatISO } from 'date-fns';\nimport { Dispatch, SetStateAction } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useCreatePayoutErrors } from '../SidebarPayoutModal/useHandleCreatePayoutErrors';\n\nimport { useUpdateInvoiceDueDateDialog } from './UpdateInvoiceDueDateDialog.hook';\nimport { useValidateInvoiceDueDate } from './validateInvoiceDueDate.hook';\n\ntype UpdateInvoiceDueDateDialogProps = {\n  open: boolean;\n  setOpen: Dispatch<SetStateAction<boolean>>;\n};\n\nexport const UpdateInvoiceDueDateDialog = ({\n  open,\n  setOpen,\n}: UpdateInvoiceDueDateDialogProps) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'updateInvoiceDueDateDialog',\n  });\n\n  const { methods, paymentRequestId, maxInvoiceDueDate } =\n    useUpdateInvoiceDueDateDialog();\n\n  const { errorMessage, showError, triggerInvoiceDueDateValidation } =\n    useValidateInvoiceDueDate(methods);\n\n  const watchInvoiceDueDate = methods.watch('invoiceDueDate');\n  const handleChange = (date: Date | null) => {\n    if (date != null) methods.setValue('invoiceDueDate', date);\n    triggerInvoiceDueDateValidation();\n  };\n  const { displayErrorToUser } = useCreatePayoutErrors();\n  const [updatePaymentRequest] = useUpdatePaymentRequestOptionalMutation();\n  const onSubmit = async (data: { invoiceDueDate: Date }) => {\n    try {\n      await updatePaymentRequest({\n        paymentRequestId,\n        invoiceDueDate: formatISO(data.invoiceDueDate, {\n          representation: 'complete',\n        }),\n      }).unwrap();\n    } catch (error) {\n      displayErrorToUser(error);\n      return;\n    }\n  };\n\n  return (\n    <Dialog\n      open={open}\n      actions={[\n        <Button\n          variant=\"primary\"\n          type=\"submit\"\n          disabled={!methods.formState.isValid}\n          onClick={methods.handleSubmit(onSubmit)}\n        >\n          {t('submitDate')}\n        </Button>,\n        <Button variant=\"secondary\" onClick={() => setOpen(false)}>\n          {t('cancel')}\n        </Button>,\n      ]}\n      title={t('dialogTitle', { paymentRequestId })}\n      onClose={() => setOpen(false)}\n      PaperProps={{ style: { width: '640px' } }}\n    >\n      <div>\n        <TextInputLabel>{t('invoiceDueDate')}</TextInputLabel>\n        <DatePickerOcarinaLike\n          disablePast\n          value={watchInvoiceDueDate}\n          maxDate={maxInvoiceDueDate}\n          minDate={new Date()}\n          placement=\"bottom-end\"\n          onChange={handleChange}\n          slotProps={{\n            textField: {\n              error: showError,\n              helperText: showError && errorMessage,\n            },\n          }}\n        />\n      </div>\n    </Dialog>\n  );\n};\n","import { AlertLevel, DrawerAlert } from '@finmid/tbl-webapps/components';\nimport { differenceInCalendarDays, isAfter, isSameDay } from 'date-fns';\nimport { useState } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { usePaymentRequestSidebarPayload } from '../PaymentRequestDetailsSidebar.context';\n\nimport { UpdateInvoiceDueDateDialog } from './UpdateInvoiceDueDateDialog/UpdateInvoiceDueDateDialog';\n\nconst compareDatesWithToday = (eventDate: string) => {\n  const today = new Date();\n  const eventDay = new Date(eventDate);\n  const isToday = isSameDay(eventDay, today);\n  const isInTheFuture = isAfter(eventDay, today);\n  const isInThePast = !isToday && !isInTheFuture;\n\n  return {\n    isInThePast,\n    isInTheFuture,\n    isToday,\n  };\n};\n\nconst getRemainingDays = (eventDate: string) =>\n  differenceInCalendarDays(new Date(eventDate), new Date());\nconst getOverdueDays = (eventDate: string) =>\n  differenceInCalendarDays(new Date(), new Date(eventDate));\n\nconst getRemainingTime = (\n  date: string,\n): {\n  i18nKey: 'remaining' | 'past' | 'today';\n  level?: AlertLevel;\n  numberOfDays?: number;\n} => {\n  const { isInTheFuture, isInThePast } = compareDatesWithToday(date);\n  if (isInTheFuture) {\n    const i18nKey = 'remaining' as const;\n    const numberOfDays = getRemainingDays(date);\n    const level = numberOfDays < 2 ? 'warning' : 'info';\n    return { i18nKey, level, numberOfDays };\n  }\n  if (isInThePast) {\n    const i18nKey = 'past' as const;\n    const numberOfDays = getOverdueDays(date);\n    const level = 'error';\n    return { i18nKey, level, numberOfDays };\n  }\n  return {\n    i18nKey: 'today',\n  };\n};\n\ntype RepaymentDeadlineInnerProps = {\n  invoiceDueDate: string;\n};\n\nconst RepaymentDeadlineInner = ({\n  invoiceDueDate,\n}: RepaymentDeadlineInnerProps) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'repaymentDeadline',\n  });\n\n  const { i18nKey, level, numberOfDays } = getRemainingTime(invoiceDueDate);\n\n  return (\n    <DrawerAlert level={level} testId=\"repayment-deadline\">\n      <Trans\n        t={t}\n        i18nKey={i18nKey}\n        components={{\n          span: <span style={{ fontWeight: 700 }} />,\n        }}\n        values={{\n          days: numberOfDays,\n        }}\n      />\n    </DrawerAlert>\n  );\n};\n\nexport const RepaymentDeadline = () => {\n  const {\n    paymentRequest: { invoiceDueDate, status, allowPayoutWithoutDueDate },\n    payouts,\n  } = usePaymentRequestSidebarPayload();\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'sidebarAlerts' });\n  const [\n    isUpdateInvoiceDueDateDialogOpen,\n    setIsUpdateInvoiceDueDateDialogOpen,\n  ] = useState(false);\n  const hasPayouts = payouts.length > 0;\n\n  if (invoiceDueDate == null && hasPayouts && allowPayoutWithoutDueDate) {\n    return (\n      <DrawerAlert level=\"warning\" testId=\"missing-invoice-due-date-alert\">\n        <UpdateInvoiceDueDateDialog\n          open={isUpdateInvoiceDueDateDialogOpen}\n          setOpen={setIsUpdateInvoiceDueDateDialogOpen}\n        />\n        <Trans\n          t={t}\n          i18nKey=\"missingInvoiceDueDate\"\n          components={{\n            span: (\n              <span\n                style={{ fontWeight: 700, cursor: 'pointer' }}\n                onClick={() => setIsUpdateInvoiceDueDateDialogOpen(true)}\n              />\n            ),\n          }}\n        />\n      </DrawerAlert>\n    );\n  }\n\n  if (invoiceDueDate == null || status === 'CANCELLED' || status === 'CLOSED') {\n    return null;\n  }\n\n  return <RepaymentDeadlineInner invoiceDueDate={invoiceDueDate} />;\n};\n","import { DangerZoneDialog } from '@finmid/tbl-webapps/components';\nimport { useCancelPaymentRequestMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport posthog from 'posthog-js';\nimport { Dispatch, SetStateAction } from 'react';\nimport { useTranslation } from 'react-i18next';\n\ntype CancelPaymentRequestDialogProps = {\n  open: boolean;\n  setOpen: Dispatch<SetStateAction<boolean>>;\n  paymentRequestId: string;\n};\n\nexport const CancelPaymentRequestDialog = ({\n  open,\n  setOpen,\n  paymentRequestId,\n}: CancelPaymentRequestDialogProps) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'cancelInvoice' });\n  const { notifySuccess, notifyError } = useNotifications();\n  const [cancelPaymentRequest] = useCancelPaymentRequestMutation();\n\n  const handleCancelPaymentRequest = async () => {\n    posthog.capture('clicked_cancel_paymentRequest_confirm');\n    try {\n      await cancelPaymentRequest(paymentRequestId);\n      notifySuccess(t('dialog.success'));\n    } catch {\n      notifyError();\n    }\n  };\n\n  return (\n    <DangerZoneDialog\n      title={t('dialog.title')}\n      cancelLabel={t('dialog.goBack')}\n      message={t('dialog.message')}\n      submitLabel={t('dialog.submitBtn')}\n      open={open}\n      onSubmit={handleCancelPaymentRequest}\n      setOpen={setOpen}\n    />\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport {\n  Dropdown,\n  Menu,\n  MenuIconButton,\n  MenuItem,\n  MenuSection,\n  MoreVerticalIcon,\n} from '@finmid/ui/ocarina';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { usePaymentRequestSidebarPayload } from '../../PaymentRequestDetailsSidebar.context';\n\nimport { CancelPaymentRequestDialog } from './CancelPaymentRequestDialog';\n\nexport const SidebarMenu = () => {\n  const theme = useTheme();\n  const [open, setOpen] = useState(false);\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'cancelInvoice' });\n  const { paymentRequest } = usePaymentRequestSidebarPayload();\n\n  const canCancelPaymentRequest = paymentRequest.status === 'PENDING';\n\n  if (!canCancelPaymentRequest) {\n    return null;\n  }\n\n  return (\n    <>\n      <Dropdown>\n        <MenuIconButton\n          icon={<MoreVerticalIcon />}\n          variant=\"invisible\"\n          color={theme.glo.color.foundations[100]}\n          data-test-id=\"sidebar-menu-button\"\n        />\n        <Menu\n          placement=\"bottom-end\"\n          data-test-id=\"menu-kebab\"\n          style={{ zIndex: 1400 }}\n        >\n          <MenuSection>\n            <MenuItem\n              onClick={() => setOpen(true)}\n              data-test-id=\"open-cancel-dialog-btn\"\n            >\n              {t('dialog.btnLabel')}\n            </MenuItem>\n          </MenuSection>\n        </Menu>\n      </Dropdown>\n      <CancelPaymentRequestDialog\n        open={open}\n        setOpen={setOpen}\n        paymentRequestId={paymentRequest.id}\n      />\n    </>\n  );\n};\n","import { Typography } from '@finmid/tbl-webapps/components';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { useTranslation } from 'react-i18next';\n\nimport { PaymentRequestStatusIndicator } from '../../../../../../../components';\nimport { usePaymentRequestSidebarPayload } from '../../PaymentRequestDetailsSidebar.context';\n\nimport { SidebarMenu } from './SidebarMenu';\n\nexport const SidebarGeneralInfo = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'details' });\n  const {\n    paymentRequest: { repaymentTermDays, status, id },\n  } = usePaymentRequestSidebarPayload();\n\n  return (\n    <>\n      <Typography fontSize={13} lineHeight=\"16px\">\n        {t('repaymentDaysFinancing', { repaymentTerm: repaymentTermDays })}\n      </Typography>\n      <Spacer height={1} />\n      <Box\n        display=\"flex\"\n        alignItems=\"center\"\n        justifyContent=\"space-between\"\n        gap={1}\n      >\n        <Box\n          display=\"flex\"\n          alignItems=\"center\"\n          justifyContent=\"flex-start\"\n          gap={1}\n          overflow=\"hidden\"\n        >\n          <PaymentRequestStatusIndicator status={status} />\n          <Typography\n            fontSize={19}\n            fontWeight={700}\n            lineHeight=\"24px\"\n            style={{\n              textOverflow: 'ellipsis',\n              overflow: 'hidden',\n              textWrap: 'nowrap',\n            }}\n          >\n            {id}\n          </Typography>\n        </Box>\n        <Box>\n          <SidebarMenu />\n        </Box>\n      </Box>\n    </>\n  );\n};\n","import { FormTextField } from '@finmid/tbl-webapps/components';\nimport { TextInputLabel } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { Control } from 'react-hook-form';\n\nimport type { PayoutFormModalType } from '../PayoutFormModal.types';\n\ntype InvoiceIdProps = {\n  control: Control<PayoutFormModalType>;\n  placeholder: string;\n  isDisabled: boolean;\n};\n\nexport const InvoiceId = ({\n  control,\n  isDisabled,\n  placeholder,\n}: InvoiceIdProps) => {\n  return (\n    <Box flexGrow={1}>\n      <TextInputLabel required>{'Invoice Id'}</TextInputLabel>\n      <FormTextField\n        control={control}\n        disabled={isDisabled}\n        name=\"invoiceId\"\n        placeholder={placeholder}\n        fullWidth\n      />\n    </Box>\n  );\n};\n","import { GetPaymentRequest } from '@finmid/distributor-types';\nimport { FormTextField } from '@finmid/tbl-webapps/components';\nimport { useCalculatePayoutValuesMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { currencySymbols } from '@finmid/tbl-webapps/utils';\nimport { TextInputLabel } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport debounce from 'lodash/debounce';\nimport { Control, UseFormSetValue, UseFormTrigger } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport type { PayoutFormModalType } from '../PayoutFormModal.types';\n\ntype AmountFieldsProps = {\n  control: Control<PayoutFormModalType>;\n  setValue: UseFormSetValue<PayoutFormModalType>;\n  paymentRequest: GetPaymentRequest.GatewayResponse;\n  trigger: UseFormTrigger<PayoutFormModalType>;\n  setCustomNetAmount: React.Dispatch<React.SetStateAction<number | null>>;\n  setCustomGrossAmount: React.Dispatch<React.SetStateAction<number | null>>;\n  setCustomFee: React.Dispatch<React.SetStateAction<number | null>>;\n};\n\nexport const AmountFields = ({\n  control,\n  setValue,\n  paymentRequest,\n  trigger,\n  setCustomNetAmount,\n  setCustomGrossAmount,\n  setCustomFee,\n}: AmountFieldsProps) => {\n  const [calculateAmount] = useCalculatePayoutValuesMutation();\n  const { t } = useTranslation('invoicesPage');\n  const {\n    id,\n    amountDetails: { originalAmount },\n    maxFinancingAmount,\n    amountPaidOut,\n    currency,\n  } = paymentRequest;\n  const calculationRequestData = {\n    intentId: id,\n    intentAmountPaidOut: amountPaidOut,\n    intentMaxPayoutAmount: maxFinancingAmount,\n    intentTotalAmount: originalAmount,\n  };\n\n  const syncValues = async (value: string, field: string) => {\n    if (field === 'grossAmount') {\n      const isValid = await trigger('grossAmount');\n      if (!isValid) {\n        return;\n      }\n      const fieldValue = Number(Number(value).toFixed(4));\n      const values = await calculateAmount({\n        ...calculationRequestData,\n        calculationType: 'AMOUNT',\n        value: fieldValue,\n      }).unwrap();\n\n      if ('grossPercent' in values) {\n        setValue('grossPercent', Number(values.grossPercent), {\n          shouldValidate: true,\n        });\n        setCustomNetAmount(values.netAmount);\n        setCustomGrossAmount(fieldValue);\n        setCustomFee(values.totalFeeAmount);\n      }\n    } else {\n      const isValid = await trigger('grossPercent');\n      if (!isValid) {\n        return;\n      }\n      const values = await calculateAmount({\n        ...calculationRequestData,\n        calculationType: 'PERCENTAGE',\n        value: Number(Number(value).toFixed(4)),\n      }).unwrap();\n\n      if ('grossAmount' in values) {\n        setValue('grossAmount', Number(values.grossAmount), {\n          shouldValidate: true,\n        });\n        setCustomNetAmount(values.netAmount);\n        setCustomGrossAmount(values.grossAmount);\n        setCustomFee(values.totalFeeAmount);\n      }\n    }\n  };\n  const debouncedSyncValues = debounce(syncValues, 300);\n\n  return (\n    <Box flexGrow={1}>\n      <TextInputLabel required>{t('table.headerAmount')}</TextInputLabel>\n      <Box display=\"flex\" gap=\"8px\">\n        <FormTextField\n          startAdornment={currencySymbols[currency]}\n          control={control}\n          name=\"grossAmount\"\n          placeholder={currency}\n          handleChange={(value) => debouncedSyncValues(value, 'grossAmount')}\n          fullWidth\n        />\n        <FormTextField\n          endAdornment={'%'}\n          control={control}\n          name=\"grossPercent\"\n          placeholder={t('createPayout.percentageGross')}\n          handleChange={(value) => debouncedSyncValues(value, 'grossPercent')}\n          fullWidth\n          testId=\"grossPercentInput\"\n        />\n      </Box>\n    </Box>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { Box } from '@mui/material';\nimport { Control, Controller } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { InstantPayoutSwitch } from '../../../../../../../../components/InstantPayoutSwitch';\nimport type { PayoutFormModalType } from '../PayoutFormModal.types';\n\ntype InstantPayoutProps = {\n  control: Control<PayoutFormModalType>;\n};\n\nexport const InstantPayout = ({ control }: InstantPayoutProps) => {\n  const theme = useTheme();\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'createInvoice' });\n\n  return (\n    <Box p={2} bgcolor={theme.glo.color.foundations[10]} borderRadius={2}>\n      <Box display=\"flex\" justifyContent=\"space-between\">\n        <Typography fontSize={13} fontWeight={600}>\n          {t('instantPayoutTitle')}\n        </Typography>\n\n        <Controller\n          name=\"instantPayout\"\n          control={control}\n          render={({ field: { onChange, value } }) => (\n            <InstantPayoutSwitch\n              checked={value}\n              handleChange={onChange}\n              testId=\"instant-payout-switch\"\n            />\n          )}\n        />\n      </Box>\n\n      <Typography\n        fontSize={13}\n        mt={0.5}\n        color={theme.glo.color.foundations[60]}\n      >\n        {t('instantPayoutInfo')}\n      </Typography>\n    </Box>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { GetPaymentRequest } from '@finmid/distributor-types';\nimport { Divider } from '@finmid/tbl-webapps/components';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { currencyIcons } from '@finmid/tbl-webapps/utils';\nimport { useFormat } from '@finmid/translations';\nimport { Badge } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { useTranslation } from 'react-i18next';\n\nimport { DetailsWrapper } from '../../../../../../../../components/DetailsWrapper';\n\ntype PayoutBreakdownProps = {\n  paymentRequest: GetPaymentRequest.GatewayResponse;\n  isInstantPayoutOn: boolean;\n  customNetAmount: number | null;\n  customGrossAmount: number | null;\n  maxGrossPayout: number | null;\n  maxNetPayout: number | null;\n  customFee: number | null;\n};\n\nconst DetailsRow = styled(Box)(({ theme }) => ({\n  backgroundColor: theme.glo.color.foundations[0],\n  display: 'grid',\n  gridTemplateColumns: '4fr 1fr',\n  rowGap: theme.spacing(1),\n  padding: theme.spacing(2),\n  alignItems: 'center',\n}));\n\nexport const PayoutBreakdown = ({\n  paymentRequest,\n  isInstantPayoutOn,\n  customNetAmount,\n  customGrossAmount,\n  customFee,\n  maxGrossPayout,\n  maxNetPayout,\n}: PayoutBreakdownProps) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'payoutBreakdown',\n  });\n  const { money } = useFormat();\n  const theme = useTheme();\n  const {\n    currency,\n    financingPortion,\n    amountsBreakdown: {\n      grossFinancingAmount,\n      totalAmount,\n      fees: { totalFeeAmount },\n    },\n  } = paymentRequest;\n\n  const netPayoutValue = isInstantPayoutOn ? maxNetPayout : customNetAmount;\n  const grossPayoutValue = isInstantPayoutOn\n    ? maxGrossPayout\n    : customGrossAmount;\n  const totalFeeAmountValue = isInstantPayoutOn ? totalFeeAmount : customFee;\n  const isFullyFinanced = financingPortion === 100;\n\n  const totalFee = totalFeeAmountValue\n    ? money(totalFeeAmountValue, currency)\n    : '-';\n  const negativeSymbol = totalFee.includes('-') ? '' : '-';\n\n  return (\n    <DetailsWrapper title={t('title')} IconFlag={currencyIcons[currency]}>\n      <DetailsRow>\n        <Typography\n          fontSize={13}\n          fontWeight={500}\n          lineHeight=\"16px\"\n          color={theme.glo.color.foundations[60]}\n          key={'totalAmountLabel'}\n        >\n          {t('totalAmount')}\n        </Typography>\n        <Typography\n          fontSize={15}\n          fontWeight={400}\n          lineHeight=\"20px\"\n          key={'totalAmountValue'}\n          textAlign=\"end\"\n          numeric\n        >\n          {money(totalAmount, currency)}\n        </Typography>\n        {!isFullyFinanced && [\n          <Typography\n            fontSize={13}\n            fontWeight={500}\n            lineHeight=\"16px\"\n            color={theme.glo.color.foundations[60]}\n            key={'financingPortionLabel'}\n          >\n            {t('financingPortion')}\n            <Badge variant=\"neutral\" label={`${financingPortion}%`} />\n          </Typography>,\n          <Typography\n            fontSize={15}\n            fontWeight={400}\n            lineHeight=\"20px\"\n            key={'financingPortionValue'}\n            textAlign=\"end\"\n            numeric\n          >\n            {money(grossFinancingAmount, currency)}\n          </Typography>,\n        ]}\n      </DetailsRow>\n      <Divider />\n      <DetailsRow>\n        <Typography\n          fontSize={13}\n          fontWeight={500}\n          lineHeight=\"16px\"\n          color={theme.glo.color.foundations[60]}\n        >\n          {t('grossPayout')}\n        </Typography>\n        <Typography\n          fontSize={15}\n          fontWeight={400}\n          lineHeight=\"20px\"\n          textAlign=\"end\"\n          numeric\n        >\n          {grossPayoutValue ? money(grossPayoutValue, currency) : '-'}\n        </Typography>\n      </DetailsRow>\n      <Divider />\n      <DetailsRow>\n        <Typography\n          fontSize={13}\n          fontWeight={500}\n          lineHeight=\"16px\"\n          color={theme.glo.color.foundations[60]}\n        >\n          {t('netPayout')}\n        </Typography>\n        <Box\n          sx={{\n            display: 'flex',\n            flexDirection: 'column',\n            alignItems: 'flex-end',\n            gap: 1,\n          }}\n        >\n          <Typography\n            fontSize={15}\n            fontWeight={400}\n            lineHeight=\"20px\"\n            textAlign=\"end\"\n            numeric\n          >\n            {netPayoutValue ? money(netPayoutValue, currency) : '-'}\n          </Typography>\n          <Typography\n            fontSize={13}\n            fontWeight={500}\n            lineHeight=\"16px\"\n            color={theme.glo.color.foundations[60]}\n            numeric\n          >\n            {negativeSymbol + totalFee}\n          </Typography>\n        </Box>\n      </DetailsRow>\n    </DetailsWrapper>\n  );\n};\n","import { GetPaymentRequest } from '@finmid/distributor-types';\nimport { TWO_DECIMAL_REGEX } from '@finmid/tbl-webapps/utils';\nimport currency from 'currency.js';\nimport { useTranslation } from 'react-i18next';\nimport * as yup from 'yup';\n\nexport const usePayoutModalFormSchema = (\n  paymentRequest: GetPaymentRequest.GatewayResponse,\n  maxPercent: number | null,\n) => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'validation' });\n  const outstandingAmount = currency(paymentRequest.maxFinancingAmount);\n  return yup.object().shape({\n    instantPayout: yup.boolean().required(),\n    invoiceId: yup.string().required(t('invoiceIdRequired')),\n    allowEmptyDueDateForPayout: yup.boolean().optional(),\n    invoiceDueDate: yup\n      .date()\n      .when(\n        'allowEmptyDueDateForPayout',\n        ([allowEmptyDueDateForPayout], schema) =>\n          allowEmptyDueDateForPayout\n            ? schema\n            : schema.required(t('invoiceDueDateRequired')),\n      ),\n    grossAmount: yup\n      .number()\n      .when('instantPayout', ([instantPayout], schema) =>\n        instantPayout ? schema : schema.required(t('priceRequired')),\n      )\n      .typeError(t('priceValid'))\n      .min(\n        0.1,\n        t('minPayoutGrossAmount', {\n          min: 0.1,\n          currency: paymentRequest.currency,\n        }),\n      )\n      .test(\n        'max-two-decimal',\n        t('maxTwoDigits'),\n        (value: number | undefined) => {\n          if (value != null) {\n            return TWO_DECIMAL_REGEX.test(value.toString());\n          }\n          return true;\n        },\n      )\n      .test(\n        'max-outstanding-amount',\n        t('maxOutstandingAmount', {\n          max: outstandingAmount.value,\n          currency: paymentRequest.currency,\n        }),\n        (value: number | undefined) => {\n          if (value != null) {\n            return value <= outstandingAmount.value;\n          }\n          return true;\n        },\n      )\n      .test(\n        'min-remaining-amount',\n        t('minRemainingAmount', {\n          min: 0.1,\n          currency: paymentRequest.currency,\n        }),\n        (value: number | undefined) => {\n          if (value != null) {\n            const grossAmountCurrency = currency(value);\n            const remainingAmountLessThan10Cents =\n              outstandingAmount.subtract(grossAmountCurrency).value < 0.1;\n            const isMax = outstandingAmount.value === grossAmountCurrency.value;\n            return !remainingAmountLessThan10Cents || isMax;\n          }\n          return true;\n        },\n      ),\n    grossPercent: yup\n      .number()\n      .when('instantPayout', ([instantPayout], schema) =>\n        instantPayout ? schema : schema.required(t('priceRequired')),\n      )\n      .typeError(t('priceValid'))\n      .positive(t('pricePositive'))\n      .max(\n        maxPercent || 100,\n        t('maxPayoutPercentage', { maxPercentage: maxPercent || 100 }),\n      )\n      .test(\n        'max-two-decimal',\n        t('maxTwoDigits'),\n        (value: number | undefined) => {\n          if (value != null) {\n            return TWO_DECIMAL_REGEX.test(value.toString());\n          }\n          return true;\n        },\n      ),\n  });\n};\n","import {\n  Button,\n  SectionContainer,\n  SectionContent,\n  SectionHeader,\n  Typography,\n} from '@finmid/tbl-webapps/components';\nimport {\n  useCalculatePayoutValuesMutation,\n  useCreatePayoutMutation,\n  useUpdatePaymentRequestOptionalMutation,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport { yupResolver } from '@hookform/resolvers/yup';\nimport { Box } from '@mui/material';\nimport { addDays, formatISO } from 'date-fns';\nimport posthog from 'posthog-js';\nimport { useEffect, useState } from 'react';\nimport { useForm } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { getBusinessToday } from '../../../../../../../PaymentRequests.utils';\nimport { InvoiceDueDatePickerOcarinaLike } from '../../../../../../../components';\nimport { usePaymentRequestSidebarPayload } from '../../PaymentRequestDetailsSidebar.context';\n\nimport { PayoutFormModalType } from './PayoutFormModal.types';\nimport {\n  AmountFields,\n  InstantPayout,\n  InvoiceId,\n  PayoutBreakdown,\n} from './components';\nimport { useCreatePayoutErrors } from './useHandleCreatePayoutErrors';\nimport { usePayoutModalFormSchema } from './usePayoutModalForm.schema';\n\ntype PayoutFormModalContentProps = {\n  onClose: () => void;\n};\ninterface updatePaymentRequestPartial {\n  invoiceNumber?: string;\n  invoiceDueDate?: string;\n  maxInvoiceDueDate?: string;\n}\nexport const PayoutFormModalContent = ({\n  onClose,\n}: PayoutFormModalContentProps) => {\n  const { paymentRequest } = usePaymentRequestSidebarPayload();\n  const { id, invoiceNumber, invoiceDueDate, repaymentTermDays } =\n    paymentRequest;\n  const allowEmptyDueDateForPayout = paymentRequest.allowPayoutWithoutDueDate;\n  const { t } = useTranslation('invoicesPage');\n  const { displayErrorToUser } = useCreatePayoutErrors();\n  const [updatePaymentRequest] = useUpdatePaymentRequestOptionalMutation();\n  const currentDate = getBusinessToday();\n  const minInvoiceDueDate = addDays(currentDate, 3);\n  const maxInvoiceDueDate = addDays(currentDate, repaymentTermDays);\n  const [calculateAmount] = useCalculatePayoutValuesMutation();\n  const [maxGrossPayout, setMaxGrossPayout] = useState<number | null>(null);\n  const [maxNetPayout, setMaxNetPayout] = useState<number | null>(null);\n  const [maxPercent, setMaxPercent] = useState<number | null>(null);\n  const validationSchema = usePayoutModalFormSchema(paymentRequest, maxPercent);\n  const [customNetAmount, setCustomNetAmount] = useState<number | null>(null);\n  const [customGrossAmount, setCustomGrossAmount] = useState<number | null>(\n    null,\n  );\n  const [customFee, setCustomFee] = useState<number | null>(null);\n  const { control, watch, setValue, trigger, handleSubmit, formState } =\n    useForm<PayoutFormModalType>({\n      resolver: yupResolver(validationSchema),\n      defaultValues: {\n        instantPayout: true,\n        invoiceId: invoiceNumber ?? '',\n        allowEmptyDueDateForPayout,\n        invoiceDueDate: invoiceDueDate ? new Date(invoiceDueDate) : undefined,\n      },\n    });\n  const isInstantPayoutOn = watch('instantPayout', true);\n  const [capturePayout] = useCreatePayoutMutation();\n  const onSubmit = async (data: PayoutFormModalType) => {\n    posthog.capture('clicked-payout-form-submit');\n    if (!invoiceNumber)\n      await updatePaymentRequestPartial({ invoiceNumber: data.invoiceId });\n    if (!allowEmptyDueDateForPayout && !invoiceDueDate && data.invoiceDueDate)\n      await updatePaymentRequestPartial({\n        invoiceDueDate: formatISO(data.invoiceDueDate, {\n          representation: 'complete',\n        }),\n        maxInvoiceDueDate: formatISO(maxInvoiceDueDate, {\n          representation: 'complete',\n        }),\n      });\n\n    const payoutInstructions = isInstantPayoutOn\n      ? {\n          payoutType: 'MAX' as const,\n        }\n      : {\n          payoutType: 'AMOUNT' as const,\n          value: Number(data.grossAmount),\n        };\n    try {\n      await capturePayout({\n        paymentRequestId: id,\n        payoutInstructions,\n      }).unwrap();\n      onClose();\n    } catch (error) {\n      displayErrorToUser(error);\n    }\n  };\n  const updatePaymentRequestPartial = async (\n    data: updatePaymentRequestPartial,\n  ) => {\n    try {\n      await updatePaymentRequest({\n        paymentRequestId: paymentRequest.id,\n        ...data,\n      }).unwrap();\n    } catch (error) {\n      displayErrorToUser(error);\n      return;\n    }\n  };\n  const fetchMaxAmount = async () => {\n    const { data } = await calculateAmount({\n      intentId: paymentRequest.id,\n      intentAmountPaidOut: paymentRequest.amountPaidOut,\n      intentMaxPayoutAmount: paymentRequest.maxFinancingAmount,\n      intentTotalAmount: paymentRequest.amountDetails.originalAmount,\n      calculationType: 'MAX',\n    });\n    if (data && 'grossAmount' in data) {\n      setMaxGrossPayout(data.grossAmount);\n      setMaxNetPayout(data.netAmount);\n      setMaxPercent(data.grossPercent);\n    }\n  };\n  useEffect(() => {\n    fetchMaxAmount();\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  return (\n    <Box sx={{ width: '480px' }}>\n      <Typography fontSize={13} fontWeight={400} lineHeight=\"16px\">\n        {t('createInvoice.newPayout')}\n      </Typography>\n      <Spacer height={1} />\n      <Typography fontSize={19} fontWeight={700} lineHeight=\"24px\">\n        {t('createInvoice.heading', { id })}\n      </Typography>\n      <Spacer height={3} />\n      <SectionContainer>\n        <SectionHeader>{t('details.payoutDetails')}</SectionHeader>\n        <SectionContent style={{ gap: 16 }}>\n          <InstantPayout control={control} />\n          <PayoutBreakdown\n            paymentRequest={paymentRequest}\n            isInstantPayoutOn={isInstantPayoutOn}\n            customNetAmount={customNetAmount}\n            customGrossAmount={customGrossAmount}\n            maxGrossPayout={maxGrossPayout}\n            maxNetPayout={maxNetPayout}\n            customFee={customFee}\n          />\n          <InvoiceId\n            control={control}\n            placeholder={t('createInvoice.invoiceIdLabel')}\n            isDisabled={!!invoiceNumber}\n          />\n          {!isInstantPayoutOn && (\n            <AmountFields\n              control={control}\n              setValue={setValue}\n              paymentRequest={paymentRequest}\n              trigger={trigger}\n              setCustomNetAmount={setCustomNetAmount}\n              setCustomGrossAmount={setCustomGrossAmount}\n              setCustomFee={setCustomFee}\n            />\n          )}\n          {!allowEmptyDueDateForPayout && (\n            <InvoiceDueDatePickerOcarinaLike\n              control={control}\n              label={t('details.invoiceDueDate')}\n              name=\"invoiceDueDate\"\n              maxDate={maxInvoiceDueDate}\n              minDate={minInvoiceDueDate}\n              disabled={!!invoiceDueDate}\n              testId=\"invoiceDueDateField\"\n            />\n          )}\n        </SectionContent>\n      </SectionContainer>\n      <Spacer height={2} />\n      <Button\n        variant=\"primary\"\n        disabled={!formState.isValid}\n        size=\"m\"\n        type=\"submit\"\n        onClick={handleSubmit(onSubmit)}\n        fullWidth\n        testId=\"capture-payout-btn\"\n      >\n        {t('activity.createPayout')}\n      </Button>\n      <Spacer height={2} />\n      <Button variant=\"invisible\" size=\"m\" onClick={onClose} fullWidth>\n        {t('captureInvoice.cancelBtnLabel')}\n      </Button>\n    </Box>\n  );\n};\n","import { DrawerHeader } from '@finmid/tbl-webapps/components';\nimport { Dialog, DialogContent } from '@mui/material';\n\nimport { usePaymentRequestSidebarPayload } from '../../PaymentRequestDetailsSidebar.context';\n\nimport { PayoutFormModalContent } from './PayoutFormModalContent';\n\nexport const SidebarPayoutModal = () => {\n  const { isPayoutDialogOpen, setIsPayoutDialogOpen } =\n    usePaymentRequestSidebarPayload();\n\n  const onClose = () => {\n    setIsPayoutDialogOpen(false);\n  };\n\n  return (\n    <Dialog\n      open={isPayoutDialogOpen}\n      onClose={onClose}\n      fullScreen\n      PaperProps={{ sx: { borderRadius: '0' } }}\n      data-test-id=\"payout-modal-dialog\"\n    >\n      <DrawerHeader\n        title=\"\"\n        onClose={onClose}\n        sx={{\n          top: 0,\n          left: 0,\n          width: '100%',\n          zIndex: 1400,\n        }}\n      />\n      <DialogContent\n        sx={{\n          display: 'flex',\n          justifyContent: 'center',\n          alignItems: 'flex-start',\n        }}\n      >\n        <PayoutFormModalContent onClose={onClose} />\n      </DialogContent>\n    </Dialog>\n  );\n};\n","import {\n  useGetPaymentRequestByIdQuery,\n  useGetPaymentRequestDocumentsQuery,\n  useGetPaymentRequestPayoutsQuery,\n  useGetPaymentRequestStatusLogsListQuery,\n  useGetSellerByIdQuery,\n} from '@finmid/tbl-webapps/gateway-api';\n\ntype UsePaymentRequestDetailsSidebarProps = {\n  paymentRequestId: string;\n};\n\nexport const usePaymentRequestDetailsSidebar = ({\n  paymentRequestId,\n}: UsePaymentRequestDetailsSidebarProps) => {\n  const {\n    data: paymentRequest,\n    isFetching: isFetchingDetails,\n    error: errorDetails,\n  } = useGetPaymentRequestByIdQuery(paymentRequestId);\n\n  const {\n    data: payouts,\n    isFetching: isFetchingPayouts,\n    error: errorPayouts,\n  } = useGetPaymentRequestPayoutsQuery(paymentRequestId);\n\n  const {\n    data: seller,\n    isFetching: isFetchingSeller,\n    error: errorSeller,\n  } = useGetSellerByIdQuery(\n    { externalId: paymentRequest?.sellerId ?? '' },\n    { skip: paymentRequest?.sellerId === '' },\n  );\n\n  const {\n    data: logs,\n    isFetching: isFetchingLogs,\n    error: errorLogs,\n  } = useGetPaymentRequestStatusLogsListQuery(paymentRequestId);\n\n  const {\n    data: uploadedDocumentsData,\n    isFetching: isFetchingDocuments,\n    error: errorDocuments,\n  } = useGetPaymentRequestDocumentsQuery(paymentRequestId);\n\n  return {\n    data: {\n      logs,\n      paymentRequest,\n      payouts,\n      seller,\n      uploadedDocuments: uploadedDocumentsData?.documents,\n    },\n    error:\n      errorDetails ||\n      errorLogs ||\n      errorPayouts ||\n      errorSeller ||\n      errorDocuments,\n    isFetching:\n      isFetchingDetails ||\n      isFetchingLogs ||\n      isFetchingPayouts ||\n      isFetchingSeller ||\n      isFetchingDocuments,\n  };\n};\n","import { Drawer, ZeroState } from '@finmid/tbl-webapps/components';\nimport { Button, Loader, Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\n\nimport { PaymentRequestSidebarDetailsContextProvider } from './PaymentRequestDetailsSidebar.context';\nimport {\n  DetailsAndDocuments,\n  PaymentRequestActivity,\n  RepaymentDeadline,\n  SidebarGeneralInfo,\n  SidebarPayoutModal,\n} from './components';\nimport { usePaymentRequestDetailsSidebar } from './hooks';\n\ntype PaymentRequestDetailsSidebarProps = {\n  open: boolean;\n  paymentRequestId: string;\n  closeSidebar: () => void;\n};\n\nexport const PaymentRequestDetailsSidebar = ({\n  open,\n  paymentRequestId,\n  closeSidebar,\n}: PaymentRequestDetailsSidebarProps) => {\n  const { t, ready } = useTranslation('invoicesPage', { keyPrefix: 'details' });\n  const {\n    data: { logs, paymentRequest, payouts, seller, uploadedDocuments },\n    error,\n    isFetching,\n  } = usePaymentRequestDetailsSidebar({\n    paymentRequestId,\n  });\n\n  const dataIsReady =\n    logs?.logEntries != null &&\n    paymentRequest != null &&\n    payouts != null &&\n    seller != null &&\n    uploadedDocuments != null;\n\n  if (error) {\n    return (\n      <Drawer title={t('sidebar.title')} open={open} onClose={closeSidebar}>\n        <ZeroState\n          title={t('notFoundTitle')}\n          description={t('notFoundDescription')}\n        >\n          <Button variant=\"primary\" onClick={closeSidebar}>\n            {t('backBtnLabel')}\n          </Button>\n        </ZeroState>\n      </Drawer>\n    );\n  }\n\n  if (isFetching || !ready || !dataIsReady) {\n    return (\n      <Drawer title={t('sidebar.title')} open={open} onClose={closeSidebar}>\n        <Loader />\n      </Drawer>\n    );\n  }\n\n  return (\n    <Drawer\n      title={t('sidebar.title')}\n      open={open}\n      onClose={closeSidebar}\n      testId=\"payment-request-sidebar\"\n    >\n      <PaymentRequestSidebarDetailsContextProvider\n        paymentRequest={paymentRequest}\n        payouts={payouts}\n        seller={seller}\n        logEntries={logs.logEntries}\n        uploadedDocuments={uploadedDocuments}\n      >\n        <Box>\n          <SidebarGeneralInfo />\n          <Spacer height={3} />\n          <RepaymentDeadline />\n          <Spacer height={2} />\n          <PaymentRequestActivity />\n          <Spacer height={2} />\n          <DetailsAndDocuments />\n        </Box>\n        <SidebarPayoutModal />\n      </PaymentRequestSidebarDetailsContextProvider>\n    </Drawer>\n  );\n};\n","import { fetchErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useGetPaymentRequestsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useEffect } from 'react';\n\nimport { usePaymentRequestsListContext } from '../../../PaymentRequestsPage.context';\n\nexport const useGetPaymentRequests = () => {\n  const { filters } = usePaymentRequestsListContext();\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const {\n    data: paymentRequestsResponse,\n    isFetching: paymentRequestsIsFetching,\n    isError: paymentRequestsIsError,\n  } = useGetPaymentRequestsQuery(filters.server);\n\n  useEffect(() => {\n    if (paymentRequestsIsError) {\n      displayErrorToast(fetchErrorProps);\n    }\n  }, [paymentRequestsIsError, displayErrorToast]);\n\n  return {\n    paymentRequestsIsFetching,\n    paymentRequestsResponse,\n  };\n};\n","import { GetPaymentRequests } from '@finmid/distributor-types';\n\nimport { usePagination } from './usePagination.hook';\n\ntype UsePaymentRequestPaginationHookProps = {\n  paymentRequestsResponse?: GetPaymentRequests.GatewayResponse;\n};\n\nexport const usePaymentRequestsPaginationHook = ({\n  paymentRequestsResponse,\n}: UsePaymentRequestPaginationHookProps) => {\n  const {\n    paginationState,\n    loading: statsIsLoading,\n    rowsCount,\n    onPaginationBack,\n    onPaginationNext,\n    onPageSizeChange,\n  } = usePagination({\n    nextCursor: paymentRequestsResponse?.metadata?.nextCursor ?? null,\n    previousCursor: paymentRequestsResponse?.metadata?.previousCursor ?? null,\n  });\n\n  return {\n    paginationState,\n    rowsCount,\n    statsIsLoading,\n    onPaginationBack,\n    onPaginationNext,\n    onPageSizeChange,\n  };\n};\n","import { useSearchInputFilter } from '@finmid/tbl-webapps/components';\nimport debounce from 'lodash/debounce';\nimport { useMemo } from 'react';\n\nimport { usePaymentRequestsListContext } from '../../../PaymentRequestsPage.context';\n\nconst debounceMs = 200;\n\nexport const useSearch = () => {\n  const { filters, updateFilters } = usePaymentRequestsListContext();\n\n  const onSearch = useMemo(() => {\n    return debounce(updateFilters, debounceMs);\n  }, [updateFilters]);\n\n  const { handleChange } = useSearchInputFilter({\n    handleUpdateFilters: onSearch,\n    searchValue: filters.server.search,\n  });\n\n  return { onSearch: handleChange, searchValue: filters.server.search };\n};\n","import { PaymentRequest } from '@finmid/distributor-types';\nimport { TruncatedContent } from '@finmid/tbl-webapps/components';\nimport { useFormat } from '@finmid/translations';\nimport { GridColDef, GridRenderCellParams } from '@mui/x-data-grid';\nimport currencyJs from 'currency.js';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { PaymentRequestStatusIndicator } from '../../../components';\n\nexport const useColumns = (): GridColDef[] => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'table' });\n\n  const { money, date } = useFormat();\n\n  return useMemo(\n    () =>\n      [\n        {\n          field: 'status',\n          headerName: '',\n          sortable: false,\n          filterable: false,\n          align: 'center',\n          width: 48,\n          renderCell: ({\n            row: { status },\n          }: GridRenderCellParams<PaymentRequest>) => (\n            <PaymentRequestStatusIndicator status={status} />\n          ),\n        },\n        {\n          field: 'id',\n          headerName: t('headerPaymentRequestId'),\n          sortable: false,\n          filterable: false,\n          minWidth: 220,\n          renderCell: ({\n            row: { id },\n          }: GridRenderCellParams<PaymentRequest>) => (\n            <TruncatedContent content={id} testId={id} />\n          ),\n        },\n        {\n          field: 'creationTime',\n          headerName: t('headerCreationDate'),\n          sortable: false,\n          filterable: false,\n          minWidth: 120,\n          renderCell: ({ row: { creationTime } }) =>\n            date(new Date(creationTime)),\n        },\n        {\n          field: 'dueDate',\n          headerName: t('headerDueDate'),\n          sortable: false,\n          filterable: false,\n          minWidth: 120,\n          renderCell: ({ row: { invoiceDueDate } }) =>\n            invoiceDueDate ? date(new Date(invoiceDueDate)) : '-',\n        },\n        {\n          field: 'buyerName',\n          headerName: t('headerBuyer'),\n          sortable: false,\n          filterable: false,\n          minWidth: 120,\n          flex: 1,\n          renderCell: ({ row: { buyerName } }) => (\n            <div style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>\n              {buyerName}\n            </div>\n          ),\n        },\n        {\n          field: 'amount',\n          headerName: t('headerAmount'),\n          sortable: false,\n          filterable: false,\n          align: 'right',\n          headerAlign: 'right',\n          minWidth: 120,\n          flex: 1,\n          renderCell: ({ row: { totalAmount, currency } }) =>\n            money(currencyJs(totalAmount), currency),\n        },\n      ] as GridColDef<PaymentRequest>[],\n    [date, money, t],\n  ) as GridColDef[];\n};\n","import {\n  ErrorBoundary,\n  LazyLoadFallback,\n  ZeroState,\n} from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { Suspense, lazy } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { BuyersSellersFilter } from './BuyersSellersFilter';\nimport { PaymentRequestsDatesFilter } from './PaymentRequestsDatesFilter';\nimport { StatusSelector } from './StatusSelector';\nimport { PaymentRequestDetailsSidebar } from './components';\nimport {\n  usePaymentRequestsTableWithSidebar,\n  useShowPaymentDetails,\n} from './hooks';\nimport { useGetPaymentRequests } from './hooks/getPaymentRequests.hook';\nimport { usePaymentRequestsPaginationHook } from './hooks/paymentRequestsPagination.hook';\nimport { useSearch } from './hooks/useSearch.hook';\nimport { useColumns } from './useColumns';\n\nconst DataGrid = lazy(() => import('@finmid/tbl-webapps/components/DataGrid'));\n\nexport const PaymentRequestsTableWithSidebar = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'table' });\n\n  const { paymentRequestsResponse, paymentRequestsIsFetching } =\n    useGetPaymentRequests();\n\n  const {\n    paginationState,\n    rowsCount,\n    statsIsLoading,\n    onPaginationBack,\n    onPaginationNext,\n    onPageSizeChange,\n  } = usePaymentRequestsPaginationHook({ paymentRequestsResponse });\n\n  const { zeroStateDescription } = usePaymentRequestsTableWithSidebar();\n\n  const { openSidebar, visiblePaymentRequestId, closeSidebar, onRowClick } =\n    useShowPaymentDetails();\n\n  const columns = useColumns();\n\n  const { onSearch, searchValue } = useSearch();\n\n  const loading = paymentRequestsIsFetching || statsIsLoading;\n\n  return (\n    <ErrorBoundary fallback={<LazyLoadFallback />}>\n      <Suspense fallback={<Loader />}>\n        {visiblePaymentRequestId ? (\n          <PaymentRequestDetailsSidebar\n            closeSidebar={closeSidebar}\n            open={openSidebar}\n            paymentRequestId={visiblePaymentRequestId}\n          />\n        ) : null}\n        <DataGrid\n          disableColumnMenu\n          rows={paymentRequestsResponse?.data ?? []}\n          columns={columns}\n          rowCount={rowsCount}\n          initialState={{\n            pagination: { paginationModel: paginationState },\n          }}\n          paginationMode=\"server\"\n          onPaginationBack={onPaginationBack}\n          onPaginationNext={onPaginationNext}\n          pageSizeOptions={[10, 20, 30]}\n          onPageSizeChange={onPageSizeChange}\n          loading={loading}\n          toolbar={{\n            title: '',\n            onSearch,\n            searchValue,\n            actionsBar: (\n              <>\n                <BuyersSellersFilter />\n                <PaymentRequestsDatesFilter />\n                <StatusSelector />\n              </>\n            ),\n          }}\n          slots={{\n            noResultsOverlay: () => (\n              <ZeroState\n                title={t('zeroStateTitle')}\n                description={zeroStateDescription}\n              />\n            ),\n            noRowsOverlay: () => (\n              <ZeroState\n                title={t('zeroStateTitle')}\n                description={zeroStateDescription}\n              />\n            ),\n          }}\n          autoHeight\n          sx={{ '--DataGrid-overlayHeight': '200px' }}\n          onRowClick={onRowClick}\n          hideFooter={\n            paymentRequestsResponse?.data != null &&\n            paymentRequestsResponse?.data.length === 0\n          }\n        />\n      </Suspense>\n    </ErrorBoundary>\n  );\n};\n","import { GetTasks } from '@finmid/distributor-types';\nimport { Task } from '@finmid/tbl-webapps/components';\nimport { sharedTblRoutes } from '@finmid/tbl-webapps/routes';\nimport { UploadIcon } from '@finmid/ui/ocarina';\nimport { Trans, useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\ntype BuyerTaskProps = {\n  task: GetTasks.PlatformBuyerTask;\n};\n\nexport const BuyerTask = ({ task }: BuyerTaskProps) => {\n  const { t } = useTranslation('notifications', { keyPrefix: 'tasks' });\n  const navigate = useNavigate();\n\n  const goToDocUpload = () => {\n    navigate(`${sharedTblRoutes.buyers}/${task.buyerExternalId}/upload`);\n  };\n\n  return (\n    <Task\n      id={task.id}\n      creationTime={task.taskCreationTime}\n      icon={<UploadIcon />}\n      onClick={goToDocUpload}\n      actionLabel={t('pendingDocumentsTask.action')}\n    >\n      <Trans\n        t={t}\n        i18nKey={'buyerLimitTask.label'}\n        components={{ bold: <strong /> }}\n        values={{\n          buyer: task.buyerLegalName,\n        }}\n      />\n    </Task>\n  );\n};\n","import { Task } from '@finmid/tbl-webapps/components';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { UploadIcon } from '@finmid/ui/ocarina';\nimport { Trans, useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\ntype PendingDocumentsTaskProps = {\n  id: string;\n  creationTime: string;\n};\n\nexport const PendingDocumentsTask = ({\n  id,\n  creationTime,\n}: PendingDocumentsTaskProps) => {\n  const { t } = useTranslation('notifications', { keyPrefix: 'tasks' });\n  const navigate = useNavigate();\n\n  const goToDocUpload = () => {\n    navigate(`${b2bPaymentRoutes.paymentRequests}/${id}/upload`);\n  };\n\n  return (\n    <Task\n      id={id}\n      creationTime={creationTime}\n      icon={<UploadIcon />}\n      onClick={goToDocUpload}\n      actionLabel={t('pendingDocumentsTask.action')}\n    >\n      <Trans\n        t={t}\n        i18nKey={'pendingDocumentsTask.label'}\n        components={{ bold: <strong /> }}\n        values={{\n          id,\n        }}\n      />\n    </Task>\n  );\n};\n","import { Button, Icon } from '@finmid/ui/ocarina';\nimport { AddRounded, RemoveRounded } from '@mui/icons-material';\nimport { Dispatch, SetStateAction } from 'react';\nimport { useTranslation } from 'react-i18next';\n\ntype ToggleViewButtonProps = {\n  viewAll: boolean;\n  setViewAll: Dispatch<SetStateAction<boolean>>;\n};\n\nexport const ToggleViewButton = ({\n  viewAll,\n  setViewAll,\n}: ToggleViewButtonProps) => {\n  const { t } = useTranslation('invoicesPage', {\n    keyPrefix: 'toggleViewButton',\n  });\n\n  return (\n    <Button\n      variant=\"invisible\"\n      suffixIcon={\n        <Icon\n          size=\"small\"\n          icon={viewAll ? <RemoveRounded /> : <AddRounded />}\n        />\n      }\n      onClick={() => setViewAll((v) => !v)}\n    >\n      {viewAll ? t('viewLess') : t('viewMore')}\n    </Button>\n  );\n};\n","import { Section } from '@finmid/tbl-webapps/components';\nimport { useGetTasksQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { Spacer } from '@finmid/ui/ocarina';\nimport { Collapse } from '@mui/material';\nimport Box from '@mui/material/Box';\nimport { Fragment, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport {\n  BuyerTask,\n  PendingDocumentsTask,\n  ToggleViewButton,\n} from './components';\n\nconst visibleTasksLimit = 3;\n\nexport const DistributorTasks = () => {\n  const { t } = useTranslation('invoicesPage', { keyPrefix: 'tasks' });\n  const { data } = useGetTasksQuery();\n  const tasks = data?.filter((task) => task.status === 'PENDING') ?? [];\n\n  const [viewAll, setViewAll] = useState(false);\n\n  if (tasks.length === 0) return null;\n\n  const initiallyVisibleTasks = tasks.slice(0, visibleTasksLimit);\n  const initiallyHiddenTasks = tasks.slice(visibleTasksLimit);\n  const hasMoreTasks = tasks.length > visibleTasksLimit;\n\n  const tasksCountIndicator = hasMoreTasks ? ` (${tasks.length})` : '';\n\n  return (\n    <Section\n      title={t('sectionTitle') + tasksCountIndicator}\n      testId=\"distributor-tasks\"\n    >\n      <Box>\n        <Box display=\"flex\" flexDirection=\"column\" gap={0.5}>\n          {initiallyVisibleTasks.map((task) => (\n            <Fragment key={task.id}>\n              {task.entityType === 'PAYMENT_REQUEST_TASK' && (\n                <PendingDocumentsTask\n                  id={task.paymentIntentId}\n                  creationTime={task.taskCreationTime}\n                />\n              )}\n              {task.entityType === 'BUYER_TASK' && <BuyerTask task={task} />}\n            </Fragment>\n          ))}\n        </Box>\n\n        <Collapse in={viewAll}>\n          <Spacer height={0.5} />\n          <Box display=\"flex\" flexDirection=\"column\" gap={0.5}>\n            {initiallyHiddenTasks.map((task) => (\n              <Fragment key={task.id}>\n                {task.entityType === 'PAYMENT_REQUEST_TASK' && (\n                  <PendingDocumentsTask\n                    id={task.paymentIntentId}\n                    creationTime={task.taskCreationTime}\n                  />\n                )}\n                {task.entityType === 'BUYER_TASK' && <BuyerTask task={task} />}\n              </Fragment>\n            ))}\n          </Box>\n        </Collapse>\n\n        {hasMoreTasks && (\n          <Box display=\"flex\" justifyContent=\"center\" mt={0.5}>\n            <ToggleViewButton viewAll={viewAll} setViewAll={setViewAll} />\n          </Box>\n        )}\n      </Box>\n    </Section>\n  );\n};\n","import { Page } from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\n\nimport { PaymentRequestsListContextProvider } from './PaymentRequestsPage.context';\nimport {\n  DistributorTasks,\n  PaymentRequestsPageNavigation,\n  PaymentRequestsTableWithSidebar,\n} from './components';\n\nexport const PaymentRequestsPage = () => {\n  const { ready: paymentRequestsPageReady } = useTranslation('invoicesPage');\n  const { ready: componentsReady } = useTranslation('components');\n  const { ready: formatsReady } = useTranslation('formats');\n  const { ready: notificationsReady } = useTranslation('notifications');\n\n  const isLoadingTranslations =\n    !paymentRequestsPageReady ||\n    !componentsReady ||\n    !formatsReady ||\n    !notificationsReady;\n\n  return (\n    <PaymentRequestsListContextProvider>\n      <PaymentRequestsPageNavigation />\n      <Page>\n        {isLoadingTranslations ? (\n          <Loader />\n        ) : (\n          <Box display=\"flex\" flexDirection=\"column\" gap={2}>\n            <DistributorTasks />\n            <PaymentRequestsTableWithSidebar />\n          </Box>\n        )}\n      </Page>\n    </PaymentRequestsListContextProvider>\n  );\n};\n","import { GetPaymentRequest, PaymentRequest } from '@finmid/distributor-types';\nimport {\n  ErrorBoundary,\n  LazyLoadFallback,\n  ZeroState,\n} from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { GridRowParams } from '@mui/x-data-grid';\nimport { TFunction } from 'i18next';\nimport { Suspense, lazy } from 'react';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useColumns } from './useColumns';\n\nconst DataGrid = lazy(() => import('@finmid/tbl-webapps/components/DataGrid'));\n\ntype SmePaymentRequestsTableProps = {\n  paymentRequests?: GetPaymentRequest.GatewayResponse[];\n  t: TFunction;\n};\n\nexport const SmePaymentRequestsTable = ({\n  paymentRequests,\n  t,\n}: SmePaymentRequestsTableProps) => {\n  const columns = useColumns();\n  const navigate = useNavigate();\n\n  const onRowClick = ({ row: { id } }: GridRowParams<PaymentRequest>) => {\n    navigate(`/invoices?view=${id}`);\n  };\n\n  return (\n    <ErrorBoundary fallback={<LazyLoadFallback />}>\n      <Suspense fallback={<Loader />}>\n        <DataGrid\n          columns={columns}\n          rows={paymentRequests ?? []}\n          disableColumnMenu\n          onRowClick={onRowClick}\n          slots={{\n            noRowsOverlay: () => (\n              <ZeroState\n                title={t('transactions.zeroStateTitle')}\n                description={t('transactions.zeroStateDescription')}\n              />\n            ),\n          }}\n          autoHeight\n          sx={{ '--DataGrid-overlayHeight': '200px', mx: 0.5 }}\n        />\n      </Suspense>\n    </ErrorBoundary>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { Buyer, Seller } from '@finmid/distributor-types';\nimport { Typography } from '@finmid/tbl-webapps/components';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { Button, MoneyIcon, Icon, PlusIcon, Spacer } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport posthog from 'posthog-js';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\ninterface Props {\n  seller?: Seller;\n  buyer?: Buyer;\n}\n\nexport const EmptyPaymentRequests = ({ seller, buyer }: Props) => {\n  const theme = useTheme();\n  const navigate = useNavigate();\n  const { t } = useTranslation('sidebar', {\n    keyPrefix: 'paymentRequestsSection.noPaymentRequests',\n  });\n\n  const status = seller?.status || buyer?.status;\n  const canCreatePaymentRequests = status === 'ACTIVE';\n\n  return (\n    <Box\n      padding={4}\n      display=\"flex\"\n      flexDirection=\"column\"\n      alignItems=\"center\"\n      bgcolor=\"white\"\n      borderRadius={3}\n      mx={0.5}\n      border={`1px solid ${theme.glo.color.foundations[20]}`}\n    >\n      <Box\n        border={`1px solid ${theme.glo.color.foundations[20]}`}\n        borderRadius={1}\n        position=\"relative\"\n        width={36}\n        height={36}\n        display=\"flex\"\n        justifyContent=\"center\"\n        alignItems=\"center\"\n      >\n        <Icon icon={<MoneyIcon />} style={{ width: '22px', height: '22px' }} />\n      </Box>\n      <Spacer height={1} />\n      <Typography fontSize={13} fontWeight={700} lineHeight=\"16px\">\n        {t('title')}\n      </Typography>\n      <Spacer height={0.5} />\n      <Typography\n        fontSize={13}\n        fontWeight={500}\n        lineHeight=\"16px\"\n        display=\"inline-block\"\n        textAlign=\"center\"\n        maxWidth={280}\n      >\n        {seller != null ? t('descForSellers') : t('descForBuyers')}\n      </Typography>\n      <Spacer height={2} />\n      {canCreatePaymentRequests ? (\n        <Button\n          prefixIcon={<PlusIcon />}\n          variant=\"invisible\"\n          onClick={() => {\n            posthog.capture('clicked-empty-pr-create-new');\n            navigate(b2bPaymentRoutes.createPaymentRequest, {\n              state: { seller, buyer },\n            });\n          }}\n          size=\"s\"\n          data-test-id=\"sme-create-pr-btn\"\n        >\n          {t('btnLabel')}\n        </Button>\n      ) : null}\n    </Box>\n  );\n};\n","import type { PaymentRequest } from '@finmid/distributor-types';\nimport { Divider, SectionContent } from '@finmid/tbl-webapps/components';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { Button } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport posthog from 'posthog-js';\nimport { Fragment } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { PaymentRequestDataRow } from '..';\n\ninterface Props {\n  paymentRequests: PaymentRequest[];\n  buyerId?: string;\n  sellerId?: string;\n}\n\nconst maxPaymentRequestsVisible = 3;\n\nexport const PaymentRequestsTable = ({\n  paymentRequests: allPaymentRequests,\n  buyerId,\n  sellerId,\n}: Props) => {\n  const navigate = useNavigate();\n  const { t } = useTranslation('buyersPage', {\n    keyPrefix: 'sidebar',\n  });\n\n  const paymentRequests = allPaymentRequests.slice(\n    0,\n    maxPaymentRequestsVisible,\n  );\n  const isShowingAll = allPaymentRequests.length <= maxPaymentRequestsVisible;\n\n  const goToPaymentRequestsForBuyerOrSeller = () => {\n    if (buyerId) {\n      posthog.capture('clicked-goto-all-prs-for-buyer');\n      navigate(`${b2bPaymentRoutes.paymentRequests}?buyer=${buyerId}`);\n    }\n\n    if (sellerId) {\n      posthog.capture('clicked-goto-all-prs-for-seller');\n      navigate(`${b2bPaymentRoutes.paymentRequests}?seller=${sellerId}`);\n    }\n  };\n\n  return (\n    <SectionContent\n      disablePadding\n      data-test-id=\"sidebar-payment-requests-table\"\n    >\n      {paymentRequests?.map((paymentRequest, index) => (\n        <Fragment key={paymentRequest.id}>\n          <PaymentRequestDataRow paymentRequest={paymentRequest} />\n          {index !== paymentRequests.length - 1 ? <Divider /> : null}\n        </Fragment>\n      ))}\n      {isShowingAll ? null : (\n        <>\n          <Divider />\n          <Box onClick={goToPaymentRequestsForBuyerOrSeller} padding={1}>\n            <Button variant=\"invisible\" size=\"s\" data-test-id=\"see-all-btn\">\n              {t('allPRBtn', { amount: allPaymentRequests.length })}\n            </Button>\n          </Box>\n        </>\n      )}\n    </SectionContent>\n  );\n};\n","import type { Buyer, PaymentRequest, Seller } from '@finmid/distributor-types';\n\nimport { EmptyPaymentRequests } from './EmptyPaymentRequests';\nimport { PaymentRequestsTable } from './PaymentRequestsTable';\n\ntype BuyerOrSeller =\n  | { buyer: Buyer; seller?: never }\n  | { buyer?: never; seller: Seller };\n\ntype Props = {\n  paymentRequests: PaymentRequest[];\n} & BuyerOrSeller;\n\nexport const PaymentRequestsTab = ({\n  paymentRequests,\n  buyer,\n  seller,\n}: Props) => {\n  const hasPaymentRequests = paymentRequests.length > 0;\n\n  return hasPaymentRequests ? (\n    <PaymentRequestsTable\n      paymentRequests={paymentRequests}\n      buyerId={buyer?.externalId}\n      sellerId={seller?.externalId}\n    />\n  ) : (\n    <EmptyPaymentRequests buyer={buyer} seller={seller} />\n  );\n};\n","import type { PaymentRequest } from '@finmid/distributor-types';\nimport {\n  Divider,\n  Section,\n  SectionContent,\n} from '@finmid/tbl-webapps/components';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { Button } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport posthog from 'posthog-js';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { PaymentRequestDataRow } from '..';\n\nexport const LatestPRSection = ({\n  paymentRequest,\n}: {\n  paymentRequest: PaymentRequest;\n}) => {\n  const navigate = useNavigate();\n  const { t } = useTranslation('buyersPage', {\n    keyPrefix: 'sidebar',\n  });\n\n  const goToPaymentRequestsPage = () => {\n    posthog.capture('clicked-sidebar-latest-pr-details');\n    navigate(`${b2bPaymentRoutes.paymentRequests}?view=${paymentRequest.id}`);\n  };\n\n  return (\n    <Section title={t('latestPaymentRequest')} testId=\"latest-payment-request\">\n      <SectionContent disablePadding>\n        <PaymentRequestDataRow paymentRequest={paymentRequest} />\n        <Divider />\n        <Box onClick={goToPaymentRequestsPage} padding={1}>\n          <Button variant=\"invisible\" size=\"s\">\n            {t('seeDetails')}\n          </Button>\n        </Box>\n      </SectionContent>\n    </Section>\n  );\n};\n","import {\n  Buyer,\n  GetBuyerLimit,\n  GetBuyerTasks,\n  PaymentRequest,\n} from '@finmid/distributor-types';\nimport { createContext, PropsWithChildren, useContext } from 'react';\n\ntype Context = {\n  buyer: Buyer;\n  limitIncreaseRequestInProgress: boolean;\n  limitIncreaseRequestUnderReview: boolean;\n  limitIncreaseRequestCompleted: boolean;\n  tasks: GetBuyerTasks.GatewayResponse;\n  limit: GetBuyerLimit.GatewayResponse;\n  paymentRequests?: PaymentRequest[];\n};\n\nconst initialContext = null;\n\nexport const BuyerDetailsContext = createContext<Context | null>(\n  initialContext,\n);\n\ntype BuyerDetailsContextProviderProps = PropsWithChildren<{\n  buyer: Buyer;\n  tasks: GetBuyerTasks.GatewayResponse;\n  limit: GetBuyerLimit.GatewayResponse;\n  paymentRequests?: PaymentRequest[];\n}>;\n\nexport const BuyerDetailsContextProvider = ({\n  children,\n  buyer,\n  tasks,\n  limit,\n  paymentRequests,\n}: BuyerDetailsContextProviderProps) => {\n  const value: Context = {\n    buyer,\n    limitIncreaseRequestInProgress: tasks.some(\n      (task) => task.status === 'PENDING',\n    ),\n    limitIncreaseRequestUnderReview: tasks.some(\n      (task) => task.status === 'SUBMITTED' || task.status === 'PROCESSING',\n    ),\n    limitIncreaseRequestCompleted: tasks.some(\n      (task) => task.status === 'COMPLETED',\n    ),\n    tasks,\n    limit,\n    paymentRequests,\n  };\n\n  return (\n    <BuyerDetailsContext.Provider value={value}>\n      {children}\n    </BuyerDetailsContext.Provider>\n  );\n};\n\nexport const useBuyerDetailsContext = () => {\n  const context = useContext(BuyerDetailsContext);\n\n  if (context == null) {\n    throw new Error(\n      'useBuyerDetailsContext can only be used inside BuyerDetailsContextProvider Provider',\n    );\n  }\n  return context;\n};\n","import { Buyer } from '@finmid/distributor-types';\nimport {\n  SuspendSmeFormDialog,\n  withErrorProps,\n} from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useSuspendBuyerMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport posthog from 'posthog-js';\nimport { Dispatch, SetStateAction } from 'react';\nimport { useTranslation } from 'react-i18next';\n\ntype SuspendBuyerDialogProps = {\n  buyer: Buyer;\n  open: boolean;\n  setOpen: Dispatch<SetStateAction<boolean>>;\n};\n\nexport const SuspendBuyerDialog = ({\n  buyer,\n  open,\n  setOpen,\n}: SuspendBuyerDialogProps) => {\n  const { t } = useTranslation('buyersPage', {\n    keyPrefix: 'suspendBuyer',\n  });\n  const { legalName: buyerLegalName, externalId } = buyer;\n  const [suspendBuyer, { isLoading }] = useSuspendBuyerMutation();\n  const { notifySuccess } = useNotifications();\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const handleSuspendBuyer = async (reason: string) => {\n    posthog.capture('clicked_suspend_buyer_confirm');\n\n    try {\n      await suspendBuyer({ externalId, reason }).unwrap();\n      notifySuccess(t('successMessage', { buyerLegalName }));\n    } catch (error) {\n      displayErrorToast(\n        withErrorProps({\n          ...(error as Error),\n          message: t('errorMessage', { buyerLegalName }),\n        }),\n      );\n    }\n  };\n\n  return (\n    <SuspendSmeFormDialog\n      message={t('message', { buyerLegalName })}\n      open={open}\n      title={t('title')}\n      handleSuspend={(reason: string) => handleSuspendBuyer(reason)}\n      setOpen={setOpen}\n      isProcessing={isLoading}\n    />\n  );\n};\n","import { Buyer } from '@finmid/distributor-types';\nimport { MenuItem, Tooltip } from '@finmid/ui/ocarina';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { SuspendBuyerDialog } from './SuspendBuyerDialog';\n\ntype Props = {\n  buyer: Buyer;\n};\n\nexport const SuspendBuyerMenuItem = ({ buyer }: Props) => {\n  const { t } = useTranslation('buyersPage', {\n    keyPrefix: 'actions.suspendBuyer',\n  });\n  const [open, setOpen] = useState(false);\n\n  const buyerIsDisabled = ['SUSPENDED', 'REJECTED'].includes(buyer.status);\n\n  return (\n    <>\n      <Tooltip\n        title={\n          buyerIsDisabled\n            ? t('tooltip.buyerStatus', { status: buyer.status.toLowerCase() })\n            : ''\n        }\n        placement=\"left\"\n      >\n        <MenuItem\n          onClick={() => {\n            posthog.capture('clicked-buyer-sidebar-suspend');\n            setOpen(true);\n          }}\n          data-test-id=\"suspend-buyer-menu-item\"\n          disabled={buyerIsDisabled}\n        >\n          {t('btnLabel')}\n        </MenuItem>\n      </Tooltip>\n      <SuspendBuyerDialog buyer={buyer} open={open} setOpen={setOpen} />\n    </>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { FormTextField, Typography } from '@finmid/tbl-webapps/components';\nimport { currencySymbols } from '@finmid/tbl-webapps/utils';\nimport { useFormat } from '@finmid/translations';\nimport { Spacer, TextInput } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { Controller, FormProvider, UseFormReturn } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\nimport { NumericFormat } from 'react-number-format';\n\nimport { useBuyerDetailsContext } from '../../../../../../../context';\n\nexport type RequestLimitFormValues = {\n  reason: string;\n  desiredAmount: string;\n};\n\ntype InfosStepProps = {\n  // eslint-disable-next-line @typescript-eslint/no-explicit-any\n  methods: UseFormReturn<RequestLimitFormValues, any, undefined>;\n};\n\nexport const InfosStep = ({ methods }: InfosStepProps) => {\n  const theme = useTheme();\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'limitIncrease' });\n  const { buyer, limit } = useBuyerDetailsContext();\n  const { money } = useFormat();\n\n  const { control } = methods;\n\n  return (\n    <Box\n      mt={1}\n      borderRadius={3}\n      border={`1px solid ${theme.glo.color.foundations[20]}`}\n      padding={2}\n    >\n      <form>\n        <FormProvider {...methods}>\n          <Typography\n            color={theme.glo.color.foundations[70]}\n            fontSize={15}\n            lineHeight=\"20px\"\n          >\n            {t('fieldReasonLabel')}\n          </Typography>\n          <Spacer height={2} />\n          <FormTextField\n            control={control}\n            name=\"reason\"\n            placeholder={t('fieldReasonPlaceholder')}\n            fullWidth\n          />\n          <Spacer height={3} />\n          <Typography\n            color={theme.glo.color.foundations[70]}\n            fontSize={15}\n            lineHeight=\"20px\"\n          >\n            {t('fieldDesiredAmountLabel', { legalName: buyer.legalName })}\n          </Typography>\n          <Spacer height={0.5} />\n          <Typography\n            color={theme.glo.color.foundations[50]}\n            fontSize={13}\n            lineHeight=\"16px\"\n          >\n            {t('currentLimit', {\n              limit: money(limit.totalLimit, limit.currency),\n            })}\n          </Typography>\n          <Spacer height={1.5} />\n          <Controller\n            control={control}\n            name=\"desiredAmount\"\n            render={({ field }) => {\n              const { onChange, ref, ...rest } = field;\n              return (\n                <NumericFormat\n                  decimalScale={2}\n                  thousandSeparator\n                  fixedDecimalScale\n                  testId={`desiredAmountField`}\n                  customInput={TextInput}\n                  onValueChange={(v) => {\n                    onChange(v.floatValue?.toString(10));\n                  }}\n                  startAdornment={currencySymbols[limit.currency]}\n                  placeholder={t('fieldDesiredAmountPlaceholder')}\n                  fullWidth\n                  {...rest}\n                />\n              );\n            }}\n          />\n        </FormProvider>\n      </form>\n    </Box>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport { File, Typography } from '@finmid/tbl-webapps/components';\nimport { MAX_FILES } from '@finmid/tbl-webapps/components/DocumentsUpload/utils/constants';\nimport { Button } from '@finmid/ui/ocarina';\nimport { AddSharp } from '@mui/icons-material';\nimport { Box } from '@mui/material';\nimport { ChangeEvent, Dispatch, Fragment, SetStateAction, useRef } from 'react';\n\ntype AddFilesProps = {\n  files: File[];\n  onAdd: (acceptedFiles: FileList) => void;\n  setFiles: Dispatch<SetStateAction<File[]>>;\n};\n\nexport const AddFiles = ({ files, onAdd, setFiles }: AddFilesProps) => {\n  const theme = useTheme();\n  const fileInputRef = useRef<HTMLInputElement>(null);\n\n  const removeFile = (index: number) => {\n    setFiles(files.filter((_, i) => i !== index));\n  };\n\n  const handleOpenFilesBrowser = () => {\n    if (fileInputRef.current) {\n      fileInputRef.current.click();\n    }\n  };\n\n  const handleFilesChange = (event: ChangeEvent<HTMLInputElement>) => {\n    const files = event.target.files;\n    if (files != null && files.length > 0) {\n      onAdd(files);\n    }\n  };\n\n  return (\n    <>\n      <Typography\n        color={theme.glo.color.foundations[60]}\n        fontSize={13}\n        fontWeight={500}\n        lineHeight=\"16px\"\n      >\n        Documents uploaded\n      </Typography>\n\n      <Box display=\"flex\" flexDirection=\"column\" gap={1} width=\"100%\">\n        {files.map((file, index) => (\n          <Fragment key={file.name + index}>\n            <File file={file} onRemove={() => removeFile(index)} />\n          </Fragment>\n        ))}\n      </Box>\n\n      <Button\n        prefixIcon={<AddSharp fontSize=\"small\" />}\n        variant=\"invisible\"\n        size=\"s\"\n        onClick={handleOpenFilesBrowser}\n        disabled={files.length >= MAX_FILES}\n      >\n        Add more documents\n      </Button>\n      <input\n        ref={fileInputRef}\n        onChange={handleFilesChange}\n        type=\"file\"\n        accept=\"image/png, image/jpeg, image/jpg, application/pdf\"\n        multiple\n        style={{ display: 'none' }}\n      />\n    </>\n  );\n};\n","import { useUploadBuyerDocumentsMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { humanReadableFileSize } from '@finmid/tbl-webapps/utils';\nimport posthog from 'posthog-js';\nimport { useEffect, useState } from 'react';\nimport { FileRejection } from 'react-dropzone';\nimport { useTranslation } from 'react-i18next';\n\nimport { useBuyerDetailsContext } from '../../../../../../../context';\n\nconst checkTooManyFiles = ({\n  currentFilesLength,\n  newFilesLength,\n}: {\n  currentFilesLength: number;\n  newFilesLength: number;\n}) => currentFilesLength + newFilesLength > MAX_FILES;\n\nconst checkFilesAreNotUnique = ({\n  files,\n  newFiles,\n}: {\n  files: File[];\n  newFiles: File[];\n}) => {\n  const duplicatedFiles: string[] = [];\n  const newFilesNames = newFiles.map((f) => f.name);\n  files.forEach((f) => {\n    if (newFilesNames.includes(f.name)) {\n      duplicatedFiles.push(f.name);\n    }\n  });\n  return duplicatedFiles;\n};\n\ntype UseUploadDocumentsStepProps = {\n  onClose: () => void;\n};\n\nexport const MAX_FILE_SIZE = 15728640; // 15 MB\nexport const MAX_FILES = 20;\n\nexport const useUploadDocumentsStep = ({\n  onClose,\n}: UseUploadDocumentsStepProps) => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'documentUpload' });\n  const { notifyError, notifySuccess } = useNotifications();\n  const {\n    buyer: { externalId },\n  } = useBuyerDetailsContext();\n  const [uploadBuyerDocuments, { isLoading }] =\n    useUploadBuyerDocumentsMutation();\n  const [files, setFiles] = useState<File[]>([]);\n  const [fileErrors, setFileErrors] = useState<FileRejection[]>([]);\n  const [tooManyFiles, setTooManyFiles] = useState(false);\n\n  useEffect(() => {\n    setTooManyFiles(files.length > MAX_FILES);\n    if (files.length === 0) setFileErrors([]);\n  }, [files.length]);\n\n  const handleUpload = async () => {\n    posthog.capture('limit-increase-documents-upload');\n    const { error } = await uploadBuyerDocuments({ externalId, files });\n    if (error) {\n      notifyError(t('errorUploadingFiles'));\n    } else {\n      onClose();\n      notifySuccess(t('successUploadingFiles'));\n    }\n  };\n\n  const onAdd = async (fileList: FileList) => {\n    posthog.capture('limit-increase-documents-add-file');\n\n    const fileListLength = fileList.length;\n    const tooManyFiles = checkTooManyFiles({\n      currentFilesLength: files.length,\n      newFilesLength: fileListLength,\n    });\n    if (tooManyFiles) {\n      setTooManyFiles(tooManyFiles);\n      return;\n    }\n\n    const newFiles: File[] = new Array<File>();\n    for (let i = 0; i < fileListLength; i++) {\n      const file = fileList.item(i);\n      if (file != null) {\n        if (file.size > MAX_FILE_SIZE) {\n          notifyError(\n            t('file.tooLarge', {\n              maxSize: humanReadableFileSize(MAX_FILE_SIZE),\n            }),\n          );\n          return;\n        }\n        newFiles[i] = file;\n      }\n    }\n    const duplicatedFiles = checkFilesAreNotUnique({ files, newFiles });\n    if (duplicatedFiles.length > 0) {\n      notifyError(`Duplicated files: ${duplicatedFiles.join(',')}`);\n      return;\n    }\n    setFiles((f) => [...f, ...newFiles]);\n  };\n\n  const onDrop = async (newFiles: File[], rejectedFiles: FileRejection[]) => {\n    setFiles((f) => [...f, ...newFiles]);\n    setFileErrors(rejectedFiles);\n  };\n\n  const isValid = files.length > 0 && fileErrors.length === 0 && !tooManyFiles;\n\n  return {\n    actionsProps: {\n      isValid,\n      onSubmit: handleUpload,\n    },\n    dialogProps: {\n      files,\n      tooManyFiles,\n      fileErrors,\n      isLoading,\n      onAdd,\n      onDrop,\n      setFiles,\n    },\n  };\n};\n","import {\n  DropzoneArea,\n  DropzoneEmptyState,\n} from '@finmid/tbl-webapps/components';\nimport { LoaderCircle } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport Dropzone, { FileRejection } from 'react-dropzone';\n\nimport { MAX_FILE_SIZE, MAX_FILES } from '../../hooks/UploadDocumentsStep.hook';\n\ntype InitialFilesDropProps = {\n  isLoading: boolean;\n  onDrop: (acceptedFiles: File[], fileRejections: FileRejection[]) => void;\n};\n\nexport const InitialFilesDrop = ({\n  isLoading,\n  onDrop,\n}: InitialFilesDropProps) => {\n  return (\n    <Dropzone\n      useFsAccessApi={false}\n      onDrop={onDrop}\n      accept={{\n        'image/jpg': ['.jpg', '.jpeg'],\n        'image/png': ['.png'],\n        'application/pdf': ['.pdf'],\n      }}\n      maxFiles={MAX_FILES}\n      maxSize={MAX_FILE_SIZE}\n    >\n      {({ getRootProps, getInputProps }) => (\n        <DropzoneArea {...getRootProps()}>\n          <input {...getInputProps()} data-test-id=\"drop-files-input\" />\n          <Box\n            display=\"flex\"\n            flexDirection=\"column\"\n            alignItems=\"center\"\n            textAlign=\"center\"\n            data-test-id=\"drop-files-box\"\n          >\n            {isLoading ? <LoaderCircle /> : <DropzoneEmptyState />}\n          </Box>\n        </DropzoneArea>\n      )}\n    </Dropzone>\n  );\n};\n","import { useTheme } from '@emotion/react';\nimport {\n  InvalidFilesAlerts,\n  TooManyFilesAlert,\n  Typography,\n} from '@finmid/tbl-webapps/components';\nimport { Banner } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { Dispatch, SetStateAction } from 'react';\nimport { FileRejection } from 'react-dropzone';\nimport { Trans, useTranslation } from 'react-i18next';\n\nimport { AddFiles } from './AddFiles';\nimport { InitialFilesDrop } from './InitialFilesDrop';\n\ntype UploadDocumentsStepProps = {\n  tooManyFiles: boolean;\n  fileErrors: FileRejection[];\n  files: File[];\n  isLoading: boolean;\n  onAdd: (acceptedFiles: FileList) => void;\n  onDrop: (acceptedFiles: File[], fileRejections: FileRejection[]) => void;\n  setFiles: Dispatch<SetStateAction<File[]>>;\n};\n\nexport const UploadDocumentsStep = ({\n  tooManyFiles,\n  fileErrors,\n  files,\n  isLoading,\n  onAdd,\n  onDrop,\n  setFiles,\n}: UploadDocumentsStepProps) => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'limitIncrease' });\n  const theme = useTheme();\n\n  const hasAddedFiles = files.length > 0;\n\n  return (\n    <Box\n      mt={1}\n      borderRadius={3}\n      border={`1px solid ${theme.glo.color.foundations[20]}`}\n      overflow=\"hidden\"\n    >\n      <Box\n        height={340}\n        padding={2}\n        display=\"flex\"\n        flexDirection=\"column\"\n        alignItems=\"flex-start\"\n        justifyContent=\"stretch\"\n        gap={2}\n        sx={{\n          overflowY: 'auto',\n        }}\n      >\n        <Typography\n          color={theme.glo.color.foundations[60]}\n          fontSize={15}\n          lineHeight=\"20px\"\n        >\n          {t('additionalDocsDescription')}\n        </Typography>\n\n        {hasAddedFiles ? (\n          <AddFiles files={files} setFiles={setFiles} onAdd={onAdd} />\n        ) : (\n          <InitialFilesDrop isLoading={isLoading} onDrop={onDrop} />\n        )}\n\n        {tooManyFiles ? <TooManyFilesAlert /> : null}\n\n        {fileErrors.length > 0 ? (\n          <InvalidFilesAlerts fileErrors={fileErrors} />\n        ) : null}\n\n        <Banner variant=\"info\" size=\"large\">\n          <Trans\n            t={t}\n            i18nKey=\"uploadLaterBanner\"\n            components={{\n              strong: <strong />,\n            }}\n          />\n        </Banner>\n      </Box>\n    </Box>\n  );\n};\n","import { Button } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\ntype InfosStepButtonsProps = {\n  isLoading: boolean;\n  isValid: boolean;\n  handleClose: () => void;\n  onSubmit: (e?: React.BaseSyntheticEvent) => Promise<void>;\n};\n\nexport const InfosStepButtons = ({\n  isLoading,\n  isValid,\n  handleClose,\n  onSubmit,\n}: InfosStepButtonsProps) => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'limitIncrease' });\n\n  return (\n    <>\n      <Button\n        variant=\"primary\"\n        type=\"submit\"\n        disabled={!isValid || isLoading}\n        onClick={onSubmit}\n        data-test-id=\"submit-increase-request\"\n      >\n        {t('submitBtn')}\n      </Button>\n      <Button variant=\"invisible\" disabled={isLoading} onClick={handleClose}>\n        {t('cancelBtn')}\n      </Button>\n    </>\n  );\n};\n\ntype UploadDocumentsButtonsProps = {\n  isValid: boolean;\n  handleClose: () => void;\n  onSubmit: () => void;\n};\n\nexport const UploadDocumentsStepButtons = ({\n  isValid,\n  handleClose,\n  onSubmit,\n}: UploadDocumentsButtonsProps) => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'limitIncrease' });\n\n  return (\n    <>\n      <Button\n        variant=\"primary\"\n        type=\"submit\"\n        disabled={!isValid}\n        onClick={onSubmit}\n        data-test-id=\"submit-documents-button\"\n      >\n        {t('submitDocsBtn')}\n      </Button>\n      <Button\n        variant=\"invisible\"\n        onClick={handleClose}\n        data-test-id=\"cancel-upload-button\"\n      >\n        {t('skipUploadBtn')}\n      </Button>\n    </>\n  );\n};\n","import { TWO_DECIMAL_REGEX } from '@finmid/tbl-webapps/utils';\nimport { useFormat } from '@finmid/translations';\nimport currencyjs from 'currency.js';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport * as yup from 'yup';\n\nimport { useBuyerDetailsContext } from '../../../../../../../context';\n\nexport const useInfosStepFormValidationSchema = () => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'limitIncrease' });\n  const { money } = useFormat();\n  const {\n    limit: { totalLimit, currency },\n  } = useBuyerDetailsContext();\n\n  const schema = useMemo(\n    () =>\n      yup.object().shape({\n        reason: yup.string().required(t('reasonRequired')),\n        desiredAmount: yup\n          .string()\n          .test(\n            'thousands-separator-comma',\n            t('thousandsSeparatorComma'),\n            (value: string | undefined) => {\n              if (value != null) {\n                return !value.includes(',');\n              }\n              return true;\n            },\n          )\n          .test(\n            'positive',\n            t('amountPositive'),\n            (value: string | undefined) => {\n              if (Number(value) > 0) {\n                return true;\n              } else {\n                return false;\n              }\n            },\n          )\n          .test(\n            'max-two-decimal',\n            t('maxTwoDigits'),\n            (value: string | undefined) => {\n              if (value != null) {\n                return TWO_DECIMAL_REGEX.test(value);\n              }\n              return true;\n            },\n          )\n          .test(\n            'greater than buyer-limit',\n            t('desiredAmountGreaterThanCurrentLimit', {\n              currentLimit: money(currencyjs(totalLimit), currency),\n            }),\n            (val) => {\n              if (val) {\n                return parseFloat(val) > totalLimit;\n              }\n              return true;\n            },\n          )\n          .required(t('desiredAmountRequired')),\n      }),\n    [t, money, totalLimit, currency],\n  );\n\n  return schema;\n};\n","import { useRequestLimitIncreaseMutation } from '@finmid/tbl-webapps/gateway-api';\nimport {\n  useDistributorCurrencies,\n  useNotifications,\n} from '@finmid/tbl-webapps/hooks';\nimport { yupResolver } from '@hookform/resolvers/yup';\nimport posthog from 'posthog-js';\nimport { Dispatch, SetStateAction, useEffect } from 'react';\nimport { useForm } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { useBuyerDetailsContext } from '../../../../../../../context';\nimport { type RequestLimitIncreaseDialogSteps } from '../RequestLimitIncreaseDialog.types';\n\nimport { useInfosStepFormValidationSchema } from './InfosStepForm.schema';\n\ntype RequestLimitFormValues = {\n  reason: string;\n  desiredAmount: string;\n};\n\ntype UseInfosStepFormProps = {\n  setStep: Dispatch<SetStateAction<RequestLimitIncreaseDialogSteps>>;\n  setOpen: Dispatch<SetStateAction<boolean>>;\n};\n\nexport const useInfosStepForm = ({\n  setStep,\n  setOpen,\n}: UseInfosStepFormProps) => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'limitIncrease' });\n  const { defaultCurrency } = useDistributorCurrencies();\n  const { notifyError, notifySuccess } = useNotifications();\n  const { buyer } = useBuyerDetailsContext();\n  const validationSchema = useInfosStepFormValidationSchema();\n  const [\n    requestLimitIncrease,\n    {\n      error: limitIncreaseRequestError,\n      isLoading: limitIncreaseRequestIsLoading,\n    },\n  ] = useRequestLimitIncreaseMutation();\n\n  useEffect(() => {\n    if (limitIncreaseRequestError) {\n      notifyError();\n    }\n  }, [limitIncreaseRequestError, notifyError]);\n\n  const methods = useForm<RequestLimitFormValues>({\n    resolver: yupResolver(validationSchema),\n    defaultValues: { reason: '', desiredAmount: '' },\n    mode: 'onChange',\n  });\n\n  const handleSubmitForm = async ({\n    reason,\n    desiredAmount,\n  }: RequestLimitFormValues) => {\n    posthog.capture('request_limit_increase_buyer');\n    const response = await requestLimitIncrease({\n      reason,\n      newLimitAmount: Number(desiredAmount),\n      currency: defaultCurrency,\n      externalId: buyer.externalId,\n    }).unwrap();\n    if (response.instantApproval) {\n      notifySuccess(t('approved', { buyer: buyer.legalName }));\n      setOpen(false);\n    } else {\n      setStep('UPLOAD_DOCS');\n    }\n  };\n\n  const onSubmit = methods.handleSubmit(handleSubmitForm);\n\n  return {\n    actionsProps: {\n      isLoading: limitIncreaseRequestIsLoading,\n      isValid: methods.formState.isValid,\n      onSubmit,\n    },\n    methods,\n    onSubmit,\n  };\n};\n","import { useLazyGetBuyerTasksQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { Dispatch, SetStateAction, useState } from 'react';\n\nimport { useBuyerDetailsContext } from '../../../../../../../context';\nimport { RequestLimitIncreaseDialogSteps } from '../RequestLimitIncreaseDialog.types';\n\nimport { useInfosStepForm } from './InfosStepForm.hook';\nimport { useUploadDocumentsStep } from './UploadDocumentsStep.hook';\n\ntype UseRequestLimitIncreaseDialogProps = {\n  setOpen: Dispatch<SetStateAction<boolean>>;\n};\n\nexport const useRequestLimitIncreaseDialog = ({\n  setOpen,\n}: UseRequestLimitIncreaseDialogProps) => {\n  const [step, setStep] = useState<RequestLimitIncreaseDialogSteps>('FORM');\n  const { buyer } = useBuyerDetailsContext();\n  const [fetchBuyerTasks] = useLazyGetBuyerTasksQuery();\n\n  const { actionsProps: infosActionsProps, methods } = useInfosStepForm({\n    setStep,\n    setOpen,\n  });\n\n  const handleClose = () => {\n    void fetchBuyerTasks({ externalId: buyer.externalId });\n    methods.reset();\n    setStep('FORM');\n    setOpen(false);\n  };\n\n  const { actionsProps: uploadActionsProps, dialogProps: uploadDialogProps } =\n    useUploadDocumentsStep({ onClose: handleClose });\n\n  return {\n    uploadActionsProps,\n    uploadDialogProps,\n    infosActionsProps,\n    methods,\n    step,\n    handleClose,\n    setStep,\n  };\n};\n","import { Dialog } from '@finmid/tbl-webapps/components';\nimport { Dispatch, SetStateAction } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useBuyerDetailsContext } from '../../../../../../context';\n\nimport {\n  InfosStep,\n  InfosStepButtons,\n  UploadDocumentsStep,\n  UploadDocumentsStepButtons,\n} from './components';\nimport { useRequestLimitIncreaseDialog } from './hooks/RequestLimitIncreaseDialog.hook';\n\ntype RequestLimitIncreaseDialogProps = {\n  open: boolean;\n  setOpen: Dispatch<SetStateAction<boolean>>;\n};\n\nexport const RequestLimitIncreaseDialog = ({\n  open,\n  setOpen,\n}: RequestLimitIncreaseDialogProps) => {\n  const { buyer } = useBuyerDetailsContext();\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'limitIncrease' });\n\n  const {\n    uploadActionsProps,\n    uploadDialogProps,\n    infosActionsProps,\n    methods,\n    step,\n    handleClose,\n  } = useRequestLimitIncreaseDialog({ setOpen });\n\n  return (\n    <Dialog\n      open={open}\n      actions={\n        step === 'FORM' ? (\n          <InfosStepButtons {...infosActionsProps} handleClose={handleClose} />\n        ) : (\n          <UploadDocumentsStepButtons\n            {...uploadActionsProps}\n            handleClose={handleClose}\n          />\n        )\n      }\n      title={\n        step === 'FORM'\n          ? t('dialogTitle', { legalName: buyer.legalName })\n          : t('dialogTitleUploadDocs')\n      }\n      onClose={handleClose}\n      PaperProps={{ style: { width: '640px' }, elevation: 2 }}\n      data-test-id=\"limit-increase-dialog\"\n    >\n      {step === 'FORM' ? <InfosStep methods={methods} /> : null}\n      {step === 'UPLOAD_DOCS' ? (\n        <UploadDocumentsStep {...uploadDialogProps} />\n      ) : null}\n    </Dialog>\n  );\n};\n","import { MenuItem, Tooltip } from '@finmid/ui/ocarina';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useBuyerDetailsContext } from '../../../../../context';\n\nimport { RequestLimitIncreaseDialog } from './RequestLimitIncreaseDialog';\n\nexport const IncreaseLimitMenuItem = () => {\n  const { t } = useTranslation('buyersPage', {\n    keyPrefix: 'actions.limitIncrease',\n  });\n  const [open, setOpen] = useState(false);\n\n  const {\n    buyer,\n    limitIncreaseRequestInProgress,\n    limitIncreaseRequestUnderReview,\n  } = useBuyerDetailsContext();\n\n  const disabled =\n    buyer.status !== 'ACTIVE' ||\n    limitIncreaseRequestInProgress ||\n    limitIncreaseRequestUnderReview;\n\n  const tooltip =\n    limitIncreaseRequestUnderReview || limitIncreaseRequestInProgress\n      ? t('tooltip.existingLimitRequest')\n      : t('tooltip.buyerStatus');\n\n  return (\n    <>\n      <Tooltip title={disabled ? tooltip : ''} placement=\"left\">\n        <MenuItem\n          onClick={() => {\n            posthog.capture('clicked_limit-increase-menu-item');\n            setOpen(true);\n          }}\n          data-test-id=\"limit-increase-menu-item\"\n          disabled={disabled}\n        >\n          {t('btnLabel')}\n        </MenuItem>\n      </Tooltip>\n      <RequestLimitIncreaseDialog open={open} setOpen={setOpen} />\n    </>\n  );\n};\n","import { Buyer } from '@finmid/distributor-types';\nimport { sharedTblRoutes } from '@finmid/tbl-webapps/routes';\nimport { MenuItem, Tooltip } from '@finmid/ui/ocarina';\nimport posthog from 'posthog-js';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\ntype Props = {\n  buyer: Buyer;\n};\n\nexport const EditBuyerMenuItem = ({ buyer }: Props) => {\n  const { t } = useTranslation('buyersPage', {\n    keyPrefix: 'actions.editBuyer',\n  });\n  const navigate = useNavigate();\n\n  const navigateToEditPage = () => {\n    posthog.capture('clicked-buyer-sidebar-edit');\n\n    navigate(`${sharedTblRoutes.buyers}/${buyer.externalId}/edit`, {\n      state: { buyer },\n    });\n  };\n\n  const disabled = buyer.status !== 'PENDING';\n\n  return (\n    <Tooltip title={disabled ? t('tooltip.buyerStatus') : ''} placement=\"left\">\n      <MenuItem\n        onClick={navigateToEditPage}\n        disabled={disabled}\n        data-test-id=\"edit-buyer-menu-item\"\n      >\n        {t('btnLabel')}\n      </MenuItem>\n    </Tooltip>\n  );\n};\n","import { Buyer } from '@finmid/distributor-types';\nimport { CreatePaymentRequestMenuItem } from '@finmid/tbl-webapps/payment-requests';\nimport {\n  Dropdown,\n  Menu,\n  MenuIconButton,\n  MenuSection,\n  MoreVerticalIcon,\n} from '@finmid/ui/ocarina';\n\nimport {\n  EditBuyerMenuItem,\n  IncreaseLimitMenuItem,\n  SuspendBuyerMenuItem,\n} from './components';\n\ntype Props = {\n  buyer: Buyer;\n};\n\nexport const BuyerActions = ({ buyer }: Props) => {\n  return (\n    <Dropdown>\n      <MenuIconButton\n        icon={<MoreVerticalIcon />}\n        variant=\"invisible\"\n        data-test-id=\"buyer-actions-menu-button\"\n      />\n      <Menu\n        placement=\"bottom-end\"\n        data-test-id=\"menu-kebab\"\n        style={{ zIndex: 1400 }}\n      >\n        <MenuSection>\n          <IncreaseLimitMenuItem />\n        </MenuSection>\n        <MenuSection>\n          <EditBuyerMenuItem buyer={buyer} />\n        </MenuSection>\n        <MenuSection>\n          <SuspendBuyerMenuItem buyer={buyer} />\n        </MenuSection>\n        <MenuSection>\n          <CreatePaymentRequestMenuItem buyer={buyer} />\n        </MenuSection>\n      </Menu>\n    </Dropdown>\n  );\n};\n","import { getCountry } from '@finmid/countries';\nimport { ProfileDetails } from '@finmid/tbl-webapps/components';\nimport { useFormat } from '@finmid/translations';\nimport { useTranslation } from 'react-i18next';\n\nimport { useBuyerDetailsContext } from '../../../../context';\n\nexport const BuyerDetailsTab = () => {\n  const { buyer, limit } = useBuyerDetailsContext();\n  const { t } = useTranslation(['buyersPage', 'sidebar']);\n  const { money } = useFormat();\n  const country =\n    getCountry(buyer.legalAddress.country)?.name ?? buyer.legalAddress.country;\n\n  return (\n    <ProfileDetails\n      sections={[\n        {\n          testId: 'sme-details',\n          lists: [\n            {\n              items: [\n                {\n                  label: t('sidebar.buyerName'),\n                  value: buyer.legalName,\n                  detail: buyer.externalId,\n                },\n                {\n                  label: t('sidebar.regNo'),\n                  value: buyer.businessRegistrationNumber,\n                },\n                {\n                  label: t('sidebar.taxNo'),\n                  value: buyer.taxNumber,\n                },\n                {\n                  label: t('sidebar.expenseLimit'),\n                  value: money(limit.totalLimit, limit.currency),\n                  'data-amount': limit.totalLimit,\n                },\n                {\n                  label: t('sidebar.availableFunds'),\n                  value: money(limit.availableLimit, limit.currency),\n                  'data-amount': limit.availableLimit,\n                },\n              ],\n            },\n          ],\n        },\n        {\n          testId: 'contact-information',\n          title: t('contactInfo', { ns: 'sidebar' }),\n          lists: [\n            {\n              items: [\n                {\n                  label: t('sidebar.email'),\n                  value: buyer.email,\n                },\n                {\n                  label: t('sidebar.phnNo'),\n                  value: buyer.phone,\n                },\n                {\n                  label: t('sidebar.address'),\n                  value: buyer.legalAddress.addressLine1,\n                  detail: `${buyer.legalAddress.city}, ${country} ${buyer.legalAddress.postalCode}`,\n                },\n              ],\n            },\n          ],\n        },\n      ]}\n    />\n  );\n};\n","import { SectionContainer } from '@finmid/tbl-webapps/components';\nimport {\n  ButtonsTabs,\n  PaymentRequestsTab,\n} from '@finmid/tbl-webapps/payment-requests';\nimport Box from '@mui/material/Box';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useBuyerDetailsContext } from '../../../../context';\n\nimport { BuyerDetailsTab } from './BuyerDetailsTab';\n\ntype Tab = 'DETAILS' | 'PAYMENT_REQUEST';\n\nexport const BuyerDetailsSection = () => {\n  const { paymentRequests = [], buyer } = useBuyerDetailsContext();\n\n  const [tab, setTab] = useState<Tab>('DETAILS');\n  const { t } = useTranslation('sidebar');\n  const buttons = [\n    {\n      label: t('details'),\n      onClick: () => {\n        posthog.capture('clicked-buyer-sidebar-details-tab');\n        setTab('DETAILS');\n      },\n      testId: 'buyer-details-sidebar-details-button',\n    },\n    {\n      label: t('paymentRequests'),\n      onClick: () => {\n        posthog.capture('clicked-buyer-sidebar-payment-requests-tab');\n        setTab('PAYMENT_REQUEST');\n      },\n      testId: 'buyer-details-sidebar-payment-request-button',\n    },\n  ];\n\n  let tabElement = null;\n  switch (tab) {\n    case 'DETAILS':\n      tabElement = <BuyerDetailsTab />;\n      break;\n    case 'PAYMENT_REQUEST':\n      tabElement = (\n        <PaymentRequestsTab paymentRequests={paymentRequests} buyer={buyer} />\n      );\n      break;\n  }\n\n  return (\n    <SectionContainer\n      className=\"section-container\"\n      data-test-id=\"buyer-details\"\n    >\n      <Box mx={0.5}>\n        <ButtonsTabs fullWidth buttons={buttons} />\n      </Box>\n      {tabElement}\n    </SectionContainer>\n  );\n};\n","import { DrawerAlert, Task } from '@finmid/tbl-webapps/components';\nimport { sharedTblRoutes } from '@finmid/tbl-webapps/routes';\nimport { Spacer, UploadIcon } from '@finmid/ui/ocarina';\nimport { Trans, useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useBuyerDetailsContext } from '../../../context';\n\nexport const BuyerTaskSection = () => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'sidebar' });\n  const navigate = useNavigate();\n  const { buyer, tasks, limitIncreaseRequestUnderReview } =\n    useBuyerDetailsContext();\n  const pendingDocTask = tasks.find(\n    (task) => task.status === 'PENDING' && task.type === 'DOCUMENTS_REQUIRED',\n  );\n\n  const goToDocUpload = () => {\n    navigate(\n      `${sharedTblRoutes.buyers}/${pendingDocTask?.buyerExternalId}/upload`,\n    );\n  };\n\n  if (limitIncreaseRequestUnderReview) {\n    return (\n      <>\n        <DrawerAlert testId=\"limit-request-under-review-alert\">\n          <Trans\n            t={t}\n            i18nKey=\"limitIncreaseInProgress\"\n            components={{\n              a: (\n                <a\n                  href=\"mailto:support@finmid.com\"\n                  style={{\n                    textDecoration: 'none',\n                    color: 'inherit',\n                  }}\n                >\n                  support@finmid.com\n                </a>\n              ),\n            }}\n            values={{\n              legalName: buyer.legalName,\n            }}\n          />\n        </DrawerAlert>\n        <Spacer height={2} />\n      </>\n    );\n  }\n\n  if (pendingDocTask) {\n    return (\n      <>\n        <Task\n          id={buyer.externalId}\n          creationTime={pendingDocTask.taskCreationTime}\n          icon={<UploadIcon />}\n          onClick={goToDocUpload}\n          actionLabel={t('uploadNow')}\n          style={{ marginLeft: 0, marginRight: 0, flexShrink: 0 }}\n        >\n          <strong>{t('documentsRequired')}</strong>\n        </Task>\n        <Spacer height={2} />\n      </>\n    );\n  }\n\n  return null;\n};\n","import {\n  useGetBuyerByIdQuery,\n  useGetBuyerLimitQuery,\n  useGetBuyersPaymentRequestsQuery,\n  useGetBuyerTasksQuery,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { useDistributorCurrencies } from '@finmid/tbl-webapps/hooks';\n\nexport const useGetBuyerDetails = (externalBuyerId: string) => {\n  const { defaultCurrency } = useDistributorCurrencies();\n\n  const {\n    data: buyer,\n    isFetching: isFetchingBuyer,\n    error: errorBuyer,\n  } = useGetBuyerByIdQuery({\n    externalId: externalBuyerId ?? '',\n    scope: 'AGGREGATED',\n  });\n\n  const {\n    data: paymentRequests,\n    isFetching: isFetchingPaymentRequests,\n    error: errorPaymentRequests,\n  } = useGetBuyersPaymentRequestsQuery({ externalId: externalBuyerId ?? '' });\n\n  const {\n    data: limit,\n    isFetching: isFetchingLimit,\n    error: errorLimit,\n  } = useGetBuyerLimitQuery({\n    externalId: externalBuyerId ?? '',\n    currency: defaultCurrency,\n  });\n\n  const {\n    data: tasks = [],\n    isFetching: isFetchingBuyerTasks,\n    error: errorTasks,\n  } = useGetBuyerTasksQuery({\n    externalId: externalBuyerId ?? '',\n  });\n\n  return {\n    data: {\n      buyer,\n      paymentRequests,\n      limit,\n      tasks,\n    },\n    error: errorBuyer || errorPaymentRequests || errorLimit || errorTasks,\n    isFetching:\n      isFetchingBuyer ||\n      isFetchingPaymentRequests ||\n      isFetchingLimit ||\n      isFetchingBuyerTasks,\n  };\n};\n","import {\n  Drawer,\n  ProfileStatusSection,\n  SmeStatusDrawerAlert,\n  ZeroState,\n} from '@finmid/tbl-webapps/components';\nimport { LatestPRSection } from '@finmid/tbl-webapps/payment-requests';\nimport { Button, Loader, Spacer } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport { BuyerDetailsContextProvider } from '../../context';\n\nimport {\n  BuyerActions,\n  BuyerDetailsSection,\n  BuyerTaskSection,\n} from './components';\nimport { useGetBuyerDetails } from './getBuyerDetails.hook';\n\ninterface BuyerDetailsSidebarProps {\n  open: boolean;\n  closeSidebar: () => void;\n  buyerId: string;\n}\n\nexport const BuyerDetailsSidebar = ({\n  open,\n  closeSidebar,\n  buyerId,\n}: BuyerDetailsSidebarProps) => {\n  const { t, ready } = useTranslation('buyersPage', {\n    keyPrefix: 'sidebar',\n  });\n  const {\n    data: { buyer, paymentRequests, limit, tasks },\n    isFetching,\n    error,\n  } = useGetBuyerDetails(buyerId);\n\n  const latestPR = paymentRequests?.[0];\n\n  const dataIsReady =\n    buyer != null && paymentRequests != null && limit != null && tasks != null;\n\n  let element;\n\n  if (error) {\n    element = (\n      <ZeroState\n        title={t('notFoundTitle')}\n        description={t('notFoundDescription')}\n      >\n        <Button variant=\"primary\" onClick={closeSidebar}>\n          {t('backBtnLabel')}\n        </Button>\n      </ZeroState>\n    );\n  } else if (isFetching || !ready || !dataIsReady) {\n    element = <Loader />;\n  } else {\n    element = (\n      <BuyerDetailsContextProvider\n        buyer={buyer}\n        tasks={tasks}\n        limit={limit}\n        paymentRequests={paymentRequests}\n      >\n        <ProfileStatusSection\n          status={buyer.status}\n          name={buyer.legalName}\n          menu={<BuyerActions buyer={buyer} />}\n        />\n        <SmeStatusDrawerAlert buyer={buyer} />\n        <BuyerTaskSection />\n        {latestPR && (\n          <>\n            <LatestPRSection paymentRequest={latestPR} />\n            <Spacer height={2} />\n          </>\n        )}\n        <BuyerDetailsSection />\n      </BuyerDetailsContextProvider>\n    );\n  }\n\n  return (\n    <Drawer\n      title={t('heading')}\n      open={open}\n      onClose={closeSidebar}\n      testId=\"buyer-sidebar\"\n    >\n      {element}\n    </Drawer>\n  );\n};\n","import { Button } from '@finmid/tbl-webapps/components';\nimport { sharedTblRoutes } from '@finmid/tbl-webapps/routes';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nexport const CreateBuyerPageButton = () => {\n  const navigate = useNavigate();\n  const { t } = useTranslation('buyersPage');\n\n  return (\n    <Button\n      variant=\"primary\"\n      onClick={() => navigate(sharedTblRoutes.createBuyers)}\n    >\n      {t('createBuyer.btnLabel')}\n    </Button>\n  );\n};\n","import { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nexport const useBuyerFormLabels = () => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'form' });\n\n  const sections = useMemo(\n    () => ({\n      generalInfo: t('sections.generalInformation'),\n      legalAddress: t('sections.legalAddress'),\n    }),\n    [t],\n  );\n\n  const labels = useMemo(\n    () => ({\n      externalId: t('labels.externalId'),\n      legalName: t('labels.legalName'),\n      businessRegistrationNumber: t('labels.businessRegistrationNumber'),\n      taxNumber: t('labels.taxNumberV2'),\n      email: t('labels.email'),\n      phone: t('labels.phone'),\n      phoneOptional: t('labels.phoneOptional'),\n\n      addressLine1: t('labels.addressLine1'),\n      addressLine2: t('labels.addressLine2'),\n      postalCode: t('labels.postalCode'),\n      city: t('labels.city'),\n      state: t('labels.state'),\n      country: t('labels.country'),\n\n      desiredLimit: t('labels.desiredLimit'),\n    }),\n    [t],\n  );\n\n  const tooltips = useMemo(\n    () => ({\n      externalId: t('tooltips.externalId'),\n      legalName: t('tooltips.legalName'),\n      businessRegistrationNumber: t('tooltips.businessRegistrationNumber'),\n      taxNumber: t('tooltips.taxNumber'),\n      email: t('tooltips.email'),\n      phone: t('tooltips.phone'),\n      desiredLimit: t('tooltips.desiredLimit'),\n\n      fieldDisabled: t('tooltips.fieldDisabled'),\n    }),\n    [t],\n  );\n\n  return {\n    labels,\n    sections,\n    tooltips,\n  };\n};\n","import { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\n// Create buyer and Update buyer forms\nexport const useBuyerFormValidationMessages = () => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'validation' });\n\n  const form = useMemo(\n    () => ({\n      externalId: {\n        required: t('externalIdRequired'),\n        externalIdRegex: t('externalIdRegex'),\n        maxLength: t('maxLength', { length: 100 }),\n        unique: t('externalIdUnique'),\n      },\n      legalName: {\n        required: t('legalNameRequired'),\n        maxLength: t('maxLength', { length: 100 }),\n      },\n      businessRegistrationNumber: {\n        required: t('businessRegistrationNumberOrTaxNumberRequired'),\n        maxLength: t('maxLength', { length: 100 }),\n      },\n      taxNumber: {\n        required: t('businessRegistrationNumberOrTaxNumberRequired'),\n        maxLength: t('maxLength', { length: 100 }),\n      },\n      email: {\n        email: t('emailValid'),\n        required: t('emailRequired'),\n      },\n      phone: {\n        plusSign: t('phonePlusSign'),\n        phoneRegex: t('phoneRegex'),\n        required: t('phoneRequired'),\n      },\n      legalAddress: {\n        addressLine1: {\n          required: t('addressLine1Required'),\n          maxLength: t('maxLength', { length: 100 }),\n        },\n        addressLine2: {\n          maxLength: t('maxLength', { length: 100 }),\n        },\n        postalCode: {\n          required: t('postalCodeRequired'),\n          maxLength: t('maxLength', { length: 20 }),\n        },\n        country: {\n          required: t('countryRequired'),\n        },\n        state: {\n          maxLength: t('maxLength', { length: 100 }),\n        },\n        city: {\n          required: t('cityRequired'),\n          maxLength: t('maxLength', { length: 100 }),\n        },\n      },\n      desiredLimit: {\n        notANumber: t('desiredLimitInvalid'),\n        notPositive: t('desiredLimitNegative'),\n      },\n    }),\n    [t],\n  );\n\n  return {\n    form,\n  };\n};\n","import { BE_Error, buyerConflictErrorCode } from '@finmid/distributor-types';\nimport {\n  GetCustomDomainErrors,\n  useHandleFormError,\n} from '@finmid/tbl-webapps/errors-handling';\nimport { useCallback } from 'react';\n\nimport {\n  useBuyerFormLabels,\n  useBuyerFormValidationMessages,\n} from '../BuyerFormUtils';\n\ntype FieldsMap = Record<string, string>;\n\nconst ServerToClientFields: FieldsMap = {\n  '.externalId': 'externalId',\n  legalName: 'legalName',\n\n  businessRegistrationNumber: 'businessRegistrationNumber',\n  taxNumber: 'taxNumber',\n  businessRegistrationNumberOrTaxNumber:\n    'businessRegistrationNumberOrTaxNumber',\n\n  email: 'email',\n  phone: 'phone',\n\n  addressLine1: 'addressLine1',\n  addressLine2: 'addressLine2',\n  postalCode: 'postalCode',\n  city: 'city',\n  state: 'state',\n  country: 'country',\n};\n\nconst useCreateBuyerCustomErrors = () => {\n  const { form } = useBuyerFormValidationMessages();\n\n  const getCustomDomainErrors: GetCustomDomainErrors = useCallback(\n    (error: BE_Error) => {\n      let message: string | undefined;\n      const { code: errorCode } = error.data.errorData.data;\n      switch (errorCode) {\n        case buyerConflictErrorCode:\n          message = form.externalId.unique;\n          break;\n        default:\n          break;\n      }\n\n      return { error, message };\n    },\n    [form],\n  );\n\n  return { getCustomDomainErrors };\n};\n\nexport const useHandleCreateBuyerErrors = () => {\n  const { labels } = useBuyerFormLabels();\n  const { getCustomDomainErrors } = useCreateBuyerCustomErrors();\n  return useHandleFormError({\n    labels,\n    fieldsMap: ServerToClientFields,\n    getCustomDomainErrors,\n  });\n};\n","import { TBLCurrency } from '@finmid/distributor-types';\nimport {\n  EXTERNAL_ID_REGEX,\n  ISD_CODE_REGEX,\n  PHONE_REGEX,\n} from '@finmid/tbl-webapps/utils';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport * as yup from 'yup';\n\nimport { useBuyerFormValidationMessages } from '../BuyerFormUtils';\n\nexport const useValidationSchema = () => {\n  const { form } = useBuyerFormValidationMessages();\n  const { ready, i18n } = useTranslation('buyersPage', {\n    keyPrefix: 'validation',\n  });\n\n  const createBuyerValidationSchema = useMemo(\n    () =>\n      yup.object().shape({\n        generalInfo: yup.object().shape(\n          {\n            externalId: yup\n              .string()\n              .max(100, form.externalId.maxLength)\n              .required(form.externalId.required)\n              .matches(EXTERNAL_ID_REGEX, form.externalId.externalIdRegex),\n            legalName: yup.string().required(form.legalName.required),\n            businessRegistrationNumber: yup.string().when('taxNumber', {\n              is: (taxNumber: string) => !taxNumber,\n              then: (s) =>\n                s\n                  .max(100, form.businessRegistrationNumber.maxLength)\n                  .required(form.businessRegistrationNumber.required),\n            }),\n            taxNumber: yup.string().when('businessRegistrationNumber', {\n              is: (businessRegistrationNumber: string) =>\n                !businessRegistrationNumber,\n              then: (s) =>\n                s\n                  .max(100, form.taxNumber.maxLength)\n                  .required(form.taxNumber.required),\n            }),\n            email: yup\n              .string()\n              .email(form.email.email)\n              .required(form.email.required),\n            phone: yup\n              .string()\n              .matches(ISD_CODE_REGEX, {\n                message: form.phone.plusSign,\n                excludeEmptyString: true,\n              })\n              .matches(PHONE_REGEX, {\n                message: form.phone.phoneRegex,\n                excludeEmptyString: true,\n              }),\n          },\n          [['taxNumber', 'businessRegistrationNumber']],\n        ),\n        address: yup.object().shape({\n          addressLine1: yup\n            .string()\n            .max(100, form.legalAddress.addressLine1.maxLength)\n            .required(form.legalAddress.addressLine1.required),\n          addressLine2: yup\n            .string()\n            .max(100, form.legalAddress.addressLine2.maxLength)\n            .optional(),\n          postalCode: yup\n            .string()\n            .max(20, form.legalAddress.postalCode.maxLength)\n            .required(form.legalAddress.postalCode.required),\n          city: yup\n            .string()\n            .max(100, form.legalAddress.city.maxLength)\n            .required(form.legalAddress.city.required),\n          state: yup\n            .string()\n            .max(100, form.legalAddress.state.maxLength)\n            .optional(),\n          country: yup\n            .string()\n            .typeError(form.legalAddress.country.required)\n            .required(form.legalAddress.country.required),\n        }),\n        desiredLimit: yup\n          .number()\n          .transform((val, orig) => (orig === '' ? undefined : val))\n          .nullable()\n          .typeError(form.desiredLimit.notANumber)\n          .positive(form.desiredLimit.notPositive)\n          .optional(),\n        desiredLimitCurrency: yup.string<TBLCurrency>().optional(),\n      }),\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [ready, i18n.language],\n  );\n\n  return createBuyerValidationSchema;\n};\n","import { CreateBuyer_GatewayRequest } from '@finmid/distributor-types';\nimport {\n  ScrollContainerHandle,\n  withErrorProps,\n} from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useCreateBuyerMutation } from '@finmid/tbl-webapps/gateway-api';\nimport {\n  useDistributorCurrencies,\n  useNotifications,\n} from '@finmid/tbl-webapps/hooks';\nimport { sharedTblRoutes } from '@finmid/tbl-webapps/routes';\nimport { setValueOrUndefined } from '@finmid/tbl-webapps/utils';\nimport { yupResolver } from '@hookform/resolvers/yup';\nimport posthog from 'posthog-js';\nimport { useEffect, useRef, useState } from 'react';\nimport { useForm } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { removeStoredBuyersFilters } from '../BuyersFilters';\n\nimport { useHandleCreateBuyerErrors } from './CreateBuyer.errors';\nimport { useValidationSchema } from './CreateBuyerForm.schema';\nimport { CreateBuyerFormType } from './CreateBuyerPage';\n\nconst defaultValues = {\n  generalInfo: {\n    externalId: '',\n    legalName: '',\n    businessRegistrationNumber: '',\n    taxNumber: '',\n    email: '',\n    phone: '',\n  },\n  address: {\n    addressLine1: '',\n    addressLine2: '',\n    postalCode: '',\n    city: '',\n    state: '',\n    country: '',\n  },\n};\n\nconst createPayload = ({\n  generalInfo,\n  address,\n  desiredLimit,\n  desiredLimitCurrency,\n}: CreateBuyerFormType): CreateBuyer_GatewayRequest => {\n  const {\n    email,\n    phone,\n    businessRegistrationNumber,\n    taxNumber,\n    ...requiredInfo\n  } = generalInfo;\n  const { addressLine2, state, ...requiredAddress } = address;\n\n  const payload: CreateBuyer_GatewayRequest = {\n    ...requiredInfo,\n    businessRegistrationNumber: setValueOrUndefined(businessRegistrationNumber),\n    taxNumber: setValueOrUndefined(taxNumber),\n    email: setValueOrUndefined(email),\n    phone: setValueOrUndefined(phone),\n    legalAddress: {\n      ...requiredAddress,\n      addressLine2: setValueOrUndefined(addressLine2),\n      state: setValueOrUndefined(state),\n    },\n    desiredLimit: setValueOrUndefined(desiredLimit),\n    desiredLimitCurrency:\n      desiredLimit != null\n        ? setValueOrUndefined(desiredLimitCurrency)\n        : undefined,\n  };\n\n  return payload;\n};\n\nexport const useCreateBuyerPage = () => {\n  const { notifySuccess } = useNotifications();\n  const { t } = useTranslation('buyersPage', {\n    keyPrefix: 'createBuyer',\n  });\n  const navigate = useNavigate();\n  const { defaultCurrency } = useDistributorCurrencies();\n\n  const validationSchema = useValidationSchema();\n  const methods = useForm<CreateBuyerFormType>({\n    resolver: yupResolver(validationSchema),\n    defaultValues: {\n      ...defaultValues,\n      desiredLimitCurrency: defaultCurrency,\n    },\n    mode: 'onBlur',\n  });\n\n  const [validationErrors, setValidationErrors] = useState<string[] | null>(\n    null,\n  );\n\n  const [createBuyer, { isLoading }] = useCreateBuyerMutation();\n  const { handleFormError } = useHandleCreateBuyerErrors();\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const handleSubmit = async (formData: CreateBuyerFormType) => {\n    posthog.capture('clicked_create_buyer_confirm');\n\n    const payload: CreateBuyer_GatewayRequest = createPayload(formData);\n\n    try {\n      await createBuyer(payload).unwrap();\n      removeStoredBuyersFilters();\n      notifySuccess(t('success', { name: payload.legalName }));\n      navigate(sharedTblRoutes.buyers);\n    } catch (error) {\n      const { customError, validationErrors } = handleFormError(error);\n      if (validationErrors) {\n        setValidationErrors(validationErrors);\n      } else {\n        displayErrorToast(\n          withErrorProps({\n            ...(error as Error),\n            message: customError,\n          }),\n        );\n      }\n    }\n  };\n\n  const scrollContainerRef = useRef<ScrollContainerHandle>(null);\n  useEffect(() => {\n    if (validationErrors != null) scrollContainerRef.current?.scrollToBottom();\n  }, [validationErrors]);\n\n  const submitDisabled =\n    !methods.formState.isValid ||\n    Object.keys(methods.formState.errors).length > 0;\n\n  return {\n    methods,\n    handleSubmit,\n    submitDisabled,\n    isLoading,\n    validationErrors,\n    scrollContainerRef,\n  };\n};\n","import {\n  CountrySelect,\n  FormTextField,\n  SectionContent,\n} from '@finmid/tbl-webapps/components';\nimport { useFormContext } from 'react-hook-form';\n\nimport { useBuyerFormLabels } from '../../BuyerFormUtils';\nimport { CreateBuyerFormType } from '../CreateBuyerPage';\n\ntype BuyerAddressFormProps = {\n  disabled: boolean;\n};\n\nexport const BuyerAddressForm = ({ disabled }: BuyerAddressFormProps) => {\n  const { control } = useFormContext<CreateBuyerFormType>();\n  const { sections, labels } = useBuyerFormLabels();\n\n  return (\n    <SectionContent title={sections.legalAddress}>\n      <FormTextField\n        control={control}\n        disabled={disabled}\n        label={labels.addressLine1}\n        name=\"address.addressLine1\"\n      />\n      <FormTextField\n        control={control}\n        disabled={disabled}\n        label={labels.addressLine2}\n        name=\"address.addressLine2\"\n      />\n      <FormTextField\n        control={control}\n        disabled={disabled}\n        label={labels.postalCode}\n        name=\"address.postalCode\"\n      />\n      <FormTextField\n        control={control}\n        disabled={disabled}\n        label={labels.city}\n        name=\"address.city\"\n      />\n      <FormTextField\n        control={control}\n        disabled={disabled}\n        label={labels.state}\n        name=\"address.state\"\n      />\n      <CountrySelect label={labels.country} name=\"address.country\" />\n    </SectionContent>\n  );\n};\n","import { FormCurrencySelector } from '@finmid/tbl-webapps/components';\nimport { useDistributorCurrencies } from '@finmid/tbl-webapps/hooks';\nimport { currencySymbols } from '@finmid/tbl-webapps/utils';\nimport { TextInput } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { Controller, useFormContext, useWatch } from 'react-hook-form';\nimport { NumericFormat } from 'react-number-format';\n\nimport { useBuyerFormLabels } from '../../BuyerFormUtils';\nimport { CreateBuyerFormType } from '../CreateBuyerPage';\n\ntype Props = {\n  disabled: boolean;\n};\n\nexport const DesiredLimitFields = ({ disabled }: Props) => {\n  const { defaultCurrency, supportedCurrencies } = useDistributorCurrencies();\n  const { labels, tooltips } = useBuyerFormLabels();\n  const { control } = useFormContext<CreateBuyerFormType>();\n  const currency = useWatch({\n    control,\n    name: 'desiredLimitCurrency',\n  });\n\n  return (\n    <Box\n      display=\"grid\"\n      gridTemplateColumns=\"240px 0.4fr\"\n      gap={2}\n      alignItems=\"flex-end\"\n    >\n      <Controller\n        control={control}\n        name=\"desiredLimit\"\n        render={({ field, fieldState }) => {\n          const { onChange, ref, ...rest } = field;\n          return (\n            <NumericFormat\n              decimalScale={2}\n              thousandSeparator\n              fixedDecimalScale\n              testId=\"desiredLimitField\"\n              customInput={TextInput}\n              error={fieldState.error != null}\n              helperText={fieldState.error?.message}\n              onValueChange={(v) => {\n                onChange(v.floatValue?.toString(10));\n              }}\n              startAdornment={currencySymbols[currency ?? defaultCurrency]}\n              disabled={disabled}\n              label={labels.desiredLimit}\n              tooltip={tooltips.desiredLimit}\n              fullWidth\n              {...rest}\n            />\n          );\n        }}\n      />\n      <FormCurrencySelector\n        name=\"desiredLimitCurrency\"\n        currencies={supportedCurrencies}\n        fullWidth\n      />\n    </Box>\n  );\n};\n","import { useLazyCheckBuyerExistsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useUniqueId } from '@finmid/tbl-webapps/hooks';\nimport { useState } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport {\n  useBuyerFormLabels,\n  useBuyerFormValidationMessages,\n} from '../../../BuyerFormUtils';\nimport { CreateBuyerFormType } from '../../CreateBuyerPage';\n\nimport { CompanyIdType } from './components';\n\nexport const useBuyerGeneralInfoForm = () => {\n  const methods = useFormContext<CreateBuyerFormType>();\n  const { labels, sections, tooltips } = useBuyerFormLabels();\n  const { form } = useBuyerFormValidationMessages();\n\n  const [checkBuyerExists] = useLazyCheckBuyerExistsQuery();\n  const checkUniqueId = useUniqueId({\n    field: 'generalInfo.externalId',\n    methods,\n    message: form.externalId.unique,\n    lazyQuery: checkBuyerExists,\n  });\n\n  const [companyIdType, setCompanyIdType] = useState<CompanyIdType>(\n    'businessRegistrationNumber',\n  );\n  const handleSelectCompanyIdType = (\n    value: 'businessRegistrationNumber' | 'taxNumber',\n  ) => {\n    methods.resetField('generalInfo.taxNumber');\n    methods.resetField('generalInfo.businessRegistrationNumber');\n    setCompanyIdType(value);\n  };\n\n  return {\n    methods,\n    labels,\n    sections,\n    tooltips,\n    checkUniqueId,\n    companyIdType,\n    handleSelectCompanyIdType,\n  };\n};\n","import { FormTextField } from '@finmid/tbl-webapps/components';\nimport { RadioGroup, Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport FormControl from '@mui/material/FormControl';\nimport { Control } from 'react-hook-form';\n\nimport { useBuyerFormLabels } from '../../../../BuyerFormUtils';\nimport { CreateBuyerFormType } from '../../../CreateBuyerPage';\n\nexport type CompanyIdType = 'businessRegistrationNumber' | 'taxNumber';\n\ntype SelectCompanyIdFieldProps = {\n  companyIdType: CompanyIdType;\n  onSelect: (value: 'businessRegistrationNumber' | 'taxNumber') => void;\n  control: Control<CreateBuyerFormType>;\n  disabled: boolean;\n};\n\nexport const SelectCompanyIdField = ({\n  companyIdType,\n  onSelect,\n  control,\n  disabled,\n}: SelectCompanyIdFieldProps) => {\n  const { labels, tooltips } = useBuyerFormLabels();\n\n  return (\n    <Box>\n      <FormControl>\n        <Box display=\"flex\" flexDirection=\"column\" gap={1}>\n          <RadioGroup\n            onChange={onSelect}\n            defaultValue={companyIdType}\n            name=\"companyIdType\"\n            options={[\n              {\n                value: 'businessRegistrationNumber',\n                label: labels.businessRegistrationNumber,\n                testId: 'company-id-businessRegistrationNumber',\n              },\n              {\n                value: 'taxNumber',\n                label: labels.taxNumber,\n                testId: 'company-id-taxNumber',\n              },\n            ]}\n          />\n        </Box>\n      </FormControl>\n\n      <Spacer height={1} />\n\n      {companyIdType === 'businessRegistrationNumber' ? (\n        <FormTextField\n          control={control}\n          name=\"generalInfo.businessRegistrationNumber\"\n          label={labels.businessRegistrationNumber}\n          disabled={disabled}\n          tooltip={tooltips.businessRegistrationNumber}\n        />\n      ) : (\n        <FormTextField\n          control={control}\n          name=\"generalInfo.taxNumber\"\n          label={labels.taxNumber}\n          disabled={disabled}\n          tooltip={tooltips.taxNumber}\n        />\n      )}\n    </Box>\n  );\n};\n","import { FormTextField, SectionContent } from '@finmid/tbl-webapps/components';\n\nimport { useBuyerGeneralInfoForm } from './BuyerGeneralInfoForm.hook';\nimport { SelectCompanyIdField } from './components';\n\ntype BuyerGeneralInfoFormProps = {\n  disabled: boolean;\n};\n\nconst ALPHA_NUMERIC_DASH_REGEX = /^[a-zA-Z0-9-._]+$/;\n\nexport const BuyerGeneralInfoForm = ({\n  disabled,\n}: BuyerGeneralInfoFormProps) => {\n  const {\n    methods,\n    sections,\n    labels,\n    tooltips,\n    checkUniqueId,\n    companyIdType,\n    handleSelectCompanyIdType,\n  } = useBuyerGeneralInfoForm();\n\n  return (\n    <SectionContent title={sections.generalInfo}>\n      <FormTextField\n        control={methods.control}\n        name=\"generalInfo.externalId\"\n        label={labels.externalId}\n        disabled={disabled}\n        tooltip={tooltips.externalId}\n        handleBlur={checkUniqueId}\n        autoFocus\n        onKeyDown={(e) => {\n          if (!ALPHA_NUMERIC_DASH_REGEX.test(e.key)) {\n            e.preventDefault();\n          }\n        }}\n      />\n      <FormTextField\n        control={methods.control}\n        name=\"generalInfo.legalName\"\n        label={labels.legalName}\n        disabled={disabled}\n        tooltip={tooltips.legalName}\n      />\n      <SelectCompanyIdField\n        companyIdType={companyIdType}\n        onSelect={handleSelectCompanyIdType}\n        control={methods.control}\n        disabled={disabled}\n      />\n      <FormTextField\n        control={methods.control}\n        name=\"generalInfo.email\"\n        label={labels.email}\n        disabled={disabled}\n        tooltip={tooltips.email}\n      />\n      <FormTextField\n        control={methods.control}\n        name=\"generalInfo.phone\"\n        label={labels.phoneOptional}\n        disabled={disabled}\n        tooltip={tooltips.phone}\n      />\n    </SectionContent>\n  );\n};\n","import {\n  CreateBuyer_GatewayRequest,\n  LegalAddress,\n  TBLCurrency,\n} from '@finmid/distributor-types';\nimport {\n  Button,\n  ErrorInfo,\n  NoFormAutofill,\n  Page,\n  PageNavigation,\n  ScrollableFormSection,\n  SectionContent,\n} from '@finmid/tbl-webapps/components';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { sharedTblRoutes } from '@finmid/tbl-webapps/routes';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { FormProvider } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useCreateBuyerPage } from './CreateBuyerPage.hook';\nimport {\n  BuyerAddressForm,\n  BuyerGeneralInfoForm,\n  DesiredLimitFields,\n} from './components';\n\nexport type CreateBuyerFormType = {\n  generalInfo: Omit<\n    CreateBuyer_GatewayRequest,\n    'legalAddress' | 'desiredLimit' | 'desiredLimitCurrency'\n  >;\n  address: LegalAddress;\n  desiredLimit?: number;\n  desiredLimitCurrency?: TBLCurrency;\n};\n\nexport const CreateBuyerPage = () => {\n  const { t, ready } = useTranslation('buyersPage', {\n    keyPrefix: 'createBuyer',\n  });\n  const { ready: componentsReady } = useTranslation('components');\n  const { ready: formatsReady } = useTranslation('formats');\n  const breadcrumbs = useBreadcrumbs();\n  const navigate = useNavigate();\n\n  const {\n    methods,\n    handleSubmit,\n    submitDisabled,\n    isLoading,\n    validationErrors,\n    scrollContainerRef,\n  } = useCreateBuyerPage();\n\n  const translationsReady = ready && componentsReady && formatsReady;\n\n  return (\n    <>\n      <PageNavigation breadcrumbs={breadcrumbs.createBuyers}>\n        {ready && (\n          <Button\n            variant=\"invisible\"\n            onClick={() => navigate(sharedTblRoutes.buyers)}\n          >\n            {t('cancelButton')}\n          </Button>\n        )}\n      </PageNavigation>\n      <Page>\n        {!translationsReady && <Loader />}\n\n        {translationsReady && (\n          <form\n            onSubmit={methods.handleSubmit(handleSubmit)}\n            autoComplete=\"off\"\n            css={{ height: '100%' }}\n          >\n            <NoFormAutofill />\n            <FormProvider {...methods}>\n              <ScrollableFormSection\n                ref={scrollContainerRef}\n                sectionTitle={t('sectionTitle')}\n                footerActions={[\n                  <Button\n                    variant=\"primary\"\n                    disabled={submitDisabled}\n                    loading={isLoading}\n                    type=\"submit\"\n                  >\n                    {t('submitCreateBuyer')}\n                  </Button>,\n                ]}\n              >\n                <BuyerGeneralInfoForm disabled={isLoading} />\n                <BuyerAddressForm disabled={isLoading} />\n                <SectionContent title=\"Additional information\">\n                  <DesiredLimitFields disabled={isLoading} />\n                </SectionContent>\n                {validationErrors?.length ? (\n                  <SectionContent disablePadding css={{ border: 'none' }}>\n                    <ErrorInfo invalidFields={validationErrors} />\n                  </SectionContent>\n                ) : null}\n              </ScrollableFormSection>\n            </FormProvider>\n          </form>\n        )}\n      </Page>\n    </>\n  );\n};\n","import { PageNavigation } from '@finmid/tbl-webapps/components';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { useTranslation } from 'react-i18next';\n\nimport { CreateBuyerPageButton } from '../../CreateBuyerPage';\n\nexport const BuyersPageNavigation = () => {\n  const breadcrumbs = useBreadcrumbs();\n  const { ready } = useTranslation('buyersPage');\n\n  return (\n    <PageNavigation breadcrumbs={breadcrumbs.buyers}>\n      {ready && <CreateBuyerPageButton />}\n    </PageNavigation>\n  );\n};\n","import { Buyer } from '@finmid/distributor-types';\nimport { GridRowParams } from '@mui/x-data-grid';\nimport { useEffect, useState } from 'react';\nimport { useSearchParams } from 'react-router-dom';\n\nexport const useShowBuyerDetails = () => {\n  const [searchParams, setSearchParams] = useSearchParams();\n  const [isSidebarOpen, setIsSidebarOpen] = useState(false);\n  const [selectedBuyerId, setSelectedBuyerId] = useState('');\n\n  useEffect(() => {\n    const view = searchParams.get('view');\n    if (view) {\n      setSelectedBuyerId(view);\n      setIsSidebarOpen(true);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const closeSidebar = () => {\n    setSearchParams({});\n    setIsSidebarOpen(false);\n  };\n\n  const triggerOpenSidebar = (id: string) => {\n    setIsSidebarOpen(true);\n    setSelectedBuyerId(id);\n  };\n\n  const onRowClick = ({ row: { externalId } }: GridRowParams<Buyer>) => {\n    const params = { view: externalId };\n    setSearchParams(params);\n    triggerOpenSidebar(externalId);\n  };\n\n  return {\n    isSidebarOpen,\n    selectedBuyerId,\n    closeSidebar,\n    onRowClick,\n  };\n};\n","import {\n  BuyerStatusSelector,\n  BuyerStatusUpdatedFilters,\n} from '@finmid/tbl-webapps/components';\nimport { useLazyGetBuyersStatsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useEffect } from 'react';\n\nimport { useBuyersListContext } from '../../BuyersPage.context';\n\nexport const BuyersStatusSelect = () => {\n  const { filters, updateFilters } = useBuyersListContext();\n\n  const [fetchStats, { data: buyersStats }] = useLazyGetBuyersStatsQuery();\n\n  const handleUpdateFilters = (updatedFilters: BuyerStatusUpdatedFilters) => {\n    updateFilters(updatedFilters);\n  };\n\n  useEffect(() => {\n    fetchStats({ search: filters.server.search });\n  }, [filters, fetchStats]);\n\n  if (!buyersStats) {\n    return null;\n  }\n\n  return (\n    <BuyerStatusSelector\n      selectedStatus={filters.server.status ?? 'ALL'}\n      onChange={handleUpdateFilters}\n      stats={buyersStats}\n    />\n  );\n};\n","import { GetBuyers_GatewayResponse } from '@finmid/distributor-types';\nimport { fetchErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useGetBuyersStatsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useCallback, useEffect, useState } from 'react';\n\nimport { useBuyersListContext } from '../../BuyersPage.context';\n\nexport const usePagination = ({\n  nextCursor,\n  previousCursor,\n}: GetBuyers_GatewayResponse['metadata']) => {\n  const {\n    filters: { firstPosition, server },\n    updateFilters,\n  } = useBuyersListContext();\n\n  const { limit, search, status } = server;\n\n  const paginationState = {\n    page: Math.floor(firstPosition / limit),\n    pageSize: limit,\n  };\n\n  const { buyersStats, isErrorStats, isFetchingStats } =\n    useGetBuyersWithRefreshOnNewSeller(search);\n\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  useEffect(() => {\n    if (isErrorStats) {\n      displayErrorToast(fetchErrorProps);\n    }\n  }, [isErrorStats, displayErrorToast]);\n\n  const onPaginationBack = useCallback(async () => {\n    if (previousCursor != null) {\n      const updatedFilters = {\n        firstPosition: Math.max(firstPosition - limit, 1),\n        'server.cursor': firstPosition < limit ? undefined : previousCursor,\n      };\n      updateFilters(updatedFilters);\n    }\n  }, [firstPosition, limit, previousCursor, updateFilters]);\n\n  const onPaginationNext = useCallback(async () => {\n    if (nextCursor != null) {\n      const updatedFilters = {\n        firstPosition: firstPosition + limit,\n        'server.cursor': nextCursor,\n      };\n      updateFilters(updatedFilters);\n    }\n  }, [firstPosition, limit, nextCursor, updateFilters]);\n\n  const currentStatus = status ?? 'ALL';\n\n  const rowsCount = buyersStats?.[currentStatus] ?? 0;\n\n  const onPageSizeChange = useCallback(\n    async (pageSize: number) => {\n      const updatedFilters = {\n        'server.limit': pageSize,\n        // reset cursor and firstPosition\n        firstPosition: 1,\n        'server.cursor': undefined,\n      };\n      updateFilters(updatedFilters);\n    },\n    [updateFilters],\n  );\n\n  return {\n    rowsCount,\n    onPaginationBack,\n    onPaginationNext,\n    onPageSizeChange,\n    paginationState,\n\n    loading: isFetchingStats,\n  };\n};\n\nconst useGetBuyersWithRefreshOnNewSeller = (search: string | undefined) => {\n  const [lastSearch, setLastSearch] = useState<{\n    search: string;\n    count: number;\n  } | null>(null);\n\n  const { updateFilters } = useBuyersListContext();\n\n  const {\n    data: stats,\n    isError: isErrorStats,\n    isFetching: isFetchingStats,\n  } = useGetBuyersStatsQuery({ search });\n\n  useEffect(() => {\n    if (stats == null || isFetchingStats) return;\n    if (search == null) return;\n\n    if (lastSearch == null) {\n      setLastSearch({\n        search,\n        count: stats.ALL,\n      });\n    } else if (lastSearch.search !== search && stats.ALL !== lastSearch.count) {\n      setLastSearch({\n        search,\n        count: stats.ALL,\n      });\n    } else if (lastSearch.search === search && stats.ALL !== lastSearch.count) {\n      setLastSearch({\n        search,\n        count: stats.ALL,\n      });\n      updateFilters({\n        firstPosition: 0,\n        'server.cursor': undefined,\n      });\n    }\n  }, [lastSearch, search, stats, isFetchingStats, updateFilters]);\n\n  return {\n    buyersStats: stats,\n    isErrorStats,\n    isFetchingStats,\n  };\n};\n","import { useSearchInputFilter } from '@finmid/tbl-webapps/components';\nimport debounce from 'lodash/debounce';\nimport { useMemo } from 'react';\n\nimport { useBuyersListContext } from '../../BuyersPage.context';\n\nconst debounceMs = 200;\n\nexport const useSearch = () => {\n  const { filters, updateFilters } = useBuyersListContext();\n\n  const onSearch = useMemo(() => {\n    return debounce(updateFilters, debounceMs);\n  }, [updateFilters]);\n\n  const { handleChange } = useSearchInputFilter({\n    handleUpdateFilters: onSearch,\n    searchValue: filters.server.search,\n  });\n\n  return { onSearch: handleChange, searchValue: filters.server.search };\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { fetchErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useGetBuyersQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useEffect } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useBuyersListContext } from '../../BuyersPage.context';\n\nimport { usePagination } from './usePagination';\nimport { useSearch } from './useSearch';\n\nexport const useBuyersTable = () => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'table' });\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const { filters } = useBuyersListContext();\n\n  const {\n    data: buyersResponse,\n    isError: buyersIsError,\n    isFetching: buyersIsFetching,\n  } = useGetBuyersQuery(filters.server);\n\n  const buyers = buyersResponse?.data;\n\n  const { onSearch, searchValue } = useSearch();\n\n  const {\n    onPaginationBack,\n    onPaginationNext,\n    onPageSizeChange,\n    paginationState,\n    rowsCount,\n    loading: loadingPagination,\n  } = usePagination({\n    nextCursor: buyersResponse?.metadata?.nextCursor ?? null,\n    previousCursor: buyersResponse?.metadata?.previousCursor ?? null,\n  });\n\n  useEffect(() => {\n    if (buyersIsError) {\n      displayErrorToast(fetchErrorProps);\n    }\n  }, [buyersIsError, displayErrorToast]);\n\n  const zeroStateDescriptionNoFilter =\n    ENVIRONMENT === 'live'\n      ? t('noBuyersMessageLive')\n      : t('noBuyersMessageTest');\n  const zeroStateDescription =\n    filters.server.status || filters.server.search\n      ? t('zeroStateDescriptionWithFilters')\n      : zeroStateDescriptionNoFilter;\n\n  return {\n    t,\n    buyers,\n    zeroStateDescription,\n\n    onSearch,\n    searchValue,\n\n    onPaginationBack,\n    onPaginationNext,\n    onPageSizeChange,\n    paginationState,\n    rowsCount,\n\n    loading: loadingPagination || buyersIsFetching,\n  };\n};\n","import { TBLCurrency } from '@finmid/distributor-types';\nimport { useFormat } from '@finmid/translations';\nimport currency from 'currency.js';\n\ntype AvailableFundsProps = {\n  amountSpent: number;\n  limit: number;\n  currency: TBLCurrency;\n  displayData: boolean;\n};\n\nexport const AvailableFunds = ({\n  amountSpent,\n  limit,\n  currency: amountCurrency,\n  displayData,\n}: AvailableFundsProps) => {\n  const { money } = useFormat();\n\n  return (\n    <span data-test-id=\"available-amount\" data-currency={amountCurrency}>\n      {displayData\n        ? money(currency(limit).subtract(amountSpent), amountCurrency)\n        : '-'}\n    </span>\n  );\n};\n","import { TBLCurrency } from '@finmid/distributor-types';\nimport { useFormat } from '@finmid/translations';\nimport currency from 'currency.js';\n\ntype DisplayCurrencyAmount = {\n  amount: string | number;\n  currency: TBLCurrency;\n  displayData: boolean;\n};\n\nexport const DisplayCurrencyAmount = ({\n  amount,\n  currency: amountCurrency,\n  displayData = true,\n}: DisplayCurrencyAmount) => {\n  const { money } = useFormat();\n\n  return (\n    <span data-test-id=\"currency-amount\" data-currency={amountCurrency}>\n      {displayData ? money(currency(amount ?? 0), amountCurrency) : '-'}\n    </span>\n  );\n};\n","import { AggregatedBuyer } from '@finmid/distributor-types';\nimport { useDistributorCurrencies } from '@finmid/tbl-webapps/hooks';\nimport { GridColDef } from '@mui/x-data-grid';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { AvailableFunds } from './components/AvailableFunds';\nimport { DisplayCurrencyAmount } from './components/DisplayCurrencyAmount';\n\nexport const useColumnsB2bp = (): GridColDef[] => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'table' });\n  const { defaultCurrency } = useDistributorCurrencies();\n\n  return useMemo(\n    () =>\n      [\n        {\n          field: 'expenseLimit',\n          headerName: t('headerExpenseLimit'),\n          sortable: false,\n          minWidth: 200,\n          align: 'right',\n          headerAlign: 'right',\n          renderCell: ({ row: { creditLimit, recourseLimit, status } }) => {\n            const displayData = status !== 'REJECTED' && status !== 'PENDING';\n            return (\n              <DisplayCurrencyAmount\n                displayData={displayData}\n                currency={defaultCurrency}\n                amount={creditLimit + recourseLimit}\n              />\n            );\n          },\n        },\n        {\n          field: 'availableFunds',\n          headerName: t('headerAvailableFunds'),\n          sortable: false,\n          minWidth: 200,\n          align: 'right',\n          headerAlign: 'right',\n          renderCell: ({\n            row: { creditLimit, recourseLimit, holdAmount, status },\n          }) => {\n            const displayData = status !== 'REJECTED' && status !== 'PENDING';\n            return (\n              <AvailableFunds\n                displayData={displayData}\n                currency={defaultCurrency}\n                limit={creditLimit + recourseLimit}\n                amountSpent={holdAmount}\n              />\n            );\n          },\n        },\n      ] as GridColDef<AggregatedBuyer>[],\n    [defaultCurrency, t],\n  ) as GridColDef[];\n};\n","import { AggregatedBuyer } from '@finmid/distributor-types';\nimport {\n  SmeStatusIndicator,\n  TruncatedContent,\n} from '@finmid/tbl-webapps/components';\nimport { GridColDef, GridRenderCellParams } from '@mui/x-data-grid';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nexport const useColumnsShared = (): GridColDef[] => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'table' });\n\n  return useMemo(\n    () =>\n      [\n        {\n          field: 'status',\n          headerName: '',\n          sortable: false,\n          align: 'center',\n          width: 48,\n          renderCell: ({ row: { status } }) => (\n            <SmeStatusIndicator status={status} />\n          ),\n        },\n        {\n          field: 'id',\n          headerName: t('headerBuyerId'),\n          sortable: false,\n          align: 'left',\n          minWidth: 220,\n          renderCell: ({\n            row: { externalId },\n          }: GridRenderCellParams<AggregatedBuyer>) => (\n            <TruncatedContent content={externalId} testId={externalId} />\n          ),\n        },\n        {\n          field: 'legalName',\n          headerName: t('headerLegalName'),\n          sortable: false,\n          minWidth: 120,\n          flex: 1,\n          renderCell: ({ row: { legalName } }) => (\n            <div style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>\n              {legalName}\n            </div>\n          ),\n        },\n      ] as GridColDef<AggregatedBuyer>[],\n    [t],\n  ) as GridColDef[];\n};\n","import { AggregatedBuyer } from '@finmid/distributor-types';\nimport { GridColDef } from '@mui/x-data-grid';\nimport { useMemo } from 'react';\n\nimport { useColumnsB2bp } from './useColumnsB2bp';\nimport { useColumnsShared } from './useColumnsShared';\n\nexport const useColumns = (): GridColDef[] => {\n  const columnsShared = useColumnsShared();\n  const columnsB2bp = useColumnsB2bp();\n\n  return useMemo(\n    () => [...columnsShared, ...columnsB2bp] as GridColDef<AggregatedBuyer>[],\n    [columnsB2bp, columnsShared],\n  ) as GridColDef[];\n};\n","import {\n  ErrorBoundary,\n  LazyLoadFallback,\n  ZeroState,\n} from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { Suspense, lazy } from 'react';\n\nimport { BuyerDetailsSidebar } from '../BuyerDetailSidebar';\nimport { useShowBuyerDetails } from '../BuyerDetailSidebar/ShowBuyerDetails.hook';\n\nimport { BuyersStatusSelect } from './BuyersStatusSelect';\nimport { useBuyersTable } from './BuyersTable.hook';\nimport { useColumns } from './useColumns';\nconst DataGrid = lazy(() => import('@finmid/tbl-webapps/components/DataGrid'));\n\nexport const BuyersTable = () => {\n  const {\n    t,\n    buyers,\n    loading,\n    zeroStateDescription,\n    onPaginationBack,\n    onPaginationNext,\n    onPageSizeChange,\n    paginationState,\n    rowsCount,\n    onSearch,\n    searchValue,\n  } = useBuyersTable();\n  const { isSidebarOpen, selectedBuyerId, closeSidebar, onRowClick } =\n    useShowBuyerDetails();\n\n  const columns = useColumns();\n\n  return (\n    <ErrorBoundary fallback={<LazyLoadFallback />}>\n      <Suspense fallback={<Loader />}>\n        {selectedBuyerId ? (\n          <BuyerDetailsSidebar\n            closeSidebar={closeSidebar}\n            open={isSidebarOpen}\n            buyerId={selectedBuyerId}\n          />\n        ) : null}\n        <DataGrid\n          disableColumnMenu\n          rows={buyers ?? []}\n          getRowId={(row) => row.externalId}\n          columns={columns}\n          rowCount={rowsCount}\n          initialState={{\n            pagination: { paginationModel: paginationState },\n          }}\n          paginationMode=\"server\"\n          onPaginationBack={onPaginationBack}\n          onPaginationNext={onPaginationNext}\n          pageSizeOptions={[10, 20, 30]}\n          onPageSizeChange={onPageSizeChange}\n          loading={loading}\n          onRowClick={onRowClick}\n          toolbar={{\n            title: '',\n            onSearch,\n            searchValue,\n            actionsBar: <BuyersStatusSelect />,\n          }}\n          slots={{\n            noRowsOverlay: () => (\n              <ZeroState\n                title={t('zeroStateTitle')}\n                description={zeroStateDescription}\n              />\n            ),\n          }}\n          autoHeight\n          sx={{ '--DataGrid-overlayHeight': '200px' }}\n          hideFooter={buyers != null && buyers.length === 0}\n        />\n      </Suspense>\n    </ErrorBoundary>\n  );\n};\n","import { Page } from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport { BuyersListContextProvider } from './BuyersPage.context';\nimport { BuyersPageNavigation, BuyersTable } from './components';\n\nexport const BuyersPage = () => {\n  const { ready: buyersPageReady } = useTranslation('buyersPage');\n  const { ready: componentsReady } = useTranslation('components');\n  const { ready: formatsReady } = useTranslation('formats');\n\n  const loading = !buyersPageReady || !componentsReady || !formatsReady;\n\n  return (\n    <>\n      <BuyersPageNavigation />\n      <Page>\n        {loading && <Loader />}\n        <BuyersListContextProvider>\n          {!loading && <BuyersTable />}\n        </BuyersListContextProvider>\n      </Page>\n    </>\n  );\n};\n","import { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { sharedTblRoutes } from '@finmid/tbl-webapps/routes';\nimport { useTranslation } from 'react-i18next';\nimport { useLocation, useNavigate } from 'react-router-dom';\n\nexport const useEditBuyerPage = () => {\n  const { state } = useLocation();\n\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'editBuyer' });\n  const navigate = useNavigate();\n  const { notifySuccess } = useNotifications();\n\n  const handleSuccess = (externalId: string) => {\n    notifySuccess(t('notificationSuccess'));\n    navigate(`${sharedTblRoutes.buyers}?view=${externalId}`);\n  };\n\n  return {\n    buyer: state?.buyer,\n    handleSuccess,\n  };\n};\n","import { useHandleFormError } from '@finmid/tbl-webapps/errors-handling';\n\nimport { useBuyerFormLabels } from '../../BuyerFormUtils';\n\nconst ServerToClientFields: Record<string, string> = {\n  '.externalId': 'externalId',\n  legalName: 'legalName',\n  businessRegistrationNumber: 'businessRegistrationNumber',\n  taxNumber: 'taxNumber',\n  email: 'email',\n  phone: 'phone',\n\n  addressLine1: 'addressLine1',\n  addressLine2: 'addressLine2',\n  postalCode: 'postalCode',\n  city: 'city',\n  state: 'state',\n  country: 'country',\n};\n\nexport const useHandleEditBuyerErrors = () => {\n  const { labels } = useBuyerFormLabels();\n  return useHandleFormError({\n    labels,\n    fieldsMap: ServerToClientFields,\n  });\n};\n","import { Buyer } from '@finmid/distributor-types';\nimport { ISD_CODE_REGEX, PHONE_REGEX } from '@finmid/tbl-webapps/utils';\nimport { yupResolver } from '@hookform/resolvers/yup';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport * as yup from 'yup';\n\nimport { useBuyerFormValidationMessages } from '../../BuyerFormUtils';\n\ntype UseEditBuyerValidationSchemaProps = {\n  buyer: Buyer;\n};\n\nexport const useEditBuyerValidationSchema = ({\n  buyer,\n}: UseEditBuyerValidationSchemaProps) => {\n  const { form } = useBuyerFormValidationMessages();\n  const { ready, i18n } = useTranslation('buyersPage', {\n    keyPrefix: 'validation',\n  });\n\n  const schema = useMemo(\n    () =>\n      yup.object().shape({\n        // General information\n        legalName: yup.string().required(form.legalName.required),\n        email: yup\n          .string()\n          .email(form.email.email)\n          .test('emailAlreadyExists', form.email.required, (email) => {\n            return buyer.email == null || buyer.email === ''\n              ? true\n              : email !== '';\n          }),\n        phone: yup\n          .string()\n          .matches(ISD_CODE_REGEX, {\n            message: form.phone.plusSign,\n            excludeEmptyString: true,\n          })\n          .matches(PHONE_REGEX, {\n            message: form.phone.phoneRegex,\n            excludeEmptyString: true,\n          })\n          .test('phoneAlreadyExists', form.phone.required, (phone) => {\n            return buyer.phone == null || buyer.phone === ''\n              ? true\n              : phone !== '';\n          }),\n\n        // Legal Address\n        addressLine1: yup\n          .string()\n          .max(100, form.legalAddress.addressLine1.maxLength)\n          .required(form.legalAddress.addressLine1.required),\n        addressLine2: yup\n          .string()\n          .max(100, form.legalAddress.addressLine2.maxLength)\n          .optional(),\n        postalCode: yup\n          .string()\n          .max(20, form.legalAddress.postalCode.maxLength)\n          .required(form.legalAddress.postalCode.required),\n        city: yup\n          .string()\n          .max(100, form.legalAddress.city.maxLength)\n          .required(form.legalAddress.city.required),\n        state: yup\n          .string()\n          .max(100, form.legalAddress.state.maxLength)\n          .optional(),\n        country: yup\n          .string()\n          .typeError(form.legalAddress.country.required)\n          .required(form.legalAddress.country.required),\n      }),\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [ready, i18n.language],\n  );\n\n  return {\n    editBuyerValidationSchema: yupResolver(schema),\n  };\n};\n","import { setValueOrNull } from '@finmid/tbl-webapps/utils';\n\nimport { EditBuyerFormValues } from './EditBuyerForm.hook';\n\nexport const getUpdatedBuyerValues = ({\n  values,\n  initialValues,\n}: {\n  values: EditBuyerFormValues;\n  initialValues: EditBuyerFormValues;\n}) => {\n  const updatedValues = Object.entries(values).reduce((acc, entry) => {\n    const [key, upToDateValue] = entry as [keyof EditBuyerFormValues, string];\n\n    if (upToDateValue !== initialValues[key]) {\n      acc[key] = setValueOrNull(upToDateValue);\n    }\n    return acc;\n  }, {} as Partial<EditBuyerFormValues>);\n\n  return updatedValues;\n};\n","import { Buyer, EditBuyer_GatewayRequest } from '@finmid/distributor-types';\nimport {\n  ScrollContainerHandle,\n  withErrorProps,\n} from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useEditBuyerMutation } from '@finmid/tbl-webapps/gateway-api';\nimport posthog from 'posthog-js';\nimport { useEffect, useRef, useState } from 'react';\nimport { Resolver, useForm } from 'react-hook-form';\n\nimport { useHandleEditBuyerErrors } from './EditBuyer.errors';\nimport { useEditBuyerValidationSchema } from './EditBuyerForm.schema';\nimport { getUpdatedBuyerValues } from './EditBuyerForm.utils';\n\ntype UseEditBuyerFormProps = {\n  buyer: Buyer;\n  handleSuccess: (buyerId: string) => void;\n};\n\nexport type EditBuyerFormValues = Omit<EditBuyer_GatewayRequest, 'externalId'>;\n\nexport const useEditBuyerForm = ({\n  buyer,\n  handleSuccess,\n}: UseEditBuyerFormProps) => {\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const [validationErrors, setValidationErrors] = useState<string[] | null>();\n  const { editBuyerValidationSchema } = useEditBuyerValidationSchema({\n    buyer,\n  });\n\n  const initialValues: EditBuyerFormValues = {\n    // General info\n    legalName: buyer.legalName,\n    email: buyer.email ?? '',\n    phone: buyer.phone ?? '',\n    // Legal address\n    addressLine1: buyer.legalAddress.addressLine1,\n    addressLine2: buyer.legalAddress?.addressLine2 ?? '',\n    postalCode: buyer.legalAddress.postalCode,\n    city: buyer.legalAddress.city,\n    state: buyer.legalAddress?.state ?? '',\n    country: buyer.legalAddress.country,\n  };\n\n  const [editBuyer, { isLoading }] = useEditBuyerMutation();\n\n  const { handleFormError } = useHandleEditBuyerErrors();\n\n  const handleEditBuyer = async (values: EditBuyerFormValues) => {\n    posthog.capture('clicked_edit_buyer_confirm');\n\n    try {\n      if (buyer.status === 'PENDING') {\n        const updatedValues = getUpdatedBuyerValues({ values, initialValues });\n        await editBuyer({\n          externalId: buyer.externalId,\n          ...updatedValues,\n        }).unwrap();\n\n        handleSuccess(buyer.externalId);\n      }\n    } catch (error) {\n      const { customError, validationErrors } = handleFormError(error);\n      if (validationErrors) {\n        setValidationErrors(validationErrors);\n      } else {\n        displayErrorToast(\n          withErrorProps({ ...(error as Error), message: customError }),\n        );\n      }\n    }\n  };\n\n  const methods = useForm<EditBuyerFormValues>({\n    // TODO: useForm can derive type from yupResolver\n    resolver: editBuyerValidationSchema as Resolver<EditBuyerFormValues>,\n    defaultValues: initialValues,\n    mode: 'onBlur',\n  });\n\n  const submitEnabled =\n    methods.formState.isValid && methods.formState.isDirty && !isLoading;\n\n  const scrollContainerRef = useRef<ScrollContainerHandle>(null);\n  useEffect(() => {\n    if (validationErrors != null) scrollContainerRef.current?.scrollToBottom();\n  }, [validationErrors]);\n\n  return {\n    methods,\n    isLoading,\n    submitEnabled,\n    handleEditBuyer,\n    validationErrors,\n    scrollContainerRef,\n  };\n};\n","import { Buyer } from '@finmid/distributor-types';\nimport { FormTextField, SectionContent } from '@finmid/tbl-webapps/components';\nimport { TextInput } from '@finmid/ui/ocarina';\nimport { Control } from 'react-hook-form';\n\nimport { useBuyerFormLabels } from '../../../BuyerFormUtils';\nimport { EditBuyerFormValues } from '../EditBuyerForm.hook';\n\ntype BuyerGeneralInfoFormProps = {\n  buyer: Buyer;\n  control: Control<EditBuyerFormValues>;\n};\n\nexport const BuyerGeneralInfoForm = ({\n  buyer,\n  control,\n}: BuyerGeneralInfoFormProps) => {\n  const { labels, sections, tooltips } = useBuyerFormLabels();\n\n  return (\n    <SectionContent title={sections.generalInfo}>\n      <TextInput\n        label={labels.externalId}\n        disabled\n        tooltip={tooltips.fieldDisabled}\n        value={buyer.externalId}\n        testId=\"externalId\"\n      />\n      <FormTextField\n        control={control}\n        name=\"legalName\"\n        label={labels.legalName}\n      />\n      <TextInput\n        label={labels.businessRegistrationNumber}\n        disabled\n        tooltip={tooltips.fieldDisabled}\n        value={buyer.businessRegistrationNumber ?? ''}\n        testId=\"businessRegistrationNumber\"\n      />\n      <TextInput\n        label={labels.taxNumber}\n        disabled\n        tooltip={tooltips.fieldDisabled}\n        value={buyer.taxNumber ?? ''}\n        testId=\"taxNumber\"\n      />\n      <FormTextField control={control} name=\"email\" label={labels.email} />\n      <FormTextField\n        control={control}\n        name=\"phone\"\n        label={buyer.phone == null ? labels.phoneOptional : labels.phone}\n      />\n    </SectionContent>\n  );\n};\n","import {\n  CountrySelect,\n  FormTextField,\n  SectionContent,\n} from '@finmid/tbl-webapps/components';\nimport { Control } from 'react-hook-form';\n\nimport { useBuyerFormLabels } from '../../../BuyerFormUtils';\nimport { EditBuyerFormValues } from '../EditBuyerForm.hook';\n\ntype BuyerLegalAddressFormProps = {\n  control: Control<EditBuyerFormValues>;\n};\n\nexport const BuyerLegalAddressForm = ({\n  control,\n}: BuyerLegalAddressFormProps) => {\n  const { labels, sections } = useBuyerFormLabels();\n\n  return (\n    <SectionContent title={sections.legalAddress}>\n      <FormTextField\n        control={control}\n        label={labels.addressLine1}\n        name=\"addressLine1\"\n      />\n      <FormTextField\n        control={control}\n        label={labels.addressLine2}\n        name=\"addressLine2\"\n      />\n      <FormTextField\n        control={control}\n        label={labels.postalCode}\n        name=\"postalCode\"\n      />\n      <FormTextField control={control} label={labels.city} name=\"city\" />\n      <FormTextField control={control} label={labels.state} name=\"state\" />\n      <CountrySelect label={labels.country} />\n    </SectionContent>\n  );\n};\n","import { Buyer } from '@finmid/distributor-types';\nimport {\n  Button,\n  ErrorInfo,\n  ScrollableFormSection,\n  SectionContent,\n} from '@finmid/tbl-webapps/components';\nimport { FormProvider } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { useEditBuyerForm } from './EditBuyerForm.hook';\nimport { BuyerGeneralInfoForm, BuyerLegalAddressForm } from './components';\n\ntype EditBuyerFormProps = {\n  buyer: Buyer;\n  handleSuccess: (externalId: string) => void;\n};\n\nexport const EditBuyerForm = ({ buyer, handleSuccess }: EditBuyerFormProps) => {\n  const { t } = useTranslation('buyersPage', { keyPrefix: 'editBuyer' });\n  const {\n    methods,\n    isLoading,\n    submitEnabled,\n    validationErrors,\n    handleEditBuyer,\n    scrollContainerRef,\n  } = useEditBuyerForm({ buyer, handleSuccess });\n\n  return (\n    <FormProvider {...methods}>\n      <form\n        onSubmit={methods.handleSubmit(handleEditBuyer)}\n        data-test-id=\"form-buyer-edit\"\n        autoComplete=\"off\"\n        css={{ height: '100%' }}\n      >\n        <ScrollableFormSection\n          ref={scrollContainerRef}\n          sectionTitle={t('sectionTitle')}\n          footerActions={[\n            <Button\n              disabled={!submitEnabled}\n              loading={isLoading}\n              variant=\"primary\"\n              type=\"submit\"\n              testId=\"edit-buyer-form-submit-btn\"\n            >\n              {t('saveChangesBtn')}\n            </Button>,\n          ]}\n        >\n          <BuyerGeneralInfoForm buyer={buyer} control={methods.control} />\n          <BuyerLegalAddressForm control={methods.control} />\n\n          {validationErrors?.length ? (\n            <SectionContent disablePadding css={{ border: 'none' }}>\n              <ErrorInfo invalidFields={validationErrors} />\n            </SectionContent>\n          ) : null}\n        </ScrollableFormSection>\n      </form>\n    </FormProvider>\n  );\n};\n","import { Button, Page, PageNavigation } from '@finmid/tbl-webapps/components';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { sharedTblRoutes } from '@finmid/tbl-webapps/routes';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\nimport { Navigate, useNavigate } from 'react-router-dom';\n\nimport { useEditBuyerPage } from './EditBuyerPage.hook';\nimport { EditBuyerForm } from './components';\n\nexport const EditBuyerPage = () => {\n  const { t, ready } = useTranslation('buyersPage');\n  const { buyer, handleSuccess } = useEditBuyerPage();\n  const breadcrumbs = useBreadcrumbs(buyer.externalId, buyer.legalName);\n  const navigate = useNavigate();\n\n  if (buyer == null) {\n    return <Navigate to={sharedTblRoutes.buyers} replace={true} />;\n  }\n\n  const goToBuyersPage = () =>\n    navigate(`${sharedTblRoutes.buyers}?view=${buyer.externalId}`);\n\n  return (\n    <>\n      <PageNavigation breadcrumbs={breadcrumbs.buyerEdit}>\n        {ready && (\n          <Button variant=\"invisible\" onClick={goToBuyersPage}>\n            {t('cancelEditButtonLabel')}\n          </Button>\n        )}\n      </PageNavigation>\n      <Page>\n        {!ready && <Loader />}\n\n        {ready && <EditBuyerForm buyer={buyer} handleSuccess={handleSuccess} />}\n      </Page>\n    </>\n  );\n};\n","import { Button } from '@finmid/tbl-webapps/components';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nexport const CreateSellerPageButton = () => {\n  const navigate = useNavigate();\n  const { t } = useTranslation('sellersPage');\n\n  return (\n    <Button\n      variant=\"primary\"\n      onClick={() => navigate(b2bPaymentRoutes.createSeller)}\n    >\n      {t('createSeller.btnLabel')}\n    </Button>\n  );\n};\n","import { SellersFilters } from './SellersFilters.types';\n\nexport const useDefaultFilters = () => {\n  const defaultSellersFilters: SellersFilters = {\n    server: {\n      limit: 10,\n      search: '',\n    },\n    firstPosition: 1,\n  };\n\n  return {\n    defaultSellersFilters,\n  };\n};\n","export const sellersFiltersKey = 'sellersFiltersKey';\n\nexport const removeStoredSellersFilters = () => {\n  sessionStorage.removeItem(sellersFiltersKey);\n};\n","import { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\n// Create seller and Update seller forms\nexport const useSellerFormValidationMessages = () => {\n  const { t } = useTranslation('sellersPage', { keyPrefix: 'validation' });\n\n  const form = useMemo(\n    () => ({\n      // General info\n      externalId: {\n        required: t('externalIdRequired'),\n        externalIdRegex: t('externalIdRegex'),\n        maxLength: t('maxLength', { length: 100 }),\n        unique: t('externalIdUnique'),\n      },\n      legalName: {\n        required: t('legalNameRequired'),\n      },\n      businessRegistrationNumber: {\n        required: t('businessRegistrationNumberOrTaxNumberRequired'),\n        maxLength: t('maxLength', { length: 100 }),\n      },\n      taxNumber: {\n        required: t('businessRegistrationNumberOrTaxNumberRequired'),\n        maxLength: t('maxLength', { length: 100 }),\n      },\n      email: {\n        valid: t('emailValid'),\n        required: t('emailRequired'),\n      },\n      phone: {\n        plusSign: t('phonePlusSign'),\n        phoneRegex: t('phoneRegex'),\n        required: t('phoneRequired'),\n      },\n\n      // Legal address\n      legalAddress: {\n        addressLine1: {\n          required: t('addressLine1Required'),\n          maxLength: t('maxLength', { length: 100 }),\n        },\n        addressLine2: {\n          maxLength: t('maxLength', { length: 100 }),\n        },\n        postalCode: {\n          required: t('postalCodeRequired'),\n          maxLength: t('maxLength', { length: 20 }),\n        },\n        city: {\n          required: t('cityRequired'),\n          maxLength: t('maxLength', { length: 100 }),\n        },\n        state: {\n          maxLength: t('maxLength', { length: 100 }),\n        },\n        country: {\n          required: t('countryRequired'),\n        },\n      },\n\n      // Bank account details\n      paymentRail: {\n        valid: t('paymentRailValid'),\n      },\n\n      iban: {\n        required: t('ibanRequired'),\n        valid: t('ibanValid'),\n      },\n      bic: {\n        required: t('bicRequired'),\n      },\n      currency: {\n        required: t('currencyRequired'),\n      },\n\n      bankAccountIdentifier: {\n        required: t('bankAccountIdentifierRequired'),\n        maxLength: t('maxLength', { length: 30 }),\n      },\n      accountNumber: {\n        required: t('accountNumberRequired'),\n        valid: t('accountNumberValid'),\n        minLength: t('minLength', { length: 8 }),\n        maxLength: t('maxLength', { length: 8 }),\n      },\n      sortCode: {\n        required: t('sortCodeRequired'),\n        valid: t('sortCodeValid'),\n        minLength: t('minLength', { length: 6 }),\n        maxLength: t('maxLength', { length: 6 }),\n      },\n      bankCode: {\n        minLength: t('minLength', { length: 4 }),\n        maxLength: t('maxLength', { length: 4 }),\n      },\n    }),\n    [t],\n  );\n\n  return {\n    form,\n  };\n};\n","import { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nexport const useSellerFormLabels = () => {\n  const { t } = useTranslation('sellersPage', { keyPrefix: 'form' });\n\n  const sections = useMemo(\n    () => ({\n      generalInfo: t('sections.generalInformation'),\n      legalAddress: t('sections.legalAddressV2'),\n      bankAccounts: t('sections.bankAccounts'),\n    }),\n    [t],\n  );\n\n  const labels = useMemo(\n    () => ({\n      externalId: t('labels.externalId'),\n      legalName: t('labels.legalName'),\n      businessRegistrationNumber: t('labels.businessRegistrationNumberV2'),\n      taxNumber: t('labels.taxNumberV2'),\n      businessRegistrationNumberOrTaxNumber: t(\n        'labels.businessRegistrationNumberOrTaxNumber',\n      ),\n      email: t('labels.email'),\n      phone: t('labels.phone'),\n      phoneOptional: t('labels.phoneOptional'),\n\n      addressLine1: t('labels.addressLine1'),\n      addressLine2: t('labels.addressLine2'),\n      postalCode: t('labels.postalCode'),\n      city: t('labels.city'),\n      state: t('labels.state'),\n      country: t('labels.country'),\n\n      bankName: t('labels.bankName'),\n      bankNameOptional: t('labels.bankNameOptional'),\n      currency: t('labels.currency'),\n      iban: t('labels.iban'),\n      bic: t('labels.bic'),\n      bicOptional: t('labels.bicOptional'),\n      bicRequired: t('labels.bicRequired'),\n\n      // FPS accounts\n      accountNumber: t('labels.accountNumber'),\n      sortCode: t('labels.sortCode'),\n      bankCodeOptional: t('labels.bankCodeOptional'),\n\n      // SWIFT accounts\n      bankAccountIdentifier: t('labels.bankAccountIdentifier'),\n      addressLine: t('labels.addressLine'),\n\n      paymentRail: t('labels.paymentRail'),\n    }),\n    [t],\n  );\n\n  const tooltips = useMemo(\n    () => ({\n      externalId: t('tooltips.externalId'),\n      legalName: t('tooltips.legalName'),\n      businessRegistrationNumber: t('tooltips.businessRegistrationNumberV2'),\n      taxNumber: t('tooltips.taxNumberV2'),\n      email: t('tooltips.email'),\n      phone: t('tooltips.phone'),\n\n      iban: t('tooltips.iban'),\n      bic: t('tooltips.bic'),\n\n      fieldDisabled: t('tooltips.fieldDisabled'),\n    }),\n    [t],\n  );\n\n  return {\n    labels,\n    sections,\n    tooltips,\n  };\n};\n","import {\n  PaymentRailIds,\n  PaymentRails,\n  TBLCurrency,\n  handledCurrencies,\n} from '@finmid/distributor-types';\n\n/**\n * Returns paymentRail and currency from `PaymentRailId` string\n * (e.g. `EUR_SWIFT`, `GBP_FPS`)\n * @param paymentRailId\n */\nexport const parsePaymentRailId = (\n  paymentRailId: string,\n): {\n  paymentRail: PaymentRails | null;\n  currency: TBLCurrency | null;\n} => {\n  if (paymentRailId !== '' && paymentRailId in PaymentRailIds) {\n    const [currency, paymentRail] = paymentRailId.split('_'); // e.g. EUR_SWIFT\n    if (\n      handledCurrencies.includes(currency as TBLCurrency) &&\n      paymentRail in PaymentRails\n    ) {\n      return {\n        currency: currency as TBLCurrency,\n        paymentRail: paymentRail as PaymentRails,\n      };\n    }\n  }\n\n  return { paymentRail: null, currency: null };\n};\n","import { BE_Error, sellerConflictErrorCode } from '@finmid/distributor-types';\nimport {\n  GetCustomDomainErrors,\n  useHandleFormError,\n} from '@finmid/tbl-webapps/errors-handling';\nimport { useCallback } from 'react';\n\nimport {\n  useSellerFormLabels,\n  useSellerFormValidationMessages,\n} from '../SellerFormUtils';\n\nconst ServerToClientFields = {\n  '.externalId': 'externalId',\n  legalName: 'legalName',\n  businessRegistrationNumber: 'businessRegistrationNumber',\n  taxNumber: 'taxNumber',\n  businessRegistrationNumberOrTaxNumber:\n    'businessRegistrationNumberOrTaxNumber',\n  email: 'email',\n  phone: 'phone',\n\n  addressLine1: 'addressLine1',\n  addressLine2: 'addressLine2',\n  postalCode: 'postalCode',\n  city: 'city',\n  state: 'state',\n  country: 'country',\n\n  // IBAN account\n  bankName: 'bankName',\n  iban: 'iban',\n  bic: 'bic',\n  currency: 'currency',\n\n  // SWIFT account\n  bankAccountIdentifier: 'bankAccountIdentifier',\n  addressLine: 'addressLine',\n\n  // FPS account\n  accountNumber: 'accountNumber',\n  sortCode: 'sortCode',\n  bankCode: 'bankCode',\n};\n\nconst useCreateSellerCustomErrors = () => {\n  const { form } = useSellerFormValidationMessages();\n\n  const getCustomDomainErrors: GetCustomDomainErrors = useCallback(\n    (error: BE_Error) => {\n      let message: string | undefined;\n      const { code: errorCode } = error.data.errorData.data;\n      switch (errorCode) {\n        case sellerConflictErrorCode:\n          message = form.externalId.unique;\n          break;\n        default:\n          break;\n      }\n\n      return { error, message };\n    },\n    [form],\n  );\n\n  return { getCustomDomainErrors };\n};\n\nexport const useHandleCreateSellerErrors = () => {\n  const { labels } = useSellerFormLabels();\n  const { getCustomDomainErrors } = useCreateSellerCustomErrors();\n  return useHandleFormError({\n    labels,\n    fieldsMap: ServerToClientFields,\n    getCustomDomainErrors,\n  });\n};\n","import { PaymentRailIds, PaymentRails } from '@finmid/distributor-types';\nimport {\n  EXTERNAL_ID_REGEX,\n  IBAN_SHAPE_REGEX,\n  ISD_CODE_REGEX,\n  PHONE_REGEX,\n} from '@finmid/tbl-webapps/utils';\nimport { yupResolver } from '@hookform/resolvers/yup';\nimport { isValidIBAN } from 'ibantools';\nimport { useMemo } from 'react';\nimport { Resolver } from 'react-hook-form';\nimport * as yup from 'yup';\n\nimport { useSellerFormValidationMessages } from '../SellerFormUtils';\n\nimport { CreateSellerFormType } from './types';\n\nexport const useCreateSellerFormSchema = () => {\n  const { form } = useSellerFormValidationMessages();\n\n  const schemaGeneralInfo = useMemo(\n    () =>\n      yup.object().shape(\n        {\n          externalId: yup\n            .string()\n            .max(100, form.externalId.maxLength)\n            .required(form.externalId.required)\n            .matches(EXTERNAL_ID_REGEX, form.externalId.externalIdRegex),\n          legalName: yup.string().max(100).required(form.legalName.required),\n          businessRegistrationNumber: yup.string().when('taxNumber', {\n            is: (taxNumber: string) => !taxNumber,\n            then: (s) =>\n              s\n                .max(100, form.businessRegistrationNumber.maxLength)\n                .required(form.businessRegistrationNumber.required),\n          }),\n          taxNumber: yup.string().when('businessRegistrationNumber', {\n            is: (businessRegistrationNumber: string) =>\n              !businessRegistrationNumber,\n            then: (s) =>\n              s\n                .max(100, form.taxNumber.maxLength)\n                .required(form.taxNumber.required),\n          }),\n          email: yup\n            .string()\n            .email(form.email.valid)\n            .required(form.email.required),\n          phone: yup\n            .string()\n            .matches(ISD_CODE_REGEX, {\n              message: form.phone.plusSign,\n              excludeEmptyString: true,\n            })\n            .matches(PHONE_REGEX, {\n              message: form.phone.phoneRegex,\n              excludeEmptyString: true,\n            })\n            .optional(),\n        },\n        [['taxNumber', 'businessRegistrationNumber']],\n      ),\n    [form],\n  );\n\n  const schemaLegalAddress = useMemo(\n    () =>\n      yup.object().shape({\n        addressLine1: yup\n          .string()\n          .max(100, form.legalAddress.addressLine1.maxLength)\n          .required(form.legalAddress.addressLine1.required),\n        addressLine2: yup\n          .string()\n          .max(100, form.legalAddress.addressLine2.maxLength)\n          .optional(),\n        postalCode: yup\n          .string()\n          .max(20, form.legalAddress.postalCode.maxLength)\n          .required(form.legalAddress.postalCode.required),\n        city: yup\n          .string()\n          .max(100, form.legalAddress.city.maxLength)\n          .required(form.legalAddress.city.required),\n        state: yup\n          .string()\n          .max(100, form.legalAddress.state.maxLength)\n          .optional(),\n        country: yup\n          .string()\n          .typeError(form.legalAddress.country.required)\n          .required(form.legalAddress.country.required),\n      }),\n    [form],\n  );\n\n  const ibanBankAccountSchema = useMemo(\n    () => ({\n      field1: yup.string().when('paymentRail', {\n        is: (paymentRail: PaymentRailIds) =>\n          paymentRail.endsWith(PaymentRailIds.EUR_SEPA),\n        then: (s) =>\n          s\n            .required(form.iban.required)\n            .test('validateIban', form.iban.valid, (iban) =>\n              isValidIBAN((iban ?? '').replaceAll(' ', '')),\n            ),\n      }),\n    }),\n    [form],\n  );\n\n  const swiftBankAccountSchema = useMemo(\n    () => ({\n      bankAccountIdentifier: yup.string().when('paymentRail', {\n        is: (paymentRail: PaymentRailIds) =>\n          paymentRail.endsWith(PaymentRails.SWIFT),\n        then: (s) =>\n          s\n            .when('bankAccountIdentifier', {\n              is: (value: string) => new RegExp(IBAN_SHAPE_REGEX).test(value),\n              then: (iban) =>\n                iban.test('validateIban', form.iban.valid, (iban) =>\n                  isValidIBAN((iban ?? '').replaceAll(' ', '')),\n                ),\n              otherwise: (accountNumber) =>\n                accountNumber.max(30, form.bankAccountIdentifier.maxLength),\n            })\n            .required(form.bankAccountIdentifier.required),\n      }),\n\n      addressLine: yup.string().when('paymentRail', {\n        is: (paymentRail: PaymentRailIds) =>\n          paymentRail.endsWith(PaymentRails.SWIFT),\n        then: (s) =>\n          s\n            .max(100, form.legalAddress.addressLine1.maxLength)\n            .required(form.legalAddress.addressLine1.required),\n      }),\n      city: yup.string().when('paymentRail', {\n        is: (paymentRail: PaymentRailIds) =>\n          paymentRail.endsWith(PaymentRails.SWIFT),\n        then: (s) =>\n          s\n            .max(100, form.legalAddress.city.maxLength)\n            .required(form.legalAddress.city.required),\n      }),\n      country: yup.string().when('paymentRail', {\n        is: (paymentRail: PaymentRailIds) =>\n          paymentRail.endsWith(PaymentRails.SWIFT),\n        then: (s) =>\n          s\n            .typeError(form.legalAddress.country.required)\n            .required(form.legalAddress.country.required),\n      }),\n    }),\n    [form],\n  );\n\n  const fpsBankAccountSchema = useMemo(\n    () => ({\n      accountNumber: yup.string().when('paymentRail', {\n        is: (paymentRail: PaymentRailIds) =>\n          paymentRail.endsWith(PaymentRails.FPS),\n        then: (s) =>\n          s\n            .matches(/^[0-9]+$/, form.accountNumber.valid)\n            .min(8, form.accountNumber.minLength)\n            .max(8, form.accountNumber.maxLength)\n            .required(form.accountNumber.required),\n      }),\n      sortCode: yup.string().when('paymentRail', {\n        is: (paymentRail: PaymentRailIds) =>\n          paymentRail.endsWith(PaymentRails.FPS),\n        then: (s) =>\n          s\n            .matches(/^[0-9]+$/, form.sortCode.valid)\n            .min(6, form.sortCode.minLength)\n            .max(6, form.sortCode.maxLength)\n            .required(form.sortCode.required),\n      }),\n      bankCode: yup.string().when('paymentRail', {\n        is: (paymentRail: PaymentRailIds) =>\n          paymentRail.endsWith(PaymentRails.FPS),\n        then: (s) =>\n          s.when('bankCode', {\n            is: (value = '') => value.length > 0,\n            then: (s) =>\n              s.min(4, form.bankCode.minLength).max(4, form.bankCode.maxLength),\n          }),\n      }),\n    }),\n    [form],\n  );\n\n  const schemaBankAccounts = useMemo(\n    () =>\n      yup.array().of(\n        yup.object().shape({\n          paymentRail: yup\n            .mixed<PaymentRailIds>()\n            .oneOf(Object.values(PaymentRailIds), form.paymentRail.valid)\n            .required(),\n          bankName: yup.string(),\n          bic: yup.string().when('paymentRail', {\n            is: (paymentRail: PaymentRailIds) =>\n              paymentRail.endsWith(PaymentRails.SWIFT),\n            then: (s) => s.required(form.bic.required),\n          }),\n          ...ibanBankAccountSchema,\n          ...swiftBankAccountSchema,\n          ...fpsBankAccountSchema,\n        }),\n      ),\n    [ibanBankAccountSchema, swiftBankAccountSchema, fpsBankAccountSchema, form],\n  );\n\n  const createSellerFormSchema = useMemo(\n    () =>\n      yup.object().shape({\n        generalInfo: schemaGeneralInfo,\n        address: schemaLegalAddress,\n        bankAccounts: schemaBankAccounts,\n      }),\n    [schemaBankAccounts, schemaGeneralInfo, schemaLegalAddress],\n  );\n\n  return yupResolver(createSellerFormSchema) as Resolver<CreateSellerFormType>;\n};\n","import { PaymentRails, TBLCurrency } from '@finmid/distributor-types';\n\nimport {\n  SellerBankAccountsFormType,\n  SellerGeneralInfoFormType,\n  SellerLegalAddressFormType,\n} from './types';\n\nexport const generalInfoDefaultValues: SellerGeneralInfoFormType = {\n  externalId: '',\n  legalName: '',\n  businessRegistrationNumber: '',\n  taxNumber: '',\n  email: '',\n  phone: '',\n};\n\nexport const legalAddressDefaultValues: SellerLegalAddressFormType = {\n  addressLine1: '',\n  addressLine2: '',\n  postalCode: '',\n  city: '',\n  state: '',\n  country: '',\n};\n\nexport const bankAccountsDefaultValues: SellerBankAccountsFormType = [\n  {\n    paymentRail: '',\n    bankName: '',\n    bankAccountIdentifier: '',\n    bic: '',\n    addressLine: '',\n    city: '',\n    country: '',\n    accountNumber: '',\n    sortCode: '',\n    bankCode: '',\n    field1: '',\n  },\n];\n\nexport const paymentRailsPerCurrency: Record<TBLCurrency, PaymentRails[]> = {\n  EUR: [PaymentRails.SEPA, PaymentRails.SWIFT],\n  GBP: [PaymentRails.FPS, PaymentRails.SEPA, PaymentRails.SWIFT],\n  USD: [PaymentRails.SWIFT],\n};\n","import {\n  AccountNumberType,\n  CreateSeller_GatewayRequest,\n  PaymentRails,\n} from '@finmid/distributor-types';\nimport {\n  IBAN_SHAPE_REGEX,\n  setValueOrUndefined,\n} from '@finmid/tbl-webapps/utils';\n\nimport { parsePaymentRailId } from '../SellerFormUtils';\n\nimport {\n  SellerBankAccountsFormType,\n  SellerGeneralInfoFormType,\n  SellerLegalAddressFormType,\n} from './types';\n\nconst createGeneralInfoRequestPayload = ({\n  externalId,\n  legalName,\n  businessRegistrationNumber,\n  taxNumber,\n  email,\n  phone,\n}: SellerGeneralInfoFormType) => ({\n  externalId: externalId,\n  legalName: legalName,\n  businessRegistrationNumber: setValueOrUndefined(businessRegistrationNumber),\n  taxNumber: setValueOrUndefined(taxNumber),\n  email: email,\n  phone: setValueOrUndefined(phone),\n});\n\nconst createLegalAddressInfoRequestPayload = (\n  legalAddressInfoForm: SellerLegalAddressFormType,\n) => {\n  const { addressLine1, addressLine2, postalCode, city, state, country } =\n    legalAddressInfoForm;\n\n  return {\n    legalAddress: {\n      addressLine1: addressLine1,\n      addressLine2: setValueOrUndefined(addressLine2),\n      postalCode: postalCode,\n      state: setValueOrUndefined(state),\n      city: city,\n      country: country,\n    },\n  };\n};\n\ntype CreateBankAccountsRequestPayload = (\n  bankAccounts: SellerBankAccountsFormType,\n) => CreateSeller_GatewayRequest['bankAccounts'];\n\nconst createBankAccountsRequestPayload: CreateBankAccountsRequestPayload = (\n  bankAccountsForm,\n) => {\n  const [bankAccount, ...bankAccounts] = bankAccountsForm.map(\n    ({ paymentRail: paymentRailId, ...bankAccount }) => {\n      const { paymentRail, currency } = parsePaymentRailId(paymentRailId);\n\n      if (paymentRail === PaymentRails.FPS) {\n        return {\n          bankName: setValueOrUndefined(bankAccount.bankName),\n          accountNumber: bankAccount.accountNumber,\n          sortCode: bankAccount.sortCode,\n          bankCode: setValueOrUndefined(bankAccount.bankCode),\n          currency: setValueOrUndefined(currency),\n        };\n      }\n\n      if (paymentRail === PaymentRails.SWIFT) {\n        const type: AccountNumberType = new RegExp(IBAN_SHAPE_REGEX).test(\n          bankAccount.bankAccountIdentifier,\n        )\n          ? 'IBAN'\n          : 'ACCOUNT_NUMBER';\n        return {\n          bankName: setValueOrUndefined(bankAccount.bankName),\n          accountNumber: bankAccount.bankAccountIdentifier,\n          accountNumberType: type,\n          bicSwift: bankAccount.bic,\n          address: {\n            addressLine: bankAccount.addressLine,\n            city: bankAccount.city,\n            country: bankAccount.country,\n          },\n          currency: setValueOrUndefined(currency),\n        };\n      }\n\n      // paymentRail === SEPA\n      return {\n        bankName: setValueOrUndefined(bankAccount.bankName),\n        iban: bankAccount.field1.replaceAll(' ', ''),\n        bic: setValueOrUndefined(bankAccount.bic),\n        currency: setValueOrUndefined(currency),\n      };\n    },\n  );\n  return [bankAccount, ...bankAccounts];\n};\n\ntype CreateSellerRequestPayload = (\n  generalInfo: SellerGeneralInfoFormType,\n  legalAddress: SellerLegalAddressFormType,\n  bankAccounts: SellerBankAccountsFormType,\n) => CreateSeller_GatewayRequest;\n\nexport const createSellerRequestPayload: CreateSellerRequestPayload = (\n  generalInfo,\n  legalAddress,\n  bankAccounts,\n) => ({\n  ...createGeneralInfoRequestPayload(generalInfo),\n  ...createLegalAddressInfoRequestPayload(legalAddress),\n  bankAccounts: createBankAccountsRequestPayload(bankAccounts),\n});\n","import {\n  ScrollContainerHandle,\n  withErrorProps,\n} from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useCreateSellerMutation } from '@finmid/tbl-webapps/gateway-api';\nimport {\n  useDistributorCurrencies,\n  useNotifications,\n} from '@finmid/tbl-webapps/hooks';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport posthog from 'posthog-js';\nimport { useEffect, useRef, useState } from 'react';\nimport { Control, useFieldArray, useForm } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { removeStoredSellersFilters } from '../SellersFilters';\n\nimport { useHandleCreateSellerErrors } from './CreateSeller.errors';\nimport { useCreateSellerFormSchema } from './CreateSellerForm.schema';\nimport {\n  bankAccountsDefaultValues,\n  generalInfoDefaultValues,\n  legalAddressDefaultValues,\n} from './CreateSellerPage.constants';\nimport { createSellerRequestPayload } from './CreateSellerPage.utils';\nimport { CreateSellerFormType } from './types';\n\nexport const useCreateSellerPage = () => {\n  const { t } = useTranslation('sellersPage', { keyPrefix: 'createSeller' });\n  const navigate = useNavigate();\n  const { notifySuccess } = useNotifications();\n  const { displayErrorToast } = useDisplayErrorToast();\n  const { supportedCurrencies } = useDistributorCurrencies();\n\n  const [validationErrors, setValidationErrors] = useState<string[] | null>(\n    null,\n  );\n\n  const resolver = useCreateSellerFormSchema();\n\n  const methods = useForm<CreateSellerFormType>({\n    defaultValues: {\n      generalInfo: generalInfoDefaultValues,\n      address: legalAddressDefaultValues,\n      bankAccounts: bankAccountsDefaultValues,\n    },\n    resolver,\n    mode: 'onBlur',\n  });\n\n  const [createSeller, { isLoading }] = useCreateSellerMutation();\n\n  const { handleFormError } = useHandleCreateSellerErrors();\n\n  const handleSubmit = async ({\n    generalInfo,\n    address,\n    bankAccounts,\n  }: CreateSellerFormType) => {\n    posthog.capture('clicked_create_seller_confirm');\n\n    const createPayload = createSellerRequestPayload(\n      generalInfo,\n      address,\n      bankAccounts,\n    );\n\n    try {\n      await createSeller(createPayload).unwrap();\n      removeStoredSellersFilters();\n      notifySuccess(t('success'));\n      navigate(b2bPaymentRoutes.sellers);\n    } catch (error) {\n      const { customError, validationErrors } = handleFormError(error);\n      if (validationErrors) {\n        setValidationErrors(validationErrors);\n      } else {\n        displayErrorToast(\n          withErrorProps({ ...(error as Error), message: customError }),\n        );\n      }\n    }\n  };\n\n  const scrollContainerRef = useRef<ScrollContainerHandle>(null);\n  useEffect(() => {\n    if (validationErrors != null) scrollContainerRef.current?.scrollToBottom();\n  }, [validationErrors]);\n\n  const submitDisabled =\n    !methods.formState.isValid ||\n    Object.keys(methods.formState.errors).length > 0;\n\n  return {\n    methods,\n    handleSubmit,\n    submitDisabled,\n    isLoading,\n    validationErrors,\n    scrollContainerRef,\n    supportedCurrencies,\n    canAddMultipleBankAccounts: supportedCurrencies.length > 1,\n  };\n};\n\nexport const useCreateSellerBankAccounts = ({\n  control,\n}: {\n  control: Control<CreateSellerFormType>;\n}) => {\n  const { fields, remove, append } = useFieldArray({\n    control: control,\n    name: 'bankAccounts',\n  });\n  const bankAccountInitial = bankAccountsDefaultValues[0];\n\n  const onAdd = () => {\n    append(bankAccountInitial);\n  };\n\n  return {\n    fields,\n    onAdd,\n    remove,\n  };\n};\n","import { FormTextField } from '@finmid/tbl-webapps/components';\nimport { MutableRefObject, useEffect } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\ntype SinglePaymentRailProps = {\n  paymentRail: string;\n  label: string;\n  name?: string;\n  forwardedRef?: MutableRefObject<HTMLInputElement>;\n};\n\nexport const SinglePaymentRail = ({\n  paymentRail,\n  label,\n  name,\n  forwardedRef,\n}: SinglePaymentRailProps) => {\n  const { control, setValue } = useFormContext();\n  const fieldName = name ?? 'paymentRail';\n\n  useEffect(() => {\n    setValue(fieldName, paymentRail);\n  }, [paymentRail, fieldName, setValue]);\n\n  return (\n    <FormTextField\n      forwardedRef={forwardedRef}\n      defaultValue={paymentRail}\n      control={control}\n      name={fieldName}\n      disabled\n      label={label}\n      testId=\"single-payment-rail\"\n    />\n  );\n};\n","import { TBLCurrency } from '@finmid/distributor-types';\nimport { FormAutocompleteField } from '@finmid/tbl-webapps/components';\nimport { currencySymbols } from '@finmid/tbl-webapps/utils';\nimport { useMemo } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport { paymentRailsPerCurrency } from '../../../CreateSellerPage.constants';\n\nimport { SinglePaymentRail } from './SinglePaymentRail';\n\ntype PaymentRailSelectProps = {\n  currencies: TBLCurrency[];\n  label: string;\n  name?: string;\n  showError?: boolean;\n  getOptionDisabled?: (option: { key: string; value: string }) => boolean;\n  disabled: boolean;\n};\n\nexport const PaymentRailSelect = ({\n  currencies,\n  label,\n  name,\n  showError,\n  getOptionDisabled,\n  disabled,\n}: PaymentRailSelectProps) => {\n  const { control } = useFormContext();\n\n  const paymentRailsList = useMemo(() => {\n    return currencies.flatMap((currency) =>\n      paymentRailsPerCurrency[currency].map((paymentRail) => ({\n        key: `${currencySymbols[currency]} ${currency} (${paymentRail})`,\n        value: `${currency}_${paymentRail}`,\n      })),\n    );\n  }, [currencies]);\n\n  if (paymentRailsList.length > 1) {\n    return (\n      <FormAutocompleteField\n        control={control}\n        label={label}\n        name={name ?? 'paymentRail'}\n        options={paymentRailsList}\n        getKey={(option) => option.key}\n        getValue={(option) => option.value}\n        getLabel={(option) => option.key}\n        showError={showError}\n        getOptionDisabled={getOptionDisabled}\n        testId=\"multiple-payment-rails\"\n        disabled={disabled}\n      />\n    );\n  } else {\n    const paymentRail = paymentRailsList[0].value;\n    return (\n      <SinglePaymentRail paymentRail={paymentRail} label={label} name={name} />\n    );\n  }\n};\n","import { Typography } from '@finmid/tbl-webapps/components';\nimport { WarningIcon } from '@finmid/ui/icons';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\n\nexport const AlertDuplicateCurrency = () => {\n  const { t } = useTranslation('sellersPage', { keyPrefix: 'createSeller' });\n\n  return (\n    <Box\n      display=\"flex\"\n      justifyContent=\"space-between\"\n      alignItems=\"center\"\n      py={1}\n      pl={1}\n      pr={2}\n      sx={{\n        backgroundColor: 'red.500',\n        borderRadius: '6px',\n      }}\n      color=\"white\"\n    >\n      <Box display=\"flex\" alignItems=\"center\">\n        <WarningIcon />\n        <Typography fontSize={12} pl={1} fontWeight={600}>\n          {t('bankAccounts.duplicateCurrencies.message')}\n        </Typography>\n      </Box>\n    </Box>\n  );\n};\n","import { Typography } from '@finmid/tbl-webapps/components';\nimport { ChevronDownIcon, CloseXIcon } from '@finmid/ui/icons';\nimport { Box, IconButton, SxProps } from '@mui/material';\n\ntype BankAccountHeaderProps = {\n  title: string;\n  open: boolean;\n  setOpen: () => void;\n  onRemove?: () => void;\n  sx?: SxProps;\n};\n\nexport const BankAccountHeader = ({\n  title,\n  open,\n  setOpen,\n  onRemove,\n  sx = {},\n}: BankAccountHeaderProps) => {\n  return (\n    <Box\n      sx={{\n        paddingBottom: 1,\n        borderBottom: '1px solid',\n        borderColor: 'gray.100',\n        display: 'flex',\n        justifyContent: 'space-between',\n        alignItems: 'flex-end',\n        cursor: 'pointer',\n        marginBottom: 0,\n        marginTop: 0,\n        maxWidth: ['100%', '100%', '100%', '100%', 480],\n        ...sx,\n      }}\n      onClick={setOpen}\n    >\n      <Typography\n        sx={{\n          fontWeight: 500,\n          fontSize: '14px',\n          lineHeight: '24px',\n          color: 'gray.700',\n        }}\n      >\n        {title}\n      </Typography>\n      <Box\n        sx={{\n          display: 'flex',\n          flexDirection: 'row',\n          justifyContent: 'flex-end',\n          alignItems: 'center',\n          fontSize: 12,\n          color: 'gray.400',\n        }}\n      >\n        {onRemove && (\n          <IconButton\n            onClick={(e) => {\n              e.stopPropagation();\n              onRemove();\n            }}\n            sx={{ fontSize: 11, mr: 2, color: 'gray.600' }}\n          >\n            <CloseXIcon fontSize=\"inherit\" color=\"inherit\" />\n          </IconButton>\n        )}\n\n        <ChevronDownIcon\n          fontSize=\"inherit\"\n          sx={{\n            transform: open ? 'rotate(180deg)' : 'rotate(0deg)',\n            transition: 'all 200ms cubic-bezier(0.4, 0, 0.2, 1) 0ms',\n          }}\n        />\n      </Box>\n    </Box>\n  );\n};\n","import { FormTextField } from '@finmid/tbl-webapps/components';\nimport { useFormContext } from 'react-hook-form';\n\nimport { useSellerFormLabels } from '../../../../../SellerFormUtils';\nimport {\n  CreateSellerFormType,\n  FpsBankAccountFormType,\n} from '../../../../types';\n\ntype FormDetailKeys = keyof FpsBankAccountFormType;\ntype GetPrefix = (\n  name: FormDetailKeys,\n) => `bankAccounts.${number}.${FormDetailKeys}`;\n\ntype FpsBankAccountFormFieldsProps = {\n  index?: number;\n  disabled: boolean;\n};\n\nexport const FpsBankAccountFormFields = ({\n  index = 0,\n  disabled,\n}: FpsBankAccountFormFieldsProps) => {\n  const prefix: GetPrefix = (name: FormDetailKeys) =>\n    `bankAccounts.${index}.${name}`;\n\n  const { labels } = useSellerFormLabels();\n  const { control, formState } = useFormContext<CreateSellerFormType>();\n\n  return (\n    <>\n      <FormTextField\n        control={control}\n        label={labels.bankNameOptional}\n        name={prefix('bankName')}\n        showError={\n          formState.touchedFields.bankAccounts?.[index]?.bankName === true\n        }\n        disabled={disabled}\n      />\n      <FormTextField\n        control={control}\n        label={labels.accountNumber}\n        name={prefix('accountNumber')}\n        showError={\n          formState.touchedFields.bankAccounts?.[index]?.accountNumber === true\n        }\n        disabled={disabled}\n      />\n      <FormTextField\n        control={control}\n        label={labels.sortCode}\n        name={prefix('sortCode')}\n        showError={\n          formState.touchedFields.bankAccounts?.[index]?.sortCode === true\n        }\n        disabled={disabled}\n      />\n      <FormTextField\n        control={control}\n        label={labels.bankCodeOptional}\n        name={prefix('bankCode')}\n        showError={\n          formState.touchedFields.bankAccounts?.[index]?.bankCode === true\n        }\n        disabled={disabled}\n      />\n    </>\n  );\n};\n","import { FormTextField } from '@finmid/tbl-webapps/components';\nimport { useFormContext } from 'react-hook-form';\n\nimport { useSellerFormLabels } from '../../../../../SellerFormUtils';\nimport {\n  CreateSellerFormType,\n  IbanBankAccountFormType,\n} from '../../../../types';\n\ntype FormDetailKeys = keyof IbanBankAccountFormType;\ntype GetPrefix = (\n  name: FormDetailKeys,\n) => `bankAccounts.${number}.${FormDetailKeys}`;\n\ntype IbanBankAccountFormFieldsProps = {\n  index?: number;\n  disabled: boolean;\n};\n\nexport const IbanBankAccountFormFields = ({\n  index = 0,\n  disabled,\n}: IbanBankAccountFormFieldsProps) => {\n  const prefix: GetPrefix = (name: FormDetailKeys) =>\n    `bankAccounts.${index}.${name}`;\n\n  const { labels, tooltips } = useSellerFormLabels();\n  const { control, formState } = useFormContext<CreateSellerFormType>();\n\n  return (\n    <>\n      <FormTextField\n        control={control}\n        label={labels.bankNameOptional}\n        name={prefix('bankName')}\n        showError={\n          formState.touchedFields.bankAccounts?.[index]?.bankName === true\n        }\n        disabled={disabled}\n      />\n      <FormTextField\n        control={control}\n        label={labels.iban}\n        name={prefix('field1')}\n        tooltip={tooltips.iban}\n        showError={\n          formState.touchedFields.bankAccounts?.[index]?.field1 === true\n        }\n        disabled={disabled}\n      />\n      <FormTextField\n        control={control}\n        label={labels.bicOptional}\n        name={prefix('bic')}\n        tooltip={tooltips.bic}\n        showError={formState.touchedFields.bankAccounts?.[index]?.bic === true}\n        disabled={disabled}\n      />\n    </>\n  );\n};\n","import { CountrySelect, FormTextField } from '@finmid/tbl-webapps/components';\nimport { useFormContext } from 'react-hook-form';\n\nimport { useSellerFormLabels } from '../../../../../SellerFormUtils';\nimport {\n  CreateSellerFormType,\n  SwiftBankAccountFormType,\n} from '../../../../types';\n\ntype FormDetailKeys = keyof SwiftBankAccountFormType;\ntype GetPrefix = (\n  name: FormDetailKeys,\n) => `bankAccounts.${number}.${FormDetailKeys}`;\n\ntype SwiftBankAccountFormFieldsProps = {\n  index?: number;\n  disabled: boolean;\n};\n\nexport const SwiftBankAccountFormFields = ({\n  index = 0,\n  disabled,\n}: SwiftBankAccountFormFieldsProps) => {\n  const prefix: GetPrefix = (name: FormDetailKeys) =>\n    `bankAccounts.${index}.${name}`;\n\n  const { labels, tooltips } = useSellerFormLabels();\n\n  const { control, formState } = useFormContext<CreateSellerFormType>();\n\n  return (\n    <>\n      <FormTextField\n        control={control}\n        label={labels.bankNameOptional}\n        name={prefix('bankName')}\n        showError={\n          formState.touchedFields.bankAccounts?.[index]?.bankName === true\n        }\n        disabled={disabled}\n      />\n      <FormTextField\n        control={control}\n        label={labels.bankAccountIdentifier}\n        name={prefix('bankAccountIdentifier')}\n        showError={\n          formState.touchedFields.bankAccounts?.[index]\n            ?.bankAccountIdentifier === true\n        }\n        disabled={disabled}\n      />\n      <FormTextField\n        control={control}\n        label={labels.bic}\n        name={prefix('bic')}\n        tooltip={tooltips.bic}\n        showError={formState.touchedFields.bankAccounts?.[index]?.bic === true}\n        disabled={disabled}\n      />\n      <FormTextField\n        control={control}\n        label={labels.addressLine}\n        name={prefix('addressLine')}\n        showError={\n          formState.touchedFields.bankAccounts?.[index]?.addressLine === true\n        }\n        disabled={disabled}\n      />\n      <FormTextField\n        control={control}\n        label={labels.city}\n        name={prefix('city')}\n        showError={formState.touchedFields.bankAccounts?.[index]?.city === true}\n        disabled={disabled}\n      />\n      <CountrySelect\n        label={labels.country}\n        name={prefix('country')}\n        showError={\n          formState.touchedFields.bankAccounts?.[index]?.country === true\n        }\n        disabled={disabled}\n      />\n    </>\n  );\n};\n","import { PaymentRails, SupportedCurrencies } from '@finmid/distributor-types';\nimport { useCallback, useEffect } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport {\n  parsePaymentRailId,\n  useSellerFormLabels,\n} from '../../../../SellerFormUtils';\nimport { CreateSellerFormType } from '../../../types';\n\nimport { PaymentRailSelect } from './PaymentRailSelect';\nimport {\n  FpsBankAccountFormFields,\n  IbanBankAccountFormFields,\n  SwiftBankAccountFormFields,\n} from './components';\n\ntype PaymentRailsFormsProps = {\n  currencies: SupportedCurrencies;\n  index?: number;\n  disabled: boolean;\n};\n\nexport const PaymentRailsForms = ({\n  currencies,\n  index = 0,\n  disabled,\n}: PaymentRailsFormsProps) => {\n  const { labels } = useSellerFormLabels();\n\n  const { trigger, watch } = useFormContext<CreateSellerFormType>();\n  const watchBankAccounts = watch('bankAccounts');\n  const { paymentRail } = parsePaymentRailId(\n    watchBankAccounts[index].paymentRail,\n  );\n\n  useEffect(() => {\n    if (paymentRail == null) return;\n    trigger();\n  }, [paymentRail, trigger]);\n\n  const isCurrencySelectedInOtherBankAccounts = useCallback(\n    (value: string) => {\n      return !!watchBankAccounts.find(({ paymentRail }, currIndex) => {\n        const selectedInOtherBankAccount = currIndex !== index;\n        const { currency } = parsePaymentRailId(paymentRail);\n        return (\n          selectedInOtherBankAccount &&\n          currency != null &&\n          value.startsWith(currency)\n        );\n      });\n    },\n    [watchBankAccounts, index],\n  );\n\n  return (\n    <>\n      <PaymentRailSelect\n        disabled={disabled}\n        currencies={currencies}\n        name={`bankAccounts.${index}.paymentRail`}\n        label={labels.paymentRail}\n        getOptionDisabled={({ value }) =>\n          isCurrencySelectedInOtherBankAccounts(value)\n        }\n      />\n      {paymentRail === PaymentRails.SWIFT && (\n        <SwiftBankAccountFormFields index={index} disabled={disabled} />\n      )}\n      {paymentRail === PaymentRails.SEPA && (\n        <IbanBankAccountFormFields index={index} disabled={disabled} />\n      )}\n      {paymentRail === PaymentRails.FPS && (\n        <FpsBankAccountFormFields index={index} disabled={disabled} />\n      )}\n    </>\n  );\n};\n","import { SupportedCurrencies } from '@finmid/distributor-types';\nimport { ColumnFlex } from '@finmid/tbl-webapps/components';\nimport Box from '@mui/material/Box';\nimport { Fragment, useState } from 'react';\nimport { FieldArrayWithId, useWatch } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { parsePaymentRailId } from '../../../../SellerFormUtils';\nimport { CreateSellerFormType } from '../../../types';\n\nimport { PaymentRailsForms } from './PaymentRailsForms';\nimport { AlertDuplicateCurrency, BankAccountHeader } from './components';\n\ntype SellerMultipleBankAccountsProps = {\n  currencies: SupportedCurrencies;\n  disabled: boolean;\n  fields: FieldArrayWithId<CreateSellerFormType, 'bankAccounts', 'id'>[];\n  onRemove: (index: number) => void;\n};\n\nexport const SellerMultipleBankAccounts = ({\n  currencies,\n  disabled,\n  fields,\n  onRemove,\n}: SellerMultipleBankAccountsProps) => {\n  const { t } = useTranslation('sellersPage', { keyPrefix: 'createSeller' });\n\n  const [open, setOpen] = useState(true);\n\n  const watchBankAccounts = useWatch<CreateSellerFormType>({\n    name: 'bankAccounts',\n  });\n\n  const selectedCurrencies = Array.isArray(watchBankAccounts)\n    ? watchBankAccounts.reduce((results: string[], { paymentRail }) => {\n        const { currency } = parsePaymentRailId(paymentRail);\n        if (currency) results.push(currency);\n        return results;\n      }, [])\n    : [];\n\n  const hasDuplicateCurrency =\n    selectedCurrencies.length > new Set(selectedCurrencies).size;\n\n  return (\n    <>\n      {fields.map((field, index) => (\n        <Fragment key={field.id}>\n          <Box data-test-id=\"bank-accounts-container\">\n            <BankAccountHeader\n              title={t('bankAccounts.bankAccount.title', { number: index + 1 })}\n              open={open}\n              setOpen={() => setOpen((v) => !v)}\n              onRemove={index === 0 ? undefined : () => onRemove(index)}\n            />\n\n            <ColumnFlex open={open} sx={{ pt: 2 }}>\n              <PaymentRailsForms\n                currencies={currencies}\n                index={index}\n                disabled={disabled}\n              />\n            </ColumnFlex>\n          </Box>\n        </Fragment>\n      ))}\n\n      {hasDuplicateCurrency ? <AlertDuplicateCurrency /> : null}\n    </>\n  );\n};\n","import { SupportedCurrencies } from '@finmid/distributor-types';\nimport { SectionContent } from '@finmid/tbl-webapps/components';\nimport Box from '@mui/material/Box';\nimport { FieldArrayWithId } from 'react-hook-form';\n\nimport { useSellerFormLabels } from '../../../SellerFormUtils';\nimport { CreateSellerFormType } from '../../types';\n\nimport { PaymentRailsForms, SellerMultipleBankAccounts } from './components';\n\ntype SellerBankAccountsFormProps = {\n  disabled: boolean;\n  fields: FieldArrayWithId<CreateSellerFormType, 'bankAccounts', 'id'>[];\n  onRemove: (index: number) => void;\n  currencies: SupportedCurrencies;\n  canAddMultipleBankAccounts: boolean;\n};\n\nexport const SellerBankAccountsForm = ({\n  disabled,\n  fields,\n  onRemove,\n  currencies,\n  canAddMultipleBankAccounts,\n}: SellerBankAccountsFormProps) => {\n  const { sections } = useSellerFormLabels();\n\n  return (\n    <SectionContent title={sections.bankAccounts}>\n      {canAddMultipleBankAccounts ? (\n        <SellerMultipleBankAccounts\n          currencies={currencies}\n          disabled={disabled}\n          fields={fields}\n          onRemove={onRemove}\n        />\n      ) : (\n        <Box\n          data-test-id=\"bank-accounts-container\"\n          display=\"inherit\"\n          flexDirection=\"inherit\"\n          gap=\"inherit\"\n          width=\"100%\"\n        >\n          <PaymentRailsForms currencies={currencies} disabled={disabled} />\n        </Box>\n      )}\n    </SectionContent>\n  );\n};\n","import { useLazyCheckSellerExistsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useUniqueId } from '@finmid/tbl-webapps/hooks';\nimport { useFormContext } from 'react-hook-form';\n\nimport { useSellerFormValidationMessages } from '../../../SellerFormUtils';\nimport { CreateSellerFormType } from '../../types';\n\nexport const useSellerGeneralInfoForm = () => {\n  const { form } = useSellerFormValidationMessages();\n\n  const methods = useFormContext<CreateSellerFormType>();\n\n  const [checkSellerExists] = useLazyCheckSellerExistsQuery();\n\n  const checkUniqueId = useUniqueId({\n    field: 'generalInfo.externalId',\n    methods,\n    message: form.externalId.unique,\n    lazyQuery: checkSellerExists,\n  });\n\n  return {\n    methods,\n    checkUniqueId,\n  };\n};\n","import { FormTextField } from '@finmid/tbl-webapps/components';\nimport { RadioGroup, Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport FormControl from '@mui/material/FormControl';\nimport { useState } from 'react';\nimport { useFormContext } from 'react-hook-form';\n\nimport { useSellerFormLabels } from '../../../../SellerFormUtils';\nimport { CreateSellerFormType } from '../../../types';\n\ntype SelectCompanyIdFieldProps = {\n  disabled: boolean;\n};\n\nexport const SellerSelectCompanyIdField = ({\n  disabled,\n}: SelectCompanyIdFieldProps) => {\n  const { labels, tooltips } = useSellerFormLabels();\n  const { control, resetField } = useFormContext<CreateSellerFormType>();\n\n  const [companyIdType, setCompanyIdType] = useState<\n    'businessRegistrationNumber' | 'taxNumber'\n  >('businessRegistrationNumber');\n\n  const handleSelectCompanyIdType = (\n    value: 'businessRegistrationNumber' | 'taxNumber',\n  ) => {\n    resetField('generalInfo.businessRegistrationNumber');\n    resetField('generalInfo.taxNumber');\n\n    setCompanyIdType(value);\n  };\n\n  return (\n    <Box>\n      <FormControl>\n        <Box display=\"flex\" flexDirection=\"column\" gap={1}>\n          <RadioGroup\n            onChange={handleSelectCompanyIdType}\n            defaultValue={companyIdType}\n            name=\"companyIdType\"\n            options={[\n              {\n                value: 'businessRegistrationNumber',\n                label: labels.businessRegistrationNumber,\n                testId: 'company-id-businessRegistrationNumber',\n              },\n              {\n                value: 'taxNumber',\n                label: labels.taxNumber,\n                testId: 'company-id-taxNumber',\n              },\n            ]}\n          />\n        </Box>\n      </FormControl>\n\n      <Spacer height={1} />\n\n      {companyIdType === 'businessRegistrationNumber' ? (\n        <FormTextField\n          control={control}\n          name=\"generalInfo.businessRegistrationNumber\"\n          label={labels.businessRegistrationNumber}\n          disabled={disabled}\n          tooltip={tooltips.businessRegistrationNumber}\n        />\n      ) : (\n        <FormTextField\n          control={control}\n          name=\"generalInfo.taxNumber\"\n          label={labels.taxNumber}\n          disabled={disabled}\n          tooltip={tooltips.taxNumber}\n        />\n      )}\n    </Box>\n  );\n};\n","import { FormTextField, SectionContent } from '@finmid/tbl-webapps/components';\n\nimport { useSellerFormLabels } from '../../../SellerFormUtils';\n\nimport { useSellerGeneralInfoForm } from './SellerGeneralInfoForm.hook';\nimport { SellerSelectCompanyIdField } from './SellerSelectCompanyId';\n\ntype SellerGeneralInfoFormProps = {\n  disabled: boolean;\n};\n\nconst ALPHA_NUMERIC_DASH_REGEX = /^[a-zA-Z0-9-._]+$/;\n\nexport const SellerGeneralInfoForm = ({\n  disabled,\n}: SellerGeneralInfoFormProps) => {\n  const { methods, checkUniqueId } = useSellerGeneralInfoForm();\n  const { labels, sections, tooltips } = useSellerFormLabels();\n\n  return (\n    <SectionContent title={sections.generalInfo}>\n      <FormTextField\n        control={methods.control}\n        disabled={disabled}\n        label={labels.externalId}\n        name=\"generalInfo.externalId\"\n        tooltip={tooltips.externalId}\n        handleBlur={checkUniqueId}\n        onKeyDown={(e) => {\n          if (!ALPHA_NUMERIC_DASH_REGEX.test(e.key)) {\n            e.preventDefault();\n          }\n        }}\n      />\n      <FormTextField\n        control={methods.control}\n        disabled={disabled}\n        label={labels.legalName}\n        name=\"generalInfo.legalName\"\n        tooltip={tooltips.legalName}\n      />\n      <SellerSelectCompanyIdField disabled={disabled} />\n      <FormTextField\n        control={methods.control}\n        disabled={disabled}\n        label={labels.email}\n        name=\"generalInfo.email\"\n        tooltip={tooltips.email}\n      />\n      <FormTextField\n        control={methods.control}\n        disabled={disabled}\n        label={labels.phoneOptional}\n        name=\"generalInfo.phone\"\n        tooltip={tooltips.phone}\n      />\n    </SectionContent>\n  );\n};\n","import {\n  CountrySelect,\n  FormTextField,\n  SectionContent,\n} from '@finmid/tbl-webapps/components';\nimport { useFormContext } from 'react-hook-form';\n\nimport { useSellerFormLabels } from '../../../SellerFormUtils';\nimport { CreateSellerFormType } from '../../types';\n\ntype SellerLegalAddressFormProps = {\n  disabled: boolean;\n};\n\nexport const SellerLegalAddressForm = ({\n  disabled,\n}: SellerLegalAddressFormProps) => {\n  const { labels, sections } = useSellerFormLabels();\n  const { control } = useFormContext<CreateSellerFormType>();\n\n  return (\n    <SectionContent title={sections.legalAddress}>\n      <FormTextField\n        control={control}\n        disabled={disabled}\n        label={labels.addressLine1}\n        name=\"address.addressLine1\"\n      />\n      <FormTextField\n        control={control}\n        disabled={disabled}\n        label={labels.addressLine2}\n        name=\"address.addressLine2\"\n      />\n      <FormTextField\n        control={control}\n        disabled={disabled}\n        label={labels.postalCode}\n        name=\"address.postalCode\"\n      />\n      <FormTextField\n        control={control}\n        disabled={disabled}\n        label={labels.city}\n        name=\"address.city\"\n      />\n      <FormTextField\n        control={control}\n        disabled={disabled}\n        label={labels.state}\n        name=\"address.state\"\n      />\n      <CountrySelect\n        disabled={disabled}\n        label={labels.country}\n        name=\"address.country\"\n      />\n    </SectionContent>\n  );\n};\n","import {\n  Button,\n  ErrorInfo,\n  NoFormAutofill,\n  Page,\n  PageNavigation,\n  ScrollableFormSection,\n  SectionContent,\n} from '@finmid/tbl-webapps/components';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { Icon, Loader } from '@finmid/ui/ocarina';\nimport { AddRounded } from '@mui/icons-material';\nimport { Box } from '@mui/material';\nimport { FormProvider } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport {\n  useCreateSellerBankAccounts,\n  useCreateSellerPage,\n} from './CreateSellerPage.hook';\nimport {\n  SellerBankAccountsForm,\n  SellerGeneralInfoForm,\n  SellerLegalAddressForm,\n} from './components';\n\nexport const CreateSellerPage = () => {\n  const { t, ready } = useTranslation('sellersPage');\n  const { ready: componentsReady } = useTranslation('components');\n  const { ready: formatsReady } = useTranslation('formats');\n  const breadcrumbs = useBreadcrumbs();\n  const navigate = useNavigate();\n\n  const {\n    methods,\n    handleSubmit,\n    submitDisabled,\n    validationErrors,\n    isLoading,\n    scrollContainerRef,\n    supportedCurrencies,\n    canAddMultipleBankAccounts,\n  } = useCreateSellerPage();\n\n  const { fields, onAdd, remove } = useCreateSellerBankAccounts({\n    control: methods.control,\n  });\n\n  const translationsReady = ready && componentsReady && formatsReady;\n\n  return (\n    <>\n      <PageNavigation breadcrumbs={breadcrumbs.createSeller}>\n        {ready && (\n          <Button\n            variant=\"invisible\"\n            onClick={() => navigate(b2bPaymentRoutes.sellers)}\n          >\n            {t('createSeller.cancelButton')}\n          </Button>\n        )}\n      </PageNavigation>\n      <Page>\n        {!translationsReady && <Loader />}\n\n        {translationsReady && (\n          <form\n            onSubmit={methods.handleSubmit(handleSubmit)}\n            autoComplete=\"off\"\n            css={{ height: '100%' }}\n          >\n            <ScrollableFormSection\n              ref={scrollContainerRef}\n              sectionTitle={t('createSeller.sectionTitle')}\n              footerActions={[\n                <Button\n                  variant=\"primary\"\n                  disabled={submitDisabled}\n                  loading={isLoading}\n                  type=\"submit\"\n                >\n                  {t('createSeller.submitCreateSeller')}\n                </Button>,\n                canAddMultipleBankAccounts ? (\n                  <Box flex={1} display=\"flex\" justifyContent=\"flex-end\">\n                    <Button\n                      onClick={onAdd}\n                      variant=\"invisible\"\n                      suffixIcon={<Icon icon={<AddRounded />} size=\"small\" />}\n                      testId=\"add-item-button\"\n                      type=\"button\"\n                    >\n                      {t('createSeller.bankAccounts.add')}\n                    </Button>\n                  </Box>\n                ) : undefined,\n              ]}\n            >\n              <NoFormAutofill />\n              <FormProvider {...methods}>\n                <SellerGeneralInfoForm disabled={isLoading} />\n                <SellerLegalAddressForm disabled={isLoading} />\n                <SellerBankAccountsForm\n                  disabled={isLoading}\n                  fields={fields}\n                  onRemove={remove}\n                  currencies={supportedCurrencies}\n                  canAddMultipleBankAccounts={canAddMultipleBankAccounts}\n                />\n                {validationErrors?.length ? (\n                  <SectionContent disablePadding css={{ border: 'none' }}>\n                    <ErrorInfo invalidFields={validationErrors} />\n                  </SectionContent>\n                ) : null}\n              </FormProvider>\n            </ScrollableFormSection>\n          </form>\n        )}\n      </Page>\n    </>\n  );\n};\n","import { Seller } from '@finmid/distributor-types';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { useTranslation } from 'react-i18next';\nimport { useLocation, useNavigate } from 'react-router-dom';\n\nexport const useEditSellerPage = () => {\n  const { state } = useLocation();\n\n  const { t } = useTranslation('sellersPage', { keyPrefix: 'editSeller' });\n  const navigate = useNavigate();\n  const { notifySuccess } = useNotifications();\n\n  const handleSuccess = (externalId: string) => {\n    notifySuccess(t('notificationSuccess'));\n    navigate(`${b2bPaymentRoutes.sellers}?view=${externalId}`);\n  };\n\n  return {\n    seller: state?.seller as Seller | undefined,\n    handleSuccess,\n  };\n};\n","import { useHandleFormError } from '@finmid/tbl-webapps/errors-handling';\n\nimport { useSellerFormLabels } from '../../SellerFormUtils';\n\nconst ServerToClientFields: Record<string, string> = {\n  '.externalId': 'externalId',\n  legalName: 'legalName',\n  email: 'email',\n  phone: 'phone',\n\n  addressLine1: 'addressLine1',\n  addressLine2: 'addressLine2',\n  postalCode: 'postalCode',\n  city: 'city',\n  state: 'state',\n  country: 'country',\n};\n\nexport const useHandleEditSellerErrors = () => {\n  const { labels } = useSellerFormLabels();\n  return useHandleFormError({\n    labels,\n    fieldsMap: ServerToClientFields,\n  });\n};\n","import { Seller } from '@finmid/distributor-types';\nimport { ISD_CODE_REGEX, PHONE_REGEX } from '@finmid/tbl-webapps/utils';\nimport { useMemo } from 'react';\nimport * as yup from 'yup';\n\nimport { useSellerFormValidationMessages } from '../../SellerFormUtils';\n\nimport { EditSellerFormType } from './EditSellerForm.types';\n\ntype UseEditSellerValidationSchemaArgs = {\n  seller: Seller;\n};\n\nexport const useEditSellerValidationSchema = ({\n  seller,\n}: UseEditSellerValidationSchemaArgs) => {\n  const { form } = useSellerFormValidationMessages();\n\n  const schema: yup.ObjectSchema<EditSellerFormType> = useMemo(\n    () =>\n      yup.object().shape({\n        legalName: yup.string().max(100).required(form.legalName.required),\n        email: yup\n          .string()\n          .email(form.email.valid)\n          .test('emailAlreadyExists', form.email.required, (email) => {\n            return seller.email == null || seller.email === ''\n              ? true\n              : email !== '';\n          }),\n        phone: yup\n          .string()\n          .matches(ISD_CODE_REGEX, {\n            message: form.phone.plusSign,\n            excludeEmptyString: true,\n          })\n          .matches(PHONE_REGEX, {\n            message: form.phone.phoneRegex,\n            excludeEmptyString: true,\n          }),\n\n        addressLine1: yup\n          .string()\n          .max(100, form.legalAddress.addressLine1.maxLength)\n          .required(form.legalAddress.addressLine1.required),\n        addressLine2: yup\n          .string()\n          .max(100, form.legalAddress.addressLine2.maxLength)\n          .optional(),\n        postalCode: yup\n          .string()\n          .max(20, form.legalAddress.postalCode.maxLength)\n          .required(form.legalAddress.postalCode.required),\n        city: yup\n          .string()\n          .max(100, form.legalAddress.city.maxLength)\n          .required(form.legalAddress.city.required),\n        state: yup\n          .string()\n          .max(100, form.legalAddress.state.maxLength)\n          .optional(),\n        country: yup\n          .string()\n          .typeError(form.legalAddress.country.required)\n          .required(form.legalAddress.country.required),\n      }),\n    [form, seller.email],\n  );\n\n  return schema;\n};\n","import { setValueOrNull } from '@finmid/tbl-webapps/utils';\n\nimport { EditSellerFormType } from './EditSellerForm.types';\n\nexport const getUpdatedSellerValues = ({\n  formValues,\n  initialValues,\n}: {\n  formValues: EditSellerFormType;\n  initialValues: EditSellerFormType;\n}) => {\n  const updatedValues = Object.entries(formValues).reduce((acc, entry) => {\n    const [key, upToDateValue] = entry as [keyof EditSellerFormType, string];\n\n    if (upToDateValue !== initialValues[key]) {\n      acc[key] = setValueOrNull(upToDateValue);\n    }\n    return acc;\n  }, {} as Partial<EditSellerFormType>);\n\n  return updatedValues;\n};\n","import { Seller } from '@finmid/distributor-types';\nimport {\n  ScrollContainerHandle,\n  withErrorProps,\n} from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useEditSellerMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { yupResolver } from '@hookform/resolvers/yup';\nimport posthog from 'posthog-js';\nimport { useEffect, useRef, useState } from 'react';\nimport { useForm } from 'react-hook-form';\n\nimport { useHandleEditSellerErrors } from './EditSellerForm.errors';\nimport { useEditSellerValidationSchema } from './EditSellerForm.schema';\nimport { EditSellerFormType } from './EditSellerForm.types';\nimport { getUpdatedSellerValues } from './EditSellerForm.utils';\n\ntype UseEditSellerFormArgs = {\n  seller: Seller;\n  handleSuccess: (externalId: string) => void;\n};\n\nexport const useEditSellerForm = ({\n  seller,\n  handleSuccess,\n}: UseEditSellerFormArgs) => {\n  const initialValues: EditSellerFormType = {\n    legalName: seller.legalName,\n    email: seller.email ?? '',\n    phone: seller.phone ?? '',\n\n    addressLine1: seller.legalAddress?.addressLine1 ?? '',\n    addressLine2: seller.legalAddress?.addressLine2 ?? '',\n    postalCode: seller.legalAddress?.postalCode ?? '',\n    city: seller.legalAddress?.city ?? '',\n    state: seller.legalAddress?.state ?? '',\n    country: seller.legalAddress?.country ?? '',\n  };\n\n  const editSellerValidationSchema = useEditSellerValidationSchema({\n    seller,\n  });\n\n  const methods = useForm<EditSellerFormType>({\n    resolver: yupResolver(editSellerValidationSchema),\n    defaultValues: initialValues,\n    mode: 'onTouched',\n  });\n\n  const { handleFormError } = useHandleEditSellerErrors();\n  const { displayErrorToast } = useDisplayErrorToast();\n  const [editSeller, { isLoading }] = useEditSellerMutation();\n  const [validationErrors, setValidationErrors] = useState<string[] | null>(\n    null,\n  );\n\n  const handleEditSeller = async (formValues: EditSellerFormType) => {\n    posthog.capture('clicked_edit_seller_confirm');\n\n    try {\n      if (seller.status === 'PENDING') {\n        const updatedValues = getUpdatedSellerValues({\n          formValues,\n          initialValues,\n        });\n        await editSeller({\n          externalId: seller.externalId,\n          ...updatedValues,\n        }).unwrap();\n\n        handleSuccess(seller.externalId);\n      }\n    } catch (error) {\n      const { customError, validationErrors } = handleFormError(error);\n      if (validationErrors) {\n        setValidationErrors(validationErrors);\n      } else {\n        displayErrorToast(\n          withErrorProps({ ...(error as Error), message: customError }),\n        );\n      }\n    }\n  };\n\n  const submitEnabled =\n    methods.formState.isValid && methods.formState.isDirty && !isLoading;\n\n  const scrollContainerRef = useRef<ScrollContainerHandle>(null);\n  useEffect(() => {\n    if (validationErrors != null) scrollContainerRef.current?.scrollToBottom();\n  }, [validationErrors]);\n\n  return {\n    methods,\n    submitEnabled,\n    isLoading,\n    handleEditSeller,\n    validationErrors,\n    scrollContainerRef,\n  };\n};\n","import { Seller } from '@finmid/distributor-types';\nimport { FormTextField, SectionContent } from '@finmid/tbl-webapps/components';\nimport { TextInput } from '@finmid/ui/ocarina';\nimport { Control } from 'react-hook-form';\n\nimport { useSellerFormLabels } from '../../../SellerFormUtils';\nimport { EditSellerFormType } from '../EditSellerForm.types';\n\ntype SellerGeneralInfoFormProps = {\n  control: Control<EditSellerFormType>;\n  seller: Seller;\n};\n\nexport const SellerGeneralInfoForm = ({\n  control,\n  seller,\n}: SellerGeneralInfoFormProps) => {\n  const { labels, sections, tooltips } = useSellerFormLabels();\n\n  return (\n    <SectionContent title={sections.generalInfo}>\n      <TextInput\n        label={labels.externalId}\n        value={seller.externalId}\n        tooltip={tooltips.fieldDisabled}\n        disabled\n        testId=\"externalId\"\n      />\n      <FormTextField\n        control={control}\n        label={labels.legalName}\n        name=\"legalName\"\n      />\n      <TextInput\n        label={labels.businessRegistrationNumber}\n        value={seller.businessRegistrationNumber ?? ''}\n        tooltip={tooltips.fieldDisabled}\n        disabled\n        testId=\"businessRegistrationNumber\"\n      />\n      <TextInput\n        label={labels.taxNumber}\n        value={seller.taxNumber ?? ''}\n        tooltip={tooltips.fieldDisabled}\n        disabled\n        testId=\"taxNumber\"\n      />\n      <FormTextField control={control} label={labels.email} name=\"email\" />\n      <FormTextField\n        control={control}\n        label={labels.phoneOptional}\n        name=\"phone\"\n      />\n    </SectionContent>\n  );\n};\n","import {\n  CountrySelect,\n  FormTextField,\n  SectionContent,\n} from '@finmid/tbl-webapps/components';\nimport { Control } from 'react-hook-form';\n\nimport { useSellerFormLabels } from '../../../SellerFormUtils';\nimport { EditSellerFormType } from '../EditSellerForm.types';\n\ntype SellerLegalAddressFormProps = {\n  control: Control<EditSellerFormType>;\n};\n\nexport const SellerLegalAddressForm = ({\n  control,\n}: SellerLegalAddressFormProps) => {\n  const { labels, sections } = useSellerFormLabels();\n\n  return (\n    <SectionContent title={sections.legalAddress}>\n      <FormTextField\n        control={control}\n        label={labels.addressLine1}\n        name=\"addressLine1\"\n      />\n      <FormTextField\n        control={control}\n        label={labels.addressLine2}\n        name=\"addressLine2\"\n      />\n      <FormTextField\n        control={control}\n        label={labels.postalCode}\n        name=\"postalCode\"\n      />\n      <FormTextField control={control} label={labels.city} name=\"city\" />\n      <FormTextField control={control} label={labels.state} name=\"state\" />\n      <CountrySelect label={labels.country} />\n    </SectionContent>\n  );\n};\n","import { Seller } from '@finmid/distributor-types';\nimport {\n  Button,\n  ErrorInfo,\n  ScrollableFormSection,\n  SectionContent,\n} from '@finmid/tbl-webapps/components';\nimport { FormProvider } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { useEditSellerForm } from './EditSellerForm.hook';\nimport { SellerGeneralInfoForm, SellerLegalAddressForm } from './components';\n\ntype EditSellerFormProps = {\n  seller: Seller;\n  handleSuccess: (externalId: string) => void;\n};\n\nexport const EditSellerForm = ({\n  seller,\n  handleSuccess,\n}: EditSellerFormProps) => {\n  const { t } = useTranslation('sellersPage', { keyPrefix: 'editSeller' });\n\n  const {\n    methods,\n    submitEnabled,\n    isLoading,\n    handleEditSeller,\n    validationErrors,\n    scrollContainerRef,\n  } = useEditSellerForm({\n    seller,\n    handleSuccess,\n  });\n\n  return (\n    <FormProvider {...methods}>\n      <form\n        onSubmit={methods.handleSubmit(handleEditSeller)}\n        data-test-id=\"form-seller-edit\"\n        autoComplete=\"off\"\n        css={{ height: '100%' }}\n      >\n        <ScrollableFormSection\n          ref={scrollContainerRef}\n          sectionTitle={t('sectionTitle')}\n          footerActions={[\n            <Button\n              disabled={!submitEnabled}\n              loading={isLoading}\n              variant=\"primary\"\n              type=\"submit\"\n              testId=\"edit-seller-form-submit-btn\"\n            >\n              {t('saveChangesBtn')}\n            </Button>,\n          ]}\n        >\n          <SellerGeneralInfoForm seller={seller} control={methods.control} />\n          <SellerLegalAddressForm control={methods.control} />\n\n          {validationErrors?.length ? (\n            <SectionContent disablePadding css={{ border: 'none' }}>\n              <ErrorInfo invalidFields={validationErrors} />\n            </SectionContent>\n          ) : null}\n        </ScrollableFormSection>\n      </form>\n    </FormProvider>\n  );\n};\n","import { Button, Page, PageNavigation } from '@finmid/tbl-webapps/components';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\nimport { Navigate, useNavigate } from 'react-router-dom';\n\nimport { useEditSellerPage } from './EditSellerPage.hook';\nimport { EditSellerForm } from './components';\n\nexport const EditSellerPage = () => {\n  const { seller, handleSuccess } = useEditSellerPage();\n  const { t, ready } = useTranslation('sellersPage');\n  const { ready: componentsReady } = useTranslation('components');\n  const breadcrumbs = useBreadcrumbs(seller?.externalId, seller?.legalName);\n  const navigate = useNavigate();\n\n  if (seller == null) {\n    return <Navigate to={b2bPaymentRoutes.sellers} replace={true} />;\n  }\n\n  const goToSellersPage = () =>\n    navigate(`${b2bPaymentRoutes.sellers}?view=${seller.externalId}`);\n\n  const translationsReady = ready && componentsReady;\n\n  return (\n    <>\n      <PageNavigation breadcrumbs={breadcrumbs.sellerEdit}>\n        {ready && (\n          <Button variant=\"invisible\" onClick={goToSellersPage}>\n            {t('cancelEditButtonLabel')}\n          </Button>\n        )}\n      </PageNavigation>\n      <Page>\n        {!translationsReady && <Loader />}\n\n        {translationsReady && (\n          <EditSellerForm seller={seller} handleSuccess={handleSuccess} />\n        )}\n      </Page>\n    </>\n  );\n};\n","import cloneDeep from 'lodash/cloneDeep';\nimport set from 'lodash/set';\nimport { createContext, PropsWithChildren, useContext, useState } from 'react';\nimport { useSessionStorage } from 'react-use';\n\nimport {\n  SellersFilters,\n  sellersFiltersKey,\n  UpdateSellersFilters,\n  useDefaultFilters,\n} from '../SellersFilters';\n\ntype ListContext = {\n  filters: SellersFilters;\n  resetFilters: () => void;\n  updateFilters: (filters: UpdateSellersFilters) => void;\n};\n\nconst initialContext = null;\n\nexport const SellersListContext = createContext<ListContext | null>(\n  initialContext,\n);\n\nexport const SellersListContextProvider = ({ children }: PropsWithChildren) => {\n  const { defaultSellersFilters } = useDefaultFilters();\n\n  const [storedFilters, setStoredFilters] =\n    useSessionStorage<SellersFilters>(sellersFiltersKey);\n\n  const [filters, setFilters] = useState<SellersFilters>(() => {\n    return storedFilters ?? defaultSellersFilters;\n  });\n\n  const updateFilters = (updatedFilters: UpdateSellersFilters) => {\n    const _filters = cloneDeep(filters);\n    Object.entries(updatedFilters).forEach(([key, value]) => {\n      set(_filters, key, value);\n    });\n    setStoredFilters(_filters);\n    setFilters(_filters);\n  };\n\n  const resetFilters = () => {\n    setStoredFilters(defaultSellersFilters);\n    setFilters(defaultSellersFilters);\n  };\n\n  const value = {\n    filters,\n    resetFilters,\n    updateFilters,\n  };\n\n  return (\n    <SellersListContext.Provider value={value}>\n      {children}\n    </SellersListContext.Provider>\n  );\n};\n\nexport const useSellersListContext = () => {\n  const context = useContext(SellersListContext);\n\n  if (context == null) {\n    throw new Error(\n      'useSellersListContext can only be used inside SellersListContext Provider',\n    );\n  }\n\n  return context;\n};\n","import { getCountry } from '@finmid/countries';\nimport {\n  BankAccountResponse,\n  PaymentRails,\n  Seller,\n} from '@finmid/distributor-types';\nimport { ItemsList, ProfileDetails } from '@finmid/tbl-webapps/components';\nimport { TFunction } from 'i18next';\nimport { friendlyFormatIBAN } from 'ibantools';\nimport { useTranslation } from 'react-i18next';\n\ninterface Props {\n  seller: Seller;\n}\n\nexport const SellerDetailsTab = ({ seller }: Props) => {\n  const { t } = useTranslation(['sellersPage', 'sidebar']);\n  const country =\n    getCountry(seller.legalAddress?.country ?? null)?.name ??\n    seller.legalAddress?.country;\n\n  return (\n    <ProfileDetails\n      sections={[\n        {\n          testId: 'sme-details',\n          lists: [\n            {\n              items: [\n                {\n                  label: t('details.nameAndId'),\n                  value: seller.legalName,\n                  detail: seller.externalId,\n                },\n                {\n                  label: t('details.registrationNumber'),\n                  value: seller.businessRegistrationNumber,\n                },\n                {\n                  label: t('details.taxNumber'),\n                  value: seller.taxNumber,\n                },\n              ],\n            },\n          ],\n        },\n        {\n          title: t('contactInfo', { ns: 'sidebar' }),\n          testId: 'contact-information',\n          lists: [\n            {\n              items: [\n                {\n                  label: t('details.email'),\n                  value: seller.email,\n                },\n                {\n                  label: t('details.phone'),\n                  value: seller.phone,\n                },\n                {\n                  label: t('details.address'),\n                  value: seller.legalAddress?.addressLine1 || '',\n                  detail: seller.legalAddress\n                    ? `${seller.legalAddress?.city}, ${country} ${seller.legalAddress?.postalCode}`\n                    : undefined,\n                },\n              ],\n            },\n          ],\n        },\n        {\n          title: t('details.sectionSellerBankAccounts'),\n          testId: 'section-bank-account',\n          lists: seller.bankAccounts\n            .map((account) => bankAccountSection(t, account))\n            .filter((a) => a !== null)\n            .map((a) => ({ items: a, testId: 'bank-accounts-container' })),\n        },\n      ]}\n    />\n  );\n};\n\nconst bankAccountSection = (\n  t: TFunction<['sellersPage', 'sidebar']>,\n  account: BankAccountResponse,\n): ItemsList | null => {\n  if ('accountNumberType' in account) {\n    return [\n      {\n        label: t('details.bankName'),\n        value: account.bankName,\n      },\n      {\n        label:\n          account.accountNumberType === 'IBAN'\n            ? t('details.iban')\n            : t('details.accountNumber'),\n        value:\n          account.accountNumberType === 'IBAN'\n            ? friendlyFormatIBAN(account.accountNumber)\n            : account.accountNumber,\n      },\n      {\n        label: t('details.bic'),\n        value: account.bicSwift,\n      },\n      {\n        label: t('details.addressLine'),\n        value: account.address.addressLine,\n      },\n      {\n        label: t('details.city'),\n        value: account.address.city,\n      },\n      {\n        label: t('details.country'),\n        value: account.address.country,\n      },\n      {\n        label: t('details.currency'),\n        value: `${account.currency} (${PaymentRails.SWIFT})`,\n      },\n    ];\n  }\n  if ('sortCode' in account) {\n    return [\n      {\n        label: t('details.bankName'),\n        value: account.bankName,\n      },\n      {\n        label: t('details.accountNumber'),\n        value: account.accountNumber,\n      },\n      {\n        label: t('details.sortCode'),\n        value: account.sortCode,\n      },\n      {\n        label: t('details.bankCode'),\n        value: account.bankCode,\n      },\n      {\n        label: t('details.currency'),\n        value: `${account.currency} (${PaymentRails.FPS})`,\n      },\n    ];\n  }\n  if ('iban' in account) {\n    return [\n      {\n        label: t('details.bankName'),\n        value: account.bankName,\n      },\n      {\n        label: t('details.bic'),\n        value: account.bic,\n      },\n      {\n        label: t('details.iban'),\n        value: friendlyFormatIBAN(account.iban),\n      },\n      {\n        label: t('details.currency'),\n        value: `${account.currency} (${PaymentRails.SEPA})`,\n      },\n    ];\n  }\n  return null;\n};\n","import type { PaymentRequest, Seller } from '@finmid/distributor-types';\nimport { SectionContainer } from '@finmid/tbl-webapps/components';\nimport {\n  ButtonsTabs,\n  PaymentRequestsTab,\n} from '@finmid/tbl-webapps/payment-requests';\nimport Box from '@mui/material/Box';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { SellerDetailsTab } from './SellerDetailsTab';\n\ntype Tab = 'DETAILS' | 'PAYMENT_REQUEST';\n\ninterface Props {\n  seller: Seller;\n  paymentRequests?: PaymentRequest[];\n}\n\nexport const SellerDetailsSection = ({\n  seller,\n  paymentRequests = [],\n}: Props) => {\n  const [tab, setTab] = useState<Tab>('DETAILS');\n  const { t } = useTranslation('sidebar');\n  const buttons = [\n    {\n      label: t('details'),\n      onClick: () => {\n        posthog.capture('clicked-seller-sidebar-details-tab');\n        setTab('DETAILS');\n      },\n      testId: 'seller-details-sidebar-details-button',\n    },\n    {\n      label: t('paymentRequests'),\n      onClick: () => {\n        posthog.capture('clicked-seller-sidebar-payment-requests-tab');\n        setTab('PAYMENT_REQUEST');\n      },\n      testId: 'seller-details-sidebar-payment-request-button',\n    },\n  ];\n\n  let tabElement = null;\n  switch (tab) {\n    case 'DETAILS':\n      tabElement = <SellerDetailsTab seller={seller} />;\n      break;\n    case 'PAYMENT_REQUEST':\n      tabElement = (\n        <PaymentRequestsTab paymentRequests={paymentRequests} seller={seller} />\n      );\n      break;\n  }\n\n  return (\n    <SectionContainer className=\"section-container\">\n      <Box mx={0.5}>\n        <ButtonsTabs fullWidth buttons={buttons} />\n      </Box>\n\n      {tabElement}\n    </SectionContainer>\n  );\n};\n","import { Seller } from '@finmid/distributor-types';\nimport { SuspendSmeFormDialog } from '@finmid/tbl-webapps/components';\nimport { Dispatch, SetStateAction } from 'react';\nimport { useTranslation } from 'react-i18next';\n\ntype SuspendSellerDialogProps = {\n  open: boolean;\n  setOpen: Dispatch<SetStateAction<boolean>>;\n  isLoading: boolean;\n  onSuspend: (reason: string) => Promise<void>;\n  seller: Seller;\n};\n\nexport const SuspendSellerDialog = ({\n  open,\n  setOpen,\n  isLoading,\n  onSuspend,\n  seller,\n}: SuspendSellerDialogProps) => {\n  const { t } = useTranslation('sellersPage', {\n    keyPrefix: 'suspendSeller',\n  });\n\n  return (\n    <SuspendSmeFormDialog\n      message={t('message', { sellerLegalName: seller.legalName })}\n      open={open}\n      title={t('title')}\n      handleSuspend={onSuspend}\n      setOpen={setOpen}\n      isProcessing={isLoading}\n    />\n  );\n};\n","import { Seller } from '@finmid/distributor-types';\nimport { withErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useSuspendSellerMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { MenuItem, Tooltip } from '@finmid/ui/ocarina';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { SuspendSellerDialog } from './SuspendSellerDialog';\n\ntype SuspendSellerProps = {\n  seller: Seller;\n};\n\nexport const SuspendSellerMenuItem = ({ seller }: SuspendSellerProps) => {\n  const { t, ready } = useTranslation('sellersPage', {\n    keyPrefix: 'suspendSeller',\n  });\n  const { notifySuccess } = useNotifications();\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const [open, setOpen] = useState(false);\n\n  const [suspendSeller, { isLoading }] = useSuspendSellerMutation();\n\n  const sellerLegalName = seller.legalName;\n\n  const handleSuspendSeller = async (reason: string) => {\n    posthog.capture('clicked_suspend_seller_confirm');\n\n    try {\n      await suspendSeller({ externalId: seller.externalId, reason }).unwrap();\n      notifySuccess(t('successMessage', { sellerLegalName }));\n    } catch (error) {\n      displayErrorToast(\n        withErrorProps({\n          ...(error as Error),\n          message: t('errorMessage', { sellerLegalName }),\n        }),\n      );\n    }\n  };\n\n  const sellerIsDisabled = ['SUSPENDED', 'REJECTED'].includes(seller.status);\n  const canSuspendSeller = !sellerIsDisabled;\n\n  const disabled = !ready || !canSuspendSeller;\n\n  return (\n    <>\n      <Tooltip\n        title={\n          disabled\n            ? t('tooltip.sellerStatus', { status: seller.status.toLowerCase() })\n            : ''\n        }\n        placement=\"left\"\n      >\n        <MenuItem\n          onClick={() => {\n            posthog.capture('clicked-seller-sidebar-suspend-menu-item');\n            setOpen(true);\n          }}\n          disabled={disabled}\n          data-test-id=\"suspend-seller-menu-item\"\n        >\n          {t('title')}\n        </MenuItem>\n      </Tooltip>\n      <SuspendSellerDialog\n        seller={seller}\n        open={open}\n        setOpen={setOpen}\n        isLoading={isLoading}\n        onSuspend={handleSuspendSeller}\n      />\n    </>\n  );\n};\n","import { Seller } from '@finmid/distributor-types';\nimport { b2bPaymentRoutes } from '@finmid/tbl-webapps/routes';\nimport { MenuItem, Tooltip } from '@finmid/ui/ocarina';\nimport posthog from 'posthog-js';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\ntype SuspendSellerProps = {\n  seller: Seller;\n};\n\nexport const EditSellerMenuItem = ({ seller }: SuspendSellerProps) => {\n  const { t, ready } = useTranslation('sellersPage', {\n    keyPrefix: 'actions.editSeller',\n  });\n  const navigate = useNavigate();\n\n  const navigateToEditPage = () => {\n    posthog.capture('clicked-seller-sidebar-edit');\n    navigate(`${b2bPaymentRoutes.sellers}/${seller.externalId}/edit`, {\n      state: { seller },\n    });\n  };\n\n  const disabled = !ready || seller.status !== 'PENDING';\n\n  return (\n    <Tooltip title={disabled ? t('tooltip.sellerStatus') : ''} placement=\"left\">\n      <MenuItem\n        onClick={navigateToEditPage}\n        disabled={disabled}\n        data-test-id=\"edit-seller-menu-item\"\n      >\n        {t('btnLabel')}\n      </MenuItem>\n    </Tooltip>\n  );\n};\n","import { Seller } from '@finmid/distributor-types';\nimport { CreatePaymentRequestMenuItem } from '@finmid/tbl-webapps/payment-requests';\nimport {\n  Dropdown,\n  Menu,\n  MenuIconButton,\n  MenuSection,\n  MoreVerticalIcon,\n} from '@finmid/ui/ocarina';\n\nimport { EditSellerMenuItem, SuspendSellerMenuItem } from './MenuItems';\n\ninterface Props {\n  seller: Seller;\n}\n\nexport const SellerDetailsMenu = ({ seller }: Props) => {\n  if (!seller) {\n    return null;\n  }\n\n  return (\n    <Dropdown>\n      <MenuIconButton\n        icon={<MoreVerticalIcon />}\n        variant=\"invisible\"\n        data-test-id=\"seller-actions-menu-button\"\n      />\n      <Menu\n        placement=\"bottom-end\"\n        data-test-id=\"menu-kebab\"\n        style={{ zIndex: 1400 }}\n      >\n        <MenuSection>\n          <EditSellerMenuItem seller={seller} />\n        </MenuSection>\n        <MenuSection>\n          <SuspendSellerMenuItem seller={seller} />\n        </MenuSection>\n        <MenuSection>\n          <CreatePaymentRequestMenuItem seller={seller} />\n        </MenuSection>\n      </Menu>\n    </Dropdown>\n  );\n};\n","import { isNotFoundError } from '@finmid/distributor-types';\nimport { fetchErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport {\n  useGetSellerByIdQuery,\n  useGetSellersPaymentRequestsQuery,\n} from '@finmid/tbl-webapps/gateway-api';\nimport posthog from 'posthog-js';\nimport { useEffect, useState } from 'react';\n\nexport type Tab = 'transactions' | 'details';\n\nexport const useGetSellerDetails = (sellerId: string) => {\n  const [tab, setTab] = useState<Tab>('details');\n\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const {\n    data: seller,\n    isFetching: isFetchingSeller,\n    error: errorSeller,\n  } = useGetSellerByIdQuery(\n    { externalId: sellerId ?? '' },\n    { skip: !sellerId },\n  );\n\n  const {\n    data: paymentRequests,\n    isError: isErrorPaymentRequests,\n    isFetching: isFetchingPaymentRequests,\n    error: errorPaymentRequests,\n  } = useGetSellersPaymentRequestsQuery(\n    { externalId: sellerId ?? '' },\n    { skip: !sellerId },\n  );\n\n  useEffect(() => {\n    if (\n      (errorSeller != null && !isNotFoundError(errorSeller)) ||\n      isErrorPaymentRequests\n    ) {\n      displayErrorToast(fetchErrorProps);\n    }\n  }, [errorSeller, isErrorPaymentRequests, displayErrorToast]);\n\n  const handleTabChange = (tab: Tab) => {\n    setTab(tab);\n    posthog.capture(`clicked_tab_seller_${tab}`);\n  };\n\n  return {\n    tab,\n    handleTabChange,\n    seller,\n    errorSeller,\n    paymentRequests,\n    errorPaymentRequests,\n    isFetching: isFetchingSeller || isFetchingPaymentRequests,\n  };\n};\n","import {\n  Drawer,\n  ProfileStatusSection,\n  SmeStatusDrawerAlert,\n  ZeroState,\n} from '@finmid/tbl-webapps/components';\nimport { LatestPRSection } from '@finmid/tbl-webapps/payment-requests';\nimport { Button, Loader, Spacer } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport { SellerDetailsSection } from './components';\nimport { SellerDetailsMenu } from './components/SellerDetailsMenu';\nimport { useGetSellerDetails } from './getSellerDetails.hook';\ninterface SellerDetailsSidebarProps {\n  open: boolean;\n  closeSidebar: () => void;\n  sellerId: string;\n}\n\nexport const SellerDetailsSidebar = ({\n  open,\n  closeSidebar,\n  sellerId,\n}: SellerDetailsSidebarProps) => {\n  const {\n    seller,\n    paymentRequests,\n    isFetching,\n    errorSeller,\n    errorPaymentRequests,\n  } = useGetSellerDetails(sellerId);\n  const latestPR = paymentRequests?.[0];\n  const { t, ready } = useTranslation(['sellersPage', 'sidebar'], {\n    keyPrefix: 'sidebar',\n  });\n\n  let element;\n\n  if (errorSeller || errorPaymentRequests) {\n    element = (\n      <ZeroState\n        title={t('notFoundTitle')}\n        description={t('notFoundDescription')}\n      >\n        <Button variant=\"primary\" onClick={closeSidebar}>\n          {t('backBtnLabel')}\n        </Button>\n      </ZeroState>\n    );\n  } else if (isFetching || !ready || !seller) {\n    element = <Loader />;\n  } else {\n    element = (\n      <>\n        <ProfileStatusSection\n          status={seller.status}\n          name={seller.legalName}\n          menu={<SellerDetailsMenu seller={seller} />}\n        />\n        <SmeStatusDrawerAlert seller={seller} />\n        {latestPR && (\n          <>\n            <LatestPRSection paymentRequest={latestPR} />\n            <Spacer height={2} />\n          </>\n        )}\n        <SellerDetailsSection\n          seller={seller}\n          paymentRequests={paymentRequests}\n        />\n      </>\n    );\n  }\n\n  return (\n    <Drawer title={t('heading')} open={open} onClose={closeSidebar}>\n      {element}\n    </Drawer>\n  );\n};\n","import { Seller } from '@finmid/distributor-types';\nimport { GridRowParams } from '@mui/x-data-grid';\nimport { useEffect, useState } from 'react';\nimport { useSearchParams } from 'react-router-dom';\n\nexport const useShowSellerDetails = () => {\n  const [searchParams, setSearchParams] = useSearchParams();\n  const [isSidebarOpen, setIsSidebarOpen] = useState(false);\n  const [selectedSellerId, setSelectedSellerId] = useState<string>('');\n\n  useEffect(() => {\n    const view = searchParams.get('view');\n    if (view) {\n      setSelectedSellerId(view);\n      setIsSidebarOpen(true);\n    }\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n  }, []);\n\n  const closeSidebar = () => {\n    setSearchParams({});\n    setIsSidebarOpen(false);\n  };\n\n  const triggerOpenSidebar = (id: string) => {\n    setIsSidebarOpen(true);\n    setSelectedSellerId(id);\n  };\n\n  const onRowClick = ({ row: { externalId } }: GridRowParams<Seller>) => {\n    const params = { view: externalId };\n    setSearchParams(params);\n    triggerOpenSidebar(externalId);\n  };\n\n  return {\n    isSidebarOpen,\n    selectedSellerId,\n    closeSidebar,\n    onRowClick,\n  };\n};\n","import {\n  SellerStatusUpdatedFilters,\n  SellerStatusSelector,\n} from '@finmid/tbl-webapps/components';\nimport { useLazyGetSellersStatsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useEffect } from 'react';\n\nimport { useSellersListContext } from '../../SellersPage.context';\n\nexport const SellersStatusSelect = () => {\n  const { filters, updateFilters } = useSellersListContext();\n\n  const [fetchStats, { data: sellersStats }] = useLazyGetSellersStatsQuery();\n\n  const handleUpdateFilters = (updatedFilters: SellerStatusUpdatedFilters) => {\n    updateFilters(updatedFilters);\n  };\n\n  useEffect(() => {\n    fetchStats({ search: filters.server.search });\n  }, [filters, fetchStats]);\n\n  if (!sellersStats) {\n    return null;\n  }\n\n  return (\n    <SellerStatusSelector\n      selectedStatus={filters.server.status ?? 'ALL'}\n      onChange={handleUpdateFilters}\n      stats={sellersStats}\n    />\n  );\n};\n","import { Seller } from '@finmid/distributor-types';\nimport {\n  SmeStatusIndicator,\n  TruncatedContent,\n} from '@finmid/tbl-webapps/components';\nimport { GridColDef, GridRenderCellParams } from '@mui/x-data-grid';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nexport const useColumns = (): GridColDef[] => {\n  const { t } = useTranslation('sellersPage', { keyPrefix: 'table' });\n\n  return useMemo(\n    () =>\n      [\n        {\n          field: 'status',\n          headerName: '',\n          sortable: false,\n          align: 'center',\n          width: 48,\n          renderCell: ({ row: { status } }) => (\n            <SmeStatusIndicator status={status} />\n          ),\n        },\n        {\n          field: 'id',\n          headerName: t('headerSellerId'),\n          sortable: false,\n          align: 'left',\n          minWidth: 220,\n          renderCell: ({\n            row: { externalId },\n          }: GridRenderCellParams<Seller>) => (\n            <TruncatedContent content={externalId} testId={externalId} />\n          ),\n        },\n        {\n          field: 'legalName',\n          headerName: t('headerLegalName'),\n          sortable: false,\n          minWidth: 120,\n          flex: 1,\n          renderCell: ({ row: { legalName } }) => (\n            <div style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>\n              {legalName}\n            </div>\n          ),\n        },\n      ] as GridColDef<Seller>[],\n    [t],\n  ) as GridColDef[];\n};\n","import { GetSellers_GatewayResponse } from '@finmid/distributor-types';\nimport { fetchErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useGetSellersStatsQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useCallback, useEffect, useState } from 'react';\n\nimport { useSellersListContext } from '../../SellersPage.context';\n\nexport const usePagination = ({\n  nextCursor,\n  previousCursor,\n}: GetSellers_GatewayResponse['metadata']) => {\n  // TODO: check how to reduce code duplication with buyers\n  const {\n    filters: { firstPosition, server },\n    updateFilters,\n  } = useSellersListContext();\n\n  const { limit, search, status, cursor } = server;\n\n  const paginationState = {\n    page: Math.floor(firstPosition / limit),\n    pageSize: limit,\n  };\n\n  const { sellersStats, isErrorStats, isFetchingStats } =\n    useGetSellersWithRefreshOnNewSeller(search);\n\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  useEffect(() => {\n    if (isErrorStats) {\n      displayErrorToast(fetchErrorProps);\n    }\n  }, [isErrorStats, displayErrorToast]);\n\n  const onPaginationBack = useCallback(async () => {\n    if (previousCursor != null) {\n      const updatedFilters = {\n        firstPosition: Math.max(firstPosition - limit, 1),\n        'server.cursor':\n          firstPosition < limit\n            ? undefined\n            : previousCursor === cursor\n            ? undefined\n            : previousCursor,\n      };\n      updateFilters(updatedFilters);\n    }\n  }, [cursor, firstPosition, limit, previousCursor, updateFilters]);\n\n  const onPaginationNext = useCallback(async () => {\n    if (nextCursor != null) {\n      const updatedFilters = {\n        firstPosition: firstPosition + limit,\n        'server.cursor': nextCursor,\n      };\n      updateFilters(updatedFilters);\n    }\n  }, [firstPosition, limit, nextCursor, updateFilters]);\n\n  const currentStatus = status ?? 'ALL';\n\n  const rowsCount = sellersStats?.[currentStatus] ?? 0;\n\n  const onPageSizeChange = useCallback(\n    async (pageSize: number) => {\n      const updatedFilters = {\n        'server.limit': pageSize,\n        // reset cursor and firstPosition\n        firstPosition: 1,\n        'server.cursor': undefined,\n      };\n      updateFilters(updatedFilters);\n    },\n    [updateFilters],\n  );\n\n  return {\n    rowsCount,\n    onPaginationBack,\n    onPaginationNext,\n    onPageSizeChange,\n    paginationState,\n\n    loading: isFetchingStats,\n  };\n};\n\nconst useGetSellersWithRefreshOnNewSeller = (search: string | undefined) => {\n  const [lastSearch, setLastSearch] = useState<{\n    search: string;\n    count: number;\n  } | null>(null);\n\n  const { updateFilters } = useSellersListContext();\n\n  const {\n    data: stats,\n    isError: isErrorStats,\n    isFetching: isFetchingStats,\n  } = useGetSellersStatsQuery({ search });\n\n  useEffect(() => {\n    if (stats == null || isFetchingStats) return;\n    if (search == null) return;\n\n    if (lastSearch == null) {\n      setLastSearch({\n        search,\n        count: stats.ALL,\n      });\n    } else if (lastSearch.search !== search && stats.ALL !== lastSearch.count) {\n      setLastSearch({\n        search,\n        count: stats.ALL,\n      });\n    } else if (lastSearch.search === search && stats.ALL !== lastSearch.count) {\n      setLastSearch({\n        search,\n        count: stats.ALL,\n      });\n      updateFilters({\n        firstPosition: 0,\n        'server.cursor': undefined,\n      });\n    }\n  }, [lastSearch, search, stats, isFetchingStats, updateFilters]);\n\n  return {\n    sellersStats: stats,\n    isErrorStats,\n    isFetchingStats,\n  };\n};\n","import { useSearchInputFilter } from '@finmid/tbl-webapps/components';\nimport debounce from 'lodash/debounce';\nimport { useMemo } from 'react';\n\nimport { useSellersListContext } from '../../SellersPage.context';\n\nconst debounceMs = 200;\n\nexport const useSearch = () => {\n  const { filters, updateFilters } = useSellersListContext();\n\n  const onSearch = useMemo(() => {\n    return debounce(updateFilters, debounceMs);\n  }, [updateFilters]);\n\n  const { handleChange } = useSearchInputFilter({\n    handleUpdateFilters: onSearch,\n    searchValue: filters.server.search,\n  });\n\n  return { onSearch: handleChange, searchValue: filters.server.search };\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport { fetchErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useGetSellersQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useEffect } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useSellersListContext } from '../../SellersPage.context';\n\nimport { useColumns } from './useColumns';\nimport { usePagination } from './usePagination';\nimport { useSearch } from './useSearch';\n\nexport const useSellersTable = () => {\n  const { t } = useTranslation('sellersPage', { keyPrefix: 'table' });\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const { filters } = useSellersListContext();\n\n  const {\n    data: sellersResponse,\n    isError: sellersIsError,\n    isFetching: sellersIsFetching,\n  } = useGetSellersQuery(filters.server);\n\n  const sellers = sellersResponse?.data;\n\n  const columns = useColumns();\n\n  useEffect(() => {\n    if (sellersIsError) {\n      displayErrorToast(fetchErrorProps);\n    }\n  }, [sellersIsError, displayErrorToast]);\n\n  const {\n    loading: loadingPagination,\n    onPaginationBack,\n    onPaginationNext,\n    onPageSizeChange,\n    paginationState,\n    rowsCount,\n  } = usePagination({\n    nextCursor: sellersResponse?.metadata?.nextCursor ?? null,\n    previousCursor: sellersResponse?.metadata?.previousCursor ?? null,\n  });\n\n  const { onSearch, searchValue } = useSearch();\n\n  const zeroStateDescriptionNoFilter =\n    ENVIRONMENT === 'live'\n      ? t('noSellersMessageLive')\n      : t('noSellersMessageTest');\n  const zeroStateDescription =\n    filters.server.status || filters.server.search\n      ? t('zeroStateDescriptionWithFilters')\n      : zeroStateDescriptionNoFilter;\n\n  return {\n    t,\n    sellers,\n    zeroStateDescription,\n\n    loading: loadingPagination || sellersIsFetching,\n\n    onPaginationBack,\n    onPaginationNext,\n    onPageSizeChange,\n    paginationState,\n    rowsCount,\n\n    onSearch,\n    searchValue,\n\n    columns,\n  };\n};\n","import {\n  ErrorBoundary,\n  LazyLoadFallback,\n  ZeroState,\n} from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { Suspense, lazy } from 'react';\n\nimport { SellerDetailsSidebar } from '../SellerDetailSidebar';\nimport { useShowSellerDetails } from '../SellerDetailSidebar/ShowBuyerDetails.hook';\n\nimport { SellersStatusSelect } from './SellersStatusSelect';\nimport { useSellersTable } from './SellersTable.hook';\n\nconst DataGrid = lazy(() => import('@finmid/tbl-webapps/components/DataGrid'));\n\nexport const SellersTable = () => {\n  const {\n    t,\n    sellers,\n    loading,\n    zeroStateDescription,\n    onSearch,\n    searchValue,\n    rowsCount,\n    onPaginationBack,\n    onPaginationNext,\n    paginationState,\n    onPageSizeChange,\n    columns,\n  } = useSellersTable();\n\n  const { onRowClick, selectedSellerId, isSidebarOpen, closeSidebar } =\n    useShowSellerDetails();\n\n  const isEmpty = sellers != null && sellers.length === 0;\n\n  return (\n    <ErrorBoundary fallback={<LazyLoadFallback />}>\n      <Suspense fallback={<Loader />}>\n        {selectedSellerId ? (\n          <SellerDetailsSidebar\n            open={isSidebarOpen}\n            closeSidebar={closeSidebar}\n            sellerId={selectedSellerId}\n          />\n        ) : null}\n        <DataGrid\n          disableColumnMenu\n          rows={isEmpty ? [] : sellers ?? []}\n          getRowId={(row) => row.externalId}\n          columns={columns}\n          rowCount={rowsCount}\n          initialState={{\n            pagination: { paginationModel: paginationState },\n          }}\n          paginationMode=\"server\"\n          onPaginationBack={onPaginationBack}\n          onPaginationNext={onPaginationNext}\n          pageSizeOptions={[10, 20, 30]}\n          onPageSizeChange={onPageSizeChange}\n          loading={loading}\n          onRowClick={onRowClick}\n          toolbar={{\n            title: '',\n            onSearch,\n            searchValue,\n            actionsBar: <SellersStatusSelect />,\n          }}\n          slots={{\n            noResultsOverlay: () => (\n              <ZeroState\n                title={t('zeroStateTitle')}\n                description={zeroStateDescription}\n              />\n            ),\n            noRowsOverlay: () => (\n              <ZeroState\n                title={t('zeroStateTitle')}\n                description={zeroStateDescription}\n              />\n            ),\n          }}\n          autoHeight\n          sx={{ '--DataGrid-overlayHeight': '200px' }}\n          hideFooter={sellers != null && sellers.length === 0}\n        />\n      </Suspense>\n    </ErrorBoundary>\n  );\n};\n","import { PageNavigation } from '@finmid/tbl-webapps/components';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { useTranslation } from 'react-i18next';\n\nimport { CreateSellerPageButton } from '../../CreateSellerPage';\n\nexport const SellersPageNavigation = () => {\n  const breadcrumbs = useBreadcrumbs();\n  const { ready } = useTranslation('sellersPage');\n\n  return (\n    <PageNavigation breadcrumbs={breadcrumbs.sellers}>\n      {ready && <CreateSellerPageButton />}\n    </PageNavigation>\n  );\n};\n","import { Page } from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport { SellersListContextProvider } from './SellersPage.context';\nimport { SellersPageNavigation, SellersTable } from './components';\n\nexport const SellersPage = () => {\n  const { ready: sellersPageReady } = useTranslation('sellersPage');\n  const { ready: componentsReady } = useTranslation('components');\n\n  const loading = !sellersPageReady || !componentsReady;\n\n  return (\n    <>\n      <SellersPageNavigation />\n      <Page>\n        {loading && <Loader />}\n\n        <SellersListContextProvider>\n          {!loading && <SellersTable />}\n        </SellersListContextProvider>\n      </Page>\n    </>\n  );\n};\n","import { AnalyticsPage } from '@finmid/tbl-webapps/analytics';\nimport {\n  BuyerDocumentsUploadPage,\n  BuyersPage,\n  CreateBuyerPage,\n  EditBuyerPage,\n} from '@finmid/tbl-webapps/buyers';\nimport {\n  CreateMultiplePaymentRequestsPage,\n  CreatePaymentRequestOnePage,\n  PaymentRequestDocumentUploadPage,\n  PaymentRequestsPage,\n} from '@finmid/tbl-webapps/payment-requests';\nimport {\n  b2bPaymentRoutes,\n  sharedRoutes,\n  sharedTblRoutes,\n} from '@finmid/tbl-webapps/routes';\nimport {\n  CreateSellerPage,\n  EditSellerPage,\n  SellersPage,\n} from '@finmid/tbl-webapps/sellers';\nimport { Navigate, Route } from 'react-router-dom';\n\n// TODO: Extract TBL router to module\nexport const B2bPaymentsRouter = (\n  <>\n    <Route\n      path={sharedRoutes.root}\n      element={<Navigate to={b2bPaymentRoutes.paymentRequests} replace />}\n    />\n    <Route path={b2bPaymentRoutes.paymentRequests}>\n      <Route index Component={PaymentRequestsPage} />\n      <Route\n        path={b2bPaymentRoutes.createPaymentRequest}\n        Component={CreatePaymentRequestOnePage}\n      />\n      <Route\n        path={b2bPaymentRoutes.createPaymentRequestsBulk}\n        Component={CreateMultiplePaymentRequestsPage}\n      />\n      <Route\n        path={b2bPaymentRoutes.paymentRequestDocumentUpload}\n        Component={PaymentRequestDocumentUploadPage}\n      />\n    </Route>\n    <Route path={sharedTblRoutes.buyers}>\n      <Route index Component={BuyersPage} />\n      <Route path={sharedTblRoutes.createBuyers} Component={CreateBuyerPage} />\n      <Route path={sharedTblRoutes.editBuyer} Component={EditBuyerPage} />\n      <Route\n        path={sharedTblRoutes.buyerDocumentsUpload}\n        Component={BuyerDocumentsUploadPage}\n      />\n    </Route>\n    <Route path={b2bPaymentRoutes.analytics} Component={AnalyticsPage} />\n    <Route path={b2bPaymentRoutes.sellers}>\n      <Route index Component={SellersPage} />\n      <Route\n        path={b2bPaymentRoutes.createSeller}\n        Component={CreateSellerPage}\n      />\n      <Route path={b2bPaymentRoutes.editSeller} Component={EditSellerPage} />\n    </Route>\n\n    <Route path=\"*\" element={<Navigate replace to={sharedRoutes.root} />} />\n  </>\n);\n","import type { ResourceKey } from 'i18next';\n\n// Dynamic imports so each language/namespace pair ships as its own lazy chunk —\n// only what the active language actually uses is downloaded.\nconst localeImports = import.meta.glob<{ default: ResourceKey }>(\n  '../locales/*/*.json',\n);\n\nexport async function loadResources(\n  language: string,\n  namespace: string,\n): Promise<ResourceKey> {\n  const load = localeImports[`../locales/${language}/${namespace}.json`];\n  if (load == null) return {};\n  return (await load()).default;\n}\n","import { supportedLanguages } from '@finmid/tbl-webapps/utils';\nimport {\n  detectedLanguageConverter,\n  initializeTranslations as initializeTranslationsBase,\n} from '@finmid/translations';\nimport { createInstance, i18n } from 'i18next';\n\nimport { loadResources } from './loadResources';\n\nexport function initializeTranslations(): Promise<i18n> {\n  return initializeTranslationsBase(\n    {\n      loadResources,\n      fallbackLng: {\n        default: ['en'],\n      },\n      useSuspense: false,\n      detectorOptions: {\n        convertDetectedLanguage: detectedLanguageConverter(supportedLanguages),\n      },\n    },\n    createInstance(),\n    supportedLanguages,\n  );\n}\n","import { ApiKey } from '@finmid/distributor-types';\nimport { ENVIRONMENT } from '@finmid/environment';\nimport { Button, Tooltip } from '@finmid/tbl-webapps/components';\nimport { usePlatformId } from '@finmid/tbl-webapps/hooks';\nimport { isFinmidTestDistributor } from '@finmid/tbl-webapps/utils';\nimport { Icon } from '@finmid/ui/ocarina';\nimport { AddRounded } from '@mui/icons-material';\nimport { Box } from '@mui/material';\nimport { ReactElement } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nconst MAX_SANDBOX_API_KEYS = 50;\n\ntype GenerateApiKeyButtonProps = {\n  apiTokens?: ApiKey[];\n  loading: boolean;\n  onClick: () => void;\n};\n\ntype ConditionalTooltipProps = {\n  children: ReactElement;\n  show: boolean;\n};\n\nconst ConditionalTooltip = ({ children, show }: ConditionalTooltipProps) => {\n  const { t } = useTranslation('apiKeysPage', { keyPrefix: 'createApiKey' });\n  return show ? (\n    <Tooltip\n      title={t('maxKeys', { maxApiKeys: MAX_SANDBOX_API_KEYS })}\n      placement=\"top-end\"\n    >\n      <Box>{children}</Box>\n    </Tooltip>\n  ) : (\n    <Box>{children}</Box>\n  );\n};\n\nexport const GenerateApiKeyButton = ({\n  apiTokens,\n  loading,\n  onClick,\n}: GenerateApiKeyButtonProps) => {\n  const { t } = useTranslation('apiKeysPage', { keyPrefix: 'createApiKey' });\n\n  const platformId = usePlatformId();\n  const activeApiKeys =\n    apiTokens?.filter((key) => key.status === 'ACTIVE') || [];\n\n  const limitIsReleased =\n    (ENVIRONMENT === 'staging' || ENVIRONMENT === 'localhost') &&\n    platformId != null &&\n    isFinmidTestDistributor(platformId);\n\n  const hasReachedMaxLimit = activeApiKeys.length >= MAX_SANDBOX_API_KEYS;\n\n  const disabled = loading || (hasReachedMaxLimit && !limitIsReleased);\n\n  return (\n    <ConditionalTooltip show={disabled}>\n      <Button\n        variant=\"invisible\"\n        disabled={disabled}\n        onClick={onClick}\n        testId=\"generateApiKeyButton\"\n        prefixIcon={<Icon icon={<AddRounded />} size=\"small\" />}\n      >\n        {t('btnLabel')}\n      </Button>\n    </ConditionalTooltip>\n  );\n};\n","import styled from '@emotion/styled';\nimport { EyeFillIcon } from '@finmid/ui/icons';\nimport { Box, Typography } from '@mui/material';\nimport { useState } from 'react';\n\nconst NakedButton = styled.button`\n  background: transparent;\n  border: 0;\n  cursor: pointer;\n  color: inherit;\n  display: inline-flex;\n  justify-content: center;\n  align-items: center;\n`;\n\ntype ReadOnlyProps = {\n  toggleVisible?: boolean;\n  value: string;\n};\n\nexport const ReadOnlyField = ({\n  toggleVisible,\n  value,\n  ...props\n}: ReadOnlyProps) => {\n  const [visible, setVisible] = useState(!toggleVisible);\n  const hiddenValue = '•••••••••••••••••••••••••••••••••••••••••';\n\n  return (\n    <Box\n      sx={{\n        bgcolor: 'gray.50',\n        borderRadius: '6px',\n        color: 'gray.600',\n        fontSize: '14px',\n        display: 'flex',\n        flexDirection: 'row',\n        alignItems: 'center',\n        justifyContent: 'space-between',\n        gap: '24px',\n        height: '32px',\n        minWidth: '416px',\n      }}\n      className=\"read-only-field\"\n    >\n      <Typography variant=\"monospace\" sx={{ p: 1 }} {...props}>\n        {toggleVisible && (visible ? value : hiddenValue)}\n        {!toggleVisible && value}\n      </Typography>\n      {toggleVisible && (\n        <NakedButton onClick={() => setVisible((v) => !v)}>\n          <EyeFillIcon sx={{ fontSize: '16px' }} />\n        </NakedButton>\n      )}\n    </Box>\n  );\n};\n","import { DangerZoneDialog } from '@finmid/tbl-webapps/components';\nimport { Dispatch, SetStateAction } from 'react';\nimport { useTranslation } from 'react-i18next';\n\ntype RevokeConfirmDialogProps = {\n  open: boolean;\n  onDelete: () => void;\n  setOpen: Dispatch<SetStateAction<boolean>>;\n};\nexport const RevokeConfirmDialog = ({\n  open,\n  onDelete,\n  setOpen,\n}: RevokeConfirmDialogProps) => {\n  const { t } = useTranslation('apiKeysPage', { keyPrefix: 'revokeDialog' });\n\n  return (\n    <DangerZoneDialog\n      title={t('title')}\n      message={t('alert')}\n      submitLabel={t('submit')}\n      open={open}\n      onSubmit={onDelete}\n      setOpen={setOpen}\n    />\n  );\n};\n","import { ApiKey } from '@finmid/distributor-types';\nimport { ENVIRONMENT } from '@finmid/environment';\nimport {\n  Button,\n  CopyButton,\n  ErrorBoundary,\n  LazyLoadFallback,\n  ZeroState,\n} from '@finmid/tbl-webapps/components';\nimport {\n  useDeleteApiTokenMutation,\n  useGetDistributorQuery,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { KeyIcon, MinusCircleFillIcon } from '@finmid/ui/icons';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { GridColDef } from '@mui/x-data-grid';\nimport posthog from 'posthog-js';\nimport { Suspense, lazy, useMemo, useState } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { GenerateApiKeyButton } from './GenerateApiKeyButton';\nimport { ReadOnlyField } from './ReadOnlyField';\nimport { RevokeConfirmDialog } from './RevokeConfirmDialog';\n\nconst DataGrid = lazy(() => import('@finmid/tbl-webapps/components/DataGrid'));\n\ntype ApiKeysListItemProps = {\n  apiToken: ApiKey;\n};\n\nconst Actions = ({ apiToken }: ApiKeysListItemProps) => {\n  const { t } = useTranslation('apiKeysPage', { keyPrefix: 'list' });\n\n  const { data: distributor } = useGetDistributorQuery();\n\n  // TODO: missing some access control here\n  const canRevoke = distributor != null && distributor.products.includes('TBL');\n\n  const [revokeApiToken, { isLoading }] = useDeleteApiTokenMutation();\n  const [revoked, setRevoked] = useState(false);\n  const [revokeDialogOpen, setRevokeDialogOpen] = useState(false);\n\n  const handleDelete = async () => {\n    posthog.capture('clicked_delete_apiKey_confirm');\n\n    try {\n      await revokeApiToken(apiToken.prefix).unwrap();\n      setRevoked(true);\n    } catch (e) {\n      // TODO: add sentry capture / notifications\n      console.log({ e });\n    }\n  };\n\n  const handleRevoke = () => {\n    setRevokeDialogOpen(true);\n  };\n  const readOnlyValue =\n    ENVIRONMENT === 'live'\n      ? `${apiToken.prefix}•••••••••••••••••••••••••••••••••`\n      : `${apiToken.prefix}.${apiToken.key}`;\n\n  return (\n    <Box\n      sx={{\n        display: 'flex',\n        justifyContent: 'flex-end',\n        gap: '16px',\n        width: '100%',\n      }}\n    >\n      {ENVIRONMENT !== 'live' && (\n        <CopyButton text={readOnlyValue} variant=\"invisible\" />\n      )}\n      {!revoked && (\n        <Button\n          disabled={isLoading || !canRevoke}\n          testId=\"revoke-button\"\n          onClick={handleRevoke}\n          variant=\"destructive\"\n        >\n          {t('btnRevokeLabel')}\n        </Button>\n      )}\n      <RevokeConfirmDialog\n        open={revokeDialogOpen}\n        onDelete={handleDelete}\n        setOpen={setRevokeDialogOpen}\n      />\n      {revoked && (\n        <Button\n          prefixIcon={<MinusCircleFillIcon />}\n          disabled\n          size=\"m\"\n          variant=\"destructive\"\n        >\n          {t('revokedStatus')}\n        </Button>\n      )}\n    </Box>\n  );\n};\n\nconst useColumns = () => {\n  const { t } = useTranslation('apiKeysPage', { keyPrefix: 'list' });\n\n  return useMemo(\n    () =>\n      [\n        {\n          field: 'name',\n          headerName: t('headerName'),\n          sortable: false,\n          flex: 1,\n          renderCell: ({ row: { name } }) => (\n            <div style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>\n              {name}\n            </div>\n          ),\n        },\n        {\n          field: 'key',\n          headerName: t('headerKey'),\n          flex: 1,\n          sortable: false,\n          renderCell: ({ row: { prefix, key } }) => {\n            const readOnlyValue =\n              ENVIRONMENT === 'live'\n                ? `${prefix}•••••••••••••••••••••••••••••••••`\n                : `${prefix}.${key}`;\n            return <ReadOnlyField value={readOnlyValue} />;\n          },\n        },\n        {\n          field: 'action',\n          headerName: '',\n          sortable: false,\n          display: 'flex',\n          minWidth: ENVIRONMENT === 'live' ? 140 : 200,\n          renderCell: ({ row }) => <Actions apiToken={row} />,\n        },\n      ] as GridColDef<ApiKey>[],\n    [t],\n  ) as GridColDef[];\n};\n\ntype ApiTokensListProps = {\n  apiTokens?: ApiKey[];\n  loading: boolean;\n};\n\nexport const ApiKeysTable = ({ apiTokens, loading }: ApiTokensListProps) => {\n  const { t } = useTranslation('apiKeysPage', { keyPrefix: 'list' });\n\n  const columns = useColumns();\n\n  const activeApiTokens = useMemo(\n    () => apiTokens?.filter((apiToken) => apiToken.status === 'ACTIVE') ?? [],\n    [apiTokens],\n  );\n\n  const navigate = useNavigate();\n\n  const onCreate = async () => {\n    navigate(sharedRoutes.createApiKeys);\n  };\n\n  return (\n    <ErrorBoundary fallback={<LazyLoadFallback />}>\n      <Suspense fallback={<Loader />}>\n        <DataGrid\n          data-test-id=\"api-tokens-table\"\n          rows={activeApiTokens}\n          getRowId={({ prefix, createdAt }) => `${prefix}-${createdAt}`}\n          columns={columns}\n          loading={loading}\n          disableColumnMenu\n          hideFooter\n          toolbar={{\n            actionsBar: (\n              <div css={{ width: '100%' }}>\n                <GenerateApiKeyButton\n                  loading={loading}\n                  apiTokens={apiTokens}\n                  onClick={onCreate}\n                />\n              </div>\n            ),\n          }}\n          slots={{\n            noRowsOverlay: () => (\n              <ZeroState\n                title={t('zeroStateTitle')}\n                description={t('zeroStateDescription')}\n                icon={<KeyIcon />}\n              >\n                <Button variant=\"primary\" onClick={onCreate} disabled={loading}>\n                  {t('createApiKey.btnLabel')}\n                </Button>\n              </ZeroState>\n            ),\n          }}\n          autoHeight\n          sx={{ '--DataGrid-overlayHeight': '400px' }}\n        />\n      </Suspense>\n    </ErrorBoundary>\n  );\n};\n","import { css } from '@emotion/react';\nimport styled from '@emotion/styled';\nimport { Box } from '@mui/material';\n\nexport const ApiKeyRow = styled(Box)`\n  ${({ theme }) => css`\n    padding: ${theme.spacing(3)} 0;\n    border-top: 1px solid ${theme.palette.gray[100]};\n    display: flex;\n    flex-direction: row;\n    align-items: center;\n    justify-content: space-between;\n\n    &:first-of-type {\n      border-top: none;\n      padding-top: 0;\n    }\n\n    &:last-of-type {\n      padding-bottom: 0;\n    }\n  `}\n`;\n","import { ENVIRONMENT } from '@finmid/environment';\nimport {\n  CopyButton,\n  Section,\n  SectionContent,\n  Typography,\n} from '@finmid/tbl-webapps/components';\nimport { TextInput } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useTranslation } from 'react-i18next';\n\nexport const BaseUrl = () => {\n  const { t } = useTranslation('apiKeysPage', { keyPrefix: 'baseUrl' });\n\n  const baseUrl =\n    ENVIRONMENT === 'live'\n      ? 'https://api.finmid.com/api/v2'\n      : 'https://sandbox.finmid.com/api/v2';\n\n  return (\n    <Section title={t('title')}>\n      <SectionContent>\n        <Typography>{t('subtitle')}</Typography>\n        <Box display=\"flex\" gap={1}>\n          <TextInput value={baseUrl} readOnly testId=\"baseUrlField\" />\n          <CopyButton text={baseUrl} />\n        </Box>\n      </SectionContent>\n    </Section>\n  );\n};\n","import {\n  Section,\n  SectionContent,\n  Typography,\n  formSectionMaxWidth,\n} from '@finmid/tbl-webapps/components';\nimport { CloseXIcon } from '@finmid/ui/icons';\nimport { Button } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\ntype Props = {\n  onAlertDismiss: () => void;\n};\n\nexport const KeysSafeBanner = ({ onAlertDismiss }: Props) => {\n  const { t } = useTranslation('apiKeysPage', { keyPrefix: 'keySafe' });\n\n  return (\n    <Section\n      title={t('title')}\n      actions={[\n        <Button\n          onClick={onAlertDismiss}\n          prefixIcon={<CloseXIcon sx={{ fontSize: '12px' }} />}\n          variant=\"invisible\"\n        />,\n      ]}\n      maxWidth={formSectionMaxWidth}\n    >\n      <SectionContent>\n        <Typography>{t('subtitle')}</Typography>\n      </SectionContent>\n    </Section>\n  );\n};\n","import { ENVIRONMENT } from '@finmid/environment';\nimport {\n  Button,\n  CopyButton,\n  Dialog,\n  Typography,\n} from '@finmid/tbl-webapps/components';\nimport { CreatedApiToken } from '@finmid/tbl-webapps/gateway-api';\nimport { Box } from '@mui/material';\nimport { useTranslation } from 'react-i18next';\n\nimport { ReadOnlyField } from './ReadOnlyField';\n\ntype KeysSafeDialogProps = {\n  open: boolean;\n  apiToken: CreatedApiToken;\n  onClose: () => void;\n};\n\nexport const KeysSafeDialog = (props: KeysSafeDialogProps) => {\n  const { open, onClose, apiToken } = props;\n  const { t } = useTranslation('apiKeysPage', { keyPrefix: 'keySafe' });\n\n  return (\n    <Dialog\n      onClose={onClose}\n      open={open}\n      title={t('title')}\n      actions={<Button onClick={onClose}>{t('done')}</Button>}\n      PaperProps={{ style: { maxWidth: '640px' } }}\n    >\n      <Typography\n        fontSize={15}\n        fontWeight={400}\n        lineHeight=\"20px\"\n        color=\"gray.500\"\n        mb={3}\n      >\n        {t('infos')}\n        {ENVIRONMENT === 'live' && ` ${t('hiddenLive')}`}\n        <br />\n        {/* TODO: add documentation on how to keep the api keys safe */}\n        {/* <ExternalLink>Learn more how to keep your keys safe.</ExternalLink> */}\n      </Typography>\n      <Box\n        sx={{\n          display: 'flex',\n          flexDirection: 'row',\n          gap: '16px',\n          alignItems: 'center',\n        }}\n      >\n        <ReadOnlyField\n          toggleVisible={ENVIRONMENT === 'live'}\n          value={apiToken.key as string}\n          data-test-id=\"created-api-key\"\n        />\n        <CopyButton text={apiToken.key as string} />\n      </Box>\n    </Dialog>\n  );\n};\n","import { fetchErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useGetApiTokensQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport { useEffect } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { ApiKeysTable, BaseUrl } from './components';\n\nexport const ApiKeysPage = () => {\n  const { ready } = useTranslation('apiKeysPage');\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const {\n    data: apiTokens,\n    isLoading: isLoadingApiTokens,\n    isFetching: isFetchingApiTokens,\n    isError,\n  } = useGetApiTokensQuery();\n\n  const loading = isLoadingApiTokens || isFetchingApiTokens;\n\n  useEffect(() => {\n    if (isError) {\n      displayErrorToast(fetchErrorProps);\n    }\n  }, [isError, displayErrorToast]);\n\n  if (!ready || loading) {\n    return <Loader />;\n  }\n\n  return (\n    <Box display=\"flex\" gap={2} flexDirection=\"column\">\n      <BaseUrl />\n\n      <Box data-test-id=\"api-keys-list\">\n        <ApiKeysTable apiTokens={apiTokens} loading={loading} />\n      </Box>\n    </Box>\n  );\n};\n","/* eslint-disable react/jsx-no-useless-fragment */\nimport { ENVIRONMENT } from '@finmid/environment';\nimport {\n  Button,\n  Page,\n  PageNavigation,\n  ScrollableFormSection,\n  SectionContent,\n  Typography,\n  withErrorProps,\n} from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport {\n  CreatedApiToken,\n  useCreateApiTokenMutation,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { useBreadcrumbs, useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport {\n  selectApiTokensPrefs,\n  setApiTokensPrefs,\n  useAppDispatch,\n  useAppSelect,\n} from '@finmid/tbl-webapps/store';\nimport { Loader, TextInput } from '@finmid/ui/ocarina';\nimport { Collapse } from '@mui/material';\nimport Link from '@mui/material/Link';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { KeysSafeBanner, KeysSafeDialog } from './components';\n\nconst MIN_API_KEY_NAME = 4;\n\nexport const CreateApiKeyPage = () => {\n  const [createdApiToken, setCreatedApiToken] =\n    useState<CreatedApiToken | null>(null);\n  const [createApiToken, { isLoading: createLoading }] =\n    useCreateApiTokenMutation();\n  const { safeKeysAlert } = useAppSelect(selectApiTokensPrefs);\n  const dispatch = useAppDispatch();\n  const { notifySuccess } = useNotifications();\n  const { t, ready } = useTranslation('apiKeysPage', {\n    keyPrefix: 'createApiKey',\n  });\n  const { displayErrorToast } = useDisplayErrorToast();\n  const breadcrumbs = useBreadcrumbs();\n\n  const [openKeySafeDialog, setOpenKeySafeDialog] = useState(false);\n  const [name, setName] = useState('');\n  const navigate = useNavigate();\n\n  const onCreate = async () => {\n    posthog.capture('clicked_create_apiKey_confirm');\n\n    try {\n      const data = await createApiToken(name).unwrap();\n      if (data) {\n        setCreatedApiToken(data);\n        setOpenKeySafeDialog(true);\n        setName('');\n        notifySuccess(t('success'));\n      }\n    } catch (err) {\n      displayErrorToast(withErrorProps(err as Error));\n    }\n  };\n\n  const onCancel = () => {\n    setOpenKeySafeDialog(false);\n    setCreatedApiToken(null);\n    navigate(sharedRoutes.developers);\n  };\n\n  const onAlertDismiss = () => {\n    dispatch(setApiTokensPrefs({ safeKeysAlert: false }));\n  };\n\n  const onDialogClose = () => {\n    setOpenKeySafeDialog(false);\n    setCreatedApiToken(null);\n    navigate(sharedRoutes.developers);\n  };\n\n  const isValid = name && name.length >= MIN_API_KEY_NAME;\n\n  return (\n    <>\n      <PageNavigation breadcrumbs={breadcrumbs.createApiKey} />\n      <Page>\n        {!ready && <Loader />}\n\n        {ready && (\n          <div\n            css={{\n              height: '100%',\n              display: 'flex',\n              flexDirection: 'column',\n              gap: 16,\n            }}\n          >\n            <Collapse\n              in={ENVIRONMENT === 'live' && safeKeysAlert}\n              unmountOnExit\n              css={{ flexShrink: 0 }}\n            >\n              <KeysSafeBanner onAlertDismiss={onAlertDismiss} />\n            </Collapse>\n\n            <ScrollableFormSection\n              sectionTitle={t('title')}\n              footerActions={[\n                <Button\n                  disabled={createLoading || !isValid}\n                  variant=\"primary\"\n                  onClick={onCreate}\n                >\n                  {t('save')}\n                </Button>,\n                <Button\n                  disabled={createLoading}\n                  onClick={onCancel}\n                  variant=\"invisible\"\n                >\n                  {t('cancel')}\n                </Button>,\n              ]}\n              sx={{ flex: 1 }}\n            >\n              <SectionContent>\n                <Typography>\n                  <Trans\n                    t={t}\n                    i18nKey=\"learnMore\"\n                    components={[\n                      <></>,\n                      <Link\n                        href=\"https://docs.finmid.com/reference/api-introduction\"\n                        sx={{ textDecoration: 'none' }}\n                      >\n                        read our guide!\n                      </Link>,\n                    ]}\n                  />\n                </Typography>\n                <TextInput\n                  value={name}\n                  label={t('fieldName')}\n                  onChange={(e) => setName(e.target.value)}\n                  data-test-id=\"api-key-name-field\"\n                />\n              </SectionContent>\n            </ScrollableFormSection>\n          </div>\n        )}\n\n        {createdApiToken && (\n          <KeysSafeDialog\n            apiToken={createdApiToken}\n            open={openKeySafeDialog}\n            onClose={onDialogClose}\n          />\n        )}\n      </Page>\n    </>\n  );\n};\n","import { useTranslation } from 'react-i18next';\nimport * as yup from 'yup';\n\nexport const useValidationSchema = () => {\n  const { t } = useTranslation('webhooksPage', { keyPrefix: 'validation' });\n\n  const form = {\n    authUsername: { required: t('authUsernameRequired') },\n    authPassword: { required: t('authPasswordRequired') },\n    url: {\n      url: t('urlValid'),\n      required: t('urlRequired'),\n    },\n    signatureSecret: { required: t('secretRequired') },\n  };\n\n  const validationSchema = yup.object().shape({\n    authUsername: yup.string().required(form.authUsername.required),\n    authPassword: yup.string().required(form.authPassword.required),\n    url: yup.string().url(form.url.url).required(form.url.required),\n    signatureSecret: yup.string().required(form.signatureSecret.required),\n  });\n\n  return {\n    validationSchema,\n  };\n};\n","import {\n  CreateWebhook,\n  useCreateWebhookMutation,\n} from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { yupResolver } from '@hookform/resolvers/yup';\nimport posthog from 'posthog-js';\nimport { useForm } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\nimport { useValidationSchema } from './CreateWebhook.schema';\n\nconst initialValues: CreateWebhook = {\n  url: '',\n  authUsername: '',\n  authPassword: '',\n  signatureSecret: '',\n};\n\nexport const useCreateWebhook = () => {\n  const navigate = useNavigate();\n  const [createWebhook, { isLoading }] = useCreateWebhookMutation();\n  const { notifyError } = useNotifications();\n  const { validationSchema } = useValidationSchema();\n  const { t, ready } = useTranslation('webhooksPage', {\n    keyPrefix: 'addWebhook',\n  });\n\n  const onCancel = () => {\n    navigate(sharedRoutes.developers);\n  };\n\n  const { control, formState, handleSubmit } = useForm<CreateWebhook>({\n    resolver: yupResolver(validationSchema),\n    defaultValues: initialValues,\n    mode: 'onBlur',\n  });\n\n  const handleSubmitForm = handleSubmit(async (values: CreateWebhook) => {\n    posthog.capture('clicked_create_webhook_confirm');\n\n    try {\n      await createWebhook(values).unwrap();\n      navigate(sharedRoutes.developers);\n    } catch {\n      notifyError();\n    }\n  });\n\n  return {\n    control,\n    isLoading,\n    isFormValid: formState.isValid,\n    ready,\n    handleSubmitForm,\n    onCancel,\n    t,\n  };\n};\n","/* eslint-disable react/jsx-no-useless-fragment */\nimport {\n  Button,\n  FormTextField,\n  Page,\n  PageNavigation,\n  ScrollableFormSection,\n  SectionContent,\n  Typography,\n} from '@finmid/tbl-webapps/components';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { Loader } from '@finmid/ui/ocarina';\nimport Link from '@mui/material/Link';\nimport { Trans } from 'react-i18next';\n\nimport { useCreateWebhook } from './CreateWebhook.hook';\n\nexport const CreateWebhookPage = () => {\n  const {\n    control,\n    isLoading,\n    isFormValid,\n    ready,\n    handleSubmitForm,\n    onCancel,\n    t,\n  } = useCreateWebhook();\n\n  const breadcrumbs = useBreadcrumbs();\n\n  return (\n    <>\n      <PageNavigation breadcrumbs={breadcrumbs.createWebhook} />\n      <Page>\n        {!ready && <Loader />}\n\n        {ready && (\n          <form onSubmit={handleSubmitForm} css={{ height: '100%' }}>\n            <ScrollableFormSection\n              sectionTitle={t('title')}\n              footerActions={[\n                <Button\n                  variant=\"primary\"\n                  loading={isLoading}\n                  disabled={isLoading || !isFormValid}\n                  type=\"submit\"\n                >\n                  {t('submit')}\n                </Button>,\n                <Button\n                  disabled={isLoading}\n                  onClick={onCancel}\n                  variant=\"invisible\"\n                >\n                  {t('btnCancelLabel')}\n                </Button>,\n              ]}\n            >\n              <SectionContent>\n                <Typography>\n                  <Trans\n                    t={t}\n                    i18nKey=\"learnMore\"\n                    components={[\n                      <></>,\n                      <Link\n                        href=\"https://docs.finmid.com/reference/webhooks\"\n                        sx={{ textDecoration: 'none' }}\n                      >\n                        read our guide\n                      </Link>,\n                    ]}\n                  />\n                </Typography>\n                <FormTextField\n                  control={control}\n                  name=\"url\"\n                  label={t('fieldUrl')}\n                  autoComplete=\"off\"\n                  disabled={isLoading}\n                />\n                <FormTextField\n                  control={control}\n                  name=\"authUsername\"\n                  label={t('fieldAuthUsername')}\n                  autoComplete=\"off\"\n                  disabled={isLoading}\n                />\n                <FormTextField\n                  control={control}\n                  name=\"authPassword\"\n                  label={t('fieldAuthPassword')}\n                  autoComplete=\"off\"\n                  type=\"password\"\n                  disabled={isLoading}\n                />\n                <FormTextField\n                  control={control}\n                  name=\"signatureSecret\"\n                  label={t('fieldSignatureSecret')}\n                  autoComplete=\"off\"\n                  type=\"password\"\n                  disabled={isLoading}\n                />\n              </SectionContent>\n            </ScrollableFormSection>\n          </form>\n        )}\n      </Page>\n    </>\n  );\n};\n","import { Webhook } from '@finmid/distributor-types';\nimport { Button } from '@finmid/tbl-webapps/components';\nimport {\n  useDeleteWebhookMutation,\n  useGetDistributorQuery,\n} from '@finmid/tbl-webapps/gateway-api';\nimport posthog from 'posthog-js';\nimport { useTranslation } from 'react-i18next';\n\ntype Props = {\n  webhook: Webhook;\n};\n\nexport const DeleteWebhookButton = ({ webhook }: Props) => {\n  const { t } = useTranslation('webhooksPage', { keyPrefix: 'table' });\n  const [deleteWebhook, { isLoading: isDeleting }] = useDeleteWebhookMutation();\n\n  const { data: distributor } = useGetDistributorQuery();\n\n  // TODO: missing some access control here\n  const canRemove = distributor != null && distributor.products.includes('TBL');\n\n  const onDelete = async () => {\n    posthog.capture('clicked_delete_webhook');\n\n    try {\n      await deleteWebhook(webhook.id).unwrap();\n    } catch {\n      // TODO: add notifications\n    }\n  };\n\n  return (\n    <Button\n      disabled={isDeleting || !canRemove}\n      onClick={onDelete}\n      data-test-id=\"delete-button\"\n      variant=\"destructive\"\n    >\n      {t('deleteBtnLabel')}\n    </Button>\n  );\n};\n","import { Webhook } from '@finmid/distributor-types';\nimport { Switch } from '@finmid/tbl-webapps/components';\nimport {\n  useGetDistributorQuery,\n  useUpdateWebhookMutation,\n} from '@finmid/tbl-webapps/gateway-api';\n\ntype Props = {\n  webhook: Webhook;\n};\n\nexport const WebhookStateSwitch = ({ webhook }: Props) => {\n  const [updateWebhook, { isLoading }] = useUpdateWebhookMutation();\n\n  const { data: distributor } = useGetDistributorQuery();\n\n  // TODO: missing some access control here\n  const canSwitch = distributor != null && distributor.products.includes('TBL');\n\n  const onChange = async (\n    _: React.ChangeEvent<HTMLInputElement>,\n    checked: boolean,\n  ) => {\n    if (isLoading) {\n      return;\n    }\n\n    try {\n      await updateWebhook({\n        id: webhook.id,\n        status: checked ? 'ACTIVE' : 'DISABLED',\n      }).unwrap();\n    } catch {\n      // TODO: add notifications\n    }\n  };\n\n  return (\n    <Switch\n      checked={webhook.status === 'ACTIVE'}\n      size=\"small\"\n      onChange={onChange}\n      disabled={!canSwitch}\n    />\n  );\n};\n","import { Webhook } from '@finmid/distributor-types';\nimport { TruncatedContent } from '@finmid/tbl-webapps/components';\nimport { GridColDef } from '@mui/x-data-grid';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { DeleteWebhookButton } from './DeleteWebhookButton';\nimport { WebhookStateSwitch } from './WebhookStateSwitch';\n\nexport const useColumns = (): GridColDef[] => {\n  const { t } = useTranslation('webhooksPage', { keyPrefix: 'table' });\n\n  return useMemo(\n    () =>\n      [\n        {\n          field: 'id',\n          headerName: t('headerEndpointId'),\n          sortable: false,\n          align: 'left',\n          minWidth: 220,\n          maxWidth: 240,\n          flex: 1,\n          renderCell: ({ row: { id } }) => (\n            <TruncatedContent content={id} testId={id} />\n          ),\n        },\n        {\n          field: 'url',\n          headerName: t('headerUrl'),\n          sortable: false,\n          minWidth: 120,\n          flex: 1,\n          renderCell: ({ row: { url } }) => (\n            <div style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>\n              {url}\n            </div>\n          ),\n        },\n        {\n          field: 'headerState',\n          headerName: t('headerState'),\n          sortable: false,\n          align: 'left',\n          width: 80,\n          renderCell: ({ row: webhook }) => (\n            <WebhookStateSwitch webhook={webhook} />\n          ),\n        },\n        {\n          field: 'actions',\n          renderHeader: () => null,\n          align: 'right',\n          minWidth: 140,\n          renderCell: ({ row: webhook }) => {\n            return <DeleteWebhookButton webhook={webhook} />;\n          },\n          sortable: false,\n        },\n      ] as GridColDef<Webhook>[],\n    [t],\n  ) as GridColDef[];\n};\n","import {\n  ErrorBoundary,\n  LazyLoadFallback,\n  ZeroState,\n} from '@finmid/tbl-webapps/components';\nimport { useGetWebhooksQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { Button, Icon, Loader } from '@finmid/ui/ocarina';\nimport { AddRounded } from '@mui/icons-material';\nimport { FunctionComponent, Suspense, lazy } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useColumns } from './useColumns';\n\nconst DataGrid = lazy(() => import('@finmid/tbl-webapps/components/DataGrid'));\n\ntype Props = {\n  onCreateWebhook: () => void;\n};\n\nexport const WebhooksTable: FunctionComponent<Props> = ({\n  onCreateWebhook,\n}) => {\n  const { t, ready } = useTranslation('webhooksPage');\n\n  const {\n    data: webhooks,\n    isLoading: isLoadingWebhooks,\n    isFetching: isFetchingWebhooks,\n  } = useGetWebhooksQuery();\n\n  const columns = useColumns();\n\n  return (\n    <ErrorBoundary fallback={<LazyLoadFallback />}>\n      <Suspense fallback={<Loader />}>\n        <DataGrid\n          data-test-id=\"webhooks-table\"\n          rows={webhooks ?? []}\n          columns={columns}\n          loading={!ready || isLoadingWebhooks || isFetchingWebhooks}\n          disableColumnMenu\n          hideFooter\n          toolbar={{\n            actionsBar: (\n              <div css={{ display: 'flex', width: '100%' }}>\n                <Button\n                  data-test-id=\"create-webhook-button\"\n                  onClick={onCreateWebhook}\n                  variant=\"invisible\"\n                  prefixIcon={<Icon size=\"small\" icon={<AddRounded />} />}\n                >\n                  {t('addWebhook.btnLabel')}\n                </Button>\n              </div>\n            ),\n          }}\n          slots={{\n            noRowsOverlay: () => (\n              <ZeroState\n                title={t('zeroState.title')}\n                description={t('zeroState.description')}\n              >\n                <Button\n                  data-test-id=\"create-webhook-button-zero-state\"\n                  variant=\"primary\"\n                  onClick={onCreateWebhook}\n                >\n                  {t('addWebhook.btnLabel')}\n                </Button>\n              </ZeroState>\n            ),\n          }}\n          autoHeight\n          sx={{ '--DataGrid-overlayHeight': '400px' }}\n        />\n      </Suspense>\n    </ErrorBoundary>\n  );\n};\n","import { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { useNavigate } from 'react-router-dom';\n\nimport { WebhooksTable } from './components';\n\nexport const WebhooksPage = () => {\n  const navigate = useNavigate();\n\n  const onCreateWebhook = () => navigate(sharedRoutes.createWebhooks);\n\n  return <WebhooksTable onCreateWebhook={onCreateWebhook} />;\n};\n","import {\n  ButtonGroup,\n  Page,\n  PageNavigation,\n} from '@finmid/tbl-webapps/components';\nimport { useBreadcrumbs } from '@finmid/tbl-webapps/hooks';\nimport { Loader } from '@finmid/ui/ocarina';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { ApiKeysPage } from './ApiKeys';\nimport { WebhooksPage } from './Webhooks';\n\nexport const DevelopersPage = () => {\n  const breadcrumbs = useBreadcrumbs();\n  const { t, ready } = useTranslation('developersPage');\n  const [tab, setTab] = useState<'api-keys' | 'webhooks'>('webhooks');\n\n  return (\n    <>\n      <PageNavigation breadcrumbs={breadcrumbs.developers}>\n        <ButtonGroup\n          buttons={[\n            {\n              label: t('webhooksTabButtonLabel'),\n              onClick: () => {\n                setTab('webhooks');\n                posthog.capture('clicked_tab_developers_webhooks');\n              },\n              testId: 'tab-webhooks',\n            },\n            {\n              label: t('apiKeysTabButtonLabel'),\n              onClick: () => {\n                setTab('api-keys');\n                posthog.capture('clicked_tab_developers_apiKeys');\n              },\n              testId: 'tab-api-keys',\n            },\n          ]}\n        />\n      </PageNavigation>\n      <Page>\n        {!ready && <Loader />}\n\n        {ready && tab === 'api-keys' ? <ApiKeysPage /> : <WebhooksPage />}\n      </Page>\n    </>\n  );\n};\n","import { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nexport const useInviteMemberFormLabels = () => {\n  const { t } = useTranslation('platformPage', {\n    keyPrefix: 'inviteDialog',\n  });\n\n  const labels = useMemo(\n    () => ({\n      email: t('field.email'),\n      firstName: t('field.firstName'),\n      lastName: t('field.lastName'),\n    }),\n    [t],\n  );\n\n  return {\n    labels,\n  };\n};\n","import { BE_Error, disposableEmailErrorCode } from '@finmid/distributor-types';\nimport {\n  GetCustomDomainErrors,\n  useHandleFormError,\n} from '@finmid/tbl-webapps/errors-handling';\nimport { useCallback } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useInviteMemberFormLabels } from './useInviteMemberFormLabels';\n\nconst ServerToClientFields = {\n  email: 'email',\n  firstName: 'firstName',\n  lastName: 'lastName',\n};\n\nconst useGetInviteMemberCustomErrors = () => {\n  const { t } = useTranslation('notifications');\n\n  const getCustomDomainErrors: GetCustomDomainErrors = useCallback(\n    (error: BE_Error) => {\n      let message: string | undefined;\n      const { code: errorCode, description: errorDescription } =\n        error.data.errorData.data;\n      switch (errorCode) {\n        case disposableEmailErrorCode:\n          message = t('clientError', {\n            context: errorCode,\n            // The gateway sends the user-facing description; it stands in\n            // for codes that have no translation of their own.\n            defaultValue: errorDescription,\n          });\n          break;\n        default:\n          break;\n      }\n\n      return { error, message };\n    },\n    [t],\n  );\n\n  return { getCustomDomainErrors };\n};\n\nexport const useHandleInviteMemberErrors = () => {\n  const { labels } = useInviteMemberFormLabels();\n  const { getCustomDomainErrors } = useGetInviteMemberCustomErrors();\n  return useHandleFormError({\n    labels,\n    fieldsMap: ServerToClientFields,\n    getCustomDomainErrors,\n  });\n};\n","import { yupResolver } from '@hookform/resolvers/yup';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport * as yup from 'yup';\n\nexport const useValidationSchema = () => {\n  const { t, ready, i18n } = useTranslation('platformPage', {\n    keyPrefix: 'memberValidation',\n  });\n\n  const form = {\n    email: {\n      required: t('emailRequired'),\n      valid: t('emailValid'),\n    },\n    firstName: {\n      required: t('firstnameRequired'),\n    },\n    lastName: {\n      required: t('lastnameRequired'),\n    },\n  };\n\n  const schema = useMemo(\n    () =>\n      yup.object().shape({\n        email: yup.string().email(form.email.valid).required(),\n        firstName: yup.string().required(form.firstName.required),\n        lastName: yup.string().required(form.lastName.required),\n      }),\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [ready, i18n.language],\n  );\n\n  return {\n    validationSchema: yupResolver(schema),\n  };\n};\n","import { Member } from '@finmid/distributor-types';\nimport { withErrorProps } from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useInviteMemberMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications, useTokenParsed } from '@finmid/tbl-webapps/hooks';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { useForm } from 'react-hook-form';\nimport { useTranslation } from 'react-i18next';\n\nimport { useHandleInviteMemberErrors } from './InviteMember.errors';\nimport { useValidationSchema } from './InviteMember.schema';\nimport { useInviteMemberFormLabels } from './useInviteMemberFormLabels';\n\ntype InviteMemberFormValues = {\n  email: string;\n  firstName: string;\n  lastName: string;\n};\n\nconst initialValues: InviteMemberFormValues = {\n  email: '',\n  firstName: '',\n  lastName: '',\n};\n\ntype UseInviteMemberProps = {\n  members?: Member[] | null;\n};\n\nexport const useInviteMember = ({ members }: UseInviteMemberProps) => {\n  const [open, setOpen] = useState(false);\n  const [validationErrors, setValidationErrors] = useState<string[] | null>(\n    null,\n  );\n  const { validationSchema } = useValidationSchema();\n  const { t, ready } = useTranslation('platformPage', {\n    keyPrefix: 'inviteDialog',\n  });\n  const [sendInvite, { isLoading }] = useInviteMemberMutation();\n  const tokenParsed = useTokenParsed();\n\n  const { notifySuccess } = useNotifications();\n\n  const { labels } = useInviteMemberFormLabels();\n\n  const { handleFormError } = useHandleInviteMemberErrors();\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const { control, formState, handleSubmit, reset } =\n    useForm<InviteMemberFormValues>({\n      resolver: validationSchema,\n      defaultValues: initialValues,\n      mode: 'onBlur',\n    });\n\n  const handleSubmitForm = handleSubmit(\n    async (values: InviteMemberFormValues) => {\n      posthog.capture('clicked_invite_member_confirm');\n\n      const { firstName, lastName, email } = values;\n\n      try {\n        const activeUser = members?.find(\n          (member) => member.email === email && member.status === 'ACTIVE',\n        );\n        if (activeUser != null) {\n          displayErrorToast(\n            withErrorProps({\n              message: t('userAlreadyExistsError', { email: activeUser.email }),\n            }),\n          );\n          return;\n        }\n\n        await sendInvite({\n          firstName,\n          lastName,\n          email,\n          inviterUserId: tokenParsed?.preferred_username || '',\n        }).unwrap();\n        reset();\n        setOpen(false);\n        notifySuccess(\n          t('success', { firstname: firstName, lastname: lastName }),\n        );\n      } catch (err) {\n        const { customError, validationErrors } = handleFormError(err);\n        if (validationErrors) {\n          setValidationErrors(validationErrors);\n        } else {\n          displayErrorToast(\n            withErrorProps({ ...(err as Error), message: customError }),\n          );\n        }\n      }\n    },\n  );\n\n  const closeDialog = () => {\n    reset();\n    setValidationErrors(null);\n    setOpen(false);\n  };\n\n  return {\n    control,\n    isFormValid: formState.isValid,\n    isLoading: isLoading || members == null,\n    labels,\n    open,\n    ready,\n    validationErrors,\n    closeDialog,\n    handleSubmitForm,\n    setOpen,\n    t,\n  };\n};\n","import { Member } from '@finmid/distributor-types';\nimport {\n  Button,\n  DialogActions,\n  DialogContent,\n  DialogTitle,\n  ErrorInfo,\n  FormTextField,\n  NoFormAutofill,\n  Typography,\n} from '@finmid/tbl-webapps/components';\nimport { ElevatedPaper } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport Dialog from '@mui/material/Dialog';\n\nimport { useInviteMember } from './InviteMember.hook';\n\ntype InviteMemberButtonProps = {\n  members: Member[] | null;\n};\n\nexport const InviteMemberButton = ({ members }: InviteMemberButtonProps) => {\n  const {\n    control,\n    isFormValid,\n    isLoading,\n    labels,\n    open,\n    ready,\n    validationErrors,\n    closeDialog,\n    handleSubmitForm,\n    setOpen,\n    t,\n  } = useInviteMember({ members });\n\n  if (!ready) {\n    return null;\n  }\n\n  return (\n    <>\n      <Button\n        onClick={() => setOpen(true)}\n        disabled={isLoading}\n        testId=\"invite-member-button\"\n        variant=\"primary\"\n      >\n        {t('inviteMemberBtnLabel')}\n      </Button>\n      <Dialog\n        open={open}\n        onClose={closeDialog}\n        fullWidth\n        PaperProps={{\n          style: { maxWidth: '480px' },\n          elevation: 2,\n        }}\n        PaperComponent={ElevatedPaper}\n      >\n        <DialogTitle>{t('title')}</DialogTitle>\n\n        <form\n          onSubmit={handleSubmitForm}\n          autoComplete=\"off\"\n          css={{ marginTop: -20 }}\n        >\n          <NoFormAutofill />\n          <DialogContent>\n            <Box data-test-id=\"invite-member-form\">\n              <Typography\n                fontSize={15}\n                fontWeight={400}\n                lineHeight=\"20px\"\n                color=\"gray.500\"\n              >\n                {t('subtitle')}\n              </Typography>\n\n              <Box mt={4} display=\"flex\" flexDirection=\"column\" gap={2}>\n                <FormTextField\n                  control={control}\n                  name=\"email\"\n                  label={labels.email}\n                />\n                <FormTextField\n                  control={control}\n                  name=\"firstName\"\n                  label={labels.firstName}\n                />\n                <FormTextField\n                  control={control}\n                  name=\"lastName\"\n                  label={labels.lastName}\n                />\n                {validationErrors?.length ? (\n                  <Box mt={2}>\n                    <ErrorInfo invalidFields={validationErrors} />\n                  </Box>\n                ) : null}\n              </Box>\n            </Box>\n          </DialogContent>\n          <DialogActions>\n            <Button\n              variant=\"primary\"\n              type=\"submit\"\n              disabled={isLoading || !isFormValid}\n              testId=\"submit-button\"\n            >\n              {t('submitBtnLabel')}\n            </Button>\n            <Button\n              onClick={closeDialog}\n              disabled={isLoading}\n              variant=\"invisible\"\n            >\n              {t('cancelBtnLabel')}\n            </Button>\n          </DialogActions>\n        </form>\n      </Dialog>\n    </>\n  );\n};\n","import { MemberStatus } from '@finmid/distributor-types';\nimport { Badge, BadgeProps } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nconst memberStatusMap = {\n  ACTIVE: { label: 'active', variant: 'success' },\n  INVITED: { label: 'pending', variant: 'alert' },\n} as const satisfies Record<MemberStatus, BadgeProps>;\n\ntype MemberStatusTagProps = {\n  status: MemberStatus;\n};\n\nexport const MemberStatusTag = ({ status }: MemberStatusTagProps) => {\n  const { t, ready } = useTranslation('components', {\n    keyPrefix: 'memberStatus',\n  });\n  const { label, variant } = memberStatusMap[status];\n\n  if (ready) {\n    return <Badge label={t(label)} variant={variant} />;\n  }\n\n  return null;\n};\n","import { Member } from '@finmid/distributor-types';\nimport {\n  Button,\n  Dialog,\n  Tooltip,\n  Typography,\n} from '@finmid/tbl-webapps/components';\nimport { useRemoveMemberMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications, useTokenParsed } from '@finmid/tbl-webapps/hooks';\nimport { Icon, IconButton, TrashIcon } from '@finmid/ui/ocarina';\nimport { Box } from '@mui/material';\nimport posthog from 'posthog-js';\nimport { useState } from 'react';\nimport { useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\ntype RemoveMemberButtonProps = {\n  member: Member;\n  isOnlyMember: boolean;\n};\n\nexport const RemoveMemberButton = ({\n  member,\n  isOnlyMember,\n}: RemoveMemberButtonProps) => {\n  const [open, setOpen] = useState(false);\n  const { t, ready } = useTranslation('platformPage', {\n    keyPrefix: 'removeDialog',\n  });\n  const { t: tNotifications } = useTranslation('notifications');\n  const [removeMember, { isLoading }] = useRemoveMemberMutation();\n  const { notifySuccess, notifyError } = useNotifications();\n  const navigate = useNavigate();\n  const tokenParsed = useTokenParsed();\n\n  const { firstName, lastName, email } = member;\n\n  const userRemoveSelf = member.id === tokenParsed?.preferred_username;\n  const canRemoveMember = !isLoading && !isOnlyMember;\n  const tooltipTitle = canRemoveMember ? '' : t('canNotRemoveLastMember');\n\n  const logout = () => navigate('/logout');\n  const closeDialog = () => setOpen(false);\n  const openDialog = () => setOpen(true);\n\n  const handleRemoveMember = async () => {\n    posthog.capture('clicked_remove_member_confirm');\n\n    try {\n      await removeMember(member.id).unwrap();\n      if (userRemoveSelf) {\n        logout();\n      } else {\n        closeDialog();\n        notifySuccess(t('success', { email }));\n      }\n    } catch {\n      notifyError(tNotifications('default.serverError'));\n    }\n  };\n\n  if (!ready) {\n    return null;\n  }\n\n  return (\n    <Box display=\"flex\">\n      <Tooltip title={tooltipTitle} placement=\"left-end\">\n        <div>\n          <IconButton\n            variant=\"invisible\"\n            icon={<Icon icon={<TrashIcon />} />}\n            disabled={!canRemoveMember}\n            onClick={canRemoveMember ? openDialog : undefined}\n            data-test-id=\"trash-icon\"\n          />\n        </div>\n      </Tooltip>\n      <Dialog\n        open={open}\n        onClose={closeDialog}\n        fullWidth\n        title={\n          userRemoveSelf ? t('self.title') : t('title', { firstName, lastName })\n        }\n        actions={[\n          <Button variant=\"primary\" onClick={closeDialog}>\n            {t('backBtnLabel')}\n          </Button>,\n          <Button\n            onClick={handleRemoveMember}\n            loading={isLoading}\n            testId=\"confirm-delete-button\"\n          >\n            {t('submitBtnLabel')}\n          </Button>,\n        ]}\n      >\n        <Typography\n          fontSize={15}\n          fontWeight={400}\n          lineHeight=\"20px\"\n          color=\"gray.500\"\n        >\n          {userRemoveSelf\n            ? t('self.subtitle')\n            : t('subtitle', { firstName, lastName })}\n        </Typography>\n      </Dialog>\n    </Box>\n  );\n};\n","import { Member } from '@finmid/distributor-types';\nimport { TruncatedContent } from '@finmid/tbl-webapps/components';\nimport { GridColDef } from '@mui/x-data-grid';\nimport { useMemo } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { MemberStatusTag } from './components/MemberStatusTag';\nimport { RemoveMemberButton } from './components/RemoveMemberButton';\n\nexport const useColumns = (): GridColDef[] => {\n  const { t } = useTranslation('platformPage', { keyPrefix: 'members.table' });\n\n  return useMemo(\n    () =>\n      [\n        {\n          field: 'name',\n          headerName: t('headerName'),\n          sortable: false,\n          align: 'left',\n          minWidth: 200,\n          flex: 1,\n          renderCell: ({ row: { firstName, lastName } }) => (\n            <div style={{ overflow: 'hidden', textOverflow: 'ellipsis' }}>\n              {`${firstName} ${lastName}`}\n            </div>\n          ),\n        },\n        {\n          field: 'email',\n          headerName: t('headerEmail'),\n          sortable: false,\n          minWidth: 220,\n          flex: 1,\n          renderCell: ({ row: { email } }) => (\n            <TruncatedContent content={email} testId={email} maxWidth={300} />\n          ),\n        },\n        {\n          field: 'status',\n          headerName: t('headerStatus'),\n          sortable: false,\n          minWidth: 220,\n          renderCell: ({ row: { status } }) => (\n            <MemberStatusTag status={status} />\n          ),\n        },\n        {\n          field: 'actions',\n          headerName: '',\n          sortable: false,\n          minWidth: 120,\n          renderCell: ({ row: member, api: { getRowsCount } }) => (\n            <RemoveMemberButton\n              member={member}\n              isOnlyMember={getRowsCount() === 1}\n            />\n          ),\n        },\n      ] as GridColDef<Member>[],\n    [t],\n  ) as GridColDef[];\n};\n","import { Member } from '@finmid/distributor-types';\nimport {\n  ErrorBoundary,\n  LazyLoadFallback,\n  ZeroState,\n} from '@finmid/tbl-webapps/components';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { Suspense, lazy } from 'react';\nimport { useTranslation } from 'react-i18next';\n\nimport { useColumns } from './useColumns';\n\nconst DataGrid = lazy(() => import('@finmid/tbl-webapps/components/DataGrid'));\n\ntype MembersTableProps = {\n  members: Member[] | null;\n};\n\nexport const MembersTable = ({ members }: MembersTableProps) => {\n  const columns = useColumns();\n  const { t } = useTranslation('platformPage', { keyPrefix: 'members' });\n\n  return (\n    <ErrorBoundary fallback={<LazyLoadFallback />}>\n      <Suspense fallback={<Loader />}>\n        <DataGrid\n          rows={members ?? []}\n          loading={members == null}\n          columns={columns}\n          disableColumnMenu\n          slots={{\n            noResultsOverlay: () => (\n              <ZeroState\n                title={t('table.zeroStateTitle')}\n                description={t('table.zeroStateDescription')}\n              />\n            ),\n            noRowsOverlay: () => (\n              <ZeroState\n                title={t('table.zeroStateTitle')}\n                description={t('table.zeroStateDescription')}\n              />\n            ),\n          }}\n          autoHeight\n          sx={{ '--DataGrid-overlayHeight': '200px' }}\n          hideFooter={members != null && members.length === 0}\n        />\n      </Suspense>\n    </ErrorBoundary>\n  );\n};\n","import {\n  Page,\n  PageNavigation,\n  ZeroState,\n} from '@finmid/tbl-webapps/components';\nimport { useGetMembersQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useBreadcrumbs, useLiveDistributor } from '@finmid/tbl-webapps/hooks';\nimport { Loader } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport { InviteMemberButton } from './InviteMember';\nimport { MembersTable } from './Members';\n\nexport const PlatformPage = () => {\n  const {\n    data: distributor,\n    isLoading: isLoadingDistributor,\n    error: distributorError,\n  } = useLiveDistributor();\n  const { data: members, error: getMembersError } = useGetMembersQuery();\n  const { t, ready } = useTranslation('platformPage');\n  const breadcrumbs = useBreadcrumbs(distributor?.fullName);\n\n  const isLoading = isLoadingDistributor;\n  const error = distributorError || getMembersError;\n\n  const loading = !ready || isLoading;\n  const hasError = !loading && error;\n  const isSuccess = !loading && !error && distributor;\n\n  return (\n    <>\n      <PageNavigation breadcrumbs={breadcrumbs.platform}>\n        <InviteMemberButton members={members ?? []} />\n      </PageNavigation>\n      <Page data-test-id=\"platform-page\">\n        {loading && <Loader />}\n\n        {hasError && (\n          <ZeroState\n            title={t('error.title')}\n            description={t('error.description')}\n          />\n        )}\n\n        {isSuccess && <MembersTable members={members ?? []} />}\n      </Page>\n    </>\n  );\n};\n","import {\n  Button,\n  Section,\n  SectionContent,\n  Typography,\n} from '@finmid/tbl-webapps/components';\nimport { useNotifications } from '@finmid/tbl-webapps/hooks';\nimport { ConsentState, useConsentContext } from '@finmid/tbl-webapps/posthog';\nimport { InfoIcon, RadioGroup, Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useEffect, useState } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\n\nexport const CookieSettings = () => {\n  const { t } = useTranslation('settingsPage', { keyPrefix: 'privacy' });\n  const { notifySuccess } = useNotifications();\n  const { consentState = 'MISSING', changeConsent } = useConsentContext();\n  const [selectedConsent, setSelectedConsent] =\n    useState<ConsentState>(consentState);\n\n  useEffect(() => {\n    setSelectedConsent(consentState);\n  }, [consentState]);\n\n  return (\n    <Section title={t('sectionTitle')} maxWidth={656} testId=\"privacy-section\">\n      <SectionContent>\n        <Box display=\"flex\" flexDirection=\"column\" alignItems=\"flex-start\">\n          <Typography fontSize={15} lineHeight=\"20px\">\n            <Trans\n              t={t}\n              i18nKey=\"cookies.info\"\n              components={{\n                pdfLink: (\n                  // eslint-disable-next-line jsx-a11y/anchor-has-content\n                  <a\n                    href=\"/Cookie Policy.pdf\"\n                    target=\"_blank\"\n                    rel=\"noreferrer\"\n                    style={{ color: 'black' }}\n                  />\n                ),\n              }}\n            />\n          </Typography>\n          <Spacer height={3} />\n\n          {consentState === 'MISSING' ? (\n            <Box display=\"flex\" gap={1} color=\"gray.500\">\n              <Box mt=\"2px\">\n                <InfoIcon width={16} height={16} color=\"inherit\" />\n              </Box>\n              <Typography color=\"inherit\">{t('cookies.missing')}</Typography>\n            </Box>\n          ) : (\n            <>\n              <RadioGroup\n                name=\"privacy\"\n                options={[\n                  {\n                    label: t('cookies.action.accept'),\n                    value: 'ACTIVE',\n                    testId: 'accept-cookies',\n                  },\n                  {\n                    label: t('cookies.action.decline'),\n                    value: 'REJECTED',\n                    testId: 'decline-cookies',\n                  },\n                ]}\n                defaultValue={selectedConsent}\n                onChange={(choice) => setSelectedConsent(choice)}\n                row\n              />\n              <Spacer height={3} />\n              <Button\n                testId=\"privacy-save\"\n                variant=\"primary\"\n                disabled={\n                  selectedConsent === 'MISSING' ||\n                  consentState === selectedConsent\n                }\n                onClick={() => {\n                  changeConsent(selectedConsent);\n                  notifySuccess(t('notifications.changeConsent.success'));\n                }}\n              >\n                {t('actions.saveChanges')}\n              </Button>\n            </>\n          )}\n        </Box>\n      </SectionContent>\n    </Section>\n  );\n};\n","import { GetMember, MfaMethod } from '@finmid/distributor-types';\nimport {\n  Button,\n  Section,\n  SectionContent,\n  Typography,\n  withErrorProps,\n} from '@finmid/tbl-webapps/components';\nimport { useDisplayErrorToast } from '@finmid/tbl-webapps/errors-handling';\nimport { useChangeMfaMethodMutation } from '@finmid/tbl-webapps/gateway-api';\nimport { useNotifications, useTokenParsed } from '@finmid/tbl-webapps/hooks';\nimport { Banner, RadioGroup, Spacer } from '@finmid/ui/ocarina';\nimport Box from '@mui/material/Box';\nimport { useState } from 'react';\nimport { Trans, useTranslation } from 'react-i18next';\nimport { useNavigate } from 'react-router-dom';\n\ntype MfaSettingsProps = {\n  user: GetMember.GatewayResponse;\n};\n\nexport const MfaSettings = ({ user }: MfaSettingsProps) => {\n  const { t } = useTranslation('settingsPage', { keyPrefix: 'mfa' });\n  const { notifySuccess } = useNotifications();\n  const { displayErrorToast } = useDisplayErrorToast();\n\n  const { f4d } = useTokenParsed();\n  const [mfaMethod, setMfaMethod] = useState<MfaMethod>(\n    f4d['2fa_method'] ?? 'sms',\n  );\n  const [selectedMfaMethod, setSelectedMfaMethod] =\n    useState<MfaMethod>(mfaMethod);\n\n  const navigate = useNavigate();\n  const logout = () => navigate('/logout');\n\n  const [changeMfaMethod, { isLoading }] = useChangeMfaMethodMutation();\n  const handleChangeMfaMethod = async () => {\n    try {\n      await changeMfaMethod({\n        userId: user.id,\n        method: selectedMfaMethod,\n      }).unwrap();\n      setMfaMethod(selectedMfaMethod);\n      notifySuccess(t('notifications.changeMfa.success'));\n      logout();\n    } catch (error) {\n      displayErrorToast(\n        withErrorProps({\n          ...(error as Error),\n          message: t('notifications.changeMfa.error'),\n        }),\n      );\n    }\n  };\n\n  const canSelectSmsMfaMethod = user.smsSupport === true;\n\n  return (\n    <Section title={t('sectionTitle')} maxWidth={656} testId=\"mfa-section\">\n      <SectionContent>\n        <Box display=\"flex\" alignItems=\"flex-start\" flexDirection=\"column\">\n          <Typography fontSize={15} lineHeight=\"20px\">\n            {t('description')}\n          </Typography>\n          <Spacer height={3} />\n          <RadioGroup\n            name=\"method\"\n            defaultValue={mfaMethod}\n            onChange={(method) => setSelectedMfaMethod(method)}\n            options={[\n              {\n                label: t('options.sms.label'),\n                caption: (\n                  <Trans\n                    t={t}\n                    i18nKey=\"options.sms.caption\"\n                    values={{ number: user.phoneNumber }}\n                    components={{\n                      a: (\n                        <a\n                          href=\"mailto:support@finmid.com\"\n                          style={{\n                            color: 'inherit',\n                          }}\n                        >\n                          support@finmid.com\n                        </a>\n                      ),\n                    }}\n                  />\n                ),\n                value: 'sms',\n                disabled: !canSelectSmsMfaMethod,\n                tooltip: !canSelectSmsMfaMethod\n                  ? t('options.sms.tooltip')\n                  : undefined,\n                testId: 'mfa-sms',\n              },\n              {\n                label: t('options.totp.label'),\n                caption: t('options.totp.caption'),\n                value: 'totp',\n                testId: 'mfa-totp',\n              },\n            ]}\n          />\n          <Spacer height={3} />\n          {mfaMethod !== selectedMfaMethod && (\n            <>\n              <Banner\n                variant=\"info\"\n                size=\"large\"\n                data-test-id=\"automatic-logout-hint\"\n              >\n                <Trans\n                  t={t}\n                  i18nKey=\"automaticLogoutHint\"\n                  components={{\n                    strong: <strong />,\n                  }}\n                />\n              </Banner>\n              <Spacer height={2} />\n            </>\n          )}\n          <Button\n            variant=\"primary\"\n            disabled={mfaMethod === selectedMfaMethod}\n            onClick={handleChangeMfaMethod}\n            loading={isLoading}\n            testId=\"mfa-save\"\n          >\n            {t('actions.saveChanges')}\n          </Button>\n        </Box>\n      </SectionContent>\n    </Section>\n  );\n};\n","import {\n  Section,\n  SectionContent,\n  Switch,\n  Typography,\n} from '@finmid/tbl-webapps/components';\nimport { useCapitalDashboardV2 } from '@finmid/tbl-webapps/hooks';\nimport Box from '@mui/material/Box';\nimport posthog from 'posthog-js';\nimport { useTranslation } from 'react-i18next';\n\n/**\n * Switches a feature that not every platform has yet on or off for this\n * browser. Flags are read once per page load, so a change reloads the page.\n */\nexport const PreviewFeatureSettings = () => {\n  const { t } = useTranslation('settingsPage', {\n    keyPrefix: 'previewFeatures',\n  });\n  const dashboardV2 = useCapitalDashboardV2();\n\n  if (!dashboardV2.canToggle) return null;\n\n  const toggle = (enabled: boolean) => {\n    posthog.capture('capital_dashboard_v2_toggled', { enabled });\n    dashboardV2.setEnabled(enabled);\n    window.location.reload();\n  };\n\n  return (\n    <Section\n      title={t('sectionTitle')}\n      maxWidth={656}\n      testId=\"preview-features-section\"\n    >\n      <SectionContent>\n        <Typography fontSize={15} lineHeight=\"20px\">\n          {t('description')}\n        </Typography>\n        <Box\n          display=\"flex\"\n          alignItems=\"flex-start\"\n          justifyContent=\"space-between\"\n          gap={2}\n          mt={3}\n        >\n          <Box>\n            <Typography fontSize={15} fontWeight={500}>\n              {t('features.capitalDashboardV2.label')}\n            </Typography>\n            <Typography fontSize={13} color=\"gray.500\">\n              {t('features.capitalDashboardV2.caption')}\n            </Typography>\n          </Box>\n          <Switch\n            size=\"small\"\n            checked={dashboardV2.enabled}\n            onChange={(_, checked) => toggle(checked)}\n            inputProps={{\n              'aria-label': t('features.capitalDashboardV2.label'),\n            }}\n            data-test-id=\"preview-feature-capitalDashboardV2\"\n          />\n        </Box>\n      </SectionContent>\n    </Section>\n  );\n};\n","import { Page, PageNavigation } from '@finmid/tbl-webapps/components';\nimport { useGetMemberQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { useBreadcrumbs, useTokenParsed } from '@finmid/tbl-webapps/hooks';\nimport { Loader, Spacer } from '@finmid/ui/ocarina';\nimport { useTranslation } from 'react-i18next';\n\nimport {\n  CookieSettings,\n  MfaSettings,\n  PreviewFeatureSettings,\n} from './components';\n\nexport const SettingsPage = () => {\n  const breadcrumbs = useBreadcrumbs();\n  const { ready } = useTranslation('settingsPage');\n\n  const { preferred_username } = useTokenParsed();\n  const { data: user, isLoading } = useGetMemberQuery(preferred_username);\n\n  return (\n    <>\n      <PageNavigation breadcrumbs={breadcrumbs.settings} />\n      <Page data-test-id=\"settings-page\">\n        {ready && !isLoading && user != null ? (\n          <>\n            <MfaSettings user={user} />\n            <Spacer height={2} />\n            <CookieSettings />\n            <Spacer height={2} />\n            <PreviewFeatureSettings />\n          </>\n        ) : (\n          <Loader />\n        )}\n      </Page>\n    </>\n  );\n};\n","import { useGetDistributorQuery } from '@finmid/tbl-webapps/gateway-api';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { Navigate, Outlet } from 'react-router-dom';\n\nexport const CapitalDistributorGuard = () => {\n  const { data: distributor, isLoading } = useGetDistributorQuery();\n\n  if (isLoading) {\n    console.log('isLoading');\n    return null; // Or a loading spinner\n  }\n\n  const isCapitalDistributor = distributor?.products?.includes('PAYABLES');\n\n  // Redirect to dashboard if Capital distributor tries to access developers\n  if (isCapitalDistributor) {\n    return <Navigate to={sharedRoutes.root} replace />;\n  }\n\n  return <Outlet />;\n};\n","import { ProductSentryTag } from '@finmid/tbl-webapps/components';\nimport {\n  CreateApiKeyPage,\n  CreateWebhookPage,\n  DevelopersPage,\n} from '@finmid/tbl-webapps/developers';\nimport { PlatformPage } from '@finmid/tbl-webapps/platform';\nimport { useInitPostHog } from '@finmid/tbl-webapps/posthog';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { SettingsPage } from '@finmid/tbl-webapps/settings';\nimport { combineProviders } from '@finmid/utils';\nimport { FunctionComponent, useMemo } from 'react';\nimport { Navigate, Route, Routes } from 'react-router-dom';\n\nimport { CapitalDistributorGuard } from '../components/CapitalDistributorGuard';\nimport { useEnabledModules } from '../hooks/useEnabledModules';\nimport { DashboardPage, Debug } from '../pages';\n\nimport { PrivateRoute } from './PrivateRoute';\n\nexport const ModulesRouter: FunctionComponent = () => {\n  const { enabledModules, isLoading } = useEnabledModules();\n\n  const modulesGlobalProviders = enabledModules.flatMap(\n    ({ globalProviders }) => globalProviders ?? [],\n  );\n\n  const Providers = useMemo(\n    () => combineProviders(modulesGlobalProviders),\n    // eslint-disable-next-line react-hooks/exhaustive-deps\n    [modulesGlobalProviders.length],\n  );\n\n  useInitPostHog();\n\n  return (\n    <Providers>\n      <Routes>\n        <Route element={<PrivateRoute component={DashboardPage} />}>\n          <Route path={sharedRoutes.debug} element={<Debug />} />\n\n          <Route\n            path={sharedRoutes.developers}\n            element={<CapitalDistributorGuard />}\n          >\n            <Route index Component={DevelopersPage} />\n            <Route\n              path={sharedRoutes.createApiKeys}\n              Component={CreateApiKeyPage}\n            />\n            <Route\n              path={sharedRoutes.createWebhooks}\n              Component={CreateWebhookPage}\n            />\n          </Route>\n\n          <Route path={sharedRoutes.platform} Component={PlatformPage} />\n          <Route path={sharedRoutes.settings} Component={SettingsPage} />\n\n          {enabledModules.map(({ router, id, name }) => (\n            <Route key={id} element={<ProductSentryTag value={name} />}>\n              {router}\n            </Route>\n          ))}\n        </Route>\n\n        {isLoading ? null : (\n          <Route\n            path=\"*\"\n            element={<Navigate replace to={sharedRoutes.root} />}\n          />\n        )}\n      </Routes>\n    </Providers>\n  );\n};\n","import {\n  AuthenticationRoutesLayout,\n  PrivateRoute,\n} from '@distributor-webapp/routes';\nimport { SentryRouteErrorFallback } from '@finmid/tbl-webapps/components';\nimport { sharedRoutes } from '@finmid/tbl-webapps/routes';\nimport { initializeTranslations } from '@finmid/tbl-webapps/translations';\nimport { initializeFeatures } from '@finmid/tbl-webapps/utils';\nimport { wrapCreateBrowserRouterV7 as wrapCreateBrowserRouter } from '@sentry/react';\nimport { FunctionComponent } from 'react';\nimport {\n  Route,\n  RouterProvider,\n  createBrowserRouter,\n  createRoutesFromElements,\n} from 'react-router-dom';\n\nimport { LoginPage, LoginVerification, LogoutPage } from './pages';\nimport { ModulesRouter } from './routes/ModulesRouter';\n\ninitializeFeatures();\nvoid initializeTranslations();\n\nconst keycloakRoutes = [\n  { path: sharedRoutes.login, element: <LoginPage /> },\n  { path: sharedRoutes.loginVerification, element: <LoginVerification /> },\n  { path: sharedRoutes.logout, element: <LogoutPage /> },\n];\n\nconst sentryCreateBrowserRouter = wrapCreateBrowserRouter(createBrowserRouter);\n\nconst router = sentryCreateBrowserRouter([\n  {\n    errorElement: <SentryRouteErrorFallback />,\n    children: createRoutesFromElements(\n      <>\n        <Route element={<AuthenticationRoutesLayout />}>\n          {keycloakRoutes.map((route) => (\n            <Route {...route} key={route.path} />\n          ))}\n          <Route path=\"*\" element={<PrivateRoute />}>\n            <Route path=\"*\" element={<ModulesRouter />} />\n          </Route>\n        </Route>\n      </>,\n    ),\n  },\n]);\n\nexport const App: FunctionComponent = () => {\n  return <RouterProvider router={router} />;\n};\n","/* eslint-disable import/first */\n/* eslint-disable import-x/order */\nimport { initializeSentry } from '@finmid/sentry/webapp';\n\nimport './index.css';\nimport { options } from './utils/sentry';\ninitializeSentry(options);\n\nimport { store } from '@finmid/tbl-webapps/store';\nimport { ThemeProvider } from '@finmid/tbl-webapps/theme';\nimport { SnackbarProvider } from 'notistack';\nimport { createRoot } from 'react-dom/client';\nimport { Provider as ReduxProvider } from 'react-redux';\n\nimport { App } from './App';\nimport {\n  ConsentContextProvider,\n  PostHogProvider,\n} from '@finmid/tbl-webapps/posthog';\n\n// eslint-disable-next-line @typescript-eslint/no-non-null-assertion\nconst container = document.getElementById('root')!;\n\nconst root = createRoot(container);\n\nroot.render(\n  <ReduxProvider store={store}>\n    <ThemeProvider>\n      <SnackbarProvider maxSnack={3}>\n        <ConsentContextProvider>\n          <PostHogProvider>\n            <App />\n          </PostHogProvider>\n        </ConsentContextProvider>\n      </SnackbarProvider>\n    </ThemeProvider>\n  </ReduxProvider>,\n);\n"],"file":"index-C1IItZL0.js"}
